(typeof window !== "undefined" ? window : globalThis).CLASSICAL_LITERATURE_DATA = [{"title": "精衛填海", "author": "《山海經》", "period": "先秦", "form": "文", "theme": "江河湖海", "mood": "vast_river", "lines": ["又北二百里，曰發鳩之山，其上多柘木。有鳥焉，其狀如烏，文首、白喙、赤足，名曰精衛，其鳴自詨。是炎帝之少女，名曰女娃，女娃遊于東海，溺而不返，故為精衛，常銜西山之木石，以堙于東海。漳水出焉，東流注于河。"], "quote": ["又北二百里，曰發鳩之山，其上多柘木。有鳥焉，其狀如烏，文首、白喙、赤足，名曰精衛，其鳴自詨。是炎帝之少女，名曰女娃，女娃遊于東海，溺而不返，故為精衛，常銜西山之木石，以堙于東海。漳水出焉，東流注于河。"], "intro": "《精衛填海》選自《山海經‧北山經》，本無題目，現題為編者所加。版本據《先秦兩漢古籍逐字索引》。 精衛，鳥名，又名誓鳥、冤禽、志鳥，俗稱帝女雀。本篇說炎帝之女在東海被淹死，靈魂化為精衛，常銜西山之木石以填東海。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%B2%BE%E8%A1%9B%E5%A1%AB%E6%B5%B7"}, {"title": "在上位不陵下", "author": "《中庸》", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["在上位，不陵下；在下位，不援上，正己而不求於人，則無怨；上不怨天，下不尤人，故君子居易以俟命，小人行險以徼幸。子曰︰「射有似乎君子，失諸正鵠，反求諸其身。」"], "quote": ["在上位，不陵下；在下位，不援上，正己而不求於人，則無怨；上不怨天，下不尤人，故君子居易以俟命，小人行險以徼幸。子曰︰「射有似乎君子，失諸正鵠，反求諸其身。」"], "intro": "這裏所節選的，是《中庸》第十四章中的一部分。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%9C%A8%E4%B8%8A%E4%BD%8D%E4%B8%8D%E9%99%B5%E4%B8%8B"}, {"title": "接輿歌", "author": "古歌謠", "period": "先秦", "form": "詩", "theme": "詠史哲思", "mood": "heroic", "lines": ["鳳兮鳳兮，何如德之衰也！", "來世不可待，往世不可追也。", "天下有道，聖人成焉；", "天下無道，聖人生焉。", "方今之時，僅免刑焉。", "福輕乎羽，莫之知載；", "禍重乎地，莫之知避。", "已乎已乎，臨人以德！", "殆乎殆乎，畫地而趨！", "迷陽迷陽，無傷吾行！", "吾行郤曲，無傷吾足。"], "quote": ["鳳兮鳳兮，何如德之衰也！", "來世不可待，往世不可追也。", "天下有道，聖人成焉；", "天下無道，聖人生焉。"], "intro": "楚狂接輿作歌之事見《莊子・人間世》及《論語・微子》篇。《論語》所載較簡：「楚狂接輿歌而過孔子，曰：『鳳兮鳳兮，何德之衰？往者不可諫，來者猶可追。已而已而，今之從政者殆而！』孔子下，欲與之言。趨而辟之，不得與之言。」接輿，楚隱士也，因行止傲放", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%8E%A5%E8%BC%BF%E6%AD%8C"}, {"title": "越人歌", "author": "古歌謠", "period": "先秦", "form": "詩", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["今夕何夕兮搴中洲流，", "今日何日兮得與王子同舟。", "蒙羞被好兮不訾詬恥，", "心幾煩而不絕兮得知王子。", "山有木兮木有枝，", "心說君兮君不知。"], "quote": ["今夕何夕兮搴中洲流，", "今日何日兮得與王子同舟。", "蒙羞被好兮不訾詬恥，", "心幾煩而不絕兮得知王子。"], "intro": "《越人歌》是中國歷史上記載的最早的一首翻譯歌。它出現在先秦時的楚國；當時的令尹鄂君子晳有一天「泛舟於新波之中」，聽到划船的越人唱起了這首歌，由於歌詞是越語，鄂君子晳聽不懂，還找了當地人來翻譯成楚語，就是今所載之《越人歌》。本篇所用版本出自《", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B6%8A%E4%BA%BA%E6%AD%8C"}, {"title": "擊壤歌", "author": "古歌謠", "period": "先秦", "form": "詩", "theme": "田園幽居", "mood": "ethereal", "lines": ["日出而作，日入而息，", "鑿井而飲，耕田而食，", "帝力于我何有哉。"], "quote": ["日出而作，日入而息，", "鑿井而飲，耕田而食，", "帝力于我何有哉。"], "intro": "宋・王應麟：《困學記聞》引周處《風土紀》云：「壤，以木為之，前廣後銳，長尺三寸，其形如履。先置一壤於地，遙於三四十步，以手中壤擊之，中者為上。」擊壤歌，言野老擊壤而戲時所作歌也。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%93%8A%E5%A3%A4%E6%AD%8C"}, {"title": "不貪為寶", "author": "《左傳》", "period": "先秦", "form": "文", "theme": "田園幽居", "mood": "ethereal", "lines": ["宋人或得玉，獻諸子罕。子罕弗受。獻玉者曰︰「以示玉人，玉人以為寶也，故敢獻之。」子罕曰︰「我以不貪為寶，爾以玉為寶，若以與我，皆喪寶也。不若人有其寶。」"], "quote": ["宋人或得玉，獻諸子罕。子罕弗受。獻玉者曰︰「以示玉人，玉人以為寶也，故敢獻之。」子罕曰︰「我以不貪為寶，爾以玉為寶，若以與我，皆喪寶也。不若人有其寶。」"], "intro": "本文選自《左傳‧襄公十五年》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B8%8D%E8%B2%AA%E7%82%BA%E5%AF%B6"}, {"title": "曹劌論戰", "author": "《左傳》", "period": "先秦", "form": "文", "theme": "山水登臨", "mood": "autumn_sunset", "lines": ["春，齊師伐我，公將戰。曹劌請見。其鄉人曰︰「肉食者謀之，又何間焉？」劌曰︰「肉食者鄙，未能遠謀。」乃入見，問︰「何以戰？」公曰︰「衣食所安，弗敢專也，必以分人。」對曰︰「小惠未徧，民弗從也。」", "公曰︰「犧牲玉帛，弗敢加也，必以信。」對曰︰「小信未孚，神弗福也」。公曰︰「小大之獄，雖不能察，必以情。」對曰︰「忠之屬也，可以一戰。」戰，則請從。公與之乘。", "戰於長勺。公將鼓之，劌曰︰「未可。」齊人三鼓。劌曰︰「可矣。」齊師敗績。公將馳之，劌曰︰「未可。」下視其轍，登軾而望之，曰︰「可矣。」遂逐齊師。", "既克，公問其故。對曰︰「夫戰，勇氣也。一鼓作氣，再而衰，三而竭。彼竭我盈，故克之。夫大國，難測也，懼有伏焉。吾視其轍亂，望其旗靡，故逐之。」"], "quote": ["春，齊師伐我，公將戰。曹劌請見。其鄉人曰︰「肉食者謀之，又何間焉？」劌曰︰「肉食者鄙，未能遠謀。」乃入見，問︰「何以戰？」公曰︰「衣食所安，弗敢專也，必以分人。」對曰︰「小惠未徧，民弗從也。」", "公曰︰「犧牲玉帛，弗敢加也，必以信。」對曰︰「小信未孚，神弗福也」。公曰︰「小大之獄，雖不能察，必以情。」對曰︰「忠之屬也，可以一戰。」戰，則請從。公與之乘。", "戰於長勺。公將鼓之，劌曰︰「未可。」齊人三鼓。劌曰︰「可矣。」齊師敗績。公將馳之，劌曰︰「未可。」下視其轍，登軾而望之，曰︰「可矣。」遂逐齊師。", "既克，公問其故。對曰︰「夫戰，勇氣也。一鼓作氣，再而衰，三而竭。彼竭我盈，故克之。夫大國，難測也，懼有伏焉。吾視其轍亂，望其旗靡，故逐之。」"], "intro": "本篇選自《左傳‧莊公十年》，記載春秋時代魯國和齊國長勺之戰前後的事，題目為後人所加。 春秋時代魯國與齊國為鄰，都在今天的山東省，本互為友好，歷代通婚。公元前六八六年，因齊國國君齊襄公無道，其弟公子小白和公子糾分別逃到莒國和魯國避禍。該年底，", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9B%B9%E5%8A%8C%E8%AB%96%E6%88%B0"}, {"title": "鄭伯克段于鄢", "author": "《左傳》", "period": "先秦", "form": "文", "theme": "田園幽居", "mood": "autumn_sunset", "lines": ["初，鄭武公娶于申，曰武姜，生莊公及共叔段。莊公寤生，驚姜氏，故名曰寤生，遂惡之。愛共叔段，欲立之。亟請於武公，公弗許。及莊公即位，為之請制。", "公曰︰「制，巖邑也，虢叔死焉。佗邑唯命。」請京，使居之，謂之京城大叔。祭仲曰︰「都，城過百雉，國之害也。先王之制︰大都，不過參國之一；中，五之一；小，九之一。今京不度，非制也，君將不堪。」", "公曰︰「姜氏欲之，焉辟害？」對曰︰「姜氏何厭之有？不如早為之所，無使滋蔓！蔓，難圖也。蔓草猶不可除，況君之寵弟乎？」公曰︰「多行不義必自斃，子姑待之。」", "既而大叔命西鄙、北鄙貳於己。公子呂曰︰「國不堪貳，君將若之何？欲與大叔，臣請事之；若弗與，則請除之。無生民心。」公曰︰「無庸，將自及。」", "大叔又收貳以為己邑，至於廩延。子封曰︰「可矣。厚將得眾。」公曰︰「不義，不暱，厚將崩。」", "大叔完、聚，繕甲、兵，具卒、乘，將襲鄭。夫人將啟之。公聞其期，曰︰「可矣。」命子封帥車二百乘以伐京。京叛大叔段，段入于鄢。公伐諸鄢。五月辛丑，大叔出奔共。", "書曰︰「鄭伯克段于鄢。」段不弟，故不言弟；如二君，故曰克；稱鄭伯，譏失教也；謂之鄭志。不言出奔，難之也。", "遂寘姜氏於城潁，而誓之曰︰「不及黃泉，無相見也！」既而悔之。", "潁考叔為潁谷封人，聞之，有獻於公。公賜之食，食舍肉。公問之，對曰︰「小人有母，皆嘗小人之食矣；未嘗君之羹，請以遺之。」公曰︰「爾有母遺，繄我獨無！」", "潁考叔曰︰「敢問何謂也？」公語之故，且告之悔。對曰︰「君何患焉？若闕地及泉，隧而相見，其誰曰不然？」公從之。公入而賦︰「大隧之中，其樂也融融。」", "姜出而賦︰「大隧之外，其樂也洩洩。」遂為母子如初。君子曰︰「潁考叔，純孝也，愛其母，施及莊公。《詩》曰︰『孝子不匱，永錫爾類』，其是之謂乎！」"], "quote": ["初，鄭武公娶于申，曰武姜，生莊公及共叔段。莊公寤生，驚姜氏，故名曰寤生，遂惡之。愛共叔段，欲立之。亟請於武公，公弗許。及莊公即位，為之請制。", "公曰︰「制，巖邑也，虢叔死焉。佗邑唯命。」請京，使居之，謂之京城大叔。祭仲曰︰「都，城過百雉，國之害也。先王之制︰大都，不過參國之一；中，五之一；小，九之一。今京不度，非制也，君將不堪。」", "公曰︰「姜氏欲之，焉辟害？」對曰︰「姜氏何厭之有？不如早為之所，無使滋蔓！蔓，難圖也。蔓草猶不可除，況君之寵弟乎？」公曰︰「多行不義必自斃，子姑待之。」", "既而大叔命西鄙、北鄙貳於己。公子呂曰︰「國不堪貳，君將若之何？欲與大叔，臣請事之；若弗與，則請除之。無生民心。」公曰︰「無庸，將自及。」"], "intro": "《鄭伯克段于鄢》選自《左傳‧隱公元年》，版本據《先秦兩漢古籍逐字索引》，題目為後人所加。鄭，春秋時姬姓國名，初都棫林（今陝西華縣西北），鄭武公（莊公父）時始遷新鄭（今河南新鄭）。鄭伯，指鄭莊公。伯，爵位名稱，春秋時有五等爵：公、侯、伯、子、", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%84%AD%E4%BC%AF%E5%85%8B%E6%AE%B5%E4%BA%8E%E9%84%A2"}, {"title": "燭之武退秦師", "author": "《左傳》", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["晉侯、秦伯圍鄭，以其無禮於晉，且貳於楚也。晉軍函陵，秦軍汜南。", "佚之狐言於鄭伯曰︰「國危矣！若使燭之武見秦君，師必退。」", "公從之。辭曰︰「臣之壯也，猶不如人；今老矣，無能為也已。」公曰︰「吾不能早用子，今急而求子，是寡人之過也。然鄭亡，子亦有不利焉。」許之。夜縋而出。", "見秦伯曰︰「秦、晉圍鄭，鄭既知亡矣。若亡鄭而有益於君，敢以煩執事。越國以鄙遠，君知其難也，焉用亡鄭以陪鄰？鄰之厚，君之薄也。若舍鄭以為東道主，行李之往來，共其乏困，君亦無所害。", "且君嘗為晉君賜矣，許君焦、瑕，朝濟而夕設版焉，君之所知也。夫晉，何厭之有？既東封鄭，又欲肆其西封。若不闕秦，將焉取之？闕秦以利晉，唯君圖之！」", "秦伯說，與鄭人盟，使杞子、逢孫、楊孫戍之，乃還。", "子犯請擊之。公曰︰「不可！微夫人之力不及此。因人之力而敝之，不仁；失其所與，不知；以亂易整，不武。吾其還也。」亦去之。"], "quote": ["晉侯、秦伯圍鄭，以其無禮於晉，且貳於楚也。晉軍函陵，秦軍汜南。", "佚之狐言於鄭伯曰︰「國危矣！若使燭之武見秦君，師必退。」", "公從之。辭曰︰「臣之壯也，猶不如人；今老矣，無能為也已。」公曰︰「吾不能早用子，今急而求子，是寡人之過也。然鄭亡，子亦有不利焉。」許之。夜縋而出。", "見秦伯曰︰「秦、晉圍鄭，鄭既知亡矣。若亡鄭而有益於君，敢以煩執事。越國以鄙遠，君知其難也，焉用亡鄭以陪鄰？鄰之厚，君之薄也。若舍鄭以為東道主，行李之往來，共其乏困，君亦無所害。"], "intro": "本篇選自《左傳‧僖公三十年》，是魯僖公三十年九月裏發生的事。魯僖公三十年，即周襄王二十二年，亦即公元前六三零年。燭之武，人名，鄭國的大夫。那時晉國約同秦國連兵攻打鄭國，已經包圍了鄭國的京城，情勢相當危急。鄭國派燭之武到秦營，說服秦君退兵，晉", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%87%AD%E4%B9%8B%E6%AD%A6%E9%80%80%E7%A7%A6%E5%B8%AB"}, {"title": "高山流水", "author": "《列子》", "period": "先秦", "form": "文", "theme": "山水登臨", "mood": "vast_river", "lines": ["伯牙善鼓琴，鍾子期善聽。伯牙鼓琴，志在登高山，鍾子期曰︰「善哉，峨峨兮若泰山！」志在流水，鍾子期曰︰「善哉，洋洋兮若江河！」伯牙所念，鍾子期必得之。", "伯牙游於泰山之陰，卒逢暴雨，止於巖下，心悲，乃援琴而鼓之。初為《霖雨》之操，更造《崩山》之音。曲每奏，鍾子期輒窮其趣。伯牙乃舍琴而嘆曰︰「善哉，善哉，子之聽夫志，想象猶吾心也。吾於何逃聲哉？」"], "quote": ["伯牙善鼓琴，鍾子期善聽。伯牙鼓琴，志在登高山，鍾子期曰︰「善哉，峨峨兮若泰山！」志在流水，鍾子期曰︰「善哉，洋洋兮若江河！」伯牙所念，鍾子期必得之。", "伯牙游於泰山之陰，卒逢暴雨，止於巖下，心悲，乃援琴而鼓之。初為《霖雨》之操，更造《崩山》之音。曲每奏，鍾子期輒窮其趣。伯牙乃舍琴而嘆曰︰「善哉，善哉，子之聽夫志，想象猶吾心也。吾於何逃聲哉？」"], "intro": "本文選自《列子‧湯問篇》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%AB%98%E5%B1%B1%E6%B5%81%E6%B0%B4"}, {"title": "愚公移山", "author": "《列子》", "period": "先秦", "form": "文", "theme": "山水登臨", "mood": "snow_winter", "lines": ["太形、王屋二山，方七百里，高萬仞；本在冀州之南，河陽之北。北山愚公者，年且九十，面山而居。懲山北之塞，出入之迂也，聚室而謀曰︰「吾與汝畢力平險，指通豫南，達於漢陰，可乎？」雜然相許。", "其妻獻疑曰︰「以君之力，曾不能損魁父之丘，如太形王屋何！且焉置土石？」雜曰︰「投諸渤海之尾，隱土之北。」遂率子孫，荷擔者三夫，叩石墾壤，箕畚運於渤海之尾。", "鄰人京城氏之孀妻，有遺男，始齔，跳往助之；寒暑易節，始一反焉。", "河曲智叟笑而止之曰︰「甚矣，汝之不惠！以殘年餘力，曾不能毀山之一毛，其如土石何。」北山愚公長息曰︰「汝心之固，固不可徹；曾不若孀妻弱子。", "雖我之死，有子存焉；子又生孫，孫又生子，子又有子，孫又有孫，子子孫孫，無窮匱也，而山不加增；何苦而不平？」河曲智叟無以應。", "操蛇之神回聞之，懼其不已也，告之於帝。帝感其誠，命夸蛾氏二子負二山，一厝朔東，一厝雍南。自此冀之南，漢之陰，無隴斷焉。"], "quote": ["太形、王屋二山，方七百里，高萬仞；本在冀州之南，河陽之北。北山愚公者，年且九十，面山而居。懲山北之塞，出入之迂也，聚室而謀曰︰「吾與汝畢力平險，指通豫南，達於漢陰，可乎？」雜然相許。", "其妻獻疑曰︰「以君之力，曾不能損魁父之丘，如太形王屋何！且焉置土石？」雜曰︰「投諸渤海之尾，隱土之北。」遂率子孫，荷擔者三夫，叩石墾壤，箕畚運於渤海之尾。", "鄰人京城氏之孀妻，有遺男，始齔，跳往助之；寒暑易節，始一反焉。", "河曲智叟笑而止之曰︰「甚矣，汝之不惠！以殘年餘力，曾不能毀山之一毛，其如土石何。」北山愚公長息曰︰「汝心之固，固不可徹；曾不若孀妻弱子。"], "intro": "本篇乃節錄《列子・湯問篇》。愚公，是作者假託的一個人，等於說「傻老頭」；移山，就是使山遷移。這是一篇寓言故事。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%84%9A%E5%85%AC%E7%A7%BB%E5%B1%B1"}, {"title": "楊布打狗", "author": "《列子》", "period": "先秦", "form": "文", "theme": "田園幽居", "mood": "ethereal", "lines": ["楊朱之弟曰布。衣素衣而出，天雨解素衣，衣緇衣而反。其狗不知，迎而吠之。楊布怒，將撲之。", "楊朱曰︰「子無撲矣，子亦猶是也。嚮者使汝狗白而往，黑而來，豈能無怪哉？」"], "quote": ["楊朱之弟曰布。衣素衣而出，天雨解素衣，衣緇衣而反。其狗不知，迎而吠之。楊布怒，將撲之。", "楊朱曰︰「子無撲矣，子亦猶是也。嚮者使汝狗白而往，黑而來，豈能無怪哉？」"], "intro": "本文選自《列子‧說符篇》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%A5%8A%E5%B8%83%E6%89%93%E7%8B%97"}, {"title": "老子四章", "author": "老子", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["一", "天下皆知美之為美，斯惡已；皆知善之為善，斯不善已。故有無相生，難易相成，長短相形，高下相傾，音聲相和，前後相隨。是以聖人處無為之事，行不言之教。萬物作焉而不辭，生而不有，為而不恃，功成而弗居；夫唯弗居，是以不去。", "二", "不尚賢，使民不爭；不貴難得之貨，使民不為盜；不見可欲，使民心不亂。是以聖人之治︰虛其心，實其腹；弱其志，強其骨；常使民無知無欲，使夫智者不敢為也。為無為，則無不治。", "三", "三十輻，共一轂；當其無，有車之用；埏埴以為器，當其無，有器之用；鑿戶牖以為室，當其無，有室之用。故有之以為利，無之以為用。", "四", "小國寡民，使有什怕之器而不用，使民重死而不遠徙。雖有舟輿，無所乘之；雖有甲兵，無所陳之；使人復結繩而用之；甘其食，美其服，樂其俗。鄰國相望，雞犬之聲相聞，民至老死不相往來。"], "quote": ["一", "天下皆知美之為美，斯惡已；皆知善之為善，斯不善已。故有無相生，難易相成，長短相形，高下相傾，音聲相和，前後相隨。是以聖人處無為之事，行不言之教。萬物作焉而不辭，生而不有，為而不恃，功成而弗居；夫唯弗居，是以不去。", "二", "不尚賢，使民不爭；不貴難得之貨，使民不為盜；不見可欲，使民心不亂。是以聖人之治︰虛其心，實其腹；弱其志，強其骨；常使民無知無欲，使夫智者不敢為也。為無為，則無不治。"], "intro": "《老子》一書，原本是一種雜記之類的書，沒有甚麼結構組織。今本《老子》，分上下兩篇，共八十一章，決非原本的本來面目。其中有些不當的分斷，以及重複的語句，和無理插入的話，大概不免有後人妄加妄改的地方。今日最通行的刻本，有「世德堂」的《河上公章句", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%80%81%E5%AD%90%E5%9B%9B%E7%AB%A0"}, {"title": "道德經（節錄）", "author": "老子", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["第三十三章", "知人者，智也。自知者，明也。勝人者，有力也。自勝者，強也。知足者，富也。強行者，有志也。不失其所者，久也。死而不亡者，壽也。", "第六十四章", "其安也，易持也。其未兆也，易謀也。其脆也，易破也。其微也，易散也。為之於其未有也，治之於其未亂也。合抱之木，生於毫末，九層之臺起於虆土，百仞之高，始於足下。為之者敗之，執之者失之。", "是以聖人無為也，故無敗也；無執也，故無失也。民之從事也，恒於幾成而敗之。故慎終若始，則無敗事矣。是以聖人欲不欲，而不貴難得之貨；學不學，復眾人之所過；能輔萬物之自然，而弗敢為。", "第八十一章", "信言不美，美言不信。知者不博，博者不知。善者不多，多者不善。聖人無積，既以為人，己愈有；既以予人，己愈多。故天之道，利而不害；人之道，為而弗爭。"], "quote": ["第三十三章", "知人者，智也。自知者，明也。勝人者，有力也。自勝者，強也。知足者，富也。強行者，有志也。不失其所者，久也。死而不亡者，壽也。", "第六十四章", "其安也，易持也。其未兆也，易謀也。其脆也，易破也。其微也，易散也。為之於其未有也，治之於其未亂也。合抱之木，生於毫末，九層之臺起於虆土，百仞之高，始於足下。為之者敗之，執之者失之。"], "intro": "甲、老子學說 老子之道，太古之道也。老子之書，太古之書也。老子為柱下史。國史掌三皇五帝之書，通上古之道，知上古之禮。老子吏隱靜觀，深疾末世之失。疾之甚則思古益篤，思之篤則求之益深。懷德抱道，白首而後著書，其意不返斯世於太古淳樸不止也。故忠質", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%81%93%E5%BE%B7%E7%B6%93%EF%BC%88%E7%AF%80%E9%8C%84%EF%BC%89"}, {"title": "刻舟求劍", "author": "《呂氏春秋》", "period": "先秦", "form": "文", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["楚人有涉江者，其劍自舟中墜於水，遽契其舟曰︰「是吾劍之所從墜也。」舟止，從其所契者入水求之。舟已行矣，而劍不行，求劍若此，不亦惑乎？"], "quote": ["楚人有涉江者，其劍自舟中墜於水，遽契其舟曰︰「是吾劍之所從墜也。」舟止，從其所契者入水求之。舟已行矣，而劍不行，求劍若此，不亦惑乎？"], "intro": "《刻舟求劍》選自《呂氏春秋‧慎大覽‧察今》，本無題目，現題為編者所加。版本據《先秦兩漢古籍逐字索引》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%88%BB%E8%88%9F%E6%B1%82%E5%8A%8D"}, {"title": "風賦", "author": "宋玉", "period": "先秦", "form": "辭賦", "theme": "春水花鳥", "mood": "vast_river", "lines": ["楚襄王游於蘭臺之宮，宋玉、景差侍。有風颯然而至，王迺披襟而當之，曰︰「快哉此風！寡人所與庶人共者邪？」宋玉對曰︰「此獨大王之風耳；庶人安得而共之？」", "王曰︰「夫風者，天地之氣，溥暢而至，不擇貴賤高下而加焉。今子獨以為寡人之風，豈有說乎？」宋玉對曰︰「臣聞於師︰『枳句來巢，空穴來風。』其所託者然，則風氣殊焉。」", "王曰︰「夫風，始安生哉？」宋玉對曰︰「夫風生於地，起於青蘋之末，侵淫谿谷，盛怒於土囊之口，緣泰山之阿，舞於松柏之下。飄忽淜滂，激颺熛怒；耾耾雷聲，迴穴錯迕；蹶石伐木，捎殺林莽。至其將衰也，被麗披離，衝孔動楗；眴煥粲爛，離散轉移。", "故其清涼雄風，則飄舉升降，乘淩高城，入於深宮，邸華葉而振氣；徘徊於桂椒之間，翱翔於激水之上，將擊芙蓉之精，獵蕙草，離秦蘅，概新夷，被荑楊，迴穴衝陵，蕭條眾芳。然後徜徉中庭，北上玉堂，躋於羅帷，經於洞房，迺得為大王之風也。", "故其風中人狀，直憯悽惏慄，清涼增欷；清清泠泠，愈病析酲；發明耳目，寧體便人。此所謂大王之雄風也。」", "王曰︰「善哉論事！夫庶人之風，豈可聞乎？」宋玉對曰︰「夫庶人之風，塕然起於窮巷之間，堀堁揚塵，勃鬱煩寃，衝孔襲門，動沙堁，吹死灰，駭溷濁，揚腐餘，邪薄入甕牖，至於室廬。", "故其風中人狀，直憞溷鬱邑，毆溫致溼，中心慘怛，生病造熱；中脣為胗，得目為䁾；啗齰嗽獲，死生不卒。此所謂庶人之雌風也。」"], "quote": ["楚襄王游於蘭臺之宮，宋玉、景差侍。有風颯然而至，王迺披襟而當之，曰︰「快哉此風！寡人所與庶人共者邪？」宋玉對曰︰「此獨大王之風耳；庶人安得而共之？」", "王曰︰「夫風者，天地之氣，溥暢而至，不擇貴賤高下而加焉。今子獨以為寡人之風，豈有說乎？」宋玉對曰︰「臣聞於師︰『枳句來巢，空穴來風。』其所託者然，則風氣殊焉。」", "王曰︰「夫風，始安生哉？」宋玉對曰︰「夫風生於地，起於青蘋之末，侵淫谿谷，盛怒於土囊之口，緣泰山之阿，舞於松柏之下。飄忽淜滂，激颺熛怒；耾耾雷聲，迴穴錯迕；蹶石伐木，捎殺林莽。至其將衰也，被麗披離，衝孔動楗；眴煥粲爛，離散轉移。", "故其清涼雄風，則飄舉升降，乘淩高城，入於深宮，邸華葉而振氣；徘徊於桂椒之間，翱翔於激水之上，將擊芙蓉之精，獵蕙草，離秦蘅，概新夷，被荑楊，迴穴衝陵，蕭條眾芳。然後徜徉中庭，北上玉堂，躋於羅帷，經於洞房，迺得為大王之風也。"], "intro": "宋玉所作的辭賦，《漢書藝文志詩賦畧》著錄十六篇，但今存已不足此數。後漢王逸《楚辭章句》裏所載宋玉作品只兩篇，即《九辯》與《招魂》；梁蕭統《昭明文選》中載有五篇：《風賦》《高唐賦》《神女賦》《登徒子好色賦》《對楚王問》；《古文苑》載有六篇：《", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%A2%A8%E8%B3%A6"}, {"title": "諫逐客書", "author": "李斯", "period": "先秦", "form": "文", "theme": "送別行旅", "mood": "vast_river", "lines": ["臣聞吏議逐客，竊以為過矣。昔繆公求士，西取由余於戎，東得百里奚於宛，迎蹇叔於宋，來丕豹、公孫支於晉。此五子者，不產於秦而繆公用之，幷國二十，遂霸西戎。", "孝公用商鞅之法，移風易俗，民以殷盛，國以富彊；百姓樂用，諸侯親服；獲楚魏之師，舉地千里，至今治彊。惠王用張儀之計，拔三川之地，西幷巴蜀，北收上郡，南取漢中，包九夷，制鄢郢，東據成皋之險，割膏腴之壤；", "遂散六國之從，使之西面事秦，功施到今。昭王得范睢，廢穰侯，逐華陽，彊公室，杜私門；蠶食諸侯，使秦成帝業。此四君者，皆以客之功。由此觀之，客何負於秦哉？向使四君卻客而不內，疏士而不用，是使國無富利之實，而秦無彊大之名也。", "今陛下致昆山之玉，有隨和之寶，垂明月之珠，服太阿之劍，乘纖離之馬，建翠鳳之旗，樹靈鼉之鼓。此數寶者，秦不生一焉，而陛下說之，何也？", "必秦國之所生然後可，則是夜光之璧不飾朝廷，犀象之器不為玩好，鄭衞之女不充後宮，而駿良駃騠不實外廄，江南金錫不為用，西蜀丹青不為采。", "所以飾後宮、充下陳、娛心意、說耳目者，必出於秦然後可，則是宛珠之簪、傅璣之珥，阿縞之衣、錦繡之飾，不進於前，而隨俗雅化、佳冶窈窕趙女不立於側也。", "夫擊甕叩缻，彈箏搏髀，而歌呼嗚嗚快耳者，真秦之聲也；鄭衞桑間，昭虞武象者，異國之樂也。今棄擊甕叩缻而就鄭衞，退彈箏而取昭虞，若是者何也？快意當前，適觀而已矣。", "今取人則不然！不問可否，不論曲直，非秦者去，為客者逐。然則是所重者在乎色樂珠玉，而所輕者在乎人民也。此非所以跨海內、制諸侯之術也。", "臣聞地廣者粟多，國大者人眾，兵彊則士勇。是以太山不讓土壤，故能成其大；河海不擇細流，故能就其深；王者不卻眾庶，故能明其德。是以地無四方，民無異國，四時充美，鬼神降福︰此五帝三王之所以無敵也。", "今乃棄黔首以資敵國，卻賓客以業諸侯，使天下之士退而不敢西向，裹足不入秦；此所謂藉寇兵而齎盜糧者也。", "夫物不產於秦，可寶者多；士不產於秦，而願忠者眾。今逐客以資敵國，損民以益讎，內自虛而外樹怨於諸侯；求國無危，不可得也。"], "quote": ["臣聞吏議逐客，竊以為過矣。昔繆公求士，西取由余於戎，東得百里奚於宛，迎蹇叔於宋，來丕豹、公孫支於晉。此五子者，不產於秦而繆公用之，幷國二十，遂霸西戎。", "孝公用商鞅之法，移風易俗，民以殷盛，國以富彊；百姓樂用，諸侯親服；獲楚魏之師，舉地千里，至今治彊。惠王用張儀之計，拔三川之地，西幷巴蜀，北收上郡，南取漢中，包九夷，制鄢郢，東據成皋之險，割膏腴之壤；", "遂散六國之從，使之西面事秦，功施到今。昭王得范睢，廢穰侯，逐華陽，彊公室，杜私門；蠶食諸侯，使秦成帝業。此四君者，皆以客之功。由此觀之，客何負於秦哉？向使四君卻客而不內，疏士而不用，是使國無富利之實，而秦無彊大之名也。", "今陛下致昆山之玉，有隨和之寶，垂明月之珠，服太阿之劍，乘纖離之馬，建翠鳳之旗，樹靈鼉之鼓。此數寶者，秦不生一焉，而陛下說之，何也？"], "intro": "戰國時候，盛行着一種養客的風氣。除了那有名的四公子外，秦相呂不韋也養了三千名食客。呂不韋自殺以後，他的食客留在秦國的不少。秦王嬴政（即秦始皇）十年，韓國派了一位名叫鄭國的水工，到秦國裏來做間諜，被秦國發覺了。於是很多秦宗室大臣向秦王進言，恐", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%AB%AB%E9%80%90%E5%AE%A2%E6%9B%B8"}, {"title": "天尊地卑", "author": "《周易》", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["天尊地卑，乾坤定矣。卑高以陳，貴賤位矣。動靜有常，剛柔斷矣。方以類聚，物以羣分，吉凶生矣。在天成象，在地成形，變化見矣。", "是故剛柔相摩，八卦相盪，鼓之以雷霆，潤之以風雨。日月運行，一寒一暑，乾道成男，坤道成女，乾知大始，坤作成物。乾以易知，坤以簡能，易則易知，簡則易從。", "易知則有親，易從則有功，有親則可久，有功則可大。可久則賢人之德可大則賢人之業。易簡而天下之理得矣，天下之理得而成位乎其中矣。"], "quote": ["天尊地卑，乾坤定矣。卑高以陳，貴賤位矣。動靜有常，剛柔斷矣。方以類聚，物以羣分，吉凶生矣。在天成象，在地成形，變化見矣。", "是故剛柔相摩，八卦相盪，鼓之以雷霆，潤之以風雨。日月運行，一寒一暑，乾道成男，坤道成女，乾知大始，坤作成物。乾以易知，坤以簡能，易則易知，簡則易從。", "易知則有親，易從則有功，有親則可久，有功則可大。可久則賢人之德可大則賢人之業。易簡而天下之理得矣，天下之理得而成位乎其中矣。"], "intro": "《天尊地卑》出自《易傳》的《繫辭傳》上篇第一章。《易傳》中的《繫辭傳》上下篇是總論《周易》和占筮之法大義的，又稱為《易大傳》，在各傳中是最受重視。《繫辭傳》主要依據卦爻辭來通論《周易》大義，因而得名。有學者認為《繫辭傳》之編定當在漢初，但其", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%A4%A9%E5%B0%8A%E5%9C%B0%E5%8D%91"}, {"title": "二子學弈", "author": "孟子", "period": "先秦", "form": "文", "theme": "邊塞豪放", "mood": "autumn_sunset", "lines": ["弈秋，通國之善弈者也。使弈秋誨二人弈，其一人專心致志，惟弈秋之為聽。一人雖聽之，一心以為有鴻鵠將至，思援弓繳而射之，雖與之俱學，弗若之矣。為是其智弗若與？曰︰「非然也。」"], "quote": ["弈秋，通國之善弈者也。使弈秋誨二人弈，其一人專心致志，惟弈秋之為聽。一人雖聽之，一心以為有鴻鵠將至，思援弓繳而射之，雖與之俱學，弗若之矣。為是其智弗若與？曰︰「非然也。」"], "intro": "本文選自《孟子‧告子（上）》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%BA%8C%E5%AD%90%E5%AD%B8%E5%BC%88"}, {"title": "生於憂患，死於安樂", "author": "孟子", "period": "先秦", "form": "文", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["孟子曰︰舜發於畎畝之中，傅說舉於版築之間，膠鬲舉於魚鹽之中，管夷吾舉於士，孫叔敖舉於海，百里奚舉於市。故天將降大任於是人也，必先苦其心志，勞其筋骨，餓其體膚，空乏其身，行拂亂其所為；", "所以動心忍性，曾益其所不能。人恆過，然後能改；困於心，衡於慮，而後作；徵於色，發於聲，而後喻。入則無法家拂士，出則無敵國外患者，國恆亡。然後知生於憂患，而死於安樂也。"], "quote": ["孟子曰︰舜發於畎畝之中，傅說舉於版築之間，膠鬲舉於魚鹽之中，管夷吾舉於士，孫叔敖舉於海，百里奚舉於市。故天將降大任於是人也，必先苦其心志，勞其筋骨，餓其體膚，空乏其身，行拂亂其所為；", "所以動心忍性，曾益其所不能。人恆過，然後能改；困於心，衡於慮，而後作；徵於色，發於聲，而後喻。入則無法家拂士，出則無敵國外患者，國恆亡。然後知生於憂患，而死於安樂也。"], "intro": "孟子晚年回鄉講學，和他的弟子從事著書的工作，寫成了《孟子》七篇，孟子的言論和事跡很多都保存在這七篇之中。 本篇出自《孟子．告子下》，只有約一百五十字，其中提出一個孟子具代表性的觀點「生於憂患，死於安樂」，也以此為題。孟子繼承了孔子所提倡的「", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%94%9F%E6%96%BC%E6%86%82%E6%82%A3%EF%BC%8C%E6%AD%BB%E6%96%BC%E5%AE%89%E6%A8%82"}, {"title": "莊暴見孟子章", "author": "孟子", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["莊暴見孟子曰︰「暴見於王，王語暴以好樂，暴未有以對也。」曰︰「好樂何如﹖」孟子曰︰「王之好樂甚，則齊國其庶幾乎﹖」", "他日，見於王曰︰「王嘗語莊子以好樂，有諸﹖」王變乎色曰︰「寡人非能好先王之樂也，直好世俗之樂耳。」曰︰「王之好樂甚，則齊其庶幾乎！今之樂，由古之樂也。」曰︰「可得聞與﹖」曰︰「獨樂樂，與人樂樂，孰樂﹖」曰︰「不若與人。」曰︰「與少樂樂，與眾樂樂，孰樂﹖」曰︰「不若與眾。」", "「臣請為王言樂︰今王鼓樂於此，百姓聞王鐘鼓之聲、管籥之音，舉疾首蹙頞而相告，曰︰『吾王之好鼓樂，夫何使我至於此極也﹖父子不相見，兄弟妻子離散。』今王田獵於此，百姓聞王車馬之音，見羽旄之美，舉疾首蹙頞而相告曰︰『吾王之好田獵，夫何使我至於此極也﹖父子不相見，兄弟妻子離散。』此無他，不與民同樂也。", "今王鼓樂於此，百姓聞王鐘鼓之聲、管籥之音，舉欣欣然有喜色而相告曰︰『吾王庶幾無疾病與﹖何以能鼓樂也﹖』今王田獵於此，百姓聞王車馬之音，見羽旄之美，舉欣欣然有喜色而相告曰︰『吾王庶幾無疾病與﹖何以能田獵也﹖』此無他，與民同樂也。今王與百姓同樂，則王矣。」"], "quote": ["莊暴見孟子曰︰「暴見於王，王語暴以好樂，暴未有以對也。」曰︰「好樂何如﹖」孟子曰︰「王之好樂甚，則齊國其庶幾乎﹖」", "他日，見於王曰︰「王嘗語莊子以好樂，有諸﹖」王變乎色曰︰「寡人非能好先王之樂也，直好世俗之樂耳。」曰︰「王之好樂甚，則齊其庶幾乎！今之樂，由古之樂也。」曰︰「可得聞與﹖」曰︰「獨樂樂，與人樂樂，孰樂﹖」曰︰「不若與人。」曰︰「與少樂樂，與眾樂樂，孰樂﹖」曰︰「不若與眾。」", "「臣請為王言樂︰今王鼓樂於此，百姓聞王鐘鼓之聲、管籥之音，舉疾首蹙頞而相告，曰︰『吾王之好鼓樂，夫何使我至於此極也﹖父子不相見，兄弟妻子離散。』今王田獵於此，百姓聞王車馬之音，見羽旄之美，舉疾首蹙頞而相告曰︰『吾王之好田獵，夫何使我至於此極也﹖父子不相見，兄弟妻子離散。』此無他，不與民同樂也。", "今王鼓樂於此，百姓聞王鐘鼓之聲、管籥之音，舉欣欣然有喜色而相告曰︰『吾王庶幾無疾病與﹖何以能鼓樂也﹖』今王田獵於此，百姓聞王車馬之音，見羽旄之美，舉欣欣然有喜色而相告曰︰『吾王庶幾無疾病與﹖何以能田獵也﹖』此無他，與民同樂也。今王與百姓同樂，則王矣。」"], "intro": "《孟子》一書共有七篇十四卷。本篇選自其中的《梁惠王章句下》，題目為後人所起。 孟子是孔子之後的儒家思想主要發揚者，除着重自身的修養，更希望在政治上推行儒家的主張，使天下大治。孟子曾周遊列國去宣揚「仁政」、「王道」，是他學說中的核心思想。他到", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%8E%8A%E6%9A%B4%E8%A6%8B%E5%AD%9F%E5%AD%90%E7%AB%A0"}, {"title": "魚我所欲也", "author": "孟子", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["孟子曰︰「魚，我所欲也，熊掌，亦我所欲也；二者不可得兼，舍魚而取熊掌者也。生亦我所欲也，義亦我所欲也；二者不可得兼，舍生而取義者也。生亦我所欲，所欲有甚於生者，故不為苟得也；死亦我所惡，所惡有甚於死者，故患有所不辟也。", "如使人之所欲莫甚於生，則凡可以得生者，何不用也？使人之所惡莫甚於死者，則凡可以辟患者，何不為也？由是則生而有不用也，由是則可以辟患而有不為也，是故所欲有甚於生者，所惡有甚於死者。非獨賢者有是心也，人皆有之，賢者能勿喪耳。", "一簞食，一豆羹，得之則生，弗得則死。嘑爾而與之，行道之人弗受；蹴爾而與之，乞人不屑也；萬鍾則不辯禮義而受之。萬鍾於我何加焉？", "為宮室之美、妻妾之奉、所識窮乏者得我與？鄉為身死而不受，今為宮室之美為之；鄉為身死而不受，今為妻妾之奉為之；鄉為身死而不受，今為所識窮乏者得我而為之，是亦不可以已乎？此之謂失其本心。」"], "quote": ["孟子曰︰「魚，我所欲也，熊掌，亦我所欲也；二者不可得兼，舍魚而取熊掌者也。生亦我所欲也，義亦我所欲也；二者不可得兼，舍生而取義者也。生亦我所欲，所欲有甚於生者，故不為苟得也；死亦我所惡，所惡有甚於死者，故患有所不辟也。", "如使人之所欲莫甚於生，則凡可以得生者，何不用也？使人之所惡莫甚於死者，則凡可以辟患者，何不為也？由是則生而有不用也，由是則可以辟患而有不為也，是故所欲有甚於生者，所惡有甚於死者。非獨賢者有是心也，人皆有之，賢者能勿喪耳。", "一簞食，一豆羹，得之則生，弗得則死。嘑爾而與之，行道之人弗受；蹴爾而與之，乞人不屑也；萬鍾則不辯禮義而受之。萬鍾於我何加焉？", "為宮室之美、妻妾之奉、所識窮乏者得我與？鄉為身死而不受，今為宮室之美為之；鄉為身死而不受，今為妻妾之奉為之；鄉為身死而不受，今為所識窮乏者得我而為之，是亦不可以已乎？此之謂失其本心。」"], "intro": "本篇節選自《孟子・告子上》。《告子上》的主要內容是闡明「性善說」，指出「人性之向善也，猶水之就下也。」又謂「惻隱之心，人皆有之；羞惡之心，人皆有之；恭敬之心，人皆有之；是非之心，人皆有之」。這種向善的天性，就是本篇反覆論證的「本心」。正如朱", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%AD%9A%E6%88%91%E6%89%80%E6%AC%B2%E4%B9%9F"}, {"title": "揠苗助長", "author": "孟子", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["宋人有閔其苗之不長而揠之者，芒芒然歸，謂其人曰︰「今日病矣！予助苗長矣！」其子趨而往視之，苗則槁矣。"], "quote": ["宋人有閔其苗之不長而揠之者，芒芒然歸，謂其人曰︰「今日病矣！予助苗長矣！」其子趨而往視之，苗則槁矣。"], "intro": "《揠苗助長》選自《孟子‧公孫丑上》，本無題目，現題為編者所加。版本據《先秦兩漢古籍逐字索引》。 孟子本意在闡明培養浩然之氣，不要圖速而違反自然本性的道理。今多以此告誡人們做事必須按部就班，不能主觀急進。本篇文字簡潔生動，短短四十一字，已將事", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%8F%A0%E8%8B%97%E5%8A%A9%E9%95%B7"}, {"title": "齊人有一妻一妾章", "author": "孟子", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "majestic_peaks", "lines": ["齊人有一妻一妾而處室者。其良人出，則必饜酒肉而後反。其妻問所與飲食者，則盡富貴也。其妻告其妾曰︰「良人出，則必饜酒肉而後反；問其與飲食者，盡富貴也，而未嘗有顯者來。吾將瞯良人之所之也！」", "蚤起，施從良人之所之，徧國中無與立談者。卒之東郭墦間，之祭者乞其餘；不足，又顧而之他，此其為饜足之道也。", "其妻歸告其妾曰︰「良人者，所仰望而終身也，今若此！」與其妾訕其良人，而相泣於中庭。而良人未之知也，施施從外來，驕其妻妾。", "由君子觀之，則人之所以求富貴利達者，其妻妾不羞也，而不相泣者，幾希矣！"], "quote": ["齊人有一妻一妾而處室者。其良人出，則必饜酒肉而後反。其妻問所與飲食者，則盡富貴也。其妻告其妾曰︰「良人出，則必饜酒肉而後反；問其與飲食者，盡富貴也，而未嘗有顯者來。吾將瞯良人之所之也！」", "蚤起，施從良人之所之，徧國中無與立談者。卒之東郭墦間，之祭者乞其餘；不足，又顧而之他，此其為饜足之道也。", "其妻歸告其妾曰︰「良人者，所仰望而終身也，今若此！」與其妾訕其良人，而相泣於中庭。而良人未之知也，施施從外來，驕其妻妾。", "由君子觀之，則人之所以求富貴利達者，其妻妾不羞也，而不相泣者，幾希矣！"], "intro": "本篇選自《孟子・離婁下》，即用首句作為標題。齊人，即齊國的人；齊國是戰國時代七大強國之一，據有今山東省的東都，後亡於秦。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%BD%8A%E4%BA%BA%E6%9C%89%E4%B8%80%E5%A6%BB%E4%B8%80%E5%A6%BE%E7%AB%A0"}, {"title": "齊桓晉文之事章", "author": "孟子", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["齊宣王問曰︰「齊桓、晉文之事，可得聞乎？」", "孟子對曰︰「仲尼之徒，無道桓、文之事者，是以後世無傳焉，臣未之聞也；無以，則王乎？」", "曰︰「德何如，則可以王矣？」", "曰︰「保民而王，莫之能禦也。」", "曰︰「若寡人者，可以保民乎哉？」", "曰︰「可。」", "曰︰「何由知吾可也？」", "曰︰「臣聞之胡齕曰︰王坐於堂上，有牽牛而過堂下者，王見之，曰︰『牛何之？』對曰︰『將以釁鐘。』王曰︰『舍之。吾不忍其觳觫，若無罪而就死地。』對曰︰『然則廢釁鐘與？』曰︰『何可廢也？以羊易之。』不識有諸？」", "曰︰「有之。」", "曰︰「是心足以王矣。百姓皆以王為愛也，臣固知王之不忍也。」", "王曰︰「然；誠有百姓者。齊國雖褊小，吾何愛一牛，即不忍其觳觫，若無罪而就死地，故以羊易之也。」", "曰︰「王無異於百姓之以王為愛也。以小易大，彼惡知之？王若隱其無罪而就死地，則牛羊何擇焉？」"], "quote": ["齊宣王問曰︰「齊桓、晉文之事，可得聞乎？」", "孟子對曰︰「仲尼之徒，無道桓、文之事者，是以後世無傳焉，臣未之聞也；無以，則王乎？」", "曰︰「德何如，則可以王矣？」", "曰︰「保民而王，莫之能禦也。」"], "intro": "本篇選自《孟子・梁惠王篇》；以內容乃孟子和齊宣王的問答，故特標今題。對，即對答的意思。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%BD%8A%E6%A1%93%E6%99%89%E6%96%87%E4%B9%8B%E4%BA%8B%E7%AB%A0"}, {"title": "論四端", "author": "孟子", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["孟子曰︰「人皆有不忍人之心。先王有不忍人之心，斯有不忍人之政矣。以不忍人之心，行不忍人之政，治天下可運之掌上。所以謂人皆有不忍人之心者，今人乍見孺子將入於井，皆有怵惕惻隱之心，非所以內交於孺子之父母也，非所以要譽於鄉黨朋友也，非惡其聲而然也。", "由是觀之，無惻隱之心，非人也；無羞惡之心，非人也；無辭讓之心，非人也；無是非之心，非人也。惻隱之心，仁之端也；羞惡之心，義之端也；辭讓之心，禮之端也；是非之心，智之端也。人之有是四端也，猶其有四體也。", "有是四端而自謂不能者，自賊者也；謂其君不能者，賊其君者也。凡有四端於我者，知皆擴而充之矣，若火之始然，泉之始達。苟能充之，足以保四海；苟不充之，不足以事父母。」"], "quote": ["孟子曰︰「人皆有不忍人之心。先王有不忍人之心，斯有不忍人之政矣。以不忍人之心，行不忍人之政，治天下可運之掌上。所以謂人皆有不忍人之心者，今人乍見孺子將入於井，皆有怵惕惻隱之心，非所以內交於孺子之父母也，非所以要譽於鄉黨朋友也，非惡其聲而然也。", "由是觀之，無惻隱之心，非人也；無羞惡之心，非人也；無辭讓之心，非人也；無是非之心，非人也。惻隱之心，仁之端也；羞惡之心，義之端也；辭讓之心，禮之端也；是非之心，智之端也。人之有是四端也，猶其有四體也。", "有是四端而自謂不能者，自賊者也；謂其君不能者，賊其君者也。凡有四端於我者，知皆擴而充之矣，若火之始然，泉之始達。苟能充之，足以保四海；苟不充之，不足以事父母。」"], "intro": "本篇選自《孟子‧公孫丑上》第六章，版本據《先秦兩漢古籍逐字索引》，現題為編者所加。 《論四端》中的四端，指惻隱、羞惡、辭讓、是非四種人類向善的本能。孟子以此四端作為「性善說」的基礎。由此發展，可體現仁、義、禮、智四種德性。儒家所謂「仁政」，", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%AB%96%E5%9B%9B%E7%AB%AF"}, {"title": "周書・秦誓", "author": "《尚書》", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "majestic_peaks", "lines": ["公曰︰「嗟！我士，聽無嘩！予誓告汝羣言之首。古人有言曰︰『民訖自若，是多盤。』責人斯無難，惟受責俾如流，是惟艱哉！我心之憂，日月逾邁，若弗云來！", "惟古之謀人，則曰『未就予忌』；惟今之謀人，姑將以為親。雖則云然，尚猷詢茲黃髮，則罔所愆。番番良士，旅力既愆，我尚有之。仡仡勇夫，射御不違，我尚不欲。惟截截善諞言，俾君子易辭，我皇多有之！", "昧昧我思之，如有一介臣，斷斷猗無他技，其心休休焉，其如有容。人之有技，若己有之。人之彥聖，其心好之，不啻若自其口出。是能容之，以保我子孫黎民，亦職有利哉！", "人之有技，冒疾以惡之。人之彥聖，而違之俾不達。是不能容，以不能保我子孫黎民，亦曰殆哉！邦之杌陧，曰由一人；邦之榮懷，亦尚一人之慶！」"], "quote": ["公曰︰「嗟！我士，聽無嘩！予誓告汝羣言之首。古人有言曰︰『民訖自若，是多盤。』責人斯無難，惟受責俾如流，是惟艱哉！我心之憂，日月逾邁，若弗云來！", "惟古之謀人，則曰『未就予忌』；惟今之謀人，姑將以為親。雖則云然，尚猷詢茲黃髮，則罔所愆。番番良士，旅力既愆，我尚有之。仡仡勇夫，射御不違，我尚不欲。惟截截善諞言，俾君子易辭，我皇多有之！", "昧昧我思之，如有一介臣，斷斷猗無他技，其心休休焉，其如有容。人之有技，若己有之。人之彥聖，其心好之，不啻若自其口出。是能容之，以保我子孫黎民，亦職有利哉！", "人之有技，冒疾以惡之。人之彥聖，而違之俾不達。是不能容，以不能保我子孫黎民，亦曰殆哉！邦之杌陧，曰由一人；邦之榮懷，亦尚一人之慶！」"], "intro": "本文為秦穆公作，向無異議。至於作於何時，誓於何地，歷來有三種說法： 1. 魯僖公三十三年（秦穆公三十三年），秦穆公親自帥師伐鄭，戰敗於崤山。還歸秦國，穆公自悔己過，誓戒群臣。 此說見於《尚書序》。《書序》曰：「秦穆公伐鄭，晉襄公帥師敗諸殽。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%91%A8%E6%9B%B8%E3%83%BB%E7%A7%A6%E8%AA%93"}, {"title": "九章・哀郢", "author": "屈原", "period": "先秦", "form": "楚辭", "theme": "江河湖海", "mood": "vast_river", "lines": ["皇天之不純命兮，何百姓之震愆？民離散而相失兮，方仲春而東遷。", "去故鄉而就遠兮，遵江夏以流亡。出國門而軫懷兮，甲之鼂吾以行。", "發郢都而去閭兮，怊荒忽之焉極？楫齊揚以容與兮，哀見君而不再得。", "望長楸而太息兮，涕淫淫其若霰。過夏首而西浮兮，顧龍門而不見。", "心嬋媛而傷懷兮，眇不知其所蹠。順風波以從流兮，焉洋洋而為客。", "淩陽侯之氾濫兮，忽翱翔之焉薄。心絓結而不解兮，思蹇產而不釋。", "將運舟而下浮兮，上洞庭而下江。去終古之所居兮，今逍遙而來東。", "羌靈魂之欲歸兮，何須臾而忘反。背夏浦而西思兮，哀故都之日遠。", "登大墳以遠望兮，聊以舒吾憂心。哀州土之平樂兮，悲江介之遺風。", "當陵陽之焉至兮，淼南渡之焉如？曾不知夏之為丘兮，孰兩東門之可蕪？", "心不怡之長久兮，憂與愁其相接。惟郢路之遼遠兮，江與夏之不可涉。", "忽若不信兮，至今九年而不復。慘鬱鬱而不通兮，蹇侘傺而含慼。"], "quote": ["皇天之不純命兮，何百姓之震愆？民離散而相失兮，方仲春而東遷。", "去故鄉而就遠兮，遵江夏以流亡。出國門而軫懷兮，甲之鼂吾以行。", "發郢都而去閭兮，怊荒忽之焉極？楫齊揚以容與兮，哀見君而不再得。", "望長楸而太息兮，涕淫淫其若霰。過夏首而西浮兮，顧龍門而不見。"], "intro": "《哀郢》選自《楚辭・九章》，版本據中華書局聚珍倣宋本。《楚辭》為騷體之祖，由於以屈原的《離騷》為代表作，故名。這種作品，富於抒情成份和浪漫氣息，篇幅、字句較長，形式也較自由，並多用「兮」字以助語勢，甚有特色。 《九章》是屈原所作，共九篇，《", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B9%9D%E7%AB%A0%E3%83%BB%E5%93%80%E9%83%A2"}, {"title": "九章・涉江", "author": "屈原", "period": "先秦", "form": "楚辭", "theme": "江河湖海", "mood": "snow_winter", "lines": ["余幼好此奇服兮，年既老而不衰。帶長鋏之陸離兮，冠切雲之崔嵬。被明月兮珮寶璐。世溷濁而莫余知兮，吾方高馳而不顧。駕青虬兮驂白螭，吾與重華遊兮瑤之圃。登崑崙兮食玉英，與天地兮同壽，與日月兮齊光。哀南夷之莫吾知兮，旦余濟乎江湘。", "乘鄂渚而反顧兮，欸秋冬之緒風。步余馬兮山臯，邸余車兮方林。乘舲船余上沅兮，齊吳榜以擊汏。船容與而不進兮，淹回水而疑滯。朝發枉陼兮，夕宿辰陽。苟余心其端直兮，雖僻遠之何傷？", "入潊浦余儃佪兮，迷不知吾所如。深林杳以冥冥兮，乃猨狖之所居。山峻高而蔽日兮，下幽晦以多雨。霰雪紛其無垠兮，雲霏霏而承宇。", "哀吾生之無樂兮，幽獨處乎山中。吾不能變心而從俗兮，固將愁苦而終窮。接輿髠首兮，桑扈臝行。忠不必用兮，賢不必以。伍子逢殃兮，比干菹醢。與前世而皆然兮，吾又何怨乎今之人！予將董道而不豫兮，固將重昬而終身。", "亂曰︰鸞鳥鳳皇，日以遠兮！燕雀烏鵲，巢堂壇兮！露申辛夷，死林薄兮！腥臊並御，芳不得薄兮！陰陽易位，時不當兮！懷言侘傺，忽乎吾將行兮！"], "quote": ["余幼好此奇服兮，年既老而不衰。帶長鋏之陸離兮，冠切雲之崔嵬。被明月兮珮寶璐。世溷濁而莫余知兮，吾方高馳而不顧。駕青虬兮驂白螭，吾與重華遊兮瑤之圃。登崑崙兮食玉英，與天地兮同壽，與日月兮齊光。哀南夷之莫吾知兮，旦余濟乎江湘。", "乘鄂渚而反顧兮，欸秋冬之緒風。步余馬兮山臯，邸余車兮方林。乘舲船余上沅兮，齊吳榜以擊汏。船容與而不進兮，淹回水而疑滯。朝發枉陼兮，夕宿辰陽。苟余心其端直兮，雖僻遠之何傷？", "入潊浦余儃佪兮，迷不知吾所如。深林杳以冥冥兮，乃猨狖之所居。山峻高而蔽日兮，下幽晦以多雨。霰雪紛其無垠兮，雲霏霏而承宇。", "哀吾生之無樂兮，幽獨處乎山中。吾不能變心而從俗兮，固將愁苦而終窮。接輿髠首兮，桑扈臝行。忠不必用兮，賢不必以。伍子逢殃兮，比干菹醢。與前世而皆然兮，吾又何怨乎今之人！予將董道而不豫兮，固將重昬而終身。"], "intro": "本文為屈原所作《九章》中的第二篇，是他晚年被流放到江南的作品。據本文所寫，他流放途中的行蹤，是渡過大江、湘水和沅水，一直到了當時楚國最荒遠的潊浦一帶，所以題為「涉江」。涉，就是渡水的意思。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B9%9D%E7%AB%A0%E3%83%BB%E6%B6%89%E6%B1%9F"}, {"title": "九歌・山鬼", "author": "屈原", "period": "先秦", "form": "楚辭", "theme": "山水登臨", "mood": "majestic_peaks", "lines": ["若有人兮山之阿，被薜荔兮帶女蘿。既含睇兮又宜笑，子慕予兮善窈窕。乘赤豹兮從文狸，辛夷車兮結桂旗。被石蘭兮帶杜衡，折芳馨兮遺所思。", "余處幽篁兮終不見天，路險難兮獨後來。表獨立兮山之上，雲容容兮而在下。杳冥冥兮羌晝晦，東風飄兮神靈雨。留靈修兮憺忘歸，歲既晏兮孰華予？", "采三秀兮於山間，石磊磊兮葛蔓蔓。怨公子兮悵忘歸，君思我兮不得閒。山中人兮芳杜若，飲石泉兮蔭松柏。君思我兮然疑作。", "靁填填兮雨冥冥，猨啾啾兮又夜鳴。風颯颯兮木蕭蕭，思公子兮徒離憂。"], "quote": ["若有人兮山之阿，被薜荔兮帶女蘿。既含睇兮又宜笑，子慕予兮善窈窕。乘赤豹兮從文狸，辛夷車兮結桂旗。被石蘭兮帶杜衡，折芳馨兮遺所思。", "余處幽篁兮終不見天，路險難兮獨後來。表獨立兮山之上，雲容容兮而在下。杳冥冥兮羌晝晦，東風飄兮神靈雨。留靈修兮憺忘歸，歲既晏兮孰華予？", "采三秀兮於山間，石磊磊兮葛蔓蔓。怨公子兮悵忘歸，君思我兮不得閒。山中人兮芳杜若，飲石泉兮蔭松柏。君思我兮然疑作。", "靁填填兮雨冥冥，猨啾啾兮又夜鳴。風颯颯兮木蕭蕭，思公子兮徒離憂。"], "intro": "「楚辭」是在戰國時期由楚國屈原、宋玉等人在民間歌謠基礎上加以潤飾、創造出的一種新詩歌形式，特色是句法參差錯落，篇幅也較長，所用語言和題材有濃厚的楚國地方色彩。由於文體別具風格，漢代稱之為楚辭。 《山鬼》是屈原所作《九歌》其中一篇。《九歌》原", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B9%9D%E6%AD%8C%E3%83%BB%E5%B1%B1%E9%AC%BC"}, {"title": "九歌・國殤", "author": "屈原", "period": "先秦", "form": "楚辭", "theme": "邊塞豪放", "mood": "heroic", "lines": ["操吳戈兮被犀甲，車錯轂兮短兵接。旌蔽日兮敵若雲，矢交墜兮士爭先。", "凌余陣兮躐余行，左驂殪兮右刃傷。霾兩輪兮縶四馬，援玉枹兮擊鳴鼓。天時墜兮威靈怒，嚴殺盡兮棄原埜。", "出不入兮往不反，平原忽兮路超遠。帶長劍兮挾秦弓，首身離兮心不懲。誠既勇兮又以武，終剛強兮不可凌。身既死兮神以靈，子魂魄兮為鬼雄。"], "quote": ["操吳戈兮被犀甲，車錯轂兮短兵接。旌蔽日兮敵若雲，矢交墜兮士爭先。", "凌余陣兮躐余行，左驂殪兮右刃傷。霾兩輪兮縶四馬，援玉枹兮擊鳴鼓。天時墜兮威靈怒，嚴殺盡兮棄原埜。", "出不入兮往不反，平原忽兮路超遠。帶長劍兮挾秦弓，首身離兮心不懲。誠既勇兮又以武，終剛強兮不可凌。身既死兮神以靈，子魂魄兮為鬼雄。"], "intro": "「殤」是夭折的意思；凡為國犧牲而死的人，就叫「國殤」。這首詩是屈原「九歌」裡的第十篇，九歌共十一篇，有人說首末兩篇是序曲和終曲，中間九首是原始歌劇。更有人推斷，因舊有歌辭鄙俚，屈原又另作了一遍。國殤是一首戰鬥的、悲壯的輓歌，古代祭祀陣亡將士", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B9%9D%E6%AD%8C%E3%83%BB%E5%9C%8B%E6%AE%A4"}, {"title": "離騷（節錄）", "author": "屈原", "period": "先秦", "form": "楚辭", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["帝高陽之苗裔兮，朕皇考曰伯庸。攝提貞于孟陬兮，惟庚寅吾以降。皇覽揆余初度兮，肇錫余以嘉名。名余曰正則兮，字余曰靈均。", "紛吾既有此內美兮，又重之以脩能。扈江離與辟芷兮，紉秋蘭以為佩。汩余若將不及兮，恐年歲之不吾與。朝搴阰之木蘭兮，夕攬洲之宿莽。日月忽其不淹兮，春與秋其代序。惟草木之零落兮，恐美人之遲暮。撫壯而棄穢兮，何不改此度也？乘騏驥以馳騁兮，來吾導夫先路也！", "昔三后之純粹兮，固眾芳之所在。雜申椒與菌桂兮，豈維紉夫蕙茝？彼堯舜之耿介兮，既遵道而得路；何桀紂之猖披兮，夫唯捷徑以窘步！惟夫黨人之偷樂兮，路幽昧以險隘。豈余身之憚殃兮？恐皇輿之敗績。忽奔走以先後兮，及前王之踵武。荃不察余之中情兮，反信讒而齌怒。余固知謇謇之為患兮，忍而不能舍也。指九天以為正兮，夫唯靈脩之故也。初既與余成言兮，後悔遁而有他。余既不難夫離別兮，傷靈脩之數化。", "余既滋蘭之九畹兮，又樹蕙之百畝。畦留夷與揭車兮，雜杜衡與芳芷。冀枝葉之峻茂兮，願竢時乎吾將刈。雖萎絕其亦何傷兮，哀眾芳之蕪穢。", "眾皆競進以貪婪兮，憑不厭乎求索。羌內恕己以量人兮，各興心而嫉妒。忽馳騖以追逐兮，非余心之所急。老冉冉其將至兮，恐脩名之不立。朝飲木蘭之墜露兮，夕餐秋菊之落英。苟余情其信姱以練要兮，長顑頷亦何傷？擥木根以結茝兮，貫薜荔之落蕊。矯菌桂以紉蕙兮，索胡繩之纚纚。謇吾法夫前脩兮，非時俗之所服。雖不周於今之人兮，願依彭咸之遺則。", "長太息以掩涕兮，哀民生之多艱。余雖脩姱以鞿羈兮，謇朝誶而夕替。既替余以蕙纕兮，又申之以擥茝。亦余心之所善兮，雖九死其猶未悔。", "怨靈脩之浩蕩兮，終不察夫民心。眾女嫉余之娥眉兮，謠諑謂余以善淫。固時俗之工巧兮，偭規矩而改錯。背繩墨以追曲兮，競周容以為度。忳鬱邑余侘傺兮，吾獨窮困乎此時也！寧溘死以流亡兮，余不忍為此態也。", "鷙鳥之不群兮，自前世而固然。何方圜之能周兮？夫孰異道而相安？屈心而抑志兮，忍尤而攘詬。伏清白以死直兮，固前聖之所厚。"], "quote": ["帝高陽之苗裔兮，朕皇考曰伯庸。攝提貞于孟陬兮，惟庚寅吾以降。皇覽揆余初度兮，肇錫余以嘉名。名余曰正則兮，字余曰靈均。", "紛吾既有此內美兮，又重之以脩能。扈江離與辟芷兮，紉秋蘭以為佩。汩余若將不及兮，恐年歲之不吾與。朝搴阰之木蘭兮，夕攬洲之宿莽。日月忽其不淹兮，春與秋其代序。惟草木之零落兮，恐美人之遲暮。撫壯而棄穢兮，何不改此度也？乘騏驥以馳騁兮，來吾導夫先路也！", "昔三后之純粹兮，固眾芳之所在。雜申椒與菌桂兮，豈維紉夫蕙茝？彼堯舜之耿介兮，既遵道而得路；何桀紂之猖披兮，夫唯捷徑以窘步！惟夫黨人之偷樂兮，路幽昧以險隘。豈余身之憚殃兮？恐皇輿之敗績。忽奔走以先後兮，及前王之踵武。荃不察余之中情兮，反信讒而齌怒。余固知謇謇之為患兮，忍而不能舍也。指九天以為正兮，夫唯靈脩之故也。初既與余成言兮，後悔遁而有他。余既不難夫離別兮，傷靈脩之數化。", "余既滋蘭之九畹兮，又樹蕙之百畝。畦留夷與揭車兮，雜杜衡與芳芷。冀枝葉之峻茂兮，願竢時乎吾將刈。雖萎絕其亦何傷兮，哀眾芳之蕪穢。"], "intro": "《離騷》為屈原的主要作品，「離」是離別，「騷」是歌曲的名稱，「離騷」就是「離歌」。司馬遷解釋：「離」作「遭」解，「騷」作「憂」解，「離騷」是「遭憂」的意思。因此，《離騷》也可以說是屈原遭遇着憂患，為抒發胸中積鬱而寫的一首長詩。 《離騷》的寫", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%9B%A2%E9%A8%B7%EF%BC%88%E7%AF%80%E9%8C%84%EF%BC%89"}, {"title": "勸學（節錄）", "author": "荀子", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["君子曰︰學不可以已。青，取之於藍，而青於藍；冰，水為之，而寒於水。木直中繩，輮以為輪，其曲中規；雖有槁曝、不復挺者，輮使之然也。故木受繩則直，金就礪則利，君子博學而日參省乎己，則知明而行無過矣。", "吾嘗終日而思矣，不如須臾之所學也；吾嘗跂而望矣，不如登高之博見也。登高而招，臂非加長也，而見者遠。順風而呼，聲非加疾也，而聞者彰。", "假輿馬者，非利足也，而致千里；假舟楫者，非能水也，而絕江河。君子生非異也，善假於物也。", "積土成山，風雨興焉；積水成淵，蛟龍生焉；積善成德，而神明自得，聖心備焉。故不積跬步，無以至千里；不積小流，無以成江海。騏驥一躍，不能十步；駑馬十駕，功在不舍。", "鍥而舍之，朽木不折；鍥而不舍，金石可鏤。螾無爪牙之利，筋骨之強，上食埃土，下飲黃泉，用心一也。蟹六跪而二螯，非蛇蟺之穴無可寄託者，用心躁也。"], "quote": ["君子曰︰學不可以已。青，取之於藍，而青於藍；冰，水為之，而寒於水。木直中繩，輮以為輪，其曲中規；雖有槁曝、不復挺者，輮使之然也。故木受繩則直，金就礪則利，君子博學而日參省乎己，則知明而行無過矣。", "吾嘗終日而思矣，不如須臾之所學也；吾嘗跂而望矣，不如登高之博見也。登高而招，臂非加長也，而見者遠。順風而呼，聲非加疾也，而聞者彰。", "假輿馬者，非利足也，而致千里；假舟楫者，非能水也，而絕江河。君子生非異也，善假於物也。", "積土成山，風雨興焉；積水成淵，蛟龍生焉；積善成德，而神明自得，聖心備焉。故不積跬步，無以至千里；不積小流，無以成江海。騏驥一躍，不能十步；駑馬十駕，功在不舍。"], "intro": "《荀子》共20卷，收錄文章32篇，其中絕大部分是他自己的作品，部分可能由他的弟子記錄而成，內容包括哲學思想、政治問題、治學方法、立身處世之道、學術論辯等。 本篇節錄自《荀子‧勸學》，《勸學》是《荀子》的第一篇，論述了學習的意義、作用、方法和", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%8B%B8%E5%AD%B8%EF%BC%88%E7%AF%80%E9%8C%84%EF%BC%89"}, {"title": "孫子二則", "author": "《孫子》", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["謀攻篇（節錄）", "故用兵之法，十則圍之，五則攻之，倍則分之，敵則能戰之，少則能逃之，不若則能避之。故小敵之堅，大敵之擒也。", "夫將者，國之輔也；輔周則國必強，輔隙則國必弱。", "故君之所以患於軍者三︰不知軍之不可以進而謂之進，不知軍之不可以退而謂之退，是謂縻軍。", "不知三軍之事，而同三軍之政者，則軍士惑矣；不知三軍之權，而同三軍之任，則軍士疑矣。三軍既惑且疑，則諸侯之難至矣。是謂亂軍引勝。", "故知勝有五︰知可以戰與不可以戰者勝，識眾寡之用者勝，上下同欲者勝，以虞待不虞者勝，將能而君不御者勝。此五者，知勝之道也。", "故曰︰知彼知己者，百戰不殆；不知彼而知己，一勝一負；不知彼，不知己，每戰必殆。", "地形篇（節錄）", "視卒如嬰兒，故可與之赴深谿；視卒如愛子，故可與之俱死。厚而不能使，愛而不能令，亂而不能治，譬若驕子，不可用也。", "知吾卒之可以擊，而不知敵之不可擊，勝之半也；知敵之可擊，而不知吾卒之不可以擊，勝之半也；知敵之可擊，知吾卒之可以擊，而不知地形之不可以戰，勝之半也。", "故知兵者，動而不迷，舉而不窮。故曰︰知彼知己，勝乃不殆；知天知地，勝乃不窮。"], "quote": ["謀攻篇（節錄）", "故用兵之法，十則圍之，五則攻之，倍則分之，敵則能戰之，少則能逃之，不若則能避之。故小敵之堅，大敵之擒也。", "夫將者，國之輔也；輔周則國必強，輔隙則國必弱。", "故君之所以患於軍者三︰不知軍之不可以進而謂之進，不知軍之不可以退而謂之退，是謂縻軍。"], "intro": "本篇第一則節錄自《孫子‧謀攻》，第二則節錄自《孫子‧地形》，版本據《先秦兩漢古籍逐字索引》。 《謀攻》是《孫子》第三篇，內容論述運用計謀獲取勝利的方法，而本節錄部分提出的「知彼知己者，百戰不殆」，更成為戰事的普遍規律。 《地形》是《孫子》第", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%AD%AB%E5%AD%90%E4%BA%8C%E5%89%87"}, {"title": "晏子相齊", "author": "《晏子春秋》", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["晏子為齊相，出，其御之妻，從門間闚其夫。其夫為相御，擁大蓋，策駟馬，意氣揚揚，甚自得也。", "既而歸，其妻請去，夫問其故。妻曰︰「晏子長不滿六尺，身相齊國，名顯諸侯。今者妾觀其出，志念深矣，常有以自下者。今子長八尺，迺為人僕御；然子之意，自以為足，妾是以求去也。」", "其後，夫自抑損，晏子怪而問之，御以實對。晏子薦以為大夫。"], "quote": ["晏子為齊相，出，其御之妻，從門間闚其夫。其夫為相御，擁大蓋，策駟馬，意氣揚揚，甚自得也。", "既而歸，其妻請去，夫問其故。妻曰︰「晏子長不滿六尺，身相齊國，名顯諸侯。今者妾觀其出，志念深矣，常有以自下者。今子長八尺，迺為人僕御；然子之意，自以為足，妾是以求去也。」", "其後，夫自抑損，晏子怪而問之，御以實對。晏子薦以為大夫。"], "intro": "本篇選自《晏子春秋》，漢司馬遷著《史記》時，曾引入《管晏列傳》中，乃敍晏子的車夫的故事。晏子，名嬰，字仲，謚平，史稱晏平仲，春秋時代齊國夷維（今山東高密縣）人。他是齊國的大夫，歷相齊靈公、莊公、景公三朝，以節儉力行顯於世，為古代名臣。題為「", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%99%8F%E5%AD%90%E7%9B%B8%E9%BD%8A"}, {"title": "庖丁解牛", "author": "莊子", "period": "先秦", "form": "文", "theme": "田園幽居", "mood": "ethereal", "lines": ["吾生也有涯，而知也無涯；以有涯隨無涯，殆已！已而為知者，殆而已矣。為善無近名，為惡無近刑；緣督以為經，可以保身，可以全生，可以養親，可以盡年。", "庖丁為文惠君解牛，手之所觸，肩之所倚，足之所履，膝之所踦，砉然嚮然，奏刀騞然，莫不中音；合於桑林之舞，乃中經首之會。文惠君曰︰「譆，善哉！技蓋至此乎？」", "庖丁釋刀對曰︰「臣之所好者，道也，進乎技矣。始臣之解牛之時，所見無非牛者；三年之後，未嘗見全牛也。方今之時，臣以神遇而不以目視，官知止而神欲行。依乎天理，批大郤，導大窾，因其固然；", "技經肯綮之未嘗，而況大軱乎！良庖歲更刀，割也；族庖月更刀，折也。今臣之刀十九年矣，所解數千牛矣，而刀刃若新發於硎。彼節者有間，而刀刃者無厚；以無厚入有間，恢恢乎其於遊刃必有餘地矣！", "是以十九年而刀刃若新發於硎。雖然，每至於族，吾見其難為；怵然為戒，視為止，行為遲，動刀甚微，謋然已解，如土委地。提刀而立，為之四顧，為之躊躇滿志，善刀而藏之。」", "文惠君曰︰「善哉！吾聞庖丁之言，得養生焉。」"], "quote": ["吾生也有涯，而知也無涯；以有涯隨無涯，殆已！已而為知者，殆而已矣。為善無近名，為惡無近刑；緣督以為經，可以保身，可以全生，可以養親，可以盡年。", "庖丁為文惠君解牛，手之所觸，肩之所倚，足之所履，膝之所踦，砉然嚮然，奏刀騞然，莫不中音；合於桑林之舞，乃中經首之會。文惠君曰︰「譆，善哉！技蓋至此乎？」", "庖丁釋刀對曰︰「臣之所好者，道也，進乎技矣。始臣之解牛之時，所見無非牛者；三年之後，未嘗見全牛也。方今之時，臣以神遇而不以目視，官知止而神欲行。依乎天理，批大郤，導大窾，因其固然；", "技經肯綮之未嘗，而況大軱乎！良庖歲更刀，割也；族庖月更刀，折也。今臣之刀十九年矣，所解數千牛矣，而刀刃若新發於硎。彼節者有間，而刀刃者無厚；以無厚入有間，恢恢乎其於遊刃必有餘地矣！"], "intro": "本篇乃《莊子‧內篇》七篇中的第三篇。題名「養生主」，即養生之道以此為主之意。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%BA%96%E4%B8%81%E8%A7%A3%E7%89%9B"}, {"title": "東施效顰", "author": "莊子", "period": "先秦", "form": "文", "theme": "送別行旅", "mood": "autumn_sunset", "lines": ["西施病心而顰其里，其里之醜人見而美之，歸亦捧心而顰其里。其里之富人見之，堅閉門而不出；貧人見之，挈妻子而去之走。", "彼知顰美而不知顰之所以美。"], "quote": ["西施病心而顰其里，其里之醜人見而美之，歸亦捧心而顰其里。其里之富人見之，堅閉門而不出；貧人見之，挈妻子而去之走。", "彼知顰美而不知顰之所以美。"], "intro": "西施是中國傳說中的一位絕色美女。據說西施名叫施夷光，是春秋末期越國人。她的家鄉有兩個村子，分在東西，村中的人大多數姓施，施夷光住在西村，所以大家都叫她西施。住在東村的就叫做東施。 當時越國和吳國打仗，越國給吳國打敗了。越王勾踐想找美女獻給吳", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9D%B1%E6%96%BD%E6%95%88%E9%A1%B0"}, {"title": "知魚之樂", "author": "莊子", "period": "先秦", "form": "文", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["莊子與惠子游於濠梁之上。莊子曰︰「鯈魚出游從容，是魚之樂也。」惠子曰︰「子非魚，安知魚之樂？」莊子曰︰「子非我，安知我不知魚之樂？」", "惠子曰︰「我非子，固不知子矣；子固非魚也，子之不知魚之樂，全矣！」莊子曰︰「請循其本。子曰『汝安知魚樂』云者，既已知吾知之而問我。我知之濠上也。」"], "quote": ["莊子與惠子游於濠梁之上。莊子曰︰「鯈魚出游從容，是魚之樂也。」惠子曰︰「子非魚，安知魚之樂？」莊子曰︰「子非我，安知我不知魚之樂？」", "惠子曰︰「我非子，固不知子矣；子固非魚也，子之不知魚之樂，全矣！」莊子曰︰「請循其本。子曰『汝安知魚樂』云者，既已知吾知之而問我。我知之濠上也。」"], "intro": "本篇選自《莊子》「外篇」的《秋水》，篇名來自文中首兩個字。《秋水》全文很長，可分為兩大部分，第一部分是河伯（河神）和北海若（海神）的對話，第二部分包含六個各自獨立的故事。這裏節選的是篇中最後一個故事，寫莊子和惠子（惠施）有關「魚之樂」的一場", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%9F%A5%E9%AD%9A%E4%B9%8B%E6%A8%82"}, {"title": "逍遙遊（節錄）", "author": "莊子", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["惠子謂莊子曰︰「魏王貽我大瓠之種，我樹之成而實五石。以盛水漿，其堅不能自舉也。剖之以為瓢，則瓠落無所容。非不呺然大也，吾為其無用而掊之。」", "莊子曰︰「夫子固拙於用大矣！宋人有善為不龜手之藥者，世世以洴澼絖為事。客聞之，請買其方百金。聚族而謀曰︰『我世世為洴澼絖，不過數金；今一朝而鬻技百金，請與之。』", "客得之，以說吳王。越有難，吳王使之將，冬與越人水戰，大敗越人，裂地而封之。能不龜手一也；或以封，或不免於洴澼絖，則所用之異也。", "今子有五石之瓠，何不慮以為大樽而浮於江湖，而憂其瓠落無所容，則夫子猶有蓬之心也夫！」", "惠子謂莊子曰︰「吾有大樹，人謂之樗；其大本擁腫而不中繩墨，其小枝卷曲而不中規矩。立之塗，匠者不顧。今子之言，大而無用，衆所同去也。」", "莊子曰︰「子獨不見狸狌乎？卑身而伏，以候敖者；東西跳梁，不辟高下，中於機辟，死於罔罟。今夫斄牛，其大若垂天之雲；此能為大矣，而不能執鼠。", "今子有大樹，患其無用，何不樹之於無何有之鄉，廣莫之野，彷徨乎無為其側，逍遙乎寢臥其下；不夭斤斧，物無害者。無所可用，安所困苦哉？」"], "quote": ["惠子謂莊子曰︰「魏王貽我大瓠之種，我樹之成而實五石。以盛水漿，其堅不能自舉也。剖之以為瓢，則瓠落無所容。非不呺然大也，吾為其無用而掊之。」", "莊子曰︰「夫子固拙於用大矣！宋人有善為不龜手之藥者，世世以洴澼絖為事。客聞之，請買其方百金。聚族而謀曰︰『我世世為洴澼絖，不過數金；今一朝而鬻技百金，請與之。』", "客得之，以說吳王。越有難，吳王使之將，冬與越人水戰，大敗越人，裂地而封之。能不龜手一也；或以封，或不免於洴澼絖，則所用之異也。", "今子有五石之瓠，何不慮以為大樽而浮於江湖，而憂其瓠落無所容，則夫子猶有蓬之心也夫！」"], "intro": "本篇節錄自《莊子‧內篇‧逍遙遊》，《逍遙遊》是《莊子》的首篇，無論是思想上或藝術上，都可視為莊子的代表作。據陳鼓應《莊子今注今譯》的分析，《逍遙遊》的主旨是「說一個人當透破功名利祿、權勢尊位的束縛，而使精神活動臻於優游自在、無掛無礙的境地。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%80%8D%E9%81%99%E9%81%8A%EF%BC%88%E7%AF%80%E9%8C%84%EF%BC%89"}, {"title": "召公諫厲王止謗", "author": "《國語》", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "majestic_peaks", "lines": ["厲王虐，國人謗王。", "召公告王曰︰「民不堪命矣！」王怒。得衛巫，使監謗者。以告，則殺之。國人莫敢言，道路以目。", "王喜。告召公曰︰「吾能弭謗矣，乃不敢言！」召公曰︰「是障之也。防民之口，甚於防川。川壅而潰，傷人必多，民亦如之。是故為川者，決之使導；為民者，宣之使言。", "故天子聽政，使公卿至於列士獻詩，瞽獻曲，史獻書，師箴，瞍賦，矇誦，百工諫，庶人傳語，近臣盡規，親戚補察，瞽史教誨，耆艾修之，而後王斟酌焉。", "是以事行而不悖。民之有口也，猶土之有山川也，財用於是乎出；猶其有原隰衍沃也，衣食於是乎生。口之宣言也，善敗於是乎興。行善而備敗，所以阜財用衣食者也。", "夫民慮之於心，而宣之於口，成而行之，胡可壅也？若壅其口，其與能幾何？」", "王弗聽。於是國人莫敢出言。三年，乃流王於彘。"], "quote": ["厲王虐，國人謗王。", "召公告王曰︰「民不堪命矣！」王怒。得衛巫，使監謗者。以告，則殺之。國人莫敢言，道路以目。", "王喜。告召公曰︰「吾能弭謗矣，乃不敢言！」召公曰︰「是障之也。防民之口，甚於防川。川壅而潰，傷人必多，民亦如之。是故為川者，決之使導；為民者，宣之使言。", "故天子聽政，使公卿至於列士獻詩，瞽獻曲，史獻書，師箴，瞍賦，矇誦，百工諫，庶人傳語，近臣盡規，親戚補察，瞽史教誨，耆艾修之，而後王斟酌焉。"], "intro": "本篇選自《國語・周語》，所記乃召公諫周厲王止謗之辭。周厲王，名胡，周夷王之子，是周代第十任國王，為西周有名的暴君。他即位於公元前八七八年，因為暴虐無道，於即位第三十七年，為人民所廢逐，居外十四年而死。召公卻召穆公，名虎，乃文王庶子召康公之後", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%8F%AC%E5%85%AC%E8%AB%AB%E5%8E%B2%E7%8E%8B%E6%AD%A2%E8%AC%97%E3%80%80"}, {"title": "小雅・采薇", "author": "《詩經》", "period": "先秦", "form": "詩經", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["采薇采薇！薇亦作止。曰歸曰歸！歲亦莫止。靡室靡家，玁狁之故。不遑啓居，玁狁之故。", "采薇采薇！薇亦柔止。曰歸曰歸！心亦憂止。憂心烈烈，載飢載渴。我戍未定，靡使歸聘。", "采薇采薇！薇亦剛止。曰歸曰歸！歲亦陽止。王事靡盬，不遑啓處!。憂心孔疚，我行不來！", "彼爾維何？維常之華。彼路斯何？君子之車。戎車既駕，四牡業業。豈敢定居？一月三捷！", "駕彼四牡，四牡騤騤。君子所依，小人所腓。四牡翼翼，象弭魚服。豈不日戒？玁狁孔棘！", "昔我往矣，楊柳依依。今我來思，雨雪霏霏。行道遲遲，載渴載飢。我心傷悲，莫知我哀！"], "quote": ["采薇采薇！薇亦作止。曰歸曰歸！歲亦莫止。靡室靡家，玁狁之故。不遑啓居，玁狁之故。", "采薇采薇！薇亦柔止。曰歸曰歸！心亦憂止。憂心烈烈，載飢載渴。我戍未定，靡使歸聘。", "采薇采薇！薇亦剛止。曰歸曰歸！歲亦陽止。王事靡盬，不遑啓處!。憂心孔疚，我行不來！", "彼爾維何？維常之華。彼路斯何？君子之車。戎車既駕，四牡業業。豈敢定居？一月三捷！"], "intro": "《采薇》為《詩 · 小雅》的一篇，版本據《先秦兩漢古籍逐字索引》。《詩序》謂「《采薇》，遣戌役也」，是「文王之時」作。後多不從此說，至今亦無定論。周朝時，北方的玁狁時常南侵，不斷發生戰爭。宣王時，征服了玁狁，《小雅》的《出車》和《六月》等篇", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B0%8F%E9%9B%85%E3%83%BB%E9%87%87%E8%96%87"}, {"title": "小雅・鹿鳴", "author": "《詩經》", "period": "先秦", "form": "詩經", "theme": "詠史哲思", "mood": "spring_breeze", "lines": ["呦呦鹿鳴，食野之苹。", "我有嘉賓，鼓瑟吹笙。", "吹笙鼓簧，承筐是將。", "人之好我，示我周行。", "呦呦鹿鳴，食野之蒿。", "我有嘉賓，德音孔昭。", "視民不恌，君子是則是傚。", "我有旨酒，嘉賓式燕以敖。", "呦呦鹿鳴，食野之芩。", "我有嘉賓，鼓瑟鼓琴。", "鼓瑟鼓琴，和樂且湛。", "我有旨酒，以燕樂嘉賓之心。"], "quote": ["呦呦鹿鳴，食野之苹。", "我有嘉賓，鼓瑟吹笙。", "吹笙鼓簧，承筐是將。", "人之好我，示我周行。"], "intro": "雅、頌無分國別，以十篇為一卷，謂之「什」，《鹿鳴》是《詩經・小雅・鹿鳴之什》的第一篇，也是小雅的首篇。小雅描寫諸侯以下貴族之禮樂。朱傳云：「以今考之，正小雅，燕饗之樂也；正大雅，會朝之樂，受釐陳戒之辭也。故或歡欣和悅，以盡群下之情；或恭敬齊", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B0%8F%E9%9B%85%E3%83%BB%E9%B9%BF%E9%B3%B4"}, {"title": "小雅・蓼莪", "author": "《詩經》", "period": "先秦", "form": "詩經", "theme": "山水登臨", "mood": "majestic_peaks", "lines": ["蓼蓼者莪，匪莪伊蒿，哀哀父母，生我劬勞！", "蓼蓼者莪，匪莪依蔚，哀哀父母，生我勞瘁！", "缾之罄矣，維罍之恥，鮮民之生，不如死之久矣！", "無父何怙？無母何恃？出則銜恤，入則靡至。", "父兮生我！母兮鞠我！拊我畜我，長我育我。", "顧我復我，出入腹我，欲報之德，昊天罔極！", "南山烈烈，飄風發發。民莫不穀，我獨何害！", "南山律律，飄風弗弗。民莫不穀，我獨不卒！"], "quote": ["蓼蓼者莪，匪莪伊蒿，哀哀父母，生我劬勞！", "蓼蓼者莪，匪莪依蔚，哀哀父母，生我勞瘁！", "缾之罄矣，維罍之恥，鮮民之生，不如死之久矣！", "無父何怙？無母何恃？出則銜恤，入則靡至。"], "intro": "《蓼莪》是《小雅・谷風之什》中的一篇。《詩序》：「蓼莪，刺幽王也。民人勞苦，孝子不得終養爾。」這是一首悼念父母的詩，表達孝子無法終養的心情。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B0%8F%E9%9B%85%E3%83%BB%E8%93%BC%E8%8E%AA"}, {"title": "王風・黍離", "author": "《詩經》", "period": "先秦", "form": "詩經", "theme": "春水花鳥", "mood": "vast_river", "lines": ["彼黍離離，彼稷之苗。行邁靡靡，中心搖搖。知我者謂我心憂，不知我者謂我何求。悠悠蒼天，此何人哉？", "彼黍離離，彼稷之穗。行邁靡靡，中心如醉。知我者謂我心憂，不知我者謂我何求。悠悠蒼天，此何人哉？", "彼黍離離，彼稷之實。行邁靡靡，中心如噎。知我者謂我心憂，不知我者謂我何求。悠悠蒼天，此何人哉？"], "quote": ["彼黍離離，彼稷之苗。行邁靡靡，中心搖搖。知我者謂我心憂，不知我者謂我何求。悠悠蒼天，此何人哉？", "彼黍離離，彼稷之穗。行邁靡靡，中心如醉。知我者謂我心憂，不知我者謂我何求。悠悠蒼天，此何人哉？", "彼黍離離，彼稷之實。行邁靡靡，中心如噎。知我者謂我心憂，不知我者謂我何求。悠悠蒼天，此何人哉？"], "intro": "這詩列於詩經「國風」中的「王風」。「王」是指的周王城（故城在今河南洛陽縣城西）所轄面積六百里的區域。原來周初文王都豐，武王都鎬，均在陝西西安附近。到了成王（姬誦）時，周公旦鑒於河南洛陽乃當時中國適中的地點，為使諸侯朝貢道里均平，便在洛陽再建", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%8E%8B%E9%A2%A8%E3%83%BB%E9%BB%8D%E9%9B%A2"}, {"title": "周南・桃夭", "author": "《詩經》", "period": "先秦", "form": "詩經", "theme": "春水花鳥", "mood": "vast_river", "lines": ["桃之夭夭，灼灼其華。之子于歸，宜其室家。", "桃之夭夭，有蕡其實。之子于歸，宜其家室。", "桃之夭夭，其葉蓁蓁。之子于歸，宜其家人。"], "quote": ["桃之夭夭，灼灼其華。之子于歸，宜其室家。", "桃之夭夭，有蕡其實。之子于歸，宜其家室。", "桃之夭夭，其葉蓁蓁。之子于歸，宜其家人。"], "intro": "《桃夭》出自《詩經》中《國風・周南》。《周南》是十五國風之一，是周公姬旦統治下的南方地區的民歌，範圍包括洛陽以南，直到江漢一帶地區。 關於此詩的背景，《毛詩序》指與后妃君王有關。現代學者一般不取《毛詩序》的觀點，認爲這是一首祝賀年青姑娘出嫁", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%91%A8%E5%8D%97%E3%83%BB%E6%A1%83%E5%A4%AD"}, {"title": "周南・關雎", "author": "《詩經》", "period": "先秦", "form": "詩經", "theme": "邊塞豪放", "mood": "autumn_sunset", "lines": ["關關雎鳩，在河之洲。窈窕淑女，君子好逑。", "參差荇菜，左右流之。窈窕淑女，寤寐求之。", "求之不得，寤寐思服。悠哉悠哉，輾轉反側。", "參差荇菜，左右采之。窈窕淑女，琴瑟友之。", "參差荇菜，左右芼之。窈窕淑女，鐘鼓樂之。"], "quote": ["關關雎鳩，在河之洲。窈窕淑女，君子好逑。", "參差荇菜，左右流之。窈窕淑女，寤寐求之。", "求之不得，寤寐思服。悠哉悠哉，輾轉反側。", "參差荇菜，左右采之。窈窕淑女，琴瑟友之。"], "intro": "《詩經》裏《國風》全是採自各國的民間歌唱，《關雎》一詩採自周南地區，這一地區在周都以南，是武王初封周公的采邑，據《史記集解》說，其地即今之洛陽。 魯詩說《關雎》乃諷刺周康王晏起晚朝的詩，毛詩則相反，以為這是歌頌后妃之美德的作品，朱子在《集傳", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%91%A8%E5%8D%97%E3%83%BB%E9%97%9C%E9%9B%8E"}, {"title": "秦風・無衣", "author": "《詩經》", "period": "先秦", "form": "詩經", "theme": "春水花鳥", "mood": "ethereal", "lines": ["豈曰無衣？與子同袍。王于興師，修我戈矛，與子同仇！", "豈曰無衣？與子同澤。王于興師，修我矛戟，與子偕作！", "豈曰無衣？與子同裳。王于興師，修我甲兵，與子偕行！"], "quote": ["豈曰無衣？與子同袍。王于興師，修我戈矛，與子同仇！", "豈曰無衣？與子同澤。王于興師，修我矛戟，與子偕作！", "豈曰無衣？與子同裳。王于興師，修我甲兵，與子偕行！"], "intro": "《無衣》選自《詩經・秦風》，版本據《先秦兩漢古籍逐字索引》。《秦風》是十五國風之一。秦，國名，在禹貢雍州地域。《毛詩》說：「《無衣》、刺用兵也。秦人刺其君好攻戰，亟用兵，而不與民同欲焉。」以為是刺詩。然後世或以為《序》意與詩情不協。今據其內", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%A7%A6%E9%A2%A8%E3%83%BB%E7%84%A1%E8%A1%A3"}, {"title": "秦風・蒹葭", "author": "《詩經》", "period": "先秦", "form": "詩經", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["蒹葭蒼蒼，白露為霜。所謂伊人，在水一方。", "遡洄從之，道阻且長。遡游從之，宛在水中央。", "蒹葭萋萋，白露未晞。所謂伊人，在水之湄。", "遡洄從之，道阻且躋。遡游從之，宛在水中坻。", "蒹葭采采，白露未已。所謂伊人，在水之涘。", "遡洄從之，道阻且右。遡游從之，宛在水中沚。"], "quote": ["蒹葭蒼蒼，白露為霜。所謂伊人，在水一方。", "遡洄從之，道阻且長。遡游從之，宛在水中央。", "蒹葭萋萋，白露未晞。所謂伊人，在水之湄。", "遡洄從之，道阻且躋。遡游從之，宛在水中坻。"], "intro": "《蒹葭》選自《詩經・秦風》，版本據《先秦兩漢古籍逐字索引》。據《毛詩序》云：「蒹葭，刺襄公也。未能用周禮。將無以固其國焉。」這是以寄託的手法去解釋詩義。《蒹葭》也可以作懷人的情詩去讀，寫對所愛的人的思慕之情，以及可望而不得近的惆悵。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%A7%A6%E9%A2%A8%E3%83%BB%E8%92%B9%E8%91%AD"}, {"title": "衛風・氓", "author": "《詩經》", "period": "先秦", "form": "詩經", "theme": "春水花鳥", "mood": "autumn_sunset", "lines": ["氓之蚩蚩，抱布貿絲。匪來貿絲，來即我謀。送子涉淇，至于頓丘。匪我愆期，子無良媒。將子無怒，秋以為期。", "乘彼垝垣，以望復關。不見復關，泣涕漣漣。既見復關，載笑載言。爾卜爾筮，體無咎言？以爾車來，以我賄遷。", "桑之未落，其葉沃若。于嗟鳩兮，無食桑葚。于嗟女兮，無與士耽！士之耽兮，猶可說也。女之耽兮，不可說也。", "桑之落矣，其黃而隕。自我徂爾，三歲食貧。淇水湯湯，漸車帷裳。女也不爽，士貣其行。士也罔極，二三其德。", "三歲為婦，靡室勞矣。夙興夜寐，靡有朝矣。言既遂矣，至于暴矣。兄弟不知，咥其笑矣。靜言思之，躬自悼矣。", "及爾偕老！老使我怨。淇則有岸，隰則有泮！總角之宴，言笑晏晏。信誓旦旦，不思其反。反是不思，亦已焉哉！"], "quote": ["氓之蚩蚩，抱布貿絲。匪來貿絲，來即我謀。送子涉淇，至于頓丘。匪我愆期，子無良媒。將子無怒，秋以為期。", "乘彼垝垣，以望復關。不見復關，泣涕漣漣。既見復關，載笑載言。爾卜爾筮，體無咎言？以爾車來，以我賄遷。", "桑之未落，其葉沃若。于嗟鳩兮，無食桑葚。于嗟女兮，無與士耽！士之耽兮，猶可說也。女之耽兮，不可說也。", "桑之落矣，其黃而隕。自我徂爾，三歲食貧。淇水湯湯，漸車帷裳。女也不爽，士貣其行。士也罔極，二三其德。"], "intro": "《氓》選自《詩經．衛風》，版本據《先秦兩漢古籍逐字索引》。《衛風》是十五國風之一。衛，國名，國都朝歌，即今河南淇縣。《毛詩序》云：「《氓》，刺時也。宣公之時，禮義消亡，淫風大行。男女無別，遂相奔誘，華落色衰，復相棄背。或乃困而自悔，喪其妃耦", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A1%9B%E9%A2%A8%E3%83%BB%E6%B0%93"}, {"title": "魏風・碩鼠", "author": "《詩經》", "period": "先秦", "form": "詩經", "theme": "春水花鳥", "mood": "autumn_sunset", "lines": ["碩鼠碩鼠，無食我黍！三歲貫女，莫我肯顧。逝將去女，適彼樂土。樂土樂土，爰得我所。", "碩鼠碩鼠，無食我麥！三歲貫女，莫我肯德。逝將去女，適彼樂國。樂國樂國，爰得我直。", "碩鼠碩鼠，無食我苗！三歲貫女，莫我肯勞。逝將去女，適彼樂郊。樂郊樂郊，誰之永號。"], "quote": ["碩鼠碩鼠，無食我黍！三歲貫女，莫我肯顧。逝將去女，適彼樂土。樂土樂土，爰得我所。", "碩鼠碩鼠，無食我麥！三歲貫女，莫我肯德。逝將去女，適彼樂國。樂國樂國，爰得我直。", "碩鼠碩鼠，無食我苗！三歲貫女，莫我肯勞。逝將去女，適彼樂郊。樂郊樂郊，誰之永號。"], "intro": "《詩經》收錄了自西周初年（約公元前11世紀）至春秋中葉（約公元前6世紀）五百多年間的305篇作品，編定成書約在春秋後期。孔子認為它有多方面的實用價值，加以整理後，拿來教授弟子。 《詩經》依音樂特點分為「風」、「雅」、「頌」三類。「風」有十五", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%AD%8F%E9%A2%A8%E3%83%BB%E7%A2%A9%E9%BC%A0"}, {"title": "一年之計", "author": "《管子》", "period": "先秦", "form": "文", "theme": "田園幽居", "mood": "ethereal", "lines": ["一年之計，莫如樹穀；十年之計，莫如樹木；終身之計，莫如樹人。一樹一穫者，穀也；一樹十穫者，木也；一樹百穫者，人也。"], "quote": ["一年之計，莫如樹穀；十年之計，莫如樹木；終身之計，莫如樹人。一樹一穫者，穀也；一樹十穫者，木也；一樹百穫者，人也。"], "intro": "本文節選自《管子‧權修》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B8%80%E5%B9%B4%E4%B9%8B%E8%A8%88"}, {"title": "染絲", "author": "《墨子》", "period": "先秦", "form": "文", "theme": "田園幽居", "mood": "ethereal", "lines": ["子墨子言見染絲者而歎曰︰「染於蒼則蒼，染於黃則黃。所入者變，其色亦變。五入必，而已則為五色矣。故染不可不慎也。」", "非獨染絲然也，國亦有染。"], "quote": ["子墨子言見染絲者而歎曰︰「染於蒼則蒼，染於黃則黃。所入者變，其色亦變。五入必，而已則為五色矣。故染不可不慎也。」", "非獨染絲然也，國亦有染。"], "intro": "本文節選自《墨子‧所染》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9F%93%E7%B5%B2"}, {"title": "兼愛上", "author": "《墨子》", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["聖人以治天下為事者也，必知亂之所自起，焉能治之；不知亂之所自起，則不能治。譬之如醫之攻人之疾者然，必知疾之所自起，焉能攻之；不知疾之所自起，則弗能攻。治亂者何獨不然，必知亂之所自起，焉能治之；不知亂之所自起，則弗能治。", "聖人以治天下為事者也，不可不察亂之所自起。當察亂何自起？起不相愛。臣子之不孝君父，所謂亂也。子自愛不愛父，故虧父而自利；弟自愛不愛兄，故虧兄而自利；臣自愛不愛君，故虧君而自利。此所謂亂也。雖父之不慈子，兄之不慈弟，君之不慈臣，此亦天下之所謂亂也。", "父自愛也，不愛子，故虧子而自利；兄自愛也，不愛弟，故虧弟而自利；君自愛也，不愛臣，故虧臣而自利。是何也？皆起不相愛。雖至天下之為盜賊者，亦然。盜愛其室，不愛異室，故竊異室以利其室；賊愛其身，不愛人，故賊人以利其身。此何也？皆起不相愛。", "雖至大夫之相亂家、諸侯之相攻國者，亦然。大夫各愛其家，不愛異家，故亂異家以利其家；諸侯各愛其國，不愛異國，故攻異國以利其國。天下之亂物，具此而已矣。", "察此何自起？皆起不相愛。若使天下兼相愛，愛人若愛其身，猶有不孝者乎？視父兄與君若其身，惡施不孝？猶有不慈者乎？視弟子與臣若其身，惡施不慈？故不慈不孝亡有。猶有盜賊乎？故視人之室若其室，誰竊？視人身若其身，誰賊？故盜賊有亡。", "猶有大夫之相亂家、諸侯之相攻國者乎？視人家若其家，誰亂？視人國若其國，誰攻？故大夫之相亂家、諸侯之相攻國者有亡。若使天下兼相愛，國與國不相攻，家與家不相亂，盜賊無有，君臣父子皆能孝慈，若此則天下治。", "故聖人以治天下為事者，惡得不禁惡而勸愛？故天下兼相愛則治，交相惡則亂。故子墨子曰不可以不勸愛人者，此也。"], "quote": ["聖人以治天下為事者也，必知亂之所自起，焉能治之；不知亂之所自起，則不能治。譬之如醫之攻人之疾者然，必知疾之所自起，焉能攻之；不知疾之所自起，則弗能攻。治亂者何獨不然，必知亂之所自起，焉能治之；不知亂之所自起，則弗能治。", "聖人以治天下為事者也，不可不察亂之所自起。當察亂何自起？起不相愛。臣子之不孝君父，所謂亂也。子自愛不愛父，故虧父而自利；弟自愛不愛兄，故虧兄而自利；臣自愛不愛君，故虧君而自利。此所謂亂也。雖父之不慈子，兄之不慈弟，君之不慈臣，此亦天下之所謂亂也。", "父自愛也，不愛子，故虧子而自利；兄自愛也，不愛弟，故虧弟而自利；君自愛也，不愛臣，故虧臣而自利。是何也？皆起不相愛。雖至天下之為盜賊者，亦然。盜愛其室，不愛異室，故竊異室以利其室；賊愛其身，不愛人，故賊人以利其身。此何也？皆起不相愛。", "雖至大夫之相亂家、諸侯之相攻國者，亦然。大夫各愛其家，不愛異家，故亂異家以利其家；諸侯各愛其國，不愛異國，故攻異國以利其國。天下之亂物，具此而已矣。"], "intro": "本篇選自《墨子閒詁》卷四，內容探討天下相亂之源與治亂之方。墨子認為，天下之亂，「起不相愛」，因而提出治亂之方，「故聖人以治天下為事者，惡得不禁惡而勸愛」。最後歸結於「天下兼相愛則治，交相惡則亂」。總之，墨子所提倡的「兼愛」，正與儒家的「推恩", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%85%BC%E6%84%9B%E4%B8%8A"}, {"title": "侍坐章", "author": "《論語》", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "spring_breeze", "lines": ["子路、曾皙、冉有、公西華侍坐。", "子曰︰「以吾一日長乎爾，毋吾以也。居則曰︰『不吾知也！』如或知爾，則何以哉？」", "子路率爾而對曰︰「千乘之國，攝乎大國之間，加之以師旅，因之以饑饉；由也為之，比及三年，可使有勇，且知方也。」", "夫子哂之。", "「求！爾何如？」", "對曰︰「方六七十，如五六十，求也為之，比及三年，可使足民。如其禮樂，以俟君子。」", "「赤！爾何如？」", "對曰︰「非曰能之，願學焉。宗廟之事，如會同，端章甫，願為小相焉。」", "「點！爾何如？」", "鼓瑟希，鏗爾，舍瑟而作，對曰︰「異乎三子者之撰。」", "子曰︰「何傷乎？亦各言其志也。」", "曰︰「莫春者，春服既成，冠者五六人，童子六七人，浴乎沂，風乎舞雩，詠而歸。」"], "quote": ["子路、曾皙、冉有、公西華侍坐。", "子曰︰「以吾一日長乎爾，毋吾以也。居則曰︰『不吾知也！』如或知爾，則何以哉？」", "子路率爾而對曰︰「千乘之國，攝乎大國之間，加之以師旅，因之以饑饉；由也為之，比及三年，可使有勇，且知方也。」", "夫子哂之。"], "intro": "本課節選自《論語‧先進》第二十六章，版本據《先秦兩漢古籍逐字索引》。內容記述孔子與子路、曾皙、冉有及公西華討論志趣問題。四人的志趣不同，可見孔門弟子中，既有好高鶩遠的，亦有誠樸務實的，而孔子則兼容並蓄，因才施教，依學生不同的能力和興趣，給他", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%BE%8D%E5%9D%90%E7%AB%A0"}, {"title": "論仁", "author": "《論語》", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["子曰︰「不仁者，不可以久處約，不可以長處樂。仁者安仁，知者利仁。」(《里仁》第四)", "子曰︰「惟仁者能好人，能惡人。」(《里仁》第四)", "子曰︰「富與貴，是人之所欲也；不以其道得之，不處也。貧與賤，是人之所惡也；不以其道得之，不去也。君子去仁，惡乎成名？君子無終食之間違仁，造次必於是，顛沛必於是。」(《里仁》第四)", "子曰︰「知者不惑，仁者不憂，勇者不懼。」(《子罕》第九)", "顏淵問仁。子曰︰「克己復禮為仁。一日克己復禮，天下歸仁焉。為仁由己，而由人乎哉？」顏淵曰︰「請問其目。」子曰︰「非禮勿視，非禮勿聽，非禮勿言，非禮勿動。」顏淵曰︰「回雖不敏，請事斯語矣。」(《顏淵》第十二)", "樊遲問仁。子曰︰「居處恭，執事敬，與人忠。雖之夷狄，不可棄也。」(《子路》第十三)", "子曰︰「志士仁人，無求生以害仁，有殺身以成仁。」(《衞靈公》第十五)"], "quote": ["子曰︰「不仁者，不可以久處約，不可以長處樂。仁者安仁，知者利仁。」(《里仁》第四)", "子曰︰「惟仁者能好人，能惡人。」(《里仁》第四)", "子曰︰「富與貴，是人之所欲也；不以其道得之，不處也。貧與賤，是人之所惡也；不以其道得之，不去也。君子去仁，惡乎成名？君子無終食之間違仁，造次必於是，顛沛必於是。」(《里仁》第四)", "子曰︰「知者不惑，仁者不憂，勇者不懼。」(《子罕》第九)"], "intro": "現存《論語》共二十篇，主要以「語錄體」的形式記錄孔子的教誨和與弟子的對話，也有孔子弟子之間或與其他人的對話。 孔子的核心思想是「仁」，「仁」一詞在孔子之前已有，是眾多德行其中一項，而孔子把「仁」提升到更高層次，把「仁」看作其他一切德行的根本", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%AB%96%E4%BB%81"}, {"title": "論君子", "author": "《論語》", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["子曰︰「君子恥其言而過其行。」（《憲問》第十四）", "子貢問君子。", "子曰︰「先行其言而後從之。」（《為政》第二）", "子曰︰「君子欲訥於言而敏於行。」（《里仁》第四）", "子曰︰「君子義以為質，禮以行之，孫以出之，信以成之。君子哉！」（《衞靈公》第十五）", "子曰︰「君子之於天下也，無適也，無莫也，義之與比。」（《里仁》第四）", "子曰︰「君子不重則不威；學則不固。主忠信；無友不如己者；過則勿憚改。」（《學而》第一）", "子曰︰「君子病無能焉，不病人之不己知也。」（《衞靈公》第十五）", "司馬牛問君子。", "子曰︰「君子不憂不懼。」", "曰︰「不憂不懼，斯謂之君子已乎？」", "子曰︰「內省不疚，夫何憂何懼！」（《顏淵》第十二）"], "quote": ["子曰︰「君子恥其言而過其行。」（《憲問》第十四）", "子貢問君子。", "子曰︰「先行其言而後從之。」（《為政》第二）", "子曰︰「君子欲訥於言而敏於行。」（《里仁》第四）"], "intro": "本文是選集《論語》中所有有關論君子的章節而成，共十五則，各於文下註明所採篇名，故標今題。所謂「君子」，乃指有高度道德修養，或在政治上社會上能成為完善而可為標準的人而言；亦即孔子認為學者應該努力達成的一種理想的人格。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%AB%96%E5%90%9B%E5%AD%90"}, {"title": "論孝", "author": "《論語》", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["孟武伯問孝。", "子曰︰「父母唯其疾之憂。」（「為政」第二）", "子游問孝。", "子曰︰「今之孝者，是謂能養；至於犬馬，皆能有養；不敬，何以別乎！」（「為政」第二）", "子夏問孝。", "子曰︰「色難。有事，弟子服其勞；有酒食，先生饌，曾是以為孝乎？」（「為政」第二）", "孟懿子問孝。", "子曰︰「毋違？」", "樊遲御，子告之曰︰「孟孫問孝於我，我對曰︰『毋違』。」", "樊遲曰︰「何謂也？」", "子曰︰「生，事之以禮；死，葬之以禮，祭之以禮。」（「為政」第二）", "宰我問三年之喪︰「期已久矣！君子三年不為禮，禮必壞；三年不為樂，樂必崩。舊穀既沒，新穀既升；鑽燧改火，期可已矣。」"], "quote": ["孟武伯問孝。", "子曰︰「父母唯其疾之憂。」（「為政」第二）", "子游問孝。", "子曰︰「今之孝者，是謂能養；至於犬馬，皆能有養；不敬，何以別乎！」（「為政」第二）"], "intro": "本篇共五則，皆從《論語》中選出，以其內容皆為論孝，故標今題。孔子自己說，他是「述而不作，信而好古」（見《論語・述而》篇）的，所以他一生未曾自己著書。後人能知道他的思想言行，研究他的學說，討論他的人格，全賴一部《論語》。這書內容包括：一、孔子", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%AB%96%E5%AD%9D"}, {"title": "三人成虎", "author": "《戰國策》", "period": "先秦", "form": "文", "theme": "田園幽居", "mood": "ethereal", "lines": ["龐葱與太子質於邯鄲。謂魏王曰︰「今一人言市有虎，王信之乎？」王曰︰「否。」「二人言市有虎，王信之乎？」王曰︰「寡人疑之矣。」「三人言市有虎，王信之乎？」王曰︰「寡人信之矣。」龐葱曰︰「夫市之無虎明矣，然而三人言而成虎。今邯鄲去大梁也遠於市，而議臣者過於三人矣，願王察之也！」王曰︰「寡人自為知。」於是辭行，而讒言先至。", "後太子罷質，果不得見。"], "quote": ["龐葱與太子質於邯鄲。謂魏王曰︰「今一人言市有虎，王信之乎？」王曰︰「否。」「二人言市有虎，王信之乎？」王曰︰「寡人疑之矣。」「三人言市有虎，王信之乎？」王曰︰「寡人信之矣。」龐葱曰︰「夫市之無虎明矣，然而三人言而成虎。今邯鄲去大梁也遠於市，而議臣者過於三人矣，願王察之也！」王曰︰「寡人自為知。」於是辭行，而讒言先至。", "後太子罷質，果不得見。"], "intro": "本文選自《戰國策‧魏策（二）》，《韓非子‧內儲說（上）》所記略同。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B8%89%E4%BA%BA%E6%88%90%E8%99%8E"}, {"title": "鄒忌諷齊王納諫", "author": "《戰國策》", "period": "先秦", "form": "文", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["鄒忌脩八尺有餘，身體昳麗。朝服衣冠窺鏡，謂其妻曰︰「我孰與城北徐公美？」其妻曰︰「君美甚，徐公何能及君也！」城北徐公，齊國之美麗者也。", "忌不自信，而復問其妾曰︰「吾孰與徐公美！」妾曰︰「徐公何能及君也！」旦日，客從外來，與坐談，問之客曰︰「吾與徐公孰美？」客曰︰「徐公不若君之美也！」", "明日，徐公來，孰視之，自以為不如；窺鏡而自視，又弗如遠甚。暮，寢而思之曰︰「吾妻之美我者，私我也；妾之美我者，畏我也；客之美我者，欲有求於我也。」", "於是入朝見威王曰︰「臣誠知不如徐公美。臣之妻私臣，臣之妾畏臣，臣之客欲有求於臣，皆以美於徐公。今齊地方千里，百二十城，宮婦左右莫不私王；朝廷之臣，莫不畏王；四境之內，莫不有求於王。由此觀之，王之蔽甚矣！」", "王曰︰「善。」乃下令︰「群臣吏民，能面刺寡人之過者，受上賞；上書諫寡人者，受中賞；能謗議於市朝，聞寡人之耳者，受下賞。」", "令初下，群臣進諫，門庭若市。數月之後，時時而間進。期年之後，雖欲言，無可進者。燕、趙、韓、魏聞之，皆朝於齊。此所謂戰勝於朝廷。"], "quote": ["鄒忌脩八尺有餘，身體昳麗。朝服衣冠窺鏡，謂其妻曰︰「我孰與城北徐公美？」其妻曰︰「君美甚，徐公何能及君也！」城北徐公，齊國之美麗者也。", "忌不自信，而復問其妾曰︰「吾孰與徐公美！」妾曰︰「徐公何能及君也！」旦日，客從外來，與坐談，問之客曰︰「吾與徐公孰美？」客曰︰「徐公不若君之美也！」", "明日，徐公來，孰視之，自以為不如；窺鏡而自視，又弗如遠甚。暮，寢而思之曰︰「吾妻之美我者，私我也；妾之美我者，畏我也；客之美我者，欲有求於我也。」", "於是入朝見威王曰︰「臣誠知不如徐公美。臣之妻私臣，臣之妾畏臣，臣之客欲有求於臣，皆以美於徐公。今齊地方千里，百二十城，宮婦左右莫不私王；朝廷之臣，莫不畏王；四境之內，莫不有求於王。由此觀之，王之蔽甚矣！」"], "intro": "本文選自《戰國策‧齊策》，版本據《先秦兩漢古籍逐字索引》，題目為後人所加。鄒忌，生卒年不詳。戰國時齊國人，善鼓琴，有辯才，曾為齊相。諷，用含蓄的話勸告或譏刺。齊王，即齊威王，在位年為周顯王十三年至周慎靚王元年（西元前三五六──前三二〇）。納", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%84%92%E5%BF%8C%E8%AB%B7%E9%BD%8A%E7%8E%8B%E7%B4%8D%E8%AB%AB"}, {"title": "蘇秦為趙合從說楚威王", "author": "《戰國策》", "period": "先秦", "form": "文", "theme": "邊塞豪放", "mood": "vast_river", "lines": ["蘇秦為趙合從，說楚威王曰︰「楚，天下之強國也。大王，天下之賢王也。楚地西有黔中、巫郡，東有夏州、海陽，南有洞庭、蒼梧，北有汾陘之塞、郇陽。地方五千里，帶甲百萬，車千乘，騎萬匹，粟支十年，此霸王之資也。夫以楚之強，與大王之賢，天下莫能當也。今乃欲西面而事秦，則諸侯莫不南面而朝於章臺之下矣。秦之所害，於天下莫如楚，楚強則秦弱，楚弱則秦強，此其勢不兩立。故為王至計，莫如從親以孤秦。大王不從親，秦必起兩軍︰一軍出武關；一軍下黔中。若此，則鄢郢動矣。臣聞治之其未亂，為之其未有也；患至而後憂之，則無及已。故願大王之早計之。」", "「大王誠能聽臣，臣請令山東之國，奉四時之獻，以承大王之明制，委社稷宗廟，練士厲兵，在大王之所用之。大王誠能聽臣之愚計，則韓魏齊燕趙衛之妙音美人，必充後宮矣。趙代良馬橐他，必實於外廄。故從合則楚王，橫成則秦帝。今釋霸王之業，而有事人之名，臣竊為大王不取也。」", "「夫秦，虎狼之國也，有吞天下之心。秦，天下之仇讎也，橫人皆欲割諸侯之地以事秦，此所謂養仇而奉讐者也。夫為人臣而割其主之地，以外交強虎狼之秦，以侵天下，卒有秦患，不顧其禍。夫外挾強秦之威，以內劫其主，以求割地，大逆不忠，無過此者。故從親，則諸侯割地以事楚；橫合，則楚割地以事秦。此兩策者，相去遠矣，有億兆之數。兩者大王何居焉？故弊邑趙王，使臣效愚計，奉明約，在大王命之。」", "楚王曰︰「寡人之國，西與秦接境，秦有舉巴蜀、并漢中之心。秦，虎狼之國，不可親也。而韓、魏迫於秦患，不可與深謀，恐反人以入於秦，故謀未發而國已危矣。寡人自料，以楚當秦，未見勝焉。內與群臣謀，不足恃也。寡人臥不安席，食不甘味，心搖搖如懸旌，而無所終薄。今君欲一天下，安諸侯，存危國，寡人謹奉社稷以從。」"], "quote": ["蘇秦為趙合從，說楚威王曰︰「楚，天下之強國也。大王，天下之賢王也。楚地西有黔中、巫郡，東有夏州、海陽，南有洞庭、蒼梧，北有汾陘之塞、郇陽。地方五千里，帶甲百萬，車千乘，騎萬匹，粟支十年，此霸王之資也。夫以楚之強，與大王之賢，天下莫能當也。今乃欲西面而事秦，則諸侯莫不南面而朝於章臺之下矣。秦之所害，於天下莫如楚，楚強則秦弱，楚弱則秦強，此其勢不兩立。故為王至計，莫如從親以孤秦。大王不從親，秦必起兩軍︰一軍出武關；一軍下黔中。若此，則鄢郢動矣。臣聞治之其未亂，為之其未有也；患至而後憂之，則無及已。故願大王之早計之。」", "「大王誠能聽臣，臣請令山東之國，奉四時之獻，以承大王之明制，委社稷宗廟，練士厲兵，在大王之所用之。大王誠能聽臣之愚計，則韓魏齊燕趙衛之妙音美人，必充後宮矣。趙代良馬橐他，必實於外廄。故從合則楚王，橫成則秦帝。今釋霸王之業，而有事人之名，臣竊為大王不取也。」", "「夫秦，虎狼之國也，有吞天下之心。秦，天下之仇讎也，橫人皆欲割諸侯之地以事秦，此所謂養仇而奉讐者也。夫為人臣而割其主之地，以外交強虎狼之秦，以侵天下，卒有秦患，不顧其禍。夫外挾強秦之威，以內劫其主，以求割地，大逆不忠，無過此者。故從親，則諸侯割地以事楚；橫合，則楚割地以事秦。此兩策者，相去遠矣，有億兆之數。兩者大王何居焉？故弊邑趙王，使臣效愚計，奉明約，在大王命之。」", "楚王曰︰「寡人之國，西與秦接境，秦有舉巴蜀、并漢中之心。秦，虎狼之國，不可親也。而韓、魏迫於秦患，不可與深謀，恐反人以入於秦，故謀未發而國已危矣。寡人自料，以楚當秦，未見勝焉。內與群臣謀，不足恃也。寡人臥不安席，食不甘味，心搖搖如懸旌，而無所終薄。今君欲一天下，安諸侯，存危國，寡人謹奉社稷以從。」"], "intro": "本文選自《戰國策‧楚策一‧卷十四》。並見《史記‧蘇秦張儀列傳》。 蘇秦（？——公元前284）學於齊，師事鬼谷子。遊歷多年，窮困潦倒，狼狽而回。家人盡訕笑之。遂伏案《陰符》，得悟合從（縱）連橫之術，以此游說。 蘇秦首先求見周顯王。但顯王的大臣", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%98%87%E7%A7%A6%E7%82%BA%E8%B6%99%E5%90%88%E5%BE%9E%E8%AA%AA%E6%A5%9A%E5%A8%81%E7%8E%8B%C2%A0"}, {"title": "鷸蚌相爭", "author": "《戰國策》", "period": "先秦", "form": "文", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["蚌方出曝，而鷸啄其肉。蚌合而拑其喙。鷸曰︰「今日不雨，明日不雨，即有死蚌。」蚌亦謂鷸曰︰「今日不出，明日不出，即有死鷸。」兩者不肯相舍，漁者得而并擒之。"], "quote": ["蚌方出曝，而鷸啄其肉。蚌合而拑其喙。鷸曰︰「今日不雨，明日不雨，即有死蚌。」蚌亦謂鷸曰︰「今日不出，明日不出，即有死鷸。」兩者不肯相舍，漁者得而并擒之。"], "intro": "戰國時期，秦國常常依靠強大的國力，侵略別的國家，其他各國也常常互相攻伐。一年，趙國準備攻打燕國，燕國聽到風聲後，急忙派說客蘇代到趙國說情，勸趙國休兵。蘇代到了趙國後，就對趙王說了「鷸蚌相爭」的故事。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%B7%B8%E8%9A%8C%E7%9B%B8%E7%88%AD"}, {"title": "大同與小康", "author": "《禮記》", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "heroic", "lines": ["昔者，仲尼與於蜡賓，事畢，出遊於觀之上，喟然而歎。仲尼之歎，蓋歎魯也。言偃在側，曰︰「君子何歎？」", "孔子曰︰「大道之行也，與三代之英，丘未之逮也，而有志焉。大道之行也，天下為公︰選賢與能，講信修睦。故人不獨親其親，不獨子其子；使老有所終，壯有所用，幼有所長，矜、寡、孤、獨，廢疾者皆有所養；男有分，女有歸。", "貨，惡其棄於地也，不必藏於己；力，惡其不出於身也，不必為己。是故謀閉而不興，盜竊亂賊而不作，故外戶而不閉。是謂『大同』。", "「今大道既隱，天下為家︰各親其親，各子其子；貨力為己；大人世及以為禮；城郭溝池以為固；禮義以為紀——以正君臣，以篤父子，以睦兄弟，以和夫婦；以設制度，以立田里；以賢勇知，以功為已。故謀用是作而兵由此起。", "禹、湯、文、武、成王、周公，由此其選也。此六君子者，未有不謹於禮者也。以著其義，以考其信，著有過，刑仁，講讓、示民有常。如有不由此者，在埶者去，眾以為殃。是謂『小康』。」"], "quote": ["昔者，仲尼與於蜡賓，事畢，出遊於觀之上，喟然而歎。仲尼之歎，蓋歎魯也。言偃在側，曰︰「君子何歎？」", "孔子曰︰「大道之行也，與三代之英，丘未之逮也，而有志焉。大道之行也，天下為公︰選賢與能，講信修睦。故人不獨親其親，不獨子其子；使老有所終，壯有所用，幼有所長，矜、寡、孤、獨，廢疾者皆有所養；男有分，女有歸。", "貨，惡其棄於地也，不必藏於己；力，惡其不出於身也，不必為己。是故謀閉而不興，盜竊亂賊而不作，故外戶而不閉。是謂『大同』。", "「今大道既隱，天下為家︰各親其親，各子其子；貨力為己；大人世及以為禮；城郭溝池以為固；禮義以為紀——以正君臣，以篤父子，以睦兄弟，以和夫婦；以設制度，以立田里；以賢勇知，以功為已。故謀用是作而兵由此起。"], "intro": "本文為《禮記・禮運篇》裏的第一章，是記載孔子告訴言偃有關五帝、三代政治的話。那時孔子正在魯國做官，陪着魯君致祭蜡廟，看到魯君所行的祭禮不合於古，不禁興歎，因此才引出他對於古代政治的嚮往，而暢發他對治國平天下的議論。照篇中所說，孔子以五帝之治", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%A4%A7%E5%90%8C%E8%88%87%E5%B0%8F%E5%BA%B7"}, {"title": "大學（節錄）", "author": "《禮記》", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["大學之道，在明明德，在親民，在止於至善。", "知止而后有定，定而后能靜，靜而后能安，安而后能慮，慮而后能得。物有本末，事有終始，知所先後，則近道矣。", "古之欲明明德於天下者，先治其國；欲治其國者，先齊其家；欲齊其家者，先脩其身；欲脩其身者，先正其心；欲正其心者，先誠其意；欲誠其意者，先致其知，致知在格物。", "物格而后知至，知至而后意誠，意誠而后心正，心正而后身脩，身脩而后家齊，家齊而后國治，國治而后天下平。", "自天子以至於庶人，壹是皆以脩身為本。其本亂而末治者，否矣，其所厚者薄，而其所薄者厚，未之有也！"], "quote": ["大學之道，在明明德，在親民，在止於至善。", "知止而后有定，定而后能靜，靜而后能安，安而后能慮，慮而后能得。物有本末，事有終始，知所先後，則近道矣。", "古之欲明明德於天下者，先治其國；欲治其國者，先齊其家；欲齊其家者，先脩其身；欲脩其身者，先正其心；欲正其心者，先誠其意；欲誠其意者，先致其知，致知在格物。", "物格而后知至，知至而后意誠，意誠而后心正，心正而后身脩，身脩而后家齊，家齊而后國治，國治而后天下平。"], "intro": "《大學》本為《小戴禮記》中之一篇。東漢鄭玄有註，唐孔穎達有疏；但尚未成為獨立的專書。到了北宋，司馬光作《大學廣義》一卷，又作《致知在格物論》一卷，始將《大學》從《禮記》中分出來作獨立的講說。稍後，程顥以為《大學》是孔子的遺書，是所謂「初學入", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%A4%A7%E5%AD%B8%EF%BC%88%E7%AF%80%E9%8C%84%EF%BC%89"}, {"title": "中庸（第一章及第十四章）", "author": "《禮記》", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["第一章", "天命之謂性，率性之謂道，修道之謂教。道也者，不可須臾離也；可離，非道也。", "是故，君子戒慎乎其所不睹，恐懼乎其所不聞。莫見乎隱，莫顯乎微，故君子慎其獨也。", "喜怒哀樂之未發，謂之中；發而皆中節，謂之和。中也者，天下之大本也；和也者，天下之達道也。致中和，天地位焉，萬物育焉。", "第十四章", "君子素其位而行，不願乎其外。素富貴，行乎富貴；素貧賤，行乎貧賤；素夷狄，行乎夷狄；素患難，行乎患難。君子無入而不自得焉！", "在上位不陵下；在下位不援上，正己而不求於人，則無怨；上不怨天，下不尤人。故君子居易以俟命，小人行險以徼幸。", "子曰︰「射有似乎君子，失諸正鵠，反求諸其身。」"], "quote": ["第一章", "天命之謂性，率性之謂道，修道之謂教。道也者，不可須臾離也；可離，非道也。", "是故，君子戒慎乎其所不睹，恐懼乎其所不聞。莫見乎隱，莫顯乎微，故君子慎其獨也。", "喜怒哀樂之未發，謂之中；發而皆中節，謂之和。中也者，天下之大本也；和也者，天下之達道也。致中和，天地位焉，萬物育焉。"], "intro": "本文錄自《禮記‧中庸第三十一》。《中庸》一篇，於《禮記》不分章節。南宋淳熙四年撫州台使庫刻《禮記》鄭玄注二十卷本，《中庸》在卷十六，不分卷，亦不分章節。唐孔穎達《禮記正義》，現時通行本為清代阮元校刻六十三卷本，《中庸》在卷五十二（止於「道前", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B8%AD%E5%BA%B8%EF%BC%88%E7%AC%AC%E4%B8%80%E7%AB%A0%E5%8F%8A%E7%AC%AC%E5%8D%81%E5%9B%9B%E7%AB%A0%EF%BC%89%C2%A0"}, {"title": "苛政猛於虎", "author": "《禮記》", "period": "先秦", "form": "文", "theme": "山水登臨", "mood": "majestic_peaks", "lines": ["孔子過泰山側，有婦人哭於墓者而哀。夫子式而聽之。使子貢問之曰︰「子之哭也，壹似重有憂者。」而曰︰「然，昔者吾舅死於虎，吾夫又死焉，今吾子又死焉。」", "夫子曰︰「為何不去也？」曰︰「無苛政。」夫子曰︰「小子識之，苛政猛於虎也！」"], "quote": ["孔子過泰山側，有婦人哭於墓者而哀。夫子式而聽之。使子貢問之曰︰「子之哭也，壹似重有憂者。」而曰︰「然，昔者吾舅死於虎，吾夫又死焉，今吾子又死焉。」", "夫子曰︰「為何不去也？」曰︰「無苛政。」夫子曰︰「小子識之，苛政猛於虎也！」"], "intro": "本課節選自《禮記‧檀弓下》，現題為編者所加，版本據《先秦兩漢古籍逐字索引》。本文從婦人口中記述了一家三代慘死於虎口的厄運，並說明她仍不願離開的原因，在於此地沒有苛政，突出了「苛政猛於虎」的主題。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%8B%9B%E6%94%BF%E7%8C%9B%E6%96%BC%E8%99%8E"}, {"title": "五蠹（節錄）", "author": "韓非", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["上古之世，人民少而禽獸眾，人民不勝禽獸蟲蛇；有聖人作，搆木為巢以避羣害，而民悅之，使王天下，號之曰有巢氏。民食果蓏蜯蛤，腥臊惡臭而傷害腹胃，民多疾病；有聖人作，鑽燧取火，以化腥臊，而民說之，使王天下，號之曰燧人氏。", "中古之世，天下大水，而鯀、禹決瀆。近古之世，桀、紂暴亂，而湯、武征伐。今有搆木鑽燧於夏后氏之世者，必為鯀、禹笑矣；有決瀆於殷、周之世者，必為湯、武笑矣。然則今有美堯、舜、湯、武、禹之道於當今之世者，必為新聖笑矣。", "是以聖人不期脩古，不法常可，論世之事，因為之備。宋人有耕者，田中有株，兔走觸株，折頸而死；因釋其耒而守株，冀復得兔，兔不可復得，而身為宋國笑。今欲以先王之政，治當世之民，皆守株之類也。", "古者丈夫不耕，草木之實足食也；婦人不織，禽獸之皮足衣也。不事力而養足，人民少而財有餘，故民不爭。是以厚賞不行，重罰不用，而民自治。", "今人有五子不為多，子又有五子，大父未死而有二十五孫。是以人民眾而貨財寡，事力勞而供養薄，故民爭；雖倍賞累罰而不免於亂。", "堯之王天下也，茅茨不翦，采椽不斲；糲粢之食，藜藿之羹；冬日麑裘，夏日葛衣︰雖監門之服養，不虧於此矣。禹之王天下也，身執耒臿，以為民先；股無胈，脛不生毛︰雖臣虜之勞不苦於此矣。", "以是言之，夫古之讓天子者，是去監門之養而離臣虜之勞也，古傳天下而不足多也。今之縣令，一日身死，子孫累世絜駕，故人重之。是以人之於讓也，輕辭古之天子，難去今之縣令者，薄厚之實異也。夫山居而谷汲者，膢臘而相遺以水；澤居苦水者，買庸而決竇。", "故饑歲之春，幼弟不饟；穰歲之秋，疏客必食。非疏骨肉，愛過客也，多少之實異也。是以古之易財，非仁也，財多也；今之爭奪，非鄙也，財寡也。輕辭天子，非高也，勢薄也；重爭土橐，非下也，權重也。", "故聖人議多少、論薄厚為之政。故罰薄不為慈，誅嚴不為戾，稱俗而行也。故事因於世，而備適於事。"], "quote": ["上古之世，人民少而禽獸眾，人民不勝禽獸蟲蛇；有聖人作，搆木為巢以避羣害，而民悅之，使王天下，號之曰有巢氏。民食果蓏蜯蛤，腥臊惡臭而傷害腹胃，民多疾病；有聖人作，鑽燧取火，以化腥臊，而民說之，使王天下，號之曰燧人氏。", "中古之世，天下大水，而鯀、禹決瀆。近古之世，桀、紂暴亂，而湯、武征伐。今有搆木鑽燧於夏后氏之世者，必為鯀、禹笑矣；有決瀆於殷、周之世者，必為湯、武笑矣。然則今有美堯、舜、湯、武、禹之道於當今之世者，必為新聖笑矣。", "是以聖人不期脩古，不法常可，論世之事，因為之備。宋人有耕者，田中有株，兔走觸株，折頸而死；因釋其耒而守株，冀復得兔，兔不可復得，而身為宋國笑。今欲以先王之政，治當世之民，皆守株之類也。", "古者丈夫不耕，草木之實足食也；婦人不織，禽獸之皮足衣也。不事力而養足，人民少而財有餘，故民不爭。是以厚賞不行，重罰不用，而民自治。"], "intro": "本文節選自《韓非子集解》卷十九，是韓非論帝王治術的代表作之一。蠹（粤：[到dou3]；普：[dù]。），即蛀蟲。五蠹，比喻危害社會的五類人：儒家的學者、縱橫家的言談者、墨家支派遊俠的帶劍者、患御者和商工之民。在《五蠹》中，作者對這些人分別作", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%BA%94%E8%A0%B9%EF%BC%88%E7%AF%80%E9%8C%84%EF%BC%89"}, {"title": "守株待兔", "author": "韓非", "period": "先秦", "form": "文", "theme": "田園幽居", "mood": "ethereal", "lines": ["宋人有耕者，田中有株，兔走觸株，折頸而死，因釋其耒而守株，冀復得兔，兔不可復得，而身為宋國笑。"], "quote": ["宋人有耕者，田中有株，兔走觸株，折頸而死，因釋其耒而守株，冀復得兔，兔不可復得，而身為宋國笑。"], "intro": "本文選自《韓非子‧五蠹》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%AE%88%E6%A0%AA%E5%BE%85%E5%85%94"}, {"title": "曾子殺豬", "author": "韓非", "period": "先秦", "form": "文", "theme": "田園幽居", "mood": "ethereal", "lines": ["曾子之妻之市，其子隨之而泣。其母曰︰「女還，顧反為女殺彘。」", "妻適市來，曾子欲捕彘殺之，妻止之曰︰「特與嬰兒戲耳。」曾子曰︰「嬰兒非與戲也。嬰兒非有知也，待父母而學者也，聽父母之教。今子欺之，是教子欺也。母欺子，子而不信其母，非以成教也。」遂烹彘也。"], "quote": ["曾子之妻之市，其子隨之而泣。其母曰︰「女還，顧反為女殺彘。」", "妻適市來，曾子欲捕彘殺之，妻止之曰︰「特與嬰兒戲耳。」曾子曰︰「嬰兒非與戲也。嬰兒非有知也，待父母而學者也，聽父母之教。今子欺之，是教子欺也。母欺子，子而不信其母，非以成教也。」遂烹彘也。"], "intro": "本文選自《韓非子‧外儲說左（上）》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9B%BE%E5%AD%90%E6%AE%BA%E8%B1%AC"}, {"title": "買櫝還珠", "author": "韓非", "period": "先秦", "form": "文", "theme": "田園幽居", "mood": "ethereal", "lines": ["楚人有賣其珠於鄭者，為木蘭之櫃，薰以桂椒，綴以珠玉，飾以玫瑰，輯以羽翠，鄭人買其櫝而還其珠。此可謂善賣櫝矣，未可謂善鬻珠也。"], "quote": ["楚人有賣其珠於鄭者，為木蘭之櫃，薰以桂椒，綴以珠玉，飾以玫瑰，輯以羽翠，鄭人買其櫝而還其珠。此可謂善賣櫝矣，未可謂善鬻珠也。"], "intro": "本文選自《韓非子‧外儲說左（上）》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B2%B7%E6%AB%9D%E9%82%84%E7%8F%A0"}, {"title": "說難", "author": "韓非", "period": "先秦", "form": "文", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["凡說之難，非吾知之有以說之之難也，又非吾辯之能明吾意之難也，又非吾敢橫失而能盡之難也。凡說之難，在知所說之心，可以吾說當之。所說出於為名高者也，而說之以厚利，則見下節而遇卑賤，必棄遠矣。", "所說出於厚利者也，而說之以名高，則見無心而遠事情，必不收矣。所說陰為厚利而顯為名高者也，而說之以名高，則陽收其身而實疏之；說之以厚利，則陰用其言顯棄其身矣。此不可不察也。", "夫事以密成，語以泄敗。未必其身泄之也，而語及所匿之事，如此者身危。彼顯有所出事，而乃以成他故，說者不徒知所出而已矣，又知其所以為，如此者身危。規異事而當，知者揣之外而得之，事泄於外，必以為己也，如此者身危。", "周澤未渥也，而語極知，說行而有功，則德忘；說不行而有敗，則見疑，如此者身危。貴人有過端，而說者明言禮義以挑其惡，如此者身危。貴人或得計而欲自以為功，說者與知焉，如此者身危。強以其所不能為，止以其所不能已，如此者身危。故與之論大人，則以為間己矣；與之論細人，則以為賣重。", "論其所愛，則以為藉資；論其所憎，則以為嘗己也。徑省其說，則以為不智而拙之；米鹽博辯，則以為多而交之。略事陳意，則曰怯懦而不盡；慮事廣肆，則曰草野而倨侮。此說之難，不可不知也。", "凡說之務，在知飾所說之所矜而滅其所恥。彼有私急也，必以公義示而強之。其意有下也，然而不能已，說者因為之飾其美而少其不為也。其心有高也，而實不能及，說者為之舉其過而見其惡，而多其不行也。", "有欲矜以智能，則為之舉異事之同類者，多為之地，使之資說於我，而佯不知也，以資其智。欲內相存之言，則必以美名明之，而微見其合於私利也。欲陳危害之事，則顯其毀誹而微見其合於私患也。", "譽異人與同行者，規異事與同計者。有與同污者，則必以大飾其無傷也；有與同敗者，則必以明飾其無失也。彼自多其力，則毋以其難概之也；自勇其斷，則無以其謫怒之；自智其計，則毋以其敗窮之。大意無所拂悟，辭言無所繫縻，然後極騁智辯焉。此道所得親近不疑而得盡辭也。", "伊尹為宰，百里奚為虜，皆所以干其上也。此二人者，皆聖人也，然猶不能無役身以進，如此其污也。今以吾言為宰虜，而可以聽用而振世，此非能仕之所恥也。夫曠日離久，而周澤既渥，深計而不疑，引爭而不罪，則明割利害以致其功，直指是非以飾其身，以此相持，此說之成也。", "昔者鄭武公欲伐胡，故先以其女妻胡君以娛其意。因問於群臣︰「吾欲用兵，誰可伐者？」大夫關其思對曰︰「胡可伐。」武公怒而戮之，曰︰「胡，兄弟之國也。子言伐之，何也？」胡君聞之，以鄭為親己，遂不備鄭。鄭人襲胡，取之。", "宋有富人，天雨牆壞。其子曰︰「不築，必將有盜。」其鄰人之父亦云。暮而果大亡其財，其家甚智其子，而疑鄰人之父。此二人說者皆當矣，厚者為戮，薄者見疑，則非知之難也，處知則難也。故繞朝之言當矣，其為聖人於晉，而為戮於秦也，此不可不察。", "昔者彌子瑕有寵於衛君。衛國之法，竊駕君車者罪刖。彌子瑕母病，人間往夜告彌子，彌子矯駕君車以出。君聞而賢之，曰︰「孝哉！為母之故，忘其刖罪。」異日，與君遊於果園，食桃而甘，不盡，以其半啖君。"], "quote": ["凡說之難，非吾知之有以說之之難也，又非吾辯之能明吾意之難也，又非吾敢橫失而能盡之難也。凡說之難，在知所說之心，可以吾說當之。所說出於為名高者也，而說之以厚利，則見下節而遇卑賤，必棄遠矣。", "所說出於厚利者也，而說之以名高，則見無心而遠事情，必不收矣。所說陰為厚利而顯為名高者也，而說之以名高，則陽收其身而實疏之；說之以厚利，則陰用其言顯棄其身矣。此不可不察也。", "夫事以密成，語以泄敗。未必其身泄之也，而語及所匿之事，如此者身危。彼顯有所出事，而乃以成他故，說者不徒知所出而已矣，又知其所以為，如此者身危。規異事而當，知者揣之外而得之，事泄於外，必以為己也，如此者身危。", "周澤未渥也，而語極知，說行而有功，則德忘；說不行而有敗，則見疑，如此者身危。貴人有過端，而說者明言禮義以挑其惡，如此者身危。貴人或得計而欲自以為功，說者與知焉，如此者身危。強以其所不能為，止以其所不能已，如此者身危。故與之論大人，則以為間己矣；與之論細人，則以為賣重。"], "intro": "司馬遷《史記》載：「非見韓之削弱，數以書諫韓王，韓王不能用。於是韓非疾治國不務修明其法制，執勢以御其臣下，富國彊兵而以求人任賢，反舉浮淫之蠹而加之於功實之上。以為儒者用文亂法，而俠者以武犯禁。寬則寵名譽之人，急則用介胄之士。今者所養非所用，", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%AA%AA%E9%9B%A3"}, {"title": "鄭人買履", "author": "韓非", "period": "先秦", "form": "文", "theme": "送別行旅", "mood": "ethereal", "lines": ["鄭人有且置履者，先自度其足而置之其坐。至之市，而忘操之，已得履，乃曰︰「吾忘持度。」反歸取之，及反，市罷，遂不得履。人曰︰「何不試之以足？」曰︰「寧信度，無自信也。」"], "quote": ["鄭人有且置履者，先自度其足而置之其坐。至之市，而忘操之，已得履，乃曰︰「吾忘持度。」反歸取之，及反，市罷，遂不得履。人曰︰「何不試之以足？」曰︰「寧信度，無自信也。」"], "intro": "", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%84%AD%E4%BA%BA%E8%B2%B7%E5%B1%A5"}, {"title": "孫叔敖埋兩頭蛇", "author": "王充", "period": "漢", "form": "文", "theme": "送別行旅", "mood": "ethereal", "lines": ["孫叔敖為兒之時，見兩頭蛇，殺而埋之。歸對其母泣，母問其故，對曰︰「我聞見兩頭蛇死；向者出見兩頭蛇，恐去母死，是以泣也。」其母曰︰「今蛇何在？」對曰︰「我恐後人見之，即殺而埋之。」其母曰︰「吾聞有陰德者，天必報之，汝必不死，天必報汝。」叔敖竟不死，遂為楚相。"], "quote": ["孫叔敖為兒之時，見兩頭蛇，殺而埋之。歸對其母泣，母問其故，對曰︰「我聞見兩頭蛇死；向者出見兩頭蛇，恐去母死，是以泣也。」其母曰︰「今蛇何在？」對曰︰「我恐後人見之，即殺而埋之。」其母曰︰「吾聞有陰德者，天必報之，汝必不死，天必報汝。」叔敖竟不死，遂為楚相。"], "intro": "本篇選自《論衡》卷六《福虛篇》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%AD%AB%E5%8F%94%E6%95%96%E5%9F%8B%E5%85%A9%E9%A0%AD%E8%9B%87"}, {"title": "生年不滿百", "author": "古詩十九首", "period": "漢", "form": "詩", "theme": "送別行旅", "mood": "ethereal", "lines": ["生年不滿百，常懷千歲憂。", "晝短苦夜長，何不秉燭遊？", "為樂當及時，何能待來茲？", "愚者愛惜費，但為後世嗤。", "仙人王子喬，難可與等期。"], "quote": ["生年不滿百，常懷千歲憂。", "晝短苦夜長，何不秉燭遊？", "為樂當及時，何能待來茲？", "愚者愛惜費，但為後世嗤。"], "intro": "《生年不滿百》是「古詩十九首」的第十五首，抒寫在亂世中對生命的省思。「古詩十九首」的作者已不可考，後人從詩中表現的感情、所反映的生活和寫作的技巧，總結認為這些詩歌應是東漢末年（約140——190年）的作品。而且，這些作品與樂府民歌有別，應出", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%94%9F%E5%B9%B4%E4%B8%8D%E6%BB%BF%E7%99%BE"}, {"title": "行行重行行", "author": "古詩十九首", "period": "漢", "form": "詩", "theme": "送別行旅", "mood": "autumn_sunset", "lines": ["行行重行行，與君生別離，相去萬餘里，各在天一涯。", "道路阻且長，會面安可知。胡馬依北風，越鳥巢南枝。", "相去日已遠，衣帶日已緩。浮雲蔽白日，遊子不顧反。", "思君令人老，歲月忽已晚，棄捐勿復道，努力加餐飯。"], "quote": ["行行重行行，與君生別離，相去萬餘里，各在天一涯。", "道路阻且長，會面安可知。胡馬依北風，越鳥巢南枝。", "相去日已遠，衣帶日已緩。浮雲蔽白日，遊子不顧反。", "思君令人老，歲月忽已晚，棄捐勿復道，努力加餐飯。"], "intro": "《行行重行行》是「古詩十九首」的第一首，抒寫家中思婦對遠行丈夫思念眷戀的複雜感情。「古詩十九首」的作者已不可考，後人從詩中表現的感情、所反映的生活和寫作的技巧，總結認為這些詩歌應是東漢末年（約140──190年）的作品。而且，這些作品與樂府", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A1%8C%E8%A1%8C%E9%87%8D%E8%A1%8C%E8%A1%8C"}, {"title": "西北有高樓", "author": "古詩十九首", "period": "漢", "form": "詩", "theme": "春水花鳥", "mood": "ethereal", "lines": ["西北有高樓，上與浮雲齊；交疏結綺窗，阿閣三重階。", "上有絃歌聲，音響一何悲；誰能為此曲？無乃杞梁妻。", "清商隨風發，中曲正徘徊；一彈再三歎，慷慨有餘哀。", "不惜歌者苦，但傷知音稀！願為雙鴻鵠，奮翅起高飛。"], "quote": ["西北有高樓，上與浮雲齊；交疏結綺窗，阿閣三重階。", "上有絃歌聲，音響一何悲；誰能為此曲？無乃杞梁妻。", "清商隨風發，中曲正徘徊；一彈再三歎，慷慨有餘哀。", "不惜歌者苦，但傷知音稀！願為雙鴻鵠，奮翅起高飛。"], "intro": "《西北有高樓》是《古詩十九首》之一，大約是東漢後期作品。東漢末年社會動盪，政治混亂，下層文人入仕無門，四處漂泊，就以筆抒寫所見社會狀況。《西北有高樓》的作者，大概是失意的文人，路過西北面的一座高樓，聽到有人彈奏悲傷的曲調，引起自己的一番感觸", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A5%BF%E5%8C%97%E6%9C%89%E9%AB%98%E6%A8%93"}, {"title": "迢迢牽牛星", "author": "古詩十九首", "period": "漢", "form": "詩", "theme": "送別行旅", "mood": "vast_river", "lines": ["迢迢牽牛星，皎皎河漢女。纖纖擢素手，札札弄機杼。", "終日不成章，泣涕零如雨。河漢清且淺，相去復幾許？", "盈盈一水間，脈脈不得語。"], "quote": ["迢迢牽牛星，皎皎河漢女。纖纖擢素手，札札弄機杼。", "終日不成章，泣涕零如雨。河漢清且淺，相去復幾許？", "盈盈一水間，脈脈不得語。"], "intro": "《迢迢牽牛星》是「古詩十九首」的第十首，借牛郎織女傳說，寫男女離別相思之情。「古詩十九首」的作者已不可考，後人從詩中表現的感情、所反映的生活和寫作的技巧，總結認為這些詩歌應是東漢末年（約140－190年）的作品。而且，這些作品與樂府民歌有別", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%BF%A2%E8%BF%A2%E7%89%BD%E7%89%9B%E6%98%9F"}, {"title": "青青河畔草", "author": "古詩十九首", "period": "漢", "form": "詩", "theme": "春水花鳥", "mood": "vast_river", "lines": ["青青河畔草，鬱鬱園中柳。", "盈盈樓上女，皎皎當窗牖；", "娥娥紅粉妝，纖纖出素手。", "昔為倡家女。今為蕩子婦；", "蕩子行不歸，空床難獨守。"], "quote": ["青青河畔草，鬱鬱園中柳。", "盈盈樓上女，皎皎當窗牖；", "娥娥紅粉妝，纖纖出素手。", "昔為倡家女。今為蕩子婦；"], "intro": "《青青河畔草》是「古詩十九首」的第二首，描寫一位獨守空闈女子的神態和心境。「古詩十九首」的作者已不可考，後人從詩中表現的感情、所反映的生活和寫作的技巧，總結認為這些詩歌應是東漢末年（約140—190年）的作品。而且，這些作品與樂府民歌有別，", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%9D%92%E9%9D%92%E6%B2%B3%E7%95%94%E8%8D%89"}, {"title": "庭中有奇樹", "author": "古詩十九首", "period": "漢", "form": "詩", "theme": "送別行旅", "mood": "spring_breeze", "lines": ["庭中有奇樹，綠葉發華滋。攀條折其榮，將以遺所思。", "馨香盈懷袖，路遠莫致之。此物何足貴？但感別經時。"], "quote": ["庭中有奇樹，綠葉發華滋。攀條折其榮，將以遺所思。", "馨香盈懷袖，路遠莫致之。此物何足貴？但感別經時。"], "intro": "《庭中有奇樹》是「古詩十九首」的第九首，表現思婦對遠行丈夫的思念。「古詩十九首」的作者已不可考，後人從詩中表現的感情、所反映的生活和寫作的技巧，總結認為這些詩歌應是東漢末年（約140──190年）的作品。而且，這些作品與樂府民歌有別，應出自", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%BA%AD%E4%B8%AD%E6%9C%89%E5%A5%87%E6%A8%B9"}, {"title": "涉江采芙蓉", "author": "古詩十九首", "period": "漢", "form": "詩", "theme": "江河湖海", "mood": "vast_river", "lines": ["涉江采芙蓉，蘭澤多芳草。", "采之欲遺誰？所思在遠道。", "還顧望舊鄉，長路漫浩浩。", "同心而離居，憂傷以終老！"], "quote": ["涉江采芙蓉，蘭澤多芳草。", "采之欲遺誰？所思在遠道。", "還顧望舊鄉，長路漫浩浩。", "同心而離居，憂傷以終老！"], "intro": "《涉江采芙蓉》是「古詩十九首」的第六首，抒寫離家遊子思念故鄉親人的感慨。「古詩十九首」的作者已不可考，後人從詩中表現的感情、所反映的生活和寫作的技巧，總結認為這些詩歌應是東漢末年（約140——190年）的作品。而且，這些作品與樂府民歌有別，", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B6%89%E6%B1%9F%E9%87%87%E8%8A%99%E8%93%89"}, {"title": "長門賦", "author": "司馬相如", "period": "漢", "form": "辭賦", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["夫何一佳人兮，步逍遙以自虞。魂踰佚而不反兮，形枯槁而獨居。言「我朝往而暮來」兮，飲食樂而忘人。心慊移而不省故兮，交得意而相親。", "伊予志之慢愚兮，懷真慤之懽心。願賜問而自進兮，得尚君之玉音。奉虛言而望誠兮，期城南之離宮。修薄具而自設兮，君曾不肯乎幸臨。", "廓獨潛而專精兮，天飄飄而疾風。登蘭臺而遙望兮，神怳怳而外淫。浮雲鬱而四塞兮，天窈窈而晝陰。雷殷殷而響起兮，聲象君之車音。飄風廻而赴閨兮，舉帷幄之襜襜；桂樹交而相紛兮，芳酷烈之誾誾。", "孔雀集而相存兮，玄猿嘯而長吟。翡翠脅翼而來萃兮，鸞鳳翔而北南。心憑噫而不舒兮，邪氣壯而攻中。", "下蘭臺而周覽兮，步從容於深宮。正殿塊以造天兮，鬱並起而穹崇。間徙倚於東廂兮，觀夫靡靡而無窮。擠玉戶以撼金鋪兮，聲噌吰而似鐘音。刻木蘭以為榱兮，飾文杏以為梁。", "羅丰茸之游樹兮，離樓梧而相撐。施瑰木之櫨欂兮，委參差以槺梁。時彷佛以物類兮，象積石之將將。五色炫以相曜兮，爛耀耀而成光。緻錯石之瓴甓兮，象瑇瑁之文章。", "張羅綺之幔帷兮，垂楚組之連綱。撫柱楣以從容兮，覽曲臺之央央。白鶴噭以哀號兮，孤雌跱於枯楊。日黃昏而望絕兮，悵獨托於空堂。", "懸明月以自照兮，徂清夜於洞房。援雅琴以變調兮，奏愁思之不可長。按「流徵」以卻轉兮，聲幼妙而復揚。貫歷覽其中操兮，意慷慨而自卬。左右悲而垂淚兮，涕流離而從橫。舒息悒而增欷兮，蹝履起而彷徨。", "揄長袂以自翳兮，數昔日之諐殃。無面目之可顯兮，遂頹思而就牀。摶芬若以為枕兮，席荃蘭而茝香。忽寢寐而夢想兮，魄若君之在旁。惕寤覺而無見兮，魂迋迋若有亡。眾雞鳴而愁予兮，起視月之精光。", "觀眾星之行列兮，畢昴出於東方。望中庭之藹藹兮，若季秋之降霜。夜曼曼其若歲兮，懷鬱鬱其不可再更。澹偃蹇而待曙兮，荒亭亭而復明。妾人竊自悲兮，究年歲而不敢忘。"], "quote": ["夫何一佳人兮，步逍遙以自虞。魂踰佚而不反兮，形枯槁而獨居。言「我朝往而暮來」兮，飲食樂而忘人。心慊移而不省故兮，交得意而相親。", "伊予志之慢愚兮，懷真慤之懽心。願賜問而自進兮，得尚君之玉音。奉虛言而望誠兮，期城南之離宮。修薄具而自設兮，君曾不肯乎幸臨。", "廓獨潛而專精兮，天飄飄而疾風。登蘭臺而遙望兮，神怳怳而外淫。浮雲鬱而四塞兮，天窈窈而晝陰。雷殷殷而響起兮，聲象君之車音。飄風廻而赴閨兮，舉帷幄之襜襜；桂樹交而相紛兮，芳酷烈之誾誾。", "孔雀集而相存兮，玄猿嘯而長吟。翡翠脅翼而來萃兮，鸞鳳翔而北南。心憑噫而不舒兮，邪氣壯而攻中。"], "intro": "長門，漢宮名。據《昭明文選》所載《長門賦》原序說，漢武帝的陳皇后，有色而頗妒，武帝別有所幸，把她貶在長門宮。她愁悶悲思，聽說武帝很愛讀司馬相如的賦，便打發人送給相如黃金百斤，請他寫了這篇賦，給漢武帝看，以感君王之心。武帝讀了，陳皇后果又得幸", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%95%B7%E9%96%80%E8%B3%A6"}, {"title": "一鳴驚人", "author": "司馬遷", "period": "漢", "form": "文", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["齊威王之時喜隱，好為淫樂長夜之飲，沉湎不治，委政卿大夫。百官荒亂，諸侯並侵，國且危亡，在於旦暮，左右莫敢諫。淳于髡說之以隱曰︰「國中有大鳥，止王之庭，三年不蜚又不鳴，王知此鳥何也？」王曰︰「此鳥不飛則已，一飛沖天；不鳴則已，一鳴驚人。」於是乃朝諸縣令長七十二人，賞一人，誅一人，奮兵而出。諸侯振驚，皆還齊侵地。威行三十六年。"], "quote": ["齊威王之時喜隱，好為淫樂長夜之飲，沉湎不治，委政卿大夫。百官荒亂，諸侯並侵，國且危亡，在於旦暮，左右莫敢諫。淳于髡說之以隱曰︰「國中有大鳥，止王之庭，三年不蜚又不鳴，王知此鳥何也？」王曰︰「此鳥不飛則已，一飛沖天；不鳴則已，一鳴驚人。」於是乃朝諸縣令長七十二人，賞一人，誅一人，奮兵而出。諸侯振驚，皆還齊侵地。威行三十六年。"], "intro": "本文選自司馬遷《史記‧滑稽列傳》。《滑稽列傳》主要記載一些古時的人臣以詼諧或諷刺的方式對君主的進言。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B8%80%E9%B3%B4%E9%A9%9A%E4%BA%BA"}, {"title": "屈原列傳（節選《屈原賈生列傳》）", "author": "司馬遷", "period": "漢", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["屈原者，名平，楚之同姓也。為楚懷王左徒。博聞彊志，明於治亂，嫺於辭令。入則與王圖議國事以出號令；出則接遇賓客，應對諸侯。王甚任之。上官大夫與之同列，爭寵而心害其能。", "懷王使屈原造為憲令，屈平屬草藁未定，上官大夫見而欲奪之，屈平不與。因讒之曰︰「王使屈平為令，眾莫不知，每一令出，平伐其功曰︰『以為非我莫能為也。』」王怒而疏屈平。", "屈平疾王聽之不聰也，讒諂之蔽明也，邪曲之害公也，方正之不容也，故憂愁幽思而作《離騷》。「離騷」者，猶離憂也。夫天者，人之始也；父母者，人之本也。人窮則反本，故勞苦倦極，未嘗不呼天也；疾痛慘怛，未嘗不呼父母也。", "屈平正道直行，竭忠盡智以事其君，讒人間之，可謂窮矣！信而見疑，忠而被謗，能無怨乎？屈平之作《離騷》，蓋自怨生也。國風好色而不淫，小雅怨誹而不亂。若《離騷》者，可謂兼之矣。上稱帝嚳，下道齊桓，中述湯武，以刺世事。", "明道德之廣崇，治亂之條貫，靡不畢見。其文約；其辭微；其志潔；其行廉；其稱文小而其指極大，舉類邇而見義遠。其志潔，故其稱物芳；其行廉，故死而不容，自疎。", "濯淖汙泥之中，蟬蛻於濁穢，以浮游塵埃之外，不獲世之滋垢，皭然泥而不滓者也。推此志也，雖與日月爭光，可也。"], "quote": ["屈原者，名平，楚之同姓也。為楚懷王左徒。博聞彊志，明於治亂，嫺於辭令。入則與王圖議國事以出號令；出則接遇賓客，應對諸侯。王甚任之。上官大夫與之同列，爭寵而心害其能。", "懷王使屈原造為憲令，屈平屬草藁未定，上官大夫見而欲奪之，屈平不與。因讒之曰︰「王使屈平為令，眾莫不知，每一令出，平伐其功曰︰『以為非我莫能為也。』」王怒而疏屈平。", "屈平疾王聽之不聰也，讒諂之蔽明也，邪曲之害公也，方正之不容也，故憂愁幽思而作《離騷》。「離騷」者，猶離憂也。夫天者，人之始也；父母者，人之本也。人窮則反本，故勞苦倦極，未嘗不呼天也；疾痛慘怛，未嘗不呼父母也。", "屈平正道直行，竭忠盡智以事其君，讒人間之，可謂窮矣！信而見疑，忠而被謗，能無怨乎？屈平之作《離騷》，蓋自怨生也。國風好色而不淫，小雅怨誹而不亂。若《離騷》者，可謂兼之矣。上稱帝嚳，下道齊桓，中述湯武，以刺世事。"], "intro": "屈原是戰國末期楚國貴族，學問淵博，出任楚懷王的左徒，對內對外都擔任重要的角色。後來他因為屢遭排擠，被貶流放，最後因見楚國國勢日衰，悲憤憂鬱，投江而死。屈原著有《離騷》、《九歌》、《天問》、《九章》、《遠遊》、《卜居》及《漁父》等作品，文采斐", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B1%88%E5%8E%9F%E5%88%97%E5%82%B3%EF%BC%88%E7%AF%80%E9%81%B8%E3%80%8A%E5%B1%88%E5%8E%9F%E8%B3%88%E7%94%9F%E5%88%97%E5%82%B3%E3%80%8B%EF%BC%89"}, {"title": "荊軻刺秦王（節選《刺客列傳》）", "author": "司馬遷", "period": "漢", "form": "文", "theme": "送別行旅", "mood": "snow_winter", "lines": ["秦將王翦破趙，虜趙王，盡收入其地，進兵北略地至燕南界。太子丹恐懼，乃請荊軻曰︰「秦兵旦暮渡易水，則雖欲長侍足下，豈可得哉！」荊軻曰︰「微太子言，臣願謁之。今行而毋信，則秦未可親也。", "夫樊將軍，秦王購之金千斤，邑萬家。誠得樊將軍首與燕督亢之地圖，奉獻秦王，秦王必說見臣，臣乃得有以報。」太子曰︰「樊將軍窮困來歸丹，丹不忍以己之私而傷長者之意，願足下更慮之！」", "荊軻知太子不忍，乃遂私見樊於期曰︰「秦之遇將軍可謂深矣，父母宗族皆為戮沒。今聞購將軍首金千斤，邑萬家，將柰何？」於期仰天太息流涕曰︰「於期每念之，常痛於骨髓，顧計不知所出耳！」", "荊軻曰︰「今有一言可以解燕國之患，報將軍之仇者，何如？」於期乃前曰︰「為之柰何？」荊軻曰︰「願得將軍之首以獻秦王，秦王必喜而見臣，臣左手把其袖，右手揕其匈，然則將軍之仇報而燕見陵之愧除矣。將軍豈有意乎？」", "樊於期偏袒搤捥而進曰︰「此臣之日夜切齒腐心也，乃今得聞教！」遂自剄。太子聞之，馳往，伏屍而哭，極哀。既已不可柰何，乃遂盛樊於期首函封之。", "於是太子豫求天下之利匕首，得趙人徐夫人匕首，取之百金，使工以藥焠之，以試人，血濡縷，人無不立死者。乃裝為遣荊卿。燕國有勇士秦舞陽，年十三，殺人，人不敢忤視。乃令秦舞陽為副。", "荊軻有所待，欲與俱；其人居遠未來，而為治行。頃之，未發，太子遲之，疑其改悔，乃復請曰︰「日已盡矣，荊卿豈有意哉？丹請得先遣秦舞陽。」", "荊軻怒，叱太子曰︰「何太子之遣？往而不返者，豎子也！且提一匕首入不測之彊秦，僕所以留者，待吾客與俱。今太子遲之，請辭決矣！」遂發。", "太子及賓客知其事者，皆白衣冠以送之。至易水之上，既祖，取道，高漸離擊筑，荊軻和而歌，為變徵之聲，士皆垂淚涕泣。又前而為歌曰︰「風蕭蕭兮易水寒，壯士一去兮不復還！」復為羽聲忼慨，士皆瞋目，髮盡上指冠。於是荊軻就車而去，終已不顧。", "遂至秦，持千金之資幣物，厚遺秦王寵臣中庶子蒙嘉。嘉為先言於秦王曰︰「燕王誠振怖大王之威，不敢舉兵以逆軍吏，願舉國為內臣，比諸侯之列，給貢職如郡縣，而得奉守先王之宗廟。恐懼不敢自陳，謹斬樊於期之頭，及獻燕督亢之地圖，函封，燕王拜送于庭，使使以聞大王，唯大王命之。」", "秦王聞之，大喜，乃朝服，設九賓，見燕使者咸陽宮。荊軻奉樊於期頭函，而秦舞陽奉地圖柙，以次進。至陛，秦舞陽色變振恐，羣臣怪之。荊軻顧笑舞陽，前謝曰︰「北蕃蠻夷之鄙人，未嘗見天子，故振慴。願大王少假借之，使得畢使於前。」秦王謂軻曰︰「取舞陽所持地圖。」", "軻既取圖奏之，秦王發圖，圖窮而匕首見。因左手把秦王之袖，而右手持匕首揕之。未至身，秦王驚，自引而起，袖絕。拔劍，劍長，操其室。時惶急，劍堅，故不可立拔。荊軻逐秦王，秦王環柱而走。羣臣皆愕，卒起不意，盡失其度。"], "quote": ["秦將王翦破趙，虜趙王，盡收入其地，進兵北略地至燕南界。太子丹恐懼，乃請荊軻曰︰「秦兵旦暮渡易水，則雖欲長侍足下，豈可得哉！」荊軻曰︰「微太子言，臣願謁之。今行而毋信，則秦未可親也。", "夫樊將軍，秦王購之金千斤，邑萬家。誠得樊將軍首與燕督亢之地圖，奉獻秦王，秦王必說見臣，臣乃得有以報。」太子曰︰「樊將軍窮困來歸丹，丹不忍以己之私而傷長者之意，願足下更慮之！」", "荊軻知太子不忍，乃遂私見樊於期曰︰「秦之遇將軍可謂深矣，父母宗族皆為戮沒。今聞購將軍首金千斤，邑萬家，將柰何？」於期仰天太息流涕曰︰「於期每念之，常痛於骨髓，顧計不知所出耳！」", "荊軻曰︰「今有一言可以解燕國之患，報將軍之仇者，何如？」於期乃前曰︰「為之柰何？」荊軻曰︰「願得將軍之首以獻秦王，秦王必喜而見臣，臣左手把其袖，右手揕其匈，然則將軍之仇報而燕見陵之愧除矣。將軍豈有意乎？」"], "intro": "本篇節選自《史記‧刺客列傳》，版本據中華書局排印本。原文記載春秋戰國時期曹沫、專諸、豫讓、聶政和荊軻五個刺客的事迹。本文只選錄荊軻事迹的一部分，記述荊軻奉燕太子丹之命謀刺秦王的經過，突顯了荊軻的俠義精神。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%8D%8A%E8%BB%BB%E5%88%BA%E7%A7%A6%E7%8E%8B%EF%BC%88%E7%AF%80%E9%81%B8%E3%80%8A%E5%88%BA%E5%AE%A2%E5%88%97%E5%82%B3%E3%80%8B%EF%BC%89"}, {"title": "廉頗藺相如列傳（節選）", "author": "司馬遷", "period": "漢", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["廉頗者，趙之良將也。趙惠文王十六年，廉頗為趙將，伐齊，大破之，取陽晉，拜為上卿，以勇氣聞於諸侯。藺相如者，趙人也，為趙宦者令繆賢舍人。", "趙惠文王時，得楚和氏璧。秦昭王聞之，使人遺趙王書，願以十五城請易璧。趙王與大將軍廉頗諸大臣謀︰欲予秦，秦城恐不可得，徒見欺；欲勿予，即患秦兵之來。計未定，求人可使報秦者，未得。宦者令繆賢曰︰「臣舍人藺相如可使。」", "王問︰「何以知之？」對曰︰「臣嘗有罪，竊計欲亡走燕，臣舍人相如止臣，曰︰『君何以知燕王？』臣語曰︰『臣嘗從大王與燕王會境上，燕王私握臣手，曰︰「願結友。」以此知之，故欲往。』相如謂臣曰︰『夫趙彊而燕弱，而君幸於趙王，故燕王欲結於君。", "今君乃亡趙走燕，燕畏趙，其勢必不敢留君，而束君歸趙矣。君不如肉袒伏斧質請罪，則幸得脫矣。』臣從其計，大王亦幸赦臣。臣竊以為其人勇士，有智謀，宜可使。」於是王召見，問藺相如曰︰「秦王以十五城請易寡人之璧，可予不？」", "相如曰︰「秦彊而趙弱，不可不許。」王曰︰「取吾璧，不予我城，奈何？」相如曰︰「秦以城求璧而趙不許，曲在趙；趙予璧而秦不予趙城，曲在秦。均之二策，寧許以負秦曲。」王曰︰「誰可使者？」", "相如曰︰「王必無人，臣願奉璧往使。城入趙而璧留秦；城不入，臣請完璧歸趙。」趙王於是遂遣相如奉璧西入秦。", "秦王坐章臺見相如，相如奉璧奏秦王。秦王大喜，傳以示美人及左右，左右皆呼萬歲。相如視秦王無意償趙城，乃前曰︰「璧有瑕，請指示王。」", "王授璧，相如因持璧，卻立，倚柱，怒髮上衝冠，謂秦王曰︰「大王欲得璧，使人發書至趙王，趙王悉召羣臣議，皆曰︰『秦貪，負其彊，以空言求璧，償城恐不可得。』議不欲予秦璧。臣以為布衣之交尚不相欺，況大國乎！", "且以一璧之故逆彊秦之驩，不可。於是趙王乃齋戒五日，使臣奉璧，拜送書於庭。何者？嚴大國之威以修敬也。今臣至，大王見臣列觀，禮節甚倨；得璧，傳之美人，以戲弄臣。臣觀大王無意償趙王城邑，故臣復取璧。大王必欲急臣，臣頭今與璧俱碎於柱矣！」", "相如持其璧睨柱，欲以擊柱。秦王恐其破璧，乃辭謝固請，召有司案圖，指從此以往十五都予趙。相如度秦王特以詐佯為予趙城，實不可得，乃謂秦王曰︰「和氏璧，天下所共傳寶也。趙王恐，不敢不獻。", "趙王送璧時，齋戒五日，今大王亦宜齋戒五日，設九賓於廷，臣乃敢上璧。」秦王度之，終不可彊奪，遂許齋五日，舍相如廣成傳。相如度秦王雖齋，決負約不償城，乃使其從者衣褐，懷其璧，從徑道亡，歸璧於趙。", "秦王齋五日後，乃設九賓禮於廷，引趙使者藺相如。相如至，謂秦王曰︰「秦自繆公以來二十餘君，未嘗有堅明約束者也。臣誠恐見欺於王而負趙，故令人持璧歸，間至趙矣。且秦彊而趙弱，大王遣一介之使至趙，趙立奉璧來；今以秦之彊而先割十五都予趙，趙豈敢留璧而得罪於大王乎？"], "quote": ["廉頗者，趙之良將也。趙惠文王十六年，廉頗為趙將，伐齊，大破之，取陽晉，拜為上卿，以勇氣聞於諸侯。藺相如者，趙人也，為趙宦者令繆賢舍人。", "趙惠文王時，得楚和氏璧。秦昭王聞之，使人遺趙王書，願以十五城請易璧。趙王與大將軍廉頗諸大臣謀︰欲予秦，秦城恐不可得，徒見欺；欲勿予，即患秦兵之來。計未定，求人可使報秦者，未得。宦者令繆賢曰︰「臣舍人藺相如可使。」", "王問︰「何以知之？」對曰︰「臣嘗有罪，竊計欲亡走燕，臣舍人相如止臣，曰︰『君何以知燕王？』臣語曰︰『臣嘗從大王與燕王會境上，燕王私握臣手，曰︰「願結友。」以此知之，故欲往。』相如謂臣曰︰『夫趙彊而燕弱，而君幸於趙王，故燕王欲結於君。", "今君乃亡趙走燕，燕畏趙，其勢必不敢留君，而束君歸趙矣。君不如肉袒伏斧質請罪，則幸得脫矣。』臣從其計，大王亦幸赦臣。臣竊以為其人勇士，有智謀，宜可使。」於是王召見，問藺相如曰︰「秦王以十五城請易寡人之璧，可予不？」"], "intro": "本篇為「史記」中七十列傳之一，所記為戰國時趙國兩位名臣的事蹟，廉頗是當時頗負盛名的大將，藺相如是一卓越的外交家，二人同時在朝，公忠體國，化嫌為友，合力抵禦强秦，趙國賴以安定。篇中插敍趙國另外二名將趙奢、李牧部分，今略去。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%BB%89%E9%A0%97%E8%97%BA%E7%9B%B8%E5%A6%82%E5%88%97%E5%82%B3%EF%BC%88%E7%AF%80%E9%81%B8%EF%BC%89"}, {"title": "鴻門會（節選《項羽本紀》）", "author": "司馬遷", "period": "漢", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["沛公旦日從百餘騎來見項王，至鴻門，謝曰︰「臣與將軍戮力而攻秦，將軍戰河北，臣戰河南，然不自意能先入關破秦，得復見將軍於此。今者，有小人之言，令將軍與臣有郤。」項王曰︰「此沛公左司馬曹無傷言之；不然，籍何以至此。」項王即日因留沛公與飲。", "項王項伯東嚮坐，亞父南嚮坐，——亞父者，范增也。——沛公北嚮坐，張良西嚮侍。范增數目項王，舉所佩玉玦以示之者三，項王默然不應。范增起，出召項莊，謂曰︰「君王為人不忍，若入前為壽，壽畢，請以劍舞，因擊沛公於坐殺之。不者，若屬皆且為所虜。」", "莊則入為壽，壽畢，曰︰「君王與沛公飲軍中，無以為樂，請以劍舞。」項王曰︰「諾。」項莊拔劍起舞；項伯亦拔劍起舞，常以身翼蔽沛公，莊不得擊。", "於是張良至軍門見樊噲。樊噲曰︰「今日之事何如？」良曰︰「甚急。今者項莊拔劍舞，其意常在沛公也。」噲曰︰「此迫矣，臣請入，與之同命。」噲即帶劍擁盾入軍門，交戟之衞士欲止不內；樊噲側其盾以撞，衞士仆地。", "噲遂入，披帷西嚮立，瞋目視項王，頭髮上指，目眦盡裂。項王按劍而跽曰︰「客何為者？」張良曰︰「沛公之驂乘樊噲者也。」項王曰︰「壯士！賜之巵酒。」則與斗巵酒；噲拜謝，起立而飲之。項王曰︰「賜之彘肩。」則與一生彘肩。", "樊噲覆其盾於地，加彘肩上，拔劍切而啗之。項王曰︰「壯士！能復飲乎？」樊噲曰︰「臣死且不避，巵酒安足辭？夫秦王有虎狼之心，殺人如不能舉，刑人如恐不勝，天下皆叛之。懷王與諸將約曰︰『先破秦入咸陽者王之』。", "今沛公先破秦，入咸陽，毫毛不敢有所近，封閉宮室，還軍霸上，以待大王來。故遣將守關者，備他盜出入與非常也。勞苦而功高如此，未有封侯之賞；而聽細說，欲誅有功之人。此亡秦之續耳！竊為大王不取也。」", "項王未有以應，曰︰「坐！」樊噲從良坐。坐須臾，沛公起如廁，因招樊噲出。沛公已出，項王使都尉陳平召沛公。", "沛公曰︰「今者出，未辭也，為之奈何？」樊噲曰︰「大行不顧細謹，大禮不辭小讓。如今人方為刀俎，我為魚肉，何辭為！」於是遂去，乃令張良留謝。良問曰︰「大王來何操？」曰︰「我持白璧一雙，欲獻項王；玉斗一雙，欲與亞父；會其怒，不敢獻。公爲我獻之。」", "張良曰︰「謹諾。」當是時，項王軍在鴻門下，沛公軍在霸上，相去四十里。沛公則置車騎，脫身獨騎，與樊噲、夏侯嬰、靳彊、紀信等四人持劍盾步走，從酈山下道芷陽間行。沛公謂張良曰︰「從此道至吾軍，不過二十里耳。度我至軍中，公乃入。」", "沛公已去，間至軍中，張良入謝，曰︰「沛公不勝桮杓，不能辭，謹使臣良奉白璧一雙，再拜獻大王足下；玉斗一雙，再拜奉大將軍足下。」項王曰︰「沛公安在？」良曰︰「聞大王有意督過之，脫身獨去，已至軍矣。」", "項王則受璧，置之坐上。亞父受玉斗，置之地，拔劍撞而破之，曰︰「唉！豎子不足與謀。奪項王天下者，必沛公也，吾屬今為之虜矣。」"], "quote": ["沛公旦日從百餘騎來見項王，至鴻門，謝曰︰「臣與將軍戮力而攻秦，將軍戰河北，臣戰河南，然不自意能先入關破秦，得復見將軍於此。今者，有小人之言，令將軍與臣有郤。」項王曰︰「此沛公左司馬曹無傷言之；不然，籍何以至此。」項王即日因留沛公與飲。", "項王項伯東嚮坐，亞父南嚮坐，——亞父者，范增也。——沛公北嚮坐，張良西嚮侍。范增數目項王，舉所佩玉玦以示之者三，項王默然不應。范增起，出召項莊，謂曰︰「君王為人不忍，若入前為壽，壽畢，請以劍舞，因擊沛公於坐殺之。不者，若屬皆且為所虜。」", "莊則入為壽，壽畢，曰︰「君王與沛公飲軍中，無以為樂，請以劍舞。」項王曰︰「諾。」項莊拔劍起舞；項伯亦拔劍起舞，常以身翼蔽沛公，莊不得擊。", "於是張良至軍門見樊噲。樊噲曰︰「今日之事何如？」良曰︰「甚急。今者項莊拔劍舞，其意常在沛公也。」噲曰︰「此迫矣，臣請入，與之同命。」噲即帶劍擁盾入軍門，交戟之衞士欲止不內；樊噲側其盾以撞，衞士仆地。"], "intro": "「本紀」，依《史記》的體例，原為皇帝的本傳。項羽乃失敗的英雄，並沒正式做到皇帝，何以他的本傳也「本紀」名篇？這乃司馬遷的深心所在，也是他的卓越的史識所在。因為這樣安排，一方面表示：史家的責任，在於忠實表達時代的真相，在於公正衡量這個人物貢獻", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%B4%BB%E9%96%80%E6%9C%83%EF%BC%88%E7%AF%80%E9%81%B8%E3%80%8A%E9%A0%85%E7%BE%BD%E6%9C%AC%E7%B4%80%E3%80%8B%EF%BC%89"}, {"title": "佳人歌", "author": "李延年", "period": "漢", "form": "詩", "theme": "田園幽居", "mood": "ethereal", "lines": ["北方有佳人，絕世而獨立。", "一顧傾人城，再顧傾人國。", "寧不知傾城與傾國，佳人難再得。"], "quote": ["北方有佳人，絕世而獨立。", "一顧傾人城，再顧傾人國。", "寧不知傾城與傾國，佳人難再得。"], "intro": "《佳人歌》的由來在《漢書‧外戚傳》中有記載：「初，（李）夫人兄延年性知音，善歌舞，武帝愛之。每為新聲變曲，聞者莫不感動。延年侍上，起舞歌曰；『北方有佳人……』上歎息曰：『善！世豈有此人乎？』平陽主因言延年有女弟。上乃召見之，實妙麗善舞，由是", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%BD%B3%E4%BA%BA%E6%AD%8C"}, {"title": "答蘇武書", "author": "李陵", "period": "漢", "form": "文", "theme": "邊塞豪放", "mood": "snow_winter", "lines": ["子卿足下︰勤宣令德，策名清時，榮問休暢，幸甚幸甚。遠托異國，昔人所悲；望風懷想，能不依依！", "昔者不遺，遠辱還答，慰誨懃懃，有踰骨肉，陵雖不敏，能不慨然！自從初降，以至今日，身之窮困，獨坐愁苦，終日無覩，但見異類。韋韝毳幙，以禦風雨；羶肉酪漿，以充饑渴。舉目言笑，誰與為歡？", "胡地玄冰，邊土慘裂，但聞悲風蕭條之聲。涼秋九月，塞外草衰；夜不能寐，側耳遠聽，胡笳互動，牧馬悲鳴，吟嘯成羣，邊聲四起。晨坐聽之，不覺淚下。嗟乎子卿，陵獨何心，能不悲哉！", "與子別後，益復無聊，上念老母，臨年被戮，妻子無辜，並為鯨鯢，身負國恩，為世所悲。子歸受榮，我留受辱，命也如何！身出禮義之鄉，而入無知之俗，違棄君親之恩，長為蠻夷之域，傷已！", "令先君之嗣，更成戎狄之族，又自悲矣！功大罪小，不蒙明察，孤負陵心區區之意，每一念至，忽然忘生。陵不難刺心以自明，刎頸以見志，顧國家於我已矣，殺身無益，適足增羞，故每攘臂忍辱，輒復苟活。", "左右之人見陵如此，以為不入耳之歡，來相勸勉，異方之樂，祗令人悲，增忉怛耳。", "嗟乎子卿，人之相知，貴相知心。前書倉卒，未盡所懷，故復略而言之。", "昔先帝授陵步卒五千，出征絕域，五將失道，陵獨遇戰。而裹萬里之糧，帥徒步之師，出天漢之外，入強胡之域。以五千之眾，對十萬之軍；策疲乏之兵，當新羈之馬。然猶斬將搴旗，追奔逐北，滅跡掃塵，斬其梟帥，使三軍之士，視死如歸。", "陵也不才，希當大任；意謂此時，功難堪矣。匈奴既敗，舉國興師。更練精兵，強踰十萬；單于臨陣，親自合圍。客主之形既不相如，步馬之勢又甚懸絕。疲兵再戰，一以當千，然猶扶乘創痛，決命爭首。死傷積野，餘不滿百，而皆扶病，不任干戈。", "然陵振臂一呼，創病皆起，舉刃指虜，胡馬奔走。兵盡矢窮，人無尺鐵，猶復徒首奮呼，爭為先登。當此時也，天地為陵震怒，戰士為陵飲血。單于謂陵不可復得，便欲引還，而賊臣教之，遂使復戰，故陵不免耳。", "昔高皇帝以三十萬眾困於平城，當此之時，猛將如雲，謀臣如雨，然猶七日不食，僅乃得免。況當陵者，豈易為力哉。而執事者云云，苟怨陵以不死。然陵不死，罪也；子卿視陵，豈偷生之士而惜死之人哉？", "寧有背君親，捐妻子，而反為利者乎！然陵不死，有所為也；故欲如前書之言，報恩于國主耳！誠以虛死不如立節，滅名不如報德也。昔範蠡不殉會稽之恥，曹沬不死三敗之辱，卒復勾踐之讎，報魯國之羞。區區之心，竊慕此耳。"], "quote": ["子卿足下︰勤宣令德，策名清時，榮問休暢，幸甚幸甚。遠托異國，昔人所悲；望風懷想，能不依依！", "昔者不遺，遠辱還答，慰誨懃懃，有踰骨肉，陵雖不敏，能不慨然！自從初降，以至今日，身之窮困，獨坐愁苦，終日無覩，但見異類。韋韝毳幙，以禦風雨；羶肉酪漿，以充饑渴。舉目言笑，誰與為歡？", "胡地玄冰，邊土慘裂，但聞悲風蕭條之聲。涼秋九月，塞外草衰；夜不能寐，側耳遠聽，胡笳互動，牧馬悲鳴，吟嘯成羣，邊聲四起。晨坐聽之，不覺淚下。嗟乎子卿，陵獨何心，能不悲哉！", "與子別後，益復無聊，上念老母，臨年被戮，妻子無辜，並為鯨鯢，身負國恩，為世所悲。子歸受榮，我留受辱，命也如何！身出禮義之鄉，而入無知之俗，違棄君親之恩，長為蠻夷之域，傷已！"], "intro": "本文選自《文選》，《藝文類聚》及《全漢文》均收入，標題均作「重報蘇武書」，惟《史記》《漢書》中之《李陵傳》不載。唐劉知幾，宋蘇軾，清章學誠，均疑為後人偽作，今已成為定案。蘇武（公元前？──前六四）字子卿，漢杜陵（今陝西長安縣東南）人。武帝時", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%AD%94%E8%98%87%E6%AD%A6%E6%9B%B8"}, {"title": "羽林郎", "author": "辛延年", "period": "漢", "form": "詩", "theme": "田園幽居", "mood": "spring_breeze", "lines": ["昔有霍家奴，姓馮名子都，", "依倚將軍勢，調笑酒家胡。", "胡姬年十五，春日獨當壚。", "長裾連理帶，廣袖合歡襦；", "頭上藍田玉，耳後大秦珠；", "兩鬟何窈窕！一世良所無，", "一鬟五百萬，兩鬟千萬餘。", "不意金吾子，娉婷過我廬；", "銀鞍何煜爚！翠蓋空踟躕。", "就我求清酒，絲繩提玉壺；", "就我求珍肴，金盤膾鯉魚。", "貽我青銅鏡，結我紅羅裾。"], "quote": ["昔有霍家奴，姓馮名子都，", "依倚將軍勢，調笑酒家胡。", "胡姬年十五，春日獨當壚。", "長裾連理帶，廣袖合歡襦；"], "intro": "本詩為漢詩中的名作之一，是文人仿照樂府民歌的情調，所寫的五言詩，初見於南朝徐陵所編的《玉臺新詠》，後由宋郭茂倩收入《樂府詩集》卷第六十三「雜曲歌辭」內。 羽林郎，乃漢代皇家的禁衛軍軍官名，為漢武帝太初元年所設置，據《後漢書・百官志》：「羽林", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%BE%BD%E6%9E%97%E9%83%8E"}, {"title": "怨歌行", "author": "班婕妤", "period": "漢", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["新裂齊紈素，鮮潔如霜雪。", "裁為合歡扇，團團似明月。", "出入君懷袖，動搖微風發；", "常恐秋節至，涼飆奪炎熱；", "棄捐篋笥中，恩情中道絕。"], "quote": ["新裂齊紈素，鮮潔如霜雪。", "裁為合歡扇，團團似明月。", "出入君懷袖，動搖微風發；", "常恐秋節至，涼飆奪炎熱；"], "intro": "本詩見於《昭明文選》及《玉臺新詠》，是一首技巧已很成熟的五言詩。《玉臺新詠》並於詩前作短序介紹：「昔漢成帝班妤婕失寵，供養於長信宮，乃作賦自傷，並為怨詩一首。」但李善注引歌辭時但稱為「古辭」，劉勰也表懷疑，恐為後人擬作。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%80%A8%E6%AD%8C%E8%A1%8C"}, {"title": "四愁詩", "author": "張衡", "period": "漢", "form": "詩", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["我所思兮在太山，欲往從之梁父艱。側身東望涕霑翰。美人贈我金錯刀，何以報之英瓊瑤。路遠莫致倚逍遙，何為懷憂心煩勞。", "我所思兮在桂林，欲往從之湘水深。側身南望涕霑襟。美人贈我琴琅玕。何以報之雙玉盤。路遠莫致倚惆悵，何為懷憂心煩怏。", "我所思兮在漢陽，欲往從之隴阪長。側身西望涕霑裳。美人贈我貂襜褕，何以報之明月珠。路遠莫致倚踟躕，何為懷憂心煩紆。", "我所思兮在雁門，欲往從之雪雰雰。側身北望涕霑巾。美人贈我錦繡段，何以報之青玉案。路遠莫致倚增歎，何為懷憂心煩惋。"], "quote": ["我所思兮在太山，欲往從之梁父艱。側身東望涕霑翰。美人贈我金錯刀，何以報之英瓊瑤。路遠莫致倚逍遙，何為懷憂心煩勞。", "我所思兮在桂林，欲往從之湘水深。側身南望涕霑襟。美人贈我琴琅玕。何以報之雙玉盤。路遠莫致倚惆悵，何為懷憂心煩怏。", "我所思兮在漢陽，欲往從之隴阪長。側身西望涕霑裳。美人贈我貂襜褕，何以報之明月珠。路遠莫致倚踟躕，何為懷憂心煩紆。", "我所思兮在雁門，欲往從之雪雰雰。側身北望涕霑巾。美人贈我錦繡段，何以報之青玉案。路遠莫致倚增歎，何為懷憂心煩惋。"], "intro": "《四愁詩》仿屈原騷體，表達一種懷人與憂思的情緒。據《文選》本詩前序文曰：「張衡久不樂處機密（衡當時為太史令），陽嘉（漢順帝年號）中出為河間相，……時天下漸弊，鬱鬱不得志，為《四愁詩》。依屈原以美人為君子，以珍寶為仁義，以水深雪雰為小人，思以", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%9B%9B%E6%84%81%E8%A9%A9"}, {"title": "步出夏門行（其四）", "author": "曹操", "period": "漢", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["神龜雖壽，猶有竟時；騰蛇乘霧，終為土灰。驥老伏櫪，志在千里；烈士暮年，壯心不已。盈縮之期，不但在天；養怡之福，可得永年。幸甚至哉！歌以詠志。"], "quote": ["神龜雖壽，猶有竟時；騰蛇乘霧，終為土灰。驥老伏櫪，志在千里；烈士暮年，壯心不已。盈縮之期，不但在天；養怡之福，可得永年。幸甚至哉！歌以詠志。"], "intro": "《步出夏門行》選自《宋書‧樂志》。夏門，指洛陽北面靠西的城門。此曲又名《隴西行》，屬古樂府《相和歌‧瑟調曲》，曹氏據譜製詞。共有《觀滄海》、《冬十月》、《土不同》及《龜雖壽》四章，前有序曲「豔辭」。此組詩作於東漢獻帝建安十二年（二〇七），曹", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%AD%A5%E5%87%BA%E5%A4%8F%E9%96%80%E8%A1%8C%EF%BC%88%E5%85%B6%E5%9B%9B%EF%BC%89"}, {"title": "短歌行", "author": "曹操", "period": "漢", "form": "詩", "theme": "詠史哲思", "mood": "vast_river", "lines": ["對酒當歌，人生幾何？譬如朝露，去日苦多。", "慨當以慷，憂思難忘。何以解憂？惟有杜康。", "「青青子衿，悠悠我心」。但為君故，沉吟至今。", "「呦呦鹿鳴，食野之苹，我有嘉賓，鼓瑟吹笙。」", "明明如月，何時可掇？憂從中來，不可斷絕！", "越陌度阡，枉用相存，契闊談讌，心念舊恩。", "月明星稀，烏鵲南飛，繞樹三匝，何枝可依？", "山不厭高，水不厭深。周公吐哺，天下歸心。"], "quote": ["對酒當歌，人生幾何？譬如朝露，去日苦多。", "慨當以慷，憂思難忘。何以解憂？惟有杜康。", "「青青子衿，悠悠我心」。但為君故，沉吟至今。", "「呦呦鹿鳴，食野之苹，我有嘉賓，鼓瑟吹笙。」"], "intro": "「行」是古體詩的一種形式，《短歌行》是樂府《相和歌辭中的平調曲名。作者就用這種詩體，抒發內心的感慨和懷抱，蒼勁悲壯，浩淼雄深，在詩國中得到極高的評價。全詩四言八韻，也就自然地分做八段。第一段劈頭一句「對酒當歌」，豪情陡發，引起對於人生短暫的", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%9F%AD%E6%AD%8C%E8%A1%8C"}, {"title": "后羿射日", "author": "《淮南子》", "period": "漢", "form": "文", "theme": "春水花鳥", "mood": "vast_river", "lines": ["逮至堯之時，十日並出，焦禾稼，殺草木，而民无所食。猰貐、九嬰、大風、封豨、鑿齒、修蛇，皆為民害。堯乃使羿誅鑿齒於疇華之澤，殺九嬰於凶水之上，繳大風於青丘之野，上射十日而下殺猰貐，斷脩蛇於洞庭，禽封狶於桑林。萬民皆喜，置堯以為天子。"], "quote": ["逮至堯之時，十日並出，焦禾稼，殺草木，而民无所食。猰貐、九嬰、大風、封豨、鑿齒、修蛇，皆為民害。堯乃使羿誅鑿齒於疇華之澤，殺九嬰於凶水之上，繳大風於青丘之野，上射十日而下殺猰貐，斷脩蛇於洞庭，禽封狶於桑林。萬民皆喜，置堯以為天子。"], "intro": "《后羿射日》選自《淮南子‧本經訓》，本無題目，現題為編者所加。版本據《先秦兩漢古籍逐字索引》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%90%8E%E7%BE%BF%E5%B0%84%E6%97%A5"}, {"title": "塞翁失馬", "author": "《淮南子》", "period": "漢", "form": "文", "theme": "邊塞豪放", "mood": "heroic", "lines": ["近塞上之人，有善術者。馬無故亡而入胡，人皆弔之。其父曰︰「此何遽不為福乎？」居數月，其馬將胡駿馬而歸，人皆賀之。其父曰︰「此何遽不能為禍乎？」家富良馬，其子好騎，墮而折其髀，人皆弔之。其父曰︰「此何遽不為福乎？」居一年，胡人大入塞，丁壯者引弦而戰，近塞之人，死者十九。此獨以跛之故，父子相保。"], "quote": ["近塞上之人，有善術者。馬無故亡而入胡，人皆弔之。其父曰︰「此何遽不為福乎？」居數月，其馬將胡駿馬而歸，人皆賀之。其父曰︰「此何遽不能為禍乎？」家富良馬，其子好騎，墮而折其髀，人皆弔之。其父曰︰「此何遽不為福乎？」居一年，胡人大入塞，丁壯者引弦而戰，近塞之人，死者十九。此獨以跛之故，父子相保。"], "intro": "本文選自《淮南子‧人間訓》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%A1%9E%E7%BF%81%E5%A4%B1%E9%A6%AC"}, {"title": "垓下歌", "author": "項羽", "period": "漢", "form": "詩", "theme": "山水登臨", "mood": "majestic_peaks", "lines": ["力拔山兮氣蓋世，時不利兮騅不逝。", "騅不逝兮可奈何，虞兮虞兮奈若何！"], "quote": ["力拔山兮氣蓋世，時不利兮騅不逝。", "騅不逝兮可奈何，虞兮虞兮奈若何！"], "intro": "垓下，地名，在今安徽省靈壁縣東南，漢高祖圍項羽於此。《史記‧項羽本紀》：「項王軍壁垓下，兵少食盡，漢軍及諸侯兵圍之數重。夜聞漢軍四面皆楚歌，項王乃大驚曰：『漢皆已得楚乎？是何楚人之多也！』項王則夜起，飲帳中。有美人名虞，常幸從；駿馬名騅，常", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%9E%93%E4%B8%8B%E6%AD%8C"}, {"title": "西門豹治鄴", "author": "褚少孫", "period": "漢", "form": "文", "theme": "送別行旅", "mood": "vast_river", "lines": ["魏文侯時，西門豹為鄴令。豹往到鄴，會長老，問之民所疾苦。長老曰︰「苦為河伯娶婦，以故貧。」豹問其故，對曰︰「鄴三老、廷掾，常歲賦斂百姓，收取其錢，得數百萬；用其二三十萬為河伯娶婦；與祝巫共分其餘錢，持歸。", "當其時，巫行視人家女好者，云︰『是當為河伯婦。』即娉取洗沐之，為治新繒、綺、縠衣。閒居齋戒，為治齋宮河上，張緹絳帷，女居其中。為具牛、酒、飯食。行十餘日，共粉飾之，如嫁女牀席，令女居其上，浮之河中。", "始浮，行數十里，乃沒。其人家有好女者，恐大巫祝為河伯取之，以故多持女遠逃亡。以故城中益空無人，又困貧，所從來久遠矣。民人俗語曰︰『即不為河伯娶婦，水來漂沒，溺其人民』云。」", "西門豹曰︰「至為河伯娶婦時，願三老、巫祝、父老送女河上，幸來告語之！吾亦往送女。」皆曰︰「諾。」", "至其時，西門豹往會之河上。三老、官屬、豪長者、里父老皆會，以人民往觀之者三二千人。其巫，老女子也，已年七十。從弟子女十人所，皆衣繒單衣，立大巫後。", "西門豹曰︰「呼河伯婦來，視其好醜。」即將女出帷中，來至前。豹視之，顧謂三老、巫祝、父老曰︰「是女子不好。煩大巫嫗為入報河伯︰得更求好女，後日送之！」即使吏卒共抱大巫嫗投之河中。", "有頃，曰︰「巫嫗何久也？弟子趣之？」復以弟子一人投河中。有頃，曰︰「弟子何久也？復使一人趣之！」復投一弟子河中。凡投三弟子。", "西門豹曰︰「巫嫗弟子，是女子也，不能白事。煩三老為入白之！」復投三老河中。西門豹簪筆磬折，嚮河立，待良久。長老、吏、傍觀者皆驚恐。", "西門豹曰︰「巫嫗、三老不來還，奈之何？」欲復使廷掾與豪長者一人入趣之。皆叩頭，叩頭且破，額血流地，色如死灰。西門豹曰︰「諾！且留！待之須臾！」", "須臾，豹曰︰「廷掾起矣！狀河伯留客之久，若皆罷去，歸矣！」鄴吏民大驚恐；從是以後，不敢復言為河伯娶婦。", "西門豹即發民鑿十二渠，引河水灌民田，田皆溉。當其時，民治渠少煩苦，不欲也。豹曰︰「民可以樂成，不可與慮始。今父老子弟雖患苦我，然百歲後，期令父老子孫思我言！」", "至今皆得水利，民人以給足富。故西門豹為鄴令，名聞天下，澤流後世，無絕已時，幾可謂非賢大夫哉！"], "quote": ["魏文侯時，西門豹為鄴令。豹往到鄴，會長老，問之民所疾苦。長老曰︰「苦為河伯娶婦，以故貧。」豹問其故，對曰︰「鄴三老、廷掾，常歲賦斂百姓，收取其錢，得數百萬；用其二三十萬為河伯娶婦；與祝巫共分其餘錢，持歸。", "當其時，巫行視人家女好者，云︰『是當為河伯婦。』即娉取洗沐之，為治新繒、綺、縠衣。閒居齋戒，為治齋宮河上，張緹絳帷，女居其中。為具牛、酒、飯食。行十餘日，共粉飾之，如嫁女牀席，令女居其上，浮之河中。", "始浮，行數十里，乃沒。其人家有好女者，恐大巫祝為河伯取之，以故多持女遠逃亡。以故城中益空無人，又困貧，所從來久遠矣。民人俗語曰︰『即不為河伯娶婦，水來漂沒，溺其人民』云。」", "西門豹曰︰「至為河伯娶婦時，願三老、巫祝、父老送女河上，幸來告語之！吾亦往送女。」皆曰︰「諾。」"], "intro": "西門豹，戰國時魏人，曾做過鄴令。他是魏文侯時一個幹練的政治人才，在鄴令任內，曾改革了當地河伯娶婦的惡俗，引水灌溉田地，人民蒙受很大福利。鄴地，在今河南臨潼縣境。本文就是敍述的他在鄴的政績，是一篇很有趣味的故事。本文是褚少孫對《史記・滑稽列傳", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A5%BF%E9%96%80%E8%B1%B9%E6%B2%BB%E9%84%B4%E3%80%80"}, {"title": "過秦論", "author": "賈誼", "period": "漢", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["秦孝公據殽函之固，擁雍州之地，君臣固守，以窺周室；有席卷天下，包舉宇內，囊括四海之意，并吞八荒之心。", "當是時也，商君佐之，內立法度、務耕織、修守戰之具；外連衡而鬬諸侯。於是秦人拱手而取西河之外。", "孝公既沒，惠文、武、昭，蒙故業，因遺策，南取漢中，西舉巴蜀，東割膏腴之地，北收要害之郡。", "諸侯恐懼，會盟而謀弱秦；不愛珍器、重寶、肥饒之地，以致天下之士，合從締交，相與為一。", "當此之時，齊有孟嘗，趙有平原，楚有春申，魏有信陵。此四君者，皆明智而忠信，寬厚而愛人，尊賢而重士。約從離橫，兼韓、魏、燕、趙、宋、衛、中山之眾。", "於是六國之士，有甯越、徐尚、蘇秦、杜赫之屬為之謀；齊明、周最、陳軫、召滑、樓緩、翟景、蘇厲、樂毅之徒通其意；吳起、孫臏、帶佗、兒良、王廖、田忌、廉頗、趙奢之倫制其兵。嘗以什倍之地，百萬之眾，叩關而攻秦。", "秦人開關而延敵，九國之師，遁逃而不敢進。秦無亡矢遺鏃之費，而天下諸侯已困矣。", "於是從散約解，爭割地而賂秦。秦有餘力而制其弊，追亡逐北，伏屍百萬，流血漂櫓；因利乘便，宰割天下，分裂河山；彊國請伏，弱國入朝。", "施及孝文王莊襄王，享國之日淺，國家無事。及至始皇，奮六世之餘烈，振長策而御宇內；吞二周而亡諸侯，履至尊而制六合；執敲扑以鞭笞天下，威振四海。南取百越之地，以為桂林象郡；百越之君，俛首係頸，委命下吏。", "乃使蒙恬北築長城而守藩籬，卻匈奴七百餘里。胡人不敢南下而牧馬，士不敢彎弓而報怨。於是廢先王之道，燔百家之言，以愚黔首；隳名城，殺豪俊，收天下之兵，聚之咸陽；銷鋒鍉，鑄以為金人十二，以弱天下之民。", "然後踐華為城，因河為池，據億丈之城，臨不測之谿以為固。良將勁弩，守要害之處；信臣精卒，陳利兵而誰何！天下已定，始皇之心，自以為關中之固，金城千里，子孫帝王萬世之業。", "始皇既沒，餘威震于殊俗。然陳涉甕牖繩樞之子，甿隸之人，而遷徙之徒也。材能不及中庸，非有仲尼墨翟之賢；陶朱猗頓之富；躡足行伍之間，俛起阡陌之中，率罷散之卒，將數百之眾，轉而攻秦。"], "quote": ["秦孝公據殽函之固，擁雍州之地，君臣固守，以窺周室；有席卷天下，包舉宇內，囊括四海之意，并吞八荒之心。", "當是時也，商君佐之，內立法度、務耕織、修守戰之具；外連衡而鬬諸侯。於是秦人拱手而取西河之外。", "孝公既沒，惠文、武、昭，蒙故業，因遺策，南取漢中，西舉巴蜀，東割膏腴之地，北收要害之郡。", "諸侯恐懼，會盟而謀弱秦；不愛珍器、重寶、肥饒之地，以致天下之士，合從締交，相與為一。"], "intro": "過秦，是評論秦朝的過失。本文在《賈子新書》裏列為第一篇，題目只是「過秦」，並無「論」字。晉陳壽撰《三國志》，在《吳志・闞澤傳》裏，記載着孫權問闞澤「書傳篇賦，何者為美？」闞澤答以「賈誼過秦論最善」。從此以後，晉左思的《詠史詩》和梁蕭統的《昭", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%81%8E%E7%A7%A6%E8%AB%96"}, {"title": "十五從軍征", "author": "漢樂府", "period": "漢", "form": "詩", "theme": "送別行旅", "mood": "ethereal", "lines": ["十五從軍征，八十始得歸。道逢鄉里人，家中有阿誰？", "遙望是君家，松柏冢纍纍。兔從狗竇入，雉從樑上飛。", "中庭生旅穀，井上生旅葵。舂穀持作飯，採葵持作羹。", "羹飯一時熟，不知貽阿誰。出門東向望，淚落沾我衣。"], "quote": ["十五從軍征，八十始得歸。道逢鄉里人，家中有阿誰？", "遙望是君家，松柏冢纍纍。兔從狗竇入，雉從樑上飛。", "中庭生旅穀，井上生旅葵。舂穀持作飯，採葵持作羹。", "羹飯一時熟，不知貽阿誰。出門東向望，淚落沾我衣。"], "intro": "《十五從軍征》節選自《樂府詩集》卷二十五，本題為「紫騮馬歌辭」，注引《古今樂錄》曰：「『十五從軍征』以下是古詩。」詩歌內容描寫一位十五歲開始從軍，八十歲才回到故鄉的老人的經歷。寫出漢代兵役制度之不合理，及戰爭給人民帶來的苦難的情形。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%8D%81%E4%BA%94%E5%BE%9E%E8%BB%8D%E5%BE%81"}, {"title": "上山採蘼蕪", "author": "漢樂府", "period": "漢", "form": "詩", "theme": "山水登臨", "mood": "vast_river", "lines": ["上山採蘼蕪，下山逢故夫。長跪問故夫，新人復何如。", "新人雖言好，未若故人姝。顏色類相似，手爪不相如。", "新人從門入，故人從閤去。新人工織縑，故人工織素。", "織縑日一匹，織素五丈餘。將縑來比素，新人不如故。"], "quote": ["上山採蘼蕪，下山逢故夫。長跪問故夫，新人復何如。", "新人雖言好，未若故人姝。顏色類相似，手爪不相如。", "新人從門入，故人從閤去。新人工織縑，故人工織素。", "織縑日一匹，織素五丈餘。將縑來比素，新人不如故。"], "intro": "本篇始見於《玉臺新詠》，原題作《古詩》，《太平御覽》引作古樂府。明‧賀貽孫云：「（此詩）有《詩經》《漢廣》和《柏舟》之遺風，字字溫厚，尤得好色不淫之意。」清‧方東樹則認為詩人藉婦人與前夫的對話來闡發君臣忠義之道，云：「此君臣之恉，奇情奇想，", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B8%8A%E5%B1%B1%E6%8E%A1%E8%98%BC%E8%95%AA"}, {"title": "上邪", "author": "漢樂府", "period": "漢", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["上邪！我欲與君相知，長命無絕衰。", "山無陵，江水為竭，冬雷震震，夏雨雪，天地合，乃敢與君絕！"], "quote": ["上邪！我欲與君相知，長命無絕衰。", "山無陵，江水為竭，冬雷震震，夏雨雪，天地合，乃敢與君絕！"], "intro": "本篇選自《樂府詩集・鼓吹典辭》，是漢樂府「《鐃歌》十八曲」之一。篇名取自首句二字。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B8%8A%E9%82%AA"}, {"title": "白頭吟", "author": "漢樂府", "period": "漢", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["皚如山上雪，皎若雲間月。聞君有兩意，故來相決絕。", "今日斗酒會，明旦溝水頭。躞蹀御溝上，溝水東西流。", "淒淒復淒淒，嫁娶不須啼。願得一心人，白頭不相離。", "竹竿何嫋嫋，魚尾何簁簁。男兒重意氣，何用錢刀為。"], "quote": ["皚如山上雪，皎若雲間月。聞君有兩意，故來相決絕。", "今日斗酒會，明旦溝水頭。躞蹀御溝上，溝水東西流。", "淒淒復淒淒，嫁娶不須啼。願得一心人，白頭不相離。", "竹竿何嫋嫋，魚尾何簁簁。男兒重意氣，何用錢刀為。"], "intro": "此詩最早見於《玉臺新詠》，題為《皚如山上雪》。《西京雜記》卷三云：「相如將聘茂陵人女為妾，卓文君作白頭吟以自絕。相如乃止。」傳說本篇為卓文君寫與司馬相如之作，然按《宋書‧樂志》所載，本篇為「樂章古辭」，與《江南可採蓮》、《烏生八九子》同為「", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%99%BD%E9%A0%AD%E5%90%9F"}, {"title": "有所思", "author": "漢樂府", "period": "漢", "form": "詩", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["有所思，乃在大海南。何用問遺君？雙珠玳瑁簪，用玉紹繚之。", "聞君有他心，拉雜摧燒之。摧燒之，當風揚其灰。從今以往，勿復相思！相思與君絕！", "雞鳴狗吠，兄嫂當知之。妃呼唏！秋風肅肅晨風颸，東方須臾高知之。"], "quote": ["有所思，乃在大海南。何用問遺君？雙珠玳瑁簪，用玉紹繚之。", "聞君有他心，拉雜摧燒之。摧燒之，當風揚其灰。從今以往，勿復相思！相思與君絕！", "雞鳴狗吠，兄嫂當知之。妃呼唏！秋風肅肅晨風颸，東方須臾高知之。"], "intro": "本篇為漢鐃歌十八曲之一。鐃歌本為「建威揚德，勸士諷敵」的軍樂，然今傳十八曲中內容龐雜，敘戰陣、紀祥瑞、表武功、寫愛情者皆有，唯配合軍樂之聲而內容多直言或為強烈情感之表現。本篇或言為「刺淫奔之詩」，或曰「逐臣見棄於其君之作」，「藩國之臣，不遇", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9C%89%E6%89%80%E6%80%9D"}, {"title": "江南", "author": "漢樂府", "period": "漢", "form": "詩", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["江南可採蓮，", "蓮葉何田田。", "魚戲蓮葉間，", "魚戲蓮葉東，", "魚戲蓮葉西，", "魚戲蓮葉南，", "魚戲蓮葉北。"], "quote": ["江南可採蓮，", "蓮葉何田田。", "魚戲蓮葉間，", "魚戲蓮葉東，"], "intro": "江南水域遼闊，湖泊星羅棋布，每到夏秋之際，綠荷飄香，蓮房結子，正是江南青年男女採蓮的季節。他們坐在特製的木盆裏，浮在綠荷掩映的水面上，一邊採摘，一邊唱歌。這首詩便是江南民間採蓮時所唱的歌。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B1%9F%E5%8D%97"}, {"title": "東門行", "author": "漢樂府", "period": "漢", "form": "詩", "theme": "江河湖海", "mood": "vast_river", "lines": ["出東門，不顧歸；來入門，悵欲悲。盎中無斗米儲，還視桁上無懸衣。拔劍出門去，舍中兒母牽衣啼。", "「他家但願富貴，賤妾與君共餔糜。共餔糜，上用倉浪天故，下為黃口小兒。今時清廉，難犯教言，君復自愛莫為非！」", "「行！吾去為遲！」", "「平慎行，望君歸！」"], "quote": ["出東門，不顧歸；來入門，悵欲悲。盎中無斗米儲，還視桁上無懸衣。拔劍出門去，舍中兒母牽衣啼。", "「他家但願富貴，賤妾與君共餔糜。共餔糜，上用倉浪天故，下為黃口小兒。今時清廉，難犯教言，君復自愛莫為非！」", "「行！吾去為遲！」", "「平慎行，望君歸！」"], "intro": "《東門行》選自宋郭茂倩《樂府詩集》。《樂府詩集》將所收自漢至五代的樂府歌辭分為十二類，《東門行》屬於「相和歌」類的「瑟調曲」。 東漢末年，朝政腐敗，宦官當權，戰禍頻仍，民不聊生。社會低下層人民即使在豐年也不得飽食，許多人淪為奴隸，或有為了生", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9D%B1%E9%96%80%E8%A1%8C"}, {"title": "長歌行", "author": "漢樂府", "period": "漢", "form": "詩", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["青青園中葵，朝露待日晞。陽春布德澤，萬物生光輝。", "常恐秋節至，焜黃華葉衰。百川東到海，何時復西歸。", "少壯不努力，老大徒傷悲！"], "quote": ["青青園中葵，朝露待日晞。陽春布德澤，萬物生光輝。", "常恐秋節至，焜黃華葉衰。百川東到海，何時復西歸。", "少壯不努力，老大徒傷悲！"], "intro": "《長歌行》選自《樂府詩集》卷三十。歌行，是古代詩歌的一種體裁。它的音節和格律一般比較自由，形式富於變化。樂府有《長歌行》、《短歌行》。這首詩勉勵年青人及時發憤，珍惜時光，「少壯不努力，老大徒傷悲」這兩句話，成為學子們的座右銘。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%95%B7%E6%AD%8C%E8%A1%8C"}, {"title": "陌上桑", "author": "漢樂府", "period": "漢", "form": "詩", "theme": "邊塞豪放", "mood": "heroic", "lines": ["日出東南隅，照我秦氏樓。秦氏有好女，自名為羅敷。羅敷憙蠶桑，採桑城南隅。青絲為籠係，桂枝為籠鈎。頭上倭墮髻，耳中明月珠。", "緗綺為下裙，紫綺為上襦。行者見羅敷，下擔捋髭鬚。少年見羅敷，脫帽著帩頭。耕者忘其犂，鋤者忘其鋤。來歸相怨怒，但坐觀羅敷。", "使君從南來，五馬立踟躕。使君遣吏往，問是誰家姝。秦氏有好女，自名為羅敷。羅敷年幾何，二十尚不足，十五頗有餘。", "使君謝羅敷，寧可共載不，羅敷前置辭。使君一何愚。使君自有婦，羅敷自有夫。", "東方千餘騎，夫婿居上頭。何用識夫婿，白馬從驪駒。青絲繫馬尾，黃金絡馬頭。腰中鹿盧劍，可直千萬餘。", "十五府小史，二十朝大夫，三十侍中郎，四十專城居。為人潔白皙，鬑鬑頗有鬚。盈盈公府步，冉冉府中趨。坐中數千人，皆言夫婿殊。"], "quote": ["日出東南隅，照我秦氏樓。秦氏有好女，自名為羅敷。羅敷憙蠶桑，採桑城南隅。青絲為籠係，桂枝為籠鈎。頭上倭墮髻，耳中明月珠。", "緗綺為下裙，紫綺為上襦。行者見羅敷，下擔捋髭鬚。少年見羅敷，脫帽著帩頭。耕者忘其犂，鋤者忘其鋤。來歸相怨怒，但坐觀羅敷。", "使君從南來，五馬立踟躕。使君遣吏往，問是誰家姝。秦氏有好女，自名為羅敷。羅敷年幾何，二十尚不足，十五頗有餘。", "使君謝羅敷，寧可共載不，羅敷前置辭。使君一何愚。使君自有婦，羅敷自有夫。"], "intro": "《陌上桑》選自《樂府詩集‧相和歌辭三》。《陌上桑》是漢樂府古辭，始著錄於南朝宋沈約《宋書‧樂志》，題作《艷歌羅敷行》；南陳徐陵輯《玉臺新詠》，題作《日出東南隅行》；宋人郭茂倩輯《樂府詩集》，收入《相和歌‧相和曲》。《陌上桑》是樂府古辭中著名", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%99%8C%E4%B8%8A%E6%A1%91"}, {"title": "飲馬長城窟行（青青河邊草）", "author": "漢樂府", "period": "漢", "form": "詩", "theme": "江河湖海", "mood": "snow_winter", "lines": ["青青河邊草，緜緜思遠道。遠道不可思，宿昔夢見之。", "夢見在我傍，忽覺在他鄉。他鄉各異縣，輾轉不相見。", "枯桑知天風，海水知天寒。入門各自媚，誰肯相為言。", "客從遠方來，遺我雙鯉魚。呼兒烹鯉魚，中有尺素書。", "長跪讀素書，書中竟何如？上言加餐食，下言長相憶。"], "quote": ["青青河邊草，緜緜思遠道。遠道不可思，宿昔夢見之。", "夢見在我傍，忽覺在他鄉。他鄉各異縣，輾轉不相見。", "枯桑知天風，海水知天寒。入門各自媚，誰肯相為言。", "客從遠方來，遺我雙鯉魚。呼兒烹鯉魚，中有尺素書。"], "intro": "這首詩最早見於《昭明文選》，題為「樂府古辭」，是民間創作，作者已不可考。「行」為樂府詩體的一種，大多為抒發情感之作，由於與「歌」的性質相似，因此也稱「歌行體」。《文選》五臣注：「長城，秦所築以備胡者。其下有泉窟，可以飲馬。征人路出於此而傷悲", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%A3%B2%E9%A6%AC%E9%95%B7%E5%9F%8E%E7%AA%9F%E8%A1%8C%EF%BC%88%E9%9D%92%E9%9D%92%E6%B2%B3%E9%82%8A%E8%8D%89%EF%BC%89"}, {"title": "戰城南", "author": "漢樂府", "period": "漢", "form": "詩", "theme": "邊塞豪放", "mood": "autumn_sunset", "lines": ["戰城南，死郭北，野死不葬烏可食。", "為我謂烏︰「且為客豪。野死諒不葬，腐肉安能去子逃？」", "水深激激，蒲葦冥冥，梟騎戰鬥死，駑馬徘徊鳴。", "梁築室，何以南？何以北？禾黍不穫君何食？願為忠臣安可得？", "思子良臣，良臣誠可思，朝行出攻，暮不夜歸！"], "quote": ["戰城南，死郭北，野死不葬烏可食。", "為我謂烏︰「且為客豪。野死諒不葬，腐肉安能去子逃？」", "水深激激，蒲葦冥冥，梟騎戰鬥死，駑馬徘徊鳴。", "梁築室，何以南？何以北？禾黍不穫君何食？願為忠臣安可得？"], "intro": "「樂府」本是漢代掌管音樂的機關，引申為樂府官署所採制的民間詩歌。後世將魏晉至唐代可以入樂的詩歌，以及仿樂府古題的作品，統稱「樂府」。 本篇是樂府古辭，屬「鼓吹曲辭」，《漢鐃歌十八曲》之一。鐃歌是軍樂，而十八曲中，寫戰爭之事者僅此一篇。「戰城", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%88%B0%E5%9F%8E%E5%8D%97"}, {"title": "大風歌", "author": "劉邦", "period": "漢", "form": "詩", "theme": "春水花鳥", "mood": "vast_river", "lines": ["大風起兮雲飛揚，威加海內兮歸故鄉，安得猛士兮守四方。"], "quote": ["大風起兮雲飛揚，威加海內兮歸故鄉，安得猛士兮守四方。"], "intro": "《大風歌》屬於樂府的《琴曲歌辭》，是漢高祖平定英布之亂後，凱旋歸來，經故鄉沛縣時和父老兄弟一同饗宴，於酒酣之中所唱的歌。 《史記‧高祖本紀》：「高祖還歸，過沛，留。置酒沛宮，悉召故人父老子弟縱酒。發沛中兒得百二十人，教之歌。酒酣，高祖擊筑，", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%A4%A7%E9%A2%A8%E6%AD%8C"}, {"title": "秋風辭", "author": "劉徹", "period": "漢", "form": "詩", "theme": "春水花鳥", "mood": "autumn_sunset", "lines": ["秋風起兮白雲飛，草木黃落兮雁南歸。", "蘭有秀兮菊有芳，懷佳人兮不能忘。", "汎樓船兮濟汾河，橫中流兮揚素波。", "蕭鼓鳴兮發櫂歌，歡樂極兮哀情多。", "少壯幾時兮奈老何！"], "quote": ["秋風起兮白雲飛，草木黃落兮雁南歸。", "蘭有秀兮菊有芳，懷佳人兮不能忘。", "汎樓船兮濟汾河，橫中流兮揚素波。", "蕭鼓鳴兮發櫂歌，歡樂極兮哀情多。"], "intro": "《秋風辭》是漢樂府名篇，也是漢武帝的代表作，屬《樂府‧雜歌謠辭》。其由來在《漢武帝故事》中略有記載：「上行幸河東，祠后土，顧視帝京欣然。中流與群臣飲宴，上歡甚，乃自作《秋風辭》。」", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%A7%8B%E9%A2%A8%E8%BE%AD"}, {"title": "孟母戒子", "author": "韓嬰", "period": "漢", "form": "文", "theme": "田園幽居", "mood": "ethereal", "lines": ["孟子少時，誦，其母方織，孟子輟然中止，乃復進，其母知其諠也，呼而問之曰︰「何為中止？」對曰︰「有所失，復得。」其母引刀裂其織，以此誡之，自是以後，孟子不復諠矣。"], "quote": ["孟子少時，誦，其母方織，孟子輟然中止，乃復進，其母知其諠也，呼而問之曰︰「何為中止？」對曰︰「有所失，復得。」其母引刀裂其織，以此誡之，自是以後，孟子不復諠矣。"], "intro": "本文節選自《韓詩外傳》卷九。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%AD%9F%E6%AF%8D%E6%88%92%E5%AD%90"}, {"title": "七哀詩", "author": "王粲", "period": "魏晉", "form": "詩", "theme": "山水登臨", "mood": "spring_breeze", "lines": ["西京亂無象，豺虎方遘患。復棄中國去，遠身適荊蠻。", "親戚對我悲，朋友相追攀。出門無所見，白骨蔽平原。", "路有飢婦人，抱子棄草間。顧聞號泣聲，揮涕獨不還。", "未知身死處，何能兩相完？驅馬棄之去，不忍聽此言。", "南登霸陵岸，迴首望長安。悟彼下泉人，喟然傷心肝。"], "quote": ["西京亂無象，豺虎方遘患。復棄中國去，遠身適荊蠻。", "親戚對我悲，朋友相追攀。出門無所見，白骨蔽平原。", "路有飢婦人，抱子棄草間。顧聞號泣聲，揮涕獨不還。", "未知身死處，何能兩相完？驅馬棄之去，不忍聽此言。"], "intro": "《七哀詩》（西京亂無象）選自《文選》卷二十三。《七哀詩》起源於漢末，是樂府新題。「七」是言哀之多，並非定數。王粲以此為題，寫成三首，這裏選的是第一首，作於初平三年（一九三）。當時李傕、郭汜在長安作亂，王粲被逼南逃。此詩便寫他離開長安到荊州避", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B8%83%E5%93%80%E8%A9%A9"}, {"title": "登樓賦", "author": "王粲", "period": "魏晉", "form": "辭賦", "theme": "山水登臨", "mood": "vast_river", "lines": ["登茲樓以四望兮，聊暇日以銷憂。覽斯宇之所處兮，實顯敞而寡仇。挾清漳之通浦兮，倚曲沮之長洲；背墳衍之廣陸兮，臨皋隰之沃流。", "北彌陶牧，西接昭丘；華實蔽野，黍稷盈疇。雖信美而非吾土兮，曾何足以少留？", "遭紛濁而遷逝兮，漫踰紀以迄今；情眷眷而懷歸兮，孰憂思之可任？憑軒檻以遙望兮，向北風而開襟。平原遠而極目兮，蔽荊山之高岑；路逶迤而修迥兮，川既漾而濟深。悲舊鄉之壅隔兮，涕橫墜而弗禁！", "昔尼父之在陳兮，有「歸與」之歎音；鍾儀幽而楚奏兮，莊舄顯而越吟。人情同於懷土兮，豈窮達而異心？惟日月之逾邁兮，俟河清其未極。冀王道之一平兮，假高衢而騁力。懼匏瓜之徒懸兮，畏井渫之莫食。", "步棲遲以徙倚兮，白日忽其將匿；風蕭瑟而並興兮，天慘慘而無色。獸狂顧以求羣兮，鳥相鳴而舉翼。原野闃其無人兮，征夫行而未息；心悽愴以感發兮，意忉怛而憯惻。", "循階除而下降兮，氣交憤於胸臆；夜參半而不寐兮，悵盤桓以反側。"], "quote": ["登茲樓以四望兮，聊暇日以銷憂。覽斯宇之所處兮，實顯敞而寡仇。挾清漳之通浦兮，倚曲沮之長洲；背墳衍之廣陸兮，臨皋隰之沃流。", "北彌陶牧，西接昭丘；華實蔽野，黍稷盈疇。雖信美而非吾土兮，曾何足以少留？", "遭紛濁而遷逝兮，漫踰紀以迄今；情眷眷而懷歸兮，孰憂思之可任？憑軒檻以遙望兮，向北風而開襟。平原遠而極目兮，蔽荊山之高岑；路逶迤而修迥兮，川既漾而濟深。悲舊鄉之壅隔兮，涕橫墜而弗禁！", "昔尼父之在陳兮，有「歸與」之歎音；鍾儀幽而楚奏兮，莊舄顯而越吟。人情同於懷土兮，豈窮達而異心？惟日月之逾邁兮，俟河清其未極。冀王道之一平兮，假高衢而騁力。懼匏瓜之徒懸兮，畏井渫之莫食。"], "intro": "漢末長安大亂，王粲赴荊州依附劉表，劉表對他沒有怎樣重視。這篇賦便是他在荊州登當陽城樓所作的。他一方面雖然欣賞着當地的風物之美，可是感懷身世，乃不勝故土之思。他提到「匏瓜」「井渫」這類的話，更可看出他對仕進一層，正在一個鬱鬱不得志的時候。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%99%BB%E6%A8%93%E8%B3%A6"}, {"title": "蘭亭集序", "author": "王羲之", "period": "魏晉", "form": "文", "theme": "田園幽居", "mood": "autumn_sunset", "lines": ["永和九年，歲在癸丑，暮春之初，會于會稽山陰之蘭亭，修禊事也。羣賢畢至，少長咸集。此地有崇山峻嶺，茂林修竹；", "又有清流激湍，映帶左右。引以為流觴曲水，列坐其次；雖無絲竹管絃之盛，一觴一詠，亦足以暢敍幽情。", "是日也，天朗氣清，惠風和暢；仰觀宇宙之大，俯察品類之盛，所以游目騁懷，足以極視聽之娛，信可樂也！", "夫人之相與，俯仰一世，或取諸懷抱，晤言一室之內；或因寄所託，放浪形骸之外。雖趨舍萬殊，靜躁不同；當其欣于所遇，暫得于己，快然自足，不知老之將至。", "及其所之既倦，情隨事遷，感慨係之矣。向之所欣，俛仰之間，以為陳迹，猶不能不以之興懷；況修短隨化，終期于盡。古人云︰「死生亦大矣」，豈不痛哉！", "每覽昔人興感之由，若合一契；未嘗不臨文嗟悼，不能喻之于懷。固知一死生為虛誕，齊彭殤為妄作。後之視今，亦猶今之視昔，悲夫！", "故列敍時人，錄其所述。雖世殊事異，所以興懷，其致一也。後之覽者，亦將有感於斯文。"], "quote": ["永和九年，歲在癸丑，暮春之初，會于會稽山陰之蘭亭，修禊事也。羣賢畢至，少長咸集。此地有崇山峻嶺，茂林修竹；", "又有清流激湍，映帶左右。引以為流觴曲水，列坐其次；雖無絲竹管絃之盛，一觴一詠，亦足以暢敍幽情。", "是日也，天朗氣清，惠風和暢；仰觀宇宙之大，俯察品類之盛，所以游目騁懷，足以極視聽之娛，信可樂也！", "夫人之相與，俯仰一世，或取諸懷抱，晤言一室之內；或因寄所託，放浪形骸之外。雖趨舍萬殊，靜躁不同；當其欣于所遇，暫得于己，快然自足，不知老之將至。"], "intro": "蘭亭，在今浙江紹興縣蘭渚。古人每逢三月上已（即第一個已日），臨水洗濯，祓除不祥，就叫做「修禊」（禊讀xì，本義即除惡之祭）；這是一種清潔運動的節目，由來很久。後來此風逐漸衰歇，但文人仍每藉此日登山臨水，飲酒賦詩，舉行雅集。晉王羲之曾與當時的", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%98%AD%E4%BA%AD%E9%9B%86%E5%BA%8F"}, {"title": "詠史（其二）", "author": "左思", "period": "魏晉", "form": "詩", "theme": "詠史哲思", "mood": "majestic_peaks", "lines": ["鬱鬱澗底松，離離山上苗。", "以彼徑寸莖，蔭此百尺條。", "世胄躡高位，英俊沉下僚。", "地勢使之然，由來非一朝。", "金張藉舊業，七葉珥漢貂。", "馮公豈不偉，白首不見招。"], "quote": ["鬱鬱澗底松，離離山上苗。", "以彼徑寸莖，蔭此百尺條。", "世胄躡高位，英俊沉下僚。", "地勢使之然，由來非一朝。"], "intro": "左思《詠史詩》共八首。「詠史」作為詩題，起自東漢班固，其後，王粲、曹植等人均有繼作。但他們的《詠史詩》大都是敘述史實，一詩專詠一人一事。左思突破了「詠史」的傳統寫法，變專詠一人一事為詠眾多的古人古事，更重要的是他能不為史事所拘，「多攄胸臆」", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A9%A0%E5%8F%B2%EF%BC%88%E5%85%B6%E4%BA%8C%EF%BC%89"}, {"title": "鑿壁借光", "author": "《西京雜記》", "period": "魏晉", "form": "文", "theme": "田園幽居", "mood": "ethereal", "lines": ["匡衡，字稚圭，勤學而無燭。鄰舍有燭而不逮，衡乃穿壁引其光，以書映光而讀之。邑人大姓文不識，家富多書，衡乃與其傭作而不求償。主人怪，問衡，衡曰︰「願得主人書遍讀之。」主人感嘆，資給以書，遂成大學。"], "quote": ["匡衡，字稚圭，勤學而無燭。鄰舍有燭而不逮，衡乃穿壁引其光，以書映光而讀之。邑人大姓文不識，家富多書，衡乃與其傭作而不求償。主人怪，問衡，衡曰︰「願得主人書遍讀之。」主人感嘆，資給以書，遂成大學。"], "intro": "", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%91%BF%E5%A3%81%E5%80%9F%E5%85%89"}, {"title": "詠懷詩", "author": "阮籍", "period": "魏晉", "form": "詩", "theme": "田園幽居", "mood": "ethereal", "lines": ["夜中不能寐，起坐彈鳴琴。薄帷鑒明月，清風吹我襟。", "孤鴻號外野，翔鳥鳴北林。徘徊將何見？憂思獨傷心。"], "quote": ["夜中不能寐，起坐彈鳴琴。薄帷鑒明月，清風吹我襟。", "孤鴻號外野，翔鳥鳴北林。徘徊將何見？憂思獨傷心。"], "intro": "阮籍的八十二首《詠懷詩》非成於一時，也非全部刻意而作，多是隨意抒感。阮籍及其《詠懷詩》的意義非常重要，他處於建安和太康年間，這兩個時代的詩歌詞藻華美，以致流於浮華，內容貧乏。阮籍的可貴在於他未受雕琢之風的影響，而是以渾樸的字句，獨步當世。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A9%A0%E6%87%B7%E8%A9%A9"}, {"title": "陳情表", "author": "李密", "period": "魏晉", "form": "文", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["臣密言︰臣以險釁，夙遭閔凶。生孩六月，慈父見背。行年四歲，舅奪母志。祖母劉，愍臣孤弱，躬親撫養。臣少多疾病，九歲不行，零丁孤苦，至于成立。既無伯叔，終鮮兄弟，門衰祚薄，晚有兒息。", "外無朞功強近之親，內無應門五尺之僮，煢煢孑立，形影相弔。而劉夙嬰疾病，常在床蓐，臣侍湯藥，未曾廢離。", "逮奉聖朝，沐浴清化。前太守臣逵察臣孝廉。後刺史臣榮舉臣秀才。臣以供養無主，辭不赴命。詔書特下，拜臣郎中，尋蒙國恩，除臣洗馬。", "猥以微賤，當侍東宮，非臣隕首所能上報。臣具以表聞，辭不就職。詔書切峻，責臣逋慢，郡縣逼迫，催臣上道，州司臨門，急於星火。", "臣欲奉詔奔馳，則劉病日篤；欲苟順私情，則告訴不許。臣之進退，實為狼狽。", "伏惟聖朝以孝治天下，凡在故老，猶蒙矜育，況臣孤苦，特為尤甚。且臣少仕偽朝，歷職郎署。本圖宦達，不矜名節。", "今臣亡國賤俘，至微至陋，過蒙拔擢，寵命優渥，豈敢盤桓，有所希冀！但以劉日薄西山，氣息奄奄，人命危淺，朝不慮夕。臣無祖母，無以至今日；祖母無臣，無以終餘年。母孫二人，更相為命，是以區區不能廢遠。", "臣密今年四十有四，祖母劉今年九十有六，是臣盡節於陛下之日長，報劉之日短也。烏鳥私情，願乞終養。臣之辛苦，非獨蜀之人士及二州牧伯所見明知，皇天后土，實所共鑒。", "願陛下矜愍愚誠，聽臣微志。庶劉僥倖，保卒餘年。臣生當隕首，死當結草。臣不勝犬馬怖懼之情，謹拜表以聞。"], "quote": ["臣密言︰臣以險釁，夙遭閔凶。生孩六月，慈父見背。行年四歲，舅奪母志。祖母劉，愍臣孤弱，躬親撫養。臣少多疾病，九歲不行，零丁孤苦，至于成立。既無伯叔，終鮮兄弟，門衰祚薄，晚有兒息。", "外無朞功強近之親，內無應門五尺之僮，煢煢孑立，形影相弔。而劉夙嬰疾病，常在床蓐，臣侍湯藥，未曾廢離。", "逮奉聖朝，沐浴清化。前太守臣逵察臣孝廉。後刺史臣榮舉臣秀才。臣以供養無主，辭不赴命。詔書特下，拜臣郎中，尋蒙國恩，除臣洗馬。", "猥以微賤，當侍東宮，非臣隕首所能上報。臣具以表聞，辭不就職。詔書切峻，責臣逋慢，郡縣逼迫，催臣上道，州司臨門，急於星火。"], "intro": "《陳情表》選自《文選》卷三十七。陳是陳述、報告的意思。表是古代公文的一種，是臣下稟告君上之辭。《陳情表》寫於公元二六七年，當時蜀漢已亡，西晉亦已建立。司馬氏為了鞏固統治，故徵召有名望的人出仕。李密這篇《陳情表》，便婉謝了晉武帝的徵召，極言自", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%99%B3%E6%83%85%E8%A1%A8"}, {"title": "遊仙詩", "author": "郭璞", "period": "魏晉", "form": "詩", "theme": "田園幽居", "mood": "vast_river", "lines": ["京華遊俠窟，山林隱遯棲。", "朱門何足榮？未若託蓬萊。", "臨源挹清波，陵崗掇丹荑。", "靈谿可潛盤，安事登雲梯。", "漆園有傲吏，萊氏有逸妻。", "進則保龍見，退為觸藩羝。", "高蹈風塵外，長揖謝夷齊。"], "quote": ["京華遊俠窟，山林隱遯棲。", "朱門何足榮？未若託蓬萊。", "臨源挹清波，陵崗掇丹荑。", "靈谿可潛盤，安事登雲梯。"], "intro": "郭璞《遊仙詩》現存十四首，內容歌詠隱逸高行，蔑視功名富貴，表達出對現實污濁的不滿。郭璞雖嚮往隱居，然終其一生並未避居。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%81%8A%E4%BB%99%E8%A9%A9"}, {"title": "飲馬長城窟行", "author": "陳琳", "period": "魏晉", "form": "詩", "theme": "邊塞豪放", "mood": "snow_winter", "lines": ["飲馬長城窟，水寒傷馬骨。往謂長城吏，慎莫稽留太原卒。官作自有程，舉築諧汝聲。男兒寧當格鬥死，何能怫鬱築長城？長城何連連，連連三千里。邊城多健少，內舍多寡婦。", "作書與內舍，便嫁莫留住。善事新姑嫜，時時念我故夫子。報書往邊地，君今出語一何鄙！身在禍難中，何為稽留他家子？生男慎莫舉，生女哺用脯。", "君獨不見長城下，死人骸骨相撐拄。結髮行事君，慊慊心意關。明知邊地苦，賤妾何能久自全？"], "quote": ["飲馬長城窟，水寒傷馬骨。往謂長城吏，慎莫稽留太原卒。官作自有程，舉築諧汝聲。男兒寧當格鬥死，何能怫鬱築長城？長城何連連，連連三千里。邊城多健少，內舍多寡婦。", "作書與內舍，便嫁莫留住。善事新姑嫜，時時念我故夫子。報書往邊地，君今出語一何鄙！身在禍難中，何為稽留他家子？生男慎莫舉，生女哺用脯。", "君獨不見長城下，死人骸骨相撐拄。結髮行事君，慊慊心意關。明知邊地苦，賤妾何能久自全？"], "intro": "《飲馬長城窟行》一曰《飲馬行》，為漢樂府古題，原屬《相和歌辭‧瑟調曲》。作者以舊題寫新辭，藉描寫秦朝修築長城所造成的人民苦難和家庭破碎，反映出東漢末年動亂的現實生活與百姓心聲。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%A3%B2%E9%A6%AC%E9%95%B7%E5%9F%8E%E7%AA%9F%E8%A1%8C"}, {"title": "桃花源記", "author": "陶潛", "period": "魏晉", "form": "文", "theme": "春水花鳥", "mood": "autumn_sunset", "lines": ["晉太元中，武陵人捕魚為業。緣溪行，忘路之遠近。忽逢桃花林，夾岸數百步，中無雜樹，芳草鮮美，落英繽紛。漁人甚異之。復前行，欲窮其林。林盡水源，便得一山，山有小口，髣髴若有光。便捨船從口入。", "初極狹，纔通人。復行數十步，豁然開朗。土地平曠，屋舍儼然。有良田、美池、桑、竹之屬。阡陌交通，雞犬相聞。其中往來種作，男女衣著，悉如外人；黃髮垂髫，並怡然自樂。", "見漁人乃大驚，問所從來。具答之。便要還家，設酒殺雞作食。村中聞有此人，咸來問訊。自云先世避秦時亂，率妻子邑人來此絕境，不復出焉，遂與外人間隔。", "問今是何世，乃不知有漢，無論魏晉。此人一一為具言所聞，皆歎惋。餘人各復延至其家，皆出酒食。停數日，辭去。此中人語云︰「不足為外人道也。」", "既出，得其船，便扶向路，處處誌之。及郡下，詣太守說如此。太守即遣人隨其往，尋向所誌，遂迷不復得路。", "南陽劉子驥，高尚士也。聞之，欣然規往，未果，尋病終，後遂無問津者。"], "quote": ["晉太元中，武陵人捕魚為業。緣溪行，忘路之遠近。忽逢桃花林，夾岸數百步，中無雜樹，芳草鮮美，落英繽紛。漁人甚異之。復前行，欲窮其林。林盡水源，便得一山，山有小口，髣髴若有光。便捨船從口入。", "初極狹，纔通人。復行數十步，豁然開朗。土地平曠，屋舍儼然。有良田、美池、桑、竹之屬。阡陌交通，雞犬相聞。其中往來種作，男女衣著，悉如外人；黃髮垂髫，並怡然自樂。", "見漁人乃大驚，問所從來。具答之。便要還家，設酒殺雞作食。村中聞有此人，咸來問訊。自云先世避秦時亂，率妻子邑人來此絕境，不復出焉，遂與外人間隔。", "問今是何世，乃不知有漢，無論魏晉。此人一一為具言所聞，皆歎惋。餘人各復延至其家，皆出酒食。停數日，辭去。此中人語云︰「不足為外人道也。」"], "intro": "本篇選自《靖節先生集》卷六，原是陶淵明的五言古詩〈桃花源詩〉前的一篇小記，相當於詩的序言，約作於晉末宋初，是作者晚年之作。陶淵明在文中描繪了一個幽美、淳樸、平等、安樂的桃花源，與當時的黑暗社會形成強烈對比。沈德潛以「此即羲皇之想也」形容本文", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%A1%83%E8%8A%B1%E6%BA%90%E8%A8%98"}, {"title": "移居二首", "author": "陶潛", "period": "魏晉", "form": "詩", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["其一", "昔欲居南村，非為卜其宅。", "聞多素心人，樂與數晨夕。", "懷此頗有年，今日從茲役。", "敝廬何必廣，取足蔽牀席。", "鄰曲時時來，抗言談在昔。", "奇文共欣賞，疑義相與析。", "其二", "春秋多佳日，登高賦新詩。", "過門更相呼，有酒斟酌之。", "農務各自歸，閒暇輒相思。", "相思則披衣，言笑無厭時。"], "quote": ["其一", "昔欲居南村，非為卜其宅。", "聞多素心人，樂與數晨夕。", "懷此頗有年，今日從茲役。"], "intro": "陶淵明上京住所失火之後，於義熙六年（410）遷往南里之南村，寫了《移居》二首。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%A7%BB%E5%B1%85%E4%BA%8C%E9%A6%96"}, {"title": "詠荊軻", "author": "陶潛", "period": "魏晉", "form": "詩", "theme": "邊塞豪放", "mood": "snow_winter", "lines": ["燕丹善養士，志在報強嬴。招集百夫良，歲暮得荊卿。", "君子死知己，提劍出燕京。素驥鳴廣陌，慷慨送我行。", "雄髮指危冠，猛氣衝長纓。飲餞易水上，四座列群英。", "漸離擊悲筑，宋意唱高聲。蕭蕭哀風逝，淡淡寒波生。", "商音更流涕，羽奏壯士驚。心知去不歸，且有後世名。", "登車何時顧，飛蓋入秦庭。凌厲越萬里，逶迤過千城。", "圖窮事自至，豪主正怔營。惜哉劍術疏，奇功遂不成。", "其人雖已沒，千載有餘情。"], "quote": ["燕丹善養士，志在報強嬴。招集百夫良，歲暮得荊卿。", "君子死知己，提劍出燕京。素驥鳴廣陌，慷慨送我行。", "雄髮指危冠，猛氣衝長纓。飲餞易水上，四座列群英。", "漸離擊悲筑，宋意唱高聲。蕭蕭哀風逝，淡淡寒波生。"], "intro": "荊軻是戰國時衛國人。到燕國去，燕人稱他為荊卿。燕太子丹在秦國作人質，逃回燕國，召募勇士要刺殺秦王。荊軻被薦。後選定時機，帶燕國地圖奉獻秦王，圖中暗藏匕首，以便行刺。臨行時，「太子及賓客知其事者，皆白衣冠以送之。至易水之上，既祖（祭祀路神）取", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A9%A0%E8%8D%8A%E8%BB%BB"}, {"title": "飲酒（其五）", "author": "陶潛", "period": "魏晉", "form": "詩", "theme": "田園幽居", "mood": "autumn_sunset", "lines": ["結廬在人境，而無車馬喧，", "問君何能爾，心遠地自偏。", "採菊東籬下，悠然見南山，", "山氣日夕佳，飛鳥相與還。", "此中有真意，欲辨已忘言。"], "quote": ["結廬在人境，而無車馬喧，", "問君何能爾，心遠地自偏。", "採菊東籬下，悠然見南山，", "山氣日夕佳，飛鳥相與還。"], "intro": "陶淵明的《飲酒》是組詩，共有二十首，有說寫於晉安帝義熙十三年（公元417年），當時陶淵明大約五十三歲。組詩前有小序，說明自己閒居寡歡，每晚都飲酒，飲醉之後常題詠數句自娛，積累成這批飲酒詩，各詩之間並無次序關係。 蕭統〈陶淵明集序〉：「有疑陶", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%A3%B2%E9%85%92%EF%BC%88%E5%85%B6%E4%BA%94%EF%BC%89"}, {"title": "歸去來辭並序", "author": "陶潛", "period": "魏晉", "form": "辭賦", "theme": "田園幽居", "mood": "snow_winter", "lines": ["余家貧，耕植不足以自給。幼稚盈室，缾無儲粟，生生所資，未見其術。親故多勸余為長吏，脫然有懷，求之靡途。會有四方之事，諸侯以惠愛為德，家叔以余貧苦，遂見用於小邑。", "于時風波未靜，心憚遠役，彭澤去家百里，公田之利，足以為酒，故便求之。及少日，眷然有歸歟之情。何則？質性自然，非矯厲所得。飢凍雖切，違己交病。嘗從人事，皆口腹自役。", "於是悵然慷慨，深媿平生之志。猶望一稔，當斂裳宵逝。尋程氏妹喪于武昌，情在駿奔，自免去職。仲秋至冬，在官八十餘日。因事順心，命篇曰《歸去來兮》。乙巳歲十一月也。", "歸去來兮，田園將蕪胡不歸？既自以心為形役，奚惆悵而獨悲！悟已往之不諫，知來者之可追；實迷途其未遠，覺今是而昨非。", "舟遙遙以輕颺，風飄飄而吹衣。問征夫以前路。恨晨光之熹微。", "乃瞻衡宇，載欣載奔。僮僕歡迎，稚子候門。三逕就荒，松菊猶存。攜幼入室，有酒盈罇。引壺觴以自酌，眄庭柯以怡顏。倚南窗以寄傲，審容膝之易安。", "園日涉以成趣，門雖設而常關。策扶老以流憩，時矯首而遐觀。雲無心以出岫，鳥倦飛而知還。景翳翳以將入，撫孤松而盤桓。", "歸去來兮，請息交以絕遊。世與我而相違，復駕言兮焉求？悅親戚之情話，樂琴書以消憂。農人告余以春及，將有事於西疇。或命巾車，或棹孤舟。", "既窈窕以尋壑，亦崎嶇而經丘。木欣欣以向榮，泉涓涓而始流。善萬物之得時，感吾生之行休。", "已矣乎，寓形宇內復幾時，曷不委心任去留？胡為乎遑遑欲何之？富貴非吾願，帝鄉不可期。懷良辰以孤往，或植杖而耘耔。", "登東皐以舒嘯，臨清流而賦詩。聊乘化以歸盡，樂夫天命復奚疑。"], "quote": ["余家貧，耕植不足以自給。幼稚盈室，缾無儲粟，生生所資，未見其術。親故多勸余為長吏，脫然有懷，求之靡途。會有四方之事，諸侯以惠愛為德，家叔以余貧苦，遂見用於小邑。", "于時風波未靜，心憚遠役，彭澤去家百里，公田之利，足以為酒，故便求之。及少日，眷然有歸歟之情。何則？質性自然，非矯厲所得。飢凍雖切，違己交病。嘗從人事，皆口腹自役。", "於是悵然慷慨，深媿平生之志。猶望一稔，當斂裳宵逝。尋程氏妹喪于武昌，情在駿奔，自免去職。仲秋至冬，在官八十餘日。因事順心，命篇曰《歸去來兮》。乙巳歲十一月也。", "歸去來兮，田園將蕪胡不歸？既自以心為形役，奚惆悵而獨悲！悟已往之不諫，知來者之可追；實迷途其未遠，覺今是而昨非。"], "intro": "本文乃作者四十一歲辭官彭澤令時所作。作者於東晉安帝（司馬德宗）義熙元年（公元四零五）八月補彭澤（故治在今江西湖口縣東）令，十一月辭職。據蕭統所撰《陶淵明傳》，說是這年冬天，郡守派員來視察，照例縣令要整衣束帶去迎拜，他很不願意，歎道：「我怎能", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%AD%B8%E5%8E%BB%E4%BE%86%E8%BE%AD%E4%B8%A6%E5%BA%8F"}, {"title": "歸園田居（其一）", "author": "陶潛", "period": "魏晉", "form": "詩", "theme": "田園幽居", "mood": "majestic_peaks", "lines": ["少無適俗韻，性本愛邱山。誤落塵網中，一去三十年。", "羈鳥戀舊林，池魚思故淵。開荒南野際，守拙歸園田。", "方宅十餘畝，草屋八九間。榆柳蔭後簷，桃李羅堂前。", "曖曖遠人村，依依墟里煙。狗吠深巷中，雞鳴桑樹顛。", "戶庭無塵雜，虛室有餘閒。久在樊籠裏，復得返自然。"], "quote": ["少無適俗韻，性本愛邱山。誤落塵網中，一去三十年。", "羈鳥戀舊林，池魚思故淵。開荒南野際，守拙歸園田。", "方宅十餘畝，草屋八九間。榆柳蔭後簷，桃李羅堂前。", "曖曖遠人村，依依墟里煙。狗吠深巷中，雞鳴桑樹顛。"], "intro": "《歸園田居》共有五首，此處選取第一首，版本據《靖節先生集》卷二。東晉安帝義熙元年（四〇五）十一月，陶淵明辭去彭澤縣令，歸隱田園，第二年便作此組詩。其一（少無適俗韻）寫出作者決心離開官場，回歸自然的志向。他描繪出恬靜自然的田園景色，和富有人情", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%AD%B8%E5%9C%92%E7%94%B0%E5%B1%85%EF%BC%88%E5%85%B6%E4%B8%80%EF%BC%89"}, {"title": "歸園田居（其三）", "author": "陶潛", "period": "魏晉", "form": "詩", "theme": "田園幽居", "mood": "autumn_sunset", "lines": ["種豆南山下，草盛豆苗稀。晨興理荒穢，帶月荷鋤歸。", "道狹草木長，夕露霑我衣。衣霑不足惜，但使願無違。"], "quote": ["種豆南山下，草盛豆苗稀。晨興理荒穢，帶月荷鋤歸。", "道狹草木長，夕露霑我衣。衣霑不足惜，但使願無違。"], "intro": "《歸園田居》共有五首，此處選取第三首，版本據《靖節先生集》卷二。東晉安帝義熙元年（四○五）十一月，陶淵明辭去彭澤縣令，歸隱田園，第二年便作此組詩。其三（種豆南山下）寫回鄉後躬耕自食，苦中有樂的生活，並說明自己歸隱的心願是堅定的。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%AD%B8%E5%9C%92%E7%94%B0%E5%B1%85%EF%BC%88%E5%85%B6%E4%B8%89%EF%BC%89"}, {"title": "雜詩（其一）", "author": "陶潛", "period": "魏晉", "form": "詩", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["人生無根蒂，飄如陌上塵。", "分散逐風轉，此已非常身。", "落地為兄弟，何必骨肉親！", "得歡當作樂，斗酒聚比鄰。", "盛年不重來，一日難再晨，", "及時當勉勵，歲月不待人。"], "quote": ["人生無根蒂，飄如陌上塵。", "分散逐風轉，此已非常身。", "落地為兄弟，何必骨肉親！", "得歡當作樂，斗酒聚比鄰。"], "intro": "陶淵明的《雜詩》共十二首。前八首內容多歎息家貧年老，並有力圖自我開解、自我勉勵之意，應是他晚年所作。後四首多寫旅途奔波之苦，大概是他壯年時期出仕時所作。本詩是《雜詩》中的第一首。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%9B%9C%E8%A9%A9%EF%BC%88%E5%85%B6%E4%B8%80%EF%BC%89"}, {"title": "讀山海經（其一）", "author": "陶潛", "period": "魏晉", "form": "詩", "theme": "山水登臨", "mood": "vast_river", "lines": ["孟夏草木長，繞屋樹扶疏。眾鳥欣有托，吾亦愛吾廬。", "既耕亦已種，時還讀我書。窮巷隔深轍，頗回故人車。", "歡言酌春酒，摘我園中蔬。微雨從東來，好風與之俱。", "泛覽周王傳，流觀山海圖。俯仰終宇宙，不樂復何如？"], "quote": ["孟夏草木長，繞屋樹扶疏。眾鳥欣有托，吾亦愛吾廬。", "既耕亦已種，時還讀我書。窮巷隔深轍，頗回故人車。", "歡言酌春酒，摘我園中蔬。微雨從東來，好風與之俱。", "泛覽周王傳，流觀山海圖。俯仰終宇宙，不樂復何如？"], "intro": "《讀山海經》組詩十三首是陶淵明讀神話書籍《山海經》後所作。詩人藉《山海經》中的奇物異事來表述自己的志趣（如「形天舞戚」、「精衛填海」等），並經由想像空間抒發人世的苦悶，開闊其胸懷。本詩為全組第一首，寫隱居耕讀的自得之樂，也是這組詩的序言。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%AE%80%E5%B1%B1%E6%B5%B7%E7%B6%93%EF%BC%88%E5%85%B6%E4%B8%80%EF%BC%89"}, {"title": "典論論文", "author": "曹丕", "period": "魏晉", "form": "文", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["文人相輕，自古而然。傅毅之於班固，伯仲之間耳；而固小之，與弟超書曰︰「武仲以能屬文為蘭臺令史，下筆不能自休。」", "夫人善於自見，而文非一體，鮮能備善，是以各以所長，相輕所短。里語曰︰「家有弊帚，享之千金」。斯不自見之患也。", "今之文人︰魯國孔融文舉，廣陵陳琳孔璋，山陽王粲仲宣，北海徐幹偉長，陳留阮瑀元瑜，汝南應瑒德璉，東平劉楨公幹︰斯七子者，於學無所遺，於辭無所假，咸以自騁驥騄於千里，仰齊足而並馳。以此相服，亦良難矣！", "蓋君子審己以度人，故能免於斯累，而作論文。王粲長於辭賦；徐幹時有齊氣，然粲之匹也。如粲之《初征》《登樓》《槐賦》《征思》，幹之《玄猿》《漏卮》《圓扇》《橘賦》，雖張、蔡不過也。然於他文，未能稱是。", "琳、瑀之章表書記，今之雋也。應瑒和而不壯；劉楨壯而不密。孔融體氣高妙，有過人者；然不能持論，理不勝辭，以至乎雜以嘲戲；及其所善，揚、班儔也。", "常人貴遠賤近，向聲背實；又患闇於自見，謂己為賢。夫文本同而末異。蓋奏議宜雅，書論宜理，銘誄尚實，詩賦欲麗。此四科不同，故能之者偏也；唯通才能備其體。", "文以氣為主，氣之清濁有體，不可力強而致；譬諸音樂，曲度雖均，節奏同檢，至於引氣不齊，巧拙有素，雖在父兄，不能以移子弟。", "蓋文章，經國之大業，不朽之盛事。年壽有時而盡，榮樂止乎其身，二者必至之常期，未若文章之無窮。是以古之作者，寄身於翰墨，見意於篇籍；不假良史之辭，不托飛馳之勢，而聲名自傳於後。故西伯幽而演《易》，周旦顯而制禮；不以隱約而弗務，不以康樂而加思。", "夫然，則古人賤尺璧而重寸陰，懼乎時之過已！而人多不強力，貧賤則懾於飢寒，富貴則流於逸樂，遂營目前之務，而遺千載之功。日月逝於上，體貌衰於下，忽然與萬物遷化，斯志士之大痛也！", "融等已逝，唯幹著論，成一家言。"], "quote": ["文人相輕，自古而然。傅毅之於班固，伯仲之間耳；而固小之，與弟超書曰︰「武仲以能屬文為蘭臺令史，下筆不能自休。」", "夫人善於自見，而文非一體，鮮能備善，是以各以所長，相輕所短。里語曰︰「家有弊帚，享之千金」。斯不自見之患也。", "今之文人︰魯國孔融文舉，廣陵陳琳孔璋，山陽王粲仲宣，北海徐幹偉長，陳留阮瑀元瑜，汝南應瑒德璉，東平劉楨公幹︰斯七子者，於學無所遺，於辭無所假，咸以自騁驥騄於千里，仰齊足而並馳。以此相服，亦良難矣！", "蓋君子審己以度人，故能免於斯累，而作論文。王粲長於辭賦；徐幹時有齊氣，然粲之匹也。如粲之《初征》《登樓》《槐賦》《征思》，幹之《玄猿》《漏卮》《圓扇》《橘賦》，雖張、蔡不過也。然於他文，未能稱是。"], "intro": "本文是《典論》中的一篇。《典論》五卷，除本篇選入《昭明文選》外，其餘全已失傳。本篇評論當代文人的優劣、各種體裁的性質及文學作品的價值，是中國最早的一篇正式的文藝批評。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%85%B8%E8%AB%96%E8%AB%96%E6%96%87"}, {"title": "燕歌行（其一）", "author": "曹丕", "period": "魏晉", "form": "詩", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["秋風蕭瑟天氣涼，草木搖落露為霜。", "群燕辭歸雁南翔，念君客遊思斷腸。", "慊慊思歸戀故鄉，君何淹留寄他方？", "賤妾煢煢守空房，憂來思君不敢忘，不覺淚下沾衣裳。", "援琴鳴弦發清商，短歌微吟不能長。", "明月皎皎照我牀，星漢西流夜未央。", "牽牛織女遙相望，爾獨何辜限河梁？"], "quote": ["秋風蕭瑟天氣涼，草木搖落露為霜。", "群燕辭歸雁南翔，念君客遊思斷腸。", "慊慊思歸戀故鄉，君何淹留寄他方？", "賤妾煢煢守空房，憂來思君不敢忘，不覺淚下沾衣裳。"], "intro": "《燕歌行》選自《文選》卷二十七，是現存最早最完整的七言詩。《燕歌行》本是樂府舊題，屬《相和歌‧平調曲》。曹丕以此舊題填上新詞有二首，此處選其中一首。此詩以一個年輕女子的口吻，抒發對遠遊不歸的丈夫的思念。作者以候鳥之南歸怨遊子之不返，以牽牛、", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%87%95%E6%AD%8C%E8%A1%8C%EF%BC%88%E5%85%B6%E4%B8%80%EF%BC%89"}, {"title": "七步詩", "author": "曹植", "period": "魏晉", "form": "詩", "theme": "田園幽居", "mood": "ethereal", "lines": ["煮豆持作羹，", "漉豉以為汁。", "萁在釜下燃，", "豆在釜中泣。", "本是同根生，", "相煎何太急。"], "quote": ["煮豆持作羹，", "漉豉以為汁。", "萁在釜下燃，", "豆在釜中泣。"], "intro": "據《世說新語》中說，曹丕做了皇帝以後，對父親曹操在生時一直偏愛才華出眾的弟弟曹植總是心懷忌恨，於是故意令曹植在七步內作詩一首，不成就要殺掉他。語音未落，曹植便說出六句詩來；因被限定在七步內作成此詩，故後世稱之為《七步詩》。此詩取材於日常生活", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B8%83%E6%AD%A5%E8%A9%A9"}, {"title": "白馬篇", "author": "曹植", "period": "魏晉", "form": "詩", "theme": "邊塞豪放", "mood": "heroic", "lines": ["白馬飾金羈，連翩西北馳。借問誰家子？幽幷游俠兒。", "少小去鄉邑，揚聲沙漠垂。宿昔秉良弓，楛矢何參差！", "控弦破左的，右發摧月支。仰手接飛猱，俯身散馬蹄。", "狡捷過猴猿，勇剽若豹螭。邊城多警急，胡虜數遷移。", "羽檄從北來，厲馬登高隄。長驅蹈匈奴，左顧陵鮮卑。", "棄身鋒刃端，性命安可懷？父母且不顧，何言子與妻？", "名編壯士籍，不得中顧私。捐軀赴國難，視死忽如歸！"], "quote": ["白馬飾金羈，連翩西北馳。借問誰家子？幽幷游俠兒。", "少小去鄉邑，揚聲沙漠垂。宿昔秉良弓，楛矢何參差！", "控弦破左的，右發摧月支。仰手接飛猱，俯身散馬蹄。", "狡捷過猴猿，勇剽若豹螭。邊城多警急，胡虜數遷移。"], "intro": "《白馬篇》是樂府歌辭的一個曲調，屬於「雜曲歌辭」，宋郭茂倩在其所選《樂府詩集》裏解釋說：「白馬者，見乘白馬而為此曲，言人當立功立事，盡力為國，不可念私也。」《文選》註云：「此即所謂『閒居非吾志，甘心赴國憂』也。」都已道出了這首詩的主題。作者", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%99%BD%E9%A6%AC%E7%AF%87"}, {"title": "與楊德祖書", "author": "曹植", "period": "魏晉", "form": "文", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["植白︰數日不見，思子為勞，想同之也。僕少小好為文章，迄至於今，二十有五年矣。然今世作者，可略而言也。昔仲宣獨步於漢南，孔璋鷹揚於河朔，偉長擅名於青土，公幹振藻於海隅，德璉發跡於大魏，足下高視於上京。", "當此之時，人人自謂握靈蛇之珠，家家自謂抱荊山之玉。吾王於是設天網以該之，頓八紘以掩之，今悉集茲國矣。", "然此數子，猶不能飛軒絕跡，一舉千里。以孔璋之才，不閑於辭賦，而多自謂能與司馬長卿同風；譬畫虎不成，反為狗也。前有書嘲之，反作論盛道僕贊其文。夫鍾期不失聽，於今稱之；吾亦不能妄歎者，畏後世之嗤余也。", "世人著述，不能無病。僕常好人譏彈其文，有不善者，應時改定。昔丁敬禮常作小文，使僕潤飾之；僕自以才不過若人，辭不為也。敬禮謂僕︰「卿何所疑難？文之佳惡，吾自得之，後世誰相知定吾文者邪？」吾常歎此達言，以為美談。", "昔尼父之文辭，與人通流；至於制《春秋》，游、夏之徒，乃不能措一辭。過此而言不病者，吾未之見也。", "蓋有南威之容，乃可以論於淑媛；有龍淵之利，乃可以議於斷割。劉季緒才不能逮於作者，而好詆訶文章，掎摭利病。昔田巴毀五帝，罪三王，呰五霸於稷下，一旦而服千人；魯連一說，使終身杜口。", "劉生之辯，未若田氏；今之仲連，求之不難，可無息乎？人各有好尚，蘭茞蓀蕙之芳，眾人所好，而海畔有逐臭之夫；「咸池」「六莖」之發，眾人所共樂，而墨翟有非之之論，豈可同哉？", "今往僕少小所著辭賦一通相與。夫街談巷說，必有可采；擊轅之歌，有應「風」「雅」；匹夫之思，未易輕棄也。辭賦小道，固未足以揄揚大義，彰示來世也。昔揚子雲，先朝執戟之臣耳，猶稱壯夫不為也。", "吾雖德薄，位為蕃侯，猶庶幾戮力上國，流惠下民，建永世之業，流金石之功；豈徒以翰墨為勳績，辭賦為君子哉？若吾志未果，吾道不行，則將采庶官之實錄，辯時俗之得失，定仁義之衷，成一家之言；雖未能藏之於名山，將以傳之於同好。", "非要之皓首，豈今日之論乎?其言之不慙，恃惠子之知我也。明早相迎，書不盡懷。植白。"], "quote": ["植白︰數日不見，思子為勞，想同之也。僕少小好為文章，迄至於今，二十有五年矣。然今世作者，可略而言也。昔仲宣獨步於漢南，孔璋鷹揚於河朔，偉長擅名於青土，公幹振藻於海隅，德璉發跡於大魏，足下高視於上京。", "當此之時，人人自謂握靈蛇之珠，家家自謂抱荊山之玉。吾王於是設天網以該之，頓八紘以掩之，今悉集茲國矣。", "然此數子，猶不能飛軒絕跡，一舉千里。以孔璋之才，不閑於辭賦，而多自謂能與司馬長卿同風；譬畫虎不成，反為狗也。前有書嘲之，反作論盛道僕贊其文。夫鍾期不失聽，於今稱之；吾亦不能妄歎者，畏後世之嗤余也。", "世人著述，不能無病。僕常好人譏彈其文，有不善者，應時改定。昔丁敬禮常作小文，使僕潤飾之；僕自以才不過若人，辭不為也。敬禮謂僕︰「卿何所疑難？文之佳惡，吾自得之，後世誰相知定吾文者邪？」吾常歎此達言，以為美談。"], "intro": "楊德祖，即楊修（公元一七三——二一九），德祖是字；弘農郡華陰（今陝西的一縣）人。聰敏好學，富於幾決；建安中，舉孝廉，除郎中，後為曹操主簿。惟才氣太高，好賣弄小聰明，見忌於曹操，終為所殺。他和曹植很友善，互相愛慕。本文作於建安二十一年（公元二", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%88%87%E6%A5%8A%E5%BE%B7%E7%A5%96%E6%9B%B8"}, {"title": "贈白馬王彪並序", "author": "曹植", "period": "魏晉", "form": "詩", "theme": "邊塞豪放", "mood": "snow_winter", "lines": ["黃初四年五月，白馬王任城王與余俱朝京師，會節氣，到洛陽，任城王薨。至七月，與白馬王還國，後有司以二王歸藩，道路宜異宿止，意毒恨之，蓋以大別在數日，是用自剖，與王辭焉，憤而成篇。", "謁帝承明廬，逝將歸舊疆。清晨發皇邑，日夕過首陽。伊洛廣且深，欲濟川無梁；汎舟越洪濤，怨彼東路長。顧瞻戀城闕，引領情內傷！", "太谷何寥廓，山樹鬱蒼蒼。霖雨泥我塗，流潦浩縱橫。中逵絕無軌，改轍登高岡；修坂造雲日，我馬玄以黃。", "玄黃猶能進，我思鬱以紆。鬱紆將何念？親愛在離居。本圖相與偕，中更不克俱。鴟梟鳴衡軛，豺狼當路衢，蒼蠅間白黑，纔巧令親疏。欲還絕無蹊，攬轡止踟躕！", "踟躕亦何留？相思無終極。秋風發微涼，寒蟬鳴我側。原野何蕭條！白日忽西匿，歸鳥赴喬林，翩翩厲羽翼；孤獸走索群，銜草不遑食。感物傷我懷，撫心長太息！", "太息將何為？天命與我違。奈何念同生，一往形不歸，孤魂翔故域，靈柩寄京師。存者忽復過，亡沒身自衰！人生處一世，去若朝露晞，年在桑榆間，影響不能追。自顧非金石，咄唶令心悲！", "心悲動我神，棄置莫復陳！丈夫志四海，萬里猶比鄰；恩愛苟不虧，在遠分日親。何必同衾幬，然後展殷勤；憂思成疾疹，無乃兒女仁？倉卒骨肉情，能不懷苦辛！", "苦辛何慮思？天命信可疑。虛無求列仙，松子久吾欺。變故在斯須，百年誰能持？離別永無會，執手將何時？王其愛玉體，俱享黃髮期！收淚即長路，援筆從此辭。"], "quote": ["黃初四年五月，白馬王任城王與余俱朝京師，會節氣，到洛陽，任城王薨。至七月，與白馬王還國，後有司以二王歸藩，道路宜異宿止，意毒恨之，蓋以大別在數日，是用自剖，與王辭焉，憤而成篇。", "謁帝承明廬，逝將歸舊疆。清晨發皇邑，日夕過首陽。伊洛廣且深，欲濟川無梁；汎舟越洪濤，怨彼東路長。顧瞻戀城闕，引領情內傷！", "太谷何寥廓，山樹鬱蒼蒼。霖雨泥我塗，流潦浩縱橫。中逵絕無軌，改轍登高岡；修坂造雲日，我馬玄以黃。", "玄黃猶能進，我思鬱以紆。鬱紆將何念？親愛在離居。本圖相與偕，中更不克俱。鴟梟鳴衡軛，豺狼當路衢，蒼蠅間白黑，纔巧令親疏。欲還絕無蹊，攬轡止踟躕！"], "intro": "曹丕即位後，諸兄弟全封王，白馬王曹彪、任城王曹彰與曹植同於黃初（魏文帝曹丕年號）四年（公元二二三）入朝京師洛陽，曹彰在洛陽死去，曹彪曹植不久又受催逼歸藩，路上且不許共在一處，曹植知道這些全出於曹丕的忌害，感傷兄弟的相殘，恐怕自己和曹彪也朝不", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B4%88%E7%99%BD%E9%A6%AC%E7%8E%8B%E5%BD%AA%E4%B8%A6%E5%BA%8F"}, {"title": "出師表", "author": "諸葛亮", "period": "魏晉", "form": "文", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["先帝創業未半，而中道崩殂；今天下三分，益州疲弊，此誠危急存亡之秋也！然侍衞之臣，不懈於內；忠志之士，忘身於外者，蓋追先帝之殊遇，欲報之於陛下也。", "誠宜開張聖聽，以光先帝遺德，恢弘志士之氣﹔不宜妄自菲薄，引喻失義，以塞忠諫之路也。", "宮中、府中，俱為一體；陟罰臧否，不宜異同。若有作姦、犯科，及為忠善者，宜付有司，論其刑賞，以昭陛下平明之治；不宜偏私，使內外異法也。", "侍中、侍郎郭攸之、費禕、董允等，此皆良實，志慮忠純，是以先帝簡拔以遺陛下。愚以為宮中之事，事無大小，悉以咨之，然後施行，必能裨補闕漏，有所廣益。", "將軍向寵，性行淑均，曉暢軍事，試用於昔日，先帝稱之曰「能」，是以眾議舉寵為督。愚以為營中之事，悉以咨之，必能使行陣和睦，優劣得所。", "親賢臣，遠小人，此先漢所以興隆也﹔親小人，遠賢臣，此後漢所以傾頹也。先帝在時，每與臣論此事，未嘗不歎息痛恨於桓、靈也！侍中、尚書、長史、參軍，此悉貞良死節之臣，願陛下親之、信之，則漢室之隆，可計日而待也。", "臣本布衣，躬耕於南陽，苟全性命於亂世，不求聞達於諸侯。先帝不以臣卑鄙，猥自枉屈，三顧臣於草廬之中，諮臣以當世之事；由是感激，遂許先帝以驅馳。", "後值傾覆，受任於敗軍之際，奉命於危難之間，爾來二十有一年矣。先帝知臣謹慎，故臨崩寄臣以大事也。受命以來，夙夜憂歎，恐託付不效，以傷先帝之明。故五月渡瀘，深入不毛。", "今南方已定，兵甲已足，當獎率三軍，北定中原，庶竭駑鈍，攘除姦凶，興復漢室，還於舊都。此臣所以報先帝而忠陛下之職分也。至於斟酌損益，進盡忠言，則攸之、禕、允之任也。", "願陛下託臣以討賊興復之效；不效，則治臣之罪，以告先帝之靈。若無興德之言，則責攸之、禕、允等之慢，以彰其咎。陛下亦宜自謀，以諮諏善道，察納雅言，深追先帝遺詔。", "臣不勝受恩感激。今當遠離，臨表涕零，不知所言！"], "quote": ["先帝創業未半，而中道崩殂；今天下三分，益州疲弊，此誠危急存亡之秋也！然侍衞之臣，不懈於內；忠志之士，忘身於外者，蓋追先帝之殊遇，欲報之於陛下也。", "誠宜開張聖聽，以光先帝遺德，恢弘志士之氣﹔不宜妄自菲薄，引喻失義，以塞忠諫之路也。", "宮中、府中，俱為一體；陟罰臧否，不宜異同。若有作姦、犯科，及為忠善者，宜付有司，論其刑賞，以昭陛下平明之治；不宜偏私，使內外異法也。", "侍中、侍郎郭攸之、費禕、董允等，此皆良實，志慮忠純，是以先帝簡拔以遺陛下。愚以為宮中之事，事無大小，悉以咨之，然後施行，必能裨補闕漏，有所廣益。"], "intro": "蜀漢建興五年（公元二二七），諸葛亮親率大軍北伐曹魏，出發前寫了這一篇表，向後主劉禪（劉備的兒子）辭行。 許多古文選本，稱此篇為《前出師表》，另有所謂《後出師表》。但陳壽《三國志》、蕭統《文選》、姚鼐《古文辭類篡》等書，都不載《後出師表》，有", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%87%BA%E5%B8%AB%E8%A1%A8"}, {"title": "石壁精舍還湖中作", "author": "謝靈運", "period": "魏晉", "form": "詩", "theme": "山水登臨", "mood": "autumn_sunset", "lines": ["昏旦變氣候，山水含清暉。清暉能娛人，遊子憺忘歸。", "出谷日尚早，入舟陽已微。林壑斂暝色，雲霞收夕霏。", "芰荷迭映蔚，蒲稗相因依。披拂趨南徑，愉悅偃東扉。", "慮澹物自輕，意愜理無違。寄言攝生客，試用此道推。"], "quote": ["昏旦變氣候，山水含清暉。清暉能娛人，遊子憺忘歸。", "出谷日尚早，入舟陽已微。林壑斂暝色，雲霞收夕霏。", "芰荷迭映蔚，蒲稗相因依。披拂趨南徑，愉悅偃東扉。", "慮澹物自輕，意愜理無違。寄言攝生客，試用此道推。"], "intro": "本篇是山水詩中的名作，大約寫於元嘉元年至三年（西元四二四──四二六年）之間。宋景平元年（西元四二三年），謝靈運稱病辭去永嘉（治所在今浙江溫州）太守職務，回到故鄉會稽始寧（今浙江上虞）的莊園。這裏曾是其曾祖謝安高臥之地，又是他祖父謝玄最初經營", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%9F%B3%E5%A3%81%E7%B2%BE%E8%88%8D%E9%82%84%E6%B9%96%E4%B8%AD%E4%BD%9C"}, {"title": "與宋元思書", "author": "吳均", "period": "南北朝", "form": "文", "theme": "山水登臨", "mood": "snow_winter", "lines": ["風煙俱淨，天山共色，從流飄蕩，任意東西。自富陽至桐廬，一百許里，奇山異水，天下獨絕。", "水皆縹碧，千丈見底；游魚細石，直視無礙。急湍甚箭，猛浪若奔。夾峰高山，皆生寒樹。負勢競上，互相軒邈，爭高直指，千百成峰。泉水激石，泠泠作響。好鳥相鳴，嚶嚶成韻。", "蟬則千轉不窮，猨則百叫無絕。鳶飛戾天者，望峰息心；經綸世務者，窺谷忘反。橫柯上蔽，在晝猶昏；疎條交映，有時見日。"], "quote": ["風煙俱淨，天山共色，從流飄蕩，任意東西。自富陽至桐廬，一百許里，奇山異水，天下獨絕。", "水皆縹碧，千丈見底；游魚細石，直視無礙。急湍甚箭，猛浪若奔。夾峰高山，皆生寒樹。負勢競上，互相軒邈，爭高直指，千百成峰。泉水激石，泠泠作響。好鳥相鳴，嚶嚶成韻。", "蟬則千轉不窮，猨則百叫無絕。鳶飛戾天者，望峰息心；經綸世務者，窺谷忘反。橫柯上蔽，在晝猶昏；疎條交映，有時見日。"], "intro": "魏晉南北朝時期，政治黑暗，社會動盪，不少知識分子寄情山水來排解心中的苦悶。《與宋元思書》是吳均以駢文形式寫給宋元思的一封信，文中也融合山水來抒發心中之情，一作《與朱元思書》。《與宋元思書》意即「給宋元思的信」，但看來完全不見書信的格式，大概", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%88%87%E5%AE%8B%E5%85%83%E6%80%9D%E6%9B%B8"}, {"title": "子夜歌", "author": "南北朝樂府", "period": "南北朝", "form": "詩", "theme": "歲時雪月", "mood": "ethereal", "lines": ["其一", "始欲識郎時，兩心望如一。", "理絲入殘機，何悟不成匹。", "其二", "夜長不得眠，明月何灼灼。", "想聞歡喚聲，虛應空中諾。"], "quote": ["其一", "始欲識郎時，兩心望如一。", "理絲入殘機，何悟不成匹。", "其二"], "intro": "《子夜歌》屬《清商曲・吳聲歌曲》，是南朝樂府民歌。《舊唐書・音樂志》：「《子夜》，晉曲也。晉有女子夜，造此聲，聲過哀苦。」《樂府詩集》載歌辭四十二首，都是男女戀歌。此選二首。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%AD%90%E5%A4%9C%E6%AD%8C"}, {"title": "木蘭詩", "author": "南北朝樂府", "period": "南北朝", "form": "詩", "theme": "邊塞豪放", "mood": "snow_winter", "lines": ["唧唧復唧唧，木蘭當戶織。不聞機杼聲，唯聞女歎息。問女何所思？問女何所憶？女亦無所思，女亦無所憶。昨夜見軍帖，可汗大點兵。", "軍書十二卷，卷卷有爺名。阿爺無大兒，木蘭無長兄。願為市鞍馬，從此替爺征。東市買駿馬，西市買鞍韉，南市買轡頭，北市買長鞭。", "旦辭爺孃去，暮宿黃河邊。不聞爺孃喚女聲，但聞黃河流水鳴濺濺。旦辭黃河去，暮至黑山頭，不聞爺孃喚女聲，但聞燕山胡騎鳴啾啾。", "萬里赴戎機，關山度若飛。朔氣傳金柝，寒光照鐵衣。將軍百戰死，壯士十年歸。", "歸來見天子，天子坐明堂。策勳十二轉，賞賜百千強。可汗問所欲，木蘭不用尚書郎，願馳千里足，送兒還故鄉。", "爺孃聞女來，出郭相扶將。阿姊聞妹來，當戶理紅妝。小弟聞姊來，磨刀霍霍向豬羊。開我東閣門，坐我西閣床。脫我戰時袍，著我舊時裳。", "當窗理雲鬢，挂鏡帖花黃。出門看火伴，火伴始驚惶。同行十二年，不知木蘭是女郎。", "雄兔腳撲朔，雌兔眼迷離。兩兔傍地走，安能辨我是雄雌？"], "quote": ["唧唧復唧唧，木蘭當戶織。不聞機杼聲，唯聞女歎息。問女何所思？問女何所憶？女亦無所思，女亦無所憶。昨夜見軍帖，可汗大點兵。", "軍書十二卷，卷卷有爺名。阿爺無大兒，木蘭無長兄。願為市鞍馬，從此替爺征。東市買駿馬，西市買鞍韉，南市買轡頭，北市買長鞭。", "旦辭爺孃去，暮宿黃河邊。不聞爺孃喚女聲，但聞黃河流水鳴濺濺。旦辭黃河去，暮至黑山頭，不聞爺孃喚女聲，但聞燕山胡騎鳴啾啾。", "萬里赴戎機，關山度若飛。朔氣傳金柝，寒光照鐵衣。將軍百戰死，壯士十年歸。"], "intro": "本篇選自《樂府詩集》卷二十五，內容敍述古代孝女花木蘭代父從軍的故事。原題在《樂府詩集》內共有兩首，本課選錄第一首。詩中對木蘭的性格，無論從車前的溫靜嫻淑，與參軍後的剛毅勇武，都有細緻的刻劃。至於中段寫木蘭功成不居、淡泊名利的表現，和後半寫木", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9C%A8%E8%98%AD%E8%A9%A9"}, {"title": "敕勒歌", "author": "南北朝樂府", "period": "南北朝", "form": "詩", "theme": "春水花鳥", "mood": "majestic_peaks", "lines": ["敕勒川，陰山下。天似穹廬，籠蓋四野。天蒼蒼，野茫茫，風吹草低見牛羊。"], "quote": ["敕勒川，陰山下。天似穹廬，籠蓋四野。天蒼蒼，野茫茫，風吹草低見牛羊。"], "intro": "《敕勒歌》選自《樂府詩集》卷八十六，是北朝敕勒族的一首民歌。敕勒，又名鐵勒，種族名，為匈奴族的後裔，北齊時居於朔丹（今山西北部）一帶。這首民歌描繪了遼闊的草原景象和北方民族的遊牧生活，文字簡樸，格調沉雄。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%95%95%E5%8B%92%E6%AD%8C"}, {"title": "答謝中書書（節錄）", "author": "陶弘景", "period": "南北朝", "form": "文", "theme": "山水登臨", "mood": "autumn_sunset", "lines": ["山川之美，古來共談。高峰入雲，清流見底。兩岸石壁，五色交輝。青林翠竹，四時俱備。曉霧將歇，猿鳥亂鳴；夕日欲頹，沉鱗競躍。實是欲界之仙都。自康樂以來，未復有能與其奇者。"], "quote": ["山川之美，古來共談。高峰入雲，清流見底。兩岸石壁，五色交輝。青林翠竹，四時俱備。曉霧將歇，猿鳥亂鳴；夕日欲頹，沉鱗競躍。實是欲界之仙都。自康樂以來，未復有能與其奇者。"], "intro": "本文是陶弘景給謝徵（一作謝微）原信的一部分。謝徵好學，善屬文，曾任中書舍人，故以官職稱其名。信的內容主要描述山水景色。據《南史》本傳所說，陶弘景「性愛山水，每經澗谷，必坐臥其間，吟詠盤桓，不能自已。」在這篇短小的文字中，可以看出他對自然的鍾", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%AD%94%E8%AC%9D%E4%B8%AD%E6%9B%B8%E6%9B%B8%EF%BC%88%E7%AF%80%E9%8C%84%EF%BC%89"}, {"title": "哀江南賦序", "author": "庾信", "period": "南北朝", "form": "文", "theme": "江河湖海", "mood": "snow_winter", "lines": ["粵以戊辰之年，建亥之月，大盜移國，金陵瓦解。余乃竄身荒谷，公私塗炭。華陽奔命，有去無歸，中興道銷，窮於甲戌。三日哭於都亭，三年囚於別館。天道周星，物極不反。傅燮之但悲身世，無處求生；袁安之每念王室，自然流涕。", "昔桓君山之志事，杜元凱之平生，並有著書，咸能自敍。潘岳之文采，始述家風；陸機之辭賦，先陳世德。信年始二毛，即逢喪亂，藐是流離，至於暮齒。燕歌遠別，悲不自勝；楚老相逢，泣將何及！", "畏南山之雨，忽踐秦庭；讓東海之濱，遂餐周粟。下亭漂泊，高橋羈旅。楚歌非取樂之方，魯酒無忘憂之用。追為此賦，聊以記言，不無危苦之辭，惟以悲哀為主。", "日暮途遠，人間何世！將軍一去，大樹飄零；壯士不還，寒風蕭瑟。荊璧睨柱，受連城而見欺；載書橫階，捧珠盤而不定。鍾儀君子，入就南冠之囚；季孫行人，留守西河之館。申包胥之頓地，碎之以首；蔡威公之淚盡，加之以血。釣臺移柳，非玉關之可望；華亭鶴唳，豈河橋之可聞！", "孫策以天下為三分，眾纔一旅；項籍用江東之子弟，人惟八千。遂乃分裂山河，宰割天下。豈有百萬義師，一朝卷甲，芟夷斬伐，如草木焉！江淮無涯岸之阻；亭壁無藩籬之固。頭會箕斂者，合從締交；鋤耰棘矜者，因利乘便。", "將非江表王氣，終於三百年乎？是知并吞六合，不免軹道之災；混一車書，無救平陽之禍。嗚呼！山嶽崩頹，既履危亡之運；春秋迭代，必有去故之悲。天意人事，可以悽愴傷心者矣！", "況復舟楫路窮，星漢非乘槎可上；風飆道阻，蓬萊無可到之期。窮者欲達其言，勞者須歌其事。陸士衡聞而撫掌，是所甘心；張平子見而陋之，固其宜矣！"], "quote": ["粵以戊辰之年，建亥之月，大盜移國，金陵瓦解。余乃竄身荒谷，公私塗炭。華陽奔命，有去無歸，中興道銷，窮於甲戌。三日哭於都亭，三年囚於別館。天道周星，物極不反。傅燮之但悲身世，無處求生；袁安之每念王室，自然流涕。", "昔桓君山之志事，杜元凱之平生，並有著書，咸能自敍。潘岳之文采，始述家風；陸機之辭賦，先陳世德。信年始二毛，即逢喪亂，藐是流離，至於暮齒。燕歌遠別，悲不自勝；楚老相逢，泣將何及！", "畏南山之雨，忽踐秦庭；讓東海之濱，遂餐周粟。下亭漂泊，高橋羈旅。楚歌非取樂之方，魯酒無忘憂之用。追為此賦，聊以記言，不無危苦之辭，惟以悲哀為主。", "日暮途遠，人間何世！將軍一去，大樹飄零；壯士不還，寒風蕭瑟。荊璧睨柱，受連城而見欺；載書橫階，捧珠盤而不定。鍾儀君子，入就南冠之囚；季孫行人，留守西河之館。申包胥之頓地，碎之以首；蔡威公之淚盡，加之以血。釣臺移柳，非玉關之可望；華亭鶴唳，豈河橋之可聞！"], "intro": "本文乃作者的辭賦代表作《哀江南賦》之序文。「哀江南」一詞，出於《楚辭‧招魂》，原句是「目極千里兮傷春心，魂兮歸來哀江南」，乃為楚國之喪亂而哀痛，江南指楚。作者借用此詞為賦，哀悼南梁之亂亡，因南梁亦在江南。據《北史》本傳：「信雖位望通顯，常作", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%93%80%E6%B1%9F%E5%8D%97%E8%B3%A6%E5%BA%8F"}, {"title": "重別周尚書（其一）", "author": "庾信", "period": "南北朝", "form": "詩", "theme": "送別行旅", "mood": "autumn_sunset", "lines": ["陽關萬里道，不見一人歸。惟有河邊雁，秋來南向飛。"], "quote": ["陽關萬里道，不見一人歸。惟有河邊雁，秋來南向飛。"], "intro": "庾信《重別周尚書》選自《庾子山集注》卷四，原題共二首，這是第一首。周尚書即周弘正，陳文帝時曾出使北周，南歸時庾信以詩贈別。由於之前已曾以詩為周贈別，故題「重別」。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%87%8D%E5%88%A5%E5%91%A8%E5%B0%9A%E6%9B%B8%EF%BC%88%E5%85%B6%E4%B8%80%EF%BC%89"}, {"title": "洛陽伽藍記兩則", "author": "楊衒之", "period": "南北朝", "form": "文", "theme": "田園幽居", "mood": "autumn_sunset", "lines": ["景林寺", "景林寺在開陽門內御道東。講殿疊起，房廡連屬；丹楹炫日，繡桷迎風，實為勝地。寺西有園，多饒奇果。春鳥秋蟬，鳴聲相續。中有禪房一所，內置祇洹精舍，形製雖小，巧構難比。加以禪閣虛靜，隱室凝邃；嘉樹夾牖，芳杜匝階。", "雖云朝市，想同巖谷。靜行之僧，繩坐其內，餐風服道，結跏數息。", "有石銘一所，國子博士盧白頭為其文。白頭字景裕，范陽人也。性愛恬靜，邱園放傲；學極六經，疏通百氏。普泰初，起家為國子博士，雖在朱門，以著述為事，注《周易》行於世。", "白馬寺", "白馬寺，漢明帝所立也。佛入中國之始。寺在西陽門外三里御道南。帝夢金神丈六，項背日月光明，金神號曰「佛」。遣使向西域求之，乃得經象焉。時白馬負而來，因以為名。帝崩，起祇洹於陵上。", "自此以後，百姓冢上或作浮圖焉。寺上經函，至今猶存，常燒香供養之。經函時放光明，耀於堂宇。是以道俗禮敬之，如仰真容。", "浮圖前，柰林蒲萄異於餘處，枝葉繁衍，子實甚大。柰林實重七斤，蒲萄實偉於棗，味並殊美，冠於中京。帝至熟時，常詣取之，或復賜宮人。宮入得之，轉餉親戚，以為奇味。得者不敢輒食，乃歷數家。京師語曰︰「白馬甜榴，一實直牛。」"], "quote": ["景林寺", "景林寺在開陽門內御道東。講殿疊起，房廡連屬；丹楹炫日，繡桷迎風，實為勝地。寺西有園，多饒奇果。春鳥秋蟬，鳴聲相續。中有禪房一所，內置祇洹精舍，形製雖小，巧構難比。加以禪閣虛靜，隱室凝邃；嘉樹夾牖，芳杜匝階。", "雖云朝市，想同巖谷。靜行之僧，繩坐其內，餐風服道，結跏數息。", "有石銘一所，國子博士盧白頭為其文。白頭字景裕，范陽人也。性愛恬靜，邱園放傲；學極六經，疏通百氏。普泰初，起家為國子博士，雖在朱門，以著述為事，注《周易》行於世。"], "intro": "北魏自孝文帝（元宏）於太和十七年（公元四九三）遷都洛陽以後，因為信仰佛教，在洛陽大建佛寺；常時洛陽城中有新舊佛寺一百所，僧尼二千餘人。其後各朝繼續興建，蔚為大觀。但自孝莊帝起，北魏的大將爾朱榮反，兵陷洛陽，六年之間，洛陽連遭數次洗劫，佛寺便", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B4%9B%E9%99%BD%E4%BC%BD%E8%97%8D%E8%A8%98%E5%85%A9%E5%89%87"}, {"title": "周處除三害", "author": "劉義慶", "period": "南北朝", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["周處年少時，兇強俠氣，為鄉里所患。又義興水中有蛟，山中有白額虎，並皆暴犯百姓。義興人謂為「三橫」，而處尤劇。或說處殺虎斬蛟，實冀三橫唯餘其一。處即刺殺虎，又入水擊蛟。蛟或浮或沒，行數十里，處與之俱。經三日三夜。鄉里皆謂已死，更相慶。竟殺蛟而出，聞里人相慶，始知為人情所患，有自改意。"], "quote": ["周處年少時，兇強俠氣，為鄉里所患。又義興水中有蛟，山中有白額虎，並皆暴犯百姓。義興人謂為「三橫」，而處尤劇。或說處殺虎斬蛟，實冀三橫唯餘其一。處即刺殺虎，又入水擊蛟。蛟或浮或沒，行數十里，處與之俱。經三日三夜。鄉里皆謂已死，更相慶。竟殺蛟而出，聞里人相慶，始知為人情所患，有自改意。"], "intro": "《世說新語》又稱《世說》，是一本筆記小說集。全書分「德行」、「言語」、「政事」、「文學」等三十六門，每門少則幾篇，多則數十篇乃至上百篇。內容主要記錄了漢末、魏、晉時期士大夫的言談和軼聞趣事，反映了當時士族的精神面貌和社會風尚。全書語言精煉，", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%91%A8%E8%99%95%E9%99%A4%E4%B8%89%E5%AE%B3"}, {"title": "荀巨伯遠看友人疾", "author": "劉義慶", "period": "南北朝", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["荀巨伯遠看友人疾，值胡賊攻郡，友人語巨伯曰︰「吾今死矣，子可去！」巨伯曰︰「遠來相視，子令吾去；敗義以求生，豈荀巨伯所行邪？」賊既至，謂巨伯曰︰「大軍至，一郡盡空，汝何男子，而敢獨止？」巨伯曰︰「友人有疾，不忍委之，寧以我身代友人命。」賊相謂曰︰「我輩無義之人，而入有義之國！」遂班軍而還，一郡並獲全。"], "quote": ["荀巨伯遠看友人疾，值胡賊攻郡，友人語巨伯曰︰「吾今死矣，子可去！」巨伯曰︰「遠來相視，子令吾去；敗義以求生，豈荀巨伯所行邪？」賊既至，謂巨伯曰︰「大軍至，一郡盡空，汝何男子，而敢獨止？」巨伯曰︰「友人有疾，不忍委之，寧以我身代友人命。」賊相謂曰︰「我輩無義之人，而入有義之國！」遂班軍而還，一郡並獲全。"], "intro": "《世說新語》原名《世說》，又名《世說新書》。及至宋代，因與漢代劉向《世說》區別，改稱《世說新語》。自東漢後，月旦之風始盛，魏晉崇尚清談。《世說新語》一書就在這樣的背景下寫成，內容主要記載東漢後期到晉宋間名士的言行軼事，寫作原材料或來自史料，", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%8D%80%E5%B7%A8%E4%BC%AF%E9%81%A0%E7%9C%8B%E5%8F%8B%E4%BA%BA%E7%96%BE"}, {"title": "望梅止渴", "author": "劉義慶", "period": "南北朝", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["魏武行役失汲道，軍皆渴，乃令曰︰「前有大梅林，饒子，甘酸可以解渴。」士卒聞之，口皆出水，乘此得及前源。"], "quote": ["魏武行役失汲道，軍皆渴，乃令曰︰「前有大梅林，饒子，甘酸可以解渴。」士卒聞之，口皆出水，乘此得及前源。"], "intro": "《世說新語》又稱《世說》，是一本筆記小說集。全書分「德行」、「言語」、「政事」、「文學」等三十六門，每門少則幾篇，多則數十篇乃至上百篇。內容主要記錄了漢末、魏、晉時期士大夫的言談和軼聞趣事，反映了當時士族的精神面貌和社會風尚。全書語言精煉，", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9C%9B%E6%A2%85%E6%AD%A2%E6%B8%B4"}, {"title": "過江諸人", "author": "劉義慶", "period": "南北朝", "form": "文", "theme": "江河湖海", "mood": "vast_river", "lines": ["過江諸人，每至美日，輒相邀新亭，藉卉飲宴。周侯中坐而歎曰︰「風景不殊，正自有山河之異。」皆相視流淚。唯王丞相愀然變色，曰︰「當共戮力王室，克復神州，何至作楚囚相對！」"], "quote": ["過江諸人，每至美日，輒相邀新亭，藉卉飲宴。周侯中坐而歎曰︰「風景不殊，正自有山河之異。」皆相視流淚。唯王丞相愀然變色，曰︰「當共戮力王室，克復神州，何至作楚囚相對！」"], "intro": "《世說新語》，舊稱《世說新書》，至趙宋始易今名。此書記錄自漢末以迄東晉間之雜事，兼述諸名流之言辭；以「德行」「言語」「政事」「文學」等分為三十六類，一事多者百餘字，少或十數字。著墨不多，而當年朝野上下之習俗風尚，魏晉人物之言論丰采，無不歷歷", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%81%8E%E6%B1%9F%E8%AB%B8%E4%BA%BA"}, {"title": "管寧華歆", "author": "劉義慶", "period": "南北朝", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["管寧、華歆，共園中鋤菜，見地有片金，管揮鋤與瓦石不異，華捉而擲去之。又嘗同席讀書，有乘軒冕過門者，寧讀如故，歆廢書出看。寧割席分坐，曰︰「子非吾友也。」"], "quote": ["管寧、華歆，共園中鋤菜，見地有片金，管揮鋤與瓦石不異，華捉而擲去之。又嘗同席讀書，有乘軒冕過門者，寧讀如故，歆廢書出看。寧割席分坐，曰︰「子非吾友也。」"], "intro": "《世說新語》，舊稱《世說新書》，至趙宋始易今名。此書記錄自漢末以迄東晉間之雜事，兼述諸名流之言辭；以「德行」「言語」「政事」「文學」等分為三十六類，一事多者百餘字，少或十數字。著墨不多，而當年朝野上下之習俗風尚，魏晉人物之言論丰采，無不歷歷", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%AE%A1%E5%AF%A7%E8%8F%AF%E6%AD%86"}, {"title": "謝太傅寒雪日內集", "author": "劉義慶", "period": "南北朝", "form": "文", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["謝太傅寒雪日內集，與兒女講論文義，俄而雪驟，公欣然曰︰「白雪紛紛何所似？」兄子胡兒曰︰「撒鹽空中差可擬。」兄女曰︰「未若柳絮因風起。」公大笑樂。即公大兄無弈女，左將軍王凝之妻也。"], "quote": ["謝太傅寒雪日內集，與兒女講論文義，俄而雪驟，公欣然曰︰「白雪紛紛何所似？」兄子胡兒曰︰「撒鹽空中差可擬。」兄女曰︰「未若柳絮因風起。」公大笑樂。即公大兄無弈女，左將軍王凝之妻也。"], "intro": "《世說新語》，舊稱《世說新書》，至趙宋始易今名。此書記錄自漢末以迄東晉間之雜事，兼述諸名流之言辭；以「德行」「言語」「政事」「文學」等分為三十六類，一事多者百餘字，少或十數字。著墨不多，而當年朝野上下之習俗風尚，魏晉人物之言論丰采，無不歷歷", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%AC%9D%E5%A4%AA%E5%82%85%E5%AF%92%E9%9B%AA%E6%97%A5%E5%85%A7%E9%9B%86"}, {"title": "文心雕龍・情采", "author": "劉勰", "period": "南北朝", "form": "文", "theme": "春水花鳥", "mood": "vast_river", "lines": ["聖賢書辭，總稱「文章」，非采而何？夫水性虛而淪漪結，木性實而花萼振；文附質也。虎豹無文，則鞹同犬羊；犀兕無文，而色資丹漆；質待文也。若乃綜述性靈，敷寫器象；鏤心鳥跡之中，織辭魚網之上；其為彪炳，縟采名矣。", "故立文之道，其理有三︰一曰「形文」，五色是也；二曰「聲文」，五音是也；三曰「情文」，五性是也。五色雜而成黼黻，五音比而成韶夏，五性發而為辭章，神理之數也。《孝經》垂典，喪「言不文」。故知君子常言，未嘗質也。老子疾偽，故稱「美言不信」，而五千精妙，則非棄美矣。", "莊周云︰「辯雕萬物。」謂「藻飾」也。韓非云︰「豔采辯說。」謂「綺麗」也。綺麗以豔說，藻飾以辯雕，文辭之變，於斯極矣！研味李老，則知文質附乎性情；詳覽莊韓，則見華實過乎淫侈。若擇源於涇渭之流，按轡於邪正之路，亦可以馭文采矣。", "夫鉛黛所以飾容，而盼倩生於淑姿；文彩所以飾言，而辯麗本於情性。故情者，文之經；辭者，理之緯。經正而後緯成，理定而後辭暢︰此立文之本源也。昔詩人什篇，為情而造文；辭人賦頌，為文而造情。何以明其然？", "蓋風雅之興，志思蓄憤；而吟咏情性，以諷其上︰此為情而造文也。諸子之徒，心非鬱陶；苟馳夸飾，鬻聲釣世︰此為文而造情也。故為情者，要約而寫真；為文者，淫麗而煩濫。而後之作者，採濫忽真，遠棄風雅，近師辭賦；故體情之製日疎，逐文之篇愈盛。", "故有志深軒冕，而汎詠皋壤；心纏幾務，而虛述人外。真宰弗存，翩其反矣！。", "夫桃李不言而成蹊，有實存也；男子樹蘭而不芳，無其情也。夫以草木之微，依情待實；況乎文章，述志為本？言與志反，文豈足徵？是以聯辭結采，將欲明經；采濫辭詭，則心理愈翳。固知翠綸桂餌，反所以失魚。言隱榮華，殆謂此也。", "是以衣錦褧衣，惡文太章；賁象窮白，貴乎反本。夫能設謨以位理，擬地以置心；心定而後結音，理正而後摛藻，使文不滅質，博不溺心，正采耀乎朱藍，閒色屏於紅紫；乃可謂雕琢其章，彬彬君子矣！贊曰︰", "言以文遠，誠哉斯驗！心術既形，英華乃贍。吳錦好渝，舜英徒豔。繁采寡情，味之必厭。"], "quote": ["聖賢書辭，總稱「文章」，非采而何？夫水性虛而淪漪結，木性實而花萼振；文附質也。虎豹無文，則鞹同犬羊；犀兕無文，而色資丹漆；質待文也。若乃綜述性靈，敷寫器象；鏤心鳥跡之中，織辭魚網之上；其為彪炳，縟采名矣。", "故立文之道，其理有三︰一曰「形文」，五色是也；二曰「聲文」，五音是也；三曰「情文」，五性是也。五色雜而成黼黻，五音比而成韶夏，五性發而為辭章，神理之數也。《孝經》垂典，喪「言不文」。故知君子常言，未嘗質也。老子疾偽，故稱「美言不信」，而五千精妙，則非棄美矣。", "莊周云︰「辯雕萬物。」謂「藻飾」也。韓非云︰「豔采辯說。」謂「綺麗」也。綺麗以豔說，藻飾以辯雕，文辭之變，於斯極矣！研味李老，則知文質附乎性情；詳覽莊韓，則見華實過乎淫侈。若擇源於涇渭之流，按轡於邪正之路，亦可以馭文采矣。", "夫鉛黛所以飾容，而盼倩生於淑姿；文彩所以飾言，而辯麗本於情性。故情者，文之經；辭者，理之緯。經正而後緯成，理定而後辭暢︰此立文之本源也。昔詩人什篇，為情而造文；辭人賦頌，為文而造情。何以明其然？"], "intro": "《文心雕龍》計十卷五十篇，據說只存四十九篇，《隱秀》一篇為後人補作。這是中國一部最早的文學批評，這一篇《情采》，便是這部書的五十篇之一。情者文章的內容，采者文章的辭藻，齊梁文勝而質亡，一般作者多競尚辭藻，而往往把內容忽視，劉勰因此強調的指出", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%96%87%E5%BF%83%E9%9B%95%E9%BE%8D%E3%83%BB%E6%83%85%E9%87%87"}, {"title": "文選序", "author": "蕭統", "period": "南北朝", "form": "文", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["式觀元始，吵覿玄風。冬穴夏巢之時，茹毛飲血之世，世質民淳，斯文未作。逮乎伏羲氏之王天下也，始畫八卦，造書契，以代結繩之政，由是文籍生焉。《易》曰︰「觀乎天文以察時變，觀乎人文以化成天下。」文之時義遠矣哉！", "若夫椎輪為大輅之始，大輅寧有椎輪之質；增冰為積水所成，積水曾微增冰之凜。何哉？蓋踵其事而增華，變其本而加厲；物既有之，文亦宜然。隨時變改，難可詳悉。", "嘗試論之，曰︰《詩序》云︰「時有六義焉︰一曰風，二曰賦，三曰比，四曰興，五曰雅，六曰頌。」至於今之作者，異乎古昔，古詩之體，今則全取賦名。荀、宋表之於前，賈、馬繼之於末。自茲以降，源流實繁。述邑居，則有憑虛亡是之作，戒畋游則有長楊羽獵之制。若其記一事，詠一物，風雲草木之興，魚蟲禽獸之流，推而廣之，不可勝載矣。", "及楚人屈原，含忠履潔，君匪從流，臣進逆耳，深思遠慮，遂放湘南。耿介之意既傷，壹鬱之懷靡愬。臨淵有《懷沙》之志，吟澤有憔悴之容。騷人之文，自茲而作。詩者，蓋志之所之也，情動於中而形於言。《關睢》《麟趾》，正始之道著；桑間濮上，亡國之音表。故風雅之道，粲然可觀。", "自炎漢中葉，厥塗漸異。退傅有在鄒之作，降將著河梁之篇，四言五言，區以別矣。又少則三字，多則九言，各體互興，分鑣並驅。頌者，所以遊揚德業，褒讚成功；吉甫有穆若之談，季子有至矣之歎。舒布為詩，既言如彼；總成為頌，又亦若此。次則箴興於補闕，戒出於弼匡；論則析理精微，銘則序事清潤；美終則誄發，圖像則讚興；", "又詔誥教令之流，表奏牋記之列，書誓符檄之品，弔祭悲哀之作，答客指事之制，三言八字之文，篇辭引序，碑碣誌狀，眾制鋒起，源流間出。譬陶匏異器，並為入耳之娛；黼黻不同，俱為悅目之翫。作者之致，蓋云備矣。", "余監撫餘閒，居多暇日，歷觀文囿，泛覽辭林，未嘗不心遊目想，移晷忘倦。自姬漢以來，眇焉悠邈，時更七代，數逾千祀。詞人才子，則名溢於縹囊；飛文染翰，則卷盈乎緗帙。自非略其蕪穢，集其清英，蓋欲兼功，太半難矣。若夫姬公之籍，孔父之書，與日月俱懸，鬼神爭奧；孝敬之准式，人倫之師友；豈可重以芟夷，加之翦截？", "老莊之作，管孟之流，蓋以立意為宗，不以能文為本；今之所撰，又以略諸。若賢人之美辭，忠臣之抗直，謀夫之話，辨士之端，冰釋泉涌，金相玉振；所謂坐狙丘，議稷下，仲連之卻秦軍，食其之下齊國，留侯之發八難，曲逆之吐六奇，蓋乃事美一時，語流千載；概見墳籍，旁出子史，若斯之流，又亦繁博，雖傳之簡牘，而事異篇章；今之所集，亦所不取。", "至於記事之史，繫年之書，所以褒貶是非，紀別異同，方之篇翰，亦已不同。若其贊論之綜緝辭采，序述之錯比文華，事出於沈思，義歸乎翰藻，故與夫篇什，雜而集之。遠自周室，迄於聖代，都為三十卷，名曰《文選》云爾。"], "quote": ["式觀元始，吵覿玄風。冬穴夏巢之時，茹毛飲血之世，世質民淳，斯文未作。逮乎伏羲氏之王天下也，始畫八卦，造書契，以代結繩之政，由是文籍生焉。《易》曰︰「觀乎天文以察時變，觀乎人文以化成天下。」文之時義遠矣哉！", "若夫椎輪為大輅之始，大輅寧有椎輪之質；增冰為積水所成，積水曾微增冰之凜。何哉？蓋踵其事而增華，變其本而加厲；物既有之，文亦宜然。隨時變改，難可詳悉。", "嘗試論之，曰︰《詩序》云︰「時有六義焉︰一曰風，二曰賦，三曰比，四曰興，五曰雅，六曰頌。」至於今之作者，異乎古昔，古詩之體，今則全取賦名。荀、宋表之於前，賈、馬繼之於末。自茲以降，源流實繁。述邑居，則有憑虛亡是之作，戒畋游則有長楊羽獵之制。若其記一事，詠一物，風雲草木之興，魚蟲禽獸之流，推而廣之，不可勝載矣。", "及楚人屈原，含忠履潔，君匪從流，臣進逆耳，深思遠慮，遂放湘南。耿介之意既傷，壹鬱之懷靡愬。臨淵有《懷沙》之志，吟澤有憔悴之容。騷人之文，自茲而作。詩者，蓋志之所之也，情動於中而形於言。《關睢》《麟趾》，正始之道著；桑間濮上，亡國之音表。故風雅之道，粲然可觀。"], "intro": "本文是昭明太子蕭統自己給他所編的《文選》寫的序文。這部《文選》的選文標準是純文學標準；所以不選「經」「史」「子」，而只限於文學作品。 《文選》內容極廣泛。就作品時間上說，上及周末屈原的《離騷》，下達於齊、梁文士的作品；就種類說，包含賦、詩、", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%96%87%E9%81%B8%E5%BA%8F"}, {"title": "擬行路難（其六）", "author": "鮑照", "period": "南北朝", "form": "詩", "theme": "送別行旅", "mood": "autumn_sunset", "lines": ["對案不能食，拔劍擊柱長嘆息。", "丈夫生世會幾時，安能蹀躞垂羽翼？", "棄置罷官去，還家自休息。", "朝出與親辭，暮還在親側。", "弄兒牀前戲，看婦機中織。", "自古聖賢盡貧賤，何況我輩孤且直。"], "quote": ["對案不能食，拔劍擊柱長嘆息。", "丈夫生世會幾時，安能蹀躞垂羽翼？", "棄置罷官去，還家自休息。", "朝出與親辭，暮還在親側。"], "intro": "《行路難》原為漢代歌謠，屬樂府雜曲。《樂府詩集》引《樂府解題》云：「《行路難》，備言世路艱難及離別悲傷之意。」晉人袁山松改變其音調，製造新詞，流行一時。今古辭和袁山松之辭都不存，所存者，以鮑照《擬行路難》十八首為最早。這十八首詩，非寫於一時", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%93%AC%E8%A1%8C%E8%B7%AF%E9%9B%A3%EF%BC%88%E5%85%B6%E5%85%AD%EF%BC%89"}, {"title": "晚登三山還望京邑", "author": "謝朓", "period": "南北朝", "form": "詩", "theme": "山水登臨", "mood": "autumn_sunset", "lines": ["灞涘望長安，河陽視京縣。", "白日麗飛甍，參差皆可見。", "餘霞散成綺，澄江靜如練。", "喧鳥覆春洲，雜英滿芳甸。", "去矣方滯淫，懷哉罷歡宴。", "佳期悵何許，淚下如流霰。", "有情知望鄉，誰能鬒不變。"], "quote": ["灞涘望長安，河陽視京縣。", "白日麗飛甍，參差皆可見。", "餘霞散成綺，澄江靜如練。", "喧鳥覆春洲，雜英滿芳甸。"], "intro": "南齊建武二年（495），謝朓由中書郎出任宣城守，離京赴任途中寫下這首詩。三山，在今南京市西南長江南岸。京邑，指南首都建康（今南京市）。詩歌寫登山臨江所見美景和去國懷鄉的惆悵之情。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%99%9A%E7%99%BB%E4%B8%89%E5%B1%B1%E9%82%84%E6%9C%9B%E4%BA%AC%E9%82%91"}, {"title": "登山曲", "author": "謝朓", "period": "南北朝", "form": "詩", "theme": "山水登臨", "mood": "autumn_sunset", "lines": ["天明開秀崿，瀾光媚碧堤。風蕩飄鶯亂，雲行芳樹低。", "暮春春服美，遊駕凌丹梯。升嶠既小魯，登巒且悵齊。", "王孫尚遊衍，蕙草正萋萋。"], "quote": ["天明開秀崿，瀾光媚碧堤。風蕩飄鶯亂，雲行芳樹低。", "暮春春服美，遊駕凌丹梯。升嶠既小魯，登巒且悵齊。", "王孫尚遊衍，蕙草正萋萋。"], "intro": "這是作者在荊州奉隨王蕭子隆之命寫的《樂府‧鼓吹曲》十首中第九首。寫登山所見清麗之景，結尾表現流連忘歸之意。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%99%BB%E5%B1%B1%E6%9B%B2"}, {"title": "折箭", "author": "魏收", "period": "南北朝", "form": "文", "theme": "山水登臨", "mood": "ethereal", "lines": ["阿豺有子二十人，緯代，長子也。阿豺又謂曰︰「汝等各奉吾一支箭，折之地下。」俄而命母弟慕利延曰︰「汝取一支箭折之。」慕利延折之。又曰︰「汝取十九支箭折之。」延不能折。阿豺曰︰「汝曹知否？單者易折，眾則難摧，戮力一心，然後社稷可固。」"], "quote": ["阿豺有子二十人，緯代，長子也。阿豺又謂曰︰「汝等各奉吾一支箭，折之地下。」俄而命母弟慕利延曰︰「汝取一支箭折之。」慕利延折之。又曰︰「汝取十九支箭折之。」延不能折。阿豺曰︰「汝曹知否？單者易折，眾則難摧，戮力一心，然後社稷可固。」"], "intro": "本文選自《魏書》卷一零一，《列傳》第八十九《吐谷渾傳》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%8A%98%E7%AE%AD"}, {"title": "顏氏家訓・涉務", "author": "顏之推", "period": "南北朝", "form": "文", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["夫君子之處世，貴能有益於物耳。不徒高談虛論，左琴右書，以費人君祿位也。國之用材，大較不過六事︰一則朝廷之臣，取其鑒達治體，經綸博雅；二則文史之臣，取其著述憲章，不忘前古；三則軍旅之臣，取其斷決有謀，強幹習事；四則藩屏之臣，取其明練風俗，清白愛民；", "五則使命之臣，取其識變從宜，不辱君命；六則興造之臣，取其程功節費，開略有術︰此則皆勤學守行者，所能辦也。人性有長短，豈責具美於六塗哉？但當皆曉指趣，能守一職，便無媿耳。", "吾見世中文學之士，品藻古今，若指諸掌；及有試用，多無所堪。居承平之世，不知有喪亂之禍；處廟堂之下，不知有戰陣之急；保俸祿之資，不知有耕稼之苦；肆吏民之上，不知有勞役之勤︰故難可以應世經務也。", "晉朝南渡，優借士族，故江南冠帶有才幹者，擢為令僕以下，尚書郎中書舍人已上，典掌機要。其餘文義之士，多迂誕浮華，不涉世務；纖微過失，又惜行捶楚。所以處於清名，蓋護其短也。", "至於臺閣令史，主書監帥，諸王籤省，並曉習吏用，濟辦時須，縱有小人之態，皆可鞭杖肅督，故多見委使，蓋用其長也。人每不自量，舉世怨梁武帝父子，愛小人而疏士大夫，此亦眼不能見其睫耳。", "梁世士大夫，皆尚褒衣博帶，大冠高履，出則車輿，入則扶侍，郊郭之內，無乘馬者。周弘正為宣城王所愛，給一果下馬，常服御之，舉朝以為放達。至乃尚書郎乘馬則糺劾之。", "及侯景之亂，膚脆骨柔，不堪行步，體羸氣弱，不耐寒暑，坐死倉猝者，往往而然。", "古人欲知稼穡之艱難，斯蓋貴穀務本之道也。夫食為民天，民非食不生矣。三日不粒，父子不能相存。耕種之，茠鉏之，刈穫之，載積之，打拂之，簸揚之，凡幾涉手而入倉廩，安可輕農事而貴末業哉？", "江南朝士，因晉中興而渡江，本為羈旅，至今八九世，未有力田，悉資俸祿而食耳。假令有者，皆信僮僕為之，未嘗目觀起一撥土，耘一株苗，不知幾月當下，幾月當收，安識世間餘務乎？故治官則不了，營家則不辦，皆優閒之過也。"], "quote": ["夫君子之處世，貴能有益於物耳。不徒高談虛論，左琴右書，以費人君祿位也。國之用材，大較不過六事︰一則朝廷之臣，取其鑒達治體，經綸博雅；二則文史之臣，取其著述憲章，不忘前古；三則軍旅之臣，取其斷決有謀，強幹習事；四則藩屏之臣，取其明練風俗，清白愛民；", "五則使命之臣，取其識變從宜，不辱君命；六則興造之臣，取其程功節費，開略有術︰此則皆勤學守行者，所能辦也。人性有長短，豈責具美於六塗哉？但當皆曉指趣，能守一職，便無媿耳。", "吾見世中文學之士，品藻古今，若指諸掌；及有試用，多無所堪。居承平之世，不知有喪亂之禍；處廟堂之下，不知有戰陣之急；保俸祿之資，不知有耕稼之苦；肆吏民之上，不知有勞役之勤︰故難可以應世經務也。", "晉朝南渡，優借士族，故江南冠帶有才幹者，擢為令僕以下，尚書郎中書舍人已上，典掌機要。其餘文義之士，多迂誕浮華，不涉世務；纖微過失，又惜行捶楚。所以處於清名，蓋護其短也。"], "intro": "本篇是《顏氏家訓》的第十一篇，此書共七卷二十篇，多述立身治家之法，辨正世俗之謬。謙言所撰非敢誨示世人，僅以教訓子弟，故名「家訓」。涉世，經歷世事之意。之推認為人的才能雖有高下，但總得有一種專長，去為國家效力，而這種專長，正由歷練而來。他有見", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%A1%8F%E6%B0%8F%E5%AE%B6%E8%A8%93%E3%83%BB%E6%B6%89%E5%8B%99"}, {"title": "水經注・三峽（節選）", "author": "酈道元", "period": "南北朝", "form": "文", "theme": "山水登臨", "mood": "snow_winter", "lines": ["江水又東，逕廣溪峽，斯乃三峽之首也。……峽中有瞿塘、黃龕二灘，……其峽蓋自禹鑿以通江，郭景純所謂巴東之峽，夏后疏鑿者也。", "江水又東，逕巫峽，杜宇所鑿以通江水也。江水歷峽東，逕新崩灘。此山漢和帝永元十二年崩，晉太元二年又崩。當崩之日，水逆流百餘里，湧起數十丈。今灘上有石，或圓如簞，或方似屋，若此者甚眾，皆崩崖所隕，致怒湍流，故謂之「新崩灘」。", "其頹崖所餘，比之諸嶺，尚為竦桀。其下十餘里，有大巫山，非惟三峽所無，乃當抗峰岷、峨，偕嶺衡、疑。其翼附群山，並概青雲，更就霄漢，辨其優劣耳。……其間首尾百六十里，謂之巫峽，蓋因山為名也。", "自三峽七百里中，兩岸連山，略無闕處；重巖疊嶂，隱天蔽日︰自非亭午夜分，不見曦月。至於夏水襄陵，沿溯阻絕，或王命急宣，有時朝發白帝，暮到江陵，其間千二百里，雖乘奔御風不以疾也。", "春冬之時，則素湍綠潭，迴清倒影。絕巘多生檉柏，懸泉瀑布，飛漱其間。清榮峻茂，良多趣味。每至晴初霜旦，林寒澗肅，常有高猿長嘯，屬引淒異，空谷傳響，哀轉久絕。", "故漁者歌曰︰「巴東三峽巫峽長，猿鳴三聲淚沾裳！」"], "quote": ["江水又東，逕廣溪峽，斯乃三峽之首也。……峽中有瞿塘、黃龕二灘，……其峽蓋自禹鑿以通江，郭景純所謂巴東之峽，夏后疏鑿者也。", "江水又東，逕巫峽，杜宇所鑿以通江水也。江水歷峽東，逕新崩灘。此山漢和帝永元十二年崩，晉太元二年又崩。當崩之日，水逆流百餘里，湧起數十丈。今灘上有石，或圓如簞，或方似屋，若此者甚眾，皆崩崖所隕，致怒湍流，故謂之「新崩灘」。", "其頹崖所餘，比之諸嶺，尚為竦桀。其下十餘里，有大巫山，非惟三峽所無，乃當抗峰岷、峨，偕嶺衡、疑。其翼附群山，並概青雲，更就霄漢，辨其優劣耳。……其間首尾百六十里，謂之巫峽，蓋因山為名也。", "自三峽七百里中，兩岸連山，略無闕處；重巖疊嶂，隱天蔽日︰自非亭午夜分，不見曦月。至於夏水襄陵，沿溯阻絕，或王命急宣，有時朝發白帝，暮到江陵，其間千二百里，雖乘奔御風不以疾也。"], "intro": "《三峽》選自《水經注・江水》，題目為編者所加，本篇節選首三段。《水經》是一部記述全國河流水道的專書，舊傳漢人桑欽作，經清人考證，大概為三國時人之作。酈道元《水經注》四十卷，雖以注釋為名，實為一部文學及史學巨著。 三峽即長江上游的瞿塘峽、巫峽", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B0%B4%E7%B6%93%E6%B3%A8%E3%83%BB%E4%B8%89%E5%B3%BD%EF%BC%88%E7%AF%80%E9%81%B8%EF%BC%89"}, {"title": "遣悲懷（三首）", "author": "元稹", "period": "唐", "form": "詩", "theme": "田園幽居", "mood": "autumn_sunset", "lines": ["其一", "謝公最小偏憐女，自嫁黔婁百事乖。", "顧我無衣搜藎篋，泥他沽酒拔金釵。", "野蔬充膳甘長藿，落葉添薪仰古槐。", "今日俸錢過十萬，與君營奠復營齋。", "其二", "昔日戲言身後意，今朝都到眼前來。", "衣裳已施行看盡，針線猶存未忍開。", "尚想舊情憐婢僕，也曾因夢送錢財。", "誠知此恨人人有，貧賤夫妻百事哀。", "其三", "閒坐悲君亦自悲，百年都是幾多時。"], "quote": ["其一", "謝公最小偏憐女，自嫁黔婁百事乖。", "顧我無衣搜藎篋，泥他沽酒拔金釵。", "野蔬充膳甘長藿，落葉添薪仰古槐。"], "intro": "《遣悲懷》三首是元稹悼念亡妻韋叢的一組七律，作於唐憲宗元和四年（八〇九）。這一年的秋天，元稹的第一個妻子韋叢病死，年僅二十七歲，元稹傷悼不已，為她寫了不少悼亡詩，其中以《遣悲懷》三首最著名。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%81%A3%E6%82%B2%E6%87%B7%EF%BC%88%E4%B8%89%E9%A6%96%EF%BC%89"}, {"title": "涼州詞（其一）（黃河遠上白雲間）", "author": "王之渙", "period": "唐", "form": "詩", "theme": "江河湖海", "mood": "snow_winter", "lines": ["黃河遠上白雲間，一片孤城萬仞山。", "羌笛何須怨楊柳？春風不度玉門關。"], "quote": ["黃河遠上白雲間，一片孤城萬仞山。", "羌笛何須怨楊柳？春風不度玉門關。"], "intro": "王之渙《涼州詞》選自《全唐詩》卷二百五十三。原題共兩首，此處錄第一首。《涼州詞》是唐代樂府曲名，《樂府詩集》收入「橫吹曲辭」，題作《出塞》。涼州，唐代州名，包括河西、隴右一帶地方，州治在今甘肅武威。本詩是以樂府曲調寫涼州遼闊荒寒的景象，境界", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B6%BC%E5%B7%9E%E8%A9%9E%EF%BC%88%E5%85%B6%E4%B8%80%EF%BC%89%EF%BC%88%E9%BB%83%E6%B2%B3%E9%81%A0%E4%B8%8A%E7%99%BD%E9%9B%B2%E9%96%93%EF%BC%89"}, {"title": "登鸛雀樓", "author": "王之渙", "period": "唐", "form": "詩", "theme": "山水登臨", "mood": "autumn_sunset", "lines": ["白日依山盡，黃河入海流。", "欲窮千里目，更上一層樓。"], "quote": ["白日依山盡，黃河入海流。", "欲窮千里目，更上一層樓。"], "intro": "《登鸛雀樓》選自《全唐詩》卷二百五十三，一作朱斌詞。鸛雀樓（鸛雀：鳥名，鶴類。鸛，粤：[貫gun3]；普：[guàn]。）在蒲州（在今山西永濟）西南。樓高三層，前對中條山，下瞰黃河，是登覽的勝地，因時常有鸛雀棲止樓上而得名。這首詩寫傍晚登鸛", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%99%BB%E9%B8%9B%E9%9B%80%E6%A8%93"}, {"title": "小松", "author": "王建", "period": "唐", "form": "詩", "theme": "田園幽居", "mood": "ethereal", "lines": ["小松初數尺，未有直生枝。", "閑即傍邊立，看多長卻遲。"], "quote": ["小松初數尺，未有直生枝。", "閑即傍邊立，看多長卻遲。"], "intro": "", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B0%8F%E6%9D%BE"}, {"title": "新嫁娘", "author": "王建", "period": "唐", "form": "詩", "theme": "田園幽居", "mood": "ethereal", "lines": ["三日入廚下，洗手作羹湯。", "未諳姑食性，先遣小姑嚐。"], "quote": ["三日入廚下，洗手作羹湯。", "未諳姑食性，先遣小姑嚐。"], "intro": "《新嫁娘》三首是王建的組詩作品。這組詩寫一位剛嫁入夫家的新娘的經歷和感受，某程度上透露了唐代的婚姻習俗和新嫁娘的生活。全組詩寫新嫁娘新婚前三天的生活片段，每首詩各寫一天，此處所選為第三首，出自蘅塘退士《唐詩三百首》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%96%B0%E5%AB%81%E5%A8%98"}, {"title": "出塞（其一）", "author": "王昌齡", "period": "唐", "form": "詩", "theme": "邊塞豪放", "mood": "majestic_peaks", "lines": ["秦時明月漢時關，萬里長征人未還。", "但使龍城飛將在，不教胡馬度陰山。"], "quote": ["秦時明月漢時關，萬里長征人未還。", "但使龍城飛將在，不教胡馬度陰山。"], "intro": "《出塞》選自《全唐詩》卷一百四十三。原題共二首，本課選錄第一首。《出塞》為樂府曲題，是一首弔古抒懷詩。首句「秦時明月漢時關」，即將眼前的邊關與悠久的戍防歷史聯繫起來，氣勢雄偉，足以統攝全詩。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%87%BA%E5%A1%9E%EF%BC%88%E5%85%B6%E4%B8%80%EF%BC%89"}, {"title": "芙蓉樓送辛漸（其一）", "author": "王昌齡", "period": "唐", "form": "詩", "theme": "送別行旅", "mood": "snow_winter", "lines": ["寒雨連天夜入湖，平明送客楚山孤。", "洛陽親友如相問，一片冰心在玉壺。"], "quote": ["寒雨連天夜入湖，平明送客楚山孤。", "洛陽親友如相問，一片冰心在玉壺。"], "intro": "《芙蓉樓送辛漸》選自《全唐詩》卷一百四十三。原題共二首，此處選錄第一首。芙蓉樓，唐潤州丹陽郡治丹徒縣（今江蘇鎮江）西北角城樓。辛漸，生平不詳，當為王昌齡友人。唐玄宗開元二十八年（七四〇），王昌齡被貶，出為江寧丞。他在任上曾遊丹陽。這首詩是在", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%8A%99%E8%93%89%E6%A8%93%E9%80%81%E8%BE%9B%E6%BC%B8%EF%BC%88%E5%85%B6%E4%B8%80%EF%BC%89"}, {"title": "長信秋詞", "author": "王昌齡", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["奉帚平明金殿開，暫將團扇共徘徊。", "玉顏不及寒鴉色，猶帶昭陽日影來。"], "quote": ["奉帚平明金殿開，暫將團扇共徘徊。", "玉顏不及寒鴉色，猶帶昭陽日影來。"], "intro": "此詩亦題《長信怨》，共五首，此為第三首。《長信怨》本古樂府的舊題，乃詠漢班婕妤怨情的。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%95%B7%E4%BF%A1%E7%A7%8B%E8%A9%9E"}, {"title": "從軍行", "author": "王昌齡", "period": "唐", "form": "詩", "theme": "邊塞豪放", "mood": "snow_winter", "lines": ["青海長雲暗雪山，孤城遙望玉門關。", "黃沙百戰穿金甲，不破樓蘭終不還。"], "quote": ["青海長雲暗雪山，孤城遙望玉門關。", "黃沙百戰穿金甲，不破樓蘭終不還。"], "intro": "《從軍行》是樂府舊題名，多寫軍旅生活。王昌齡的《從軍行》共有詩七首，這裏選的是其中第四首，謳歌了將士在艱苦環境下和激烈戰鬥中那種高漲的士氣和獻身精神。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%BE%9E%E8%BB%8D%E8%A1%8C"}, {"title": "閨怨", "author": "王昌齡", "period": "唐", "form": "詩", "theme": "邊塞豪放", "mood": "spring_breeze", "lines": ["閨中少婦不知愁，春日凝妝上翠樓。", "忽見陌頭楊柳色，悔教夫壻覓封侯。"], "quote": ["閨中少婦不知愁，春日凝妝上翠樓。", "忽見陌頭楊柳色，悔教夫壻覓封侯。"], "intro": "唐代前期，國力很強盛，從軍遠征，到邊疆立功，是人們求取功名的一條捷徑，所以當時不少做妻子的都鼓勵自己的丈夫從軍。在封建時代，從來就是妻憑夫貴，丈夫得到功名，妻子才會得到光彩。《閨怨》這首詩，顧名思義，就是寫一位年輕婦女思念遠征丈夫的心情。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%96%A8%E6%80%A8"}, {"title": "杜少府之任蜀州", "author": "王勃", "period": "唐", "form": "詩", "theme": "送別行旅", "mood": "vast_river", "lines": ["城闕輔三秦，風煙望五津。", "與君離別意，同是宦遊人。", "海內存知己，天涯若比鄰。", "無為在岐路，兒女共霑巾。"], "quote": ["城闕輔三秦，風煙望五津。", "與君離別意，同是宦遊人。", "海內存知己，天涯若比鄰。", "無為在岐路，兒女共霑巾。"], "intro": "《杜少府之任蜀州》選自《全唐詩》卷五十六，一作「杜少府之任蜀川」。少府，官名，唐代縣尉的通稱。任，赴任。蜀州，在今四川。這是王勃在長安任沛王府修撰時，為送友人杜少府到蜀州任職的贈別之作。詩中既表達了作者與友人的深情厚誼，又反映出曠達的精神和", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9D%9C%E5%B0%91%E5%BA%9C%E4%B9%8B%E4%BB%BB%E8%9C%80%E5%B7%9E"}, {"title": "滕王閣餞別序", "author": "王勃", "period": "唐", "form": "文", "theme": "江河湖海", "mood": "snow_winter", "lines": ["南昌故郡，洪都新府，星分翼軫，地接衡廬。襟三江而帶五湖，控蠻荊而引甌越。物華天寶，龍光射牛斗之墟；人傑地靈，徐孺下陳蕃之榻。", "雄州霧列，俊采星馳。臺隍枕夷夏之交，賓主盡東南之美。都督閻公之雅望，棨戟遙臨；宇文新州之懿範，襜帷暫駐。十旬休暇，勝友如雲；千里逢迎，高朋滿座。騰蛟起鳳，孟學士之詞宗；紫電清霜，王將軍之武庫。", "家君作宰，路出名區；童子何知，躬逢勝餞。", "時維九月，序屬三秋；潦水盡而寒潭清，煙光凝而暮山紫。儼驂騑於上路，訪風景於崇阿。臨帝子之長洲，得仙人之舊館。層臺聳翠，上出重霄；飛閣流丹，下臨無地。", "鶴汀鳧渚，窮島嶼之縈迴；桂殿蘭宮，即岡巒之體勢。披繡闥，俯雕甍。山原曠其盈視，川澤盱其駭矚。閭閻撲地，鐘鳴鼎食之家；舸艦彌津，青雀黃龍之軸。虹銷雨霽，彩徹雲衢。", "落霞與孤鶩齊飛，秋水共長天一色。漁舟唱晚，響窮彭蠡之濱；雁陣驚寒，聲斷衡陽之浦。", "遙襟俯暢，逸興遄飛。爽籟發而清風生，纖歌凝而白雲遏。睢園綠竹，氣凌彭澤之樽；鄴水朱華，光照臨川之筆。四美具，二難并。窮睇眄於中天，極娛遊於暇日。天高地迥，覺宇宙之無窮；興盡悲來，識盈虛之有數。望長安於日下，指吳會於雲間。", "地勢極而南溟深，天柱高而北辰遠。關山難越，誰悲失路之人；萍水相逢，盡是他鄉之客。懷帝閽而不見，奉宣室以何年。嗟乎！時運不齊，命途多舛；馮唐易老，李廣難封。屈賈誼於長沙，非無聖主；竄梁鴻於海曲，豈乏明時。", "所賴君子安貧，達人知命。老當益壯，寧移白首之心；窮且益堅，不墜青雲之志。酌貪泉而覺爽，處涸轍以相懽。北海雖賒，扶搖可接；東隅已逝，桑榆非晚。孟嘗高潔，空餘報國之情；阮籍倡狂，豈效窮途之哭。", "勃三尺微命，一介書生。無路請纓，等終軍之弱冠；有懷投筆，慕宗慤之長風。舍簪笏於百齡，奉晨昏於萬里。非謝家之寶樹，接孟氏之芳鄰。他日趨庭，叨陪鯉對；今茲捧袂，喜託龍門。楊意不逢，撫凌雲而自惜；鍾期既遇，奏流水以何慚。", "嗚呼！勝地不常，盛筵難再；蘭亭已矣，梓澤邱墟。臨別贈言，幸承恩於偉餞；登高作賦，是所望於群公。敢竭鄙誠，恭疏短引；一言均賦，四韻俱成。請灑潘江，各傾陸海云爾。"], "quote": ["南昌故郡，洪都新府，星分翼軫，地接衡廬。襟三江而帶五湖，控蠻荊而引甌越。物華天寶，龍光射牛斗之墟；人傑地靈，徐孺下陳蕃之榻。", "雄州霧列，俊采星馳。臺隍枕夷夏之交，賓主盡東南之美。都督閻公之雅望，棨戟遙臨；宇文新州之懿範，襜帷暫駐。十旬休暇，勝友如雲；千里逢迎，高朋滿座。騰蛟起鳳，孟學士之詞宗；紫電清霜，王將軍之武庫。", "家君作宰，路出名區；童子何知，躬逢勝餞。", "時維九月，序屬三秋；潦水盡而寒潭清，煙光凝而暮山紫。儼驂騑於上路，訪風景於崇阿。臨帝子之長洲，得仙人之舊館。層臺聳翠，上出重霄；飛閣流丹，下臨無地。"], "intro": "《滕王閣餞別序》選自《王子安集》卷五，又稱《秋日登洪府滕王閣餞別序》、《滕王閣序》。序是古代文體之一，有書序、贈序和宴集序等。本篇屬於多寫盛會場面和宴飲之樂的宴集詩序。滕王，傳統認為是唐高祖第二十二子李元嬰。唐高宗顯慶四年（六五九），元嬰任", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%BB%95%E7%8E%8B%E9%96%A3%E9%A4%9E%E5%88%A5%E5%BA%8F"}, {"title": "九月九日憶山東兄弟", "author": "王維", "period": "唐", "form": "詩", "theme": "山水登臨", "mood": "majestic_peaks", "lines": ["獨在異鄉為異客，每逢佳節倍思親。", "遙知兄弟登高處，遍插茱萸少一人。"], "quote": ["獨在異鄉為異客，每逢佳節倍思親。", "遙知兄弟登高處，遍插茱萸少一人。"], "intro": "《九月九日憶山東兄弟》選自《全唐詩》卷一百二十八。山東，指崤山函谷關以東地區，這裏代指詩人故鄉蒲州（今山西永濟）。原注有「時年十七」四字，則知當時王維已離開家鄉在長安準備應試。此詩寫自己在重陽節對故鄉兄弟的思念。全詩構思新穎，感情真摯，文字", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B9%9D%E6%9C%88%E4%B9%9D%E6%97%A5%E6%86%B6%E5%B1%B1%E6%9D%B1%E5%85%84%E5%BC%9F"}, {"title": "山中送別", "author": "王維", "period": "唐", "form": "詩", "theme": "送別行旅", "mood": "autumn_sunset", "lines": ["山中相送罷，日暮掩柴扉。", "春草明年綠，王孫歸不歸？"], "quote": ["山中相送罷，日暮掩柴扉。", "春草明年綠，王孫歸不歸？"], "intro": "這首詩是王維隱居山林時所作，抒發送別友人之後的情思。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B1%B1%E4%B8%AD%E9%80%81%E5%88%A5"}, {"title": "山居秋暝", "author": "王維", "period": "唐", "form": "詩", "theme": "田園幽居", "mood": "autumn_sunset", "lines": ["空山新雨後，天氣晚來秋。", "明月松間照，清泉石上流。", "竹喧歸浣女，蓮動下漁舟。", "隨意春芳歇，王孫自可留。"], "quote": ["空山新雨後，天氣晚來秋。", "明月松間照，清泉石上流。", "竹喧歸浣女，蓮動下漁舟。", "隨意春芳歇，王孫自可留。"], "intro": "《山居秋暝》是王維居於輞川時的作品。輞川別墅在終南山下，故稱「山居」。詩中描繪了秋日傍晚雨後山林的景色，表現了詩人寄情山水田園，嚮往歸隱生活的意趣。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B1%B1%E5%B1%85%E7%A7%8B%E6%9A%9D"}, {"title": "少年行", "author": "王維", "period": "唐", "form": "詩", "theme": "詠史哲思", "mood": "ethereal", "lines": ["一身能擘兩彫弧，虜騎千重只似無；", "偏坐金鞍調白羽，紛紛射殺五單于。"], "quote": ["一身能擘兩彫弧，虜騎千重只似無；", "偏坐金鞍調白羽，紛紛射殺五單于。"], "intro": "這首詩是王維《少年行》七絕組詩其中一首。根據組詩反映的少年游俠精神來看，是王維早期的作品，應作於「安史之亂」之前。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B0%91%E5%B9%B4%E8%A1%8C"}, {"title": "竹里館", "author": "王維", "period": "唐", "form": "詩", "theme": "田園幽居", "mood": "heroic", "lines": ["獨坐幽篁裏，彈琴復長嘯。", "深林人不知，明月來相照。"], "quote": ["獨坐幽篁裏，彈琴復長嘯。", "深林人不知，明月來相照。"], "intro": "《竹里館》選自《全唐詩》卷一百二十八，是《輞川集》二十首中之第十七首。竹里館即竹裏館，在詩人隱居的輞川別墅內，是輞川別業的勝景之一，因建於竹林深處而得名。此詩寫隱居者的一種閒適情致，情景交融，清幽絕俗。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%AB%B9%E9%87%8C%E9%A4%A8"}, {"title": "相思", "author": "王維", "period": "唐", "form": "詩", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["紅豆生南國，春來發幾枝。", "願君多采擷，此物最相思。"], "quote": ["紅豆生南國，春來發幾枝。", "願君多采擷，此物最相思。"], "intro": "《相思》選自《全唐詩》卷一百二十八，此詩為王維早年之作。作品借物托情，以紅豆寄寓思念的情懷。寫來含蓄委婉，在當時已被譜成歌曲，廣為流傳。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%9B%B8%E6%80%9D"}, {"title": "送別", "author": "王維", "period": "唐", "form": "詩", "theme": "送別行旅", "mood": "majestic_peaks", "lines": ["下馬飲君酒，問君何所之？", "君言不得意，歸臥南山陲。", "但去莫復問，白雲無盡時。"], "quote": ["下馬飲君酒，問君何所之？", "君言不得意，歸臥南山陲。", "但去莫復問，白雲無盡時。"], "intro": "", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%80%81%E5%88%A5"}, {"title": "鳥鳴澗", "author": "王維", "period": "唐", "form": "詩", "theme": "田園幽居", "mood": "vast_river", "lines": ["人閑桂花落，夜靜春山空。", "月出驚山鳥，時鳴春澗中。"], "quote": ["人閑桂花落，夜靜春山空。", "月出驚山鳥，時鳴春澗中。"], "intro": "《鳥鳴澗》是王維題友人皇甫岳所居的雲溪別墅所寫的組詩《皇甫岳雲溪雜題五首》的第一首。此詩描繪山間春夜裏寧靜幽美的景色，應作於開元年間（七一三──七四一）王維遊歷江南之時，是王維年青時期的作品。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%B3%A5%E9%B3%B4%E6%BE%97"}, {"title": "鹿柴", "author": "王維", "period": "唐", "form": "詩", "theme": "田園幽居", "mood": "autumn_sunset", "lines": ["空山不見人，但聞人語響。", "返景入深林，復照青苔上。"], "quote": ["空山不見人，但聞人語響。", "返景入深林，復照青苔上。"], "intro": "《鹿柴》選自《全唐詩》卷一百二十八。鹿柴，即鹿砦（柴，同砦，藩落、木柵。柴，粵：[寨dzai6]；普：[zhài]。），是詩人隱居之處。作者晚年在輞川別墅（陝西藍田）與友人裴迪唱和，吟詠當地景物，自輯五言絕句二十首，題名為《輞川集》，此詩是", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%B9%BF%E6%9F%B4"}, {"title": "渭川田家", "author": "王維", "period": "唐", "form": "詩", "theme": "田園幽居", "mood": "vast_river", "lines": ["斜光照墟落，窮巷牛羊歸。", "野老念牧童，倚杖候荊扉。", "雉雊麥苗秀，蠶眠桑葉稀。", "田夫荷鋤至，相見語依依。", "即此羨閑逸，悵然吟式微。"], "quote": ["斜光照墟落，窮巷牛羊歸。", "野老念牧童，倚杖候荊扉。", "雉雊麥苗秀，蠶眠桑葉稀。", "田夫荷鋤至，相見語依依。"], "intro": "《渭川田家》一詩創作年份不詳，可能是王維隱居藍田時，遊覽渭水兩岸農村時有感而作，是開元（唐玄宗年號，公元713——741年）後期的作品。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B8%AD%E5%B7%9D%E7%94%B0%E5%AE%B6"}, {"title": "渭城曲", "author": "王維", "period": "唐", "form": "詩", "theme": "送別行旅", "mood": "spring_breeze", "lines": ["渭城朝雨浥輕塵，客舍青青柳色新。", "勸君更盡一杯酒，西出陽關無故人。"], "quote": ["渭城朝雨浥輕塵，客舍青青柳色新。", "勸君更盡一杯酒，西出陽關無故人。"], "intro": "《渭城曲》選自《全唐詩》卷一百二十八，是一首著名的送別詩，詩題又作《送元二使安西》、《陽關曲》、《陽關三疊》。《樂府詩集》收入近代曲辭。元二，名字及事蹟均不詳，一說為元載。此詩通過送別場面的細緻描寫，生動地表現出朋友間的深情厚誼。本詩音韻悠", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B8%AD%E5%9F%8E%E6%9B%B2"}, {"title": "輞川閒居贈裴秀才迪", "author": "王維", "period": "唐", "form": "詩", "theme": "田園幽居", "mood": "snow_winter", "lines": ["寒山轉蒼翠，秋水日潺湲。", "倚杖柴門外，臨風聽暮蟬。", "渡頭餘落日，墟里上孤煙。", "復值接輿醉，狂歌五柳前。"], "quote": ["寒山轉蒼翠，秋水日潺湲。", "倚杖柴門外，臨風聽暮蟬。", "渡頭餘落日，墟里上孤煙。", "復值接輿醉，狂歌五柳前。"], "intro": "這首詩是王維晚年的作品，詩中概括了他晚年的生活與思想。據唐史記載，王維晚年「得宋之問藍田別墅，在輞口。輞水周於舍下，別漲竹州花塢，與道友裴迪，浮舟往來，彈琴賦詩，嘯詠終日」。 輞川，水名，在今陝西省藍田縣南終南山下；中有鹿柴、華子岡、竹里館", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%BC%9E%E5%B7%9D%E9%96%92%E5%B1%85%E8%B4%88%E8%A3%B4%E7%A7%80%E6%89%8D%E8%BF%AA"}, {"title": "涼州詞（其一）（蒲萄美酒夜光杯）", "author": "王翰", "period": "唐", "form": "詩", "theme": "邊塞豪放", "mood": "heroic", "lines": ["蒲萄美酒夜光杯，欲飲琵琶馬上催。", "醉臥沙場君莫笑，古來征戰幾人回。"], "quote": ["蒲萄美酒夜光杯，欲飲琵琶馬上催。", "醉臥沙場君莫笑，古來征戰幾人回。"], "intro": "王翰《涼州詞》選自《全唐詩》卷一百五十六。原題共二首，此處選錄第一首。這首詩描寫將士們在作戰前飲酒的情景，及其豪邁的情懷。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B6%BC%E5%B7%9E%E8%A9%9E%EF%BC%88%E5%85%B6%E4%B8%80%EF%BC%89%EF%BC%88%E8%92%B2%E8%90%84%E7%BE%8E%E9%85%92%E5%A4%9C%E5%85%89%E6%9D%AF%EF%BC%89"}, {"title": "與李生論詩書", "author": "司空圖", "period": "唐", "form": "文", "theme": "田園幽居", "mood": "snow_winter", "lines": ["文之難，而詩之難尤難。古今之喻多矣。而愚以為辨於味，而后可以言詩也。", "江嶺之南，凡足資於適口者，若醯，非不酸也，止於酸而已；若鹺，非不鹹也，止於鹹而已。中華之人，所以充飢而遽輟者，知其鹹酸之外，醇美者有所乏耳。彼江嶺之人，習之而不辨也，宜哉！", "詩貫六義，則諷諭抑揚，渟蓄淵雅，皆在其間矣。然直致所得，以格自奇，前輩諸集，亦不專工於此，矧其下者邪？王右丞、韋蘇州，澄澹精緻，格在其中，豈妨於遒舉哉？賈閬仙誠有警句，然視其全篇，意思殊餒；大抵務於寒澀，方可致才，亦為體之不備也。矧其下者哉？噫！近而不浮，遠而不盡，然后可以言韻外之致耳。", "愚幼嘗自負，久既而愈覺缺然。然得於早春，則有「草嫩侵沙長，冰輕著雨消」；又「人家寒食月，花影午時天」；又「兩微吟足思，花落夢無憀」。得於山中，則有「坡暖冬生筍，松涼夏健人」；又「川明虹照雨，樹密鳥衝人」。得於江南，則有「戍鼓和潮暗，船燈照島幽」；又「曲塘春盡雨，方響夜深船」；又「夜短猿悲減，風和鵲喜靈」。得於塞上，則有「馬色經寒慘，鵰聲帶晚飢」。得於喪亂，則有「驊騮思故策，鸚鸝失佳人」；又「鯨鯢人海涸，魑魅棘林幽」。得於道宮，則有「碁聲花院閉，幡影石壇高」。得於夏景，則有「地涼清鶴夢，林靜肅僧儀」。得於佛寺，則有「松日明金象，苔龕響木魚」；又「解吟僧亦俗，愛舞鶴終卑」。得於郊原，則有「遠坡春草滲，猶有水禽飛」。得於樂府，則有「晚粧留拜月，春睡更生香」。得於寂寥，則有「孤螢出荒池，落葉穿破屋」。得於愜適，則有「客來當意愜，花發遇歌成」。雖庶幾不濱於淺涸，亦未廢作者之譏訶也。七言云︰「逃難人多分隙地，放生鹿大出寒林」；又「得劍乍如添健僕，亡書久似憶良朋」；又「孤嶼池痕春漲滿，小欄花韻午晴初」；又「五更惆悵迴孤枕，猶自殘鐙照落花」。又「殷勤元旦日，欹午又明年」。皆不拘於一概也。蓋絕句之作，本於詣極。此外千變萬狀，不知所以神而自神也。豈容易哉？", "今足下之詩，時輩固有難色，儻復以全美為工，即知味外之旨矣。勉旃！某再拜。"], "quote": ["文之難，而詩之難尤難。古今之喻多矣。而愚以為辨於味，而后可以言詩也。", "江嶺之南，凡足資於適口者，若醯，非不酸也，止於酸而已；若鹺，非不鹹也，止於鹹而已。中華之人，所以充飢而遽輟者，知其鹹酸之外，醇美者有所乏耳。彼江嶺之人，習之而不辨也，宜哉！", "詩貫六義，則諷諭抑揚，渟蓄淵雅，皆在其間矣。然直致所得，以格自奇，前輩諸集，亦不專工於此，矧其下者邪？王右丞、韋蘇州，澄澹精緻，格在其中，豈妨於遒舉哉？賈閬仙誠有警句，然視其全篇，意思殊餒；大抵務於寒澀，方可致才，亦為體之不備也。矧其下者哉？噫！近而不浮，遠而不盡，然后可以言韻外之致耳。", "愚幼嘗自負，久既而愈覺缺然。然得於早春，則有「草嫩侵沙長，冰輕著雨消」；又「人家寒食月，花影午時天」；又「兩微吟足思，花落夢無憀」。得於山中，則有「坡暖冬生筍，松涼夏健人」；又「川明虹照雨，樹密鳥衝人」。得於江南，則有「戍鼓和潮暗，船燈照島幽」；又「曲塘春盡雨，方響夜深船」；又「夜短猿悲減，風和鵲喜靈」。得於塞上，則有「馬色經寒慘，鵰聲帶晚飢」。得於喪亂，則有「驊騮思故策，鸚鸝失佳人」；又「鯨鯢人海涸，魑魅棘林幽」。得於道宮，則有「碁聲花院閉，幡影石壇高」。得於夏景，則有「地涼清鶴夢，林靜肅僧儀」。得於佛寺，則有「松日明金象，苔龕響木魚」；又「解吟僧亦俗，愛舞鶴終卑」。得於郊原，則有「遠坡春草滲，猶有水禽飛」。得於樂府，則有「晚粧留拜月，春睡更生香」。得於寂寥，則有「孤螢出荒池，落葉穿破屋」。得於愜適，則有「客來當意愜，花發遇歌成」。雖庶幾不濱於淺涸，亦未廢作者之譏訶也。七言云︰「逃難人多分隙地，放生鹿大出寒林」；又「得劍乍如添健僕，亡書久似憶良朋」；又「孤嶼池痕春漲滿，小欄花韻午晴初」；又「五更惆悵迴孤枕，猶自殘鐙照落花」。又「殷勤元旦日，欹午又明年」。皆不拘於一概也。蓋絕句之作，本於詣極。此外千變萬狀，不知所以神而自神也。豈容易哉？"], "intro": "司空圖的詩論，除《詩品》外，尚有本文及《與極浦談詩書》《與王駕評詩書》，而本文尤為其論詩之重要作品。李生，不詳。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%88%87%E6%9D%8E%E7%94%9F%E8%AB%96%E8%A9%A9%E6%9B%B8"}, {"title": "江村即事", "author": "司空曙", "period": "唐", "form": "詩", "theme": "江河湖海", "mood": "vast_river", "lines": ["釣罷歸來不繫船，江村月落正堪眠。", "縱然一夜風吹去，只在蘆花淺水邊。"], "quote": ["釣罷歸來不繫船，江村月落正堪眠。", "縱然一夜風吹去，只在蘆花淺水邊。"], "intro": "", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B1%9F%E6%9D%91%E5%8D%B3%E4%BA%8B"}, {"title": "長恨歌", "author": "白居易", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["漢皇重色思傾國，御宇多年求不得。", "楊家有女初長成，養在深閨人未識。", "天生麗質難自棄，一朝選在君王側。", "回眸一笑百媚生，六宮粉黛無顏色。", "春寒賜浴華清池，溫泉水滑洗凝脂。", "侍兒扶起嬌無力，始是新承恩澤時。", "雲鬢花顏金步搖，芙蓉帳暖度春宵。", "春宵苦短日高起，從此君王不早朝。", "承歡侍宴無閒暇，春從春遊夜專夜。", "後宮佳麗三千人，三千寵愛在一身。", "金屋妝成嬌侍夜，玉樓宴罷醉和春。", "姊妹弟兄皆列土，可憐光彩生門戶。"], "quote": ["漢皇重色思傾國，御宇多年求不得。", "楊家有女初長成，養在深閨人未識。", "天生麗質難自棄，一朝選在君王側。", "回眸一笑百媚生，六宮粉黛無顏色。"], "intro": "《長恨歌》選自《全唐詩》卷四百三十五，作於唐憲宗元和元年（八○六）白居易任盩厔（今陝西周至）縣尉時。《長恨歌》是一篇廣為傳誦的長篇敍事詩，寫唐玄宗李隆基與貴妃楊玉環的愛情故事。憲宗元和元年十二月，白居易與陳鴻、王質夫等同遊仙游寺，話及開元、", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%95%B7%E6%81%A8%E6%AD%8C"}, {"title": "長相思（其一）（汴水流）", "author": "白居易", "period": "唐", "form": "詞", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["汴水流，泗水流，流到瓜洲古渡頭，吳山點點愁。", "思悠悠，恨悠悠，恨到歸時方始休，月明人倚樓。"], "quote": ["汴水流，泗水流，流到瓜洲古渡頭，吳山點點愁。", "思悠悠，恨悠悠，恨到歸時方始休，月明人倚樓。"], "intro": "白居易《長相思》（汴水流）選自《白居易集‧外集》卷上，原題共二首，今選其中一首。「長相思」本為唐代教坊曲名，後改用為詞牌。這首被清人王奕清等纂修的《詞譜》定為該詞的正體。 詞中女子在明月朗照的晚上倚樓遠眺，期待客居江南的親人早歸。作者取川流", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%95%B7%E7%9B%B8%E6%80%9D%EF%BC%88%E5%85%B6%E4%B8%80%EF%BC%89%EF%BC%88%E6%B1%B4%E6%B0%B4%E6%B5%81%EF%BC%89"}, {"title": "荔枝圖序", "author": "白居易", "period": "唐", "form": "文", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["荔枝生巴峽間︰樹形圓如帷蓋；葉如桂，冬青；華如橘，春榮；實如丹，夏熟；朵如葡萄；核如枇杷；殼如紅繒；膜如紫綃，瓤肉瑩白如雪；漿液甘酸如醴酪︰大略如此，其實過之。", "若離本枝，一日而色變，二日而香變，三日而味變，四五日外，色香味盡去矣。", "元和十五年夏，南賓守樂天，命工吏圖而書之；蓋為不識者，與識而不及一、二、三日者云。"], "quote": ["荔枝生巴峽間︰樹形圓如帷蓋；葉如桂，冬青；華如橘，春榮；實如丹，夏熟；朵如葡萄；核如枇杷；殼如紅繒；膜如紫綃，瓤肉瑩白如雪；漿液甘酸如醴酪︰大略如此，其實過之。", "若離本枝，一日而色變，二日而香變，三日而味變，四五日外，色香味盡去矣。", "元和十五年夏，南賓守樂天，命工吏圖而書之；蓋為不識者，與識而不及一、二、三日者云。"], "intro": "白居易在唐憲宗元和十三年（公元八一八）十二月，由江州司馬調忠州刺史。本文作於元和十五年的夏天，那時他還在忠州刺史任內。忠州，即現在四川的忠縣，在唐為忠州，唐天寶元年曾一度改稱南賓郡。荔枝係一種常綠喬木，幹高三四丈，在中國產於福建、廣東、四川", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%8D%94%E6%9E%9D%E5%9C%96%E5%BA%8F"}, {"title": "問劉十九", "author": "白居易", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["綠螘新醅酒，紅泥小火壚。", "晚來天欲雪，能飲一杯無？"], "quote": ["綠螘新醅酒，紅泥小火壚。", "晚來天欲雪，能飲一杯無？"], "intro": "《問劉十九》選自《全唐詩》卷四百四十。劉十九，嵩陽處士，劉姓，排行十九。《白氏長慶集‧劉十九同宿》有「惟共嵩陽劉處士，圍棋賭酒到天明」句。本詩大約寫於唐憲宗元和十二年（八一七），是一首極富生活情趣的五言絕句。家中新釀了酒，又有溫酒禦寒的小火", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%95%8F%E5%8A%89%E5%8D%81%E4%B9%9D"}, {"title": "望月有感", "author": "白居易", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["時難年荒世業空，弟兄羈旅各西東。", "田園寥落干戈後，骨肉流離道路中。", "吊影分為千里雁，辭根散作九秋蓬。", "共看明月應垂淚，一夜鄉心五處同。"], "quote": ["時難年荒世業空，弟兄羈旅各西東。", "田園寥落干戈後，骨肉流離道路中。", "吊影分為千里雁，辭根散作九秋蓬。", "共看明月應垂淚，一夜鄉心五處同。"], "intro": "這首詩原題：「自河南經亂，關內阻飢，兄弟離散，各在一處。因望月有感，聊書所懷，寄上浮梁大兄、於潛七兄、烏江十五兄，兼示符離及下邽弟妹。」貞元十五年（799）二月，宣武軍作亂，接着彰義軍節度使吳少誠反。到九月，德宗遣十六道軍討吳少誠，戰事大都", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9C%9B%E6%9C%88%E6%9C%89%E6%84%9F"}, {"title": "琵琶行  並序", "author": "白居易", "period": "唐", "form": "詩", "theme": "送別行旅", "mood": "snow_winter", "lines": ["元和十年，予左遷九江郡司馬。明年秋，送客湓浦口。聞船中夜彈琵琶者。聽其音，錚錚然有京都聲。問其人，本長安倡女，嘗學琵琶於穆、曹二善才。年長色衰，委身為賈人婦。遂命酒，使快彈數曲。", "曲罷，憫默。自敍少小時歡樂事，今漂淪鷦顇，轉徙於江湖間。予出官二年，恬然自安，感斯人言，是夕始覺有遷謫意，因為長句歌以贈之。凡六百一十二言，命曰琵琶行。", "潯陽江頭夜送客，楓葉荻花秋索索。主人下馬客在船，舉酒欲飲無管弦。醉不成歡慘將別，別時茫茫江浸月。忽聞水上琵琶聲，主人忘歸客不發。", "尋聲暗問彈者誰？琵琶聲停欲語遲。移船相近邀相見，添酒迴燈重開宴。千呼萬喚始出來，猶抱琵琶半遮面。", "轉軸撥弦三兩聲，未成曲調先有情。弦弦掩抑聲聲思，似訴平生不得意。低眉信手續續彈，說盡心中無限事。", "輕攏慢撚抹復挑，初為霓裳後六么。大弦嘈嘈如急雨，小弦切切如私語。嘈嘈切切錯雜彈，大珠小珠落玉盤。間關鶯語花底滑，幽咽泉流水下灘。水泉冷澀弦疑絕，疑絕不通聲暫歇。", "別有幽愁暗恨生，此時無聲勝有聲。銀缾乍破水漿迸，鐵騎突出刀槍鳴。曲終收撥當心畫，四弦一聲如裂帛。東舟西舫悄無言，唯見江心秋月白。", "沈吟放撥插弦中，整頓衣裳起斂容，自言本是京城女，家在蝦蟇陵下住。十三學得琵琶成，名屬教坊第一部。曲罷曾教善才伏，妝成每被秋娘妒。五陵年少爭纏頭，一曲紅綃不知數。鈿頭雲篦擊節碎，血色羅裙翻酒汙。", "今年歡笑復明年，秋月春風等閒度。弟走從軍阿姨死，暮去朝來顏色故，門前冷落鞍馬稀，老大嫁作商人婦。", "商人重利輕別離，前月浮梁買茶去，去來江口守空船，繞船月明江水寒。夜深忽夢少年事，夢啼妝淚紅闌干。", "我聞琵琶已歎息，又聞此語重唧唧。同是天涯淪落人，相逢何必曾相識。我從去年辭帝京，謫居臥病潯陽城。潯陽小處無音樂，終歲不聞絲竹聲。住近湓江地低溼，黃蘆苦竹繞宅生。", "其間旦暮聞何物？杜鵑啼血猿哀鳴。春江花朝秋月夜，往往取酒還獨傾。豈無山歌與村笛？嘔啞嘲哳難為聽。今夜聞君琵琶語，如聽仙樂耳暫明。莫辭更坐彈一曲，為君翻作琵琶行。"], "quote": ["元和十年，予左遷九江郡司馬。明年秋，送客湓浦口。聞船中夜彈琵琶者。聽其音，錚錚然有京都聲。問其人，本長安倡女，嘗學琵琶於穆、曹二善才。年長色衰，委身為賈人婦。遂命酒，使快彈數曲。", "曲罷，憫默。自敍少小時歡樂事，今漂淪鷦顇，轉徙於江湖間。予出官二年，恬然自安，感斯人言，是夕始覺有遷謫意，因為長句歌以贈之。凡六百一十二言，命曰琵琶行。", "潯陽江頭夜送客，楓葉荻花秋索索。主人下馬客在船，舉酒欲飲無管弦。醉不成歡慘將別，別時茫茫江浸月。忽聞水上琵琶聲，主人忘歸客不發。", "尋聲暗問彈者誰？琵琶聲停欲語遲。移船相近邀相見，添酒迴燈重開宴。千呼萬喚始出來，猶抱琵琶半遮面。"], "intro": "《琵琶行》選自《全唐詩》卷四百三十五，作於唐憲宗元和十一年（八一六）秋。據白居易自序云，作者於憲宗元和十年（八一五）被貶為九江郡（今江西九江）司馬。次年秋，送客於湓浦口。夜中偶逢琵琶女，從她的漂泊遭遇，想到自己仕途上的失意坎坷，遂寫成《琵琶", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%90%B5%E7%90%B6%E8%A1%8C++%E4%B8%A6%E5%BA%8F"}, {"title": "慈烏夜啼", "author": "白居易", "period": "唐", "form": "詩", "theme": "田園幽居", "mood": "ethereal", "lines": ["慈烏失其母，啞啞吐哀音。晝夜不飛去，經年守故林。", "夜夜夜半啼，聞者為霑襟。聲中如告訴，未盡反哺心。", "百鳥豈無母？爾獨哀怨深。應是母慈重，使爾悲不任。", "昔有吳起者，母歿喪不臨。嗟哉斯徒輩，其心不如禽！", "慈烏復慈烏，鳥中之曾參。"], "quote": ["慈烏失其母，啞啞吐哀音。晝夜不飛去，經年守故林。", "夜夜夜半啼，聞者為霑襟。聲中如告訴，未盡反哺心。", "百鳥豈無母？爾獨哀怨深。應是母慈重，使爾悲不任。", "昔有吳起者，母歿喪不臨。嗟哉斯徒輩，其心不如禽！"], "intro": "《慈烏夜啼》選自《全唐詩》卷四百二十四，屬諷諭詩，是作者於元和六年（八一一）或七年初，他的母親去世後不久，回鄉丁憂時寫成。慈烏是烏鳥的一種，嘴小、性慈孝。這種鳥在母鳥死後，常徘徊於母鳥的故巢，每在半夜哀啼。作者除以這首詩悼念亡母之外，並用以", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%85%88%E7%83%8F%E5%A4%9C%E5%95%BC"}, {"title": "新豐折臂翁", "author": "白居易", "period": "唐", "form": "詩", "theme": "送別行旅", "mood": "snow_winter", "lines": ["新豐老翁八十八，頭鬢眉鬚皆似雪。玄孫扶向店前行，左臂憑肩右臂折。問翁「臂折來幾年？」兼問「致折何因緣？」翁云「貫屬新豐縣，生逢聖代無征戰。慣聽梨園歌管聲，不識旗槍與弓箭。無何天寶大徵兵，戶有三丁點一丁。點得驅將何處去？五月萬里雲南行。聞道雲南有瀘水，椒花落時瘴煙起。大軍徒涉水如湯，未過十人二三死。邨南邨北哭聲哀，兒別耶孃夫別妻，皆云前後征蠻者，千萬人行無一回。是時翁年二十四，兵部牒中有名字。夜深不敢使人知，偷將大石槌折臂。張弓簸旗俱不堪，從茲使免征雲南。骨碎筋傷非不苦，且圖揀退歸鄉土。此臂折來六十年，一肢雖廢一身全。至今風雨陰寒夜，直到天明痛不眠。痛不眠，終不悔，且喜老身今獨在。不然當時瀘水頭，身死魂孤骨不收。應作雲南望鄉鬼，萬人冢上哭呦呦！」老人言，君聽取！君不聞開元宰相宋開府，不賞邊功防黷武？又不聞天寶宰相楊國忠，欲求恩幸立邊功？邊功未立生民怨，請問新豐折臂翁。"], "quote": ["新豐老翁八十八，頭鬢眉鬚皆似雪。玄孫扶向店前行，左臂憑肩右臂折。問翁「臂折來幾年？」兼問「致折何因緣？」翁云「貫屬新豐縣，生逢聖代無征戰。慣聽梨園歌管聲，不識旗槍與弓箭。無何天寶大徵兵，戶有三丁點一丁。點得驅將何處去？五月萬里雲南行。聞道雲南有瀘水，椒花落時瘴煙起。大軍徒涉水如湯，未過十人二三死。邨南邨北哭聲哀，兒別耶孃夫別妻，皆云前後征蠻者，千萬人行無一回。是時翁年二十四，兵部牒中有名字。夜深不敢使人知，偷將大石槌折臂。張弓簸旗俱不堪，從茲使免征雲南。骨碎筋傷非不苦，且圖揀退歸鄉土。此臂折來六十年，一肢雖廢一身全。至今風雨陰寒夜，直到天明痛不眠。痛不眠，終不悔，且喜老身今獨在。不然當時瀘水頭，身死魂孤骨不收。應作雲南望鄉鬼，萬人冢上哭呦呦！」老人言，君聽取！君不聞開元宰相宋開府，不賞邊功防黷武？又不聞天寶宰相楊國忠，欲求恩幸立邊功？邊功未立生民怨，請問新豐折臂翁。"], "intro": "這首詩是白居易《新樂府》五十首中的第九篇。原文在題下自注：「戒邊功也。」乃反對侵略戰爭的詩。折臂翁，譯為語體，即斷了胳膊的老頭兒。唐天寶末年，楊國忠為宰相，為了邀功固寵，輕啟邊禍，徵兵到雲南去打仗，新豐縣的一個居民，因在被徵之列，暗將自己胳", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%96%B0%E8%B1%90%E6%8A%98%E8%87%82%E7%BF%81"}, {"title": "暮江吟", "author": "白居易", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["一道殘陽鋪水中，半江瑟瑟半江紅。", "可憐九月初三夜，露似真珠月似弓。"], "quote": ["一道殘陽鋪水中，半江瑟瑟半江紅。", "可憐九月初三夜，露似真珠月似弓。"], "intro": "這首詩的寫作時間，一說是白居易在江州司馬任（公元816——818）上作；一說是長慶二年（公元822）白居易赴任杭州刺史途中所作。其實這類即景之作，大可不必考究在何時何地所作。總之，在某一刻，白居易暫且放下官場上的煩惱，投入大自然的懷抱裏，領", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9A%AE%E6%B1%9F%E5%90%9F"}, {"title": "賣炭翁", "author": "白居易", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["賣炭翁，伐薪燒炭南山中。滿面塵灰煙火色，兩鬢蒼蒼十指黑。賣炭得錢何所營？身上衣裳口中食。可憐身上衣正單，心憂炭賤願天寒！", "夜來城上一尺雪，曉駕炭車輾冰轍。牛困人飢日已高，市南門外泥中歇。翩翩兩騎來是誰，黃衣使者白衫兒。", "手把文書口稱敕，迴車叱牛牽向北。一車炭，千餘斤，宮使驅將惜不得。半匹紅紗一丈綾，繫向牛頭充炭直。"], "quote": ["賣炭翁，伐薪燒炭南山中。滿面塵灰煙火色，兩鬢蒼蒼十指黑。賣炭得錢何所營？身上衣裳口中食。可憐身上衣正單，心憂炭賤願天寒！", "夜來城上一尺雪，曉駕炭車輾冰轍。牛困人飢日已高，市南門外泥中歇。翩翩兩騎來是誰，黃衣使者白衫兒。", "手把文書口稱敕，迴車叱牛牽向北。一車炭，千餘斤，宮使驅將惜不得。半匹紅紗一丈綾，繫向牛頭充炭直。"], "intro": "《賣炭翁》選自《全唐詩》卷四百二十七，是《新樂府》之一。作者自注：「苦宮市也。」宮市是皇帝派宦官到市集購物，後發展為變相掠奪的一種方式。唐德宗貞元末年，凡宮中所需之物，均由宦官採辦。宦官以「宮市」的名義，看中甚麼東西便拿走，或象徵性給點錢，", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B3%A3%E7%82%AD%E7%BF%81"}, {"title": "賦得古原草送別", "author": "白居易", "period": "唐", "form": "詩", "theme": "送別行旅", "mood": "spring_breeze", "lines": ["離離原上草，一歲一枯榮。", "野火燒不盡，春風吹又生。", "遠芳侵古道，晴翠接荒城。", "又送王孫去，萋萋滿別情。"], "quote": ["離離原上草，一歲一枯榮。", "野火燒不盡，春風吹又生。", "遠芳侵古道，晴翠接荒城。", "又送王孫去，萋萋滿別情。"], "intro": "《賦得古原草送別》選自《全唐詩》卷四百三十六，一作《古原草》，為白居易少年時代之作。所謂「賦得」，凡指定、限定的詩題，按例須在題目上加「賦得」二字。據說此詩是作者準備應考時的習作，故也加「賦得」二字。本詩描寫古原上離離春草的景象，寄託了送別", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B3%A6%E5%BE%97%E5%8F%A4%E5%8E%9F%E8%8D%89%E9%80%81%E5%88%A5"}, {"title": "憶江南（其一）（江南好）", "author": "白居易", "period": "唐", "form": "詞", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["江南好，風景舊曾諳。日出江花紅勝火，春來江水綠如藍。能不憶江南？"], "quote": ["江南好，風景舊曾諳。日出江花紅勝火，春來江水綠如藍。能不憶江南？"], "intro": "《憶江南》（江南好）選自《白居易集》卷三十四。《憶江南》為詞牌名，原作《望江南》或《夢江南》，白居易改作此名，又稱《謝秋娘》。原題共三首，今選其中一首。 江南，此指蘇州、杭州一帶。作者晚年居於洛陽，偶憶江南宦遊生活，特製此曲，並名為《憶江南", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%86%B6%E6%B1%9F%E5%8D%97%EF%BC%88%E5%85%B6%E4%B8%80%EF%BC%89%EF%BC%88%E6%B1%9F%E5%8D%97%E5%A5%BD%EF%BC%89"}, {"title": "燕詩", "author": "白居易", "period": "唐", "form": "詩", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["叟有愛子，背叟逃去，叟甚悲念之。叟少年時，亦嘗如是。故作《燕詩》以諭之矣。", "梁上有雙燕，翩翩雄與雌；", "銜泥兩椽間，一巢生四兒。", "四兒日夜長，索食聲孜孜，", "青蟲不易捕，黃口無飽期。", "嘴爪雖欲弊，心力不知疲。", "須臾十來往，猶恐巢中飢。", "辛勤三十日，母瘦雛漸肥，", "喃喃教言語，一一刷毛衣。", "一旦羽翼成，引上庭樹枝；", "舉翅不回顧，隨風四散飛。", "雌雄空中鳴，聲盡呼不歸，"], "quote": ["叟有愛子，背叟逃去，叟甚悲念之。叟少年時，亦嘗如是。故作《燕詩》以諭之矣。", "梁上有雙燕，翩翩雄與雌；", "銜泥兩椽間，一巢生四兒。", "四兒日夜長，索食聲孜孜，"], "intro": "白居易是「新樂府運動」的倡導者，所作「新樂府詩」影響較大，《燕詩示劉叟》是其中的代表作。 這首詩原有題注：「叟有愛子，背叟逃去，叟甚悲念之。叟少年時，亦嘗如是。故作《燕詩》以諭之矣。」意即有一個姓劉的老翁，因為心愛的兒子不顧他而離去，老翁十", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%87%95%E8%A9%A9"}, {"title": "近試上張水部", "author": "朱慶餘", "period": "唐", "form": "詩", "theme": "田園幽居", "mood": "vast_river", "lines": ["洞房昨夜停紅燭，待曉堂前拜舅姑。", "妝罷低聲問夫婿，畫眉深淺入時無。"], "quote": ["洞房昨夜停紅燭，待曉堂前拜舅姑。", "妝罷低聲問夫婿，畫眉深淺入時無。"], "intro": "唐代科舉考試前，各地舉子匯聚京城，他們把自己平時的詩文投獻給京城的官員，希望能獲得賞識，從而被推薦。朱慶餘這首詩的用意也在於此。「張水部」指時任水部員外郎的張籍。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%BF%91%E8%A9%A6%E4%B8%8A%E5%BC%B5%E6%B0%B4%E9%83%A8"}, {"title": "白雪歌送武判官歸京", "author": "岑參", "period": "唐", "form": "詩", "theme": "送別行旅", "mood": "snow_winter", "lines": ["北風捲地白草折，胡天八月即飛雪。", "忽如一夜春風來，千樹萬樹梨花開。", "散入珠簾濕羅幕，狐裘不煖錦衾薄。", "將軍角弓不得控，都護鐵衣冷難著。", "瀚海闌干百丈冰，愁雲黲淡萬里凝。", "中軍置酒飲歸客，胡琴琵琶與羌笛。", "紛紛暮雪下轅門，風掣紅旗凍不翻。", "輪臺東門送君去，去時雪滿天山路。", "山迴路轉不見君，雪上空留馬行處。"], "quote": ["北風捲地白草折，胡天八月即飛雪。", "忽如一夜春風來，千樹萬樹梨花開。", "散入珠簾濕羅幕，狐裘不煖錦衾薄。", "將軍角弓不得控，都護鐵衣冷難著。"], "intro": "《白雪歌送武判官歸京》選自《全唐詩》卷一百九十九。天寶十三年（七五四），岑參充任安西北庭節度使封常清的判官，奉命再度出塞，到達今新疆西部地區。武判官其人及生平今已無可考，或即岑參的前任判官。岑參接任後為他送行，遂寫下這首詠雪送行的名作。杜甫", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%99%BD%E9%9B%AA%E6%AD%8C%E9%80%81%E6%AD%A6%E5%88%A4%E5%AE%98%E6%AD%B8%E4%BA%AC"}, {"title": "逢入京使", "author": "岑參", "period": "唐", "form": "詩", "theme": "田園幽居", "mood": "ethereal", "lines": ["故園東望路漫漫，雙袖龍鍾淚不乾。", "馬上相逢無紙筆，憑君傳語報平安。"], "quote": ["故園東望路漫漫，雙袖龍鍾淚不乾。", "馬上相逢無紙筆，憑君傳語報平安。"], "intro": "這首詩寫於唐玄宗天寶八載（749），岑參第一次遠赴安西任職的途中。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%80%A2%E5%85%A5%E4%BA%AC%E4%BD%BF"}, {"title": "凱歌", "author": "岑參", "period": "唐", "form": "詩", "theme": "邊塞豪放", "mood": "snow_winter", "lines": ["暮雨旌旗濕未乾，胡塵白草日光寒；", "昨夜將軍連曉戰，番軍只見馬空鞍。"], "quote": ["暮雨旌旗濕未乾，胡塵白草日光寒；", "昨夜將軍連曉戰，番軍只見馬空鞍。"], "intro": "這首詩是岑參《獻封大夫破播仙凱歌》組詩的第六首。唐玄宗天寶十三載（754），封常清攻打播仙鎮，從地理位置看，應是與吐蕃之間的戰爭。當時岑參在封常清的幕府供職，是年冬天，創作了這組詩；前四首寫凱旋，後兩首追敘戰鬥情況。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%87%B1%E6%AD%8C"}, {"title": "磧中作", "author": "岑參", "period": "唐", "form": "詩", "theme": "邊塞豪放", "mood": "ethereal", "lines": ["走馬西來欲到天，辭家見月兩回圓。", "今夜未知何處宿，平沙莽莽絕人煙。"], "quote": ["走馬西來欲到天，辭家見月兩回圓。", "今夜未知何處宿，平沙莽莽絕人煙。"], "intro": "這是沙漠（磧）行軍途中野營生活的剪影，大約天寶八載（七四九）作者第一次從軍西征時在沙漠中所作。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%A3%A7%E4%B8%AD%E4%BD%9C"}, {"title": "月下獨酌（其一）", "author": "李白", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "spring_breeze", "lines": ["花間一壺酒，獨酌無相親。", "舉杯邀明月，對影成三人。", "月既不解飲，影徒隨我身。", "暫伴月將影，行樂須及春。", "我歌月徘徊，我舞影零亂。", "醒時同交歡，醉後各分散。", "永結無情遊，相期邈雲漢。"], "quote": ["花間一壺酒，獨酌無相親。", "舉杯邀明月，對影成三人。", "月既不解飲，影徒隨我身。", "暫伴月將影，行樂須及春。"], "intro": "《月下獨酌》為五言古詩，共四首，此處選的為第一首。據張健《李白詩選：大唐詩仙》一書的考證，這首詩約作於天寶三年（公元744），李白在長安任翰林供奉。當時，他與楊國忠不和，亦得罪了高力士，受到了排擠和讒毀，漸為玄宗疏遠，翰林供奉一職，其實只是", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9C%88%E4%B8%8B%E7%8D%A8%E9%85%8C%EF%BC%88%E5%85%B6%E4%B8%80%EF%BC%89"}, {"title": "早發白帝城", "author": "李白", "period": "唐", "form": "詩", "theme": "江河湖海", "mood": "vast_river", "lines": ["朝辭白帝彩雲間，千里江陵一日還。", "兩岸猿聲啼不盡，輕舟已過萬重山。"], "quote": ["朝辭白帝彩雲間，千里江陵一日還。", "兩岸猿聲啼不盡，輕舟已過萬重山。"], "intro": "《早發白帝城》選自《全唐詩》卷一百八十一，一作「白帝下江陵」、「下江陵」。白帝城，地名，在今四川奉節東的白帝山上。唐肅宗乾元二年（七五九）三月，李白因永王璘案的牽連，被流放夜郎。至白帝城遇赦，旋即乘舟東下江陵。此詩是江行途中所作，描寫舟行經", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%97%A9%E7%99%BC%E7%99%BD%E5%B8%9D%E5%9F%8E"}, {"title": "行路難（其一）", "author": "李白", "period": "唐", "form": "詩", "theme": "江河湖海", "mood": "snow_winter", "lines": ["金樽清酒斗十千，玉盤珍羞直萬錢。", "停杯投箸不能食，拔劍四顧心茫然。", "欲渡黃河冰塞川，將登太行雪滿山。", "閒來垂釣碧溪上，忽復乘舟夢日邊。", "行路難！行路難！多歧路，今安在？", "長風破浪會有時，直掛雲帆濟滄海。"], "quote": ["金樽清酒斗十千，玉盤珍羞直萬錢。", "停杯投箸不能食，拔劍四顧心茫然。", "欲渡黃河冰塞川，將登太行雪滿山。", "閒來垂釣碧溪上，忽復乘舟夢日邊。"], "intro": "〈行路難〉是古樂府《雜曲歌辭》舊題。唐玄宗天寶三載（744），李白離開長安時所作；共三首，這是第一首。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A1%8C%E8%B7%AF%E9%9B%A3%EF%BC%88%E5%85%B6%E4%B8%80%EF%BC%89"}, {"title": "宣州謝朓樓餞别校書叔雲", "author": "李白", "period": "唐", "form": "詩", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["棄我去者昨日之日不可留，亂我心者今日之日多煩憂。", "長風萬里送秋鴈，對此可以酣高樓。", "蓬萊文章建安骨，中間小謝又清發。", "俱懷逸興壯思飛，欲上青天攬明月。", "抽刀斷水水更流，舉杯消愁愁更愁。", "人生在世不稱意。明朝散髮弄扁舟。"], "quote": ["棄我去者昨日之日不可留，亂我心者今日之日多煩憂。", "長風萬里送秋鴈，對此可以酣高樓。", "蓬萊文章建安骨，中間小謝又清發。", "俱懷逸興壯思飛，欲上青天攬明月。"], "intro": "藉餞別校書叔雲，抒發心中的憂愁，並同情對方之不遇；逸興標舉，奇情橫想，是李集中浪漫的名作。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%AE%A3%E5%B7%9E%E8%AC%9D%E6%9C%93%E6%A8%93%E9%A4%9E%E5%88%AB%E6%A0%A1%E6%9B%B8%E5%8F%94%E9%9B%B2"}, {"title": "春夜宴從弟桃花園序", "author": "李白", "period": "唐", "form": "文", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["夫天地者，萬物之逆旅也；光陰者，百代之過客也。而浮生若夢，為歡幾何？古人秉燭夜遊，良有以也。況陽春召我以煙景，大塊假我以文章。會桃花之芳園，序天倫之樂事。群季俊秀，皆為惠連；吾人詠歌，獨慚康樂。幽賞未已，高談轉清。開瓊筵以坐花，飛羽觴而醉月。不有佳詠，何伸雅懷？如詩不成，罰依金谷酒數。"], "quote": ["夫天地者，萬物之逆旅也；光陰者，百代之過客也。而浮生若夢，為歡幾何？古人秉燭夜遊，良有以也。況陽春召我以煙景，大塊假我以文章。會桃花之芳園，序天倫之樂事。群季俊秀，皆為惠連；吾人詠歌，獨慚康樂。幽賞未已，高談轉清。開瓊筵以坐花，飛羽觴而醉月。不有佳詠，何伸雅懷？如詩不成，罰依金谷酒數。"], "intro": "序是文體的一種。古人宴飲，每推舉一人撰寫文章，記述聚會酬唱的緣起，並多作為當時所作詩歌的總序，如王羲之的《蘭亭集序》；後來這類文章獨立成篇，無詩配合亦可單作，如本篇即是。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%98%A5%E5%A4%9C%E5%AE%B4%E5%BE%9E%E5%BC%9F%E6%A1%83%E8%8A%B1%E5%9C%92%E5%BA%8F"}, {"title": "秋浦歌", "author": "李白", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["白髮三千丈，緣愁似个長。", "不知明鏡裏，何處得秋霜。"], "quote": ["白髮三千丈，緣愁似个長。", "不知明鏡裏，何處得秋霜。"], "intro": "大約在唐代天寶十二年（公元753），已年近半百的李白漫遊到秋浦（今安徽省貴池縣西。浦，粵：[普pou2]；普：[pŭ]。），寫了十七首《秋浦歌》，這是其中的第十五首。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%A7%8B%E6%B5%A6%E6%AD%8C"}, {"title": "送友人", "author": "李白", "period": "唐", "form": "詩", "theme": "送別行旅", "mood": "vast_river", "lines": ["青山橫北郭，白水遶東城。此地一為別，孤蓬萬里征。", "浮雲遊子意，落日故人情。揮手自茲去，蕭蕭班馬鳴。"], "quote": ["青山橫北郭，白水遶東城。此地一為別，孤蓬萬里征。", "浮雲遊子意，落日故人情。揮手自茲去，蕭蕭班馬鳴。"], "intro": "《送友人》選自《全唐詩》卷一百七十七，是一首家喻戶曉的送別名作。此詩寫作者為友人送別的情境，抒發難捨難分的深情。詩人先以「青山」、「白水」描摹出一個山明水秀的送別背景，再用「浮雲」、「落日」的意象作對比，烘托出詩人惆悵的心情。結句「揮手自茲", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%80%81%E5%8F%8B%E4%BA%BA"}, {"title": "將進酒", "author": "李白", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["君不見黃河之水天上來，奔流到海不復回？", "君不見高堂明鏡悲白髮，朝如青絲暮成雪。", "人生得意須盡歡，莫使金樽空對月！", "天生我材必有用，千金散盡還復來。", "烹羊宰牛且為樂，會須一飲三百杯。", "岑夫子，丹邱生；將進酒，君莫停。", "與君歌一曲，請君為我傾耳聽。", "鐘鼓饌玉不足貴，但願長醉不用醒。", "古來聖賢皆寂寞，唯有飲者留其名。", "陳王昔時宴平樂，斗酒十千恣歡謔。", "主人何為言少錢，徑須沽取對君酌。", "五花馬，千金裘；呼兒將出換美酒，與爾同銷萬古愁。"], "quote": ["君不見黃河之水天上來，奔流到海不復回？", "君不見高堂明鏡悲白髮，朝如青絲暮成雪。", "人生得意須盡歡，莫使金樽空對月！", "天生我材必有用，千金散盡還復來。"], "intro": "李白特別喜歡飲酒，在詩中多次提到酒。李白才情橫逸，自視甚高，但不能適應官場，際遇一直欠佳。他的嗜酒，大概也有借酒消愁的味道。李白的名篇《將進酒》便是專門以飲酒為題。 《將進酒》原是古樂府篇名，漢代的鼓吹鐃歌十八曲就有《將進酒》，題意是勸飲歌", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B0%87%E9%80%B2%E9%85%92"}, {"title": "望廬山瀑布（其二）", "author": "李白", "period": "唐", "form": "詩", "theme": "山水登臨", "mood": "vast_river", "lines": ["日照香爐生紫煙，遙看瀑布挂前川。", "飛流直下三千尺，疑是銀河落九天。"], "quote": ["日照香爐生紫煙，遙看瀑布挂前川。", "飛流直下三千尺，疑是銀河落九天。"], "intro": "《望廬山瀑布》選自《全唐詩》卷一百八十，一作「望廬山香爐峰瀑布」或「望廬山瀑布水」。李白此題寫有兩首詩，一首為五言古體，此為其二。廬山，古名南障山，又名匡山，總稱匡廬，在今江西九江市南，瀑布為廬山奇景之一。本詩當作於入京之前，大約在開元十四", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9C%9B%E5%BB%AC%E5%B1%B1%E7%80%91%E5%B8%83%EF%BC%88%E5%85%B6%E4%BA%8C%EF%BC%89"}, {"title": "菩薩蠻（平林漠漠煙如織）", "author": "李白", "period": "唐", "form": "詞", "theme": "田園幽居", "mood": "snow_winter", "lines": ["平林漠漠煙如織，寒山一帶傷心碧。暝色入高樓，有人樓上愁。", "玉階空佇立，宿鳥歸飛急。何處是回程，長亭更短亭。"], "quote": ["平林漠漠煙如織，寒山一帶傷心碧。暝色入高樓，有人樓上愁。", "玉階空佇立，宿鳥歸飛急。何處是回程，長亭更短亭。"], "intro": "《菩薩蠻》（平林漠漠煙如織）選自《唐五代詞》。此詞不見於唐人載籍，北宋釋文瑩《湘山野錄》、南宋黃昇《唐宋諸賢絕妙詞選》均以為是李白之作。黃昇更謂《菩薩蠻》（平林漠漠煙如織）與《憶秦娥》（簫聲咽）二詞為「百代詞曲之祖」。 《菩薩蠻》本是唐玄宗", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%8F%A9%E8%96%A9%E8%A0%BB%EF%BC%88%E5%B9%B3%E6%9E%97%E6%BC%A0%E6%BC%A0%E7%85%99%E5%A6%82%E7%B9%94%EF%BC%89"}, {"title": "登金陵鳳凰臺", "author": "李白", "period": "唐", "form": "詩", "theme": "山水登臨", "mood": "vast_river", "lines": ["鳳凰臺上鳳凰遊，鳳去臺空江自流。", "吳宮花草埋幽徑，晉代衣冠成古丘。", "三山半落青天外，二水中分白鷺洲。", "總為浮雲能蔽日，長安不見使人愁。"], "quote": ["鳳凰臺上鳳凰遊，鳳去臺空江自流。", "吳宮花草埋幽徑，晉代衣冠成古丘。", "三山半落青天外，二水中分白鷺洲。", "總為浮雲能蔽日，長安不見使人愁。"], "intro": "《登金陵鳳凰臺》選自《全唐詩》卷一百八十。據說太白作此詩，原欲與崔顥《黃鶴樓》爭勝，故用崔顥詩的原韻，句法也有模倣前詩之意。金陵，即今南京。《江南通志》云：「宋元嘉十六年（四三九），有三鳥翔集山間，文彩五色，狀如孔雀，時人謂之鳳凰，起臺於山", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%99%BB%E9%87%91%E9%99%B5%E9%B3%B3%E5%87%B0%E8%87%BA"}, {"title": "黃鶴樓送孟浩然之廣陵", "author": "李白", "period": "唐", "form": "詩", "theme": "送別行旅", "mood": "vast_river", "lines": ["故人西辭黃鶴樓，煙花三月下揚州。", "孤帆遠影碧山盡，唯見長江天際流。"], "quote": ["故人西辭黃鶴樓，煙花三月下揚州。", "孤帆遠影碧山盡，唯見長江天際流。"], "intro": "《黃鶴樓送孟浩然之廣陵》選自《全唐詩》卷一百七十四，約寫於開元十六年（七二八）。黃鶴樓，舊址在武昌蛇山黃鶴磯上，今在湖北武漢長江岸邊。之，去的意思。廣陵，即揚州（今江蘇揚州）。古人慣以詩詞送別，這是李白於武昌黃鶴樓送別好友孟浩然之作。以「孤", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%BB%83%E9%B6%B4%E6%A8%93%E9%80%81%E5%AD%9F%E6%B5%A9%E7%84%B6%E4%B9%8B%E5%BB%A3%E9%99%B5"}, {"title": "蜀道難", "author": "李白", "period": "唐", "form": "詩", "theme": "山水登臨", "mood": "autumn_sunset", "lines": ["噫，吁嚱，危乎高哉！", "蜀道之難難於上青天！", "蠶叢及魚鳧，開國何茫然！", "爾來四萬八千歲，不與秦塞通人煙。", "西當太白有鳥道，可以橫絕峨眉巔。", "地崩山摧壯士死，然後天梯石棧方鉤連。", "上有六龍回日之高標，下有衝波逆折之回川，", "黃鶴之飛尚不得過，猿猱欲度愁攀緣。", "青泥何盤盤，百步九折縈巖巒。", "捫參歷井仰脅息，以手撫膺坐長歎！", "問君西遊何時還？畏途巉巖不可攀。", "但見悲鳥號古木，雄飛雌從繞林間；"], "quote": ["噫，吁嚱，危乎高哉！", "蜀道之難難於上青天！", "蠶叢及魚鳧，開國何茫然！", "爾來四萬八千歲，不與秦塞通人煙。"], "intro": "「蜀道難」是古樂府詩題之一，在相和歌瑟調三十八曲裏面，即吟詠蜀道（自中原通往四川的道路）險阻情況的詩。李白集中，樂府詩很多，大都援用樂府舊題，另為新的創造，用不同的意境來表達同一題旨，等於原題的改作，本詩即是李白這類樂府詩中，極為世人稱賞的", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%9C%80%E9%81%93%E9%9B%A3"}, {"title": "憶秦娥（簫聲咽）", "author": "李白", "period": "唐", "form": "詞", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["簫聲咽，秦娥夢橫秦樓月。秦樓月，年年柳色，覇陵傷別。", "樂遊原上清秋節，咸陽古道音塵絕。音塵絕，西風殘照，漢家陵闕。"], "quote": ["簫聲咽，秦娥夢橫秦樓月。秦樓月，年年柳色，覇陵傷別。", "樂遊原上清秋節，咸陽古道音塵絕。音塵絕，西風殘照，漢家陵闕。"], "intro": "《憶秦娥》（簫聲咽）選自《唐五代詞》。此詞不見於唐人載籍，北宋釋文瑩《湘山野錄》、南宋黃昇《唐宋諸賢絕妙詞選》均以為是李白之作。黃昇更謂《菩薩蠻》（平林漠漠煙如織）與《憶秦娥》（簫聲咽）二詞為「百代詞曲之祖」。 《憶秦娥》以調為題，內容寫秦", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%86%B6%E7%A7%A6%E5%A8%A5%EF%BC%88%E7%B0%AB%E8%81%B2%E5%92%BD%EF%BC%89"}, {"title": "獨坐敬亭山", "author": "李白", "period": "唐", "form": "詩", "theme": "山水登臨", "mood": "snow_winter", "lines": ["眾鳥高飛盡，孤雲獨去閒。", "相看兩不厭，只有敬亭山。"], "quote": ["眾鳥高飛盡，孤雲獨去閒。", "相看兩不厭，只有敬亭山。"], "intro": "此詩作於唐代天寶十二載（公元753），李白遭讒言譭謗被迫棄官離京已有十年。十年中他到處漂泊，飽嘗人間冷暖，因此憎惡世態炎涼，意欲寄情山水，尋求平淡恬靜的生活。 敬亭山，在今安徽省宣城，山高數百丈，千巖萬壑，風景幽美。山上有敬亭，南齊詩人謝眺", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%8D%A8%E5%9D%90%E6%95%AC%E4%BA%AD%E5%B1%B1"}, {"title": "靜夜思", "author": "李白", "period": "唐", "form": "詩", "theme": "田園幽居", "mood": "snow_winter", "lines": ["牀前明月光，疑是地上霜。", "舉頭望山月，低頭思故鄉。"], "quote": ["牀前明月光，疑是地上霜。", "舉頭望山月，低頭思故鄉。"], "intro": "《靜夜思》選自《全唐詩》卷一百六十五。詩題一作《夜思》，寫客途中靜夜見月而牽動了思鄉之情。全詩語言簡潔自然，構思卻極細緻深曲。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%9D%9C%E5%A4%9C%E6%80%9D"}, {"title": "贈汪倫", "author": "李白", "period": "唐", "form": "詩", "theme": "春水花鳥", "mood": "autumn_sunset", "lines": ["李白乘舟將欲行，忽聞岸上踏歌聲。", "桃花潭水深千尺，不及汪倫送我情。"], "quote": ["李白乘舟將欲行，忽聞岸上踏歌聲。", "桃花潭水深千尺，不及汪倫送我情。"], "intro": "天寶十四載（公元755），李白前往涇縣（今屬安徽省）桃花潭遊覽，當地村民汪倫以美酒款待，臨走時李白寫下這首詩相贈。 傳說汪倫非常仰慕李白，當他聽說李白漫遊到了秋浦，便很想請他到自己的家鄉桃花潭遊玩，但又怕他不來，於是寫信給李白，說家鄉有「萬", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B4%88%E6%B1%AA%E5%80%AB"}, {"title": "夜上受降城聞笛", "author": "李益", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["回樂峰前沙似雪，受降城下月如霜。", "不知何處吹蘆管，一夜征人盡望鄉。"], "quote": ["回樂峰前沙似雪，受降城下月如霜。", "不知何處吹蘆管，一夜征人盡望鄉。"], "intro": "李益《夜上受降城聞笛》選自《全唐詩》卷二百八十三，一作「戎昱詩」。貞觀二十年（六四六），唐太宗曾親臨靈州（今寧夏回族自治區靈武）接受突厥一部的投降，受降城一名即由此而來。作者夜登城樓，眼見白沙似雪、月色如霜，此時此際，聞遠處傳來蘆笛清音，一", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%A4%9C%E4%B8%8A%E5%8F%97%E9%99%8D%E5%9F%8E%E8%81%9E%E7%AC%9B"}, {"title": "弔古戰場文", "author": "李華", "period": "唐", "form": "文", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["浩浩乎平沙無垠，夐不見人。河水縈帶，羣山糾紛。黯兮慘悴，風悲日曛。蓬斷草枯，凜若霜晨。鳥飛不下，獸鋌亡羣。亭長告余曰︰「此古戰場也，常覆三軍。往往鬼哭，天陰則聞。」", "傷心哉！秦歟？漢歟？將近代歟？吾聞夫齊魏徭戍，荊韓召募；萬里奔走，連年暴露。沙草晨牧，河冰夜渡。地闊天長，不知歸路。寄身鋒刃，腷臆誰愬？", "秦漢而還，多事四夷；中州耗斁，無世無之。古稱戎夏，不抗王師。文教失宣，武臣用奇。奇兵有異於仁義，王道迂闊而莫為！", "嗚呼噫嘻！吾想夫北風振漠，胡兵伺便；主將驕敵，期門受戰。野豎旄旗，川迴組練。法重心駭，威尊命賤。利鏃穿骨，驚沙入面，主客相搏，山川震眩。聲析江河，勢崩雷電。至若窮陰凝閉，凜冽海隅。積雪沒脛，堅冰在鬚。鷙鳥休巢，征馬踟躕。", "繒纊無溫，墮指裂膚。當此苦寒，天假強胡，憑陵殺氣，以相翦屠。徑截輜重，橫攻士卒；都尉新降，將軍覆沒。屍填巨港之岸，血滿長城之窟。無貴無賤，同為枯骨，可勝言哉？鼓衰兮力盡，矢竭兮弦絕，白刃交兮寶刀折，兩軍蹙兮生死決。", "降矣哉？終身夷狄！戰矣哉？骨暴沙礫！鳥無聲兮山寂寂，夜正長兮風淅淅。魂魄結兮天沉沉，鬼神聚兮雲冪冪。日光寒兮草短，月色苦兮霜白。傷心慘目，有如是耶？", "吾聞之︰牧用趙卒，大破林胡，開地千里，遁逃匈奴。漢傾天下，財殫力痡。任人而已，其在多乎？周逐獫狁，北至太原。既城朔方，全師而還，飲至策勳，和樂且閑，穆穆棣棣，君臣之間。", "秦起長城，竟海為關，荼毒生靈，萬里朱殷。漢擊匈奴，雖得陰山，枕骸徧野，功不補患。", "蒼蒼蒸民，誰無父母，提攜捧負，畏其不壽？誰無兄弟，如足如手？誰無夫婦，如賓如友？生也何恩，殺之何咎？其存其歿，家莫聞知；人或有言，將信將疑；悁悁心目，寢寐見之。布奠傾觴，哭望天涯，天地為愁，草木淒悲。", "弔祭不至，精魂何依？必有凶年，人其流離！嗚呼噫嘻！時耶？命耶？從古如斯。為之奈何？守在四夷。"], "quote": ["浩浩乎平沙無垠，夐不見人。河水縈帶，羣山糾紛。黯兮慘悴，風悲日曛。蓬斷草枯，凜若霜晨。鳥飛不下，獸鋌亡羣。亭長告余曰︰「此古戰場也，常覆三軍。往往鬼哭，天陰則聞。」", "傷心哉！秦歟？漢歟？將近代歟？吾聞夫齊魏徭戍，荊韓召募；萬里奔走，連年暴露。沙草晨牧，河冰夜渡。地闊天長，不知歸路。寄身鋒刃，腷臆誰愬？", "秦漢而還，多事四夷；中州耗斁，無世無之。古稱戎夏，不抗王師。文教失宣，武臣用奇。奇兵有異於仁義，王道迂闊而莫為！", "嗚呼噫嘻！吾想夫北風振漠，胡兵伺便；主將驕敵，期門受戰。野豎旄旗，川迴組練。法重心駭，威尊命賤。利鏃穿骨，驚沙入面，主客相搏，山川震眩。聲析江河，勢崩雷電。至若窮陰凝閉，凜冽海隅。積雪沒脛，堅冰在鬚。鷙鳥休巢，征馬踟躕。"], "intro": "本篇《舊唐書》本傳原名《祭古戰場文》。坊間選本均易「祭」作「弔」，茲從之。此文故事已見上「作者」欄，是作自自矜才藻之作，並非真為弔古戰場而作的。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%BC%94%E5%8F%A4%E6%88%B0%E5%A0%B4%E6%96%87"}, {"title": "李賀小傳", "author": "李商隱", "period": "唐", "form": "文", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["京兆杜牧為《李長吉集序》，狀長吉之奇甚盡，世傳之。長吉姊嫁王氏者，語長吉之事尤備。", "長吉細瘦，通眉，長指爪。能苦吟，疾書。最先為昌黎韓愈所知。所與游者，王參元、楊敬之、權璩、崔植為密。每旦日出，與諸公游，未嘗得題，然後為詩，如他人思量牽合，以及程限為意。恆從小奚奴，騎距驢，背一古破錦囊；遇有所得，即書投囊中。及暮歸，太夫人使婢受囊，出之，見所書多，輒曰﹕「是兒要當嘔出心始已耳！」上燈與食，長吉從婢取書、研墨、疊紙，足成之，投他囊中。非大醉及弔喪日，率如此；過，亦不復省。王、楊輩時復來探取寫去。長吉往往獨騎往還京雒，所至或時有著，隨棄之，故沈子明家所餘，四卷而已。", "長吉將死時，忽晝見一緋衣人，駕赤虯，持一版書若太古篆，或霹靂石文者，云當召長吉。長吉了不能讀，歘下榻叩頭言︰「阿㜷老且病，賀不願去。」緋衣人笑曰﹕「帝成白玉樓，立召君為記。天上差樂，不苦也。」長吉獨泣，邊人盡見之。少之，長吉氣絕。嘗所居窗中，勃勃有煙氣；聞行車嘒管之聲。太夫人急止人哭，待之；如炊五斗黍許時，長吉竟死。王氏姊非能造作謂長吉者，實所見如此。", "嗚呼！天蒼蒼而高也，上果有帝耶？果有苑囿宮室觀閣之玩耶？苟信然，則天之高邈，帝之尊嚴，亦宜有人物文采愈此世者，何獨眷眷於長吉，而使其不壽耶？噫！又豈世所謂才而奇者，不獨地上少，即天上亦不多耶？長吉生二十四年，位不過奉禮太常，當世人亦多排擯毀斥之；又豈才而奇者，帝獨重之，而人反不重耶？又豈人見會勝帝耶？"], "quote": ["京兆杜牧為《李長吉集序》，狀長吉之奇甚盡，世傳之。長吉姊嫁王氏者，語長吉之事尤備。", "長吉細瘦，通眉，長指爪。能苦吟，疾書。最先為昌黎韓愈所知。所與游者，王參元、楊敬之、權璩、崔植為密。每旦日出，與諸公游，未嘗得題，然後為詩，如他人思量牽合，以及程限為意。恆從小奚奴，騎距驢，背一古破錦囊；遇有所得，即書投囊中。及暮歸，太夫人使婢受囊，出之，見所書多，輒曰﹕「是兒要當嘔出心始已耳！」上燈與食，長吉從婢取書、研墨、疊紙，足成之，投他囊中。非大醉及弔喪日，率如此；過，亦不復省。王、楊輩時復來探取寫去。長吉往往獨騎往還京雒，所至或時有著，隨棄之，故沈子明家所餘，四卷而已。", "長吉將死時，忽晝見一緋衣人，駕赤虯，持一版書若太古篆，或霹靂石文者，云當召長吉。長吉了不能讀，歘下榻叩頭言︰「阿㜷老且病，賀不願去。」緋衣人笑曰﹕「帝成白玉樓，立召君為記。天上差樂，不苦也。」長吉獨泣，邊人盡見之。少之，長吉氣絕。嘗所居窗中，勃勃有煙氣；聞行車嘒管之聲。太夫人急止人哭，待之；如炊五斗黍許時，長吉竟死。王氏姊非能造作謂長吉者，實所見如此。", "嗚呼！天蒼蒼而高也，上果有帝耶？果有苑囿宮室觀閣之玩耶？苟信然，則天之高邈，帝之尊嚴，亦宜有人物文采愈此世者，何獨眷眷於長吉，而使其不壽耶？噫！又豈世所謂才而奇者，不獨地上少，即天上亦不多耶？長吉生二十四年，位不過奉禮太常，當世人亦多排擯毀斥之；又豈才而奇者，帝獨重之，而人反不重耶？又豈人見會勝帝耶？"], "intro": "李賀（公元七九零──八一六），字長吉，唐隴西成紀（今甘肅秦安縣北）人，在昌谷（今河南宜陽縣西）生長。他是一個貴族子弟，乃唐宗室鄭王李元懿之孫。生有夙慧，十餘歲就和當時的名詩人李益齊名，韓愈、皇甫湜都很賞識他。因為父名李晉肅，元稹等倡嫌名之說", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9D%8E%E8%B3%80%E5%B0%8F%E5%82%B3"}, {"title": "夜雨寄北", "author": "李商隱", "period": "唐", "form": "詩", "theme": "山水登臨", "mood": "autumn_sunset", "lines": ["君問歸期未有期，巴山夜雨漲秋池。", "何當共剪西窗燭，卻話巴山夜雨時。"], "quote": ["君問歸期未有期，巴山夜雨漲秋池。", "何當共剪西窗燭，卻話巴山夜雨時。"], "intro": "《夜雨寄北》選自《全唐詩》卷五百三十九。宣宗大中五年（八五一），李商隱抵蜀，入東川節度使幕，不久之後寫成這首詩。《萬首唐人絕句》題作《夜雨寄內》，內即內人，也就是妻子。現存李詩各本則多題作《夜雨寄北》，北即北方的人，相對於在蜀的作者而言。根", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%A4%9C%E9%9B%A8%E5%AF%84%E5%8C%97"}, {"title": "馬嵬", "author": "李商隱", "period": "唐", "form": "詩", "theme": "邊塞豪放", "mood": "autumn_sunset", "lines": ["海外徒聞更九州，他生未卜此生休。", "空聞虎旅傳宵柝，無復雞人報曉籌。", "此日六軍同駐馬，當時七夕笑牽牛。", "如何四紀為天子，不及盧家有莫愁！"], "quote": ["海外徒聞更九州，他生未卜此生休。", "空聞虎旅傳宵柝，無復雞人報曉籌。", "此日六軍同駐馬，當時七夕笑牽牛。", "如何四紀為天子，不及盧家有莫愁！"], "intro": "此詩詠歎發生於天寶十五載（七五六）的「馬嵬事變」。唐玄宗天寶十四載，安祿山以誅奸相楊國忠為名，起兵叛變，潼關失守。唐玄宗携愛妃楊玉環，倉皇逃離京師長安。到長安以西二十餘里的馬嵬坡，六軍不發，禁軍將領要求誅殺楊氏兄妹。唐玄宗無奈下旨賜死最寵愛", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%A6%AC%E5%B5%AC"}, {"title": "常娥", "author": "李商隱", "period": "唐", "form": "詩", "theme": "江河湖海", "mood": "vast_river", "lines": ["雲母屏風燭影深，長河漸落曉星沉。", "常娥應悔偷靈藥，碧海青天夜夜心。"], "quote": ["雲母屏風燭影深，長河漸落曉星沉。", "常娥應悔偷靈藥，碧海青天夜夜心。"], "intro": "《常娥》選自《全唐詩》卷五百四十。常娥，原名恆娥，避文帝諱而改，又稱嫦娥，原是后羿的妻子，因為偷吃了西王母送給她丈夫的不死藥，遂獨自飛奔到月宮，成了寂寞的仙子。李商隱就憑這一傳說，於詩中抒發了一個孤寂的人對周遭的感受。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B8%B8%E5%A8%A5"}, {"title": "無題（相見時難別亦難）", "author": "李商隱", "period": "唐", "form": "詩", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["相見時難別亦難，東風無力百花殘。", "春蠶到死絲方盡，蠟炬成灰淚始乾。", "曉鏡但愁雲鬢改，夜吟應覺月光寒。", "蓬山此去無多路，青鳥殷勤為探看。"], "quote": ["相見時難別亦難，東風無力百花殘。", "春蠶到死絲方盡，蠟炬成灰淚始乾。", "曉鏡但愁雲鬢改，夜吟應覺月光寒。", "蓬山此去無多路，青鳥殷勤為探看。"], "intro": "李商隱的無題詩，在他的集子裏很多，無論古、近體，無論律絕詩都有。因為無題，再加上他的故為隱僻，以致自古沒有一定的解釋。 這是一首盪氣迴腸的哀情詩。「春蠶」一聯，膾炙人口，傳誦千古。 馮浩《集注》說：「首言相晤為難，光陰易過；次言己之愁思，畢", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%84%A1%E9%A1%8C%EF%BC%88%E7%9B%B8%E8%A6%8B%E6%99%82%E9%9B%A3%E5%88%A5%E4%BA%A6%E9%9B%A3%EF%BC%89"}, {"title": "樂遊原", "author": "李商隱", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["向晚意不適，驅車登古原。", "夕陽無限好，只是近黃昏。"], "quote": ["向晚意不適，驅車登古原。", "夕陽無限好，只是近黃昏。"], "intro": "《樂遊原》選自《全唐詩》卷五百三十九。樂遊原，在長安（今陝西西安）之南，高平之地叫做原，此處高下敞豁，是當時有名的遊覽勝地。這首詩抒寫對美好事物即將消逝的惋惜和悵惘。其中「夕陽無限好，只是近黃昏」更是富於哲理的名句。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%A8%82%E9%81%8A%E5%8E%9F"}, {"title": "錦瑟", "author": "李商隱", "period": "唐", "form": "詩", "theme": "田園幽居", "mood": "autumn_sunset", "lines": ["錦瑟無端五十絃，一絃一柱思華年。", "莊生曉夢迷蝴蝶，望帝春心託杜鵑。", "滄海月明珠有淚，藍田日暖玉生煙。", "此情可待成追憶，只是當時已惘然。"], "quote": ["錦瑟無端五十絃，一絃一柱思華年。", "莊生曉夢迷蝴蝶，望帝春心託杜鵑。", "滄海月明珠有淚，藍田日暖玉生煙。", "此情可待成追憶，只是當時已惘然。"], "intro": "李商隱《錦瑟》選自《全唐詩》卷五百三十九。 《錦瑟》主題有多種不同的解釋：一說錦瑟是令狐楚家婢女名；一說此詩是李商隱悼念亡妻王氏之作；也有說此詩是描寫音樂的詠物詩。而以此為作者晚年憶敘生平，自感遭際之辭，較合情理。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%8C%A6%E7%91%9F"}, {"title": "古風（其二）", "author": "李紳", "period": "唐", "form": "詩", "theme": "春水花鳥", "mood": "ethereal", "lines": ["鋤禾日當午，汗滴禾下土。誰知盤中餐，粒粒皆辛苦。"], "quote": ["鋤禾日當午，汗滴禾下土。誰知盤中餐，粒粒皆辛苦。"], "intro": "李紳《古風》選自《全唐詩》卷四百八十三，一作「憫農」。此題共二首，本篇是第二首。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%8F%A4%E9%A2%A8%EF%BC%88%E5%85%B6%E4%BA%8C%EF%BC%89"}, {"title": "古從軍行", "author": "李頎", "period": "唐", "form": "詩", "theme": "邊塞豪放", "mood": "snow_winter", "lines": ["白日登山望烽火，黃昏飲馬傍交河。", "行人刁斗風沙暗，公主琵琶幽怨多。", "野營萬里無城郭，雨雪紛紛連大漠。", "胡雁哀鳴夜夜飛，胡兒眼淚雙雙落。", "聞道玉門猶被遮，應將性命逐輕車。", "年年戰骨埋荒外，空見蒲萄入漢家。"], "quote": ["白日登山望烽火，黃昏飲馬傍交河。", "行人刁斗風沙暗，公主琵琶幽怨多。", "野營萬里無城郭，雨雪紛紛連大漠。", "胡雁哀鳴夜夜飛，胡兒眼淚雙雙落。"], "intro": "《從軍行》本是樂府古題。此詩作於天寶（唐玄宗年號，742-756）初年，借漢皇開邊，諷刺唐玄宗窮兵黷武開邊之策。戰士軍旅生涯艱苦，萬千將士埋骨荒野，只換來西域特產的葡萄，得不償失。由於寫當代國事，怕觸犯忌諱，所以在題目上加一個「古」字。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%8F%A4%E5%BE%9E%E8%BB%8D%E8%A1%8C"}, {"title": "虬髯客傳", "author": "杜光庭", "period": "唐", "form": "小說", "theme": "送別行旅", "mood": "autumn_sunset", "lines": ["隋煬帝之幸江都也，命司空楊素守西京。素驕貴，又以時亂，天下之權重望崇者，莫我若也，奢貴自奉，禮異人臣。每公卿入言，賓客上謁，未嘗不踞牀而見，令美人捧出。侍婢羅列，頗僭於上。末年愈甚，無復知所負荷，有扶危持顛之心。", "一日，衞公李靖以布衣上謁，獻奇策。素亦踞見。公前揖曰︰「天下方亂，英雄競起。公為帝室重臣，須以收羅豪傑為心，不宜踞見賓客。」素斂容而起，謝公，與語，大悅，收其策而退。", "當公之騁辯也，一妓有殊色，執紅拂，立於前，獨目公。公既去，而執拂者臨軒指吏曰︰「問去者︰處士第幾？住何處？」公具以對。妓誦而去。", "公歸逆旅。其夜五更初，忽聞叩門而聲低者，公起問焉。乃紫衣戴帽人，杖揭一囊。公問︰「誰？」曰︰「妾，楊家之紅拂妓也。」公遽延入。脫衣去帽，乃十八九佳麗人也，素面畫衣而拜。公驚，答拜。曰︰「妾侍楊司空久，閱天下之人多矣，無如公者。絲蘿非獨生，願託喬木，故來奔耳。」公曰︰「楊司空權重京師，如何？」曰︰「彼屍居餘氣，不足畏也。諸妓知其無成，去者眾矣，彼亦不甚逐也。計之詳矣。幸無疑焉。」問其姓。曰︰「張。」問伯仲之次。曰︰「最長。」觀其肌膚、儀狀、言詞、氣性，真天人也。公不自意獲之，愈喜愈懼，瞬息萬慮不安。而窺戶者無停屨。數日，亦聞追討之聲，意亦非峻。乃雄服乘馬，排闥而去，將歸太原。", "行次靈石旅舍，既設牀，爐中烹肉且熟。張氏以髮長委地，立梳牀前，公方刷馬。忽有一人，中形，赤髯而虬，乘蹇驢而來。投革囊於爐前，取枕欹臥。看張梳頭。公怒甚，未決，猶刷馬。張熟視其面，一手握髮，一手映身搖示公，令勿怒。急急梳頭畢，斂袵前問其姓。臥客答曰︰「姓張。」對曰︰「妾亦姓張，合是妹。」遽拜之。問︰「第幾？」曰︰「第三。」因問︰「妹第幾？」曰︰「最長。」遂喜曰︰「今多幸逢一妹。」張氏遙呼︰「李郎，且來見三兄！」公驟拜之。遂環坐。曰︰「煮者何肉？」曰︰「羊肉，計已熟矣。」客曰︰「飢。」公出市胡餅。客抽腰間匕首，切肉共食。食竟，餘肉亂切送驢前食之，甚速。客曰︰「觀李郎之行，貧士也。何以致斯異人？」曰︰「靖雖貧，亦有心者焉。他人見問，故不言。兄之問，則不隱耳。」具言其由。曰︰「然則將何之？」曰︰「將避地太原。」曰︰「然吾故非君所致也。」曰︰「有酒乎?」曰︰「主人西，則酒肆也。」公取酒一斗，既巡，客曰︰「吾有少下酒物，李郎能同之乎？」曰︰「不敢。」於是開革囊，取一人頭並心肝。卻頭囊中，以匕首切心肝，共食之。曰︰「此人天下負心者，銜之十年，今始獲之，吾憾釋矣。」又曰︰「觀李郎儀形器宇，真丈夫也。亦聞太原有異人乎？」曰︰「嘗識一人，愚謂之真人也。其餘，將帥而已。」曰︰「何姓？」曰︰「靖之同姓。」曰︰「年幾？」曰︰「僅二十。」曰︰「今何為？」曰︰「州將之子。」曰︰「似矣。亦須見之。李郎能致吾一見乎？」曰︰「靖之友劉文靜與之狎。因文靜見之可也。然兄何為？」曰︰「望氣者言太原有奇氣，使訪之。李郎明發，何日到太原？」靖計之日。曰︰「達之明日月方曙，候我於汾陽橋。」言訖，乘驢而去，其行若飛，迴顧已失。公與張氏且驚且喜，久之，曰︰「烈士不欺人，固無畏。」促鞭而行。", "及期，入太原。果復相見。大喜，偕詣劉氏。詐謂文靜曰︰「以善相者思見郎君，請迎之。」文靜素奇其人，一旦聞有客善相，遽致使迎之。使迴而至，不衫不履，裼裘而來，神氣揚揚，貌與常異。虬髯默居末坐，見之心死，飲數杯，招靖曰︰「真天子也！」公以告劉，劉益喜，自負。既出，而虬髯曰︰「吾得十八九矣。然須道兄見。李郎宜與一妹復入京，某日午時，訪我於馬行東酒樓下。下有此驢及瘦驢，即我與道兄俱在其上矣。到即登焉。」又別而去，公與張氏復應之。", "及期訪焉，宛見二乘。攬衣登樓，虬髯與一道士方對飲，見公驚喜，召坐。圍飲十數巡。曰︰「樓下櫃中有錢十萬，擇一深隱處駐一妹。某日，復會我於汾陽橋。」如期至，則道士與虬髯已到矣。俱謁文靜。時方弈棋，揖而話心焉。文靜飛書迎文皇看棋。道士對弈，虬髯與公旁侍焉。俄而文皇到來，精采驚人，長揖而坐；神氣清朗，滿坐風生，顧盼煒如也。道士一見慘然，下棋子曰︰「此局全輸矣！於此失卻局哉！救無路矣！復奚言！」罷奕而請去。既出，謂虬髯曰︰「此世界非公世界；他方可也。勉之，勿以為念！」因共入京。虬髯曰︰「計李郎之程，某日方到。到之明日，可與一妹同詣某坊曲小宅相訪。李郎相從一妹，懸然如磬，欲令新婦祇謁，兼議從容，無前卻也。」言畢，吁嗟而去。", "公策馬而歸。即到京，遂與張氏同往。乃一小版戶，叩之，有應者，拜曰︰「三郎令候李郎一娘子久矣。」延入重門，門愈壯。婢四十人，羅列庭前。奴二十人，引公入東廳。廳之陳設，窮極珍異，箱中妝奩冠鏡首飾之盛，非人間之物。巾櫛妝飾畢，請更衣，衣又珍異。既畢，傳云︰「三郎來！」乃虬髯紗帽裼裘而來，亦有龍虎之狀，歡然相見。催其妻出拜，蓋亦天人耳。遂延中堂，陳設盤筵之盛，雖王公家不侔也。四人對饌訖，陳女樂二十人，列奏於前，似從天降，非人間之曲。食畢，行酒。家人自東堂舁出二十牀，各以錦繡帕覆之。既陳，盡去其帕，乃文簿鑰匙耳。虬髯曰︰「此盡寶貨泉貝之數。吾之所有，悉以充贈。何者？欲於此世界求事，當龍戰三二十載，建少功業。今既有主，住亦何為？太原李氏，真英主也。三五年內，即當太平。李郎以奇特之才，輔清平之主，竭心盡善，必極人臣。一妹以天人之姿，蘊不世之藝，從夫之貴，以盛軒裳。非一妹不能識李郎，非李郎不能榮一妹。起陸之貴，際會如期。虎嘯風生，龍吟雲萃，固非偶然也。持余之贈，以佐真主，贊功業也；勉之哉！此後十年，當東南數千里外有異事，是吾得事之秋也。一妹與李郎可瀝酒東南相賀。」因命家童列拜，曰︰「李郎、一妹，是汝主也。」言訖，與其妻從一奴，乘馬而去。數步，遂不復見。公據其宅，乃為豪家，得以助文皇締構之賢，遂匡天下。", "貞觀十年，公以左僕射平章事，適南蠻入奏曰︰「有海船千艘，甲兵十萬，入扶餘國，殺其主自立。國已定矣。」公心知虬髯得事也，歸告張氏，具衣拜賀，瀝酒東南祝拜之。乃知真人之興也，非英雄所冀。況非英雄乎？人臣之謬思亂者，乃螳臂之拒走輪耳。我皇家垂福萬葉，豈虛然哉！或曰︰「衞公之兵法，半乃是虬髯所傳耳。」"], "quote": ["隋煬帝之幸江都也，命司空楊素守西京。素驕貴，又以時亂，天下之權重望崇者，莫我若也，奢貴自奉，禮異人臣。每公卿入言，賓客上謁，未嘗不踞牀而見，令美人捧出。侍婢羅列，頗僭於上。末年愈甚，無復知所負荷，有扶危持顛之心。", "一日，衞公李靖以布衣上謁，獻奇策。素亦踞見。公前揖曰︰「天下方亂，英雄競起。公為帝室重臣，須以收羅豪傑為心，不宜踞見賓客。」素斂容而起，謝公，與語，大悅，收其策而退。", "當公之騁辯也，一妓有殊色，執紅拂，立於前，獨目公。公既去，而執拂者臨軒指吏曰︰「問去者︰處士第幾？住何處？」公具以對。妓誦而去。", "公歸逆旅。其夜五更初，忽聞叩門而聲低者，公起問焉。乃紫衣戴帽人，杖揭一囊。公問︰「誰？」曰︰「妾，楊家之紅拂妓也。」公遽延入。脫衣去帽，乃十八九佳麗人也，素面畫衣而拜。公驚，答拜。曰︰「妾侍楊司空久，閱天下之人多矣，無如公者。絲蘿非獨生，願託喬木，故來奔耳。」公曰︰「楊司空權重京師，如何？」曰︰「彼屍居餘氣，不足畏也。諸妓知其無成，去者眾矣，彼亦不甚逐也。計之詳矣。幸無疑焉。」問其姓。曰︰「張。」問伯仲之次。曰︰「最長。」觀其肌膚、儀狀、言詞、氣性，真天人也。公不自意獲之，愈喜愈懼，瞬息萬慮不安。而窺戶者無停屨。數日，亦聞追討之聲，意亦非峻。乃雄服乘馬，排闥而去，將歸太原。"], "intro": "《虬髯客傳》不在杜集中。《宋史藝文志》小說類著錄《虬髯客傳一卷》。宋程大昌《攷古篇》﹙九﹚作《虬鬚傳》。《說郛》及《唐人說薈》以為乃張說撰，非。此傳影響藝壇甚廣，後來衍為戲劇，明張鳳翼張太和皆有《紅拂記》，凌初成有《虬髯翁》，馮夢龍有《女丈", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%99%AC%E9%AB%AF%E5%AE%A2%E5%82%B3"}, {"title": "月夜（今夜鄜州月）", "author": "杜甫", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["今夜鄜州月，閨中只獨看。遙憐小兒女，未解憶長安。", "香霧雲鬟溼，清輝玉臂寒。何時倚虛幌，雙照淚痕乾。"], "quote": ["今夜鄜州月，閨中只獨看。遙憐小兒女，未解憶長安。", "香霧雲鬟溼，清輝玉臂寒。何時倚虛幌，雙照淚痕乾。"], "intro": "《月夜》一詩選自《全唐詩》卷二百二十四，作於唐肅宗至德元年（七五六）八月，作者當時在長安。是年六月，安史叛軍攻佔潼關，杜甫攜眷逃難鄜州（今陝西富縣）。七月，肅宗即位靈武（今靈夏回族自治區靈武），杜甫隻身從鄜州奔赴靈武，途中為叛軍所俘，押回長", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9C%88%E5%A4%9C%EF%BC%88%E4%BB%8A%E5%A4%9C%E9%84%9C%E5%B7%9E%E6%9C%88%EF%BC%89"}, {"title": "曲江二首", "author": "杜甫", "period": "唐", "form": "詩", "theme": "江河湖海", "mood": "snow_winter", "lines": ["其一", "一片花飛減卻春，風飄萬點正愁人。", "且看欲盡花經眼，莫厭傷多酒入唇。", "江上小堂巢翡翠，苑邊高塚臥麒麟。", "細推物理須行樂，何用浮名絆此身！", "其二", "朝回日日典春衣，每日江頭盡醉歸。", "酒債尋常行處有，人生七十古來稀。", "穿花蛺蝶深深見，點水蜻蜓款款飛。", "傳語風光共流轉，暫時相賞莫相違。"], "quote": ["其一", "一片花飛減卻春，風飄萬點正愁人。", "且看欲盡花經眼，莫厭傷多酒入唇。", "江上小堂巢翡翠，苑邊高塚臥麒麟。"], "intro": "這兩首詩寫於唐肅宗乾元元年（758）春，在前一年的九月和十月，唐軍連續打敗安史叛軍，相繼收復了長安和洛陽，全國一片歡呼。唐肅宗也回到了長安，許多官僚貴族都像經過一場冬眠的蟲子一樣重又復甦，重又過起紙醉金迷的享樂生活。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9B%B2%E6%B1%9F%E4%BA%8C%E9%A6%96"}, {"title": "江南逢李龜年", "author": "杜甫", "period": "唐", "form": "詩", "theme": "江河湖海", "mood": "vast_river", "lines": ["岐王宅裏尋常見，崔九堂前幾度聞。", "正是江南好風景，落花時節又逢君。"], "quote": ["岐王宅裏尋常見，崔九堂前幾度聞。", "正是江南好風景，落花時節又逢君。"], "intro": "《江南逢李龜年》選自《全唐詩》卷二百三十二，於唐代宗大曆五年（七七○）所作。李龜年是位著名樂師，與杜甫有舊交。安史之亂後，杜甫流落江南，在潭州（今湖南長沙市）與李龜年重逢。戰亂之中在異鄉偶遇故人，分外高興，遂賦詩述懷。詩的前二句，回憶當年太", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B1%9F%E5%8D%97%E9%80%A2%E6%9D%8E%E9%BE%9C%E5%B9%B4"}, {"title": "兵車行", "author": "杜甫", "period": "唐", "form": "詩", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["車轔轔，馬蕭蕭；行人弓箭各在腰。", "耶孃妻子走相送，塵埃不見咸陽橋。", "牽衣頓足攔道哭，哭聲直上干雲霄。", "道旁過者問行人，行人但云點行頻。", "或從十五北防河，便至四十西營田。", "去時里正與裹頭，歸來頭白還戍邊。", "邊庭流血成海水，武皇開邊意未已。", "君不聞漢家山東二百州，千村萬落生荊杞。", "縱有健婦把鋤犁，禾生隴畝無東西。", "況復秦兵耐苦戰，被驅不異犬與雞。", "長者雖有問，役夫敢申恨？", "且如今年冬，未休關西卒。"], "quote": ["車轔轔，馬蕭蕭；行人弓箭各在腰。", "耶孃妻子走相送，塵埃不見咸陽橋。", "牽衣頓足攔道哭，哭聲直上干雲霄。", "道旁過者問行人，行人但云點行頻。"], "intro": "唐代天寶年間，朝廷對西北、西南外族的戰爭越來越頻繁。連年戰事不單使朝廷負擔沉重，也使廣大人民受苦。杜甫看到連年開邊的禍害，在詩中反映當時民間疾苦。 對此詩的歷史背景，歷代注家有兩種觀點。一種認為是因哥舒翰用兵吐蕃而作，另一種認為是因楊國忠令", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%85%B5%E8%BB%8A%E8%A1%8C"}, {"title": "茅屋為秋風所破歌", "author": "杜甫", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["八月秋高風怒號，卷我屋上三重茅。", "茅飛渡江灑江郊︰高者掛罥長林梢，下者飄轉沉塘坳。", "南村羣童欺我老無力，忍能對面為盜賊。", "公然抱茅入竹去，脣焦口燥呼不得，歸來倚仗自歎息！", "俄頃風定雲墨色，秋天漠漠向昏黑。", "布衾多年冷似鐵，嬌兒惡臥踏裏裂。", "牀頭屋漏無乾處，雨腳如麻未斷絕。", "自經喪亂少睡眠，長夜沾濕何由徹﹖", "安得廣廈千萬間，大庇天下寒士俱歡顏，風雨不動安如山！", "嗚呼！何時眼前突兀見此屋﹖吾廬獨破受凍死亦足！"], "quote": ["八月秋高風怒號，卷我屋上三重茅。", "茅飛渡江灑江郊︰高者掛罥長林梢，下者飄轉沉塘坳。", "南村羣童欺我老無力，忍能對面為盜賊。", "公然抱茅入竹去，脣焦口燥呼不得，歸來倚仗自歎息！"], "intro": "此詩作於唐肅宗上元二年（公元七六一）八月，那時杜甫已經五十歲，剛來到四川成都不久 住在一座破敝的茅屋裏。秋高風急，竟把茅屋屋頂給颳去了，可見詩人老年的窮困。後來多虧友人資助，纔在成都城西浣花溪畔，建了一所草堂居住。這首詩就是寫他住的茅屋被風", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%8C%85%E5%B1%8B%E7%82%BA%E7%A7%8B%E9%A2%A8%E6%89%80%E7%A0%B4%E6%AD%8C"}, {"title": "客至", "author": "杜甫", "period": "唐", "form": "詩", "theme": "送別行旅", "mood": "vast_river", "lines": ["舍南舍北皆春水，但見群鷗日日來。", "花徑不曾緣客掃，蓬門今始為君開。", "盤飧市遠無兼味，樽酒家貧只舊醅。", "肯與鄰翁相對飲，隔籬呼取盡餘杯。"], "quote": ["舍南舍北皆春水，但見群鷗日日來。", "花徑不曾緣客掃，蓬門今始為君開。", "盤飧市遠無兼味，樽酒家貧只舊醅。", "肯與鄰翁相對飲，隔籬呼取盡餘杯。"], "intro": "這首詩作於唐肅宗上元二年（公元761），當時杜甫居住在成都草堂，除了幾個知己，他很少與人交往。一日，親友崔明府來訪。明府，在唐代是對縣令的尊稱。杜甫的母親姓崔，一說崔明府是他母家的親戚，一說是他的舅氏崔頊。無論如何，有客來訪，詩人都感到喜出", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%AE%A2%E8%87%B3"}, {"title": "春望", "author": "杜甫", "period": "唐", "form": "詩", "theme": "春水花鳥", "mood": "autumn_sunset", "lines": ["國破山河在，城春草木深。感時花濺淚，恨別鳥驚心。", "烽火連三月，家書抵萬金。白頭搔更短，渾欲不勝簪。"], "quote": ["國破山河在，城春草木深。感時花濺淚，恨別鳥驚心。", "烽火連三月，家書抵萬金。白頭搔更短，渾欲不勝簪。"], "intro": "《春望》選自《全唐詩》卷二百二十四，為作者於唐肅宗至德二年（七五七）三月，身陷長安時作。其時雖為暮春三月，一片花繁葉茂，然長安卻被安史叛軍焚掠一空。滿目荒涼，作者觸景傷情，寫下了這首憂時傷亂的名篇。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%98%A5%E6%9C%9B"}, {"title": "旅夜書懷", "author": "杜甫", "period": "唐", "form": "詩", "theme": "江河湖海", "mood": "vast_river", "lines": ["細草微風岸，危檣獨夜舟。星垂平野闊，月湧大江流。", "名豈文章著，官因老病休。飄飄何所似？天地一沙鷗。"], "quote": ["細草微風岸，危檣獨夜舟。星垂平野闊，月湧大江流。", "名豈文章著，官因老病休。飄飄何所似？天地一沙鷗。"], "intro": "杜甫《旅夜書懷》選自《全唐詩》卷二百二十六。 《旅夜書懷》作於唐代宗永泰元年（七六五）。此年劍南節度使嚴武去世，杜甫在蜀無所依靠，便於五月攜眷離開成都，乘船東下，途經渝州（今四川重慶）、忠州（今四州忠縣），九月到達雲安（今四川雲陽）。此詩即", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%97%85%E5%A4%9C%E6%9B%B8%E6%87%B7"}, {"title": "望嶽", "author": "杜甫", "period": "唐", "form": "詩", "theme": "山水登臨", "mood": "majestic_peaks", "lines": ["岱宗夫如何？齊魯青未了。", "造化鍾神秀，陰陽割昏曉。", "盪胸生層雲，決眥入歸鳥。", "會當凌絕頂，一覽眾山小。"], "quote": ["岱宗夫如何？齊魯青未了。", "造化鍾神秀，陰陽割昏曉。", "盪胸生層雲，決眥入歸鳥。", "會當凌絕頂，一覽眾山小。"], "intro": "杜集中有三首《望嶽》詩，分詠東嶽、南嶽、西嶽。這首詩是寫東嶽泰山的，寫於唐玄宗開元年間杜甫第一次漫遊齊趙時，是現存杜詩中年代最早的一首五言詩。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9C%9B%E5%B6%BD"}, {"title": "登岳陽樓", "author": "杜甫", "period": "唐", "form": "詩", "theme": "山水登臨", "mood": "snow_winter", "lines": ["昔聞洞庭水，今上岳陽樓。", "吳楚東南坼，乾坤日夜浮。", "親朋無一字，老病有孤舟。", "戎馬關山北，憑軒涕泗流。"], "quote": ["昔聞洞庭水，今上岳陽樓。", "吳楚東南坼，乾坤日夜浮。", "親朋無一字，老病有孤舟。", "戎馬關山北，憑軒涕泗流。"], "intro": "《登岳陽樓》選自《全唐詩》卷二百三十三，是杜甫在唐代宗大曆三年（七六八）冬十二月，自湖北至岳州（今湖南岳陽）時作。岳陽樓原是岳陽城西門的門樓，前臨洞庭湖。這首詩寫詩人登臨岳陽樓時所見景象及一時感觸。作者面對氣象萬千、無邊空闊的洞庭湖，勾起憂", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%99%BB%E5%B2%B3%E9%99%BD%E6%A8%93"}, {"title": "登高", "author": "杜甫", "period": "唐", "form": "詩", "theme": "山水登臨", "mood": "snow_winter", "lines": ["風急天高猿嘯哀，渚清沙白鳥飛迴。", "無邊落木蕭蕭下，不盡長江衮衮來。", "萬里悲秋常作客，百年多病獨登臺。", "艱難苦恨繁霜鬢，潦倒新停濁酒杯。"], "quote": ["風急天高猿嘯哀，渚清沙白鳥飛迴。", "無邊落木蕭蕭下，不盡長江衮衮來。", "萬里悲秋常作客，百年多病獨登臺。", "艱難苦恨繁霜鬢，潦倒新停濁酒杯。"], "intro": "杜甫《登高》選自《全唐詩》卷二百二十七。 《登高》是唐代宗大曆二年（七六七），杜甫流寓夔州（今四川奉節），重九時扶病登高之作。明胡應麟《詩藪》稱此詩精光萬丈，為古代七言律詩之冠，是「曠代之作」，並非溢美之詞。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%99%BB%E9%AB%98"}, {"title": "登樓", "author": "杜甫", "period": "唐", "form": "詩", "theme": "山水登臨", "mood": "autumn_sunset", "lines": ["花近高樓傷客心，萬方多難此登臨。", "錦江春色來天地，玉壘浮雲變古今。", "北極朝廷終不改，西山寇盜莫相侵。", "可憐後主還祠廟，日暮聊為梁甫吟。"], "quote": ["花近高樓傷客心，萬方多難此登臨。", "錦江春色來天地，玉壘浮雲變古今。", "北極朝廷終不改，西山寇盜莫相侵。", "可憐後主還祠廟，日暮聊為梁甫吟。"], "intro": "公元763年正月，官軍收復河南河北，安史之亂平定；九月，吐蕃軍隊東侵，涇州刺史高暉投降吐蕃，引吐蕃人攻佔長安，代宗逃奔陝州。吐蕃重立新帝、改年號。幸得郭子儀將吐蕃趕出長安，收復京師，代宗復位。年底，吐蕃又向四川進攻，佔領了松州、維州等地。這", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%99%BB%E6%A8%93"}, {"title": "絕句", "author": "杜甫", "period": "唐", "form": "詩", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["兩個黃鸝鳴翠柳，", "一行白鷺上青天。", "窗含西嶺千秋雪，", "門泊東吳萬里船。"], "quote": ["兩個黃鸝鳴翠柳，", "一行白鷺上青天。", "窗含西嶺千秋雪，", "門泊東吳萬里船。"], "intro": "這首詩寫於唐代宗廣德二年（公元764）春天。杜甫在安史之亂時流落成都，為棲身而在浣花溪畔搭建草堂居住。他在那裏居住的期間，創作了超過二百首詩歌。其中一些是充滿生活情趣的小詩；本詩是一組四首題為《絕句》的七言絕詩的第三首。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%B5%95%E5%8F%A5"}, {"title": "飲中八仙歌", "author": "杜甫", "period": "唐", "form": "詩", "theme": "春水花鳥", "mood": "vast_river", "lines": ["知章騎馬如乘船，眼花落井水底眠。", "汝陽三斗始朝天，道逢麹車口流涎，恨不移封向酒泉。", "左相日興費萬錢，飲如長鯨吸百川，銜杯樂聖稱避賢。", "宗之瀟灑美少年，舉觴白眼望青天，皎如玉樹臨風前。", "蘇晉長齋繡佛前，醉中往往愛逃禪。", "李白一斗詩百篇，長安市上酒家眠，天子呼來不上船，自稱臣是酒中仙。", "張旭三杯草聖傳，脫帽露頂王公前，揮毫落紙如雲煙。", "焦遂五斗方卓然，高談雄辨驚四筵。"], "quote": ["知章騎馬如乘船，眼花落井水底眠。", "汝陽三斗始朝天，道逢麹車口流涎，恨不移封向酒泉。", "左相日興費萬錢，飲如長鯨吸百川，銜杯樂聖稱避賢。", "宗之瀟灑美少年，舉觴白眼望青天，皎如玉樹臨風前。"], "intro": "《新唐書・李白傳》記載，李白與賀知章、李適之、李璡、崔宗之、蘇晉、張旭、焦遂八人俱善飲，稱為「酒中八仙人」。杜甫這首《飲中八仙歌》是根據這一說法，以詩歌描繪這八人。 詩中提及李適之罷相後的生活。據《新唐書・李適之傳》，李適之罷相是在天寶五載", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%A3%B2%E4%B8%AD%E5%85%AB%E4%BB%99%E6%AD%8C"}, {"title": "蜀相", "author": "杜甫", "period": "唐", "form": "詩", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["丞相祠堂何處尋？錦官城外柏森森。", "映階碧草自春色，隔葉黃鸝空好音。", "三顧頻煩天下計，兩朝開濟老臣心。", "出師未捷身先死，長使英雄淚滿襟！"], "quote": ["丞相祠堂何處尋？錦官城外柏森森。", "映階碧草自春色，隔葉黃鸝空好音。", "三顧頻煩天下計，兩朝開濟老臣心。", "出師未捷身先死，長使英雄淚滿襟！"], "intro": "杜甫晚年寄寓成都，在昔日蜀漢故地上流連了好些日子。諸葛亮在四川一帶艱苦經營二十多年，取得不錯的成績，深得當地人的景仰。杜甫在成都時看到不少蜀漢遺迹，寫下不少歌頌諸葛亮的詩歌，其中著名的有《蜀相》、《八陣圖》和《詠懷古跡之五》。 《蜀相》寫於", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%9C%80%E7%9B%B8"}, {"title": "聞官軍收河南河北", "author": "杜甫", "period": "唐", "form": "詩", "theme": "江河湖海", "mood": "vast_river", "lines": ["劍外忽傳收薊北，初聞涕淚滿衣裳。", "卻看妻子愁何在，漫卷詩書喜欲狂。", "白日放歌須縱酒，青春作伴好還鄉。", "即從巴峽穿巫峽，便下襄陽向洛陽。"], "quote": ["劍外忽傳收薊北，初聞涕淚滿衣裳。", "卻看妻子愁何在，漫卷詩書喜欲狂。", "白日放歌須縱酒，青春作伴好還鄉。", "即從巴峽穿巫峽，便下襄陽向洛陽。"], "intro": "《聞官軍收河南河北》選自《全唐詩》卷二百二十七，一作「收兩河」。河南，黃河以南洛陽一帶。河北，黃河以北，今河北北部一帶。本詩寫於唐代宗廣德元年（七六三），時杜甫在梓州（今四川三台）。肅宗寶應元年（七六二）十月，唐大軍屢破史朝義叛軍，次年正月", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%81%9E%E5%AE%98%E8%BB%8D%E6%94%B6%E6%B2%B3%E5%8D%97%E6%B2%B3%E5%8C%97"}, {"title": "九日齊山登高", "author": "杜牧", "period": "唐", "form": "詩", "theme": "山水登臨", "mood": "autumn_sunset", "lines": ["江涵秋影雁初飛，與客攜壺上翠微。", "塵世難逢開口笑，菊花須插滿頭歸。", "但將酩酊酬佳節，不用登臨恨落暉。", "古往今來只如此，牛山何必獨霑衣！"], "quote": ["江涵秋影雁初飛，與客攜壺上翠微。", "塵世難逢開口笑，菊花須插滿頭歸。", "但將酩酊酬佳節，不用登臨恨落暉。", "古往今來只如此，牛山何必獨霑衣！"], "intro": "這首詩是唐武宗會昌五年（公元845年）杜牧任池州刺史時的作品。杜牧的友人張祜到池州拜訪他，並在重陽佳節同登齊山。他們二人都懷才不遇，同病相憐，在登山時引起感慨，寫成此詩。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B9%9D%E6%97%A5%E9%BD%8A%E5%B1%B1%E7%99%BB%E9%AB%98"}, {"title": "山行", "author": "杜牧", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["遠上寒山石徑斜，白雲生處有人家。", "停車坐愛楓林晚，霜葉紅於二月花。"], "quote": ["遠上寒山石徑斜，白雲生處有人家。", "停車坐愛楓林晚，霜葉紅於二月花。"], "intro": "《山行》選自《全唐詩》卷五百二十四。這是一首寫山行小景的詩，山居環境的幽僻，鮮紅楓葉的美麗，以清淡的筆墨寫來，鮮明如畫。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B1%B1%E8%A1%8C"}, {"title": "江南春", "author": "杜牧", "period": "唐", "form": "詩", "theme": "春水花鳥", "mood": "vast_river", "lines": ["千里鶯啼綠映紅，水村山郭酒旗風。", "南朝四百八十寺，多少樓臺煙雨中？"], "quote": ["千里鶯啼綠映紅，水村山郭酒旗風。", "南朝四百八十寺，多少樓臺煙雨中？"], "intro": "", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B1%9F%E5%8D%97%E6%98%A5"}, {"title": "赤壁", "author": "杜牧", "period": "唐", "form": "詩", "theme": "詠史哲思", "mood": "vast_river", "lines": ["折戟沉沙鐵未銷，自將磨洗認前朝。", "東風不與周郎便，銅雀春深鎖二喬。"], "quote": ["折戟沉沙鐵未銷，自將磨洗認前朝。", "東風不與周郎便，銅雀春深鎖二喬。"], "intro": "《赤壁》一詩是杜牧官黃州刺史時（八四二──八四四）所作。赤壁，即赤壁山，在今湖北省蒲圻縣西北長江南岸，北臨大江，對岸即烏林，漢末周瑜破曹操處。黃州城外有赤鼻磯，並非三國時孫、曹大戰的赤壁，詩人不過藉以抒發自己的感慨而已。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B5%A4%E5%A3%81"}, {"title": "阿房宮賦", "author": "杜牧", "period": "唐", "form": "辭賦", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["六王畢，四海一；蜀山兀，阿房出。覆壓三百餘里，隔離天日。驪山北構而西折，直走咸陽。二川溶溶，流入宮牆。五步一樓，十步一閣；廊腰縵迴，簷牙高啄；各抱地勢，鈎心鬭角。盤盤焉，囷囷焉，蜂房水渦，矗不知乎幾千萬落。", "長橋臥波，未雲何龍？複道行空，不霽何虹？高低冥迷，不知西東。歌臺暖響，春光融融；舞殿冷袖，風雨淒淒。一日之內，一宮之間，而氣候不齊。", "妃嬪媵嬙，王子皇孫，辭樓下殿，輦來於秦，朝歌夜絃，為秦宮人。明星熒熒，開粧鏡也；綠雲擾擾，梳曉鬟也；渭流漲膩，棄脂水也；烟斜霧橫，焚椒蘭也。雷霆乍驚，宮車過也；轆轆遠聽，杳不知其所之也。", "一肌一容，盡態極妍；縵立遠視，而望幸焉。有不得見者，三十六年。", "燕趙之收藏，韓魏之經營，齊楚之精英，幾世幾年，剽掠其人，倚疊如山；一旦不能有，輸來其間。鼎鐺玉石，金塊珠礫，棄擲邐迤；秦人視之，亦不甚惜。", "嗟乎！一人之心，千萬人之心也。秦愛紛奢，人亦念其家；柰何取之盡錙銖，用之如泥沙？使負棟之柱，多於南畝之農夫；架梁之椽，多於機上之工女；釘頭磷磷，多於在庾之粟粒；瓦縫參差，多於周身之帛縷；", "直欄橫檻，多於九土之城郭；管絃嘔啞，多於市人之言語。使天下之人，不敢言而敢怒；獨夫之心，日益驕固。戍卒叫，函谷舉；楚人一炬，可憐焦土。", "嗚呼！滅六國者，六國也，非秦也。族秦者，秦也，非天下也。嗟乎！使六國各愛其人，則足以拒秦。秦復愛六國之人，則遞三世，可至萬世而為君，誰得而族滅也？秦人不暇自哀，而後人哀之；後人哀之而不鑑之，亦使後人而復哀後人也。"], "quote": ["六王畢，四海一；蜀山兀，阿房出。覆壓三百餘里，隔離天日。驪山北構而西折，直走咸陽。二川溶溶，流入宮牆。五步一樓，十步一閣；廊腰縵迴，簷牙高啄；各抱地勢，鈎心鬭角。盤盤焉，囷囷焉，蜂房水渦，矗不知乎幾千萬落。", "長橋臥波，未雲何龍？複道行空，不霽何虹？高低冥迷，不知西東。歌臺暖響，春光融融；舞殿冷袖，風雨淒淒。一日之內，一宮之間，而氣候不齊。", "妃嬪媵嬙，王子皇孫，辭樓下殿，輦來於秦，朝歌夜絃，為秦宮人。明星熒熒，開粧鏡也；綠雲擾擾，梳曉鬟也；渭流漲膩，棄脂水也；烟斜霧橫，焚椒蘭也。雷霆乍驚，宮車過也；轆轆遠聽，杳不知其所之也。", "一肌一容，盡態極妍；縵立遠視，而望幸焉。有不得見者，三十六年。"], "intro": "《阿房宮賦》選自《樊川文集》卷一，約作於唐敬宗寶曆元年（八二五）。 阿房宮是我國古代一座著名宮殿，故址在今陝西西安西北。阿，指屋四周的曲簷，一說大陵曰「阿」，而此宮則建於大陵之旁。始建於秦始皇三十五年（西元前二一二），至秦亡時（西元前二〇六", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%98%BF%E6%88%BF%E5%AE%AE%E8%B3%A6"}, {"title": "泊秦淮", "author": "杜牧", "period": "唐", "form": "詩", "theme": "江河湖海", "mood": "snow_winter", "lines": ["煙籠寒水月籠沙，夜泊秦淮近酒家。", "商女不知亡國恨，隔江猶唱後庭花。"], "quote": ["煙籠寒水月籠沙，夜泊秦淮近酒家。", "商女不知亡國恨，隔江猶唱後庭花。"], "intro": "《泊秦淮》選自《全唐詩》卷五百二十三。泊，船隻停泊。秦淮，河名，穿金陵城（今江蘇南京）而入長江。這是一首即景抒懷詩，作者在詩中除了描寫秦淮河的夜色外，又藉着商女的歌聲慨歎沉淪的國運。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B3%8A%E7%A7%A6%E6%B7%AE"}, {"title": "秋夕", "author": "杜牧", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["紅燭秋光冷畫屏，輕羅小扇撲流螢。", "天階夜色涼如水，坐看牽牛織女星。"], "quote": ["紅燭秋光冷畫屏，輕羅小扇撲流螢。", "天階夜色涼如水，坐看牽牛織女星。"], "intro": "《秋夕》選自《全唐詩》卷五百二十四。秋夕，這裏特指七夕，即陰曆的七月七日夜晚。這是一首宮怨詩，作者選取了宮女秋夜納涼的情景，來反映她們宮中生活的無聊與苦悶。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%A7%8B%E5%A4%95"}, {"title": "寄揚州韓綽判官", "author": "杜牧", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["青山隱隱水迢迢，秋盡江南草木凋。", "二十四橋明月夜，玉人何處教吹簫。"], "quote": ["青山隱隱水迢迢，秋盡江南草木凋。", "二十四橋明月夜，玉人何處教吹簫。"], "intro": "杜牧《寄揚州韓綽判宮》選自《全唐詩》卷五百二十二。 《寄揚州韓綽判官》是杜牧離開揚州後，寄贈韓綽之作。詩中抒發了作者對舊日揚州和故友的思念之情。韓綽與杜牧都是淮南節度使幕中同僚，二人喜作狎邪遊，詩中但言揚州景物，不着人事，可見二人相得之處。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%AF%84%E6%8F%9A%E5%B7%9E%E9%9F%93%E7%B6%BD%E5%88%A4%E5%AE%98"}, {"title": "清明", "author": "杜牧", "period": "唐", "form": "詩", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["清明時節雨紛紛，", "路上行人欲斷魂。", "借問酒家何處有，", "牧童遙指杏花村。"], "quote": ["清明時節雨紛紛，", "路上行人欲斷魂。", "借問酒家何處有，", "牧童遙指杏花村。"], "intro": "", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B8%85%E6%98%8E"}, {"title": "贈別（二首）", "author": "杜牧", "period": "唐", "form": "詩", "theme": "送別行旅", "mood": "spring_breeze", "lines": ["其一", "娉娉裊裊十三餘，豆蔻梢頭二月初。", "春風十里揚州路，捲上珠簾總不如。", "其二", "多情卻似總無情，唯覺樽前笑不成。", "蠟燭有心還惜別，替人垂淚到天明。"], "quote": ["其一", "娉娉裊裊十三餘，豆蔻梢頭二月初。", "春風十里揚州路，捲上珠簾總不如。", "其二"], "intro": "這兩首贈別詩是唐文宗大和九年（八三五）杜牧離開揚州與一位歌女分別時所寫。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B4%88%E5%88%A5%EF%BC%88%E4%BA%8C%E9%A6%96%EF%BC%89"}, {"title": "金縷衣", "author": "杜秋娘", "period": "唐", "form": "詩", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["勸君莫惜金縷衣，勸君惜取少年時！", "花開堪折直須折，莫待無花空折枝。"], "quote": ["勸君莫惜金縷衣，勸君惜取少年時！", "花開堪折直須折，莫待無花空折枝。"], "intro": "《金縷衣》屬於樂府曲辭，是中唐時的一首流行歌詞。據說元和時鎮海節度使李錡酷愛此詞，常命侍妾杜秋娘在酒宴上演唱（見杜牧《杜秋娘詩》及自注）。歌詞的作者已不可考，有的唐詩選本就題爲杜秋娘作或李錡作。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%87%91%E7%B8%B7%E8%A1%A3"}, {"title": "遊子吟", "author": "孟郊", "period": "唐", "form": "詩", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["慈母手中線，遊子身上衣。", "臨行密密縫，意恐遲遲歸。", "誰言寸草心，報得三春暉。"], "quote": ["慈母手中線，遊子身上衣。", "臨行密密縫，意恐遲遲歸。", "誰言寸草心，報得三春暉。"], "intro": "孟郊《遊子吟》選自《全唐詩》卷三百七十二。《遊子吟》為樂府題目，「吟」是詩體的名稱。這首詩題下作者自注：「迎母溧上作。」孟郊於唐德宗貞元十二年（七九六）中進士，之後曾為溧陽縣尉，這首詩就是接他母親到溧陽奉養而作。 詩人有感於母親的養育之恩，", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%81%8A%E5%AD%90%E5%90%9F"}, {"title": "春曉", "author": "孟浩然", "period": "唐", "form": "詩", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["春眠不覺曉，處處聞啼鳥。", "夜來風雨聲，花落知多少？"], "quote": ["春眠不覺曉，處處聞啼鳥。", "夜來風雨聲，花落知多少？"], "intro": "孟浩然《春曉》選自《全唐詩》卷一百六十，寫作者春睡初醒時的情景與感受，合蓄蘊藉，耐人尋味。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%98%A5%E6%9B%89"}, {"title": "宿建德江", "author": "孟浩然", "period": "唐", "form": "詩", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["移舟泊煙渚，日暮客愁新。", "野曠天低樹，江清月近人。"], "quote": ["移舟泊煙渚，日暮客愁新。", "野曠天低樹，江清月近人。"], "intro": "孟浩然《宿建德江》選自《全唐詩》卷一百六十。建德，唐代縣名，屬江南道睦州新定郡，即今浙江建德。浙江流經建德的一段稱建德江。本詩為南遊吳越時所作。作者選取旅程中日暮與日出的片段，抒發羈旅的孤寂感與思鄉之情。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%AE%BF%E5%BB%BA%E5%BE%B7%E6%B1%9F"}, {"title": "過故人莊", "author": "孟浩然", "period": "唐", "form": "詩", "theme": "田園幽居", "mood": "majestic_peaks", "lines": ["故人具雞黍，邀我至田家。", "綠樹村邊合，青山郭外斜。", "開筵面場圃，把酒話桑麻。", "待到重陽日，還來就菊花。"], "quote": ["故人具雞黍，邀我至田家。", "綠樹村邊合，青山郭外斜。", "開筵面場圃，把酒話桑麻。", "待到重陽日，還來就菊花。"], "intro": "《過故人莊》選自《全唐詩》卷一百六十。作者應邀到農家作客，用清新的文字描寫鄉村美麗的風光和閒適恬靜的田園生活。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%81%8E%E6%95%85%E4%BA%BA%E8%8E%8A"}, {"title": "臨洞庭", "author": "孟浩然", "period": "唐", "form": "詩", "theme": "江河湖海", "mood": "vast_river", "lines": ["八月湖水平，涵虛混太清，", "氣蒸雲夢澤，波撼岳陽城。", "欲濟無舟楫，端居恥聖明。", "坐觀垂釣者，徒有羨魚情！"], "quote": ["八月湖水平，涵虛混太清，", "氣蒸雲夢澤，波撼岳陽城。", "欲濟無舟楫，端居恥聖明。", "坐觀垂釣者，徒有羨魚情！"], "intro": "詩題一作《望洞庭湖贈張丞相》，張丞相一般的說法是張九齡。因為張九齡在開元二十一年（公元733）任同中書門下平章事（即丞相），三年後罷相。開元二十五年（公元737）貶為荊州大都督府長史，請孟浩然到幕府中任從事。荊州離洞庭湖不算太遠。所以很可能", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%87%A8%E6%B4%9E%E5%BA%AD"}, {"title": "祖逖傳", "author": "房玄齡", "period": "唐", "form": "文", "theme": "江河湖海", "mood": "snow_winter", "lines": ["祖逖，字士稚，范陽人也。少孤，性豁蕩，不修儀檢；年十四五，猶未知書，諸兄每憂之；然輕財好俠，慷慨有節尚。每至田舍，輒稱兄意散穀帛以賙貧乏，鄉黨、宗族以是重之。", "後乃博覽書記，該涉古今；往來京師，見者謂逖有贊世才具。年二十四，僑居陽平；後與劉琨俱為主簿。情好綢繆，共被同寢。中夜，聞荒雞鳴，蹴琨覺，曰︰「此非惡聲也。」因起舞。", "逖、琨並有英氣，每語世事，或中宵起坐，相謂曰︰「若四海鼎沸，豪傑並起，吾與足下當相避於中原耳。」", "及京師大亂，逖率親黨數百家，避地淮泗。以所乘車馬，載同行老、疾，躬自徒步；藥物衣糧，與眾共之；又多權略，是以少長咸宗之，推逖為行主。達泗口，元帝逆用為徐州刺史；尋徵軍諮祭酒，居丹徒之京口。", "逖以社稷傾覆，常懷振復之志；時帝方拓定江南，未遑北伐。逖進說曰︰「晉室之亂，非上無道而下怨叛也；由藩王爭權，自相誅滅，遂使戎狄乘隙，毒流中原。今遺黎既被殘酷，人有奮擊之志。", "大王誠能發威命將，使若逖等為之統主，則郡國豪傑必因風向赴，沈溺之士欣於來蘇，庶幾國恥可雪。願大王圖之！」帝乃以逖為奮威將軍豫州刺史，給千人，廩布三千匹，不給鎧仗，使自招募。", "仍將本流徒部曲百餘家渡江，中流擊楫而誓曰︰「祖逖不能清中原而復濟者，有如大江！」辭色壯烈，眾皆慨歎。屯於江陰，起冶鑄兵器，得二千餘人而後進。……由是黃河以南，盡為晉土。", "逖愛人下士，雖疎交，賤隸，皆恩禮遇之。躬自儉約，勸督農桑，剋己務施，不畜資產。子弟耕耘，負擔樵薪。又收葬枯骨，為之祭醊，百姓感悅。嘗置酒大會，耆老中坐流涕，曰︰「吾等老矣，更得父母，死將何根？」乃歌曰︰「幸哉遺黎免俘虜，三辰既朗遇慈父，玄酒忘勞甘瓠脯，何以詠恩歌且舞！」其得人心如此。", "方當推鋒越河，掃清冀朔，會朝廷將遣戴若思為都督，且聞王敦與劉隗等構隙，慮有內難，大功不遂，感激發病。病篤，歎曰︰「方平河北，而天欲殺我，此乃不祐國也！」俄卒於雍丘，時年五十六。豫州士女，若喪考妣；譙梁百姓，為之立祠。"], "quote": ["祖逖，字士稚，范陽人也。少孤，性豁蕩，不修儀檢；年十四五，猶未知書，諸兄每憂之；然輕財好俠，慷慨有節尚。每至田舍，輒稱兄意散穀帛以賙貧乏，鄉黨、宗族以是重之。", "後乃博覽書記，該涉古今；往來京師，見者謂逖有贊世才具。年二十四，僑居陽平；後與劉琨俱為主簿。情好綢繆，共被同寢。中夜，聞荒雞鳴，蹴琨覺，曰︰「此非惡聲也。」因起舞。", "逖、琨並有英氣，每語世事，或中宵起坐，相謂曰︰「若四海鼎沸，豪傑並起，吾與足下當相避於中原耳。」", "及京師大亂，逖率親黨數百家，避地淮泗。以所乘車馬，載同行老、疾，躬自徒步；藥物衣糧，與眾共之；又多權略，是以少長咸宗之，推逖為行主。達泗口，元帝逆用為徐州刺史；尋徵軍諮祭酒，居丹徒之京口。"], "intro": "本篇節選自《晉書》裏的《祖逖傳》。祖逖，生於公元二六六年，卒於公元三二一年；在他的生存期間，正是晉朝受了外族的侵略，喪失了中原大部國土，退守江南，偏安一隅的時代。他曾立志恢復國土，實行渡江北伐，率領着反攻的健兒，和敵人的軍隊相周旋，終於光復", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%A5%96%E9%80%96%E5%82%B3"}, {"title": "三戒‧黔之驢", "author": "柳宗元", "period": "唐", "form": "文", "theme": "江河湖海", "mood": "vast_river", "lines": ["黔無驢。有好事者船載以入。至，則無可用，放之山下。虎見之，龐然大物也，以為神，蔽林間窺之。稍出近之，憖憖然莫相知。", "他日，驢一鳴，虎大駭，遠遁，以為且噬己也，甚恐。然往來視之，覺無異能者，益習其聲，又近出前後，終不敢搏。稍近益狎，蕩倚衝冒。", "驢不勝怒，蹄之。虎因喜，計之曰︰「技止此耳！」因跳踉大㘚，斷其喉，盡其肉，乃去。", "噫！形之龐也類有德，聲之宏也類有能，向不出其技，虎雖猛，疑畏，卒不敢取。今若是焉，悲夫！"], "quote": ["黔無驢。有好事者船載以入。至，則無可用，放之山下。虎見之，龐然大物也，以為神，蔽林間窺之。稍出近之，憖憖然莫相知。", "他日，驢一鳴，虎大駭，遠遁，以為且噬己也，甚恐。然往來視之，覺無異能者，益習其聲，又近出前後，終不敢搏。稍近益狎，蕩倚衝冒。", "驢不勝怒，蹄之。虎因喜，計之曰︰「技止此耳！」因跳踉大㘚，斷其喉，盡其肉，乃去。", "噫！形之龐也類有德，聲之宏也類有能，向不出其技，虎雖猛，疑畏，卒不敢取。今若是焉，悲夫！"], "intro": "本課選自《河東先生集》卷三，是《三戒》中的第二篇。孔子說：「君子有三戒」（《論語‧季氏》），柳宗元便用「三戒」作為三篇寓言的總題，意思是告訴人們三件應該警戒的事情。黔，唐代的黔中道，包括現在的湖北、四川、貴州、湖南部分地區，後來改稱現在的貴", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B8%89%E6%88%92%E2%80%A7%E9%BB%94%E4%B9%8B%E9%A9%A2"}, {"title": "江雪", "author": "柳宗元", "period": "唐", "form": "詩", "theme": "江河湖海", "mood": "snow_winter", "lines": ["千山鳥飛絕，", "萬徑人踪滅，", "孤舟蓑笠翁，", "獨釣寒江雪。"], "quote": ["千山鳥飛絕，", "萬徑人踪滅，", "孤舟蓑笠翁，", "獨釣寒江雪。"], "intro": "這首詩是柳宗元貶居永州（今湖南省零陵縣）時的作品，在一定程度上可以看作詩人的自況。政治鬥爭失敗後，他被貶到永州，當一名毫無實權的閒官，感到十分苦悶；詩中孤獨漁翁的形象，正是柳宗元本人的寫照。但是詩人雖身處逆境，仍能以堅毅的意志面對人生。他在", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B1%9F%E9%9B%AA"}, {"title": "至小丘西小石潭記", "author": "柳宗元", "period": "唐", "form": "文", "theme": "山水登臨", "mood": "snow_winter", "lines": ["從小丘西行百二十步，隔篁竹，聞水聲，如鳴珮環，心樂之，伐竹取道，下見小潭，水尤清冽，全石以為底，近岸卷石底以出，為坻、為嶼、為嵁、為巖，青樹翠蔓，蒙絡搖綴，參差披拂。潭中魚可百許頭，皆若空遊無所依，日光下澈，影布石上，怡然不動，俶爾遠逝，往來翕忽，似與游者相樂。", "潭西南而望，斗折蛇行，明滅可見，其岸勢犬牙差互，不可知其源，坐潭上，四面竹樹環合，寂寥無人，凄神寒骨，悄愴幽邃，以其境過清，不可久居，乃記之而去。同遊者吳武陵、龔古、余弟宗玄，隸而從者，崔氏二小生，曰恕己、曰奉壹。"], "quote": ["從小丘西行百二十步，隔篁竹，聞水聲，如鳴珮環，心樂之，伐竹取道，下見小潭，水尤清冽，全石以為底，近岸卷石底以出，為坻、為嶼、為嵁、為巖，青樹翠蔓，蒙絡搖綴，參差披拂。潭中魚可百許頭，皆若空遊無所依，日光下澈，影布石上，怡然不動，俶爾遠逝，往來翕忽，似與游者相樂。", "潭西南而望，斗折蛇行，明滅可見，其岸勢犬牙差互，不可知其源，坐潭上，四面竹樹環合，寂寥無人，凄神寒骨，悄愴幽邃，以其境過清，不可久居，乃記之而去。同遊者吳武陵、龔古、余弟宗玄，隸而從者，崔氏二小生，曰恕己、曰奉壹。"], "intro": "《至小丘西小石潭記》選自《柳河東集》卷二十九。柳宗元被貶永州後，遊山玩水，尋幽探勝，並把各地的勝景一一記敍。這些山水遊記中最有代表性的是「永州八記」。這八篇文章包括《始得西山宴遊記》、《鈷鉧潭記》、《鈷鉧潭西小丘記》、《袁家碣記》、《石渠記", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%87%B3%E5%B0%8F%E4%B8%98%E8%A5%BF%E5%B0%8F%E7%9F%B3%E6%BD%AD%E8%A8%98"}, {"title": "始得西山宴遊記", "author": "柳宗元", "period": "唐", "form": "文", "theme": "山水登臨", "mood": "autumn_sunset", "lines": ["自余為僇人，居是州，恆惴慄。其隟也，則施施而行，漫漫而遊；日與其徒上高山，入深林，窮迴溪；幽泉怪石，無遠不到；", "到則披草而坐，傾壼而醉；醉則更相枕以臥；臥而夢，意有所極，夢亦同趣；覺而起，起而歸。以為凡是州之山有異態者，皆我有也。而未始知西山之怪特。", "今年九月二十八日，因坐法華西亭，望西山，始指異之。遂命僕過湘江，緣染溪，斫榛莽，焚茅茷，窮山之高而止。攀援而登，箕踞而遨，則凡數州之土壤，皆在衽席之下。", "其高下之勢，岈然、洼然，若垤、若穴，尺寸千里，攢蹙累積，莫得遯隱。縈青繚白，外與天際，四望如一。然後知是山之特出，不與培塿為類，悠悠乎與灝氣俱而莫得其涯，洋洋乎與造物者游而不知其所窮。", "引觴滿酌，頹然就醉，不知日之入。蒼然暮色，自遠而至，至無所見，而猶不欲歸。心凝形釋，與萬化冥合，然後知吾嚮之未始遊，遊於是乎始。故為之文以志。", "是歲，元和四年也。"], "quote": ["自余為僇人，居是州，恆惴慄。其隟也，則施施而行，漫漫而遊；日與其徒上高山，入深林，窮迴溪；幽泉怪石，無遠不到；", "到則披草而坐，傾壼而醉；醉則更相枕以臥；臥而夢，意有所極，夢亦同趣；覺而起，起而歸。以為凡是州之山有異態者，皆我有也。而未始知西山之怪特。", "今年九月二十八日，因坐法華西亭，望西山，始指異之。遂命僕過湘江，緣染溪，斫榛莽，焚茅茷，窮山之高而止。攀援而登，箕踞而遨，則凡數州之土壤，皆在衽席之下。", "其高下之勢，岈然、洼然，若垤、若穴，尺寸千里，攢蹙累積，莫得遯隱。縈青繚白，外與天際，四望如一。然後知是山之特出，不與培塿為類，悠悠乎與灝氣俱而莫得其涯，洋洋乎與造物者游而不知其所窮。"], "intro": "作者在永州曾寫了八篇遊記，描寫永州的山水風景，總名為《永州八記》。這樣所選的是其中的一篇，錄自《柳河東集》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%A7%8B%E5%BE%97%E8%A5%BF%E5%B1%B1%E5%AE%B4%E9%81%8A%E8%A8%98"}, {"title": "哀溺文序（節錄）", "author": "柳宗元", "period": "唐", "form": "文", "theme": "江河湖海", "mood": "vast_river", "lines": ["永之氓咸善游。一日，水暴甚，有五、六氓，乘小船絕湘水。中濟，船破，皆游。其一氓盡力而不能尋常。其侶曰︰「汝善游最也，今何後為？」曰︰「吾腰千錢，重，是以後。」曰︰「何不去之？」不應，搖其首。有頃益怠。已濟者立岸上呼且號曰︰「汝愚之甚，蔽之甚！身且死，何以貨為？」又搖其首，遂溺死。"], "quote": ["永之氓咸善游。一日，水暴甚，有五、六氓，乘小船絕湘水。中濟，船破，皆游。其一氓盡力而不能尋常。其侶曰︰「汝善游最也，今何後為？」曰︰「吾腰千錢，重，是以後。」曰︰「何不去之？」不應，搖其首。有頃益怠。已濟者立岸上呼且號曰︰「汝愚之甚，蔽之甚！身且死，何以貨為？」又搖其首，遂溺死。"], "intro": "《哀溺文》載於《柳宗元集》第十八卷。原文由序和正文兩部分組成，序是一篇散文體的寓言，正文是一段仿《楚辭》體裁的抒情小賦。這裏所節選的就是序文的一部分。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%93%80%E6%BA%BA%E6%96%87%E5%BA%8F%EF%BC%88%E7%AF%80%E9%8C%84%EF%BC%89"}, {"title": "捕蛇者說", "author": "柳宗元", "period": "唐", "form": "文", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["永州之野產異蛇，黑質而白章，觸草木，盡死；以齧人，無禦之者。然得而腊之以為餌，可以已大風、攣踠、瘻、癘，去死肌，殺三蟲。其始，太醫以王命聚之，歲賦其二；募有能捕之者，當其租入。永之人爭奔走焉。", "有蔣氏者，專其利三世矣。問之，則曰︰「吾祖死於是，吾父死於是，今吾嗣為之十二年，幾死者數矣。」言之，貌若甚慼者。", "余悲之，且曰︰「若毒之乎？余將告於蒞事者，更若役，復若賦，則何如？」", "蔣氏大戚，汪然出涕曰︰「君將哀而生之乎？則吾斯役之不幸，未若復吾賦不幸之甚也。嚮吾不為斯役，則久已病矣。自吾氏三世居是鄉，積於今六十歲矣，而鄉鄰之生日蹙。殫其地之出，竭其廬之入，呼號而轉徙，饑渴而頓踣，觸風雨，犯寒暑，呼噓毒癘，往往而死者相藉也。", "曩與吾祖居者，今其室十無一焉；與吾父居者，今其室十無二三焉；與吾居十二年者，今其室十無四五焉。非死則徙爾，而吾以捕蛇獨存。悍吏之來吾鄉，叫囂乎東西，隳突乎南北，譁然而駭者，雖雞狗不得寧焉。吾恂恂而起，視其缶，而吾蛇尚存，則弛然而臥。", "謹食之，時而獻焉。退而甘食其土之有，以盡吾齒。蓋一歲之犯死者二焉；其餘則熙熙而樂。豈若吾鄉鄰之旦旦若是哉？今雖死乎此，比吾鄉鄰之死則已後矣，又安敢毒耶？」", "余聞而愈悲。孔子曰︰「苛政猛於虎也！」吾嘗疑乎是。今以蔣氏觀之，猶信。嗚呼！孰知賦歛之毒，有甚是蛇者乎？故為之說，以俟夫觀人風者得焉。"], "quote": ["永州之野產異蛇，黑質而白章，觸草木，盡死；以齧人，無禦之者。然得而腊之以為餌，可以已大風、攣踠、瘻、癘，去死肌，殺三蟲。其始，太醫以王命聚之，歲賦其二；募有能捕之者，當其租入。永之人爭奔走焉。", "有蔣氏者，專其利三世矣。問之，則曰︰「吾祖死於是，吾父死於是，今吾嗣為之十二年，幾死者數矣。」言之，貌若甚慼者。", "余悲之，且曰︰「若毒之乎？余將告於蒞事者，更若役，復若賦，則何如？」", "蔣氏大戚，汪然出涕曰︰「君將哀而生之乎？則吾斯役之不幸，未若復吾賦不幸之甚也。嚮吾不為斯役，則久已病矣。自吾氏三世居是鄉，積於今六十歲矣，而鄉鄰之生日蹙。殫其地之出，竭其廬之入，呼號而轉徙，饑渴而頓踣，觸風雨，犯寒暑，呼噓毒癘，往往而死者相藉也。"], "intro": "唐朝賦稅，本輕徭薄役，租庸調制，四十而稅一。中唐以後，行兩稅制法，量出為入，紕漏始生。憲宗元和年間，李渤上奏曰︰「渭南縣長源鄉，本有四百戶，今才一百餘戶。閺鄉縣本有三千戶，今才有一千戶。其他州縣，大約相似。訪尋積弊，始自均攤逃戶。凡十家之內", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%8D%95%E8%9B%87%E8%80%85%E8%AA%AA"}, {"title": "鈷鉧潭記", "author": "柳宗元", "period": "唐", "form": "文", "theme": "田園幽居", "mood": "autumn_sunset", "lines": ["鈷鉧潭在西山西。其始蓋冉水自南奔注，扺山石，屈折東流。其顛委勢峻，盪擊益暴，齧其涯，故旁廣而中深，畢至石乃止。", "流沫成輪，然後徐行。其清而平者且十畝，有樹環焉，有泉懸焉。", "其上有居者，以余之亟游也，一旦款門來告曰︰「不勝官租私券之委積，既芟山而更居，願以潭上田貿財以緩禍。」予樂而如其言。", "則崇其臺，延其檻。行其泉於高者而墜之潭，有聲潀然，尤與中秋觀月為宜。於以見天之高，氣之迥。孰使予樂居夷而忘故土者，非茲潭也歟！"], "quote": ["鈷鉧潭在西山西。其始蓋冉水自南奔注，扺山石，屈折東流。其顛委勢峻，盪擊益暴，齧其涯，故旁廣而中深，畢至石乃止。", "流沫成輪，然後徐行。其清而平者且十畝，有樹環焉，有泉懸焉。", "其上有居者，以余之亟游也，一旦款門來告曰︰「不勝官租私券之委積，既芟山而更居，願以潭上田貿財以緩禍。」予樂而如其言。", "則崇其臺，延其檻。行其泉於高者而墜之潭，有聲潀然，尤與中秋觀月為宜。於以見天之高，氣之迥。孰使予樂居夷而忘故土者，非茲潭也歟！"], "intro": "作者在永州司馬任內寫了八篇遊記，描寫永州的山水風景，包括：《始得西山宴遊記》、《鈷鉧潭記》、《鈷鉧潭西小丘記》、《至小丘西小石潭記》、《袁家渴記》、《石渠記》、《石澗記》、《小石城山記》，總名為「永州八記」。這樣所選的是其中一篇，作於唐憲宗", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%88%B7%E9%89%A7%E6%BD%AD%E8%A8%98"}, {"title": "漁翁", "author": "柳宗元", "period": "唐", "form": "詩", "theme": "江河湖海", "mood": "vast_river", "lines": ["漁翁夜傍西巖宿，曉汲清湘燃楚竹。", "煙銷日出不見人，欸乃一聲山水綠。", "迴看天際下中流，巖上無心雲相逐。"], "quote": ["漁翁夜傍西巖宿，曉汲清湘燃楚竹。", "煙銷日出不見人，欸乃一聲山水綠。", "迴看天際下中流，巖上無心雲相逐。"], "intro": "《漁翁》選自《全唐詩》卷三百五十三，是作者在永州時的作品。柳宗元被貶永州後，為排解心中的孤寂和鬱悶，寫了不少寄情於山水的詩篇。本詩以樸實的筆觸描寫了漁翁曉出作業的生活和江上四周的景物，構成一幅清新秀麗的畫面。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%BC%81%E7%BF%81"}, {"title": "種樹郭橐駝傳", "author": "柳宗元", "period": "唐", "form": "文", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["郭橐駝，不知始何名。病僂隆然伏行，有類橐駝者，故鄉人號之駝。駝聞之曰︰「甚善！名我固當。」因捨其名，亦自謂橐駝云。", "其鄉曰「豐樂鄉」，在長安西。駝業種樹，凡長安豪家、富人為觀遊及賣果者，皆爭迎取養。視駝所種樹，或移徙，無不活；且碩茂，蚤實以蕃。他植者雖窺伺、傚慕，莫能如也。", "有問之，對曰︰「橐駝，非能使木壽且孳也；能順木之天，以致其性焉爾。凡植木之性，其本欲舒，其培欲平，其土欲故，其築欲密。既然已，勿動勿慮，去不復顧。其蒔也若予，其置也若棄，則其天者全，而其性得矣。故吾不害其長而已，非有能碩茂之也；不抑耗其實而已，非有能蚤而蕃之也。他植者則不然，根拳而土易；其培之也，若不過焉則不及。苟有能反是者，則又愛之太恩，憂之太勤，旦視而暮撫，已去而復顧；甚者爪其膚以驗其生枯，搖其本以觀其疏密，而木之性日以離矣。雖曰愛之，其實害之；雖曰憂之，其實讐之；故不我若也。吾又何能為哉？」", "問者曰︰「以子之道，移之官理，可乎？」駝曰︰「我知種樹而已，官理非吾業也。然吾居鄉，見長人者好煩其令，若甚憐焉，而卒以禍。旦暮，吏來而呼曰︰『官命促爾耕，勖爾植，督爾獲，蚤繰而緒，蚤織而縷，字而幼孩，遂而雞豚。』鳴鼓而聚之，擊木而召之。吾小人輟飧饔以勞吏者，且不得暇，又何以蕃吾生而安吾性邪？故病且殆若是。則與吾業者，其亦有類乎？」", "問者嘻曰︰「不亦善夫？吾問養樹，得養人術。傳其事以為官戒也。」"], "quote": ["郭橐駝，不知始何名。病僂隆然伏行，有類橐駝者，故鄉人號之駝。駝聞之曰︰「甚善！名我固當。」因捨其名，亦自謂橐駝云。", "其鄉曰「豐樂鄉」，在長安西。駝業種樹，凡長安豪家、富人為觀遊及賣果者，皆爭迎取養。視駝所種樹，或移徙，無不活；且碩茂，蚤實以蕃。他植者雖窺伺、傚慕，莫能如也。", "有問之，對曰︰「橐駝，非能使木壽且孳也；能順木之天，以致其性焉爾。凡植木之性，其本欲舒，其培欲平，其土欲故，其築欲密。既然已，勿動勿慮，去不復顧。其蒔也若予，其置也若棄，則其天者全，而其性得矣。故吾不害其長而已，非有能碩茂之也；不抑耗其實而已，非有能蚤而蕃之也。他植者則不然，根拳而土易；其培之也，若不過焉則不及。苟有能反是者，則又愛之太恩，憂之太勤，旦視而暮撫，已去而復顧；甚者爪其膚以驗其生枯，搖其本以觀其疏密，而木之性日以離矣。雖曰愛之，其實害之；雖曰憂之，其實讐之；故不我若也。吾又何能為哉？」", "問者曰︰「以子之道，移之官理，可乎？」駝曰︰「我知種樹而已，官理非吾業也。然吾居鄉，見長人者好煩其令，若甚憐焉，而卒以禍。旦暮，吏來而呼曰︰『官命促爾耕，勖爾植，督爾獲，蚤繰而緒，蚤織而縷，字而幼孩，遂而雞豚。』鳴鼓而聚之，擊木而召之。吾小人輟飧饔以勞吏者，且不得暇，又何以蕃吾生而安吾性邪？故病且殆若是。則與吾業者，其亦有類乎？」"], "intro": "種樹，替以栽種樹木為業的人。郭橐駝，人名；不過實際上卻沒有這麼一個人，只是作者為了發揮他的政治主張，和諷刺當時的行政，特假託了這樣一個人名，藉種樹做比喻罷了。所以雖然標題為「傳」，卻不是「傳」，而是一篇寓言。選自《柳河東集》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%A8%AE%E6%A8%B9%E9%83%AD%E6%A9%90%E9%A7%9D%E5%82%B3"}, {"title": "滁州西澗", "author": "韋應物", "period": "唐", "form": "詩", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["獨憐幽草澗邊生，上有黃鸝深樹鳴。", "春潮帶雨晚來急，野渡無人舟自橫。"], "quote": ["獨憐幽草澗邊生，上有黃鸝深樹鳴。", "春潮帶雨晚來急，野渡無人舟自橫。"], "intro": "《滁州西澗》選自《全唐詩》卷一百九十三，是詩人於唐德宗建中二年（七八一）任滁州刺史時所作。滁州，唐時屬淮南東道，州治在今安徽省。滁州西澗在滁州城西門外，景色幽美，詩人常到那裏流連，這是他寫景抒情之代表作，表露出恬淡的情懷。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%BB%81%E5%B7%9E%E8%A5%BF%E6%BE%97"}, {"title": "登幽州臺歌", "author": "陳子昂", "period": "唐", "form": "詩", "theme": "山水登臨", "mood": "ethereal", "lines": ["前不見古人，後不見來者。", "念天地之悠悠，獨愴然而涕下！"], "quote": ["前不見古人，後不見來者。", "念天地之悠悠，獨愴然而涕下！"], "intro": "《登幽州臺歌》選自《全唐詩》卷八十三。幽州臺即薊北樓，故址在今北京德勝門西北。這首詩是陳子昂在武則天萬歲通天元年（六九六），隨軍北征契丹時於幽州所作。當時北征大軍的前鋒戰敗，主將武攸宜不僅不聽從陳子昂退敵之策，並且把他降職。子昂感慨萬分，發", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%99%BB%E5%B9%BD%E5%B7%9E%E8%87%BA%E6%AD%8C"}, {"title": "燕歌行  並序", "author": "高適", "period": "唐", "form": "詩", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["開元二十六年，客有從御史大夫張公出塞而還者，作《燕歌行》以示適，感征戍之事，因而和焉。", "漢家煙塵在東北，漢將辭家破殘賊。", "男兒本自重橫行，天子非常賜顏色。", "摐金伐鼓下榆關，旌旆逶迤碣石間。", "校尉羽書飛瀚海，單于獵火照狼山。", "山川蕭條極邊土，胡騎憑陵雜風雨。", "戰士軍前半死生，美人帳下猶歌舞。", "大漠窮秋塞草腓，孤城落日鬥兵稀。", "身當恩遇恆輕敵，力盡關山未解圍。", "鐵衣遠戍辛勤久，玉筯應啼別離後。", "少婦城南欲斷腸，征人薊北空回首。", "邊庭飄颻那可度，絕域蒼茫更何有！"], "quote": ["開元二十六年，客有從御史大夫張公出塞而還者，作《燕歌行》以示適，感征戍之事，因而和焉。", "漢家煙塵在東北，漢將辭家破殘賊。", "男兒本自重橫行，天子非常賜顏色。", "摐金伐鼓下榆關，旌旆逶迤碣石間。"], "intro": "本詩選自《全唐詩》卷二百一十三，作於唐玄宗開元二十六年（七三八）。燕歌行屬樂府《相和歌‧平調曲》舊題，歌辭多詠東北邊地征戍之情。燕，在河北一帶。詩序所言的張公即張守珪，是當時鎮守北邊的名將。後因恃功驕縱，不惜士卒，任其生死，遂激發高適寫成此", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%87%95%E6%AD%8C%E8%A1%8C++%E4%B8%A6%E5%BA%8F"}, {"title": "黃鶴樓", "author": "崔顥", "period": "唐", "form": "詩", "theme": "田園幽居", "mood": "autumn_sunset", "lines": ["昔人已乘白雲去，此地空餘黃鶴樓。", "黃鶴一去不復返，白雲千載空悠悠。", "晴川歷歷漢陽樹，春草萋萋鸚鵡洲。", "日暮鄉關何處是？煙波江上使人愁。"], "quote": ["昔人已乘白雲去，此地空餘黃鶴樓。", "黃鶴一去不復返，白雲千載空悠悠。", "晴川歷歷漢陽樹，春草萋萋鸚鵡洲。", "日暮鄉關何處是？煙波江上使人愁。"], "intro": "崔顥《黃鶴樓》選自《全唐詩》卷一百三十。黃鶴樓，故址在今湖北武漢西蛇山上，相傳建於三國吳國大帝黃武二年（二二三），面臨長江。作者登上宏偉的黃鶴樓，極目遠眺，胸中湧起無限的感慨。在讚嘆山川壯美之餘，流露出懷念家鄉的深情。此詩在當時即享盛名，受", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%BB%83%E9%B6%B4%E6%A8%93"}, {"title": "望月懷遠", "author": "張九齡", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["海上生明月，天涯共此時。情人怨遙夜，竟夕起相思。", "滅燭憐光滿，披衣覺露滋。不堪盈手贈，還寢夢佳期。"], "quote": ["海上生明月，天涯共此時。情人怨遙夜，竟夕起相思。", "滅燭憐光滿，披衣覺露滋。不堪盈手贈，還寢夢佳期。"], "intro": "《望月懷遠》選自《全唐詩》卷四十八，是張九齡在唐玄宗開元二十五年（七三七）被貶官荊州期間所作。這是一首描寫海上明月，同時懷念遠人的詩。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9C%9B%E6%9C%88%E6%87%B7%E9%81%A0"}, {"title": "漁歌子（其一）（西塞山前白鷺飛）", "author": "張志和", "period": "唐", "form": "詞", "theme": "江河湖海", "mood": "vast_river", "lines": ["西塞山前白鷺飛，桃花流水鱖魚肥。青箬笠、綠蓑衣，斜風細雨不須歸。"], "quote": ["西塞山前白鷺飛，桃花流水鱖魚肥。青箬笠、綠蓑衣，斜風細雨不須歸。"], "intro": "《漁歌子》（西塞山前白鷺飛）選自《尊前集》，原題共五首，今選其中一首。這是作者退隱江湖後得意之作。歌詞流暢自然，不假彫飾。「斜風細雨」一句，既寫景，亦言情。暗示遠離塵俗，不復再問世事之願。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%BC%81%E6%AD%8C%E5%AD%90%EF%BC%88%E5%85%B6%E4%B8%80%EF%BC%89%EF%BC%88%E8%A5%BF%E5%A1%9E%E5%B1%B1%E5%89%8D%E7%99%BD%E9%B7%BA%E9%A3%9B%EF%BC%89"}, {"title": "春江花月夜", "author": "張若虛", "period": "唐", "form": "詩", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["春江潮水連海平，海上明月共潮生。灩灩隨波千萬里，何處春江無月明！江流宛轉遶芳甸，月照花林皆似霰。空裏流霜不覺飛，汀上白沙看不見。江天一色無纖塵，皎皎空中孤月輪。", "江畔何人初見月﹖江月何年初照人？人生代代無窮已，江月年年祇相似。不知江月待何人，但見長江送流水。白雲一片去悠悠，青楓浦上不勝愁。誰家今夜扁舟子？何處相思明月樓？可憐樓上月徘徊，應照離人妝鏡臺。", "玉戶簾中卷不去，擣衣砧上拂還來。此時相望不相聞，願逐月華流照君。鴻雁長飛光不度，魚龍潛躍水成文。昨夜閑潭夢落花，可憐春半不還家。", "江水流春去欲盡，江潭落月復西斜。斜月沉沉藏海霧。碣石瀟湘無限路。不知乘月幾人歸，落月搖情滿江樹。"], "quote": ["春江潮水連海平，海上明月共潮生。灩灩隨波千萬里，何處春江無月明！江流宛轉遶芳甸，月照花林皆似霰。空裏流霜不覺飛，汀上白沙看不見。江天一色無纖塵，皎皎空中孤月輪。", "江畔何人初見月﹖江月何年初照人？人生代代無窮已，江月年年祇相似。不知江月待何人，但見長江送流水。白雲一片去悠悠，青楓浦上不勝愁。誰家今夜扁舟子？何處相思明月樓？可憐樓上月徘徊，應照離人妝鏡臺。", "玉戶簾中卷不去，擣衣砧上拂還來。此時相望不相聞，願逐月華流照君。鴻雁長飛光不度，魚龍潛躍水成文。昨夜閑潭夢落花，可憐春半不還家。", "江水流春去欲盡，江潭落月復西斜。斜月沉沉藏海霧。碣石瀟湘無限路。不知乘月幾人歸，落月搖情滿江樹。"], "intro": "原是樂府舊題，相傳為南朝後主陳叔寶所創。張若虛這首詩只是用了這個題目來創作，已非原有曲調。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%98%A5%E6%B1%9F%E8%8A%B1%E6%9C%88%E5%A4%9C"}, {"title": "節婦吟", "author": "張籍", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["君知妾有夫，贈妾雙明珠；", "感君纏綿意，繫在紅羅襦。", "妾家高樓連苑起，良人執戟明光裏。", "知君用心如日月，事夫誓擬同生死。", "還君明珠雙淚垂，恨不相逢未嫁時！"], "quote": ["君知妾有夫，贈妾雙明珠；", "感君纏綿意，繫在紅羅襦。", "妾家高樓連苑起，良人執戟明光裏。", "知君用心如日月，事夫誓擬同生死。"], "intro": "本篇題下一作「寄東平李司空」，或「寄東平李司空師道」。「李司空」即是當時的淄青（今山東益都）節度使李師道，「東平」即鄆州（今山東東平），是淄青節度使的使府所在。據《舊唐書‧憲宗本紀》所載，元和十一年（公元八一六）冬十月李師道加檢校司空；元和", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%AF%80%E5%A9%A6%E5%90%9F"}, {"title": "楓橋夜泊", "author": "張繼", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["月落烏啼霜滿天，江楓漁父對愁眠。", "姑蘇城外寒山寺，夜半鐘聲到客船。"], "quote": ["月落烏啼霜滿天，江楓漁父對愁眠。", "姑蘇城外寒山寺，夜半鐘聲到客船。"], "intro": "《楓橋夜泊》選自《全唐詩》卷二百四十二，一作「夜泊楓江」。楓橋，亦名封橋，在今江蘇蘇州市楓橋鎮。這首詩寫羈旅中的客愁。詩人善於以景物烘托情緒，無論遠觀、近觀、一景、一聲，都充分表露出客旅的愁懷。此詩一出，千古傳誦。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%A5%93%E6%A9%8B%E5%A4%9C%E6%B3%8A"}, {"title": "官倉鼠", "author": "曹鄴", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["官倉老鼠大如斗，見人開倉亦不走。", "健兒無糧百姓饑，誰遣朝朝入君口？"], "quote": ["官倉老鼠大如斗，見人開倉亦不走。", "健兒無糧百姓饑，誰遣朝朝入君口？"], "intro": "唐朝末年，藩鎮割據，朋黨傾軋，宦官專權，從皇帝到縣吏，無不貪殘暴虐，國家被搞得烏煙瘴氣，民變四起，後來終於爆發了黃巢之亂。這首詩便是在晚唐這樣動盪的社會背景下寫成的。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%AE%98%E5%80%89%E9%BC%A0"}, {"title": "閔子騫童年", "author": "敦煌變文", "period": "唐", "form": "文", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["閔子騫，名損，魯人也。父取後妻，生二子，騫供養父母，孝敬無怠。後母嫉之，所生親子，衣加棉絮，子騫與蘆花絮衣。其父不知，冬月，遣子御車，騫不堪甚，騫手凍，數失繮靷，父乃責之，騫終不自理。", "父密察之，知騫有寒色，父以手撫之，見衣甚薄，毀而觀之，始知非絮。後妻二子，純衣以綿。父乃悲歎，遂遣其妻。子騫雨淚前白父曰︰「母在一子寒，母去三子單，願大人思之。」父慚而止。後母悔過，遂以三子均平，衣食如一，得成慈母。孝子聞於天下。"], "quote": ["閔子騫，名損，魯人也。父取後妻，生二子，騫供養父母，孝敬無怠。後母嫉之，所生親子，衣加棉絮，子騫與蘆花絮衣。其父不知，冬月，遣子御車，騫不堪甚，騫手凍，數失繮靷，父乃責之，騫終不自理。", "父密察之，知騫有寒色，父以手撫之，見衣甚薄，毀而觀之，始知非絮。後妻二子，純衣以綿。父乃悲歎，遂遣其妻。子騫雨淚前白父曰︰「母在一子寒，母去三子單，願大人思之。」父慚而止。後母悔過，遂以三子均平，衣食如一，得成慈母。孝子聞於天下。"], "intro": "本文選自《敦煌變文集》中的《孝子傳》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%96%94%E5%AD%90%E9%A8%AB%E7%AB%A5%E5%B9%B4"}, {"title": "更漏子（玉爐香）", "author": "温庭筠", "period": "唐", "form": "詞", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["玉爐香，紅蠟淚，偏照畫堂秋思。眉翠薄，鬢雲殘，夜長衾枕寒。", "梧桐樹，三更雨，不道離情正苦。一葉葉，一聲聲，空階滴到明。"], "quote": ["玉爐香，紅蠟淚，偏照畫堂秋思。眉翠薄，鬢雲殘，夜長衾枕寒。", "梧桐樹，三更雨，不道離情正苦。一葉葉，一聲聲，空階滴到明。"], "intro": "《更漏子》，詞牌名，又名《付金釵》、《獨倚樓》、《翻翠袖》。溫庭筠共寫過六首內容相仿的《更漏子》。這一首《更漏子》（玉爐香），借「更漏」夜景詠女子相思情事，詞從夜晚寫到天明。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9B%B4%E6%BC%8F%E5%AD%90%EF%BC%88%E7%8E%89%E7%88%90%E9%A6%99%EF%BC%89"}, {"title": "菩薩蠻（小山重疊金明滅）", "author": "温庭筠", "period": "唐", "form": "詞", "theme": "山水登臨", "mood": "snow_winter", "lines": ["小山重疊金明滅，鬢雲欲度香腮雪。懶起畫蛾眉，弄妝梳洗遲。", "照花前後鏡，花面交相映。新帖繡羅襦，雙雙金鷓鴣。"], "quote": ["小山重疊金明滅，鬢雲欲度香腮雪。懶起畫蛾眉，弄妝梳洗遲。", "照花前後鏡，花面交相映。新帖繡羅襦，雙雙金鷓鴣。"], "intro": "《菩薩蠻》為唐教坊曲名，後用為詞牌，亦作《菩薩鬘》。 據《唐才子傳》和《北夢瑣言》記載，唐宣宗喜歡曲詞《菩薩蠻》，相國令狐綯暗中請溫庭筠代自己填《菩薩蠻》詞，再向宣宗進獻。當時約在大中四年（八五〇）十月至十三年（八五九）之間。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%8F%A9%E8%96%A9%E8%A0%BB%EF%BC%88%E5%B0%8F%E5%B1%B1%E9%87%8D%E7%96%8A%E9%87%91%E6%98%8E%E6%BB%85%EF%BC%89"}, {"title": "蘇武廟", "author": "温庭筠", "period": "唐", "form": "詩", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["蘇武魂銷漢使前，古祠高樹兩茫然。", "雲邊雁斷胡天月，隴上羊歸塞草煙。", "回日樓臺非甲帳，去時冠劍是丁年。", "茂陵不見封侯印，空向秋波哭逝川。"], "quote": ["蘇武魂銷漢使前，古祠高樹兩茫然。", "雲邊雁斷胡天月，隴上羊歸塞草煙。", "回日樓臺非甲帳，去時冠劍是丁年。", "茂陵不見封侯印，空向秋波哭逝川。"], "intro": "蘇武是歷史上著名的堅持民族氣節的英雄人物。漢武帝天漢元年（前100年）他出使匈奴，被扣留異地。匈奴多次逼降，他堅貞不屈，被流放到北海牧羊。直至昭帝始元六年（前81年），才被遣返漢朝，前後長達十九年。這首詩是溫庭筠瞻仰蘇武廟後追思憑弔之作。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%98%87%E6%AD%A6%E5%BB%9F"}, {"title": "回鄉偶書", "author": "賀知章", "period": "唐", "form": "詩", "theme": "送別行旅", "mood": "autumn_sunset", "lines": ["少小離鄉老大回，鄉音難改鬢毛衰。", "兒童相見不相識，笑問客從何處來。"], "quote": ["少小離鄉老大回，鄉音難改鬢毛衰。", "兒童相見不相識，笑問客從何處來。"], "intro": "賀知章《回鄉偶書》選自《全唐詩》卷一百一十二，原題共兩首，此處選錄第一首。本詩是詩人晚年之作，寫久別還鄉的感受。賀知章年少時就離開了故鄉，直到老年才得返故里，「鄉音難改」蘊藏着對故鄉的深情。全詩樸素平實，對比鮮明。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%9B%9E%E9%84%89%E5%81%B6%E6%9B%B8"}, {"title": "詠柳", "author": "賀知章", "period": "唐", "form": "詩", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["碧玉妝成一樹高，萬條垂下綠絲縧。", "不知細葉誰裁出，二月春風似剪刀。"], "quote": ["碧玉妝成一樹高，萬條垂下綠絲縧。", "不知細葉誰裁出，二月春風似剪刀。"], "intro": "", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A9%A0%E6%9F%B3"}, {"title": "詠螢", "author": "虞世南", "period": "唐", "form": "詩", "theme": "田園幽居", "mood": "ethereal", "lines": ["的歷流光小，飄颻弱翅輕。", "恐畏無人識，獨自暗中明。"], "quote": ["的歷流光小，飄颻弱翅輕。", "恐畏無人識，獨自暗中明。"], "intro": "", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A9%A0%E8%9E%A2"}, {"title": "尋隱者不遇", "author": "賈島", "period": "唐", "form": "詩", "theme": "田園幽居", "mood": "majestic_peaks", "lines": ["松下問童子，言師採藥去。只在此山中，雲深不知處。"], "quote": ["松下問童子，言師採藥去。只在此山中，雲深不知處。"], "intro": "《尋隱者不遇》選自《全唐詩》卷五百七十四，一作「孫革訪羊尊師詩」，寫入山訪尋一位隱士不遇的情景。全詩只截取了訪而不遇時與看門童子對答的一個片段，簡單數語，隱者的飄逸高潔與訪者的悵惘之情躍然紙上。語言真率樸素。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B0%8B%E9%9A%B1%E8%80%85%E4%B8%8D%E9%81%87"}, {"title": "月夜（更深月色半人家）", "author": "劉方平", "period": "唐", "form": "詩", "theme": "歲時雪月", "mood": "spring_breeze", "lines": ["更深月色半人家，北斗闌干南斗斜。", "今夜偏知春氣暖，蟲聲新透綠窗紗。"], "quote": ["更深月色半人家，北斗闌干南斗斜。", "今夜偏知春氣暖，蟲聲新透綠窗紗。"], "intro": "劉方平生活在唐代開元、天寶年間。他一生沒有出仕做官，過着隱居的生活。他的詩多以詠物寫景為主。本篇選自《全唐詩》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9C%88%E5%A4%9C%EF%BC%88%E6%9B%B4%E6%B7%B1%E6%9C%88%E8%89%B2%E5%8D%8A%E4%BA%BA%E5%AE%B6%EF%BC%89"}, {"title": "石頭城", "author": "劉禹錫", "period": "唐", "form": "詩", "theme": "詠史哲思", "mood": "vast_river", "lines": ["山圍故國周遭在，潮打空城寂寞回。", "淮水東邊舊時月，夜深還過女牆來。"], "quote": ["山圍故國周遭在，潮打空城寂寞回。", "淮水東邊舊時月，夜深還過女牆來。"], "intro": "這是劉禹錫懷古組詩〈金陵五題〉中的第一首。寫於唐敬宗寶曆二年（826），詩人任和州刺史時期。石頭城，故址在今南京清涼山一帶。戰國時是楚國的金陵城，三國時孫權重建，並改名為石頭城。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%9F%B3%E9%A0%AD%E5%9F%8E"}, {"title": "竹枝詞（其一）", "author": "劉禹錫", "period": "唐", "form": "詩", "theme": "田園幽居", "mood": "vast_river", "lines": ["楊柳青青江水平，聞郎江上唱歌聲。", "東邊日出西邊雨，道是無晴卻有晴。"], "quote": ["楊柳青青江水平，聞郎江上唱歌聲。", "東邊日出西邊雨，道是無晴卻有晴。"], "intro": "劉禹錫《竹枝詞》選自《全唐詩》卷三百六十五。原題共二首，本課選錄第一首。《竹枝詞》是古代四川東部的民歌，人們喜以連手踏地為歌演出。唐穆宗長慶二年（八二二），劉禹錫調任夔州（治所在今四川奉節）刺史，深愛當地民歌，遂按其調而另作新詩，亦稱《竹枝", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%AB%B9%E6%9E%9D%E8%A9%9E%EF%BC%88%E5%85%B6%E4%B8%80%EF%BC%89"}, {"title": "陋室銘", "author": "劉禹錫", "period": "唐", "form": "文", "theme": "田園幽居", "mood": "vast_river", "lines": ["山不在高，有仙則名；水不在深，有龍則靈。斯是陋室，惟吾德馨。苔痕上階綠，草色入簾青。談笑有鴻儒，往來無白丁。", "可以調素琴、閱金經。無絲竹之亂耳，無案牘之勞形。南陽諸葛廬，西蜀子雲亭。孔子云︰「何陋之有？」"], "quote": ["山不在高，有仙則名；水不在深，有龍則靈。斯是陋室，惟吾德馨。苔痕上階綠，草色入簾青。談笑有鴻儒，往來無白丁。", "可以調素琴、閱金經。無絲竹之亂耳，無案牘之勞形。南陽諸葛廬，西蜀子雲亭。孔子云︰「何陋之有？」"], "intro": "本篇選自《全唐文》卷六百八。銘是古代文體的一種，鏤刻在金屬器物或碑石上面，主要用來頌揚祖德，昭明鑒誡，兼有自勉之意。《陋室銘》是作者描寫自己所居住的簡陋房子，藉此表達不同流俗的志趣和坦蕩樂天的襟懷。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%99%8B%E5%AE%A4%E9%8A%98"}, {"title": "烏衣巷", "author": "劉禹錫", "period": "唐", "form": "詩", "theme": "春水花鳥", "mood": "autumn_sunset", "lines": ["朱雀橋邊野草花，烏衣巷口夕陽斜。", "舊時王謝堂前燕，飛入尋常百姓家。"], "quote": ["朱雀橋邊野草花，烏衣巷口夕陽斜。", "舊時王謝堂前燕，飛入尋常百姓家。"], "intro": "《烏衣巷》選自《全唐詩》卷三百六十五。烏衣巷，在今南京東南部秦淮河南岸。三國時，吳國的軍隊曾在這裡駐防，士兵穿烏衣，故而得名。東晉時，王導、謝安等豪門世族曾在這裏居住。這是一首詠史詩，為作者《金陵五題》的第二首。就烏衣巷王謝門第衰敗的遺蹟，", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%83%8F%E8%A1%A3%E5%B7%B7"}, {"title": "在獄詠蟬", "author": "駱賓王", "period": "唐", "form": "詩", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["西陸蟬聲唱，南冠客思深。", "不堪玄鬢影，來對白頭吟。", "露重飛難進。風多響易沉。", "無人信高潔，誰為表予心？"], "quote": ["西陸蟬聲唱，南冠客思深。", "不堪玄鬢影，來對白頭吟。", "露重飛難進。風多響易沉。", "無人信高潔，誰為表予心？"], "intro": "唐高宗儀鳳三年（678年），駱賓王為侍御史時，「數上書言天下大計，後曌怒，誣以法，逮繫獄中。」（胡應麟《補唐書駱侍御傳》）這年秋天，詩人在獄中寫下了這首詩。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%9C%A8%E7%8D%84%E8%A9%A0%E8%9F%AC"}, {"title": "詠鵝", "author": "駱賓王", "period": "唐", "form": "詩", "theme": "春水花鳥", "mood": "vast_river", "lines": ["鵝鵝鵝，", "曲項向天歌。", "白毛浮綠水，", "紅掌撥清波。"], "quote": ["鵝鵝鵝，", "曲項向天歌。", "白毛浮綠水，", "紅掌撥清波。"], "intro": "", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A9%A0%E9%B5%9D"}, {"title": "左遷至藍關示姪孫湘", "author": "韓愈", "period": "唐", "form": "詩", "theme": "邊塞豪放", "mood": "snow_winter", "lines": ["一封朝奏九重天，夕貶潮陽路八千。", "欲為聖朝除弊事，肯將衰朽惜殘年！", "雲橫秦嶺家何在？雪擁藍關馬不前。", "知汝遠來應有意，好收吾骨瘴江邊。"], "quote": ["一封朝奏九重天，夕貶潮陽路八千。", "欲為聖朝除弊事，肯將衰朽惜殘年！", "雲橫秦嶺家何在？雪擁藍關馬不前。", "知汝遠來應有意，好收吾骨瘴江邊。"], "intro": "《左遷至藍關示姪孫湘》選自《全唐詩》卷三百四十四。左遷，貶官，古時尊右卑左。藍關，一名藍田關，在今陝西商縣西北。示，長輩把事情告訴晚輩叫示。元和十四年（八一九）正月，唐憲宗派遣使者迎鳳翔法門寺護國真身塔內釋迦文佛的一節指骨進宮，韓愈時為刑部", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B7%A6%E9%81%B7%E8%87%B3%E8%97%8D%E9%97%9C%E7%A4%BA%E5%A7%AA%E5%AD%AB%E6%B9%98"}, {"title": "初春小雨", "author": "韓愈", "period": "唐", "form": "詩", "theme": "春水花鳥", "mood": "vast_river", "lines": ["天街小雨潤如酥，草色遙看近卻無。", "最是一年春好處，絕勝煙柳滿皇都。"], "quote": ["天街小雨潤如酥，草色遙看近卻無。", "最是一年春好處，絕勝煙柳滿皇都。"], "intro": "本詩題目原為《早春呈水部張十八員外》。「張十八員外」，即張籍，他曾任水部員外郎，「十八」為兄弟間的排行。張籍是韓愈的好朋友，韓愈寫了不少詩歌給他。此詩原有兩首，這是第一首。這首詩寫於唐穆宗長慶三年（公元823），是作者逝世前一年的作品；可以", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%88%9D%E6%98%A5%E5%B0%8F%E9%9B%A8"}, {"title": "柳子厚墓誌銘", "author": "韓愈", "period": "唐", "form": "文", "theme": "春水花鳥", "mood": "vast_river", "lines": ["子厚，諱宗元。七世祖慶，為拓跋魏侍中，封濟陰公。曾伯祖奭，為唐宰相，與褚遂良、韓瑗俱得罪武后，死高宗朝。皇考諱鎮，以事母棄太常博士，求為縣令江南。其後以不能媚權貴，失御史；權貴人死，乃復拜侍御史，號為剛直。所與遊，皆當世名人。", "子厚少精敏，無不通達。逮其父時，雖少年，已自成人，能取進士第，嶄然見頭角；眾謂柳氏有子矣。其後以博學宏詞，授集賢殿正字。儁傑廉悍，議論證據今古，出入經史百子。踔厲風發，率常屈其座人，名聲大振，一時皆慕與之交。諸公要人爭欲令出我門下，交口薦譽之。", "貞元十九年，由藍田尉拜監察御史。順宗即位，拜禮部員外郎。遇用事者得罪，例出為刺史；未至，又例貶永州司馬。居閒，益自刻苦，務記覽為詞章，汎濫停蓄，為深博無涯涘，而自肆於山水間。", "元和中，嘗例召至京師，又偕出為刺史，而子厚得柳州。既至，歎曰︰「是豈不足為政邪？」因其土俗，為設教禁，州人順賴。其俗以男女質錢，約不時贖，子本相侔，則沒為奴婢。子厚與設方計，悉令贖歸。其尤貧力不能者，令書其傭，足相當，則使歸其質。觀察使下其法於他州，比一歲，免而歸者且千人。衡湘以南為進士者，皆以子厚為師；其經承子厚口講指畫為文詞者，悉有法度可觀。", "其召至京師而復為刺史也，中山劉夢得禹錫亦在遣中，當詣播州。子厚泣曰︰「播州，非人所居，而夢得親在堂。吾不忍夢得之窮，無辭以白其大人；且萬無母子俱往理。」請於朝，將拜疏，願以柳易播，雖重得罪，死不恨。遇有以夢得事白上者，夢得於是改刺連州。嗚呼！士窮乃見節義。今夫平居里巷相慕悅，酒食遊戲相徵逐，詡詡強笑語以相取下，握手出於肺肝相示，指天日涕泣，誓生死不相背負，真若可信。一旦臨小利害，僅如毛髮比，反眼若不相識；落陷穽不一引手救，反擠之又下石焉者，皆是也。此宜禽獸夷狄所不忍為，而其人自視以為得計。聞子厚之風，亦可以少媿矣！", "子厚前時少年，勇於為人，不自貴重顧藉，謂功業可立就，故坐廢退；既退，又無相知有氣力得位者推挽，故卒死於窮裔。材不為世用，道不行於時也。使子厚在臺省時，自持其身已能如司馬刺史時，亦自不斥；斥時，有人力能舉之，且必復用不窮。然子厚斥不久，窮不極，雖有出於人，其文學辭章，必不能自力以致必傳於後，如今無疑也；雖使子厚得所願，為將相於一時，以彼易此，孰得孰失，必有能辨之者。", "子厚以元和十四年十一月八日卒，年四十七。以十五年七月十日，歸葬萬年先人墓側。子厚有子男二人，長曰周六，始四歲；季曰周七，子厚卒，乃生。女子二人，皆幼。其得歸葬也，費皆出觀察使河東裴君行立。行立有節槩，重然諾；與子厚結交，子厚亦為之盡，竟賴其力。葬子厚於萬年之墓者，舅弟盧遵。遵，涿人，性謹慎，學問不厭；自子厚之斥，遵從而家焉，逮其死不去；既往葬子厚，又將經紀其家，庶幾有始終者。", "銘曰︰「是惟子厚之室，既固既安，以利其嗣人。」"], "quote": ["子厚，諱宗元。七世祖慶，為拓跋魏侍中，封濟陰公。曾伯祖奭，為唐宰相，與褚遂良、韓瑗俱得罪武后，死高宗朝。皇考諱鎮，以事母棄太常博士，求為縣令江南。其後以不能媚權貴，失御史；權貴人死，乃復拜侍御史，號為剛直。所與遊，皆當世名人。", "子厚少精敏，無不通達。逮其父時，雖少年，已自成人，能取進士第，嶄然見頭角；眾謂柳氏有子矣。其後以博學宏詞，授集賢殿正字。儁傑廉悍，議論證據今古，出入經史百子。踔厲風發，率常屈其座人，名聲大振，一時皆慕與之交。諸公要人爭欲令出我門下，交口薦譽之。", "貞元十九年，由藍田尉拜監察御史。順宗即位，拜禮部員外郎。遇用事者得罪，例出為刺史；未至，又例貶永州司馬。居閒，益自刻苦，務記覽為詞章，汎濫停蓄，為深博無涯涘，而自肆於山水間。", "元和中，嘗例召至京師，又偕出為刺史，而子厚得柳州。既至，歎曰︰「是豈不足為政邪？」因其土俗，為設教禁，州人順賴。其俗以男女質錢，約不時贖，子本相侔，則沒為奴婢。子厚與設方計，悉令贖歸。其尤貧力不能者，令書其傭，足相當，則使歸其質。觀察使下其法於他州，比一歲，免而歸者且千人。衡湘以南為進士者，皆以子厚為師；其經承子厚口講指畫為文詞者，悉有法度可觀。"], "intro": "柳子厚，是韓愈的好朋友，他們都是當時文壇上的健將。柳一生窮困，死後蕭條，韓愈非常同情，自動地為他寫了這篇墓誌銘。他的生平事蹟，詳見正文。 墓誌銘是刻在墓地裏石碑上的文章，用以表揚或紀念死去的人。有的樹在墳前，有的埋在地下，都是預備萬一後世陵", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9F%B3%E5%AD%90%E5%8E%9A%E5%A2%93%E8%AA%8C%E9%8A%98"}, {"title": "送孟東野序", "author": "韓愈", "period": "唐", "form": "文", "theme": "送別行旅", "mood": "snow_winter", "lines": ["大凡物不得其平則鳴。草木之無聲，風撓之鳴。水之無聲，風蕩之鳴。其躍也，或激之；其趨也，或梗之；其沸也，或炙之。", "金石之無聲，或擊之鳴。人之於言也亦然，有不得已者而后言。謌也有思，其哭也有懷。凡出乎口而為聲者，其皆有弗平者乎！", "樂也者，鬱於中而泄於外者也，擇其善鳴者而假之鳴。金、石、絲、竹、匏、土、革、木八者，物之善鳴者也。維天之於時也亦然，擇其善鳴者而假之鳴。是故以鳥鳴春，以雷鳴夏，以蟲鳴秋，以風鳴冬。", "四時之相推敓，其必有不得其平者乎？其於人也亦然，人聲之精者為言，文辭之於言，又其精也，尤擇其善鳴者而假之鳴。", "其在唐虞，咎陶禹其善鳴者也，而假以鳴。夔弗能以文辭鳴，又自假於《韶》以鳴。夏之時，五子以其歌鳴。伊尹鳴殷，周公鳴周。凡載於詩書六藝，皆鳴之善者也。周之衰，孔子之徒鳴之，其聲大而遠。", "傳曰︰「天將以夫子為木鐸。」其弗信矣乎？其末也，莊周以其荒唐之辭鳴。楚，大國也，其亡也，以屈原鳴。臧孫辰、孟軻、荀卿，以道鳴者也。楊朱、墨翟、管夷吾、晏嬰、老聃、申不害、韓非、昚到、田駢、鄒衍、尸佼、孫武、張儀、蘇秦之屬，皆以其術鳴。", "秦之興，李斯鳴之。漢之時，司馬遷、相如、揚雄，最其善鳴者也。其下魏晉氏，鳴者不及於古，然亦未嘗絕也。就其善者，其聲清以浮，其節數以急，其辭淫以哀，其志弛以肆；其為言也，亂雜而無章。將天醜其德莫之顧邪？何為乎不鳴其善鳴者也？", "唐之有天下，陳子昂、蘇源明、元結、李白、杜甫、李觀，皆以其所能鳴。其存而在下者，孟郊東野始以其詩鳴。其高出魏晉，不懈而及於古；其他浸乎漢氏矣。從吾遊者，李翱、張籍其尤也。三子者之鳴信善矣。", "抑不知天將和其聲而使鳴國家之盛邪？抑將窮餓其身、思愁其心腸而使自鳴其不幸邪？三子者之命則懸乎天矣。其在上也奚以喜？其在下也奚以悲？東野之役於江南也，有若不釋然者，故吾道其命於天者以解之。"], "quote": ["大凡物不得其平則鳴。草木之無聲，風撓之鳴。水之無聲，風蕩之鳴。其躍也，或激之；其趨也，或梗之；其沸也，或炙之。", "金石之無聲，或擊之鳴。人之於言也亦然，有不得已者而后言。謌也有思，其哭也有懷。凡出乎口而為聲者，其皆有弗平者乎！", "樂也者，鬱於中而泄於外者也，擇其善鳴者而假之鳴。金、石、絲、竹、匏、土、革、木八者，物之善鳴者也。維天之於時也亦然，擇其善鳴者而假之鳴。是故以鳥鳴春，以雷鳴夏，以蟲鳴秋，以風鳴冬。", "四時之相推敓，其必有不得其平者乎？其於人也亦然，人聲之精者為言，文辭之於言，又其精也，尤擇其善鳴者而假之鳴。"], "intro": "本篇選自《韓昌黎文集校注》卷四。孟東野，即唐代詩人孟郊，東野是他的字，湖州武康（今浙江武康）人。年青時屢試不第，直至貞元十二年（七九六），四十六歲才得中進士，其後仕途也不順利。孟郊文才毅力都很超卓，寫出了不少名聞遐邇的詩文，為韓愈所激賞，稱", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%80%81%E5%AD%9F%E6%9D%B1%E9%87%8E%E5%BA%8F"}, {"title": "師說", "author": "韓愈", "period": "唐", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["古之學者必有師。師者，所以傳道、受業、解惑也。人非生而知之者，孰能無惑？惑而不從師，其為惑也終不解矣。", "生乎吾前．其聞道也，固先乎吾，吾從而師之；生乎吾後，其聞道也，亦先乎吾，吾從而師之。吾師道也，夫庸知其年之先後生於吾乎？是故無貴、無賤、無長、無少，道之所存，師之所存也。", "嗟乎！師道之不傳也久矣！欲人之無惑也難矣！古之聖人，其出人也遠矣，猶且從師而問焉；今之眾人，其下聖人也亦遠矣，而恥學於師；是故聖益聖，愚益愚，聖人之所以為聖，愚人之所以為愚，其皆出於此乎？", "愛其子，擇師而教之，於其身也則恥師焉，惑矣！彼童子之師，授之書而習其句讀者，非吾所謂傳其道、解其惑者也。句讀之不知，惑之不解，或師焉，或不焉，小學而大遺，吾未見其明也。", "巫、醫、樂師、百工之人，不恥相師；士大夫之族，曰師、曰弟子云者，則羣聚而笑之。問之，則曰︰「彼與彼年相若也，道相似也」。位卑則足羞，官盛則近諛。", "嗚呼！師道之不復，可知矣。巫、醫、樂師、百工之人，君子不齒，今其智乃反不能及，其可怪也歟！", "聖人無常師，孔子師郯子、萇弘、師襄、老聃。郯子之徒，其賢不及孔子。孔子曰︰「三人行，則必有我師」。是故弟子不必不如師，師不必賢於弟子；聞道有先後，術業有專攻，如是而已。", "李氏子蟠，年十七，好古文，六藝經傳，皆通習之；不拘於時，學於余。余嘉其能行古道，作「師說」以貽之。"], "quote": ["古之學者必有師。師者，所以傳道、受業、解惑也。人非生而知之者，孰能無惑？惑而不從師，其為惑也終不解矣。", "生乎吾前．其聞道也，固先乎吾，吾從而師之；生乎吾後，其聞道也，亦先乎吾，吾從而師之。吾師道也，夫庸知其年之先後生於吾乎？是故無貴、無賤、無長、無少，道之所存，師之所存也。", "嗟乎！師道之不傳也久矣！欲人之無惑也難矣！古之聖人，其出人也遠矣，猶且從師而問焉；今之眾人，其下聖人也亦遠矣，而恥學於師；是故聖益聖，愚益愚，聖人之所以為聖，愚人之所以為愚，其皆出於此乎？", "愛其子，擇師而教之，於其身也則恥師焉，惑矣！彼童子之師，授之書而習其句讀者，非吾所謂傳其道、解其惑者也。句讀之不知，惑之不解，或師焉，或不焉，小學而大遺，吾未見其明也。"], "intro": "作者在當時，有不少的人向他學古文，他也好為人師，所以他最講究師道。本文是他慨歎當時師道之不講，提倡學人必須從師；並特為贈給他的愛徒李蟠而作。選自作者文集。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B8%AB%E8%AA%AA"}, {"title": "祭十二郎文", "author": "韓愈", "period": "唐", "form": "文", "theme": "送別行旅", "mood": "autumn_sunset", "lines": ["年月日，季父愈，聞汝喪之七日，乃能銜哀致誠，使建中遠具時羞之奠，告汝十二郎之靈︰", "嗚呼！吾少孤，及長，不省所怙，惟兄嫂是依。中年，兄歿南方，吾與汝俱幼，從嫂歸葬河陽，既又與汝就食江南。零丁孤苦，未嘗一日相離也。吾上有三兄，皆不幸早世。承先人後者，在孫惟汝，在子惟吾；兩世一身，形單影隻。嫂嘗撫汝指吾而言曰︰「韓氏兩世，惟此而已！」汝時尤小，當不復記憶；吾時雖能記憶，亦未知其言之悲也。", "吾年十九，始來京城。其後四年，而歸視汝，又四年，吾往河陽省墳墓，遇汝從嫂喪來葬。又二年，吾佐董丞相於汴州，汝來省吾；止一歲，請歸取其孥。明年，丞相薨，吾去汴州，汝不果來。是年，吾佐戎徐州，使取汝者始行，吾又罷去，汝又不果來。吾念汝從於東，東亦客也，不可以久。圖久遠者，莫如西歸，將成家而致汝。嗚呼，孰謂汝遽去吾而歿乎！吾與汝俱少年，以為雖暫相別，終當久相與處，故捨汝而旅食京師，以求斗斛之祿。誠知其如此，雖萬乘之公相，吾不以一日輟汝而就也！", "去年，孟東野往，吾書與汝曰︰「吾年未四十，而視茫茫，而髮蒼蒼，而齒牙動搖。念諸父與諸兄，皆康彊而早世，如吾之衰者，其能久存乎？吾不可去，汝不肯來，恐旦暮死，而汝抱無涯之戚也。」孰謂少者歿而長者存，彊者夭而病者全乎！嗚呼！其信然邪？其夢邪？其傳之非其真邪？信也，吾兄之盛德而夭其嗣乎？汝之純明而不克蒙其澤乎？少者彊者而夭歿，長者衰者而存全乎？未可以為信也。夢也，傳之非其真也，東野之書，耿蘭之報，何為而在吾側也？嗚呼，其信然矣！吾兄之盛德而夭其嗣矣！汝之純明宜業其家者，不克蒙其澤矣！所謂天者誠難測，而神者誠難明矣！所謂理者不可推，而壽者不可知矣！雖然，吾自今年來，蒼蒼者或化而為白矣，動搖者或脫而落矣；毛血日益衰，志氣日益微，幾何不從汝而死也！死而有知，其幾何離；其無知，悲不幾時，而不悲者無窮期矣！汝之子始十歲，吾之子始五歲，少而彊者不可保，如此孩提者，又可冀其成立邪？嗚呼哀哉！嗚呼哀哉！", "汝去年書云︰「比得軟腳病，往往而劇。」吾曰︰「是疾也，江南之人，常常有之。」未始以為憂也。嗚呼！其竟以此而殞其生乎？抑別有疾而至斯乎？汝之書，六月十七日也；東野云，汝歿以六月二日；耿蘭之報無月日。蓋東野之使者，不知問家人以月日；如耿蘭之報，不知當言月日。東野與吾書，乃問使者；使者妄稱以應之耳。其然乎，其不然乎？", "今吾使建中祭汝，弔汝之孤，與汝之乳母。彼有食可守以待終喪，則待終喪而取以來；如不能守以終喪，則遂取以來；其餘奴婢，並令守汝喪。吾力能改葬，終葬汝於先人之兆，然後惟其所願。", "嗚呼！汝病吾不知時，汝歿吾不知日；生不能相養以共居，歿不得撫汝以盡哀；斂不憑其棺，窆不臨其穴。吾行負神明，而使汝夭；不孝、不慈，而不得與汝相養以生，相守以死。一在天之涯，一在地之角；生而影不與吾形相依；死而魂不與吾夢相接。吾實為之，其又何尤！彼蒼者天，曷其有極！自今以往，吾其無意於人世矣！當求數頃之田於伊、潁之上，以待餘年，教吾子與汝子，幸其成；長吾女與汝女，待其嫁，如此而已！", "嗚呼！言有窮而情不可終，汝其知也邪？其不知也邪？嗚呼哀哉！尚饗！"], "quote": ["年月日，季父愈，聞汝喪之七日，乃能銜哀致誠，使建中遠具時羞之奠，告汝十二郎之靈︰", "嗚呼！吾少孤，及長，不省所怙，惟兄嫂是依。中年，兄歿南方，吾與汝俱幼，從嫂歸葬河陽，既又與汝就食江南。零丁孤苦，未嘗一日相離也。吾上有三兄，皆不幸早世。承先人後者，在孫惟汝，在子惟吾；兩世一身，形單影隻。嫂嘗撫汝指吾而言曰︰「韓氏兩世，惟此而已！」汝時尤小，當不復記憶；吾時雖能記憶，亦未知其言之悲也。", "吾年十九，始來京城。其後四年，而歸視汝，又四年，吾往河陽省墳墓，遇汝從嫂喪來葬。又二年，吾佐董丞相於汴州，汝來省吾；止一歲，請歸取其孥。明年，丞相薨，吾去汴州，汝不果來。是年，吾佐戎徐州，使取汝者始行，吾又罷去，汝又不果來。吾念汝從於東，東亦客也，不可以久。圖久遠者，莫如西歸，將成家而致汝。嗚呼，孰謂汝遽去吾而歿乎！吾與汝俱少年，以為雖暫相別，終當久相與處，故捨汝而旅食京師，以求斗斛之祿。誠知其如此，雖萬乘之公相，吾不以一日輟汝而就也！", "去年，孟東野往，吾書與汝曰︰「吾年未四十，而視茫茫，而髮蒼蒼，而齒牙動搖。念諸父與諸兄，皆康彊而早世，如吾之衰者，其能久存乎？吾不可去，汝不肯來，恐旦暮死，而汝抱無涯之戚也。」孰謂少者歿而長者存，彊者夭而病者全乎！嗚呼！其信然邪？其夢邪？其傳之非其真邪？信也，吾兄之盛德而夭其嗣乎？汝之純明而不克蒙其澤乎？少者彊者而夭歿，長者衰者而存全乎？未可以為信也。夢也，傳之非其真也，東野之書，耿蘭之報，何為而在吾側也？嗚呼，其信然矣！吾兄之盛德而夭其嗣矣！汝之純明宜業其家者，不克蒙其澤矣！所謂天者誠難測，而神者誠難明矣！所謂理者不可推，而壽者不可知矣！雖然，吾自今年來，蒼蒼者或化而為白矣，動搖者或脫而落矣；毛血日益衰，志氣日益微，幾何不從汝而死也！死而有知，其幾何離；其無知，悲不幾時，而不悲者無窮期矣！汝之子始十歲，吾之子始五歲，少而彊者不可保，如此孩提者，又可冀其成立邪？嗚呼哀哉！嗚呼哀哉！"], "intro": "十二郎，是作者的姪兒，名老成。作者有三個哥哥：會、介、俞；會無子，介有二子：長曰百川，次曰老成。百川早死，老成過繼給會為嗣。作者少孤，即賴兄會及嫂鄭夫人撫養成人，自幼及長，與十二郎在一起，非常親愛，唐德宗貞元十九年（公元八零三），作者得十二", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%A5%AD%E5%8D%81%E4%BA%8C%E9%83%8E%E6%96%87"}, {"title": "答李翊書", "author": "韓愈", "period": "唐", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["六月二十六日，愈白李生足下︰", "生之書辭甚高，而其問何下而恭也！能如是，誰不欲告生以其道？道德之歸也有日矣，況其外之文乎！抑愈所謂望孔子之門牆而不入於其宮者，焉足以知是且非邪？雖然，不可不為生言之。", "生所謂立言者，是也；生所為者與所期者，甚似而幾矣。抑不知生之志，蘄勝於人而取於人邪？將蘄至於古之立言者邪？蘄勝於人而取於人，則固勝於人而可取於人矣；將蘄至於古之立言者，則無望其速成，無誘於勢利；養其根而竢其實，加其膏而希其光。", "根之茂者其實遂，膏之沃者其光曄；仁義之人，其言藹如也。", "抑又有難者︰愈之所為，不自知其至猶未也。雖然，學之二十餘年矣。始者，非三代兩漢之書不敢觀，非聖人之志不敢存；處若忘，行若遺，儼乎其若思，茫乎其若迷。當其取於心而注於手也，惟陳言之務去，戛戛乎其難哉！其觀於人，不知其非笑之為非笑也。", "如是者亦有年，猶不改。然後識古書之正偽，與雖正而不至焉者，昭昭然白黑分矣；而務去之，乃徐有得也。當其取於心而注於手也，汨汨然來矣。其觀於人也，笑之，則以為喜；譽之，則以為憂，以其猶有人之說者存也。", "如是者亦有年，然後浩乎其沛然矣。吾又懼其雜也，迎而拒之，平心而察之；其皆醇也，然後肆焉。雖然，不可以不養也。行之乎仁義之途，游之乎詩書之源，無迷其途，無絕其源，終吾身而已矣。", "氣，水也；言，浮物也。水大，而物之浮者大小畢浮。氣之與言猶是也。氣盛，則言之短長與聲之高下者皆宜。雖如是，其敢自謂幾於成乎？雖幾於成，其用於人也，奚敢焉？", "雖然，待用於人者，其肖於器邪？用與舍屬諸人。君子則不然︰處心有道，行己有方；用則施諸人，舍則傳諸其徒，垂諸文而為後世法；如是者，其亦足樂乎，其無足樂也？有志乎古者希矣！志乎古，必遺乎今，吾誠樂而悲之。", "亟稱其人，所以勸之，非敢褎其可褎，而貶其可貶也。問於愈者多矣，念生之言不志乎利，聊相為言之。愈白。"], "quote": ["六月二十六日，愈白李生足下︰", "生之書辭甚高，而其問何下而恭也！能如是，誰不欲告生以其道？道德之歸也有日矣，況其外之文乎！抑愈所謂望孔子之門牆而不入於其宮者，焉足以知是且非邪？雖然，不可不為生言之。", "生所謂立言者，是也；生所為者與所期者，甚似而幾矣。抑不知生之志，蘄勝於人而取於人邪？將蘄至於古之立言者邪？蘄勝於人而取於人，則固勝於人而可取於人矣；將蘄至於古之立言者，則無望其速成，無誘於勢利；養其根而竢其實，加其膏而希其光。", "根之茂者其實遂，膏之沃者其光曄；仁義之人，其言藹如也。"], "intro": "李翊是韓愈的朋友，一說是他的弟子。就這篇文章的稱謂和語氣來看，大概李翊是韓愈的一個後輩。據《韓昌黎集》在本篇題下註云：「貞元十八年，陸傪佐主司權德輿於禮部，公以李翊薦於傪，用是其年登第。」因此推斷這篇文章作於貞元十七年（公元八〇一）。韓愈在", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%AD%94%E6%9D%8E%E7%BF%8A%E6%9B%B8"}, {"title": "雜說四", "author": "韓愈", "period": "唐", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["世有伯樂，然後有千里馬。千里馬常有，而伯樂不常有，故雖有名馬，祇辱於奴隸人之手，駢死於槽櫪之間，不以千里稱也。", "馬之千里者，一食或盡粟一石。食馬者，不知其能千里而食也。是馬也，雖有千里之能，食不飽，力不足，才美不外見，且欲與常馬等不可得，安求其能千里也？", "策之不以其道，食之不能盡其材，鳴之而不能通其意，執策而臨之，曰︰「天下無馬。」嗚呼！其真無馬邪？其真不知馬也！"], "quote": ["世有伯樂，然後有千里馬。千里馬常有，而伯樂不常有，故雖有名馬，祇辱於奴隸人之手，駢死於槽櫪之間，不以千里稱也。", "馬之千里者，一食或盡粟一石。食馬者，不知其能千里而食也。是馬也，雖有千里之能，食不飽，力不足，才美不外見，且欲與常馬等不可得，安求其能千里也？", "策之不以其道，食之不能盡其材，鳴之而不能通其意，執策而臨之，曰︰「天下無馬。」嗚呼！其真無馬邪？其真不知馬也！"], "intro": "「雜說」是文藝性較強的短篇論說文，不拘一格，類似現代的隨筆、雜感，以至報刊上的專欄雜文。韓愈有《雜說》四篇，是一組短論，皆托物寄意之作，這裏選的是第四篇。因所寫的是馬，所以後世也有把題目改為《馬說》的。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%9B%9C%E8%AA%AA%E5%9B%9B"}, {"title": "諫太宗十思疏", "author": "魏徵", "period": "唐", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["臣聞求木之長者，必固其根本；欲流之遠者，必浚其泉源；思國之安者，必積其德義。源不深，而豈望流之遠？根不固，而何求木之長？德不厚，而思國之治，雖在下愚，知其不可，而況於明哲乎？人君當神器之重，居域中之大，將崇極天之峻，永保無疆之休。不念於居安思危，戒奢以儉，德不處其厚，情不勝其欲；斯亦伐根以求木茂，塞源而欲流長者也。", "凡百元首，承天景命，莫不殷憂而道著，功成而德衰，有善始者實繁，能克終者蓋寡。豈其取之易而守之難乎？昔取之而有餘，今守之而不足，何也？夫在殷憂，必竭誠以待下；既得志，則縱情以傲物。竭誠，則胡越為一體；傲物，則骨肉為行路。雖董之以嚴刑，振之以威怒；終苟免而不懷仁，貌恭而不心服。怨不在大，可畏惟人。載舟覆舟，所宜深慎！奔車朽索，其可忽乎？", "君人者，誠能見可欲，則思知足以自戒，將有作，則思知止以安人，念高危，則思謙沖而自牧，懼滿盈，則思江海下百川，樂盤遊，則思三驅以為度；恐懈怠，則思慎始而敬終；慮壅蔽，則思虛心以納下；想讒邪，則思正身以黜惡；恩所加，則思無因喜以謬賞；罰所及，則思無因怒而濫刑；總此十思，弘茲九德，簡能而任之，擇善而從之；則智者盡其謀，勇者竭其力，仁者播其惠，信者效其忠；文武爭馳，君臣無事，可以盡豫遊之樂，可以養松喬之壽，鳴琴垂拱，不言而化；何必勞神苦思，代下司職，役聰明之耳目，虧無為之大道哉！"], "quote": ["臣聞求木之長者，必固其根本；欲流之遠者，必浚其泉源；思國之安者，必積其德義。源不深，而豈望流之遠？根不固，而何求木之長？德不厚，而思國之治，雖在下愚，知其不可，而況於明哲乎？人君當神器之重，居域中之大，將崇極天之峻，永保無疆之休。不念於居安思危，戒奢以儉，德不處其厚，情不勝其欲；斯亦伐根以求木茂，塞源而欲流長者也。", "凡百元首，承天景命，莫不殷憂而道著，功成而德衰，有善始者實繁，能克終者蓋寡。豈其取之易而守之難乎？昔取之而有餘，今守之而不足，何也？夫在殷憂，必竭誠以待下；既得志，則縱情以傲物。竭誠，則胡越為一體；傲物，則骨肉為行路。雖董之以嚴刑，振之以威怒；終苟免而不懷仁，貌恭而不心服。怨不在大，可畏惟人。載舟覆舟，所宜深慎！奔車朽索，其可忽乎？", "君人者，誠能見可欲，則思知足以自戒，將有作，則思知止以安人，念高危，則思謙沖而自牧，懼滿盈，則思江海下百川，樂盤遊，則思三驅以為度；恐懈怠，則思慎始而敬終；慮壅蔽，則思虛心以納下；想讒邪，則思正身以黜惡；恩所加，則思無因喜以謬賞；罰所及，則思無因怒而濫刑；總此十思，弘茲九德，簡能而任之，擇善而從之；則智者盡其謀，勇者竭其力，仁者播其惠，信者效其忠；文武爭馳，君臣無事，可以盡豫遊之樂，可以養松喬之壽，鳴琴垂拱，不言而化；何必勞神苦思，代下司職，役聰明之耳目，虧無為之大道哉！"], "intro": "《舊唐書・魏徵傳》載有魏徵上唐太宗四篇奏疏，史臣贊稱「可為萬代王者法」；本文即第二篇。因篇中列有十點，請太宗思考，作為修身治國之準則，故題為「十思」。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%AB%AB%E5%A4%AA%E5%AE%97%E5%8D%81%E6%80%9D%E7%96%8F"}, {"title": "蜂", "author": "羅隱", "period": "唐", "form": "詩", "theme": "春水花鳥", "mood": "majestic_peaks", "lines": ["不論平地與山尖，", "無限風光盡被占。", "採得百花成蜜後，", "為誰辛苦為誰甜！"], "quote": ["不論平地與山尖，", "無限風光盡被占。", "採得百花成蜜後，", "為誰辛苦為誰甜！"], "intro": "", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%9C%82"}, {"title": "相見歡（無言獨上西樓）", "author": "李煜", "period": "五代十國", "form": "詞", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["無言獨上西樓，月如鈎，寂寞梧桐深院鎖清秋。", "翦不斷，理還亂，是離愁。別是一般滋味在心頭。"], "quote": ["無言獨上西樓，月如鈎，寂寞梧桐深院鎖清秋。", "翦不斷，理還亂，是離愁。別是一般滋味在心頭。"], "intro": "《相見歡》（無言獨上西樓）選自《評註南唐二主詞》。《相見歡》為詞牌名，是李後主亡國後之作。此詞描寫作者在一個冷清的秋夜，獨自登樓，舉頭見新月如鈎，低頭見桐陰深鎖，嘗盡離愁別緒之苦。悱惻悽婉，動人心弦。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%9B%B8%E8%A6%8B%E6%AD%A1%EF%BC%88%E7%84%A1%E8%A8%80%E7%8D%A8%E4%B8%8A%E8%A5%BF%E6%A8%93%EF%BC%89"}, {"title": "浪淘沙（簾外雨潺潺）", "author": "李煜", "period": "五代十國", "form": "詞", "theme": "江河湖海", "mood": "snow_winter", "lines": ["簾外雨潺潺，春意闌珊。羅衾不耐五更寒，夢裏不知身是客，一晌貪歡。", "獨自莫凭闌，無限江山，別時容易見時難。流水落花春去也，天上人間！"], "quote": ["簾外雨潺潺，春意闌珊。羅衾不耐五更寒，夢裏不知身是客，一晌貪歡。", "獨自莫凭闌，無限江山，別時容易見時難。流水落花春去也，天上人間！"], "intro": "《浪淘沙》（簾外雨潺潺）選自《評註南唐二主詞》。《浪淘沙》為詞牌名，一名「賣花聲」，是李後主亡國後之作。這詞透過夢境與現實，歡樂與愁恨之對比，透露出作者對故國、家園的無限眷念。詞的意境高遠，蘊含無限愁苦，傳為千古哀音。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B5%AA%E6%B7%98%E6%B2%99%EF%BC%88%E7%B0%BE%E5%A4%96%E9%9B%A8%E6%BD%BA%E6%BD%BA%EF%BC%89"}, {"title": "破陣子（四十年來家國）", "author": "李煜", "period": "五代十國", "form": "詞", "theme": "送別行旅", "mood": "vast_river", "lines": ["四十年來家國，三千里地山河。鳳閣龍樓連霄漢，玉樹瓊枝作煙蘿。幾曾識干戈？", "一旦歸為臣虜，沈腰潘鬢銷磨。最是倉皇辭廟日，教坊猶奏別離歌。垂淚對宮娥。"], "quote": ["四十年來家國，三千里地山河。鳳閣龍樓連霄漢，玉樹瓊枝作煙蘿。幾曾識干戈？", "一旦歸為臣虜，沈腰潘鬢銷磨。最是倉皇辭廟日，教坊猶奏別離歌。垂淚對宮娥。"], "intro": "《破陣子》，詞牌名，唐教坊曲，又名《十拍子》。陳暘《樂書》指是秦王（李世民）所制，是唐開國時的大型舞曲。《破陣子》為雙調小令，應是截取舞曲中之一段而成。 宋軍在公元975年攻破金陵，李煜出城投降成為俘虜，被宋太祖軟禁在宋都汴京。《破陣子》是", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%A0%B4%E9%99%A3%E5%AD%90%EF%BC%88%E5%9B%9B%E5%8D%81%E5%B9%B4%E4%BE%86%E5%AE%B6%E5%9C%8B%EF%BC%89"}, {"title": "清平樂（別來春半）", "author": "李煜", "period": "五代十國", "form": "詞", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["別來春半，觸目柔腸斷。砌下落梅如雪亂，拂了一身還滿。", "雁來音信無憑，路遙歸夢難成。離恨恰如春草，更行更遠還生。"], "quote": ["別來春半，觸目柔腸斷。砌下落梅如雪亂，拂了一身還滿。", "雁來音信無憑，路遙歸夢難成。離恨恰如春草，更行更遠還生。"], "intro": "這首詞是後主亡國，被擄北上後有感於國破家亡的離愁別恨，及對南唐宮廷生活的無限依戀而寫下來的作品。充分表現了後主懷念故國的憂鬱心情。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B8%85%E5%B9%B3%E6%A8%82%EF%BC%88%E5%88%A5%E4%BE%86%E6%98%A5%E5%8D%8A%EF%BC%89"}, {"title": "菩薩蠻（花明月暗飛輕霧）", "author": "李煜", "period": "五代十國", "form": "詞", "theme": "歲時雪月", "mood": "spring_breeze", "lines": ["花明月暗飛輕霧，今宵好向郎邊去。剗襪步香階，手提金縷鞋。", "畫堂南畔見，一向偎人顫。奴為出來難，教君恣意憐。"], "quote": ["花明月暗飛輕霧，今宵好向郎邊去。剗襪步香階，手提金縷鞋。", "畫堂南畔見，一向偎人顫。奴為出來難，教君恣意憐。"], "intro": "這首詞是李煜前期的作品，寫他與小周后幽會的豔史。小周后是大周后的妹妹，容貌秀麗，神采端靜，後主同時偷偷愛上了她。後來大周后去世，後主遂以禮納之為后。這裏描寫他們婚前幽會的情形。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%8F%A9%E8%96%A9%E8%A0%BB%EF%BC%88%E8%8A%B1%E6%98%8E%E6%9C%88%E6%9A%97%E9%A3%9B%E8%BC%95%E9%9C%A7%EF%BC%89"}, {"title": "虞美人（春花秋月何時了）", "author": "李煜", "period": "五代十國", "form": "詞", "theme": "春水花鳥", "mood": "autumn_sunset", "lines": ["春花秋月何時了？往事知多少？小樓昨夜又東風，故國不堪回首月明中！", "雕闌玉砌應猶在，只是朱顏改。問君能有幾多愁？恰似一江春水向東流！"], "quote": ["春花秋月何時了？往事知多少？小樓昨夜又東風，故國不堪回首月明中！", "雕闌玉砌應猶在，只是朱顏改。問君能有幾多愁？恰似一江春水向東流！"], "intro": "《虞美人》（春花秋月何時了）選自《評註南唐二主詞》。《虞美人》為詞牌名，是李後主亡國後之作。此詞抒發作者因家國今昔巨變而帶來的無限感慨，通篇運用種種比喻和暗示，將過去和現在的生活作回憶對比。文字清逸俊秀，情感清悽沉痛。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%99%9E%E7%BE%8E%E4%BA%BA%EF%BC%88%E6%98%A5%E8%8A%B1%E7%A7%8B%E6%9C%88%E4%BD%95%E6%99%82%E4%BA%86%EF%BC%89"}, {"title": "攤破浣溪沙（菡萏香銷翠葉殘）", "author": "李璟", "period": "五代十國", "form": "詞", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["菡萏香銷翠葉殘，西風愁起綠波間，還與韶光共憔悴，不堪看！", "細雨夢回雞塞遠，小樓吹徹玉笙寒。多少淚珠何限恨！倚闌干。"], "quote": ["菡萏香銷翠葉殘，西風愁起綠波間，還與韶光共憔悴，不堪看！", "細雨夢回雞塞遠，小樓吹徹玉笙寒。多少淚珠何限恨！倚闌干。"], "intro": "這首詞原題《浣溪沙》，一題《山花子》，為《浣溪沙》的別體。萬樹《詞律》卷三：「此調本以《浣溪沙》原調結句破七字為十字，故名《攤破浣溪沙》。」詞中描寫思婦懷念遠在邊塞的丈夫的情景。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%94%A4%E7%A0%B4%E6%B5%A3%E6%BA%AA%E6%B2%99%EF%BC%88%E8%8F%A1%E8%90%8F%E9%A6%99%E9%8A%B7%E7%BF%A0%E8%91%89%E6%AE%98%EF%BC%89"}, {"title": "菩薩蠻（其二）（人人盡說江南好）", "author": "韋莊", "period": "五代十國", "form": "詞", "theme": "江河湖海", "mood": "snow_winter", "lines": ["人人盡說江南好，遊人只合江南老。春水碧於天，畫船聽雨眠。", "壚邊人似月，皓腕凝雙雪。未老莫還鄉，還鄉須斷腸！"], "quote": ["人人盡說江南好，遊人只合江南老。春水碧於天，畫船聽雨眠。", "壚邊人似月，皓腕凝雙雪。未老莫還鄉，還鄉須斷腸！"], "intro": "韋莊《菩薩蠻》詞共有五首，「人人盡說江南好」是第二首，版本據《花間集》。詞中描寫了四川的風光和人物，結句有樂不思鄉之感。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%8F%A9%E8%96%A9%E8%A0%BB%EF%BC%88%E5%85%B6%E4%BA%8C%EF%BC%89%EF%BC%88%E4%BA%BA%E4%BA%BA%E7%9B%A1%E8%AA%AA%E6%B1%9F%E5%8D%97%E5%A5%BD%EF%BC%89"}, {"title": "謁金門（風乍起）", "author": "馮延巳", "period": "五代十國", "form": "詞", "theme": "春水花鳥", "mood": "vast_river", "lines": ["風乍起，吹皺一池春水。閒引鴛鴦芳徑裏，手挼紅杏蕊。", "鬥鴨闌干獨倚，碧玉搔頭斜墜。終日望君君不至，舉頭聞鵲喜。"], "quote": ["風乍起，吹皺一池春水。閒引鴛鴦芳徑裏，手挼紅杏蕊。", "鬥鴨闌干獨倚，碧玉搔頭斜墜。終日望君君不至，舉頭聞鵲喜。"], "intro": "本調為唐詞，取義為儒生朝謁天子。毛先舒《詞學全書》：「唐樂名有『儒生謁金門』，詞沿其名。」金門即天子宮門，據《白香詞譜》：「漢武帝使學士待詔金馬門，備顧問，亦省稱金門。」金門後與玉堂並稱，見揚雄《解嘲》：「今吾子幸得應金門，上玉堂有日矣。」", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%AC%81%E9%87%91%E9%96%80%EF%BC%88%E9%A2%A8%E4%B9%8D%E8%B5%B7%EF%BC%89"}, {"title": "正氣歌  並序", "author": "文天祥", "period": "宋", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["余囚北庭，坐一土室；室廣八尺，深可四尋；單扉低小，白間短窄，汙下而幽暗。當此夏日，諸氣萃然︰雨潦四集，浮動牀几，時則為水氣。塗泥半朝，蒸漚歷瀾，時則為土氣。", "乍晴乍熱，風道四塞，時則為日氣。簷陰薪爨，助長炎虐，時則為火氣。倉腐寄頓，陳陳逼人，時則為米氣。駢肩雜遝，腥臊汙垢，時則為人氣。或圊溷，或毀屍，或腐鼠，惡氣雜出，時則為穢氣。疊是數氣，當之者鮮不為厲；而余以孱弱，俯仰其間，於茲二年矣。", "審如是，殆有養致然爾。然亦安知所養何哉！孟子曰︰「我善養吾浩然之氣」；彼氣有七，吾氣有一；以一敵七，吾何患焉！況浩然者乃天地之正氣也？作《正氣歌》一首。", "天地有正氣，雜然賦流形︰下則為河嶽，上則為日星。於人曰浩然，沛乎塞蒼冥。皇路當清夷，含和吐明廷。時窮節乃見，一一垂丹青。在齊太史簡，在晉董狐筆。在秦張良椎，在漢蘇武節。", "為嚴將軍頭，為嵇侍中血。為張睢陽齒，為顏常山舌。或為遼東帽，清操厲冰雪；或為出師表，鬼神泣壯烈；或為渡江楫，慷慨吞胡羯；或為擊賊笏，逆豎頭破裂。是氣所磅礡，凜烈萬古存。", "當其貫日月，生死安足論！地維賴以立，天柱賴以尊。三綱實繫命，道義為之根。", "嗟余遘陽九，隸也實不力！楚囚纓其冠。傳車送窮北，鼎鑊甘如飴，求之不可得。陰房闃鬼火，春院閟天黑。牛驥同一皁，雞棲鳳凰食。一朝蒙霧露，分作溝中瘠，如此再寒暑，百沴自辟易。", "哀哉沮洳場，為我安樂國。豈有它繆巧，陰陽不能賊？顧此耿耿在，仰視浮雲白。悠悠我心憂，蒼天曷有極！哲人日以遠，典型在夙昔。風簷展書讀，古道照顏色。"], "quote": ["余囚北庭，坐一土室；室廣八尺，深可四尋；單扉低小，白間短窄，汙下而幽暗。當此夏日，諸氣萃然︰雨潦四集，浮動牀几，時則為水氣。塗泥半朝，蒸漚歷瀾，時則為土氣。", "乍晴乍熱，風道四塞，時則為日氣。簷陰薪爨，助長炎虐，時則為火氣。倉腐寄頓，陳陳逼人，時則為米氣。駢肩雜遝，腥臊汙垢，時則為人氣。或圊溷，或毀屍，或腐鼠，惡氣雜出，時則為穢氣。疊是數氣，當之者鮮不為厲；而余以孱弱，俯仰其間，於茲二年矣。", "審如是，殆有養致然爾。然亦安知所養何哉！孟子曰︰「我善養吾浩然之氣」；彼氣有七，吾氣有一；以一敵七，吾何患焉！況浩然者乃天地之正氣也？作《正氣歌》一首。", "天地有正氣，雜然賦流形︰下則為河嶽，上則為日星。於人曰浩然，沛乎塞蒼冥。皇路當清夷，含和吐明廷。時窮節乃見，一一垂丹青。在齊太史簡，在晉董狐筆。在秦張良椎，在漢蘇武節。"], "intro": "本篇乃文天祥被俘後在獄中所作的長歌。認為古來忠臣義士皆天地正氣之所鍾；這正氣便是孟子所說的「浩然之氣」，能養這浩然之氣，便不怕一切磨折困難。因作此歌，一以表示對前賢的嚮往，一以抒寫自己的懷抱和決心；故題曰《正氣歌》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%AD%A3%E6%B0%A3%E6%AD%8C++%E4%B8%A6%E5%BA%8F"}, {"title": "過零丁洋", "author": "文天祥", "period": "宋", "form": "詩", "theme": "山水登臨", "mood": "vast_river", "lines": ["辛苦遭逢起一經，干戈寥落四周星。", "山河破碎風飄絮，身世浮沉雨打萍。", "惶恐灘頭說惶恐，零丁洋裏嘆零丁。", "人生自古誰無死，留取丹心照汗青。"], "quote": ["辛苦遭逢起一經，干戈寥落四周星。", "山河破碎風飄絮，身世浮沉雨打萍。", "惶恐灘頭說惶恐，零丁洋裏嘆零丁。", "人生自古誰無死，留取丹心照汗青。"], "intro": "中國的宋朝重文輕武，長期積弱，飽受外族的侵凌，最後亡於外族之手。在這時期內民族英雄特別多，顯示了中國人的風骨氣節。最著名的是抗金名將岳飛，可惜他被奸人所害，無辜被殺。南宋從此更一蹶不振，光復無望。北方強敵金人去了，更強悍的蒙古人又來。終南宋", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%81%8E%E9%9B%B6%E4%B8%81%E6%B4%8B"}, {"title": "元日", "author": "王安石", "period": "宋", "form": "詩", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["爆竹聲中一歲除，", "春風送暖入屠蘇。", "千門萬戶曈曈日，", "總把新桃換舊符。"], "quote": ["爆竹聲中一歲除，", "春風送暖入屠蘇。", "千門萬戶曈曈日，", "總把新桃換舊符。"], "intro": "元日即一年的第一天，即農曆正月初一。這是寫農曆新年的詩。詩人把歡樂熱鬧、萬戶更新的迎春氣象，生動地描繪出來。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%85%83%E6%97%A5"}, {"title": "明妃曲（兩首）", "author": "王安石", "period": "宋", "form": "詩", "theme": "邊塞豪放", "mood": "spring_breeze", "lines": ["其一", "明妃初出漢宮時，淚濕春風鬢腳垂。", "低徊顧影無顏色，尚得君王不自持。", "歸來卻怪丹青手，入眼平生幾曾有；", "意態由來畫不成，當時枉殺毛延壽。", "一去心知更不歸，可憐著盡漢宮衣；", "寄聲欲問塞南事，只有年年鴻雁飛。", "家人萬里傳消息，好在氈城莫相憶；", "君不見咫尺長門閉阿嬌，人生失意無南北。", "其二", "明妃初嫁與胡兒，氈車百輛皆胡姬。", "含情欲語獨無處，傳與琵琶心自知。"], "quote": ["其一", "明妃初出漢宮時，淚濕春風鬢腳垂。", "低徊顧影無顏色，尚得君王不自持。", "歸來卻怪丹青手，入眼平生幾曾有；"], "intro": "《明妃曲》是北宋王安石的作品，寫「昭君出塞」的故事。「明妃」即王昭君，原名王嬙，字昭君，晉朝時避司馬昭諱，改稱明君，後人又稱為明妃。王昭君被稱為中國古代「四大美人」之一，她的故事在西晉時代就有人傳誦，歷代不少詩人都寫過詠昭君的作品。在歷代文", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%98%8E%E5%A6%83%E6%9B%B2%EF%BC%88%E5%85%A9%E9%A6%96%EF%BC%89"}, {"title": "泊船瓜洲", "author": "王安石", "period": "宋", "form": "詩", "theme": "江河湖海", "mood": "vast_river", "lines": ["京口瓜洲一水間，鍾山衹隔數重山。", "春風又綠江南岸，明月何時照我還。"], "quote": ["京口瓜洲一水間，鍾山衹隔數重山。", "春風又綠江南岸，明月何時照我還。"], "intro": "《泊船瓜洲》選自《王荊文公詩箋註》卷四十三，作於宋神宗熙寧八年（一〇七五）二月。瓜江，在江蘇省邗江縣南，運河於此注入長江。當時王安石第二次拜相，奉詔進京，乘船路過瓜洲，即興而作。其中「春風又綠江南岸」一句，尤為後人稱道，成為文人煉字的典範。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B3%8A%E8%88%B9%E7%93%9C%E6%B4%B2"}, {"title": "書湖陰先生壁（其一）", "author": "王安石", "period": "宋", "form": "詩", "theme": "江河湖海", "mood": "vast_river", "lines": ["茅簷長掃靜無苔，花木成畦手自栽。", "一水護田將綠遶，兩山排闥送青來。"], "quote": ["茅簷長掃靜無苔，花木成畦手自栽。", "一水護田將綠遶，兩山排闥送青來。"], "intro": "《書湖陰先生壁》選自《王荊文公詩箋註》卷四十三，原題共二首，此處選錄第一首。當時作者被罷免宰相職務，隱居於金陵紫金山下，與鄰人湖陰先生楊德逢經常來往。這首詩就是王安石題寫在楊家牆壁上的一首名作。全詩雅淡而別緻，顯示了房主人湖陰先生高潔情操。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9B%B8%E6%B9%96%E9%99%B0%E5%85%88%E7%94%9F%E5%A3%81%EF%BC%88%E5%85%B6%E4%B8%80%EF%BC%89"}, {"title": "桂枝香・金陵懷古", "author": "王安石", "period": "宋", "form": "詞", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["登臨送目，正故國晚秋，天氣初肅。千里澄江似練，翠峰如簇。歸帆去棹殘陽裏，背西風，酒旗斜矗。彩舟雲淡，星河鷺起，畫圖難足。", "念往昔，繁華競逐，歎門外樓頭，悲恨相續。千古憑高，對此漫嗟榮辱。六朝舊事隨流水，但寒煙衰草凝綠。至今商女，時時猶唱，後庭遺曲。"], "quote": ["登臨送目，正故國晚秋，天氣初肅。千里澄江似練，翠峰如簇。歸帆去棹殘陽裏，背西風，酒旗斜矗。彩舟雲淡，星河鷺起，畫圖難足。", "念往昔，繁華競逐，歎門外樓頭，悲恨相續。千古憑高，對此漫嗟榮辱。六朝舊事隨流水，但寒煙衰草凝綠。至今商女，時時猶唱，後庭遺曲。"], "intro": "「桂枝香」命名，似由唐人詩句而來。裴思謙詩：「夜來新惹桂枝香。」袁皓詩：「桂枝香惹蕊珠香。」此詞可能是安王罷相之後，外調南京時所作。全詞弔古傷今，極符合他新政失敗後之心情。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%A1%82%E6%9E%9D%E9%A6%99%E3%83%BB%E9%87%91%E9%99%B5%E6%87%B7%E5%8F%A4"}, {"title": "梅花", "author": "王安石", "period": "宋", "form": "詩", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["牆角數枝梅，凌寒獨自開。", "遙知不是雪，為有暗香來。"], "quote": ["牆角數枝梅，凌寒獨自開。", "遙知不是雪，為有暗香來。"], "intro": "", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%A2%85%E8%8A%B1"}, {"title": "登飛來峰", "author": "王安石", "period": "宋", "form": "詩", "theme": "山水登臨", "mood": "vast_river", "lines": ["飛來峰上千尋塔，聞說雞鳴見日升。", "不畏浮雲遮望眼，自緣身在最高層。"], "quote": ["飛來峰上千尋塔，聞說雞鳴見日升。", "不畏浮雲遮望眼，自緣身在最高層。"], "intro": "飛來峰在杭州西湖西，與靈隱寺隔溪相對，高一百六十八米。相傳東晉時，印度僧人慧理曾說此山很像天竺國的靈鷲山，不知何以飛到中國來，人們便稱之為飛來峰。 王安石這首詩所寫的，是不是杭州的飛來峰，歷來都有人提出疑問。有人指出杭州的飛來峰無塔，和詩的", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%99%BB%E9%A3%9B%E4%BE%86%E5%B3%B0"}, {"title": "答司馬諫議書", "author": "王安石", "period": "宋", "form": "文", "theme": "邊塞豪放", "mood": "ethereal", "lines": ["某啟︰昨日蒙教。竊以為與君實游處相好之日久，而議事每不合，所操之術多異故也。雖欲強聒，終必不蒙見察，故略上報，不復一一自辨。重念蒙君實視遇厚；於反覆不宜鹵莽，故今具道所以，冀君實或見恕也。", "蓋儒者所爭，尤在於名實，名實已明而天下之理得矣。今君實所以見教者，以為侵官生事，征利拒諫，以致天下怨謗也。某則以為︰受命於人主，議法度而修之於朝廷，以授之於有司，不為侵官；舉先王之政，以興利除弊，不為生事；為天下理財，不為征利；闢邪說，難壬人，不為拒諫。", "至於怨誹之多，則固前知其如此也。人習於苟且非一日，士大夫多以不恤國事，同俗自媚於眾為善。上乃欲變此，而某不量敵之眾寡，欲出力助上以抗之，則眾何為而不洶洶？然盤庚之遷，胥怨者民也，非特朝廷士大夫而已。盤庚不為怨者故改其度，度義而後動，是而不見可悔故也。", "如君實責我以在位久，未能助上大有為，以膏澤斯民，則某知罪矣，如曰今日當一切不事事，守前所為而已，則非某之所敢知。", "無由會晤，不任區區向往之至！"], "quote": ["某啟︰昨日蒙教。竊以為與君實游處相好之日久，而議事每不合，所操之術多異故也。雖欲強聒，終必不蒙見察，故略上報，不復一一自辨。重念蒙君實視遇厚；於反覆不宜鹵莽，故今具道所以，冀君實或見恕也。", "蓋儒者所爭，尤在於名實，名實已明而天下之理得矣。今君實所以見教者，以為侵官生事，征利拒諫，以致天下怨謗也。某則以為︰受命於人主，議法度而修之於朝廷，以授之於有司，不為侵官；舉先王之政，以興利除弊，不為生事；為天下理財，不為征利；闢邪說，難壬人，不為拒諫。", "至於怨誹之多，則固前知其如此也。人習於苟且非一日，士大夫多以不恤國事，同俗自媚於眾為善。上乃欲變此，而某不量敵之眾寡，欲出力助上以抗之，則眾何為而不洶洶？然盤庚之遷，胥怨者民也，非特朝廷士大夫而已。盤庚不為怨者故改其度，度義而後動，是而不見可悔故也。", "如君實責我以在位久，未能助上大有為，以膏澤斯民，則某知罪矣，如曰今日當一切不事事，守前所為而已，則非某之所敢知。"], "intro": "王安石變法，甚受輿論指責，司馬光先已因反對青苗募役等法，使安石不快，調判西京（洛陽）御史臺，這時又寫了一封數千言的長信來規勸安石，批評新法不對，又批評安石厭惡反對意見的毛病，說：「人之議論與我合則善之，不合則惡之。如此，方正之士何由進？諂諛", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%AD%94%E5%8F%B8%E9%A6%AC%E8%AB%AB%E8%AD%B0%E6%9B%B8"}, {"title": "遊褒禪山記", "author": "王安石", "period": "宋", "form": "文", "theme": "田園幽居", "mood": "snow_winter", "lines": ["褒禪山亦謂之華山，唐浮圖慧褒始舍於其址，而卒葬之，以故其後名之曰褒禪。今所謂「慧空禪院」者，褒之廬冢也。距其院東五里，所謂華陽洞者，以其在華山之陽名之也。距洞百餘步，有碑仆道，其文漫滅，獨其為文猶可識曰﹕「花山」。今言華如華實之華者，蓋音謬也。其下平曠，有泉側出，而記遊者甚眾，所謂前洞也。由山以上五六里，有穴窈然，入之甚寒，問其深，則其好遊者不能窮也，謂之後洞。", "余與四人擁火以入，入之愈深，其進愈難，而其見愈奇。有怠而欲出者，曰﹕「不出，火且盡。」遂與之俱出。蓋予所至，比好遊者尚不能十一，然視其左右，來而記之者已少。蓋其又深，則其至又加少矣。方是時，予之力尚足以入，火尚足以明也。既其出，則或咎其欲出者，而予亦悔其隨之，而不得極乎遊之樂也。", "於是予有歎焉，古人之觀於天地、山川、草木、蟲魚、鳥獸，往往有得，以其求思之深而無不在也。夫夷以近，則遊者眾；險以遠，則至者少。而世之奇偉瑰怪非常之觀，常在於險遠，而人之所罕至焉。故非有志者，不能至也。有志矣，不隨以止也，然力不足者，亦不能至也。有志與力，而又不隨以怠，至於幽暗昏惑，而無物以相之，亦不能至也。然力足以至焉而不至，於人為可譏，而在己為有悔。盡吾志也，而不能至者，可以無悔矣。其孰能譏之乎？此予之所得也。", "余於仆碑，又以悲夫古書之不存，後世之謬其傳，而莫能名者，何可勝道也哉！此所以學者不可以不深思而慎取之也。", "四人者︰廬陵蕭君圭君玉，長樂王回深父，余弟安國平父、安上純父。"], "quote": ["褒禪山亦謂之華山，唐浮圖慧褒始舍於其址，而卒葬之，以故其後名之曰褒禪。今所謂「慧空禪院」者，褒之廬冢也。距其院東五里，所謂華陽洞者，以其在華山之陽名之也。距洞百餘步，有碑仆道，其文漫滅，獨其為文猶可識曰﹕「花山」。今言華如華實之華者，蓋音謬也。其下平曠，有泉側出，而記遊者甚眾，所謂前洞也。由山以上五六里，有穴窈然，入之甚寒，問其深，則其好遊者不能窮也，謂之後洞。", "余與四人擁火以入，入之愈深，其進愈難，而其見愈奇。有怠而欲出者，曰﹕「不出，火且盡。」遂與之俱出。蓋予所至，比好遊者尚不能十一，然視其左右，來而記之者已少。蓋其又深，則其至又加少矣。方是時，予之力尚足以入，火尚足以明也。既其出，則或咎其欲出者，而予亦悔其隨之，而不得極乎遊之樂也。", "於是予有歎焉，古人之觀於天地、山川、草木、蟲魚、鳥獸，往往有得，以其求思之深而無不在也。夫夷以近，則遊者眾；險以遠，則至者少。而世之奇偉瑰怪非常之觀，常在於險遠，而人之所罕至焉。故非有志者，不能至也。有志矣，不隨以止也，然力不足者，亦不能至也。有志與力，而又不隨以怠，至於幽暗昏惑，而無物以相之，亦不能至也。然力足以至焉而不至，於人為可譏，而在己為有悔。盡吾志也，而不能至者，可以無悔矣。其孰能譏之乎？此予之所得也。", "余於仆碑，又以悲夫古書之不存，後世之謬其傳，而莫能名者，何可勝道也哉！此所以學者不可以不深思而慎取之也。"], "intro": "褒禪山在安徽省含山縣北十五里，原名北山，因唐僧慧褒曾在此居住，又葬於此山，所以後人呼為褒禪山。作者這篇記，敍述遊山的事並不多，不過藉此發表他個人的一些意見。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%81%8A%E8%A4%92%E7%A6%AA%E5%B1%B1%E8%A8%98"}, {"title": "傷仲永", "author": "王安石", "period": "宋", "form": "文", "theme": "送別行旅", "mood": "ethereal", "lines": ["金谿民方仲永，世隸耕。仲永生五年，未嘗識書具，忽啼求之；父母焉，借旁近與之。即書詩四句，并自為其名；其詩以養父母收族為意。傳一鄉秀才觀之。自是指物作詩，立就，其文理皆有可觀者。邑人奇之，稍稍賓客其父；或以錢幣乞之。父利其然也，日扳仲永環謁於邑人，不使學。", "余聞之也久。明道中，從先人還家，於舅家見之，十二三矣。令作詩，不能稱前時之聞。又七年，還自揚州，復到舅家問焉。曰︰「泯然眾人矣！」", "王子曰︰「仲永之通悟，受之天也。其受之天也，賢於材人遠矣；卒之為眾人，則其受於人者不至也。彼其受之天也，如此其賢也，不受之人且為眾人；今夫不受之天，固眾人；又不受之人，得為眾人而已邪？」"], "quote": ["金谿民方仲永，世隸耕。仲永生五年，未嘗識書具，忽啼求之；父母焉，借旁近與之。即書詩四句，并自為其名；其詩以養父母收族為意。傳一鄉秀才觀之。自是指物作詩，立就，其文理皆有可觀者。邑人奇之，稍稍賓客其父；或以錢幣乞之。父利其然也，日扳仲永環謁於邑人，不使學。", "余聞之也久。明道中，從先人還家，於舅家見之，十二三矣。令作詩，不能稱前時之聞。又七年，還自揚州，復到舅家問焉。曰︰「泯然眾人矣！」", "王子曰︰「仲永之通悟，受之天也。其受之天也，賢於材人遠矣；卒之為眾人，則其受於人者不至也。彼其受之天也，如此其賢也，不受之人且為眾人；今夫不受之天，固眾人；又不受之人，得為眾人而已邪？」"], "intro": "傷，是「可惜」的意思；仲永，人名，姓方；有天才，卻未能受教育。本文即為作者惜方仲永失學而作，選自《臨川先生文集》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%82%B7%E4%BB%B2%E6%B0%B8"}, {"title": "讀孟嘗君傳", "author": "王安石", "period": "宋", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["世皆稱孟嘗君能得士，士以故歸之，而卒賴其力以脫於虎豹之秦。", "嗟乎！孟嘗君特雞鳴狗盜之雄耳，豈足以言得士？", "不然，擅齊之強，得一士焉，宜可以南面而制秦，尚何取雞鳴狗盜之力哉！雞鳴狗盜之出其門，此士之所以不至也。"], "quote": ["世皆稱孟嘗君能得士，士以故歸之，而卒賴其力以脫於虎豹之秦。", "嗟乎！孟嘗君特雞鳴狗盜之雄耳，豈足以言得士？", "不然，擅齊之強，得一士焉，宜可以南面而制秦，尚何取雞鳴狗盜之力哉！雞鳴狗盜之出其門，此士之所以不至也。"], "intro": "《孟嘗君傳》，是漢司馬遷所著《史記》中的一篇列傳，在《史記》卷七十五。本文即王安石讀了這篇列傳以後所寫的「讀後感」，針對孟嘗君好士這一點提出了批評。孟嘗君，姓田名文，戰國時代齊國的主義──按《史記》本傳，他是齊威王田因齊的孫兒。他的父親田嬰", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%AE%80%E5%AD%9F%E5%98%97%E5%90%9B%E5%82%B3"}, {"title": "卜算子（水是眼波橫）", "author": "王觀", "period": "宋", "form": "詞", "theme": "送別行旅", "mood": "vast_river", "lines": ["送鮑浩然之浙東", "水是眼波橫，山是眉峰聚。欲問行人去那邊？眉眼盈盈處。", "才始送春歸，又送君歸去。若到江南趕上春，千萬和春住。"], "quote": ["送鮑浩然之浙東", "水是眼波橫，山是眉峰聚。欲問行人去那邊？眉眼盈盈處。", "才始送春歸，又送君歸去。若到江南趕上春，千萬和春住。"], "intro": "《卜算子》是詞牌名，通稱《採桑子》，又名《百尺樓》、《眉峰碧》、《楚天遙》等。北宋時盛行此曲。 這是一首送別詞，有副題「送鮑浩然之浙東」，題目一作「別意」。春末時節，作者在越州大都督府送別即將回家鄉（浙東）的好友鮑浩然。他自己也家在浙東，欲", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%8D%9C%E7%AE%97%E5%AD%90%EF%BC%88%E6%B0%B4%E6%98%AF%E7%9C%BC%E6%B3%A2%E6%A9%AB%EF%BC%89"}, {"title": "口鼻眼眉爭辯", "author": "王讜", "period": "宋", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["口與鼻爭高下。口曰︰「我談古今是非，爾何能居我上？」鼻曰︰「飲食非我不能辨。」眼謂鼻曰︰「我近鑒毫端，遠察天際，惟我當先。」又謂眉曰︰「爾有何功居我上？」眉曰︰「我雖無用，亦如世有賓客，何益主人？無即不成禮儀。若無眉，成何面目？」"], "quote": ["口與鼻爭高下。口曰︰「我談古今是非，爾何能居我上？」鼻曰︰「飲食非我不能辨。」眼謂鼻曰︰「我近鑒毫端，遠察天際，惟我當先。」又謂眉曰︰「爾有何功居我上？」眉曰︰「我雖無用，亦如世有賓客，何益主人？無即不成禮儀。若無眉，成何面目？」"], "intro": "本文節錄自《唐語林》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%8F%A3%E9%BC%BB%E7%9C%BC%E7%9C%89%E7%88%AD%E8%BE%AF"}, {"title": "與王介甫書", "author": "司馬光", "period": "宋", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["光居常無事，不敢涉兩府之門，以是久不得通名於將命者。春暖，伏維機政餘裕，台侯萬福。", "孔子曰︰「益者三友，損者三友。」光不材，不足以辱介甫為友。然自接侍以來，十有餘年，屢嘗同僚，亦不可謂無一日之雅也。雖愧多聞，至於直諒，不敢不勉；若乃便佞，則固不敢為也。", "孔子曰︰「君子和而不同；小人同而不和。」君子之道，出處語嘿，安可同也；然其志則皆欲立身行道，輔世養民，此其所以和也。曏者，與介甫議論朝廷事，數相違，未知介甫之察不察；然於光嚮慕之心，未始變移也。", "竊見介甫獨負天下大名三十餘年，才高而學富，難進而易退。遠近之士，識與不識，咸謂介甫不起而已，起則太平可立致，生民咸被其澤矣。天子用此起介甫於不可起之中，引參大政，豈非亦欲望眾人之所望於介甫邪？", "今介甫從政始朞年，而士大夫在朝廷及自四方來者，莫不非議介甫，如出一口；下至閭閻細民，小吏走卒，亦切切怨歎，人人歸咎於介甫。不知介甫亦嘗聞其言而知其故乎？光竊意門下之士，方日譽盛德而贊功業，未始有一人敢以此聞達於左右者也。非門下之士，則皆曰︰「彼方得君而專政，無為觸之以取禍；不若坐而待之，不過二三年，彼將自敗。」若是者，不唯不忠於介甫，亦不忠於朝廷。", "若介甫果信此志，推而行之，及二三年，則朝廷之患已深矣，安可救乎？如光則不然，忝備交遊之末，不敢苟避譴怒，不為介甫一一陳之。", "今天下之人惡介甫之甚者，謗詆無所不至，光獨知其不然。介甫固大賢，其失在於用心太過，自信太厚而已。何以言之？自古聖賢所以治國者，不過使百官各稱其職，委任而責成功也；其所以養民者，不過輕租稅，薄賦斂，已逋責也。介甫以為此皆腐儒之常談，不足為，思得古人所未嘗為者而為之；於是財利不以委三司而自治之，更立制置三司條例司，聚文章之士及曉財利之人，使之講利。", "孔子曰︰「君子喻於義，小人喻於利。」樊須請學稼，孔子猶鄙之，以為不知禮義信。況講商賈之末利乎？使彼誠君子邪，則固不能言利；彼誠小人邪，則固民是盡，以飽上之欲，又可從乎？是知條例一司，已不當置而置之。又於其中不次用人，往往暴得美官；於是言利之人，皆攘臂圜視，衒鬻爭進，各鬭智巧，以變更祖宗舊法。大抵所利不能補其所傷，所得不能償其所亡；徒欲別出新意，以自為功名耳。此其為害已甚矣。", "又置提舉常平廣惠倉使者四十餘人，使行新法於四方︰先散青苗錢，次欲使比戶出助役錢，次又欲更搜求農田水利而行之。所遣者雖皆選擇才俊，然其中亦有輕佻狂躁之人，陵轢州縣，騷擾百姓者。於是士大夫不服，農商喪業。故謗議沸騰，怨嗟盈路。迹其本原，咸以此也。", "《書》曰︰「民不靜，亦惟在王宮邦君室。」伊尹為阿衡，有一夫不獲其所，若己推而內之溝中。孔子曰︰「君子求諸己。」介甫亦當自思所以致其然者，不可專罪天下之人也。", "夫侵官者，亂政也，介甫更以為治術而先施之；貸息錢，鄙事也，介甫更以為王政而力行之；徭役自古皆從民出，介甫更欲斂民錢，雇市傭而使之。此三者，常人皆知其不可，而介甫獨以為可；非介甫之智不及常人也，直欲求非常之功，而忽常人之所知耳。", "夫皇極之道，施之於天地人，皆不可須臾離。故孔子曰︰「道之不明也，我知之矣︰智者過之；愚者不及也。道之不行也，我知之矣︰賢者過之；不肖者不及也。」介甫之智與賢皆過人；及其失也，乃與不及之患均。此光所謂用心太過者也。"], "quote": ["光居常無事，不敢涉兩府之門，以是久不得通名於將命者。春暖，伏維機政餘裕，台侯萬福。", "孔子曰︰「益者三友，損者三友。」光不材，不足以辱介甫為友。然自接侍以來，十有餘年，屢嘗同僚，亦不可謂無一日之雅也。雖愧多聞，至於直諒，不敢不勉；若乃便佞，則固不敢為也。", "孔子曰︰「君子和而不同；小人同而不和。」君子之道，出處語嘿，安可同也；然其志則皆欲立身行道，輔世養民，此其所以和也。曏者，與介甫議論朝廷事，數相違，未知介甫之察不察；然於光嚮慕之心，未始變移也。", "竊見介甫獨負天下大名三十餘年，才高而學富，難進而易退。遠近之士，識與不識，咸謂介甫不起而已，起則太平可立致，生民咸被其澤矣。天子用此起介甫於不可起之中，引參大政，豈非亦欲望眾人之所望於介甫邪？"], "intro": "介甫，是王安石（一〇二一──一〇八六）的字。司馬光給王安石的這封信，大約寫於一〇七〇年，時司馬光五十二歲，王安石五十歲。那時司馬光是諫議大夫，王安石是宰相。這是當時「變法」政爭的一個重要文獻。要了解這篇文章，我們必須先了解那一段歷史背景。 ", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%88%87%E7%8E%8B%E4%BB%8B%E7%94%AB%E6%9B%B8"}, {"title": "資治通鑑・赤壁之戰", "author": "司馬光", "period": "宋", "form": "文", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["初，魯肅聞劉表卒，言於孫權曰︰「荊州與國鄰接，江山險固，沃野萬里，士民殷富，若據而有之，此帝王之資也。今劉表新亡，二子不協，軍中諸將，各有彼此。劉備天下梟雄，與操有隙，寄寓於表，表惡其能而不能用也。", "若備與彼協心，上下齊同，則宜撫安，與結盟好；如有離違，宜別圖之，以濟大事。肅請得奉命弔表二子，并慰勞其軍中用事者，及說備使撫表眾，同心一意，共治曹操，備必喜而從命。如其克諧，天下可定也。今不速往，恐為操所先。」權即遣肅行。", "到夏口，聞操已向州，晨夜兼道，比至南郡，而琮已降，備南走，肅徑迎之，與備會於當陽長坂。肅宣權旨，論天下事勢，致殷勤之意。且問備曰︰「豫州今欲何至？」備曰︰「與蒼梧太守吳巨有舊，欲往投之。」", "肅曰︰「孫討虜聰明仁惠，敬賢禮士，江表英豪，咸歸附之，已據有六郡，兵精糧多，足以立事。今為君計，莫若遣腹心自結於東，以共濟世業，而欲投吳巨；巨是凡人，偏在遠郡，行將為人所併，豈足託乎！」備甚悅。", "肅又謂諸葛亮曰︰「我，子瑜友也。」即共定交。子瑜者，亮兄瑾也，避亂江東，為孫權長史。備用肅計，進住鄂縣之樊口。", "曹操自江陵將順江東下。諸葛亮謂劉備曰︰「事急矣，請奉命求救於孫將軍。」遂與魯肅俱詣孫權。亮見權於柴桑，說權曰︰「海內大亂，將軍起兵江東，劉豫州收眾漢南，與曹操共爭天下。今操芟夷大難，略已平矣，遂破州，威震四海。英雄無用武之地，故豫州遁逃至此，願將軍量力而處之！", "若能以吳、越之眾與中國抗衡，不如早與之絕；若不能，何不按兵束甲，北面而事之！今將軍外託服從之名而內懷猶豫之計，事急而不斷，禍至無日矣。」權曰︰「苟如君言，劉豫州何不遂事之乎？」", "亮曰︰「田橫，齊之壯士耳，猶守義不辱；況劉豫州王室之冑，英才蓋世，眾士慕仰，若水之歸海。若事之不濟，此乃天也，安能復為之下乎！」權勃然曰︰「吾不能舉全吳之地，十萬之眾，受制於人。吾計決矣！非劉豫州莫可以當曹操者；然豫州新敗之後，安能抗此難乎？」", "亮曰︰「豫州軍雖敗於長坂，今戰士還者及關羽水軍精甲萬人，劉琦合江夏戰士亦不下萬人。曹操之眾，遠來疲敝，聞追豫州，輕騎一日一夜行三百餘里，此所謂『強弩之末勢不能穿魯縞』者也。故《兵法》忌之，曰『必蹶上將軍』。且北方之人，不習水戰；又荊州之民附操者，偪兵勢耳，非心服也。", "今將軍誠能命猛將統兵數萬，與豫州協規同力，破操軍必矣。操軍破，必北還；如此，則荊、吳之勢強，鼎足之形成矣。成敗之機，在於今日！」權大悅，與其羣下謀之。", "是時，曹操遺權書曰︰「近者奉辭伐罪。旌麾南指，劉琮束手。今治水軍八十萬眾，方與將軍會獵於吳。」權以示臣下，莫不響震失色。長史張昭等曰︰「曹公，豺虎也，挾天子以征四方，動以朝為辭；今日拒之，事更不順。", "且將軍大勢可以拒操者，長江也；今操得荆州，奄有其地，劉表治水軍，蒙衝鬭艦乃以千數，操悉浮以沿江，兼有步兵，水陸俱下，此為長江之險已與我共之矣，而勢力眾寡又不可論。愚謂大計不如迎之。」魯肅獨不言。權起更衣，肅追於宇下。權知其意，執肅手曰︰「卿欲何言？」"], "quote": ["初，魯肅聞劉表卒，言於孫權曰︰「荊州與國鄰接，江山險固，沃野萬里，士民殷富，若據而有之，此帝王之資也。今劉表新亡，二子不協，軍中諸將，各有彼此。劉備天下梟雄，與操有隙，寄寓於表，表惡其能而不能用也。", "若備與彼協心，上下齊同，則宜撫安，與結盟好；如有離違，宜別圖之，以濟大事。肅請得奉命弔表二子，并慰勞其軍中用事者，及說備使撫表眾，同心一意，共治曹操，備必喜而從命。如其克諧，天下可定也。今不速往，恐為操所先。」權即遣肅行。", "到夏口，聞操已向州，晨夜兼道，比至南郡，而琮已降，備南走，肅徑迎之，與備會於當陽長坂。肅宣權旨，論天下事勢，致殷勤之意。且問備曰︰「豫州今欲何至？」備曰︰「與蒼梧太守吳巨有舊，欲往投之。」", "肅曰︰「孫討虜聰明仁惠，敬賢禮士，江表英豪，咸歸附之，已據有六郡，兵精糧多，足以立事。今為君計，莫若遣腹心自結於東，以共濟世業，而欲投吳巨；巨是凡人，偏在遠郡，行將為人所併，豈足託乎！」備甚悅。"], "intro": "本文選自《資治通鑑》卷六十五《漢獻帝紀》，題目為編者所加，版本據中華書局排印本。 赤壁之戰發生於漢獻帝建安十三年（二〇八）。是年七月，曹操襲取了荊州，劉備退守樊口，向孫權求援。孫權遂聯合劉備，以數萬軍隊對抗曹軍。十月，曹操和孫權會師於長江邊", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B3%87%E6%B2%BB%E9%80%9A%E9%91%91%E3%83%BB%E8%B5%A4%E5%A3%81%E4%B9%8B%E6%88%B0"}, {"title": "鷓鴣天（我是清都山水郎）", "author": "朱敦儒", "period": "宋", "form": "詞", "theme": "山水登臨", "mood": "vast_river", "lines": ["西都作", "我是清都山水郎，天教懶慢帶疏狂。曾批給露支風敕，累奏留雲借月章。", "詩萬首，酒千觴。幾曾着眼看侯王？玉樓金闕慵歸去，且插梅花醉洛陽。"], "quote": ["西都作", "我是清都山水郎，天教懶慢帶疏狂。曾批給露支風敕，累奏留雲借月章。", "詩萬首，酒千觴。幾曾着眼看侯王？玉樓金闕慵歸去，且插梅花醉洛陽。"], "intro": "此詞原題「西都作」。西都是指洛陽。據《宋史‧文苑傳》載：「靖康中召朱敦儒至京師，將處以學官。敦儒辭曰：麟鹿之性，自樂閑曠，爵祿非所願也，固辭還山。」這首詞大約是南渡前，從汴京回洛陽後所作。詞中充分表現出他那超脫不羈，卑視權位的個性。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%B7%93%E9%B4%A3%E5%A4%A9%EF%BC%88%E6%88%91%E6%98%AF%E6%B8%85%E9%83%BD%E5%B1%B1%E6%B0%B4%E9%83%8E%EF%BC%89"}, {"title": "大學章句序", "author": "朱熹", "period": "宋", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["《大學》之書，古之大學所以教人之法也。蓋自天降生民，則既莫不與之以仁義禮智之性矣；然其氣質之稟，或不能齊，是以不能皆有以知其性之所有而全之也。", "一有聰明睿智能盡其性者，出於其閒，則天必命之以為億兆之君師，使之治而教之，以復其性。此伏羲、神農、黃帝、堯、舜所以繼天立極，而司徒之職、典樂之官，所繇設也。", "三代之隆，其法寖備，然後王宮國都以及閭巷，莫不有學。人生八歲，則自王公以下，至於庶人之子弟，皆入小學，而教之以灑掃、應對、進退之節，禮、樂、射、御、書、數之文。", "及其十有五年，則自天子之元子、眾子，以至公、卿、大夫、元士之適子，與凡民之俊秀，皆入大學，而教之以窮理、正心、修己、治人之道。此又學校之教，大小之節，所以分也。", "夫以學校之設，其廣如此，教之之術，其次第節目之詳又如此，而其所以為教，則又皆本之人君躬行心得之餘，不待求之民生日用彝倫之外，是以當世之人無不學，其學焉者，無不有以知其性分之所固有，職分之所當為，而各俛焉以盡其力。此古昔盛時，所以治隆於上，俗美於下，而非後世之所能及也。", "及周之衰，賢聖之君不作，學校之政不修，教化陵夷，風俗頹敗。時則有若孔子之聖，而不得君師之位，以行其政教，於是獨取先王之法，誦而傳之，以詔後世。若《曲禮》、《少儀》、《內則》、《弟子職》諸篇，固小學之支流餘裔；", "而此篇者，則因小學之成功，以著大學之明法，外有以極其規模之大，而內有以盡其節目之詳者也。三千之徒，蓋莫不聞其說，而曾氏之傳，獨得其宗，於是作為傳義，以發其意。及孟子沒而其傳泯焉，則其書雖存，而知者鮮矣。", "自是以來，俗儒記誦詞章之習，其功倍於小學而無用；異端虛無寂滅之教，其高過於大學而無實；其它權謀術數，一切以就功名之說，與夫百家眾技之流，所以惑世誣民、充塞仁義者，又紛然雜出乎其閒，", "使其君子不幸而不得聞大道之要，其小人不幸而不得蒙至治之澤，晦盲否塞，反覆沈痼，以及五季之衰，而壞亂極矣。", "天運循環，無往不復。宋德隆盛，治教休明，於是河南程氏兩夫子出，而有以接乎孟氏之傳，實始尊信此篇而表章之。既又為之次其簡編，發其歸趣，然後古者大學教人之法，聖經賢傳之指，粲然復明於世。", "雖以熹之不敏，亦幸私淑而與有聞焉。顧其為書，猶頗放失，是以忘其固陋，采而輯之，間亦竊附己意，補其闕略，以俟後之君子。極知僭踰，無所逃罪，然於國家化民成俗之意，學者修己治人之方，則未必無小補云。"], "quote": ["《大學》之書，古之大學所以教人之法也。蓋自天降生民，則既莫不與之以仁義禮智之性矣；然其氣質之稟，或不能齊，是以不能皆有以知其性之所有而全之也。", "一有聰明睿智能盡其性者，出於其閒，則天必命之以為億兆之君師，使之治而教之，以復其性。此伏羲、神農、黃帝、堯、舜所以繼天立極，而司徒之職、典樂之官，所繇設也。", "三代之隆，其法寖備，然後王宮國都以及閭巷，莫不有學。人生八歲，則自王公以下，至於庶人之子弟，皆入小學，而教之以灑掃、應對、進退之節，禮、樂、射、御、書、數之文。", "及其十有五年，則自天子之元子、眾子，以至公、卿、大夫、元士之適子，與凡民之俊秀，皆入大學，而教之以窮理、正心、修己、治人之道。此又學校之教，大小之節，所以分也。"], "intro": "《大學》，本是《小戴禮記》裏的一篇，相傳為子思所作，朱子則以為出於曾子。全篇綜論道德修養與政治實踐（儒家所謂「學」）的本質、意義、相互關係、及若干具體問題，大致可說是儒家人文思想的精髓文獻。因此，宋儒程子（頤）以為這應是孔子的遺書，應作為「", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%A4%A7%E5%AD%B8%E7%AB%A0%E5%8F%A5%E5%BA%8F"}, {"title": "春日", "author": "朱熹", "period": "宋", "form": "詩", "theme": "春水花鳥", "mood": "vast_river", "lines": ["勝日尋芳泗水濱，無邊光景一時新。", "等閒識得東風面，萬紫千紅總是春。"], "quote": ["勝日尋芳泗水濱，無邊光景一時新。", "等閒識得東風面，萬紫千紅總是春。"], "intro": "《春日》一詩，從字面看是作者春天郊遊時所寫的遊春觀感，但根據朱熹生活的年代，位於山東省中部的泗水之地早已被金人侵佔，朱熹也未曾北上到達泗水之地。因此，「泗水遊春」並非寫實，只是一種虛擬。 這首詩其實是寓理於景，以描寫春景來比喻探求學問的精神", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%98%A5%E6%97%A5"}, {"title": "熟讀精思", "author": "朱熹", "period": "宋", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["凡讀書，須整頓几案，令潔淨端正，將書冊齊整頓放，正身體，對書冊，詳緩看字，仔細分明讀之。須要讀得字字響亮，不可誤一字，不可少一字，不可多一字，不可倒一字，不可牽強暗記，只是要多誦數遍，自然上口，久遠不忘。", "古人云︰「讀書千遍，其義自見。」謂讀得熟，則不待解說，自曉其義也。余嘗謂，讀書有三到，謂心到、眼到、口到。心不在此，則眼不看仔細，心眼既不專一，卻只漫浪誦讀，決不能記，記亦不能久也。三到之中，心到最急。心既到矣，眼口豈不到乎？"], "quote": ["凡讀書，須整頓几案，令潔淨端正，將書冊齊整頓放，正身體，對書冊，詳緩看字，仔細分明讀之。須要讀得字字響亮，不可誤一字，不可少一字，不可多一字，不可倒一字，不可牽強暗記，只是要多誦數遍，自然上口，久遠不忘。", "古人云︰「讀書千遍，其義自見。」謂讀得熟，則不待解說，自曉其義也。余嘗謂，讀書有三到，謂心到、眼到、口到。心不在此，則眼不看仔細，心眼既不專一，卻只漫浪誦讀，決不能記，記亦不能久也。三到之中，心到最急。心既到矣，眼口豈不到乎？"], "intro": "本文選自《朱子語類》卷十。《朱子語類》是宋代黎靖德所編，輯錄了朱熹與門人問答之語，全書共一百四十卷。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%86%9F%E8%AE%80%E7%B2%BE%E6%80%9D"}, {"title": "觀書有感（其一）", "author": "朱熹", "period": "宋", "form": "詩", "theme": "山水登臨", "mood": "vast_river", "lines": ["半畝方塘一鑑開，天光雲影共徘徊。", "問渠那得清如許，為有源頭活水來。"], "quote": ["半畝方塘一鑑開，天光雲影共徘徊。", "問渠那得清如許，為有源頭活水來。"], "intro": "《觀書有感》選自《朱子大全》文二。詩人以《觀書有感》為題寫了兩首絕句，這裏選錄第一首。作者將觀書所得心境，比喻作面對半畝方塘，山光雲影映入眼中；而方塘之初見又如鏡匣之乍開，兩相譬喻，優美而貼切。最後兩句用塘中活水比喻學問之不斷增進。詩不直接", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A7%80%E6%9B%B8%E6%9C%89%E6%84%9F%EF%BC%88%E5%85%B6%E4%B8%80%EF%BC%89"}, {"title": "風入松（聽風聽雨過清明）", "author": "吳文英", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["春晚感懷", "聽風聽雨過清明。愁草瘞花銘。樓前綠暗分攜路，一絲柳、一寸柔情。料峭春寒中酒，交加曉夢啼鶯。", "西園日日掃林亭。依舊賞新晴。黃蜂頻撲鞦韆索，有當時、纖手香凝。惆悵雙鴛不到，幽階一夜苔生。"], "quote": ["春晚感懷", "聽風聽雨過清明。愁草瘞花銘。樓前綠暗分攜路，一絲柳、一寸柔情。料峭春寒中酒，交加曉夢啼鶯。", "西園日日掃林亭。依舊賞新晴。黃蜂頻撲鞦韆索，有當時、纖手香凝。惆悵雙鴛不到，幽階一夜苔生。"], "intro": "吳文英《風入松》（聽風聽雨過清明）選自《全宋詞》。 《風入松》原是古琴曲。唐代僧皎然有《風入松歌》，後演變為詞調。吳文英的《風入松》，自題為「春晚感懷」，則是悼念亡妾而寫的。上片寫清明雨景，下片寫新晴之日，都襯出物是人非的惆悵。全詞不言傷情", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%A2%A8%E5%85%A5%E6%9D%BE%EF%BC%88%E8%81%BD%E9%A2%A8%E8%81%BD%E9%9B%A8%E9%81%8E%E6%B8%85%E6%98%8E%EF%BC%89"}, {"title": "采桑子（恨君不似江樓月）", "author": "呂本中", "period": "宋", "form": "詞", "theme": "江河湖海", "mood": "vast_river", "lines": ["恨君不似江樓月，南北東西，南北東西，只有相隨無別離。", "恨君卻似江樓月，暫滿還虧，暫滿還虧，待得團圓是幾時？"], "quote": ["恨君不似江樓月，南北東西，南北東西，只有相隨無別離。", "恨君卻似江樓月，暫滿還虧，暫滿還虧，待得團圓是幾時？"], "intro": "《采桑子》又名《醜奴兒》，上下兩片的格式都是「七－四－四－七」，中間兩個四字句，可相同亦可變化。本詞就採用重章疊句的形式，反復詠唱之間，有一種百轉千迴的情味。復沓（疊句）也是民歌常用的表現手法，既能顯示出感慨的深刻，又可增強詩歌的旋律美，有", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%87%87%E6%A1%91%E5%AD%90%EF%BC%88%E6%81%A8%E5%90%9B%E4%B8%8D%E4%BC%BC%E6%B1%9F%E6%A8%93%E6%9C%88%EF%BC%89"}, {"title": "月兒彎彎照九州", "author": "宋代民謠", "period": "宋", "form": "曲", "theme": "歲時雪月", "mood": "vast_river", "lines": ["月兒彎彎照九州，幾家歡樂幾家愁。", "幾家夫婦同羅帳，幾家飄散在他州。"], "quote": ["月兒彎彎照九州，幾家歡樂幾家愁。", "幾家夫婦同羅帳，幾家飄散在他州。"], "intro": "這是南宋初年在江南一帶流行的民歌。當時金兵南下，佔領了中國北方的大部分土地。南宋朝廷一味妥協，不想收復失地，致使許多老百姓流離失所。這首歌唱出了他們心中的怨憤。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9C%88%E5%85%92%E5%BD%8E%E5%BD%8E%E7%85%A7%E4%B9%9D%E5%B7%9E"}, {"title": "鷓鴣天（畫轂雕輪狹路逢）", "author": "宋祁", "period": "宋", "form": "詞", "theme": "山水登臨", "mood": "vast_river", "lines": ["畫轂雕輪狹路逢，一聲腸斷繡簾中。身無彩鳳雙飛翼，心有靈犀一點通。", "金作屋，玉為櫳，車如流水馬如龍。劉郎已恨蓬山遠，更隔蓬山一萬重。"], "quote": ["畫轂雕輪狹路逢，一聲腸斷繡簾中。身無彩鳳雙飛翼，心有靈犀一點通。", "金作屋，玉為櫳，車如流水馬如龍。劉郎已恨蓬山遠，更隔蓬山一萬重。"], "intro": "據以前詞話家的記載說：宋祁為學士，一日，過繁臺街。遇內家（宮中）車子數輛馳來，不及迴避。車中忽有搴簾者曰，此小宋也。宋祁驚訝不已，歸賦《鷓鴣天》云云。詞傳唱達於禁中，仁宗聞之，因問第幾車子何人呼小宋。有內人自陳云：頃因內宴，見宣翰林學士，左", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%B7%93%E9%B4%A3%E5%A4%A9%EF%BC%88%E7%95%AB%E8%BD%82%E9%9B%95%E8%BC%AA%E7%8B%B9%E8%B7%AF%E9%80%A2%EF%BC%89"}, {"title": "卜算子（我住長江頭）", "author": "李之儀", "period": "宋", "form": "詞", "theme": "江河湖海", "mood": "vast_river", "lines": ["我住長江頭，君住長江尾。日日思君不見君，共飲長江水。", "此水幾時休，此恨何時已。只願君心似我心，定不負相思意。"], "quote": ["我住長江頭，君住長江尾。日日思君不見君，共飲長江水。", "此水幾時休，此恨何時已。只願君心似我心，定不負相思意。"], "intro": "《卜算子》是詞牌名，通稱《採桑子》，又名《百尺樓》、《眉峰碧》、《楚天遙》等。北宋時盛行此曲。 崇寧二年（一一〇三年），李之儀被貶太平州，仕途受到沉重打擊，家人又連遭不幸，子女和妻子相繼去世。傳說他在這時遇到歌伎楊姝，引為知音，寫下幾首聽她", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%8D%9C%E7%AE%97%E5%AD%90%EF%BC%88%E6%88%91%E4%BD%8F%E9%95%B7%E6%B1%9F%E9%A0%AD%EF%BC%89"}, {"title": "一剪梅（紅藕香殘玉簟秋）", "author": "李清照", "period": "宋", "form": "詞", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["紅藕香殘玉簟秋。輕解羅裳，獨上蘭舟。雲中誰寄錦書來？雁字回時，月滿西樓。", "花自飄零水自流。一種相思，兩處閒愁。此情無計可消除，才下眉頭，卻上心頭。"], "quote": ["紅藕香殘玉簟秋。輕解羅裳，獨上蘭舟。雲中誰寄錦書來？雁字回時，月滿西樓。", "花自飄零水自流。一種相思，兩處閒愁。此情無計可消除，才下眉頭，卻上心頭。"], "intro": "《一剪梅》（紅藕香殘玉簟秋）選自《全宋詞》，《一剪梅》是詞牌名。這是一首抒寫離情別緒的詞，當寫於作者婚後不久，趙明誠即負笈遠遊之時。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B8%80%E5%89%AA%E6%A2%85%EF%BC%88%E7%B4%85%E8%97%95%E9%A6%99%E6%AE%98%E7%8E%89%E7%B0%9F%E7%A7%8B%EF%BC%89"}, {"title": "漁家傲（天接雲濤連曉霧）", "author": "李清照", "period": "宋", "form": "詞", "theme": "江河湖海", "mood": "snow_winter", "lines": ["天接雲濤連曉霧，星河欲轉千帆舞。彷彿夢魂歸帝所，聞天語，殷勤問我歸何處。", "我報路長嗟日暮，學詩謾有驚人句。九萬里風鵬正舉。風休住，蓬舟吹取三山去。"], "quote": ["天接雲濤連曉霧，星河欲轉千帆舞。彷彿夢魂歸帝所，聞天語，殷勤問我歸何處。", "我報路長嗟日暮，學詩謾有驚人句。九萬里風鵬正舉。風休住，蓬舟吹取三山去。"], "intro": "這首詞應為南渡後之作，約作於建炎四年（公元1130），時李清照四十七歲。李清照《金石錄後序》：「（建炎三年）冬十二月，金人陷洪州。……上江既不可往，又虜勢叵測。有弟迒任勅局刪定官，遂往依之，到台，台守已遁，之剡，出睦。又棄衣被走黃巖，雇舟入", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%BC%81%E5%AE%B6%E5%82%B2%EF%BC%88%E5%A4%A9%E6%8E%A5%E9%9B%B2%E6%BF%A4%E9%80%A3%E6%9B%89%E9%9C%A7%EF%BC%89%C2%A0"}, {"title": "鳳凰臺上憶吹簫（香冷金猊）", "author": "李清照", "period": "宋", "form": "詩", "theme": "江河湖海", "mood": "snow_winter", "lines": ["香冷金猊，被翻紅浪，起來慵自梳頭。任寶奩塵滿，日上簾鉤。生怕離懷別苦，多少事欲說還休。新來瘦，非干病酒，不是悲秋。", "休休！這回去也，千萬遍陽關也則難留。念武陵人遠，煙鎖秦樓。惟有樓前流水，應念我終日凝眸。凝眸處，從今又添一段新愁！"], "quote": ["香冷金猊，被翻紅浪，起來慵自梳頭。任寶奩塵滿，日上簾鉤。生怕離懷別苦，多少事欲說還休。新來瘦，非干病酒，不是悲秋。", "休休！這回去也，千萬遍陽關也則難留。念武陵人遠，煙鎖秦樓。惟有樓前流水，應念我終日凝眸。凝眸處，從今又添一段新愁！"], "intro": "這一詞牌，《填詞名解》說，是根據《列仙傳》所載秦弄玉故事而取名的。秦弄玉是春秋時秦穆公的女兒，她愛上了一位會吹簫的簫史，穆公就讓他倆結了婚，並為他倆蓋了一座樓。這一對愛侶，就天天在樓上吹簫，一天，吹來了一隻鳳凰，他倆就隨着鳳凰飛走了。這故事", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%B3%B3%E5%87%B0%E8%87%BA%E4%B8%8A%E6%86%B6%E5%90%B9%E7%B0%AB"}, {"title": "醉花陰（薄霧濃雲愁永晝）", "author": "李清照", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["薄霧濃雲愁永晝，瑞腦消金獸。佳節又重陽，玉枕紗廚，半夜涼初透。", "東籬把酒黃昏後，有暗香盈袖。莫道不消魂，簾捲西風，人似黃花瘦。"], "quote": ["薄霧濃雲愁永晝，瑞腦消金獸。佳節又重陽，玉枕紗廚，半夜涼初透。", "東籬把酒黃昏後，有暗香盈袖。莫道不消魂，簾捲西風，人似黃花瘦。"], "intro": "《醉花陰》（薄霧濃雲愁永晝）選自《全宋詞》，《醉花陰》是詞牌名，或題作「九日」、「重陽」，點出時值重陽。飲酒看菊，向來是古人在重陽佳節的賞心樂事。在這首詞裏，作者卻描寫了這天的愁悶。下闋將人與黃花相比，表達對丈夫的深切思念。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%86%89%E8%8A%B1%E9%99%B0%EF%BC%88%E8%96%84%E9%9C%A7%E6%BF%83%E9%9B%B2%E6%84%81%E6%B0%B8%E6%99%9D%EF%BC%89"}, {"title": "聲聲慢・秋情（尋尋覓覓）", "author": "李清照", "period": "宋", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["尋尋覓覓，冷冷清清，悽悽慘慘戚戚。乍煖還寒時候，最難將息。三杯兩盞淡酒，怎敵他晚來風急！雁過也，正傷心，卻是舊時相識。", "滿地黃花堆積，憔悴損，如今有誰堪摘？守著窗兒，獨自怎生得黑！梧桐更兼細雨，到黃昏、點點滴滴。這次第，怎一箇愁字了得！"], "quote": ["尋尋覓覓，冷冷清清，悽悽慘慘戚戚。乍煖還寒時候，最難將息。三杯兩盞淡酒，怎敵他晚來風急！雁過也，正傷心，卻是舊時相識。", "滿地黃花堆積，憔悴損，如今有誰堪摘？守著窗兒，獨自怎生得黑！梧桐更兼細雨，到黃昏、點點滴滴。這次第，怎一箇愁字了得！"], "intro": "《聲聲慢》，詞牌名，原名《勝勝慢》，最早見於北宋晁補之筆下。後因南宋蔣捷以此調作《秋聲》詞，全用「聲」字收韻，故改稱《聲聲慢》。這首詞作於李清照中年以後寓居臨安時期。李清照此時已經歷過國破家亡，親人離喪的打擊，生活也比以前悽苦得多。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%81%B2%E8%81%B2%E6%85%A2%E3%83%BB%E7%A7%8B%E6%83%85"}, {"title": "病牛", "author": "李綱", "period": "宋", "form": "詩", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["耕犁千畝實千箱，力盡筋疲誰復傷？", "但得眾生皆得飽，不辭羸病臥殘陽。"], "quote": ["耕犁千畝實千箱，力盡筋疲誰復傷？", "但得眾生皆得飽，不辭羸病臥殘陽。"], "intro": "建炎二年（公元1128），李綱為相七十日，罷相流放鄂州（今湖北省武昌市）。四年後，太學生陳東等向朝廷上書請命，要求讓李綱官復原職，事情失敗，陳東也因此被殺，這時的李綱處境更加艱險。這首詩寫於紹興二年（公元1132），是他謫居時心境的真實寫照", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%97%85%E7%89%9B"}, {"title": "摸鐘", "author": "沈括", "period": "宋", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["陳述古密直知建州浦城縣日，有人失物，捕得莫知的為盜者，述古乃紿之曰︰「某廟有一鐘，能辨盜至靈。」使人迎置後閤祠之，引群囚立鐘前，自陳不為盜者，摸之則無聲，為盜者摸之則有聲。述古自率同職，禱鐘甚肅，祭訖，以帷圍之，乃陰使人以墨塗鐘。良久，引囚逐一令引手入帷摸之，出乃驗其手，皆有墨，唯有一囚無墨，訊之，遂承為盜。蓋恐鐘有聲，不敢摸也。"], "quote": ["陳述古密直知建州浦城縣日，有人失物，捕得莫知的為盜者，述古乃紿之曰︰「某廟有一鐘，能辨盜至靈。」使人迎置後閤祠之，引群囚立鐘前，自陳不為盜者，摸之則無聲，為盜者摸之則有聲。述古自率同職，禱鐘甚肅，祭訖，以帷圍之，乃陰使人以墨塗鐘。良久，引囚逐一令引手入帷摸之，出乃驗其手，皆有墨，唯有一囚無墨，訊之，遂承為盜。蓋恐鐘有聲，不敢摸也。"], "intro": "本文選自《夢溪筆談》的《權智》類，主要反映人物的機智和靈活。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%91%B8%E9%90%98"}, {"title": "木蘭花慢（可憐今夕月）", "author": "辛棄疾", "period": "宋", "form": "詞", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["中秋飲酒將旦，客謂前人詩詞有賦待月，無送月者。因用《天問》體賦。", "可憐今夕月，向何處、去悠悠？是別有人間，那邊纔見，光影東頭？是天外，空汗漫，但長風浩浩送中秋？飛鏡無根誰繫？姮娥不嫁誰留？", "謂經海底問無由，恍惚使人愁。怕萬里長鯨，從橫觸破，玉殿瓊樓。蝦蟆故堪浴水，問云何玉兔解沉浮？若道都齊無恙，云何漸漸如鉤？"], "quote": ["中秋飲酒將旦，客謂前人詩詞有賦待月，無送月者。因用《天問》體賦。", "可憐今夕月，向何處、去悠悠？是別有人間，那邊纔見，光影東頭？是天外，空汗漫，但長風浩浩送中秋？飛鏡無根誰繫？姮娥不嫁誰留？", "謂經海底問無由，恍惚使人愁。怕萬里長鯨，從橫觸破，玉殿瓊樓。蝦蟆故堪浴水，問云何玉兔解沉浮？若道都齊無恙，云何漸漸如鉤？"], "intro": "《木蘭花慢》（可憐今夕月）一詞是辛棄疾在上饒帶湖閒居時的作品。詞前有小序，說明是在中秋夜暢飲至快將天亮時，想到前人賦月作品只有待月的，並無送月的，於是仿效屈原《天問》的形式來寫一首送月詞。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9C%A8%E8%98%AD%E8%8A%B1%E6%85%A2%EF%BC%88%E5%8F%AF%E6%86%90%E4%BB%8A%E5%A4%95%E6%9C%88%EF%BC%89"}, {"title": "水龍吟（楚天千里清秋）", "author": "辛棄疾", "period": "宋", "form": "詞", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["登建康賞心亭", "楚天千里清秋，水隨天去秋無際。遙岑遠目，獻愁供恨，玉簪螺髻。落日樓頭，斷鴻聲裏，江南游子。把吳鉤看了，欄干拍徧，無人會、登臨意。", "休說鱸魚堪鱠。儘西風、季鷹歸未。求田問舍，怕應羞見，劉郎才氣。可惜流年，憂愁風雨，樹猶如此！倩何人，喚取盈盈翠袖，搵英雄淚？"], "quote": ["登建康賞心亭", "楚天千里清秋，水隨天去秋無際。遙岑遠目，獻愁供恨，玉簪螺髻。落日樓頭，斷鴻聲裏，江南游子。把吳鉤看了，欄干拍徧，無人會、登臨意。", "休說鱸魚堪鱠。儘西風、季鷹歸未。求田問舍，怕應羞見，劉郎才氣。可惜流年，憂愁風雨，樹猶如此！倩何人，喚取盈盈翠袖，搵英雄淚？"], "intro": "辛棄疾《水龍吟》（楚天千里清秋）選自《全宋詞》。 《水龍吟》，詞題為「登建康賞心亭」，是辛棄疾任江東安撫司時所作。建康即今南京，賞心亭在建康「下水門」城上，臨秦淮河。作者登賞心亭，在一望無際的秋色中，觸景生情，感慨國家偷安一隅和個人報國無門", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B0%B4%E9%BE%8D%E5%90%9F%EF%BC%88%E6%A5%9A%E5%A4%A9%E5%8D%83%E9%87%8C%E6%B8%85%E7%A7%8B%EF%BC%89"}, {"title": "永遇樂（千古江山）", "author": "辛棄疾", "period": "宋", "form": "詞", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["京口北固亭懷古", "千古江山，英雄無覓，孫仲謀處。舞榭歌臺，風流總被，雨打風吹去。斜陽草樹，尋常巷陌，人道寄奴曾住。想當年，金戈鐵馬，氣吞萬里如虎。", "元嘉草草，封狼居胥，贏得倉皇北顧。四十三年，望中猶記，烽火揚州路。可堪回首，佛狸祠下，一片神鴉社鼓。憑誰問，廉頗老矣，尚能飯否？"], "quote": ["京口北固亭懷古", "千古江山，英雄無覓，孫仲謀處。舞榭歌臺，風流總被，雨打風吹去。斜陽草樹，尋常巷陌，人道寄奴曾住。想當年，金戈鐵馬，氣吞萬里如虎。", "元嘉草草，封狼居胥，贏得倉皇北顧。四十三年，望中猶記，烽火揚州路。可堪回首，佛狸祠下，一片神鴉社鼓。憑誰問，廉頗老矣，尚能飯否？"], "intro": "辛棄疾《永遇樂》（千古江山）選自《全宋詞》。 《永遇樂》，詞題作「京口北固亭懷古」。京口，今江蘇鎮江。北固亭在鎮江東北北固山上，面臨長江。此詞作於宋寧宗開禧元年（一二〇五），是年作者六十六歲，任鎮江府知府，正是烈士暮年，壯心未已。此詞雖曰懷", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B0%B8%E9%81%87%E6%A8%82%EF%BC%88%E5%8D%83%E5%8F%A4%E6%B1%9F%E5%B1%B1%EF%BC%89"}, {"title": "青玉案・元夕（東風夜放花千樹）", "author": "辛棄疾", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["東風夜放花千樹，更吹落、星如雨。寶馬雕車香滿路。鳳簫聲動，玉壺光轉，一夜魚龍舞。", "蛾兒雪柳黃金縷，笑語盈盈暗香去。衆裏尋他千百度；驀然回首，那人卻在、燈火闌珊處。"], "quote": ["東風夜放花千樹，更吹落、星如雨。寶馬雕車香滿路。鳳簫聲動，玉壺光轉，一夜魚龍舞。", "蛾兒雪柳黃金縷，笑語盈盈暗香去。衆裏尋他千百度；驀然回首，那人卻在、燈火闌珊處。"], "intro": "《青玉案》，詞牌名，取自東漢張衡《四愁詩》：「美人贈我錦繡段，何以報之青玉案」。「元夕」即元宵節，農曆正月十五日是「上元節」，晚上叫「元夕」、「元宵」或「元夜」，中國自古有元宵觀燈的風俗。 這首《青玉案‧元夕》收錄在在四卷本《稼軒詞》的甲集", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%9D%92%E7%8E%89%E6%A1%88%E3%83%BB%E5%85%83%E5%A4%95%EF%BC%88%E6%9D%B1%E9%A2%A8%E5%A4%9C%E6%94%BE%E8%8A%B1%E5%8D%83%E6%A8%B9%EF%BC%89"}, {"title": "破陣子（醉裏挑燈看劍）", "author": "辛棄疾", "period": "宋", "form": "詞", "theme": "邊塞豪放", "mood": "autumn_sunset", "lines": ["為陳同甫賦壯語以寄", "醉裏挑燈看劍，夢回吹角連營。八百里分麾下炙，五十絃翻塞外聲。沙場秋點兵。", "馬作的盧飛快，弓如霹靂弦驚。了卻君王天下事，贏得生前身後名。可憐白髮生。"], "quote": ["為陳同甫賦壯語以寄", "醉裏挑燈看劍，夢回吹角連營。八百里分麾下炙，五十絃翻塞外聲。沙場秋點兵。", "馬作的盧飛快，弓如霹靂弦驚。了卻君王天下事，贏得生前身後名。可憐白髮生。"], "intro": "《破陣子》（醉裏挑燈看劍）選自《全宋詞》。《破陣子》是詞牌名，本來是唐代教坊曲名，源自龜茲的舞曲。陳同甫，即陳亮，生於宋高宗紹興十三年，卒於宋光宗紹熙五年（一一四三──一一九四），字同甫，南宋時著名思想家和愛國詞人，史稱「為人氣超邁，喜談兵", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%A0%B4%E9%99%A3%E5%AD%90%EF%BC%88%E9%86%89%E8%A3%8F%E6%8C%91%E7%87%88%E7%9C%8B%E5%8A%8D%EF%BC%89"}, {"title": "菩薩蠻（鬱孤臺下清江水）", "author": "辛棄疾", "period": "宋", "form": "詞", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["書江西造口壁", "鬱孤臺下清江水，中間多少行人淚。東北是長安，可憐無數山。", "青山遮不住，畢竟江流去。江晚正愁予，山深聞鷓鴣。"], "quote": ["書江西造口壁", "鬱孤臺下清江水，中間多少行人淚。東北是長安，可憐無數山。", "青山遮不住，畢竟江流去。江晚正愁予，山深聞鷓鴣。"], "intro": "《菩薩蠻》（鬱孤臺下清江水）選自《全宋詞》。《菩薩蠻》是詞牌名，本是唐代教坊曲名。唐宣宗時，女蠻國女子隨使者入貢，謂為「菩薩蠻隊」，教坊樂工依其音樂為「菩薩蠻」曲。宋高宗建炎三年（一一二九），金兵大舉南侵，兵分東西兩路進逼，直抵造口（今江西", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%8F%A9%E8%96%A9%E8%A0%BB%EF%BC%88%E9%AC%B1%E5%AD%A4%E8%87%BA%E4%B8%8B%E6%B8%85%E6%B1%9F%E6%B0%B4%EF%BC%89"}, {"title": "賀新郎（甚矣吾衰矣）", "author": "辛棄疾", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "vast_river", "lines": ["邑中園亭，僕皆為賦此詞。一日，獨坐停雲，水聲山色，競來相娛。意溪山欲援例者。遂作數語，庶幾彷彿淵明思親友之意云。", "甚矣吾衰矣！悵平生、交遊零落，只今餘幾？白髮空垂三千丈，一笑人間萬事。問何物能令公喜？我見青山多嫵媚，料青山、見我應如是。情與貌，略相似。", "一尊搔首東窗裏，想淵明、停雲詩就，此時風味。江左沉酣求名者，豈識濁醪妙理？回首叫雲飛風起。不恨古人吾不見，恨古人、不見吾狂耳。知我者，二三子。"], "quote": ["邑中園亭，僕皆為賦此詞。一日，獨坐停雲，水聲山色，競來相娛。意溪山欲援例者。遂作數語，庶幾彷彿淵明思親友之意云。", "甚矣吾衰矣！悵平生、交遊零落，只今餘幾？白髮空垂三千丈，一笑人間萬事。問何物能令公喜？我見青山多嫵媚，料青山、見我應如是。情與貌，略相似。", "一尊搔首東窗裏，想淵明、停雲詩就，此時風味。江左沉酣求名者，豈識濁醪妙理？回首叫雲飛風起。不恨古人吾不見，恨古人、不見吾狂耳。知我者，二三子。"], "intro": "《賀新郎》是詞牌名，又名《金縷曲》、《乳燕飛》等。此調最早見於《東坡樂府》所收蘇軾詞，原名《賀新涼》，後來將「涼」字誤作「郎」字。 據鄧廣銘《稼軒詞編年箋注》考證 ，此詞約作於宋寧宗慶元四年（一一九八）左右。辛棄疾投奔南宋後，最初雖得到宋主", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B3%80%E6%96%B0%E9%83%8E%EF%BC%88%E7%94%9A%E7%9F%A3%E5%90%BE%E8%A1%B0%E7%9F%A3%EF%BC%89"}, {"title": "摸魚兒（更能消幾番風雨）", "author": "辛棄疾", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "vast_river", "lines": ["淳熙己亥，自湖北漕移湖南，同官王正之置酒小山亭，為賦。", "更能消、幾番風雨！怱怱春又歸去。惜春長恨花開早，何況落紅無數？春且住！見說道、天涯芳草迷歸路。怨春不語。算只有殷勤，畫簷蛛網，盡日惹飛絮。", "長門事，準擬佳期又誤。蛾眉曾有人妒。千金縱買相如賦，脈脈此情誰訴？君莫舞！君不見、玉環飛燕皆塵土？閒愁最苦。休去倚危樓，斜陽正在，煙柳斷腸處！"], "quote": ["淳熙己亥，自湖北漕移湖南，同官王正之置酒小山亭，為賦。", "更能消、幾番風雨！怱怱春又歸去。惜春長恨花開早，何況落紅無數？春且住！見說道、天涯芳草迷歸路。怨春不語。算只有殷勤，畫簷蛛網，盡日惹飛絮。", "長門事，準擬佳期又誤。蛾眉曾有人妒。千金縱買相如賦，脈脈此情誰訴？君莫舞！君不見、玉環飛燕皆塵土？閒愁最苦。休去倚危樓，斜陽正在，煙柳斷腸處！"], "intro": "辛棄疾《摸魚兒》（更能消幾番風雨）選自《全宋詞》。 《摸魚兒》又名《摸魚子》，本為唐玄宗時教坊曲名。宋孝宗淳熙六年（一一七九），作者從湖北調任湖南轉運副使，在小山亭與友人王正之置酒餞別，寫下此詞。詞中抒發了作者被朝中權臣排擠，有志難伸的憤慨", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%91%B8%E9%AD%9A%E5%85%92%EF%BC%88%E6%9B%B4%E8%83%BD%E6%B6%88%E5%B9%BE%E7%95%AA%E9%A2%A8%E9%9B%A8%EF%BC%89"}, {"title": "醜奴兒（少年不識愁滋味）", "author": "辛棄疾", "period": "宋", "form": "詞", "theme": "山水登臨", "mood": "autumn_sunset", "lines": ["書博山道中壁", "少年不識愁滋味，愛上層樓，愛上層樓，為賦新詞強說愁。", "而今識盡愁滋味，欲說還休，欲說還休，卻道天涼好個秋。"], "quote": ["書博山道中壁", "少年不識愁滋味，愛上層樓，愛上層樓，為賦新詞強說愁。", "而今識盡愁滋味，欲說還休，欲說還休，卻道天涼好個秋。"], "intro": "《醜奴兒》是詞牌名，通稱《採桑子》。這首詞是辛棄疾被劾去職，閒居帶湖時所作，他雖常閒遊於博山道中，卻念念不忘國家大事，因此心中非常愁悶。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%86%9C%E5%A5%B4%E5%85%92%EF%BC%88%E5%B0%91%E5%B9%B4%E4%B8%8D%E8%AD%98%E6%84%81%E6%BB%8B%E5%91%B3%EF%BC%89"}, {"title": "六醜・落花", "author": "周邦彥", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "vast_river", "lines": ["正單衣試酒，恨客裏光陰虛擲。願春暫留，春歸如過翼，一去無跡！為問花何在，夜來風雨，葬楚宮傾國。釵鈿墮處遺香澤，亂點桃蹊，輕翻柳陌，多情更誰追惜？但蜂媒蝶使，時叩窗隔。", "東園岑寂，漸蒙籠暗碧。靜繞珍叢底，成嘆息。長條故惹行客，似牽衣待話，別情無極。殘英小，強簪巾幘，終不似一朵釵頭顫裊，向人欹側。漂流處，莫趁潮汐；恐斷紅尚有相思字，何由見得？"], "quote": ["正單衣試酒，恨客裏光陰虛擲。願春暫留，春歸如過翼，一去無跡！為問花何在，夜來風雨，葬楚宮傾國。釵鈿墮處遺香澤，亂點桃蹊，輕翻柳陌，多情更誰追惜？但蜂媒蝶使，時叩窗隔。", "東園岑寂，漸蒙籠暗碧。靜繞珍叢底，成嘆息。長條故惹行客，似牽衣待話，別情無極。殘英小，強簪巾幘，終不似一朵釵頭顫裊，向人欹側。漂流處，莫趁潮汐；恐斷紅尚有相思字，何由見得？"], "intro": "《六醜》，乃作者自製的一支新詞牌，在他以前並無此調。據陳元龍注，「醜」字作「類」解；周密《癸辛雜志》說，「徽宗周邦彥六醜之義，對曰：『此犯六調，皆聲之美者；然絕難歌。』」按此，六醜乃截取六種宮調中最佳部份拼揍而成，相當於「集曲」。題下注為「", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%85%AD%E9%86%9C%E3%83%BB%E8%90%BD%E8%8A%B1"}, {"title": "少年遊（幷刀如水）", "author": "周邦彥", "period": "宋", "form": "詞", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["幷刀如水，吳鹽勝雪，纖手破新橙。錦幄初溫，獸香不斷，相對坐調笙。", "低聲問，向誰行宿，城上已三更。馬滑霜濃，不如休去，直是少人行。"], "quote": ["幷刀如水，吳鹽勝雪，纖手破新橙。錦幄初溫，獸香不斷，相對坐調笙。", "低聲問，向誰行宿，城上已三更。馬滑霜濃，不如休去，直是少人行。"], "intro": "根據張瑞義《貴耳集》載：「道君（宋徽宗）幸李師師家，偶周邦彥先在焉。知道君至，遂匿於床下。道君自攜新橙一顆云：『江南初進來。』遂與師師謔語。邦彥悉聞之。隱括成《少年遊》。」下並有邦彥之獲罪，始遭斥逐，終復獲赦種種曲折敍述。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B0%91%E5%B9%B4%E9%81%8A%EF%BC%88%E5%B9%B7%E5%88%80%E5%A6%82%E6%B0%B4%EF%BC%89"}, {"title": "西河・金陵懷古（佳麗地）", "author": "周邦彥", "period": "宋", "form": "詞", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["佳麗地，南朝盛事誰記？山圍故國遶清江，髻鬟對起。怒濤寂寞打孤城，風檣遙度天際。", "斷崖樹，猶倒倚，莫愁艇子曾繫。空餘舊跡鬱蒼蒼，霧沈半壘。夜深月過女牆來，傷心東望淮水。", "酒旗戲鼓甚處市？想依稀、王謝鄰里。燕子不知何世，向尋常巷陌人家，相對如說興亡，斜陽裡。"], "quote": ["佳麗地，南朝盛事誰記？山圍故國遶清江，髻鬟對起。怒濤寂寞打孤城，風檣遙度天際。", "斷崖樹，猶倒倚，莫愁艇子曾繫。空餘舊跡鬱蒼蒼，霧沈半壘。夜深月過女牆來，傷心東望淮水。", "酒旗戲鼓甚處市？想依稀、王謝鄰里。燕子不知何世，向尋常巷陌人家，相對如說興亡，斜陽裡。"], "intro": "西河是詞調名。《碧雞漫志》記載唐大曆初，有樂工取古《西河長命女》加減節奏而成新聲。本題為「金陵懷古」，當作於金陵。近人羅慷烈認為是周邦彥作於溧水任內（公元1093——1096），屬晚年的作品。周邦彥於哲宗元祐八年（公元1093）知溧水縣，至", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A5%BF%E6%B2%B3%E3%83%BB%E9%87%91%E9%99%B5%E6%87%B7%E5%8F%A4%EF%BC%88%E4%BD%B3%E9%BA%97%E5%9C%B0%EF%BC%89%C2%A0"}, {"title": "蘇幕遮・般涉（燎沈香）", "author": "周邦彥", "period": "宋", "form": "詞", "theme": "江河湖海", "mood": "vast_river", "lines": ["燎沈香，消溽暑。鳥雀呼晴，侵曉窺簷語。葉上初陽乾宿雨、水面清圓，一一風荷舉。", "故鄉遙，何日去。家住吳門，久作長安旅。五月漁郎相憶否？小楫輕舟，夢入芙蓉浦。"], "quote": ["燎沈香，消溽暑。鳥雀呼晴，侵曉窺簷語。葉上初陽乾宿雨、水面清圓，一一風荷舉。", "故鄉遙，何日去。家住吳門，久作長安旅。五月漁郎相憶否？小楫輕舟，夢入芙蓉浦。"], "intro": "周邦彥《蘇幕遮・般涉》選自《全宋詞》。 《蘇幕遮》，詞牌名，本為唐玄宗時教坊曲名，來自西域。《新唐書‧宋務光傳》載呂元泰上唐中宗書曰：「比見坊邑相率為渾脫隊，駿馬胡服，名曰『蘇莫遮』。」渾脫是舞名，渾脫隊即歌舞隊，可見《蘇幕遮》原是胡人舞曲", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%98%87%E5%B9%95%E9%81%AE%E3%83%BB%E8%88%AC%E6%B6%89%EF%BC%88%E7%87%8E%E6%B2%88%E9%A6%99%EF%BC%89"}, {"title": "蘭陵王・越調・柳（柳陰直）", "author": "周邦彥", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["柳陰直。煙裏絲絲弄碧。隋堤上、曾見幾番，拂水飄綿送行色。登臨望故國。誰識、京華倦客？長亭路，年去歲來，應折柔條過千尺。", "閒尋舊蹤跡。又酒趁哀絃，燈照離席。梨花榆火催寒食。愁一箭風快，半篙波暖，回頭迢遞便數驛。望人在天北。", "悽惻、恨堆積！漸別浦縈回，津堠岑寂。斜陽冉冉春無極。念月榭攜手，露橋聞笛。沈思前事，似夢裏，淚暗滴。"], "quote": ["柳陰直。煙裏絲絲弄碧。隋堤上、曾見幾番，拂水飄綿送行色。登臨望故國。誰識、京華倦客？長亭路，年去歲來，應折柔條過千尺。", "閒尋舊蹤跡。又酒趁哀絃，燈照離席。梨花榆火催寒食。愁一箭風快，半篙波暖，回頭迢遞便數驛。望人在天北。", "悽惻、恨堆積！漸別浦縈回，津堠岑寂。斜陽冉冉春無極。念月榭攜手，露橋聞笛。沈思前事，似夢裏，淚暗滴。"], "intro": "周邦彥《蘭陵王・越調・柳》選自《全宋詞》。 《蘭陵王》本屬北齊舞曲，是為仿效蘭陵王高長恭勇冠三軍之態而作。周邦彥此篇用舊曲填新詞，仍沿用《蘭陵王》做詞牌名。又因《蘭陵王》分三片，多在送別時唱，故稱《渭城三疊》。周邦彥此詞的詞題是「柳」，實為", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%98%AD%E9%99%B5%E7%8E%8B%E3%83%BB%E8%B6%8A%E8%AA%BF%E3%83%BB%E6%9F%B3%EF%BC%88%E6%9F%B3%E9%99%B0%E7%9B%B4%EF%BC%89"}, {"title": "浙江之潮", "author": "周密", "period": "宋", "form": "文", "theme": "江河湖海", "mood": "snow_winter", "lines": ["浙江之潮，天下之偉觀也。自既望以至十八日為最盛。方其遠出海門，僅如銀線，既而漸近，則玉城雪嶺，際天而來，大聲如雷霆，震撼激射，吞天沃日，勢極雄豪。楊誠齋詩云︰「海湧銀為郭，江橫玉繫腰」者是也。"], "quote": ["浙江之潮，天下之偉觀也。自既望以至十八日為最盛。方其遠出海門，僅如銀線，既而漸近，則玉城雪嶺，際天而來，大聲如雷霆，震撼激射，吞天沃日，勢極雄豪。楊誠齋詩云︰「海湧銀為郭，江橫玉繫腰」者是也。"], "intro": "本文選自《武林舊事》卷三。該書追憶南宋都城杭州故事，涉及南宋的典章制度、杭州山川、風俗、市肆等方面，共十卷。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B5%99%E6%B1%9F%E4%B9%8B%E6%BD%AE"}, {"title": "愛蓮說", "author": "周敦頤", "period": "宋", "form": "文", "theme": "春水花鳥", "mood": "vast_river", "lines": ["水陸草木之花，可愛者甚蕃；晉陶淵明獨愛菊。自李唐來，世人甚愛牡丹。予獨愛蓮之出淤泥而不染，濯清漣而不妖；中通外直，不蔓不枝；香遠益清，亭亭淨植，可遠觀而不可褻玩焉。", "予謂︰菊，花之隱逸者也；牡丹，花之富貴者也；蓮，花之君子者也。噫！菊之愛，陶後鮮有聞；蓮之愛，同予者何人？牡丹之愛，宜乎眾矣！"], "quote": ["水陸草木之花，可愛者甚蕃；晉陶淵明獨愛菊。自李唐來，世人甚愛牡丹。予獨愛蓮之出淤泥而不染，濯清漣而不妖；中通外直，不蔓不枝；香遠益清，亭亭淨植，可遠觀而不可褻玩焉。", "予謂︰菊，花之隱逸者也；牡丹，花之富貴者也；蓮，花之君子者也。噫！菊之愛，陶後鮮有聞；蓮之愛，同予者何人？牡丹之愛，宜乎眾矣！"], "intro": "周敦頤是北宋理學濂洛學派創始人，他品德高尚，為官清廉，不媚權貴。嘉祐六年（1061）至治平元年（1064）周敦頤任虔州通判時，建有蓮池，並於嘉祐八年（1063）五月在此揮筆寫下《愛蓮說》。北宋中葉享樂之風盛行，不少士人只追求富貴利達，周敦頤", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%84%9B%E8%93%AE%E8%AA%AA"}, {"title": "滿江紅（怒髮衝冠）", "author": "岳飛", "period": "宋", "form": "詞", "theme": "江河湖海", "mood": "snow_winter", "lines": ["怒髮衝冠！憑闌處瀟瀟雨歇。抬望眼，仰天長嘯，壯懷激烈。三十功名塵與土，八千里路雲和月。莫等閒白了少年頭，空悲切！", "靖康恥，猶未雪；臣子恨，何時滅？駕長車，踏破賀蘭山缺。壯志飢餐胡虜肉，笑談渴飲匈奴血。待從頭收拾舊山河，朝天闕。"], "quote": ["怒髮衝冠！憑闌處瀟瀟雨歇。抬望眼，仰天長嘯，壯懷激烈。三十功名塵與土，八千里路雲和月。莫等閒白了少年頭，空悲切！", "靖康恥，猶未雪；臣子恨，何時滅？駕長車，踏破賀蘭山缺。壯志飢餐胡虜肉，笑談渴飲匈奴血。待從頭收拾舊山河，朝天闕。"], "intro": "本篇是一首詞；詞是從舊詩中分化出來的一種詩歌，有一定的調子，可以譜上音樂歌唱。每一詞調，有一個名稱，也叫做詞牌，作詞的人都習慣地即用為詞的標題。至於詞牌的名稱究竟創自何人，很難查考，綜合歷代詞書研究，大抵有下列數端：（一）取諸琴曲樂府；（二", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%BB%BF%E6%B1%9F%E7%B4%85%EF%BC%88%E6%80%92%E9%AB%AE%E8%A1%9D%E5%86%A0%EF%BC%89"}, {"title": "題臨安邸", "author": "林升", "period": "宋", "form": "詩", "theme": "江河湖海", "mood": "vast_river", "lines": ["山外青山樓外樓，西湖歌舞幾時休！", "暖風熏得遊人醉，直把杭州作汴州。"], "quote": ["山外青山樓外樓，西湖歌舞幾時休！", "暖風熏得遊人醉，直把杭州作汴州。"], "intro": "公元1127年，金人攻破北宋都城汴梁，並俘虜了徽、欽二帝，康王趙構（宋高宗）逃到江南，後在臨安（即今浙江省杭州市）定都，建立了偏安一隅的南宋朝廷。南宋統治者不思收復失地，也忘記了亡國之恨，在臨安大修宮殿廟堂，富商大賈也在此經營宅第。幾十年來", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%A1%8C%E8%87%A8%E5%AE%89%E9%82%B8"}, {"title": "名落孫山", "author": "范公偁", "period": "宋", "form": "文", "theme": "山水登臨", "mood": "majestic_peaks", "lines": ["孫山，滑稽才子也。赴舉時，鄉人托以子偕往。榜發，鄉人子失意，山綴榜末先歸。鄉人問其子得失，山曰︰「解名盡處是孫山，賢郎更在孫山外。」"], "quote": ["孫山，滑稽才子也。赴舉時，鄉人托以子偕往。榜發，鄉人子失意，山綴榜末先歸。鄉人問其子得失，山曰︰「解名盡處是孫山，賢郎更在孫山外。」"], "intro": "本文選自《過庭錄》其中一節。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%90%8D%E8%90%BD%E5%AD%AB%E5%B1%B1"}, {"title": "岳陽樓記", "author": "范仲淹", "period": "宋", "form": "文", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["慶曆四年春，滕子京謫守巴陵郡。越明年，政通人和，百廢具興。乃重修岳陽樓，增其舊制，刻唐賢今人詩賦於其上；屬予作文以記之。", "予觀夫巴陵勝狀，在洞庭一湖，銜遠山，吞長江，浩浩湯湯，橫無際涯，朝暉夕陰，氣象萬千，此則岳陽樓之大觀也；前人之述備矣。", "然則北通巫峽，南極瀟湘，遷客騷人，多會於此，覽物之情，得無異乎？", "若夫霪雨霏霏，連月不開，陰風怒號，濁浪排空，日星隱曜，山岳潛形；商旅不行，檣傾楫摧；薄暮冥冥，虎嘯猿啼；登斯樓也，則有去國懷鄉，憂讒畏譏，滿目蕭然，感極而悲者矣！", "至若春和景明，波瀾不驚，上下天光，一碧萬頃，沙鷗翔集，錦鱗游泳，岸芷汀蘭，郁郁青青；而或長煙一空，皓月千里，浮光耀金，靜影沈璧，漁歌互答，此樂何極！", "登斯樓也，則有心曠神怡，寵辱皆忘，把酒臨風，其喜洋洋者矣！", "嗟夫！予嘗求古仁人之心，或異二者之為，何哉？不以物喜，不以己悲。居廟堂之高，則憂其民，處江湖之遠，則憂其君，是進亦憂，退亦憂。", "然則何時而樂耶？其必曰「先天下之憂而憂，後天下之樂而樂」歟！噫，微斯人，吾誰與歸！"], "quote": ["慶曆四年春，滕子京謫守巴陵郡。越明年，政通人和，百廢具興。乃重修岳陽樓，增其舊制，刻唐賢今人詩賦於其上；屬予作文以記之。", "予觀夫巴陵勝狀，在洞庭一湖，銜遠山，吞長江，浩浩湯湯，橫無際涯，朝暉夕陰，氣象萬千，此則岳陽樓之大觀也；前人之述備矣。", "然則北通巫峽，南極瀟湘，遷客騷人，多會於此，覽物之情，得無異乎？", "若夫霪雨霏霏，連月不開，陰風怒號，濁浪排空，日星隱曜，山岳潛形；商旅不行，檣傾楫摧；薄暮冥冥，虎嘯猿啼；登斯樓也，則有去國懷鄉，憂讒畏譏，滿目蕭然，感極而悲者矣！"], "intro": "岳陽樓在湖南岳陽，樓高三層，下臨洞庭湖，相傳其前身為三國時期吳國都督魯肅的閱兵臺。現時的岳陽樓，則為唐玄宗開元四年（公元716年），張説謫守岳州時，在閱兵臺舊址所建。至北宋慶曆四年（公元1044年），滕子京被貶到岳州巴陵郡為太守，第二年重修", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B2%B3%E9%99%BD%E6%A8%93%E8%A8%98"}, {"title": "漁家傲・秋思（塞下秋來風景異）", "author": "范仲淹", "period": "宋", "form": "詞", "theme": "邊塞豪放", "mood": "snow_winter", "lines": ["塞下秋來風景異，衡陽雁去無留意。四面邊聲連角起，千嶂裏，長煙落日孤城閉。", "濁酒一杯家萬里，燕然未勒歸無計。羌管悠悠霜滿地。人不寐，將軍白髮征夫淚。"], "quote": ["塞下秋來風景異，衡陽雁去無留意。四面邊聲連角起，千嶂裏，長煙落日孤城閉。", "濁酒一杯家萬里，燕然未勒歸無計。羌管悠悠霜滿地。人不寐，將軍白髮征夫淚。"], "intro": "《漁家傲》（塞下秋來風景異）選自《全宋詞》。《漁家傲》是詞牌名，「秋思」是詞題。此調始於北宋晏殊，因他的詞中有「神仙一曲漁家傲」之句，遂取以為名。後因填此調者特多，遂成為詞牌名。北宋仁宗時，崛起於西北的西夏不斷侵擾中原，寶元三年（一〇四〇）", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%BC%81%E5%AE%B6%E5%82%B2%E3%83%BB%E7%A7%8B%E6%80%9D%EF%BC%88%E5%A1%9E%E4%B8%8B%E7%A7%8B%E4%BE%86%E9%A2%A8%E6%99%AF%E7%95%B0%EF%BC%89"}, {"title": "蘇幕遮・懷舊（碧雲天）", "author": "范仲淹", "period": "宋", "form": "詞", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["碧雲天，黃葉地。秋色連波，波上寒煙翠。山映斜陽天接水，芳草無情，更在斜陽外。", "黯鄉魂，追旅思，夜夜除非，好夢留人睡。明月樓高休獨倚，酒入愁腸，化作相思淚。"], "quote": ["碧雲天，黃葉地。秋色連波，波上寒煙翠。山映斜陽天接水，芳草無情，更在斜陽外。", "黯鄉魂，追旅思，夜夜除非，好夢留人睡。明月樓高休獨倚，酒入愁腸，化作相思淚。"], "intro": "《蘇幕遮》（碧雲天）選自《全宋詞》。《蘇幕遮》是詞牌名，本是唐宮廷教坊演奏的舞曲，因傳自西域的龜茲國，故又稱胡樂。「懷舊」是詞題，《花庵詞選》題作「別恨」。范仲淹這首詞抒寫羈旅情思，上片寫碧雲、黃葉、翠煙，以色澤來渲染夕陽下的秋景，為下片言", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%98%87%E5%B9%95%E9%81%AE%E3%83%BB%E6%87%B7%E8%88%8A%EF%BC%88%E7%A2%A7%E9%9B%B2%E5%A4%A9%EF%BC%89"}, {"title": "四時田園雜興（夏・其七）", "author": "范成大", "period": "宋", "form": "詩", "theme": "田園幽居", "mood": "vast_river", "lines": ["晝出耘田夜績麻，村莊兒女各當家。", "童孫未解供耕織，也傍桑陰學種瓜。"], "quote": ["晝出耘田夜績麻，村莊兒女各當家。", "童孫未解供耕織，也傍桑陰學種瓜。"], "intro": "范成大《四時田園雜興》選自《石湖居士詩集》卷二十七。宋孝宗淳熙十三年（一一八六），作者在蘇州石湖養病期間，以農村生活為題材，寫了六十首絕句。小引云：「淳熙丙午，沉疴少紓，復至石湖舊隱，野外即事，輒書一絕，終歲得六十篇，號《四時田園雜興》。」", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%9B%9B%E6%99%82%E7%94%B0%E5%9C%92%E9%9B%9C%E8%88%88%EF%BC%88%E5%A4%8F%E3%83%BB%E5%85%B6%E4%B8%83%EF%BC%89"}, {"title": "揚州慢（淮左名都）", "author": "姜夔", "period": "宋", "form": "詞", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["淳熙丙申至日，予過維揚。夜雪初霽，薺麥彌望。入其城，則四顧蕭條，寒水自碧，暮色漸起，戍角悲吟。予懷愴然，感慨今昔，因自度此曲。千巖老人以為有黍離之悲也。", "淮左名都，竹西佳處，解鞍少駐初程。過春風十里，盡薺麥青青。自胡馬窺江去後，廢池喬木，猶厭言兵。漸黃昏，清角吹寒，都在空城。", "杜郎俊賞，算而今、重到須驚。縱豆蔻詞工，青樓夢好，難賦深情。二十四橋仍在，波心蕩、冷月無聲。念橋邊紅藥，年年知為誰生？"], "quote": ["淳熙丙申至日，予過維揚。夜雪初霽，薺麥彌望。入其城，則四顧蕭條，寒水自碧，暮色漸起，戍角悲吟。予懷愴然，感慨今昔，因自度此曲。千巖老人以為有黍離之悲也。", "淮左名都，竹西佳處，解鞍少駐初程。過春風十里，盡薺麥青青。自胡馬窺江去後，廢池喬木，猶厭言兵。漸黃昏，清角吹寒，都在空城。", "杜郎俊賞，算而今、重到須驚。縱豆蔻詞工，青樓夢好，難賦深情。二十四橋仍在，波心蕩、冷月無聲。念橋邊紅藥，年年知為誰生？"], "intro": "姜夔《揚州慢》（淮左名都）選自《全宋詞》。 《揚州慢》是姜夔自度之曲，慢是慢曲子的簡稱，即聲調和字句都加長了。揚州，即今江蘇揚州，是隋唐時代的繁華都市。宋高宗建炎三年（一一二九）和紹興三十一年（一一六一），揚州先後遭到金兵洗劫。作者於宋孝宗", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%8F%9A%E5%B7%9E%E6%85%A2%EF%BC%88%E6%B7%AE%E5%B7%A6%E5%90%8D%E9%83%BD%EF%BC%89"}, {"title": "八聲甘州（對瀟瀟暮雨灑江天）", "author": "柳永", "period": "宋", "form": "詞", "theme": "江河湖海", "mood": "snow_winter", "lines": ["對瀟瀟暮雨灑江天，一番洗清秋。漸霜風淒慘，關河冷落，殘照當樓。是處紅衰翠減，苒苒物華休。惟有長江水，無語東流。", "不忍登高臨遠，望故鄉渺邈，歸思難收。歎年來蹤迹，何事苦淹留！想佳人、妝樓顒望，誤幾回、天際識歸舟。爭知我、倚闌干處，正恁凝愁？"], "quote": ["對瀟瀟暮雨灑江天，一番洗清秋。漸霜風淒慘，關河冷落，殘照當樓。是處紅衰翠減，苒苒物華休。惟有長江水，無語東流。", "不忍登高臨遠，望故鄉渺邈，歸思難收。歎年來蹤迹，何事苦淹留！想佳人、妝樓顒望，誤幾回、天際識歸舟。爭知我、倚闌干處，正恁凝愁？"], "intro": "柳永《八聲甘州》（對瀟瀟暮雨灑江天）取自《全宋詞》。 《八聲甘州》，一名《甘州》，也是唐玄宗時教坊大曲名，來自西域。曲譜為西涼人所創，後人據以填詞，遂演為詞調。此調前後段共八韻，故又名《八聲甘州》。柳永此詞以第一人稱寫作，前片寫景，皆眼前事", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%85%AB%E8%81%B2%E7%94%98%E5%B7%9E%EF%BC%88%E5%B0%8D%E7%80%9F%E7%80%9F%E6%9A%AE%E9%9B%A8%E7%81%91%E6%B1%9F%E5%A4%A9%EF%BC%89"}, {"title": "雨霖鈴（寒蟬淒切）", "author": "柳永", "period": "宋", "form": "詞", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["寒蟬淒切，對長亭晚，驟雨初歇。都門帳飲無緒，留戀處，蘭舟催發。執手相看淚眼，竟無語凝噎。念去去、千里煙波，暮靄沉沉楚天闊。", "多情自古傷離別，更那堪、冷落清秋節。今宵酒醒何處？楊柳岸、曉風殘月。此去經年，應是良辰好景虛設。便縱有、千種風情，更與何人說！"], "quote": ["寒蟬淒切，對長亭晚，驟雨初歇。都門帳飲無緒，留戀處，蘭舟催發。執手相看淚眼，竟無語凝噎。念去去、千里煙波，暮靄沉沉楚天闊。", "多情自古傷離別，更那堪、冷落清秋節。今宵酒醒何處？楊柳岸、曉風殘月。此去經年，應是良辰好景虛設。便縱有、千種風情，更與何人說！"], "intro": "《雨霖鈴》為詞牌名，又名《雨淋鈴》。原為唐代教坊歌曲。相傳唐玄宗避安史之亂入蜀，被迫在馬嵬坡賜死楊貴妃。叛亂平定後，玄宗北還，路途中遇雨聞鈴而思念貴妃，故作此曲。曲調本身具有哀傷的成分。 這首詞是柳永離開都城汴京（今河南開封）南下時所寫惜別", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%9B%A8%E9%9C%96%E9%88%B4%EF%BC%88%E5%AF%92%E8%9F%AC%E6%B7%92%E5%88%87%EF%BC%89"}, {"title": "望海潮（東南形勝）", "author": "柳永", "period": "宋", "form": "詞", "theme": "江河湖海", "mood": "snow_winter", "lines": ["東南形勝，三吳都會，錢塘自古繁華。煙柳畫橋，風簾翠幕，參差十萬人家。雲樹繞堤沙，怒濤卷霜雪，天塹無涯。市列珠璣，戶盈羅綺，競豪奢。", "重湖疊巘清嘉，有三秋桂子，十里荷花。羌管弄晴，菱歌泛夜，嬉嬉釣叟蓮娃。千騎擁高牙，乘醉聽簫鼓，吟賞煙霞。異日圖將好景，歸去鳳池誇。"], "quote": ["東南形勝，三吳都會，錢塘自古繁華。煙柳畫橋，風簾翠幕，參差十萬人家。雲樹繞堤沙，怒濤卷霜雪，天塹無涯。市列珠璣，戶盈羅綺，競豪奢。", "重湖疊巘清嘉，有三秋桂子，十里荷花。羌管弄晴，菱歌泛夜，嬉嬉釣叟蓮娃。千騎擁高牙，乘醉聽簫鼓，吟賞煙霞。異日圖將好景，歸去鳳池誇。"], "intro": "「望海潮」是詞調名，首見於柳永的《樂章集》。 宋真宗咸平（九九八──一〇〇四）末至景德（一〇〇四──一〇〇八）初，柳永的布衣之交孫何出任兩浙轉運使。由於門禁森嚴，二人無法會見。傳說柳永於中秋之夜，請歌妓楚楚在孫何面前演唱了自己的這首詞，孫何", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9C%9B%E6%B5%B7%E6%BD%AE%EF%BC%88%E6%9D%B1%E5%8D%97%E5%BD%A2%E5%8B%9D%EF%BC%89"}, {"title": "蝶戀花（佇倚危樓風細細）", "author": "柳永", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["佇倚危樓風細細。望極春愁，黯黯生天際。草色煙光殘照裏，無言誰會憑闌意。", "擬把疏狂圖一醉。對酒當歌，強樂還無味。衣帶漸寬終不悔，為伊消得人憔悴。"], "quote": ["佇倚危樓風細細。望極春愁，黯黯生天際。草色煙光殘照裏，無言誰會憑闌意。", "擬把疏狂圖一醉。對酒當歌，強樂還無味。衣帶漸寬終不悔，為伊消得人憔悴。"], "intro": "《蝶戀花》，原唐教坊曲名，後用作詞牌名，又名《鳳棲梧》《鵲踏枝》。 《蝶戀花》（佇倚危樓風細細）是一首懷人之作，大概作於宋真宗咸平五年（一〇〇二）之後，具體創作時間不詳。當時柳永過着漂泊的生活，與意中人分離而作懷念之詞。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%9D%B6%E6%88%80%E8%8A%B1%EF%BC%88%E4%BD%87%E5%80%9A%E5%8D%B1%E6%A8%93%E9%A2%A8%E7%B4%B0%E7%B4%B0%EF%BC%89"}, {"title": "好事近", "author": "胡詮", "period": "宋", "form": "詞", "theme": "送別行旅", "mood": "autumn_sunset", "lines": ["富貴本無心，何事故鄉輕別？空使猿驚鶴怨，誤薜蘿秋月。", "囊錐剛要出頭來，不道甚時節。欲駕巾車歸去，有豺狼當轍！"], "quote": ["富貴本無心，何事故鄉輕別？空使猿驚鶴怨，誤薜蘿秋月。", "囊錐剛要出頭來，不道甚時節。欲駕巾車歸去，有豺狼當轍！"], "intro": "胡銓因上書反對與金人議和、請斬秦檜等奸賊而得罪編管新州（今廣東新興一帶）。據《宋史》本傳記載，高宗紹興十八年（一一四八），新州守官又告發他「與客唱酬，謗訕怨望」，於是，他「罪」上加「罪」，被謫往更為僻遠蠻荒的吉陽軍（今海南島的最南端）。所謂", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%A5%BD%E4%BA%8B%E8%BF%91"}, {"title": "浣溪沙（一曲新詞酒一盃）", "author": "晏殊", "period": "宋", "form": "詞", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["一曲新詞酒一盃。去年天氣舊亭臺。夕陽西下幾時迴？", "無可奈何花落去，似曾相識燕歸來！小園香徑獨徘徊。"], "quote": ["一曲新詞酒一盃。去年天氣舊亭臺。夕陽西下幾時迴？", "無可奈何花落去，似曾相識燕歸來！小園香徑獨徘徊。"], "intro": "晏殊《浣溪沙》（一曲新詞酒一杯）選自《全宋詞》。 《浣溪沙》，唐玄宗時教坊曲名，後用為詞調名。沙，一作紗。此詞寫暮春傍晚，酒後獨步園中的心境。上片寫懷舊，下片寫惜春，詞中無一字哀怨，而惆悵之情，則隱寓其中。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B5%A3%E6%BA%AA%E6%B2%99%EF%BC%88%E4%B8%80%E6%9B%B2%E6%96%B0%E8%A9%9E%E9%85%92%E4%B8%80%E7%9B%83%EF%BC%89"}, {"title": "臨江仙（夢後樓臺高鎖）", "author": "晏幾道", "period": "宋", "form": "詞", "theme": "江河湖海", "mood": "vast_river", "lines": ["夢後樓臺高鎖，酒醒簾幕低垂。去年春恨卻來時。落花人獨立，微雨燕雙飛。", "記得小蘋初見，兩重心字羅衣。琵琶絃上說相思。當時明月在，曾照彩雲歸。"], "quote": ["夢後樓臺高鎖，酒醒簾幕低垂。去年春恨卻來時。落花人獨立，微雨燕雙飛。", "記得小蘋初見，兩重心字羅衣。琵琶絃上說相思。當時明月在，曾照彩雲歸。"], "intro": "晏幾道《臨江仙》（夢後樓臺高鎖）選自《全宋詞》。 《臨江仙》是唐玄宗時的教坊曲名，後用為詞調，屬於令詞。晏幾道填此以懷念歌女小蘋。上片先寫酒醒夢覺的淒寂，繼寫別恨，落花二句，雖全襲前人詩句，而移用甚為妥貼，更能顯出作者所處情景。下片懷人，情", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%87%A8%E6%B1%9F%E4%BB%99%EF%BC%88%E5%A4%A2%E5%BE%8C%E6%A8%93%E8%87%BA%E9%AB%98%E9%8E%96%EF%BC%89"}, {"title": "鷓鴣天（彩袖殷勤捧玉鍾）", "author": "晏幾道", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["彩袖殷勤捧玉鍾。當年拚卻醉顏紅。舞低楊柳樓心月，歌盡桃花扇影風。", "從別後，憶相逢。幾回魂夢與君同。今宵賸把銀釭照，猶恐相逢是夢中！"], "quote": ["彩袖殷勤捧玉鍾。當年拚卻醉顏紅。舞低楊柳樓心月，歌盡桃花扇影風。", "從別後，憶相逢。幾回魂夢與君同。今宵賸把銀釭照，猶恐相逢是夢中！"], "intro": "晏幾道《鷓鴣天》（彩袖殷勤捧玉鍾）選自《全宋詞》。 《鷓鴣天》，唐、五代詞中無此調，首見於北宋宋祁之作，至晏殊、晏幾道時用此調漸多。此詞上片追憶歡樂的往事，下片寫意外重逢的喜悅。全詞結構嚴謹，為小令賦懷絕妙之作。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%B7%93%E9%B4%A3%E5%A4%A9%EF%BC%88%E5%BD%A9%E8%A2%96%E6%AE%B7%E5%8B%A4%E6%8D%A7%E7%8E%89%E9%8D%BE%EF%BC%89"}, {"title": "踏莎行（霧失樓臺）", "author": "秦觀", "period": "宋", "form": "詞", "theme": "江河湖海", "mood": "snow_winter", "lines": ["霧失樓臺，月迷津渡。桃源望斷無尋處。可堪孤館閉春寒，杜鵑聲裏斜陽暮。", "驛寄梅花，魚傳尺素。砌成此恨無重數。郴江幸自繞郴山，為誰流下瀟湘去。"], "quote": ["霧失樓臺，月迷津渡。桃源望斷無尋處。可堪孤館閉春寒，杜鵑聲裏斜陽暮。", "驛寄梅花，魚傳尺素。砌成此恨無重數。郴江幸自繞郴山，為誰流下瀟湘去。"], "intro": "秦觀《踏莎行》（霧失樓臺）選自《全宋詞》。 《踏莎行》詞調，唐、五代詞不載，始見於北宋寇準及晏殊的作品。秦觀此詞小題為「郴州旅舍」，當作於宋哲宗紹聖四年（一〇九七）春天被貶郴州（今湖南郴縣）時。作者以比興手法抒寫失意的心境。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B8%8F%E8%8E%8E%E8%A1%8C%EF%BC%88%E9%9C%A7%E5%A4%B1%E6%A8%93%E8%87%BA%EF%BC%89"}, {"title": "鵲橋仙（纖雲弄巧）", "author": "秦觀", "period": "宋", "form": "詞", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["纖雲弄巧，飛星傳恨，銀漢迢迢暗度。金風玉露一相逢，便勝卻人間無數！", "柔情似水，佳期如夢，忍顧鵲橋歸路。兩情若是久長時，又豈在朝朝暮暮？"], "quote": ["纖雲弄巧，飛星傳恨，銀漢迢迢暗度。金風玉露一相逢，便勝卻人間無數！", "柔情似水，佳期如夢，忍顧鵲橋歸路。兩情若是久長時，又豈在朝朝暮暮？"], "intro": "秦觀《鵲橋仙》（纖雲弄巧）選自《全宋詞》。 《鵲橋仙》原是詠牛郎、織女的愛情故事而創作的樂曲，本詞的內容也正是如此，所以又題作「七夕」。秦觀雖仍是依據傳說而題詠，但卻能別出機杼，不寫雙星遠隔之恨，而改以羨慕的心情去歌頌雙星永恆的愛情。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%B5%B2%E6%A9%8B%E4%BB%99%EF%BC%88%E7%BA%96%E9%9B%B2%E5%BC%84%E5%B7%A7%EF%BC%89"}, {"title": "白鹿洞書院講義", "author": "陸九淵", "period": "宋", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["某雖少服父兄師友之訓，不敢自棄，而頑鈍疏拙，學不加進。每懷愧惕，恐卒負其初心，方將求鍼砭鐫磨於四方師友，冀獲開發，以免罪戾。此來得從郡侯秘書至白鹿洞堂，群賢畢集，瞻覩盛觀，竊自慶幸。", "秘書先生教授先生，不察其愚，令登講席，以吐所聞。顧惟庸虛，何敢當此？辭避再三，不得所請，取《論語》中一章，陳平日之所感，以應嘉命；亦幸有以教之！", "子曰︰「君子喻於義，小人喻於利。」此章以義利判君子小人，辭旨曉白。然讀之者苟不切己觀省，亦恐未能有益也。某平日讀此，不無所感。竊謂學者於此，當辨其志。", "人之所喻，由其所習，所習由其所志。志乎義，則所習者必在於義；所習在義，斯喻於義矣。志乎利，則所習者必在於利；所習在利，斯喻於利矣。故學者之志，不可不辨也。", "科舉取士久矣，名儒鉅公，皆由此出。今為士者，固不能免此。然場屋之得失，顧其技與有司好惡如何耳；非所以為君子小人之辨也。而今世以此相尚，使汨沒於此而不能自拔，則終日從事者，雖曰聖賢之書，而要其志之所鄉，則有與聖賢背而馳者矣。", "推而上之，則又惟官資崇卑，祿廩厚薄是計，豈能悉心力於國事民隱，以無負於任使之者哉？從事其間，更歷之多，講習之熟，安得不有所喻？顧恐不在於義耳。誠能深思是身，不可使之為小人之歸，其於利欲之習，怛焉為之痛心疾首；專志乎義而日勉焉，博學、審問、慎思、明辨而篤行之。", "由是而進於場屋，其文必皆道其平日之學，胸中之蘊，而不詭於聖人；由是而仕，必皆共其職，勤其事，必乎國，心乎民，而不為身計，其得不謂之君子乎？", "祕書先生起廢以新斯堂，其意篤矣。凡至斯堂者，必不殊志；願與諸君勉之，以毋負其志！"], "quote": ["某雖少服父兄師友之訓，不敢自棄，而頑鈍疏拙，學不加進。每懷愧惕，恐卒負其初心，方將求鍼砭鐫磨於四方師友，冀獲開發，以免罪戾。此來得從郡侯秘書至白鹿洞堂，群賢畢集，瞻覩盛觀，竊自慶幸。", "秘書先生教授先生，不察其愚，令登講席，以吐所聞。顧惟庸虛，何敢當此？辭避再三，不得所請，取《論語》中一章，陳平日之所感，以應嘉命；亦幸有以教之！", "子曰︰「君子喻於義，小人喻於利。」此章以義利判君子小人，辭旨曉白。然讀之者苟不切己觀省，亦恐未能有益也。某平日讀此，不無所感。竊謂學者於此，當辨其志。", "人之所喻，由其所習，所習由其所志。志乎義，則所習者必在於義；所習在義，斯喻於義矣。志乎利，則所習者必在於利；所習在利，斯喻於利矣。故學者之志，不可不辨也。"], "intro": "白鹿洞書院，在今江西星子縣北廬山五老峰下。唐代時，有李涉、李渤兩兄弟來這裏讀書，養了一隻白鹿作伴，因此有「白鹿洞」這名稱。南唐時曾在這裏建立學校，宋初改名「書院」，後來又被廢除。因此有「白鹿洞」這名稱。南唐時曾在這建立學校，宋初改名「書院」", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%99%BD%E9%B9%BF%E6%B4%9E%E6%9B%B8%E9%99%A2%E8%AC%9B%E7%BE%A9"}, {"title": "卜算子・詠梅（驛外斷橋邊）", "author": "陸游", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["驛外斷橋邊，寂寞開無主。已是黃昏獨自愁，更著風和雨。", "無意苦爭春，一任羣芳妒。零落成泥碾作塵，只有香如故。"], "quote": ["驛外斷橋邊，寂寞開無主。已是黃昏獨自愁，更著風和雨。", "無意苦爭春，一任羣芳妒。零落成泥碾作塵，只有香如故。"], "intro": "這首詞題為「詠梅」，是借詠物以言志。陸游酷愛梅花，在本詞中，他以梅花象徵自己的孤高和勁節。陸游一生主張抗金救國，卻屢遭朝廷主和派的排擠，未能舒展抱負，但他始終立場堅定，沒有向現實中的種種挫折屈服，一如詞中的梅花，即使遭受風雨的侵襲，依然獨自", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%8D%9C%E7%AE%97%E5%AD%90%E3%83%BB%E8%A9%A0%E6%A2%85%EF%BC%88%E9%A9%9B%E5%A4%96%E6%96%B7%E6%A9%8B%E9%82%8A%EF%BC%89"}, {"title": "示兒", "author": "陸游", "period": "宋", "form": "詩", "theme": "江河湖海", "mood": "vast_river", "lines": ["死去元知萬事空，但悲不見九州同。", "王師北定中原日，家祭無忘告乃翁。"], "quote": ["死去元知萬事空，但悲不見九州同。", "王師北定中原日，家祭無忘告乃翁。"], "intro": "《示兒》選自《劍南詩稿校注》卷八十五。陸游以《示兒》為題的詩有多首，此處所選的是陸游死前之作，時年八十五歲，正值南宋寧宗嘉定三年（一二一〇）春。詩中對南宋統治者的屈辱求和、偏安江左，深表悲憤，但仍盼宋室終能收復故土，可見作者矢志不渝的愛國情", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%A4%BA%E5%85%92"}, {"title": "書憤", "author": "陸游", "period": "宋", "form": "詩", "theme": "邊塞豪放", "mood": "snow_winter", "lines": ["早歲那知世事艱，中原北望氣如山。", "樓船夜雪瓜洲渡，鐵馬秋風大散關。", "塞上長城空自許，鏡中衰鬢已先斑。", "出師一表真名世，千載誰堪伯仲間。"], "quote": ["早歲那知世事艱，中原北望氣如山。", "樓船夜雪瓜洲渡，鐵馬秋風大散關。", "塞上長城空自許，鏡中衰鬢已先斑。", "出師一表真名世，千載誰堪伯仲間。"], "intro": "《書憤》（早歲那知世事艱）選自《劍南詩稿校注》卷十七。宋孝宗淳熙十三年（一一八六）春，陸游在山陰（今浙江紹興）罷官閑居已有六年之久，突然接到朝廷起用的詔命，他以興奮的心情寫下了這首七言律詩，追憶早年的英勇事跡，感嘆歲月蹉跎，然後重申平生的壯", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9B%B8%E6%86%A4"}, {"title": "釵頭鳳（紅酥手）", "author": "陸游", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "majestic_peaks", "lines": ["紅酥手，黃縢酒，滿城春色宮牆柳。東風惡，歡情薄，一懷愁緒，幾年離索，錯！錯！錯！", "春如舊，人空瘦，淚痕紅浥鮫綃透。桃花落，閒池閣，山盟雖在，錦書難託，莫！莫！莫！"], "quote": ["紅酥手，黃縢酒，滿城春色宮牆柳。東風惡，歡情薄，一懷愁緒，幾年離索，錯！錯！錯！", "春如舊，人空瘦，淚痕紅浥鮫綃透。桃花落，閒池閣，山盟雖在，錦書難託，莫！莫！莫！"], "intro": "陸游《釵頭鳳》（紅酥手）選自《全宋詞》。 《釵頭鳳》原名《擷芳詞》，陸游因無名氏詞中有「可憐孤似釵頭鳳」句，故改名《釵頭鳳》。此詞是陸游於宋高宗紹興二十五年（一一五五）三十一歲時為其前妻唐琬而作。陸游初娶表妹唐琬，但為陸母所反對，唐琬遂遭休", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%87%B5%E9%A0%AD%E9%B3%B3%EF%BC%88%E7%B4%85%E9%85%A5%E6%89%8B%EF%BC%89"}, {"title": "訴衷情（當年萬里覓封侯）", "author": "陸游", "period": "宋", "form": "詞", "theme": "邊塞豪放", "mood": "autumn_sunset", "lines": ["當年萬里覓封侯，匹馬戍梁州。關河夢斷何處，塵暗舊貂裘。", "胡未滅，鬢先秋，淚空流。此生誰料，心在天山，身老滄洲。"], "quote": ["當年萬里覓封侯，匹馬戍梁州。關河夢斷何處，塵暗舊貂裘。", "胡未滅，鬢先秋，淚空流。此生誰料，心在天山，身老滄洲。"], "intro": "這首詞是陸游晚年的作品，透露了他對當時社會現實的悲涼激越心情，抒寫出敵人未滅而英雄已老的苦悶，表現了作者憂國傷時的痛苦。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A8%B4%E8%A1%B7%E6%83%85%EF%BC%88%E7%95%B6%E5%B9%B4%E8%90%AC%E9%87%8C%E8%A6%93%E5%B0%81%E4%BE%AF%EF%BC%89"}, {"title": "遊山西村", "author": "陸游", "period": "宋", "form": "詩", "theme": "山水登臨", "mood": "vast_river", "lines": ["莫笑農家臘酒渾，豐年留客足雞豚。", "山重水複疑無路，柳暗花明又一村。", "簫鼓追隨春社近，衣冠簡樸古風存。", "從今若許閑乘月，拄杖無時夜叩門。"], "quote": ["莫笑農家臘酒渾，豐年留客足雞豚。", "山重水複疑無路，柳暗花明又一村。", "簫鼓追隨春社近，衣冠簡樸古風存。", "從今若許閑乘月，拄杖無時夜叩門。"], "intro": "《遊山西村》選自《劍南詩稿校注》卷一。宋孝宗隆興二年（一一六四）四月，宋室與金人媾和，主和派再次得勢，主戰派首領張浚被罷去右丞相及江淮都督之職，其他主戰者都受到貶斥。陸游以「交結台諫，鼓唱是非，力說張浚用兵」的罪名被罷官歸鄉，閑居山陰（今浙", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%81%8A%E5%B1%B1%E8%A5%BF%E6%9D%91"}, {"title": "關山月", "author": "陸游", "period": "宋", "form": "詩", "theme": "邊塞豪放", "mood": "majestic_peaks", "lines": ["和戎詔下十五年，將軍不戰空臨邊。", "朱門沉沉按歌舞，廐馬肥死弓斷弦。", "戍樓刁斗催落月，三十從軍今白髮。", "笛裏誰知壯士心，沙頭空照征人骨。", "中原干戈古亦聞，豈有逆胡傳子孫。", "遺民忍死望恢復，幾處今宵垂淚痕。"], "quote": ["和戎詔下十五年，將軍不戰空臨邊。", "朱門沉沉按歌舞，廐馬肥死弓斷弦。", "戍樓刁斗催落月，三十從軍今白髮。", "笛裏誰知壯士心，沙頭空照征人骨。"], "intro": "《關山月》選自《劍南詩稿校注》卷八。南宋孝宗淳熙四年（一一七七），五十三歲的陸游時任成都府路（今四川成都）安撫使同參議官的閑職。報國壯志未能伸展，憂憤地寫下了這首詩。《關山月》本是漢樂府「鼓角橫吹曲」十五首之一，作者借用樂府舊題，以守邊將士", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%97%9C%E5%B1%B1%E6%9C%88"}, {"title": "華山", "author": "寇準", "period": "宋", "form": "詩", "theme": "山水登臨", "mood": "vast_river", "lines": ["只有天在上，更無山與齊。", "舉頭紅日近，回首白雲低。"], "quote": ["只有天在上，更無山與齊。", "舉頭紅日近，回首白雲低。"], "intro": "華（粵：[話wa6]；普：[huà]。）山在陝西省華陰縣南，為五嶽中的西嶽，海拔1997公尺，山峰雄奇險峻，有蓮花峰、朝陽峰、玉女峰等，為遊覽勝地。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%8F%AF%E5%B1%B1"}, {"title": "賀新郎（夢繞神州路）", "author": "張元幹", "period": "宋", "form": "詞", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["送胡邦衡待制", "夢繞神州路。悵秋風、連營畫角，故宮離黍。底事崑崙傾砥柱。九地黃流亂注？聚萬落、千村狐兔。天意從來高難問，況人情、老易悲如許！更南浦，送君去。", "涼生岸柳催殘暑。耿斜河、疏星淡月，斷雲微度。萬里江山知何處？回首對牀夜語。雁不到、書成誰與？目盡青天懷今古，肯兒曹、恩怨相爾汝。舉大白，聽金縷。"], "quote": ["送胡邦衡待制", "夢繞神州路。悵秋風、連營畫角，故宮離黍。底事崑崙傾砥柱。九地黃流亂注？聚萬落、千村狐兔。天意從來高難問，況人情、老易悲如許！更南浦，送君去。", "涼生岸柳催殘暑。耿斜河、疏星淡月，斷雲微度。萬里江山知何處？回首對牀夜語。雁不到、書成誰與？目盡青天懷今古，肯兒曹、恩怨相爾汝。舉大白，聽金縷。"], "intro": "張元幹《賀新郎》（夢繞神州路）選自《全宋詞》。 《賀新郎》是詞牌名，屬慢曲，首見於蘇軾詞，因詞中有「晚涼新浴」句，又名《賀新涼》。張元幹的《賀新郎》，詞題作「送胡邦衡待制」，是他送別被貶往新州（今廣東新興）的胡銓之作。胡銓是力主抗金的主戰派", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B3%80%E6%96%B0%E9%83%8E%EF%BC%88%E5%A4%A2%E7%B9%9E%E7%A5%9E%E5%B7%9E%E8%B7%AF%EF%BC%89"}, {"title": "天仙子（水調數聲持酒聽）", "author": "張先", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "autumn_sunset", "lines": ["水調數聲持酒聽。午醉醒來愁未醒。送春春去幾時回？臨晚鏡，傷流景。往事後期空記省！", "沙上並禽池上暝。雲破月來花弄影。重重簾幕密遮燈，風不定。人初靜。明日落紅應滿徑。"], "quote": ["水調數聲持酒聽。午醉醒來愁未醒。送春春去幾時回？臨晚鏡，傷流景。往事後期空記省！", "沙上並禽池上暝。雲破月來花弄影。重重簾幕密遮燈，風不定。人初靜。明日落紅應滿徑。"], "intro": "張先《天仙子》（水調數聲持酒聽），取自《全宋詞》。 《天仙子》，唐玄宗時教坊曲名，後用為詞調。唐五代人多用此調詠天仙、仙子（借指女道士），也有用來寫仙郎的，都是以調為題。張先此詞，約作於宋仁宗慶曆元年（一〇四一），自注云：「時為嘉禾小倅，以", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%A4%A9%E4%BB%99%E5%AD%90%EF%BC%88%E6%B0%B4%E8%AA%BF%E6%95%B8%E8%81%B2%E6%8C%81%E9%85%92%E8%81%BD%EF%BC%89"}, {"title": "水調歌頭（雪洗虜塵靜）", "author": "張孝祥", "period": "宋", "form": "詞", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["聞采石戰勝", "雪洗虜塵靜，風約楚雲留。何人為寫悲壯，吹角古城樓。湖海平生豪氣，關塞如今風景，剪燭看吳鈎。賸喜燃犀處，駭浪與天浮。", "憶當年，周與謝，富春秋，小喬初嫁，香囊未解，勳業故優游。赤壁磯頭落照，肥水橋邊衰草，渺渺喚人愁。我欲乘風去，擊楫誓中流。"], "quote": ["聞采石戰勝", "雪洗虜塵靜，風約楚雲留。何人為寫悲壯，吹角古城樓。湖海平生豪氣，關塞如今風景，剪燭看吳鈎。賸喜燃犀處，駭浪與天浮。", "憶當年，周與謝，富春秋，小喬初嫁，香囊未解，勳業故優游。赤壁磯頭落照，肥水橋邊衰草，渺渺喚人愁。我欲乘風去，擊楫誓中流。"], "intro": "這首詞寫在虞允文大破金兵於采石磯後不久的紹興三十一年（一一六一）年冬，地點在撫州任上，主人翁是作者自己。內容是歌頌抗戰將領勳業，抒發自己從戎報國的激情，及對中原失地的懷念和異族入侵的悲慨，可謂是喜中寓愁，壯中帶悲。全詞筆墨酣暢，音節振拔，奔", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B0%B4%E8%AA%BF%E6%AD%8C%E9%A0%AD%EF%BC%88%E9%9B%AA%E6%B4%97%E8%99%9C%E5%A1%B5%E9%9D%9C%EF%BC%89"}, {"title": "高陽臺・西湖春感（接葉巢鶯）", "author": "張炎", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "vast_river", "lines": ["接葉巢鶯，平波卷絮，斷橋斜日歸船。能幾番游？看花又是明年。東風且伴薔薇住，到薔薇、春已堪憐。更淒然，萬綠西泠，一抹荒煙。", "當年燕子知何處？但苔深韋曲，草暗斜川。見說新愁，如今也到鷗邊。無心再續笙歌夢，掩重門、淺醉閒眠。莫開簾。怕見飛花，怕聽啼鵑。"], "quote": ["接葉巢鶯，平波卷絮，斷橋斜日歸船。能幾番游？看花又是明年。東風且伴薔薇住，到薔薇、春已堪憐。更淒然，萬綠西泠，一抹荒煙。", "當年燕子知何處？但苔深韋曲，草暗斜川。見說新愁，如今也到鷗邊。無心再續笙歌夢，掩重門、淺醉閒眠。莫開簾。怕見飛花，怕聽啼鵑。"], "intro": "西湖處於浙江杭州，宋時稱臨安，是南宋偏安時的首都。當時社會高度繁華，名勝西湖是繁華競逐之地，南宋祝穆《方輿勝覽》記載說「山川秀發，四時畫舫遨遊，歌鼓之聲不絕」，可以想見情況。隨着南宋覆亡，往昔繁華煙消雲散，張炎亦流落江湖，在某春天，重遊西湖", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%AB%98%E9%99%BD%E8%87%BA%E3%83%BB%E8%A5%BF%E6%B9%96%E6%98%A5%E6%84%9F%EF%BC%88%E6%8E%A5%E8%91%89%E5%B7%A2%E9%B6%AF%EF%BC%89%C2%A0"}, {"title": "清平樂（采芳人杳）", "author": "張炎", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["采芳人杳。頓覺遊情少。客裏看春多草草。總被詩愁分了。", "去年燕子天涯。今年燕子誰家？三月休聽夜雨，如今不是催花。"], "quote": ["采芳人杳。頓覺遊情少。客裏看春多草草。總被詩愁分了。", "去年燕子天涯。今年燕子誰家？三月休聽夜雨，如今不是催花。"], "intro": "公元一二七六年，元兵佔領臨安之後，張炎的家園被抄沒，親人被擄殺，他成了逃亡在外的宋臣。多年以後，他的家禍在人們心中已經淡忘，他回到了臨安。時值春天，他目睹境況蕭條，自己也已無家可歸，而成了舊日都城的過客，有如飄泊無依的燕子，於是萬千感慨，聚", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B8%85%E5%B9%B3%E6%A8%82%EF%BC%88%E9%87%87%E8%8A%B3%E4%BA%BA%E6%9D%B3%EF%BC%89"}, {"title": "宜黃縣學記", "author": "曾鞏", "period": "宋", "form": "文", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["古之人，自家至於天子之國，皆有學；自幼至於長，未嘗去於學之中。學有詩書、六藝、弦歌、洗爵、俯仰之容、升降之節，以習其心、體、耳、目、手、足之舉措；又有祭祀、鄉射、養老之禮，以習恭讓；進材、論獄、出兵、授捷之法，以習其從事；師友以解其惑，勸懲以勉其進，戒其不率；其所以為具如此。", "而其大要，則務使人人學其性，不獨防其邪僻放肆也。雖有剛柔緩急之異，皆可以進之中，而無過不及。使其識之明，氣之充於其心，則用之於進退語默之際，而無不得其宜；臨之以禍福死生之故，無足動其意者。為天下之士，而所以養其身之備如此。則又使知天地事物之變，古今治亂之理；至於損益廢置先後始終之要，無所不知。", "其在堂戶之上，而四海九州之業，萬世之策皆得；及出而履天下之任，列百官之中，則隨所施為無不可者。何則？其素所學問然也。蓋凡人之起居飲食動作之小事，至於修身為國家天下之大體，皆自學出，而無斯須去於教也。其動於視聽四支者，必使其洽於內；其謹於初者，必使其要於終。馴之以自然，而待之以積久。", "噫，何其至也！故其俗之成，則刑罰措；其材之成，則三公百官得其士；其為法之永，則中材可以守，其入人之深，則雖更衰世而不亂。為教之極至此，鼓舞天下而人不知其從之，豈用力也哉？", "及三代衰，聖人之制作盡壞。千餘年之間，學有存者，亦非古法。人之體性之舉動，唯其所自肆。而臨政治人之方，固不素講。士有聰明樸茂之質，而無教養之漸，則其材之不成固然。蓋以不學未成之材，而為天下之吏；又承衰敝之後，而治不教之民。嗚呼，仁政之所以不行，盜賊刑罰之所以積，其不以此也歟？", "宋興幾百年矣。慶曆三年，天子圖當世之務，而以學為先，於是天下之學乃得立。而方此之時，撫州之宜黃猶不能有學。士之學者，皆相率而寓於州，以群聚講習。其明年，天下之學復廢，士亦皆散去；而春秋釋奠之事，以著於令，則常以廟祀孔氏，廟廢不復理。皇祐元年，會令李君詳至，始議立學。", "而縣之士某某與其徒，皆自以謂得發憤於此，莫不相勵而趨為之；故其材不賦而羨，匠不發而多。其成也︰積屋之區若干，而門序正位，講藝之堂，栖士之舍皆足；積器之數若干，而祀飲寢食之用皆具；其象，孔氏而下，從祭之士皆備；其書，經史百氏，翰林子墨之文章，無外求者；其相基會作之本末，總為日若干而已，何其周且速也！", "當四方學廢之初，有司之議，固以謂學者人情之所不樂；及觀此學之作，在其廢學數年之後，唯其令之一唱，而四境之內，響應而圖之，如恐不及，則夫言人之情不樂於學者，其果然也歟？", "宜黃之學者，固多良士；而李君之為令，威行愛立，訟清事舉，其政又良也。夫及良令之時，而順其慕學發憤之俗，作為宮室教肄之所，以至圖書器用之須，莫不皆有以養其良材之士。雖古之去今，遠矣，而聖人之典籍皆在，其言可考，其法可求；使其相與學而明之，禮樂節文之詳，固有所不得為者；若夫正心修身，為國家天下之大務，則在其進之而已。", "使一人之行修，移之於一家；一家之行修，移之於鄉鄰族黨；則一縣之風俗成，人材出矣。教化之行，道德之歸，非遠人也；可不勉歟？", "縣之士來請曰︰「願有記。」故記之，十二月某日也。"], "quote": ["古之人，自家至於天子之國，皆有學；自幼至於長，未嘗去於學之中。學有詩書、六藝、弦歌、洗爵、俯仰之容、升降之節，以習其心、體、耳、目、手、足之舉措；又有祭祀、鄉射、養老之禮，以習恭讓；進材、論獄、出兵、授捷之法，以習其從事；師友以解其惑，勸懲以勉其進，戒其不率；其所以為具如此。", "而其大要，則務使人人學其性，不獨防其邪僻放肆也。雖有剛柔緩急之異，皆可以進之中，而無過不及。使其識之明，氣之充於其心，則用之於進退語默之際，而無不得其宜；臨之以禍福死生之故，無足動其意者。為天下之士，而所以養其身之備如此。則又使知天地事物之變，古今治亂之理；至於損益廢置先後始終之要，無所不知。", "其在堂戶之上，而四海九州之業，萬世之策皆得；及出而履天下之任，列百官之中，則隨所施為無不可者。何則？其素所學問然也。蓋凡人之起居飲食動作之小事，至於修身為國家天下之大體，皆自學出，而無斯須去於教也。其動於視聽四支者，必使其洽於內；其謹於初者，必使其要於終。馴之以自然，而待之以積久。", "噫，何其至也！故其俗之成，則刑罰措；其材之成，則三公百官得其士；其為法之永，則中材可以守，其入人之深，則雖更衰世而不亂。為教之極至此，鼓舞天下而人不知其從之，豈用力也哉？"], "intro": "宜黃，縣名，宋屬江南西路撫州，故城在今江西宜黃縣東。古時按照行政單位，州有州學，府有府學，縣有縣學；縣學，即在縣裏建立的學宮，為祭祀先師孔子和教育縣中士人的地方，設有學官掌其事。本文是宜黃縣的縣學落成之時，由作者寫的一篇「記」，選自《元豐類", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%AE%9C%E9%BB%83%E7%B8%A3%E5%AD%B8%E8%A8%98"}, {"title": "四箴", "author": "程頤", "period": "宋", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["視箴", "心兮本虛，應物無迹；操之有要，視為之則。蔽交於前，其中則遷。制之於外，以安其內；克己復禮，久而誠矣。", "聽箴", "人有秉彝，本乎天性，知誘物化，遂亡其正。卓彼先覺，知止有定，閑邪存誠，非禮勿聽。", "言箴", "人心之動，因言以宣；發禁躁妄，內斯靜專。矧是樞機，興戎出好，吉凶榮辱，惟其所召。傷易則誕，傷煩則支。己肆物忤，出悖來違。非法不道，欽哉訓辭！", "動箴", "哲人知幾，誠之於思，志士勵行，守之於為。順理則裕，從欲惟危。造次克念，戰兢自持，習與性成，聖賢同歸。"], "quote": ["視箴", "心兮本虛，應物無迹；操之有要，視為之則。蔽交於前，其中則遷。制之於外，以安其內；克己復禮，久而誠矣。", "聽箴", "人有秉彝，本乎天性，知誘物化，遂亡其正。卓彼先覺，知止有定，閑邪存誠，非禮勿聽。"], "intro": "程頤《四箴》，乃本於《論語‧顏淵》篇之「四勿」而作，其自序云：「顏淵問克己復禮之目。夫子曰：『非禮勿視，非禮勿聽，非禮勿言，非禮勿動。』四者，身之用也，由乎中而應乎外；制於外，所以養其中也。顏淵事斯語，所以進於聖人。後之學聖人者，宜服膺而勿", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%9B%9B%E7%AE%B4"}, {"title": "遊園不值", "author": "葉紹翁", "period": "宋", "form": "詩", "theme": "田園幽居", "mood": "spring_breeze", "lines": ["應憐屐齒印蒼苔，小扣柴扉久不開。", "春色滿園關不住，一枝紅杏出牆來。"], "quote": ["應憐屐齒印蒼苔，小扣柴扉久不開。", "春色滿園關不住，一枝紅杏出牆來。"], "intro": "初春的時候，一天，詩人興致勃勃到友人的花園去探訪，可是敲門久久卻無人應答，不得入內。「不值」指不遇，詩人沒有見到要探訪的人。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%81%8A%E5%9C%92%E4%B8%8D%E5%80%BC"}, {"title": "青玉案・橫塘路（凌波不過橫塘路）", "author": "賀鑄", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "autumn_sunset", "lines": ["凌波不過橫塘路。但目送、芳塵去。錦瑟華年誰與度？月橋花院，瑣窗朱戶，只有春知處。", "飛雲冉冉蘅皋暮。彩筆新題斷腸句。若問閒情都幾許？一川煙草，滿城風絮，梅子黃時雨。"], "quote": ["凌波不過橫塘路。但目送、芳塵去。錦瑟華年誰與度？月橋花院，瑣窗朱戶，只有春知處。", "飛雲冉冉蘅皋暮。彩筆新題斷腸句。若問閒情都幾許？一川煙草，滿城風絮，梅子黃時雨。"], "intro": "賀鑄《青玉案・橫塘路》（凌波不過橫塘路）選自《全宋詞》。 賀鑄《橫塘路》，是依《青玉案》一調填寫，而以詞中字句作為詞牌名。賀鑄《東山詞集》中，多取詞中字句作為調名，可見作者愛己詞之深。此詞是作者晚年寓居蘇州時所作，以望美人不來發端，抒發幽居", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%9D%92%E7%8E%89%E6%A1%88%E3%83%BB%E6%A9%AB%E5%A1%98%E8%B7%AF%EF%BC%88%E5%87%8C%E6%B3%A2%E4%B8%8D%E9%81%8E%E6%A9%AB%E5%A1%98%E8%B7%AF%EF%BC%89"}, {"title": "寄黃幾復", "author": "黃庭堅", "period": "宋", "form": "詩", "theme": "江河湖海", "mood": "vast_river", "lines": ["我居北海君南海，寄雁傳書謝不能。", "桃李春風一杯酒，江湖夜雨十年燈。", "持家但有四立壁，治病不祈三折肱。", "想得讀書頭已白，隔溪猿哭瘴溪藤。"], "quote": ["我居北海君南海，寄雁傳書謝不能。", "桃李春風一杯酒，江湖夜雨十年燈。", "持家但有四立壁，治病不祈三折肱。", "想得讀書頭已白，隔溪猿哭瘴溪藤。"], "intro": "這首詩題下原有自注：「乙丑年德平鎮作。」德平鎮在今山東德州東北。乙丑是元豐八年（公元1085）。元豐六年（公元1083）十二月，黃庭堅監德州德平鎮，直到元豐八年五月，一直在德平任上。黃幾復，黃介字幾復（幾，粵：[機gei1]；普：[jī]。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%AF%84%E9%BB%83%E5%B9%BE%E5%BE%A9"}, {"title": "清平樂（春歸何處）", "author": "黃庭堅", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["春歸何處？寂寞無行路。若有人知春去處，喚取歸來同住。", "春無蹤跡誰知？除非問取黃鸝。百囀無人能解，因風吹過薔薇。"], "quote": ["春歸何處？寂寞無行路。若有人知春去處，喚取歸來同住。", "春無蹤跡誰知？除非問取黃鸝。百囀無人能解，因風吹過薔薇。"], "intro": "", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B8%85%E5%B9%B3%E6%A8%82%EF%BC%88%E6%98%A5%E6%AD%B8%E4%BD%95%E8%99%95%EF%BC%89"}, {"title": "登快閣", "author": "黃庭堅", "period": "宋", "form": "詩", "theme": "山水登臨", "mood": "autumn_sunset", "lines": ["癡兒了卻公家事，快閣東西倚晚晴。", "落木千山天遠大，澄江一道月分明。", "朱絃已為佳人絕，青眼聊因美酒橫。", "萬里歸船弄長笛，此心吾與白鷗盟。"], "quote": ["癡兒了卻公家事，快閣東西倚晚晴。", "落木千山天遠大，澄江一道月分明。", "朱絃已為佳人絕，青眼聊因美酒橫。", "萬里歸船弄長笛，此心吾與白鷗盟。"], "intro": "黃庭堅《登快閣》選自《山谷外集》，作於宋神宗元豐五年（一〇八二），當時作者在吉州（今江西）太和（今泰和）縣作縣令。快閣是當地名勝，在太和縣治所東面的澄江（今贛江）之上，江山廣遠，景物清華。本詩描繪了清秋江山的美景，並表達了作者無心仕進，嚮往", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%99%BB%E5%BF%AB%E9%96%A3"}, {"title": "鷓鴣天（黃菊枝頭生曉寒）", "author": "黃庭堅", "period": "宋", "form": "詞", "theme": "田園幽居", "mood": "snow_winter", "lines": ["黃菊枝頭生曉寒，人生莫放酒杯乾。風前橫笛斜吹雨，醉裏簪花倒著冠。", "身健在，且加餐。舞裙歌板盡清歡。黃花白髮相牽挽，付與時人冷眼看。"], "quote": ["黃菊枝頭生曉寒，人生莫放酒杯乾。風前橫笛斜吹雨，醉裏簪花倒著冠。", "身健在，且加餐。舞裙歌板盡清歡。黃花白髮相牽挽，付與時人冷眼看。"], "intro": "一、這首詞根據其原題「座中有眉山隱客史應之，和前韻，即席答之」，知道是作者與史應之互相酬唱的作品。史應之，眉山人，落魄無檢，題中稱「隱客」，可見是個甘居山野，不求功名的人。 二、這首詞是作者因坐元祐黨籍，被貶放西南荒僻之地時所作。詞中作者塑", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%B7%93%E9%B4%A3%E5%A4%A9%EF%BC%88%E9%BB%83%E8%8F%8A%E6%9E%9D%E9%A0%AD%E7%94%9F%E6%9B%89%E5%AF%92%EF%BC%89"}, {"title": "小池", "author": "楊萬里", "period": "宋", "form": "詩", "theme": "田園幽居", "mood": "vast_river", "lines": ["泉眼無聲惜細流，", "樹陰照水愛晴柔。", "小荷才露尖尖角，", "早有蜻蜓立上頭。"], "quote": ["泉眼無聲惜細流，", "樹陰照水愛晴柔。", "小荷才露尖尖角，", "早有蜻蜓立上頭。"], "intro": "", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B0%8F%E6%B1%A0"}, {"title": "宿新市徐公店", "author": "楊萬里", "period": "宋", "form": "詩", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["籬落疏疏一徑深，樹頭花落未成陰。", "兒童急走追黃蝶，飛入菜花無處尋。"], "quote": ["籬落疏疏一徑深，樹頭花落未成陰。", "兒童急走追黃蝶，飛入菜花無處尋。"], "intro": "新市是地名，而徐公店是客店名。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%AE%BF%E6%96%B0%E5%B8%82%E5%BE%90%E5%85%AC%E5%BA%97"}, {"title": "曉出淨慈寺送林子方", "author": "楊萬里", "period": "宋", "form": "詩", "theme": "送別行旅", "mood": "vast_river", "lines": ["畢竟西湖六月中，", "風光不與四時同。", "接天蓮葉無窮碧，", "映日荷花別樣紅。"], "quote": ["畢竟西湖六月中，", "風光不與四時同。", "接天蓮葉無窮碧，", "映日荷花別樣紅。"], "intro": "這首詩的作者在早晨外出至當時著名的寺院——淨慈寺（位於西湖西南，南屏山下）送別友人林子方。 這首詩寫於淳熙十四年（公元1187）。南宋朝廷設於杭州，當時作者在朝廷任秘書少監，因此對杭州的名勝西湖相當熟悉；他在這首送別朋友的詩裏，把夏日西湖風", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9B%89%E5%87%BA%E6%B7%A8%E6%85%88%E5%AF%BA%E9%80%81%E6%9E%97%E5%AD%90%E6%96%B9"}, {"title": "一剪梅（一片春愁待酒澆）", "author": "蔣捷", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "autumn_sunset", "lines": ["舟過吳江", "一片春愁待酒澆，江上舟搖，樓上帘招。秋娘渡與泰娘橋，風又飄飄，雨又瀟瀟。", "何日歸家洗客袍，銀字笙調，心字香燒。流光容易把人拋，紅了櫻桃，綠了芭蕉。"], "quote": ["舟過吳江", "一片春愁待酒澆，江上舟搖，樓上帘招。秋娘渡與泰娘橋，風又飄飄，雨又瀟瀟。", "何日歸家洗客袍，銀字笙調，心字香燒。流光容易把人拋，紅了櫻桃，綠了芭蕉。"], "intro": "南宋亡後，蔣捷懷着亡國之痛，隱居姑蘇一帶太湖之濱，漂泊不仕。《一剪梅》這首詞有副題「舟過吳江」，是蔣捷於南宋被滅之初，寫自己乘船經過吳江縣時，見春光明媚的風景，藉以反襯自己羈旅不定的生活，感歎時光的流逝。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B8%80%E5%89%AA%E6%A2%85%EF%BC%88%E4%B8%80%E7%89%87%E6%98%A5%E6%84%81%E5%BE%85%E9%85%92%E6%BE%86%EF%BC%89"}, {"title": "虞美人（少年聽雨歌樓上）", "author": "蔣捷", "period": "宋", "form": "詞", "theme": "江河湖海", "mood": "vast_river", "lines": ["聽雨", "少年聽雨歌樓上。紅燭昏羅帳。壯年聽雨客舟中。江闊雲低，斷雁叫西風。", "而今聽雨僧廬下。鬢已星星也。悲歡離合總無情。一任階前點滴到天明。"], "quote": ["聽雨", "少年聽雨歌樓上。紅燭昏羅帳。壯年聽雨客舟中。江闊雲低，斷雁叫西風。", "而今聽雨僧廬下。鬢已星星也。悲歡離合總無情。一任階前點滴到天明。"], "intro": "蔣捷生當宋、元易代之際，他本是宋度宗咸淳年間進士，幾年後南宋就滅亡了。南宋亡後，他隱居姑蘇一帶太湖之濱，漂泊不仕。他的一生在戰亂年代中顛沛流離，飽經憂患。《虞美人・聽雨》一詞是他後期的代表作，是對自己憂患一生的自述。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%99%9E%E7%BE%8E%E4%BA%BA%EF%BC%88%E5%B0%91%E5%B9%B4%E8%81%BD%E9%9B%A8%E6%AD%8C%E6%A8%93%E4%B8%8A%EF%BC%89"}, {"title": "約客", "author": "趙師秀", "period": "宋", "form": "詩", "theme": "送別行旅", "mood": "spring_breeze", "lines": ["黃梅時節家家雨，青草池塘處處蛙。", "有約不來過夜半，閒敲棋子落燈花。"], "quote": ["黃梅時節家家雨，青草池塘處處蛙。", "有約不來過夜半，閒敲棋子落燈花。"], "intro": "", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%B4%84%E5%AE%A2"}, {"title": "玉樓春（年年躍馬長安市）", "author": "劉克莊", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "vast_river", "lines": ["戲林推", "年年躍馬長安市。客舍似家家似寄。青錢換酒日無何，紅燭呼盧宵不寐。", "易挑錦婦機中字。難得玉人心下事。男兒西北有神州，莫滴水西橋畔淚。"], "quote": ["戲林推", "年年躍馬長安市。客舍似家家似寄。青錢換酒日無何，紅燭呼盧宵不寐。", "易挑錦婦機中字。難得玉人心下事。男兒西北有神州，莫滴水西橋畔淚。"], "intro": "劉克莊《玉樓春》（年年躍馬長安市）選自《全宋詞》。 《玉樓春》首見於《花間集》顧敻詞起句：「月照玉樓春漏促」，後演變為詞調名。劉克莊的《玉樓春》，詞題為「戲林推」。林推，姓林的推官，是作者朋友。推官，節度推官的省稱，為帥府僚屬，負責刑事訴訟", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%8E%89%E6%A8%93%E6%98%A5%EF%BC%88%E5%B9%B4%E5%B9%B4%E8%BA%8D%E9%A6%AC%E9%95%B7%E5%AE%89%E5%B8%82%EF%BC%89"}, {"title": "畫荻", "author": "《歐陽公事迹》", "period": "宋", "form": "文", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["先公四歲而孤，家貧無資，太夫人以荻畫地，教以書字，多誦古人篇章，使學為詩。及其稍長，而家無書讀，就閭里士人家借而讀之，或因而抄錄。抄錄未畢，而已能誦其書。以至晝夜忘寢食，惟讀書是務。自幼所作詩賦文字，下筆已如成人。"], "quote": ["先公四歲而孤，家貧無資，太夫人以荻畫地，教以書字，多誦古人篇章，使學為詩。及其稍長，而家無書讀，就閭里士人家借而讀之，或因而抄錄。抄錄未畢，而已能誦其書。以至晝夜忘寢食，惟讀書是務。自幼所作詩賦文字，下筆已如成人。"], "intro": "歐陽修（公元一〇〇七——一〇七二），字永叔，號醉翁，又號六一居士，北宋廬陵（今江西省吉安市）人。幼年喪父，家境貧寒，母親用蘆桿教他認字。仁宗天聖年間進士，曾任參知政事等職。由於主張政治革新，與朝廷中的保守勢力形成對立，也因此而受到陷害，曾屢", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%95%AB%E8%8D%BB"}, {"title": "五代史伶官傳序", "author": "歐陽修", "period": "宋", "form": "文", "theme": "詠史哲思", "mood": "spring_breeze", "lines": ["嗚呼！盛衰之理，雖曰天命，豈非人事哉！原莊宗之所以得天下，與其所以失之者，可以知之矣。", "世言晉王之將終也，以三矢賜莊宗而告之曰︰「梁，吾仇也；燕王吾所立，契丹與吾約為兄弟，而皆背晉以歸梁。此三者，吾遺恨也。與爾三矢，爾其無忘乃父之志！」莊宗受而藏之於廟。", "其後用兵，則遣從事，以一少牢告廟，請其矢，盛以錦囊，負而前驅，及凱旋而納之。方其係燕父子以組，函梁君臣之首，入於太廟，還矢先王，而告以成功，其意氣之盛，可謂壯哉！", "及仇讎已滅，天下已定，一夫夜呼，亂者四應，倉皇東出，未見賊而士卒離散，君臣相顧，不知所歸；至於誓天斷髮，泣下沾襟，何其衰也！豈得之難而失之易歟？抑本其成敗之迹，而皆自於人歟？", "《書》曰︰「滿招損，謙受益。」憂勞可以興國，逸豫可以亡身，自然之理也。故方其盛也，舉天下之豪傑，莫能與之爭；及其衰也，數十伶人困之，而身死國滅，為天下笑。夫禍患常積於忽微，而智勇多困於所溺，豈獨伶人也哉！作《伶官傳》。"], "quote": ["嗚呼！盛衰之理，雖曰天命，豈非人事哉！原莊宗之所以得天下，與其所以失之者，可以知之矣。", "世言晉王之將終也，以三矢賜莊宗而告之曰︰「梁，吾仇也；燕王吾所立，契丹與吾約為兄弟，而皆背晉以歸梁。此三者，吾遺恨也。與爾三矢，爾其無忘乃父之志！」莊宗受而藏之於廟。", "其後用兵，則遣從事，以一少牢告廟，請其矢，盛以錦囊，負而前驅，及凱旋而納之。方其係燕父子以組，函梁君臣之首，入於太廟，還矢先王，而告以成功，其意氣之盛，可謂壯哉！", "及仇讎已滅，天下已定，一夫夜呼，亂者四應，倉皇東出，未見賊而士卒離散，君臣相顧，不知所歸；至於誓天斷髮，泣下沾襟，何其衰也！豈得之難而失之易歟？抑本其成敗之迹，而皆自於人歟？"], "intro": "本文乃《新五代史》卷三十七《伶官傳》的序文。在中國歷史上，從唐亡到宋興，中間相距有五十餘年，經歷了五個朝代，即後梁、後唐、後晉、後漢、後周，後世因稱為五代。這五個朝代的歷史，因為時間短促——長的也不過十幾年，短的只有三四年，便合為一編，稱為", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%BA%94%E4%BB%A3%E5%8F%B2%E4%BC%B6%E5%AE%98%E5%82%B3%E5%BA%8F"}, {"title": "玉樓春（尊前擬把歸期說）", "author": "歐陽修", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["尊前擬把歸期說，未語春容先慘咽。人生自是有情癡，此恨不關風與月。", "離歌且莫翻新闋，一曲能教腸寸結。直須看盡洛城花，始共春風容易別！"], "quote": ["尊前擬把歸期說，未語春容先慘咽。人生自是有情癡，此恨不關風與月。", "離歌且莫翻新闋，一曲能教腸寸結。直須看盡洛城花，始共春風容易別！"], "intro": "歐陽修《玉樓春》選自《全宋詞》。 《玉樓春》一名《木蘭花令》，為詞調之一種，用於酒筵歌席，為行令的歌曲。此詞是歐陽修於宋仁宗景祐三年（一〇三六）時作。是年三月，歐陽修任滿西京留守推官，臨行作有《玉樓春》詞多首。此詞當寫於離筵上，表示對京城的", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%8E%89%E6%A8%93%E6%98%A5%EF%BC%88%E5%B0%8A%E5%89%8D%E6%93%AC%E6%8A%8A%E6%AD%B8%E6%9C%9F%E8%AA%AA%EF%BC%89"}, {"title": "生查子（去年元夜時）", "author": "歐陽修", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["去年元夜時，花市燈如晝。月上柳梢頭，人約黃昏後。", "今年元夜時，月與燈依舊。不見去年人，淚濕春衫袖。"], "quote": ["去年元夜時，花市燈如晝。月上柳梢頭，人約黃昏後。", "今年元夜時，月與燈依舊。不見去年人，淚濕春衫袖。"], "intro": "《生查子》（去年元夜時）選自《全宋詞》。《生查子》是詞牌名。本詞寫元宵夜的約會。農曆正月十五日是中國傳統節日元宵節，自唐朝起有觀燈鬧夜的風俗。北宋時從正月十四到十六，開宵禁三天，有燈街花市，也是年輕人外出約會的好機會。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%94%9F%E6%9F%A5%E5%AD%90%EF%BC%88%E5%8E%BB%E5%B9%B4%E5%85%83%E5%A4%9C%E6%99%82%EF%BC%89"}, {"title": "秋聲賦", "author": "歐陽修", "period": "宋", "form": "辭賦", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["歐陽子方夜讀書，聞有聲自西南來者，悚然而聽之，曰︰「異哉！」初淅瀝以蕭颯，忽奔騰而砰湃，如波濤夜驚，風雨驟至。其觸於物也，鏦鏦錚錚，金鐵皆鳴；又如赴敵之兵，銜枚疾走，不聞號令，但聞人馬之行聲。", "余謂童子︰「此何聲也？汝出視之。」童子曰︰「星月皎潔，明河在天，四無人聲，聲在樹間。」余曰︰「噫嘻，悲哉！此秋聲也。胡為而來哉。", "蓋夫秋之為狀也，其色慘淡，煙霏雲歛；其容清明，天高日晶；其氣慄冽，砭人肌骨；其意蕭條，山川寂寥。故其為聲也，淒淒切切，呼號憤發。豐草綠縟而爭茂，佳木葱蘢而可悅；草拂之而色變，木遭之而葉脫；其所以摧敗零落者，乃其一氣之餘烈。", "夫秋，刑官也，於時為陰；又兵象也，於行為金。是謂天地之義氣，常以肅殺而為心。天之於物，春生秋實。故其在樂也，商聲主西方之音，夷則為七月之律。商，傷也，物既老而悲傷。夷，戮也，物過盛而當殺。", "嗟乎！草木無情，有時飄零。人為動物，惟物之靈；百憂感其心，萬事勞其形，有動於中，必搖其精。而況思其力之所不及，憂其智之所不能，宜其渥然丹者為槁木，黝然黑者為星星。奈何以非金石之質，欲與草木而爭榮？念誰為之戕賊，亦何恨乎秋聲！」", "童子莫對，垂頭而睡。但聞四壁蟲聲唧唧，如助余之歎息。"], "quote": ["歐陽子方夜讀書，聞有聲自西南來者，悚然而聽之，曰︰「異哉！」初淅瀝以蕭颯，忽奔騰而砰湃，如波濤夜驚，風雨驟至。其觸於物也，鏦鏦錚錚，金鐵皆鳴；又如赴敵之兵，銜枚疾走，不聞號令，但聞人馬之行聲。", "余謂童子︰「此何聲也？汝出視之。」童子曰︰「星月皎潔，明河在天，四無人聲，聲在樹間。」余曰︰「噫嘻，悲哉！此秋聲也。胡為而來哉。", "蓋夫秋之為狀也，其色慘淡，煙霏雲歛；其容清明，天高日晶；其氣慄冽，砭人肌骨；其意蕭條，山川寂寥。故其為聲也，淒淒切切，呼號憤發。豐草綠縟而爭茂，佳木葱蘢而可悅；草拂之而色變，木遭之而葉脫；其所以摧敗零落者，乃其一氣之餘烈。", "夫秋，刑官也，於時為陰；又兵象也，於行為金。是謂天地之義氣，常以肅殺而為心。天之於物，春生秋實。故其在樂也，商聲主西方之音，夷則為七月之律。商，傷也，物既老而悲傷。夷，戮也，物過盛而當殺。"], "intro": "歐陽修《秋聲賦》選自《歐陽修全集》。 《秋聲賦》作於宋仁宗嘉祐四年（一〇五九）。以秋聲發端，描寫暮秋的蕭條景象，感歎自己因人事憂勞，而形神衰老。本文用散文寫法，間以駢偶，是宋朝流行文體之一，稱為文賦。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%A7%8B%E8%81%B2%E8%B3%A6"}, {"title": "畫眉鳥", "author": "歐陽修", "period": "宋", "form": "詩", "theme": "田園幽居", "mood": "majestic_peaks", "lines": ["百囀千聲隨意移，山花紅紫樹高低。", "始知鎖向金籠聽，不及林間自在啼。"], "quote": ["百囀千聲隨意移，山花紅紫樹高低。", "始知鎖向金籠聽，不及林間自在啼。"], "intro": "這首詩作於慶曆七年(1047)，當時歐陽修被貶在滁州（今安徽省滁州市）。詩的另一題目是《郡齋聞百舌》。「郡齋」是作者出任滁州時所居住的官署。「百舌」是畫眉鳥的一種。從這個題目可知，此詩是作者閒居官署時聽到了畫眉鳥歡快的叫聲，有感而作的。歐陽", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%95%AB%E7%9C%89%E9%B3%A5"}, {"title": "誨學（家誡）", "author": "歐陽修", "period": "宋", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["玉不琢，不成器，人不學，不知道。然玉之為物，有不變之常德，雖不琢以為器，而猶不害為玉也；人之性，因物則遷，不學，則捨君子而為小人，可不念哉？"], "quote": ["玉不琢，不成器，人不學，不知道。然玉之為物，有不變之常德，雖不琢以為器，而猶不害為玉也；人之性，因物則遷，不學，則捨君子而為小人，可不念哉？"], "intro": "", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%AA%A8%E5%AD%B8%EF%BC%88%E5%AE%B6%E8%AA%A1%EF%BC%89"}, {"title": "蝶戀花（庭院深深深幾許）", "author": "歐陽修", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "autumn_sunset", "lines": ["庭院深深深幾許？楊柳堆煙，簾幕無重數。玉勒雕鞍遊冶處，樓高不見章臺路。", "雨橫風狂三月暮，門掩黃昏，無計留春住。淚眼問花花不語，亂紅飛過鞦韆去。"], "quote": ["庭院深深深幾許？楊柳堆煙，簾幕無重數。玉勒雕鞍遊冶處，樓高不見章臺路。", "雨橫風狂三月暮，門掩黃昏，無計留春住。淚眼問花花不語，亂紅飛過鞦韆去。"], "intro": "這首詞的作者，也有一種說法認為是南唐的馮延巳。但是，李清照的《臨江仙》曾有自序說：「歐陽公作《蝶戀花》，有『深深深幾許』之句，予酷愛之。用其語作『庭院深深』數闋。」據此，將其定為歐陽修所作。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%9D%B6%E6%88%80%E8%8A%B1%EF%BC%88%E5%BA%AD%E9%99%A2%E6%B7%B1%E6%B7%B1%E6%B7%B1%E5%B9%BE%E8%A8%B1%EF%BC%89%C2%A0"}, {"title": "賣油翁", "author": "歐陽修", "period": "宋", "form": "文", "theme": "田園幽居", "mood": "autumn_sunset", "lines": ["陳康肅公堯咨善射，當世無雙，公亦以此自矜。嘗射於家圃，有賣油翁釋擔而立，睨之，久而不去。見其發矢十中八九，但微頷之。", "康肅問曰︰「汝亦知射乎？吾射不亦精乎？」翁曰︰「無他，但手熟爾。」康肅忿然曰︰「爾安敢輕吾射！」", "翁曰︰「以我酌油知之。」乃取一葫蘆置於地，以錢覆其口，徐以杓酌油瀝之，自錢孔入，而錢不濕。因曰︰「我亦無他，惟手熟爾。」康肅笑而遣之。"], "quote": ["陳康肅公堯咨善射，當世無雙，公亦以此自矜。嘗射於家圃，有賣油翁釋擔而立，睨之，久而不去。見其發矢十中八九，但微頷之。", "康肅問曰︰「汝亦知射乎？吾射不亦精乎？」翁曰︰「無他，但手熟爾。」康肅忿然曰︰「爾安敢輕吾射！」", "翁曰︰「以我酌油知之。」乃取一葫蘆置於地，以錢覆其口，徐以杓酌油瀝之，自錢孔入，而錢不濕。因曰︰「我亦無他，惟手熟爾。」康肅笑而遣之。"], "intro": "本文選自《歐陽文忠公文集》卷一百二十二之《歸田錄》。《歸田錄》共兩卷，乃歐陽修晚年所作。其於自序中云：「《歸田錄》者，朝廷之遺事，史官之所不記，與夫士大夫笑談之餘而可錄者，錄之以備閒居之覽也。」由書中可窺探當時的人物軼事、典章制度、文化風俗", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B3%A3%E6%B2%B9%E7%BF%81"}, {"title": "踏莎行（候館梅殘）", "author": "歐陽修", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "vast_river", "lines": ["候館梅殘，溪橋柳細。草薰風暖搖征轡。離愁漸遠漸無窮，迢迢不斷如春水。", "寸寸柔腸，盈盈粉淚。樓高莫近危闌倚。平蕪盡處是春山，行人更在春山外。"], "quote": ["候館梅殘，溪橋柳細。草薰風暖搖征轡。離愁漸遠漸無窮，迢迢不斷如春水。", "寸寸柔腸，盈盈粉淚。樓高莫近危闌倚。平蕪盡處是春山，行人更在春山外。"], "intro": "《踏莎行》（候館梅殘）選自《全宋詞》。《踏莎行》是詞牌名。本詞描寫一對情人的相思之情。上片寫行人早春羈旅的所見所感，下片寫女子在閨樓中的傷春懷遠之情。文筆婉約，情意深摯。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B8%8F%E8%8E%8E%E8%A1%8C%EF%BC%88%E5%80%99%E9%A4%A8%E6%A2%85%E6%AE%98%EF%BC%89"}, {"title": "醉翁亭記", "author": "歐陽修", "period": "宋", "form": "文", "theme": "田園幽居", "mood": "snow_winter", "lines": ["環滁皆山也。其西南諸峰，林壑尤美；望之蔚然而深秀者，瑯琊也。山行六七里，漸聞水聲潺潺，而瀉出於兩峯之間者，釀泉也。峯回路轉，有亭翼然臨於泉上者，醉翁亭也。", "作亭者誰？山之僧曰智仙也。名之者誰？太守自謂也。太守與客來飲於此，飲少輒醉，而年又最高，故自號曰醉翁也。醉翁之意不在酒，在乎山水之間也。山水之樂，得之心而寓之酒也。", "若夫日出而林霏開，雲歸而巖穴暝，晦明變化者，山間之朝暮也。野芳發而幽香，佳木秀而繁陰，風霜高潔，水落而石出者，山間之四時也。朝而往，暮而歸，四時之景不同，而樂亦無窮也。", "至於負者歌於塗，行者休於樹；前者呼，後者應；傴僂提攜，往來而不絕者，滁人遊也。臨溪而漁，溪深而魚肥；釀泉為酒，泉香而酒洌；山肴野蔌，雜然而前陳者，太守宴也。", "宴酣之樂，非絲非竹，射者中，弈者勝，觥籌交錯，起坐而諠譁者，眾賓懽也。蒼顏白髮，頹然乎其間者，太守醉也。", "已而夕陽在山，人影散亂，太守歸而賓客從也。樹林陰翳，鳴聲上下，遊人去而禽鳥樂也。然而禽鳥知山林之樂，而不知人之樂；人知從太守遊而樂，而不知太守之樂其樂也。", "醉能同其樂，醒能述以文者，太守也。太守謂誰？廬陵歐陽修也。"], "quote": ["環滁皆山也。其西南諸峰，林壑尤美；望之蔚然而深秀者，瑯琊也。山行六七里，漸聞水聲潺潺，而瀉出於兩峯之間者，釀泉也。峯回路轉，有亭翼然臨於泉上者，醉翁亭也。", "作亭者誰？山之僧曰智仙也。名之者誰？太守自謂也。太守與客來飲於此，飲少輒醉，而年又最高，故自號曰醉翁也。醉翁之意不在酒，在乎山水之間也。山水之樂，得之心而寓之酒也。", "若夫日出而林霏開，雲歸而巖穴暝，晦明變化者，山間之朝暮也。野芳發而幽香，佳木秀而繁陰，風霜高潔，水落而石出者，山間之四時也。朝而往，暮而歸，四時之景不同，而樂亦無窮也。", "至於負者歌於塗，行者休於樹；前者呼，後者應；傴僂提攜，往來而不絕者，滁人遊也。臨溪而漁，溪深而魚肥；釀泉為酒，泉香而酒洌；山肴野蔌，雜然而前陳者，太守宴也。"], "intro": "醉翁亭在滁州（今安徽滁縣）城西南瑯琊山兩峯之間，為作者任滁州太守時所築。「記」，即關於醉翁亭的一篇紀念文字。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%86%89%E7%BF%81%E4%BA%AD%E8%A8%98"}, {"title": "瀧岡阡表", "author": "歐陽修", "period": "宋", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["嗚呼！惟我皇考崇公，卜吉于瀧岡之六十年，其子修始克表於其阡。非敢緩也，蓋有待也。", "修不幸，生四歲而孤。太夫人守節自誓，居窮，自力於衣食，以長以教，俾至于成人。太夫人告之曰︰「汝父為吏，廉而好施與，喜賓客。其俸祿雖薄，常不使有餘，曰︰『毋以是為我累。』", "故其亡也，無一瓦之覆，一壠之植，以庇而為生，吾何恃而能自守邪？吾於汝父，知其一二，以有待於汝也。自吾為汝家婦，不及事吾姑，然知汝父之能養也。汝孤而幼，吾不能知汝之必有立，然知汝父之必將有後也。", "吾之始歸也，汝父免於母喪，方逾年，歲時祭祀，則必涕泣曰︰『祭而豐，不如養之薄也。』間御酒食，則又涕泣曰︰『昔常不足而今有餘，其何及也！』吾始一二見之，以為新免於喪適然耳。既而其後常然，至其終身未嘗不然。吾雖不及事姑，而以此知汝父之能養也。汝父為吏，嘗夜燭治官書，屢廢而歎。", "吾問之，則曰︰『此死獄也，我求其生不得爾！』吾曰︰『生可求乎？』曰︰『求其生而不得，則死者與我皆無恨也。矧求而有得邪，以其有得，則知不求而死者有恨也。夫常求其生，猶失之死，而世常求其死也。』回顧乳者劍汝而立于旁，因指而歎曰︰『術者謂我歲行在戌，將死。使其言然，吾不及見兒之立也，後當以我語告之。』", "其平居教他子弟，常用此語，吾耳熟焉，故能詳也。其施於外事，吾不能知；其居於家，無所矜飾，而所為如此，是真發於中者邪。嗚呼！其心厚於仁者邪，此吾知汝父之必將有後也，汝其勉之！", "夫養不必豐，要於孝；利雖不得博於物，要其心之厚於仁。吾不能教汝，此汝父之志也。」修泣而志之，不敢忘。", "先公少孤力學，咸平三年，進士及第，為道州判官，泗綿二州推官，又為泰州判官，享年五十有九，葬沙溪之瀧岡。太夫人姓鄭氏，考諱德儀，世為江南名族。太夫人恭儉仁愛而有禮，初封福昌縣太君，進封樂安、安康、彭城三郡太君。", "自其家少微時，治其家以儉約，其後常不使過之，曰︰「吾兒不能苟合於世，儉薄所以居患難也。」其後修貶夷陵，太夫人言笑自若，曰︰「汝家故貧賤也，吾處之有素矣；汝能安之，吾亦安矣。」", "自先公之亡二十年，修始得祿而養。又十有二年，列官于朝，始得贈封其親。又十年，修為龍圖閣直學士、尚書吏部郎中，留守南京。太夫人以疾終于官舍，享年七十有二。又八年，修以非才入副樞密，遂參政事。又七年而罷。", "自登二府，天子推恩，褒其三世。故自嘉祐以來，逢國大慶，必加寵錫。皇曾祖府君，累贈金紫光祿大夫、太師、中書令；曾祖妣，累封楚國太夫人；皇祖府君，累贈金紫光祿大夫、太師、中書令兼尚書令；祖妣，累封吳國太夫人。", "皇考崇公，累贈金紫光祿大夫、太師、中書令兼尚書令；皇妣，累封越國太夫人。今上初郊，皇考賜爵為崇國公，太夫人進號魏國。"], "quote": ["嗚呼！惟我皇考崇公，卜吉于瀧岡之六十年，其子修始克表於其阡。非敢緩也，蓋有待也。", "修不幸，生四歲而孤。太夫人守節自誓，居窮，自力於衣食，以長以教，俾至于成人。太夫人告之曰︰「汝父為吏，廉而好施與，喜賓客。其俸祿雖薄，常不使有餘，曰︰『毋以是為我累。』", "故其亡也，無一瓦之覆，一壠之植，以庇而為生，吾何恃而能自守邪？吾於汝父，知其一二，以有待於汝也。自吾為汝家婦，不及事吾姑，然知汝父之能養也。汝孤而幼，吾不能知汝之必有立，然知汝父之必將有後也。", "吾之始歸也，汝父免於母喪，方逾年，歲時祭祀，則必涕泣曰︰『祭而豐，不如養之薄也。』間御酒食，則又涕泣曰︰『昔常不足而今有餘，其何及也！』吾始一二見之，以為新免於喪適然耳。既而其後常然，至其終身未嘗不然。吾雖不及事姑，而以此知汝父之能養也。汝父為吏，嘗夜燭治官書，屢廢而歎。"], "intro": "歐陽修《瀧岡阡表》選自《歐陽修全集》。 《瀧岡阡表》是宋神宗熙寧三年（一〇七〇），歐陽修根據舊稿《先君墓表》修改而成。作者四歲喪父，由母親撫育成人。六十年後，始為其父撰寫碑文，是為《瀧岡阡表》。瀧岡，地名，在今江西永豐南。阡，是墓道；表，是", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%80%A7%E5%B2%A1%E9%98%A1%E8%A1%A8"}, {"title": "六國論", "author": "蘇洵", "period": "宋", "form": "文", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["六國破滅，非兵不利，戰不善，弊在賂秦。賂秦而力虧，破滅之道也。或曰︰「六國互喪，率賂秦耶？」曰︰「不賂者以賂者喪。」蓋失強援，不能獨完，故曰「弊在賂秦」也。", "秦以攻取之外，小則獲邑，大則得城，較秦之所得與戰勝而得者，其實百倍；諸侯之所亡與戰敗而亡者，其實亦百倍。則秦之所大欲，諸侯之所大患，固不在戰矣。", "思厥先袓父，暴霜露，斬荊棘，以有尺寸之地。子孫視之不甚惜，舉以予人，如棄草芥。今日割五城，明日割十城，然後得一夕安寢；起視四境，而秦兵又至矣。", "然則諸侯之地有限，暴秦之欲無厭，奉之彌繁，侵之愈急，故不戰而強弱勝負已判矣。至於顛覆，理固宜然。古人云︰「以地事秦，猶抱薪救火，薪不盡，火不滅。」此言得之。", "齊人未嘗賂秦，終繼五國遷滅，何哉？與嬴而不助五國也。五國既喪，齊亦不免矣。燕、趙之君，始有遠略，能守其土，義不賂秦。是故燕雖小國而後亡，斯用兵之效也。至丹以荊卿為計，始速禍焉。", "趙嘗五戰于秦，二敗而三勝；後秦擊趙者再，李牧連卻之。洎牧以讒誅，邯鄲為郡，惜其用武而不終也。且燕、趙處秦革滅殆盡之際，可謂智力孤危，戰敗而亡，誠不得已。", "向使三國各愛其地，齊人勿附于秦，刺客不行，良將猶在，則勝負之數，存亡之理，當與秦相較，或未易量。", "嗚呼！以賂秦之地，封天下之謀臣；以事秦之心，禮天下之奇才；並力西嚮，則吾恐秦人食之不得下咽也。", "悲夫﹗有如此之勢，而為秦人積威之所劫，日削月割以趨於亡！為國者無使為積威之所劫哉！", "夫六國與秦皆諸侯，其勢弱於秦，而猶有可以不賂而勝之之勢；苟以天下之大，而從六國破亡之故事，是又在六國下矣！"], "quote": ["六國破滅，非兵不利，戰不善，弊在賂秦。賂秦而力虧，破滅之道也。或曰︰「六國互喪，率賂秦耶？」曰︰「不賂者以賂者喪。」蓋失強援，不能獨完，故曰「弊在賂秦」也。", "秦以攻取之外，小則獲邑，大則得城，較秦之所得與戰勝而得者，其實百倍；諸侯之所亡與戰敗而亡者，其實亦百倍。則秦之所大欲，諸侯之所大患，固不在戰矣。", "思厥先袓父，暴霜露，斬荊棘，以有尺寸之地。子孫視之不甚惜，舉以予人，如棄草芥。今日割五城，明日割十城，然後得一夕安寢；起視四境，而秦兵又至矣。", "然則諸侯之地有限，暴秦之欲無厭，奉之彌繁，侵之愈急，故不戰而強弱勝負已判矣。至於顛覆，理固宜然。古人云︰「以地事秦，猶抱薪救火，薪不盡，火不滅。」此言得之。"], "intro": "本篇選自《嘉祐集》，為《權書》諸篇之一；原題無「論」字，因其為議論文，特照《唐宋八大家文鈔》補。六國，即戰國時代為秦先後所滅的韓、趙、魏、燕、楚、齊。本文乃析論六國滅亡之由，藉以針砭當時北宋對外族忍辱求和的政策。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%85%AD%E5%9C%8B%E8%AB%96"}, {"title": "淮中晚泊犢頭", "author": "蘇舜欽", "period": "宋", "form": "詩", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["春陰垂野草青青，時有幽花一樹明。", "晚泊孤舟古祠下，滿川風雨看潮生。"], "quote": ["春陰垂野草青青，時有幽花一樹明。", "晚泊孤舟古祠下，滿川風雨看潮生。"], "intro": "淮中泛指淮河流域。犢（粵：[讀duk9]；普：[dú]。）頭是淮河沿岸地名。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B7%AE%E4%B8%AD%E6%99%9A%E6%B3%8A%E7%8A%A2%E9%A0%AD"}, {"title": "卜算子（缺月掛疏桐）", "author": "蘇軾", "period": "宋", "form": "詞", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["黃州定慧院寓居作", "缺月掛疏桐，漏斷人初靜。誰見幽人獨往來，縹緲孤鴻影。", "驚起卻回頭，有恨無人省。揀盡寒枝不肯棲，寂寞沙洲冷。"], "quote": ["黃州定慧院寓居作", "缺月掛疏桐，漏斷人初靜。誰見幽人獨往來，縹緲孤鴻影。", "驚起卻回頭，有恨無人省。揀盡寒枝不肯棲，寂寞沙洲冷。"], "intro": "東坡於元豐三年（一〇八〇）二月一日至黃州貶所，初寓居定慧院（一作定惠院，在黃州城東南清淮門外）；五月遷臨皋亭（在黃州城南長江邊）。此詞的詞題說是「黃州定慧院寓居作」，則當作於本年初到黃州時，二月至五月間。 東坡初到黃州，心情極為沉鬱悲痛。士", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%8D%9C%E7%AE%97%E5%AD%90%EF%BC%88%E7%BC%BA%E6%9C%88%E6%8E%9B%E7%96%8F%E6%A1%90%EF%BC%89"}, {"title": "方山子傳", "author": "蘇軾", "period": "宋", "form": "文", "theme": "山水登臨", "mood": "autumn_sunset", "lines": ["方山子，光、黃間隱人也。少時慕朱家、郭解為人，閭里之俠皆宗之。稍壯，折節讀書，欲以此馳騁當世，然終不遇。晚乃遯於光、黃間，曰︰「岐亭」。庵居蔬食，不與世相聞。棄車馬，毀冠服，徒步往來山中，人莫識也。見其所著帽，方屋而高，曰︰「此豈古方山冠之遺像乎？」因謂之「方山子」。", "余謫居於黃，過岐亭，適見焉，曰︰「嗚呼！此吾故人陳慥季常也，何為而在此？」方山子亦矍然問余所以至此者。余告之故。俛而不答，仰而笑。呼余宿其家。環堵蕭然，而妻子奴婢，皆有自得之意。", "余既聳然異之，獨念方山子少時，使酒好劍，用財如糞土；前十有九年，余在岐山，見方山子從兩騎，挾二矢，遊西山。鵲起於前，使騎逐而射之，不獲；方山子怒馬獨出，一發得之。因與余馬上論用兵，及古今成敗，自謂一世豪士。今幾日耳，精悍之色，猶見於眉間，而豈山中之人哉？", "然方山子世有勳閥，當得官；使從事於其間，今已顯聞。而其家在洛陽，園宅壯麗，與公侯等；河北有田，歲得帛千匹，亦足以富樂；皆棄不取，獨來窮山中，此豈無得而然哉？", "余聞光、黃間多異人，往往佯狂垢污，不可得而見，方山子儻見之歟？"], "quote": ["方山子，光、黃間隱人也。少時慕朱家、郭解為人，閭里之俠皆宗之。稍壯，折節讀書，欲以此馳騁當世，然終不遇。晚乃遯於光、黃間，曰︰「岐亭」。庵居蔬食，不與世相聞。棄車馬，毀冠服，徒步往來山中，人莫識也。見其所著帽，方屋而高，曰︰「此豈古方山冠之遺像乎？」因謂之「方山子」。", "余謫居於黃，過岐亭，適見焉，曰︰「嗚呼！此吾故人陳慥季常也，何為而在此？」方山子亦矍然問余所以至此者。余告之故。俛而不答，仰而笑。呼余宿其家。環堵蕭然，而妻子奴婢，皆有自得之意。", "余既聳然異之，獨念方山子少時，使酒好劍，用財如糞土；前十有九年，余在岐山，見方山子從兩騎，挾二矢，遊西山。鵲起於前，使騎逐而射之，不獲；方山子怒馬獨出，一發得之。因與余馬上論用兵，及古今成敗，自謂一世豪士。今幾日耳，精悍之色，猶見於眉間，而豈山中之人哉？", "然方山子世有勳閥，當得官；使從事於其間，今已顯聞。而其家在洛陽，園宅壯麗，與公侯等；河北有田，歲得帛千匹，亦足以富樂；皆棄不取，獨來窮山中，此豈無得而然哉？"], "intro": "方山子，姓陳，名慥，字季常，宋眉州青神（今四川青神縣）人，一說永嘉（今浙江永嘉縣）人。他和蘇軾是朋友，生平已詳本文。另有一事為本文所未載者，即陳慥妻柳氏，性悍妬，慥每宴客，有聲伎，柳氏即以杖擊壁大呼，客為散去，蘇軾有戲季常詩云：「忽聞河東獅", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%96%B9%E5%B1%B1%E5%AD%90%E5%82%B3"}, {"title": "水調歌頭  並序（明月幾時有）", "author": "蘇軾", "period": "宋", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["丙辰中秋，歡飲達旦，大醉，作此篇，兼懷子由。", "明月幾時有？把酒問青天。不知天上宮闕，今夕是何年。我欲乘風歸去，又恐瓊樓玉宇，高處不勝寒。起舞弄清影，何似在人間！", "轉朱閣，低綺戶，照無眠。不應有恨，何事長向別時圓？人有悲歡離合，月有陰晴圓缺，此事古難全。但願人長久，千里共嬋娟。"], "quote": ["丙辰中秋，歡飲達旦，大醉，作此篇，兼懷子由。", "明月幾時有？把酒問青天。不知天上宮闕，今夕是何年。我欲乘風歸去，又恐瓊樓玉宇，高處不勝寒。起舞弄清影，何似在人間！", "轉朱閣，低綺戶，照無眠。不應有恨，何事長向別時圓？人有悲歡離合，月有陰晴圓缺，此事古難全。但願人長久，千里共嬋娟。"], "intro": "《水調歌頭》是詞牌名。又名《元會曲》、《臺城遊》等。相傳隋煬帝開鑿汴河時曾製作《水調歌》，唐人演為大曲。大曲有散序、中序、入破三部分，「歌頭」是中序的第一章。 蘇軾這首《水調歌頭》詞前有序：「丙辰中秋，歡飲達旦，大醉，作此篇，兼懷子由。」說", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B0%B4%E8%AA%BF%E6%AD%8C%E9%A0%AD++%E4%B8%A6%E5%BA%8F%EF%BC%88%E6%98%8E%E6%9C%88%E5%B9%BE%E6%99%82%E6%9C%89%EF%BC%89"}, {"title": "水龍吟（似花還似非花）", "author": "蘇軾", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "vast_river", "lines": ["次韻章質夫楊花詞", "似花還似非花，也無人惜從教墜。拋家傍路，思量卻是，無情有思。縈損柔腸，困酣嬌眼，欲開還閉。夢隨風萬里，尋郎去處，又還被、鶯呼起。", "不恨此花飛盡，恨西園、落紅難綴！曉來雨過，遺蹤何在？一池萍碎。春色三分︰二分塵土，一分流水。細看來不是楊花，點點是，離人淚。"], "quote": ["次韻章質夫楊花詞", "似花還似非花，也無人惜從教墜。拋家傍路，思量卻是，無情有思。縈損柔腸，困酣嬌眼，欲開還閉。夢隨風萬里，尋郎去處，又還被、鶯呼起。", "不恨此花飛盡，恨西園、落紅難綴！曉來雨過，遺蹤何在？一池萍碎。春色三分︰二分塵土，一分流水。細看來不是楊花，點點是，離人淚。"], "intro": "蘇軾《水龍吟》（似花還似非花）選自《全宋詞》。 《水龍吟》詞調，首見於柳永的詠梅之作，其次就是章質夫、蘇軾的唱和詞。章楶，字質夫，浦城（今福建浦城）人。當時與蘇軾同官京師。章質夫詠楊花的《水龍吟》為當時名作，蘇軾依照章詞的原韻和了此詞，所以", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B0%B4%E9%BE%8D%E5%90%9F%EF%BC%88%E4%BC%BC%E8%8A%B1%E9%82%84%E4%BC%BC%E9%9D%9E%E8%8A%B1%EF%BC%89"}, {"title": "永遇樂  并序（明月如霜）", "author": "蘇軾", "period": "宋", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["夜宿燕子樓，夢盼盼，因作此詞。", "明月如霜，好風如水，清景無限。曲港跳魚，圓荷瀉露，寂寞無人見。紞如三鼓，鏗然一葉，黯黯夢雲驚斷。夜茫茫，重尋無處，覺來小園行徧。", "天涯倦客，山中歸路，望斷故園心眼。燕子樓空，佳人何在？空鎖樓中燕！古今如夢，何曾夢覺？但有舊歡新怨。異時對、黃樓夜景，為余浩歎！"], "quote": ["夜宿燕子樓，夢盼盼，因作此詞。", "明月如霜，好風如水，清景無限。曲港跳魚，圓荷瀉露，寂寞無人見。紞如三鼓，鏗然一葉，黯黯夢雲驚斷。夜茫茫，重尋無處，覺來小園行徧。", "天涯倦客，山中歸路，望斷故園心眼。燕子樓空，佳人何在？空鎖樓中燕！古今如夢，何曾夢覺？但有舊歡新怨。異時對、黃樓夜景，為余浩歎！"], "intro": "蘇軾《永遇樂》（明月如霜）選自《全宋詞》。 此詞作於元豐元年（一〇七八）秋，東坡四十三歲，任徐州知州。前一年東坡與徐州軍民共抗水患，水退後，又親自參與增修城牆，並向朝廷申請撥款修建大堤，完成種種治水工作。這年二月他另在彭城（徐州城）東門新建", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B0%B8%E9%81%87%E6%A8%82++%E5%B9%B6%E5%BA%8F%EF%BC%88%E6%98%8E%E6%9C%88%E5%A6%82%E9%9C%9C%EF%BC%89"}, {"title": "石鐘山記", "author": "蘇軾", "period": "宋", "form": "文", "theme": "山水登臨", "mood": "vast_river", "lines": ["《水經》云︰「彭蠡之口，有石鐘山焉。」酈元以為︰「下臨深潭，微風鼓浪，水石相搏，聲如洪鐘。」是說也，人常疑之。今以鐘磬置水中，雖大風浪不能鳴也，而況石乎？", "至唐李渤，始訪其遺蹤，得雙石於潭上，扣而聆之，南聲函胡，北音清越，枹止響騰，餘韻徐歇；自以為得之矣。然是說也，余尤疑之，石之鏗然有聲者，所在皆是也，而此獨以鐘名，何哉？", "元豐七年六月丁丑，余自齊安舟行適臨汝，而長子邁，將赴饒之德興尉，送之至湖口，因得觀所謂石鐘者。寺僧使小童持斧，於亂石間擇其一二，扣之硿硿然；余固笑而不信也。至其夜，月明，獨與邁乘小舟至絕壁下。", "大石側立千尺，如猛獸奇鬼，森然欲搏人；而山上棲鶻聞人聲，亦驚起，磔磔雲霄間；又有若老人欬且笑於山谷中者，或曰︰「此鸛鶴也。」余方心動，欲還，而大聲發於水上，噌吰如鐘鼓不絕。舟人大恐。徐而察之，則山下皆石穴罅，不知其淺深；微波入焉，涵澹澎湃而為此也。", "舟迴至兩山間，將入港口，有大石當中流，可坐百人，空中而多竅，與風水相吞吐，有窾坎鏜鞳之聲；與向之噌吰者相應，如樂作焉。因笑謂邁曰︰「汝識之乎？噌吰者周景王之無射也；窾坎鏜鞳者，魏獻子之歌鐘也；古之人不余欺也。」", "事不目見耳聞而臆斷其有無，可乎？酈元之所見聞，殆與余同，而言之不詳。士大夫終不肯以小舟夜泊絕壁之下，故莫能知。而漁工水師，雖知而不能言，此世所以不傳也。而陋者乃以斧斤考擊而求之，自以為得其實。余是以記之，蓋歎酈元之簡，而笑李渤之陋也。"], "quote": ["《水經》云︰「彭蠡之口，有石鐘山焉。」酈元以為︰「下臨深潭，微風鼓浪，水石相搏，聲如洪鐘。」是說也，人常疑之。今以鐘磬置水中，雖大風浪不能鳴也，而況石乎？", "至唐李渤，始訪其遺蹤，得雙石於潭上，扣而聆之，南聲函胡，北音清越，枹止響騰，餘韻徐歇；自以為得之矣。然是說也，余尤疑之，石之鏗然有聲者，所在皆是也，而此獨以鐘名，何哉？", "元豐七年六月丁丑，余自齊安舟行適臨汝，而長子邁，將赴饒之德興尉，送之至湖口，因得觀所謂石鐘者。寺僧使小童持斧，於亂石間擇其一二，扣之硿硿然；余固笑而不信也。至其夜，月明，獨與邁乘小舟至絕壁下。", "大石側立千尺，如猛獸奇鬼，森然欲搏人；而山上棲鶻聞人聲，亦驚起，磔磔雲霄間；又有若老人欬且笑於山谷中者，或曰︰「此鸛鶴也。」余方心動，欲還，而大聲發於水上，噌吰如鐘鼓不絕。舟人大恐。徐而察之，則山下皆石穴罅，不知其淺深；微波入焉，涵澹澎湃而為此也。"], "intro": "石鐘山在江西湖口縣境，位鄱陽湖東岸。山有二：一在縣治南，曰上鐘山，一在縣治北，曰下鐘山，各距縣一里，皆高五六百尺，周十里許。其勢相向，土人稱為雙鐘。《水經注》以為「水石相搏，聲如洪鐘。」曾國藩《求闕齋讀書錄》則以為「上鐘巖與下鐘巖皆有洞，形", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%9F%B3%E9%90%98%E5%B1%B1%E8%A8%98"}, {"title": "江城子（十年生死兩茫茫）", "author": "蘇軾", "period": "宋", "form": "詞", "theme": "江河湖海", "mood": "snow_winter", "lines": ["乙卯正月二十日夜記夢", "十年生死兩茫茫。不思量，自難忘。千里孤墳，無處話淒涼。縱使相逢應不識，塵滿面，鬢如霜。", "夜來幽夢忽還鄉。小軒窗，正梳妝。相顧無言，惟有淚千行。料得年年腸斷處，明月夜，短松岡。"], "quote": ["乙卯正月二十日夜記夢", "十年生死兩茫茫。不思量，自難忘。千里孤墳，無處話淒涼。縱使相逢應不識，塵滿面，鬢如霜。", "夜來幽夢忽還鄉。小軒窗，正梳妝。相顧無言，惟有淚千行。料得年年腸斷處，明月夜，短松岡。"], "intro": "本詞名為《江城子》，共七十字。前後兩半闋相同，各為八句，句法為七三三、四五、七三三，均五用韻。 本詞作者自註云：「乙卯正月二十日夜，記夢。」乙卯，即宋神熙寧八年。乃作者妻子死後十年，夢中相見，醒後所作。前半闋先寫生離死別後十年間相思之苦，以", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B1%9F%E5%9F%8E%E5%AD%90%EF%BC%88%E5%8D%81%E5%B9%B4%E7%94%9F%E6%AD%BB%E5%85%A9%E8%8C%AB%E8%8C%AB%EF%BC%89"}, {"title": "江城子（老夫聊發少年狂）", "author": "蘇軾", "period": "宋", "form": "詞", "theme": "邊塞豪放", "mood": "snow_winter", "lines": ["密州出獵", "老夫聊發少年狂。左牽黃，右擎蒼。錦帽貂裘，千騎卷平岡。為報傾城隨太守，親射虎，看孫郎。", "酒酣胸膽尚開張。鬢微霜，又何妨。持節雲中，何日遣馮唐。會挽雕弓如滿月，西北望，射天狼。"], "quote": ["密州出獵", "老夫聊發少年狂。左牽黃，右擎蒼。錦帽貂裘，千騎卷平岡。為報傾城隨太守，親射虎，看孫郎。", "酒酣胸膽尚開張。鬢微霜，又何妨。持節雲中，何日遣馮唐。會挽雕弓如滿月，西北望，射天狼。"], "intro": "熙寧八年（一〇七五），東坡任密州知州，這年冬天，他到常山祭祀，歸途中與同官梅戶曹會獵於鐵溝，一時興起，作了這首滿懷豪情的詞。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B1%9F%E5%9F%8E%E5%AD%90%EF%BC%88%E8%80%81%E5%A4%AB%E8%81%8A%E7%99%BC%E5%B0%91%E5%B9%B4%E7%8B%82%EF%BC%89"}, {"title": "花影", "author": "蘇軾", "period": "宋", "form": "詩", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["重重疊疊上瑤台，幾度呼童掃不開。", "剛被太陽收拾去，卻教明月送將來。"], "quote": ["重重疊疊上瑤台，幾度呼童掃不開。", "剛被太陽收拾去，卻教明月送將來。"], "intro": "", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%8A%B1%E5%BD%B1"}, {"title": "和子由澠池懷舊", "author": "蘇軾", "period": "宋", "form": "詩", "theme": "江河湖海", "mood": "snow_winter", "lines": ["人生到處知何似？應似飛鴻踏雪泥。", "泥上偶然留指爪，鴻飛那復計東西。", "老僧已死成新塔，壞壁無由見舊題。", "往日崎嶇還記否？路長人困蹇驢嘶。"], "quote": ["人生到處知何似？應似飛鴻踏雪泥。", "泥上偶然留指爪，鴻飛那復計東西。", "老僧已死成新塔，壞壁無由見舊題。", "往日崎嶇還記否？路長人困蹇驢嘶。"], "intro": "這首詩是蘇軾就弟弟蘇轍（字子由）所作《懷澠池寄子瞻兄》而寫的和韻詩。嘉祐元年（1056年），蘇軾和弟弟蘇轍赴京應試，路過澠池（今河南澠池縣），在縣中寺院留宿，並曾在壁上題詩。到嘉祐六年（1061年），蘇軾被任命為鳳翔簽判，弟弟蘇轍送他上任，", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%92%8C%E5%AD%90%E7%94%B1%E6%BE%A0%E6%B1%A0%E6%87%B7%E8%88%8A"}, {"title": "定風波（莫聽穿林打葉聲）", "author": "蘇軾", "period": "宋", "form": "詞", "theme": "田園幽居", "mood": "snow_winter", "lines": ["三月七日，沙湖道中遇雨。雨具先去，同行皆狼狽，余獨不覺，已而遂晴，故作此。", "莫聽穿林打葉聲，何妨吟嘯且徐行。竹杖芒鞋輕勝馬，誰怕？一蓑煙雨任平生。", "料峭春風吹酒醒，微冷，山頭斜照卻相迎。回首向來蕭瑟處，歸去，也無風雨也無晴。"], "quote": ["三月七日，沙湖道中遇雨。雨具先去，同行皆狼狽，余獨不覺，已而遂晴，故作此。", "莫聽穿林打葉聲，何妨吟嘯且徐行。竹杖芒鞋輕勝馬，誰怕？一蓑煙雨任平生。", "料峭春風吹酒醒，微冷，山頭斜照卻相迎。回首向來蕭瑟處，歸去，也無風雨也無晴。"], "intro": "元豐五年（一〇八二）三月七日，東坡寫作《寒食雨》後不久，雨勢稍微緩和，他終於可以踏出臨皋亭住家，心情也好轉。東坡與朋友一起去黃州東南三十里處的沙湖看田地。在人群中的東坡，比起之前因雨發愁的他，顯得更有精神。這趟出遊，一路行來，原以為天氣應該", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%AE%9A%E9%A2%A8%E6%B3%A2%EF%BC%88%E8%8E%AB%E8%81%BD%E7%A9%BF%E6%9E%97%E6%89%93%E8%91%89%E8%81%B2%EF%BC%89"}, {"title": "念奴嬌 赤壁懷古（大江東去）", "author": "蘇軾", "period": "宋", "form": "詩", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["大江東去，浪淘盡，千古風流人物。故壘西邊，人道是︰三國周郎赤壁。亂石穿空，驚濤拍岸，捲起千堆雪。江山如畫，一時多少豪傑！", "遙想公瑾當年，小喬初嫁了，雄姿英發。羽扇綸巾，談笑間、檣櫓灰飛煙滅。故國神遊，多情應笑我，早生華髮。人生如夢，一尊還酹江月。"], "quote": ["大江東去，浪淘盡，千古風流人物。故壘西邊，人道是︰三國周郎赤壁。亂石穿空，驚濤拍岸，捲起千堆雪。江山如畫，一時多少豪傑！", "遙想公瑾當年，小喬初嫁了，雄姿英發。羽扇綸巾，談笑間、檣櫓灰飛煙滅。故國神遊，多情應笑我，早生華髮。人生如夢，一尊還酹江月。"], "intro": "元豐二年（公元1079年），發生了「烏臺詩案」，蘇軾被彈劾以詩文諷喻朝政，結果被捕入獄，翌年被貶黃州。來到黃州後，蘇軾四處遊山玩水，「深自閉塞，扁舟革履，放浪山水之間，與漁樵雜處」，就在元豐五年（公元1082年），他遊黃州赤壁（鼻）磯，寫下", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%BF%B5%E5%A5%B4%E5%AC%8C+%E8%B5%A4%E5%A3%81%E6%87%B7%E5%8F%A4%EF%BC%88%E5%A4%A7%E6%B1%9F%E6%9D%B1%E5%8E%BB%EF%BC%89"}, {"title": "前赤壁賦", "author": "蘇軾", "period": "宋", "form": "辭賦", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["壬戌之秋，七月既望，蘇子與客泛舟遊於赤壁之下。清風徐來，水波不興。舉酒屬客，誦明月之詩，歌窈窕之章。少焉，月出於東山之上，徘徊於斗牛之間。", "白露橫江，水光接天。縱一葦之所如，凌萬頃之茫然。浩浩乎如憑虛御風，而不知其所止；飄飄乎如遺世獨立，羽化而登仙。", "於是飲酒樂甚，扣舷而歌之。歌曰︰「桂棹兮蘭槳，擊空明兮泝流光。渺渺兮予懷，望美人兮天一方。」客有吹洞簫者，倚歌而和之，其聲嗚嗚然，如怨如慕，如泣如訴。餘音嫋嫋，不絕如縷。舞幽壑之潛蛟，泣孤舟之嫠婦。", "蘇子愀然，正襟危坐，而問客曰︰「何為其然也？」客曰︰「『月明星稀，烏鵲南飛。』此非曹孟德之詩乎？西望夏口，東望武昌。山川相繆，鬱乎蒼蒼。此非孟德之困於周郎者乎？", "方其破荊州，下江陵，順流而東也，舳艫千里，旌旗蔽空，釃酒臨江，橫槊賦詩，固一世之雄也，而今安在哉？況吾與子漁樵於江渚之上，侶魚蝦而友麋鹿。駕一葉之扁舟，舉匏尊以相屬。", "寄蜉蝣於天地，眇滄海之一粟。哀吾生之須臾，羨長江之無窮。挾飛仙以遨遊，抱明月而長終。知不可乎驟得，託遺響於悲風。」", "蘇子曰︰「客亦知夫水與月乎？逝者如斯，而未嘗往也。盈虛者如彼，而卒莫消長也。蓋將自其變者而觀之，則天地曾不能以一瞬。自其不變者而觀之，則物與我皆無盡也，而又何羨乎？且夫天地之間，物各有主，苟非吾之所有，雖一毫而莫取。", "惟江上之清風，與山間之明月，耳得之而為聲，目遇之而成色。取之無禁，用之不竭。是造物者之無盡藏也，而吾與子之所共適。」客喜而笑，洗盞更酌，肴核既盡，杯盤狼藉，相與枕藉乎舟中，不知東方之既白。"], "quote": ["壬戌之秋，七月既望，蘇子與客泛舟遊於赤壁之下。清風徐來，水波不興。舉酒屬客，誦明月之詩，歌窈窕之章。少焉，月出於東山之上，徘徊於斗牛之間。", "白露橫江，水光接天。縱一葦之所如，凌萬頃之茫然。浩浩乎如憑虛御風，而不知其所止；飄飄乎如遺世獨立，羽化而登仙。", "於是飲酒樂甚，扣舷而歌之。歌曰︰「桂棹兮蘭槳，擊空明兮泝流光。渺渺兮予懷，望美人兮天一方。」客有吹洞簫者，倚歌而和之，其聲嗚嗚然，如怨如慕，如泣如訴。餘音嫋嫋，不絕如縷。舞幽壑之潛蛟，泣孤舟之嫠婦。", "蘇子愀然，正襟危坐，而問客曰︰「何為其然也？」客曰︰「『月明星稀，烏鵲南飛。』此非曹孟德之詩乎？西望夏口，東望武昌。山川相繆，鬱乎蒼蒼。此非孟德之困於周郎者乎？"], "intro": "這篇文章是作者貶官黃州（今湖北黃岡縣）時，和賓客們遊歷赤壁以後寫的。「賦」是一種文體。赤壁，山名；有二，都在湖北省境。一在嘉魚縣東北長江南岸，岡巒綿亙如垣，上鐫「赤壁」二字，三國時吳周瑜蜀劉備聯合打敗曹操，就在這個地方。二在黃岡縣城外，也叫", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%89%8D%E8%B5%A4%E5%A3%81%E8%B3%A6"}, {"title": "洞仙歌（冰肌玉骨）", "author": "蘇軾", "period": "宋", "form": "詞", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["余七歲時，見眉山老尼，姓朱，忘其名，年九十餘。自言︰嘗隨其師入蜀主孟昶宮中。一日大熱，蜀主與花蕊夫人夜納涼摩訶池上，作一詞。朱具能記之。今四十年，朱已死久矣，人無知此詞者，但記其首兩句。暇日尋味，豈《洞仙歌令》乎？乃為足之云。", "冰肌玉骨，自清涼無汗。水殿風來暗香滿。繡簾開、一點明月窺人，人未寢，攲枕釵橫鬢亂。", "起來攜素手，庭戶無聲，時見疏星渡河漢。試問夜如何，夜已三更，金波淡、玉繩低轉。但屈指西風幾時來，又不道流年，暗中偷換。"], "quote": ["余七歲時，見眉山老尼，姓朱，忘其名，年九十餘。自言︰嘗隨其師入蜀主孟昶宮中。一日大熱，蜀主與花蕊夫人夜納涼摩訶池上，作一詞。朱具能記之。今四十年，朱已死久矣，人無知此詞者，但記其首兩句。暇日尋味，豈《洞仙歌令》乎？乃為足之云。", "冰肌玉骨，自清涼無汗。水殿風來暗香滿。繡簾開、一點明月窺人，人未寢，攲枕釵橫鬢亂。", "起來攜素手，庭戶無聲，時見疏星渡河漢。試問夜如何，夜已三更，金波淡、玉繩低轉。但屈指西風幾時來，又不道流年，暗中偷換。"], "intro": "元豐五年（一〇八三）夏日，東坡想起四十年前在家鄉眉州的童年舊事，作《洞仙歌》一首。整首詞所關心的仍是時間的主題：「但屈指西風幾時來，又不道流年，暗中偷換。」寫後蜀花蕊夫人納涼情景，百年往事，依稀目前，細細回味中，時間不曾停歇。東坡借事述懷，", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B4%9E%E4%BB%99%E6%AD%8C%EF%BC%88%E5%86%B0%E8%82%8C%E7%8E%89%E9%AA%A8%EF%BC%89"}, {"title": "浣溪沙（山下蘭芽短浸溪）", "author": "蘇軾", "period": "宋", "form": "詞", "theme": "山水登臨", "mood": "autumn_sunset", "lines": ["游蘄水清泉寺。寺臨蘭溪，溪水西流。", "山下蘭芽短浸溪。松間沙路淨無泥。蕭蕭暮雨子規啼。", "誰道人生無再少，門前流水尚能西。休將白髮唱黃雞。"], "quote": ["游蘄水清泉寺。寺臨蘭溪，溪水西流。", "山下蘭芽短浸溪。松間沙路淨無泥。蕭蕭暮雨子規啼。", "誰道人生無再少，門前流水尚能西。休將白髮唱黃雞。"], "intro": "《東坡志林》記述：黃州東南三十里為沙湖，亦名螺師店，東坡要到那裏去買田，不料前往看田時生病了。聽聞附近有位耳聾的名醫龐安常（名安時），便去找他求診，經過幾天的治療，結果病真的好了。龐安常雖然聽不見，但他絕頂聰穎，看人用手指點畫數字，就已深刻", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B5%A3%E6%BA%AA%E6%B2%99%EF%BC%88%E5%B1%B1%E4%B8%8B%E8%98%AD%E8%8A%BD%E7%9F%AD%E6%B5%B8%E6%BA%AA%EF%BC%89"}, {"title": "記承天寺夜遊", "author": "蘇軾", "period": "宋", "form": "文", "theme": "江河湖海", "mood": "vast_river", "lines": ["元豐六年十月十二日，夜，解衣欲睡，月色入戶，欣然起行。念無與為樂者，遂至承天寺，尋張懷民。懷民亦未寢，相與步於中庭。", "庭下如積水空明，水中藻、荇交橫，蓋竹柏影也。", "何夜無月？何處無竹柏？但少閑人如吾兩人者耳。"], "quote": ["元豐六年十月十二日，夜，解衣欲睡，月色入戶，欣然起行。念無與為樂者，遂至承天寺，尋張懷民。懷民亦未寢，相與步於中庭。", "庭下如積水空明，水中藻、荇交橫，蓋竹柏影也。", "何夜無月？何處無竹柏？但少閑人如吾兩人者耳。"], "intro": "本文是蘇軾被貶黃州時所作。蘇軾因和王安石政見不合，元豐二年（公元1079），被貶為黃州團練副使，在官銜上還加上「本州安置」的字樣，表示不得參與公事，事實形同流放。元豐六年（公元1083），他的朋友張懷民也被貶來黃州，暫寄住於承天寺（在今湖北", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A8%98%E6%89%BF%E5%A4%A9%E5%AF%BA%E5%A4%9C%E9%81%8A"}, {"title": "惠崇春江晚景", "author": "蘇軾", "period": "宋", "form": "詩", "theme": "春水花鳥", "mood": "autumn_sunset", "lines": ["竹外桃花三兩枝，春江水暖鴨先知。", "蔞蒿滿地蘆芽短，正是河豚欲上時。"], "quote": ["竹外桃花三兩枝，春江水暖鴨先知。", "蔞蒿滿地蘆芽短，正是河豚欲上時。"], "intro": "這是蘇軾在神宗元豐八年（公元1085）在汴京（今河南省開封市）寫的一首題畫詩。他所題的，是宋初名畫家惠崇的一幅畫。惠崇是一位僧人，工畫水禽，特別擅長繪畫水鄉景色，點綴鵝雁、鷺鷥等，人稱「惠崇小景」。這首詩所提的畫，是一幅以春天景物為背景的鴨", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%83%A0%E5%B4%87%E6%98%A5%E6%B1%9F%E6%99%9A%E6%99%AF"}, {"title": "超然臺記", "author": "蘇軾", "period": "宋", "form": "文", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["凡物皆有可觀。苟有可觀，皆有可樂，非必怪奇偉麗者也。哺糟啜醨皆可以醉；果蔬草木，皆可以飽。推此類也，吾安往而不樂？", "夫所爲求褔而辭禍者，以褔可喜而禍可悲也。人之所欲無窮，而物之可以足吾欲者有盡，美惡之辨戰乎中，而去取之擇交乎前。則可樂者常少，而可悲者常多。是謂求禍而辭褔。夫求禍而辭褔，豈人之情也哉？物有以蓋之矣。", "彼遊於物之內，而不遊於物之外。物非有大小也，自其內而觀之，未有不高且大者也。彼挾其高大以臨我，則我常眩亂反覆，如隙中之觀鬥，又焉知勝負之所在。是以美惡橫生，而憂樂出焉，可不大哀乎！", "余自錢塘移守膠西，釋舟楫之安，而服車馬之勞；去雕牆之美，而蔽採椽之居；背湖山之觀，而適桑麻之野。始至之日，歲比不登，盜賊滿野，獄訟充斥；而齋廚索然，日食杞菊。人固疑余之不樂也。處之期年，而貌加豐，髮之白者日以反黑。", "余既樂其風俗之淳，而其吏民亦安予之拙也。於是治其園圃，潔其庭宇，伐安丘、高密之木，以修補破敗，爲苟全之計。而園之北，因城以爲臺者舊矣，稍葺而新之。", "時相與登覽，放意肆志焉。南望馬耳常山，出沒隱見，若近若遠，庶幾有隱君子乎！而其東則盧山，秦人盧敖之所從遁也。西望穆陵，隱然如城郭，師尚父、齊桓公之遺烈，猶有存者。北俯濰水，慨然太息，思淮陰之功，而弔其不終。臺高而安，深而明，夏涼而冬溫。", "雨雪之朝，風月之夕，余未嘗不在，客未嘗不從。擷園蔬，取池魚，釀秫酒，瀹脫粟而食之，曰︰「樂哉遊乎！」", "方是時，余弟子由，適在濟南，聞而賦之，且名其臺曰「超然」，以見余之無所往而不樂者，蓋遊於物之外也。"], "quote": ["凡物皆有可觀。苟有可觀，皆有可樂，非必怪奇偉麗者也。哺糟啜醨皆可以醉；果蔬草木，皆可以飽。推此類也，吾安往而不樂？", "夫所爲求褔而辭禍者，以褔可喜而禍可悲也。人之所欲無窮，而物之可以足吾欲者有盡，美惡之辨戰乎中，而去取之擇交乎前。則可樂者常少，而可悲者常多。是謂求禍而辭褔。夫求禍而辭褔，豈人之情也哉？物有以蓋之矣。", "彼遊於物之內，而不遊於物之外。物非有大小也，自其內而觀之，未有不高且大者也。彼挾其高大以臨我，則我常眩亂反覆，如隙中之觀鬥，又焉知勝負之所在。是以美惡橫生，而憂樂出焉，可不大哀乎！", "余自錢塘移守膠西，釋舟楫之安，而服車馬之勞；去雕牆之美，而蔽採椽之居；背湖山之觀，而適桑麻之野。始至之日，歲比不登，盜賊滿野，獄訟充斥；而齋廚索然，日食杞菊。人固疑余之不樂也。處之期年，而貌加豐，髮之白者日以反黑。"], "intro": "蘇軾反對王安石變法，爲新黨所不容，被排擠出朝廷，先任開封府推官，繼任杭州通判。「三年不得代，以轍之在濟南。求爲東州守」。蘇軾《欒城集‧超然亭賦序》。宋神宗熙寧七年1074年被批准改任密州（今山東省諸城）太守。第二年，政局初定，他便開始治園圃", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B6%85%E7%84%B6%E8%87%BA%E8%A8%98"}, {"title": "飲湖上初晴後雨（其二）", "author": "蘇軾", "period": "宋", "form": "詩", "theme": "江河湖海", "mood": "vast_river", "lines": ["水光瀲灧晴方好，山色空濛雨亦奇。", "若把西湖比西子，淡粧濃抹總相宜。"], "quote": ["水光瀲灧晴方好，山色空濛雨亦奇。", "若把西湖比西子，淡粧濃抹總相宜。"], "intro": "《飲湖上初晴後雨》選自《蘇軾詩集》卷九，作於宋神宗熙寧六年（一〇七三），原題共二首，此處選錄第二首，湖指杭州西湖。作者用概括的語言讚美西湖的景色，首先就湖上的陰晴變化描寫了西湖的風貌，接着用絕妙的比喻來表達西湖的神韻，留下想像的空間讓讀者尋", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%A3%B2%E6%B9%96%E4%B8%8A%E5%88%9D%E6%99%B4%E5%BE%8C%E9%9B%A8%EF%BC%88%E5%85%B6%E4%BA%8C%EF%BC%89"}, {"title": "蝶戀花（花褪殘紅青杏小）", "author": "蘇軾", "period": "宋", "form": "詞", "theme": "春水花鳥", "mood": "autumn_sunset", "lines": ["花褪殘紅青杏小，燕子飛時，綠水人家繞。枝上柳綿吹又少，天涯何處無芳草。", "牆裏鞦韆牆外道，牆外行人，牆裏佳人笑。笑漸不聞聲漸悄，多情卻被無情惱。"], "quote": ["花褪殘紅青杏小，燕子飛時，綠水人家繞。枝上柳綿吹又少，天涯何處無芳草。", "牆裏鞦韆牆外道，牆外行人，牆裏佳人笑。笑漸不聞聲漸悄，多情卻被無情惱。"], "intro": "據傳東坡貶謫惠州（廣東惠陽）時，曾命朝雲唱這首《蝶戀花》詞。明代張岱《琅嬛記》卷中引《青泥蓮花記》云：「子瞻在惠州，與朝雲閒坐，時青女初至，落木蕭蕭，淒然有悲秋之意。命朝雲把大白，唱『花褪殘紅』。朝雲歌喉將囀，淚滿衣襟。子瞻詰其故，答曰：『", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%9D%B6%E6%88%80%E8%8A%B1%EF%BC%88%E8%8A%B1%E8%A4%AA%E6%AE%98%E7%B4%85%E9%9D%92%E6%9D%8F%E5%B0%8F%EF%BC%89"}, {"title": "臨江仙（夜飲東坡醒復醉）", "author": "蘇軾", "period": "宋", "form": "詞", "theme": "江河湖海", "mood": "vast_river", "lines": ["夜歸臨皋", "夜飲東坡醒復醉，歸來彷彿三更。家童鼻息已雷鳴。敲門都不應，倚仗聽江聲。", "長恨此身非我有，何時忘卻營營。夜闌風靜縠紋平。小舟從此逝，江海寄餘生。"], "quote": ["夜歸臨皋", "夜飲東坡醒復醉，歸來彷彿三更。家童鼻息已雷鳴。敲門都不應，倚仗聽江聲。", "長恨此身非我有，何時忘卻營營。夜闌風靜縠紋平。小舟從此逝，江海寄餘生。"], "intro": "曠達的胸襟源於先天的性情與後天的鍛鍊。年輕時的東坡雖不免任性自負，但他也是一位自省力極強、悟性很高的人，加上其有溫厚的人格、開朗的個性，使得他隨着年歲的增長、生活的歷練、學識的涵養以及個人的修持，逐漸地就形成了圓融的自我觀照，而得以透視生命", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%87%A8%E6%B1%9F%E4%BB%99%EF%BC%88%E5%A4%9C%E9%A3%B2%E6%9D%B1%E5%9D%A1%E9%86%92%E5%BE%A9%E9%86%89%EF%BC%89"}, {"title": "題西林壁", "author": "蘇軾", "period": "宋", "form": "詩", "theme": "山水登臨", "mood": "majestic_peaks", "lines": ["橫看成嶺側成峰，遠近高低總不同，", "不識廬山真面目，只緣身在此山中。"], "quote": ["橫看成嶺側成峰，遠近高低總不同，", "不識廬山真面目，只緣身在此山中。"], "intro": "《題西林壁》選自《蘇軾詩集》卷二十三，是蘇軾在宋神宗元豐七年（一〇八四）初遊廬山時作。西林，廬山寺名，又名乾明寺。本詩不僅描繪了廬山山勢奇特、姿態萬千的風貌，也說出了觀察事物的重要哲理。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%A1%8C%E8%A5%BF%E6%9E%97%E5%A3%81"}, {"title": "贈劉景文", "author": "蘇軾", "period": "宋", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["荷盡已無擎雨蓋，菊殘猶有傲霜枝。", "一年好景君須記，最是橙黃橘綠時。"], "quote": ["荷盡已無擎雨蓋，菊殘猶有傲霜枝。", "一年好景君須記，最是橙黃橘綠時。"], "intro": "元祐初年，舊黨重新執政，蘇軾被召還朝，成為朝廷重臣。但是蘇軾反對舊黨盡廢新法，元祐四年（公元1089）初迫二度外放杭州。當時，他已離開杭州整整十五年了。 這首詩是元祐五年（公元1090）初冬在杭州所作。劉景文，名季孫，開封祥符（今河南省祥符", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B4%88%E5%8A%89%E6%99%AF%E6%96%87"}, {"title": "上樞密韓太尉書", "author": "蘇轍", "period": "宋", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["太尉執事︰", "轍生好為文，思之至深，以為文者氣之所形。然文不可以學而能，氣可以養而致。孟子曰︰「我善養吾浩然之氣。」今觀其文章，寬厚宏博，充乎天地之間，稱其氣之小大。", "太史公行天下，周覽四海名山大川，與燕趙間豪俊交游，故其文疏蕩，頗有奇氣。此二子者，豈嘗執筆學為如此之文哉？其氣充乎其中，而溢乎其貌，動乎其言，而見乎其文，而不自知也。", "轍生十有九年矣。其居家所與遊者，不過其鄰里鄉黨之人；所見不過數百里之間，無高山大野，可登覽以自廣。百氏之書，雖無所不讀，然皆古人之陳迹，不足以激發其志氣。恐遂汩沒，故決然捨去，求天下奇聞壯觀，以知天地之廣大。", "過秦漢之故都，恣觀終南嵩華之高；北顧黃河之奔流，慨然想見古之豪傑。至京師，仰觀天子宮闕之壯，與倉廩府庫、城池苑囿之富且大也，而後知天下之巨麗。見翰林歐陽公，聽其議論之宏辯，觀其容貌之秀偉，與其門人賢士大夫遊，而後知天下之文章聚乎此也。", "太尉以才略冠天下，天下之所恃以無憂，四夷之所憚以不敢發。入則周公召公，出則方叔召虎，而轍也未之見焉。", "且夫人之學也，不志其大，雖多而何為？轍之來也，於山見終南嵩華之高，於水見黃河之大且深，於人見歐陽公，而猶以為未見太尉也︰故願得觀賢人之光耀，聞一言以自壯，然後可以盡天下之大觀而無憾者矣。", "轍年少，未能通習吏事。嚮之來，非有取於斗升之祿。偶然得之，非其所樂。然幸得賜歸待選，使得優游數年之間。將以益治其文，且學為政。太尉苟以為可教而辱教之，又幸矣！"], "quote": ["太尉執事︰", "轍生好為文，思之至深，以為文者氣之所形。然文不可以學而能，氣可以養而致。孟子曰︰「我善養吾浩然之氣。」今觀其文章，寬厚宏博，充乎天地之間，稱其氣之小大。", "太史公行天下，周覽四海名山大川，與燕趙間豪俊交游，故其文疏蕩，頗有奇氣。此二子者，豈嘗執筆學為如此之文哉？其氣充乎其中，而溢乎其貌，動乎其言，而見乎其文，而不自知也。", "轍生十有九年矣。其居家所與遊者，不過其鄰里鄉黨之人；所見不過數百里之間，無高山大野，可登覽以自廣。百氏之書，雖無所不讀，然皆古人之陳迹，不足以激發其志氣。恐遂汩沒，故決然捨去，求天下奇聞壯觀，以知天地之廣大。"], "intro": "這是宋仁宗嘉祐三年（公元一〇五八）蘇轍寫給當時「樞密使」韓琦的信，錄自《欒城文集》。宋朝的樞密使，掌管全國兵權，和宰相平行。「太尉」是秦漢時全國最高的武官名，作者稱韓琦為太尉，表示尊崇。 韓琦，字稚圭，河南安陽人。西夏（今陝西省以西地）來侵", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B8%8A%E6%A8%9E%E5%AF%86%E9%9F%93%E5%A4%AA%E5%B0%89%E6%9B%B8"}, {"title": "黃州快哉亭記", "author": "蘇轍", "period": "宋", "form": "文", "theme": "江河湖海", "mood": "vast_river", "lines": ["江出西陵，始得平地；其流奔放肆大，南合沅、湘，北合漢、沔，其勢益張。至於赤壁之下，波流浸灌，與海相若。清河張君夢得，謫居齊安，即其廬之西南為亭，以覽觀江流之勝；而余兄子瞻，名之曰「快哉」。", "蓋亭之所見，南北百里，東西一舍，濤瀾洶湧，風雲開闔；晝則舟楫出沒於其前，夜則魚龍悲嘯於其下；變化倏忽，動心駭目，不可久視。今乃得玩之几席之上，舉目而足。西望武昌諸山，岡陵起伏，草木行列，煙消日出，漁父樵夫之舍，皆可指數。此其所以為「快哉」者也。", "至於長洲之濱，故城之墟；曹孟德、孫仲謀之所睥睨，周瑜、陸遜之所馳騖；其流風遺跡，亦足以稱快世俗。", "昔楚襄王從宋玉、景差於蘭臺之宮，有風颯然至者，王披襟當之曰︰「快哉此風！寡人所與庶人共者耶？」宋玉曰︰「此獨大王之雄風耳，庶人安得共之！」玉之言，蓋有諷焉。", "夫風無雄雌之異，而人有遇不遇之變。楚王之所以為樂，與庶人之所以為憂，此則人之變也。而風何與焉？", "士生於世，使其中不自得，將何往而非病？使其中坦然不以物傷性，將何適而非快？今張君不以謫為患，收會稽之餘功，而自放山水之間，此其中宜有以過人者。將蓬戶、甕牖，無所不快；而況乎濯長江之清流，挹西山之白雲，窮耳目之勝，以自適也哉？", "不然，連山絕壑，長林古木，振之以清風，照之以明月，此皆騷人思士之所以悲傷、憔悴，而不能勝者；烏睹其為快也哉？"], "quote": ["江出西陵，始得平地；其流奔放肆大，南合沅、湘，北合漢、沔，其勢益張。至於赤壁之下，波流浸灌，與海相若。清河張君夢得，謫居齊安，即其廬之西南為亭，以覽觀江流之勝；而余兄子瞻，名之曰「快哉」。", "蓋亭之所見，南北百里，東西一舍，濤瀾洶湧，風雲開闔；晝則舟楫出沒於其前，夜則魚龍悲嘯於其下；變化倏忽，動心駭目，不可久視。今乃得玩之几席之上，舉目而足。西望武昌諸山，岡陵起伏，草木行列，煙消日出，漁父樵夫之舍，皆可指數。此其所以為「快哉」者也。", "至於長洲之濱，故城之墟；曹孟德、孫仲謀之所睥睨，周瑜、陸遜之所馳騖；其流風遺跡，亦足以稱快世俗。", "昔楚襄王從宋玉、景差於蘭臺之宮，有風颯然至者，王披襟當之曰︰「快哉此風！寡人所與庶人共者耶？」宋玉曰︰「此獨大王之雄風耳，庶人安得共之！」玉之言，蓋有諷焉。"], "intro": "黃州，隋代所置州名，治今湖北黃岡縣。有一位名叫張夢得的人，因故貶官，謫居在那裏，建了一所亭子，以為公餘遊憩之所。作者的哥哥蘇軾命名為「快哉亭」，作者便寫了這一篇「記」。「快哉」的快，是快樂的意思。本文選自《欒城文集》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%BB%83%E5%B7%9E%E5%BF%AB%E5%93%89%E4%BA%AD%E8%A8%98"}, {"title": "邁陂塘（問世間）", "author": "元好問", "period": "元", "form": "詞", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["乙丑歲赴試幷州，道逢捕雁者云，今旦獲一雁，殺之矣。其脫網者悲鳴不能去，竟自投於地而死。予因買得之，葬之汾水之上，累石為識，號曰「雁丘」。時同行者多為賦詩，予亦有雁丘辭，舊所作無宮商，今改定之。", "問世間，情是何物？直教生死相許。天南地北雙飛客，老翅幾回寒暑。歡樂趣，離別苦，就中更有癡兒女。君應有語，渺萬里層雲，千山暮雪，隻影向誰去？", "橫汾路，寂寞當年簫鼓，荒煙依舊平楚。招魂楚些何嗟及，山鬼暗啼風雨。天也妒，未信與，鶯兒燕子俱黃土。千秋萬古，為留待騷人，狂歌痛飲，來訪雁丘處。"], "quote": ["乙丑歲赴試幷州，道逢捕雁者云，今旦獲一雁，殺之矣。其脫網者悲鳴不能去，竟自投於地而死。予因買得之，葬之汾水之上，累石為識，號曰「雁丘」。時同行者多為賦詩，予亦有雁丘辭，舊所作無宮商，今改定之。", "問世間，情是何物？直教生死相許。天南地北雙飛客，老翅幾回寒暑。歡樂趣，離別苦，就中更有癡兒女。君應有語，渺萬里層雲，千山暮雪，隻影向誰去？", "橫汾路，寂寞當年簫鼓，荒煙依舊平楚。招魂楚些何嗟及，山鬼暗啼風雨。天也妒，未信與，鶯兒燕子俱黃土。千秋萬古，為留待騷人，狂歌痛飲，來訪雁丘處。"], "intro": "《邁陂塘》，詞牌名，又名《買陂塘》、《摸魚兒》。唐教坊曲名，本為歌詠捕魚的民歌。 這首詞原寫於元好問年輕時候。序中說他在泰和五年（1205年）到幷州（今山西太原）赴試，在路上遇到一個捕雁的獵人，對他說：那天捕獲一隻雁，把雁殺了。怎料另有一隻", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%82%81%E9%99%82%E5%A1%98%EF%BC%88%E5%95%8F%E4%B8%96%E9%96%93%EF%BC%89"}, {"title": "素梅（其五十六）", "author": "王冕", "period": "元", "form": "詩", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["冰雪林中著此身，不同桃李混芳塵。", "忽然一夜清香發，散作乾坤萬里香。"], "quote": ["冰雪林中著此身，不同桃李混芳塵。", "忽然一夜清香發，散作乾坤萬里香。"], "intro": "王冕在會稽九里山隱居時，種植梅花千樹，自號「梅花屋主」。他生活在梅花中間，常常畫梅、詠梅。他現存的八十三首七絕中，八十二首為詠梅詩，可見他對梅花的偏愛。《素梅》是他寫的一組題畫詩，共五十八首，這裏選了其中一首。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%B4%A0%E6%A2%85%EF%BC%88%E5%85%B6%E4%BA%94%E5%8D%81%E5%85%AD%EF%BC%89"}, {"title": "墨梅（其三）", "author": "王冕", "period": "元", "form": "詩", "theme": "山水登臨", "mood": "majestic_peaks", "lines": ["我家洗硯池頭樹，個個花開淡墨痕。", "不要人誇好顏色，只留清氣滿乾坤。"], "quote": ["我家洗硯池頭樹，個個花開淡墨痕。", "不要人誇好顏色，只留清氣滿乾坤。"], "intro": "王冕在會稽九里山隱居時，種植梅花千樹，自號「梅花屋主」。他生活在梅花中間，常常畫梅、詠梅。在他現存的八十三首七絕中，八十二首為詠梅詩，可見他對梅花的偏愛。本詩題在他為良佐所畫的《梅花圖》上。這幅畫今天還可以看到，背景空無一物，一枝梅花橫斜在", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%A2%A8%E6%A2%85%EF%BC%88%E5%85%B6%E4%B8%89%EF%BC%89"}, {"title": "〔中呂〕十二月過堯民歌・別情", "author": "王實甫", "period": "元", "form": "曲", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["自別後遙山隱隱，更那堪遠水粼粼。見楊柳飛綿滾滾，對桃花醉臉醺醺。透內閣香風陣陣，掩重門暮雨紛紛。", "怕黃昏忽地又黃昏，不銷魂怎地不銷魂。新啼痕壓舊啼痕，斷腸人憶斷腸人。今春，香肌瘦幾分？摟帶寬三寸。"], "quote": ["自別後遙山隱隱，更那堪遠水粼粼。見楊柳飛綿滾滾，對桃花醉臉醺醺。透內閣香風陣陣，掩重門暮雨紛紛。", "怕黃昏忽地又黃昏，不銷魂怎地不銷魂。新啼痕壓舊啼痕，斷腸人憶斷腸人。今春，香肌瘦幾分？摟帶寬三寸。"], "intro": "《十二月過堯民歌・別情》是王實甫唯一存世的散曲小令。這首散曲是帶過曲，帶過曲是指同一個宮調的曲牌帶過另一個曲牌，即用二至三個同一宮調的小令串聯在一起以寫一個共同的內容。帶過曲必須一韻到底，中間不可換韻。本曲即由《十二月》帶過同一「中呂」宮調", "url": "https://www.classicalchineseliterature.org/article.php?article=%E3%80%94%E4%B8%AD%E5%91%82%E3%80%95%E5%8D%81%E4%BA%8C%E6%9C%88%E9%81%8E%E5%A0%AF%E6%B0%91%E6%AD%8C%E3%83%BB%E5%88%A5%E6%83%85"}, {"title": "沉醉東風・漁夫", "author": "白樸", "period": "元", "form": "曲", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["黃蘆岸白蘋渡口，綠楊堤紅蓼灘頭。雖無刎頸交，卻有忘機友。點秋江白鷺沙鷗，傲殺人間萬戶侯。不識字煙波釣叟。"], "quote": ["黃蘆岸白蘋渡口，綠楊堤紅蓼灘頭。雖無刎頸交，卻有忘機友。點秋江白鷺沙鷗，傲殺人間萬戶侯。不識字煙波釣叟。"], "intro": "散曲，盛行於元明兩代，和詞一樣，是一種配合音樂可歌的長短句。有小令（一支曲子單獨成篇）和套數（多支曲子合成一套）兩種。 白樸《沉醉東風》選自《中原音韻》。漁夫，傳統上常作為隱士的代名詞。如《楚辭》中屈原的《漁父》便是一個例子。此曲以漁夫生活", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B2%89%E9%86%89%E6%9D%B1%E9%A2%A8%E3%83%BB%E6%BC%81%E5%A4%AB"}, {"title": "岳飛之少年時代", "author": "佚名", "period": "元", "form": "文", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["岳飛，字鵬舉，相州湯陰人也。生時，有大禽若鵠，飛鳴室上，因以為名。未彌月，河決內黃，水暴至，母姚氏抱飛坐巨甕中，衝濤乘流而下，及岸，得不死。", "飛少負氣節，沉厚寡言。天資敏悟，強記書傳，尤好《左氏春秋》及孫吳兵法。家貧，拾薪為燭，誦習達旦不寐。生有神力，未冠，能挽弓三百斤。學射於周同。同射三矢，皆中的，以示飛；飛引弓一發，破其筈；再發，又中。同大驚，以所愛良弓贈之。飛由是益自練習，盡得同術。", "未幾，同死，飛悲慟不已。每值朔望，必具酒肉，詣同墓，奠而泣；又引同所贈弓，發三矢，乃酹。父知而義之，撫其背曰︰「使汝異日得為時用，其殉國死義乎？」應曰︰「惟大人許兒以身報國家，何事不可為！」"], "quote": ["岳飛，字鵬舉，相州湯陰人也。生時，有大禽若鵠，飛鳴室上，因以為名。未彌月，河決內黃，水暴至，母姚氏抱飛坐巨甕中，衝濤乘流而下，及岸，得不死。", "飛少負氣節，沉厚寡言。天資敏悟，強記書傳，尤好《左氏春秋》及孫吳兵法。家貧，拾薪為燭，誦習達旦不寐。生有神力，未冠，能挽弓三百斤。學射於周同。同射三矢，皆中的，以示飛；飛引弓一發，破其筈；再發，又中。同大驚，以所愛良弓贈之。飛由是益自練習，盡得同術。", "未幾，同死，飛悲慟不已。每值朔望，必具酒肉，詣同墓，奠而泣；又引同所贈弓，發三矢，乃酹。父知而義之，撫其背曰︰「使汝異日得為時用，其殉國死義乎？」應曰︰「惟大人許兒以身報國家，何事不可為！」"], "intro": "岳飛（公元1103——1142）是南宋抗金名將，著名民族英雄。他出身貧寒，但自幼聰敏過人，少年時就抱有遠大的志向和高尚的節操，立志以身報國。宋徽宗宣和四年開始應募從軍，參與抗遼、抗金的戰役。宋欽宗靖康二年，金人破京城，擄去徽、欽二帝，北宋遂", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B2%B3%E9%A3%9B%E4%B9%8B%E5%B0%91%E5%B9%B4%E6%99%82%E4%BB%A3%C2%A0"}, {"title": "天淨沙・秋思（枯藤老樹昏鴉）", "author": "馬致遠", "period": "元", "form": "曲", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["枯藤老樹昏鴉，小橋流水人家，古道西風瘦馬；夕陽西下，斷腸人在天涯。"], "quote": ["枯藤老樹昏鴉，小橋流水人家，古道西風瘦馬；夕陽西下，斷腸人在天涯。"], "intro": "《天淨沙》亦作《天淨紗》，又名《塞上秋》，在北曲中屬於「越調」。《天淨沙・秋思》是元曲家馬致遠創作的小令。 馬致遠年輕時希望考取功名，但由於統治者的高壓政策，讀書人一直沒有出路。他幾乎一生都過着漂泊無定的生活，鬱鬱不得志，窮困潦倒。他在獨自", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%A4%A9%E6%B7%A8%E6%B2%99%E3%83%BB%E7%A7%8B%E6%80%9D%EF%BC%88%E6%9E%AF%E8%97%A4%E8%80%81%E6%A8%B9%E6%98%8F%E9%B4%89%EF%BC%89"}, {"title": "撥不斷（布衣中）", "author": "馬致遠", "period": "元", "form": "曲", "theme": "詠史哲思", "mood": "vast_river", "lines": ["布衣中，問英雄，王圖霸業成何用？禾黍高低六代宮，楸梧遠近千官塚，一場惡夢。"], "quote": ["布衣中，問英雄，王圖霸業成何用？禾黍高低六代宮，楸梧遠近千官塚，一場惡夢。"], "intro": "元代重武輕文，自元太宗九年（公元1237）開科一次後，直到元仁宗延佑元年（公元1314）恢復開科取士。馬致遠恰巧生逢在這沒有科舉的七十八年中，加上朝廷歧視漢人，馬致遠大部分人生沒有機會考取功名，僅在元世祖年間擔任江浙省務提舉小官而已，因此其", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%92%A5%E4%B8%8D%E6%96%B7%EF%BC%88%E5%B8%83%E8%A1%A3%E4%B8%AD%EF%BC%89%C2%A0"}, {"title": "灞橋餞別（《漢宮秋》第三折）", "author": "馬致遠", "period": "元", "form": "曲", "theme": "送別行旅", "mood": "snow_winter", "lines": ["【步步嬌】您將那一曲陽關休輕放，俺咫尺如天樣，慢慢的捧玉觴。朕本意待尊前捱些時光，且休問劣了宮商，您則與我半句兒俄延着唱。", "【殿前歡】則甚麼留下舞衣裳，被西風吹散舊時香。我委實怕宮車再過青苔巷，猛到椒房，那一會想菱花鏡裏妝，風流相，兜的又橫心上。看今日昭君出塞，幾時似蘇武還鄉？", "【七弟兄】說甚麼大王，不當，戀王嬙，兀良，怎禁他臨去也回頭望！那堪這散風雪旌節影悠揚，動關山鼓角聲悲壯。"], "quote": ["【步步嬌】您將那一曲陽關休輕放，俺咫尺如天樣，慢慢的捧玉觴。朕本意待尊前捱些時光，且休問劣了宮商，您則與我半句兒俄延着唱。", "【殿前歡】則甚麼留下舞衣裳，被西風吹散舊時香。我委實怕宮車再過青苔巷，猛到椒房，那一會想菱花鏡裏妝，風流相，兜的又橫心上。看今日昭君出塞，幾時似蘇武還鄉？", "【七弟兄】說甚麼大王，不當，戀王嬙，兀良，怎禁他臨去也回頭望！那堪這散風雪旌節影悠揚，動關山鼓角聲悲壯。"], "intro": "灞橋位於西安東十多公里處的灞河上，是古代東出長安必經之地。古人送別每於此地，故用「灞橋餞別」四字概括此段戲劇。 《灞橋餞別》三支曲【步步嬌】、【殿前歡】、【七弟兄】，選自馬致遠著名歷史劇《漢宮秋》（全名《破幽夢孤雁漢宮秋》）第三折。《漢宮秋", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%81%9E%E6%A9%8B%E9%A4%9E%E5%88%A5%EF%BC%88%E3%80%8A%E6%BC%A2%E5%AE%AE%E7%A7%8B%E3%80%8B%E7%AC%AC%E4%B8%89%E6%8A%98%EF%BC%89%C2%A0"}, {"title": "天淨沙（青苔古木蕭蕭）", "author": "張可久", "period": "元", "form": "曲", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["魯卿庵中", "青苔古木蕭蕭，蒼雲秋水迢迢，紅葉山齋小小。有誰曾到，探梅人過溪橋。"], "quote": ["魯卿庵中", "青苔古木蕭蕭，蒼雲秋水迢迢，紅葉山齋小小。有誰曾到，探梅人過溪橋。"], "intro": "本調名為《天淨沙》，一名《塞上秋》，共五句五韻，句法為六六六、四六。本曲原題下註：「魯卿庵中」，乃寫景之作。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%A4%A9%E6%B7%A8%E6%B2%99%EF%BC%88%E9%9D%92%E8%8B%94%E5%8F%A4%E6%9C%A8%E8%95%AD%E8%95%AD%EF%BC%89"}, {"title": "〔南呂〕一枝花・湖上歸", "author": "張可久", "period": "元", "form": "曲", "theme": "江河湖海", "mood": "snow_winter", "lines": ["長天落綵霞，遠水涵秋鏡。花如人面紅，山似佛頭青。生色圍屏，翠冷松雲徑，嫣然眉黛橫。但攜將旖旎濃香，何必賦橫斜瘦影。", "《梁州》挽玉手留連錦英，據胡牀指點銀瓶。素娥不嫁傷孤另。想當年小小，問何處卿卿？東坡才調，西子娉婷，總相宜千古留名。吾二人此地私行。六一泉亭上詩成，三五夜花前月明，十四絃指下風生。可憎，有情。捧紅牙合和《伊州令》。萬籟寂，四山靜。幽咽泉流水下聲，鶴怨猿驚。", "《尾聲》巖阿禪窟鳴金磬，波底龍宮漾水精。夜氣清，酒力醒。寶篆銷，玉漏鳴。笑歸來彷彿二更，煞強似踏雪尋梅灞橋冷。"], "quote": ["長天落綵霞，遠水涵秋鏡。花如人面紅，山似佛頭青。生色圍屏，翠冷松雲徑，嫣然眉黛橫。但攜將旖旎濃香，何必賦橫斜瘦影。", "《梁州》挽玉手留連錦英，據胡牀指點銀瓶。素娥不嫁傷孤另。想當年小小，問何處卿卿？東坡才調，西子娉婷，總相宜千古留名。吾二人此地私行。六一泉亭上詩成，三五夜花前月明，十四絃指下風生。可憎，有情。捧紅牙合和《伊州令》。萬籟寂，四山靜。幽咽泉流水下聲，鶴怨猿驚。", "《尾聲》巖阿禪窟鳴金磬，波底龍宮漾水精。夜氣清，酒力醒。寶篆銷，玉漏鳴。笑歸來彷彿二更，煞強似踏雪尋梅灞橋冷。"], "intro": "元曲體制由「音樂」與「詞章」合成。「南呂」是中國古代音樂宮調之一。《一枝花》是曲牌。《湖上歸》是題目，或題作《湖上晚歸》、《攜美人湖上歸》。本篇是套曲，由三支宮調相同的曲子組成，首支曲是《一枝花》；所用宮調是「南呂」，是中國古代音樂宮調調式", "url": "https://www.classicalchineseliterature.org/article.php?article=%E3%80%94%E5%8D%97%E5%91%82%E3%80%95%E4%B8%80%E6%9E%9D%E8%8A%B1%E3%83%BB%E6%B9%96%E4%B8%8A%E6%AD%B8"}, {"title": "賣花聲・懷古（美人自刎烏江岸）", "author": "張可久", "period": "元", "form": "曲", "theme": "詠史哲思", "mood": "vast_river", "lines": ["美人自刎烏江岸。戰火曾燒赤壁山。將軍空老玉門關。傷心秦漢，生民塗炭，讀書人一聲長嘆。"], "quote": ["美人自刎烏江岸。戰火曾燒赤壁山。將軍空老玉門關。傷心秦漢，生民塗炭，讀書人一聲長嘆。"], "intro": "元代異族入主中原，計九十年間，皇帝九換，政治不甚穩定，又加上連年征伐，人民生活亦甚苦困。另外，元代實施種族歧視政策，壓抑漢人，重武輕文，對漢人士子心靈影響深遠。一般讀書人在現實社會上多不得志，經常以文學為精神寄託。《賣花聲・懷古》是一首懷古", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B3%A3%E8%8A%B1%E8%81%B2%E3%83%BB%E6%87%B7%E5%8F%A4%EF%BC%88%E7%BE%8E%E4%BA%BA%E8%87%AA%E5%88%8E%E7%83%8F%E6%B1%9F%E5%B2%B8%EF%BC%89%C2%A0"}, {"title": "山坡羊・潼關懷古", "author": "張養浩", "period": "元", "form": "曲", "theme": "山水登臨", "mood": "vast_river", "lines": ["峯巒如聚，波濤如怒，山河表裏潼關路。望西都，意踟躕，傷心秦漢經行處。宮闕萬間都做了土。興，百姓苦；亡，百姓苦！"], "quote": ["峯巒如聚，波濤如怒，山河表裏潼關路。望西都，意踟躕，傷心秦漢經行處。宮闕萬間都做了土。興，百姓苦；亡，百姓苦！"], "intro": "張養浩《山坡羊》（峰巒如聚）選自《朝野新聲太平樂府》卷四。《山坡羊》是曲牌名，大約寫於張養浩在陝西救災時。潼關，在今陝西潼關縣北，地勢險要，為兵家必爭之地。這首曲寫作者登臨潼關所見，表達了對治亂興衰的感慨。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B1%B1%E5%9D%A1%E7%BE%8A%E3%83%BB%E6%BD%BC%E9%97%9C%E6%87%B7%E5%8F%A4"}, {"title": "水仙子（冬前冬後幾村莊）", "author": "喬吉", "period": "元", "form": "曲", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["尋梅", "冬前冬後幾村莊，溪北溪南兩屨霜，樹頭樹底孤山上。冷風來何處香，忽相逢、縞袂綃裳。酒醒寒驚夢，笛淒春斷腸，淡日昏黃。"], "quote": ["尋梅", "冬前冬後幾村莊，溪北溪南兩屨霜，樹頭樹底孤山上。冷風來何處香，忽相逢、縞袂綃裳。酒醒寒驚夢，笛淒春斷腸，淡日昏黃。"], "intro": "本曲是北曲中散曲的小令。本曲調名為《水仙子》，為北曲「雙調」三十五調中之一調，此調亦入「中呂宮」與「南呂宮」（按曲調分宮及調二種：宮有「仙呂」「中呂」「南呂」「正宮」等調，調有「商調」「越調」「雙調」等調），一名《湘妃怨》，一名《凌波仙》，", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B0%B4%E4%BB%99%E5%AD%90%EF%BC%88%E5%86%AC%E5%89%8D%E5%86%AC%E5%BE%8C%E5%B9%BE%E6%9D%91%E8%8E%8A%EF%BC%89"}, {"title": "岳鄂王墓", "author": "趙孟頫", "period": "元", "form": "詩", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["鄂王墳上草離離，秋日荒涼百獸危。", "南渡君臣輕社稷，中原父老望旌旗。", "英雄已死嗟何及，天下中分遂不支。", "莫向西湖歌此曲，水光山色不勝悲。"], "quote": ["鄂王墳上草離離，秋日荒涼百獸危。", "南渡君臣輕社稷，中原父老望旌旗。", "英雄已死嗟何及，天下中分遂不支。", "莫向西湖歌此曲，水光山色不勝悲。"], "intro": "這首七律是作者瞻仰岳飛墓時所作。通過憑弔岳飛墓，沉痛地追敍了南宋朝中執政者殺害抗戰的民族英雄，屈辱苟安，而終於亡國的歷史悲劇，對岳飛之死表示了痛切的哀悼之情，對南宋君臣的苟且偷安表現了強烈的憤恨。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B2%B3%E9%84%82%E7%8E%8B%E5%A2%93"}, {"title": "蟾宮曲・夢中作", "author": "鄭光祖", "period": "元", "form": "曲", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["半窗幽夢微茫，歌罷錢塘，賦罷高唐，風入羅幃，爽入疎櫺，月照紗窗。縹緲見梨花淡粧，依稀聞蘭麝餘香，喚起思量；待不思量，怎不思量？"], "quote": ["半窗幽夢微茫，歌罷錢塘，賦罷高唐，風入羅幃，爽入疎櫺，月照紗窗。縹緲見梨花淡粧，依稀聞蘭麝餘香，喚起思量；待不思量，怎不思量？"], "intro": "《蟾宮曲》這一曲牌，亦名《折桂令》，隸屬「雙調」。本曲用「陽」韻。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%9F%BE%E5%AE%AE%E6%9B%B2%E3%83%BB%E5%A4%A2%E4%B8%AD%E4%BD%9C"}, {"title": "一半兒・題情（雲鬟霧鬢勝堆鴉）", "author": "關漢卿", "period": "元", "form": "曲", "theme": "田園幽居", "mood": "spring_breeze", "lines": ["雲鬟霧鬢勝堆鴉，淺露金蓮簌絳紗，不比等閒牆外花。罵你個俏冤家，一半兒難當一半兒耍。"], "quote": ["雲鬟霧鬢勝堆鴉，淺露金蓮簌絳紗，不比等閒牆外花。罵你個俏冤家，一半兒難當一半兒耍。"], "intro": "關漢卿是元曲大家，雖以創作雜劇取得巨大成就。然而其散曲創作，亦甚受後人喜愛。《一半兒‧題情》凡四首：「雲鬟霧鬢勝堆鴉，淺露金蓮簌絳紗。不比等閒牆外花。罵你個俏冤家，一半兒難當一半兒耍。」（其一）「碧紗窗外靜無人，跪在床前忙要親。罵了個負心回", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B8%80%E5%8D%8A%E5%85%92%E3%83%BB%E9%A1%8C%E6%83%85%EF%BC%88%E9%9B%B2%E9%AC%9F%E9%9C%A7%E9%AC%A2%E5%8B%9D%E5%A0%86%E9%B4%89%EF%BC%89%C2%A0"}, {"title": "四塊玉・閑適（其四）", "author": "關漢卿", "period": "元", "form": "曲", "theme": "山水登臨", "mood": "majestic_peaks", "lines": ["南畝耕，東山臥，世態人情經歷多。閑將往事思量過，賢的是他，愚的是我。爭甚麼？"], "quote": ["南畝耕，東山臥，世態人情經歷多。閑將往事思量過，賢的是他，愚的是我。爭甚麼？"], "intro": "散曲，盛行於元明兩代，和詞一樣，是一種配合音樂可歌的長短句。有小令（一支曲子單獨成篇）和套數（多支曲子合成一套）兩種。 關漢卿《四塊玉》選自《樂府群珠》卷二，以「閑適」為標題的共四首，皆從不同角度反映作者不滿現實的內心世界，整組曲的風格活潑", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%9B%9B%E5%A1%8A%E7%8E%89%E3%83%BB%E9%96%91%E9%81%A9%EF%BC%88%E5%85%B6%E5%9B%9B%EF%BC%89"}, {"title": "竇娥冤・第三折", "author": "關漢卿", "period": "元", "form": "曲", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["（外扮監斬官上，云）下官監斬官是也。今日處決犯人，着做公的把住巷口，休放往來人閒走。（淨扮公人鼓三通、鑼三下科。劊子磨旗、提刀，押正旦帶枷上。劊子云）行動些，行動些，監斬官去法場上多時了！（正旦唱）", "〔正宮〕〔端正好〕沒來由犯王法，不提防遭刑憲，叫聲屈動地驚天！頃刻間遊魂先赴森羅殿，怎不將天地也生埋怨？", "〔滾繡球〕有日月朝暮懸，有鬼神掌着生死權，天地也，只合把清濁分辨，可怎生錯看了盜跖顏淵？為善的受貧窮更命短，造惡的享富貴又壽延。天地也，做得個怕硬欺軟，却原來也這般順水推船。地也，你不分好歹何為地？天也，你錯勘賢愚枉做天！哎，只落得兩淚漣漣。", "（劊子云）快行動些，誤了時辰也。（正旦唱）", "〔倘秀才〕則被這枷扭的我左側右偏，人擁的我前合後偃。我竇娥向哥哥行有句言；（劊子云）你有甚麼話說？（正旦唱）前街裏去心懷恨，後街裏去死無冤，休推辭路遠。", "（劊子云）你如今到法場上面，有甚麼親眷要見的？可教他過來，見你一面也好。（正旦唱）", "〔叨叨令〕可憐我孤身隻影無親眷，則落的吞聲忍氣空嗟怨。（劊子云）難道你爺娘家也沒的？（正旦云）止有個爹爹，十三年前上朝取應去了，至今杳無音信。（唱）早已是十年多不睹爹爹面。（劊子云）你適纔要我往後街裏去，是甚麼主意？（正旦唱）怕則怕前街裏被我婆婆見。（劊子云）你的性命也顧不得，怕他見怎的？（正旦云）俺婆婆若見我披枷帶鎖，赴法場餐刀去呵，（唱）枉將他氣殺也麼哥，枉將他氣殺也麼哥！告哥哥，臨危好與人行方便。", "（卜兒哭上科，云）天那，兀的不是我媳婦兒！（劊子云）婆子靠後！（正旦云）既是俺婆婆來了，叫他來，待我囑付他幾句話咱。（劊子云）那婆子近前來，你媳婦要囑付你話哩。（卜兒云）孩兒，痛殺我也！（正旦云）婆婆，那張驢兒把毒藥放在羊肚兒湯裏，實指望藥死了你，要霸佔我為妻。不想婆婆讓與他老子吃，倒把他老子藥死了。我怕連累婆婆，屈招了藥死公公，今日赴法場典刑。婆婆，此後遇着冬時年節，月一十五，有瀽不了的漿水飯，瀽半碗兒與我吃；燒不了的紙錢，與竇娥燒一陌兒，則是看你死的孩兒面上！（唱）", "〔快活三〕念竇娥葫蘆提當罪愆，念竇娥身首不完全，念竇娥從前已往幹家緣。婆婆也，你只看竇娥少爺無娘面。", "〔鮑老兒〕念竇娥伏侍婆婆這幾年，遇時節將碗涼漿奠；你去那受刑法尸骸上烈些紙錢，只當把你亡化的孩兒薦。（卜兒哭科，云）孩兒放心，這個老身都記得。天那，兀的不痛殺我也！（正旦唱）婆婆也，再也不要啼啼哭哭，煩煩惱惱，怨氣衝天。這都是我做竇娥的沒時沒運，不明不暗，負屈銜冤。", "（劊子做喝科，云）兀那婆子靠後，時辰到了也。（正旦跪科）（劊子開枷科）（正旦云）竇娥告監斬大人，有一事肯依竇娥，便死而無怨。（監斬官云）你有甚麼事？你說。（正旦云）要一領淨席，等我竇娥站立；又要丈二白練，挂在旗槍上。若是我竇娥委實冤枉，刀過處頭落，一腔熱血，休半點兒沾在地下，都飛在白練上者。（監斬官云）這個就依你，打甚麼不緊。（劊子做取席站科，又取白練挂旗上科）（正旦唱）", "〔耍孩兒〕不是我竇娥罰下這等無頭願，委實的冤情不淺。若沒些兒靈聖與世人傳，也不見得湛湛青天。我不要半星熱血紅塵灑，都只在八尺旗槍素練懸，等他四下裏皆瞧見。這就是咱萇弘化碧，望帝啼鵑。"], "quote": ["（外扮監斬官上，云）下官監斬官是也。今日處決犯人，着做公的把住巷口，休放往來人閒走。（淨扮公人鼓三通、鑼三下科。劊子磨旗、提刀，押正旦帶枷上。劊子云）行動些，行動些，監斬官去法場上多時了！（正旦唱）", "〔正宮〕〔端正好〕沒來由犯王法，不提防遭刑憲，叫聲屈動地驚天！頃刻間遊魂先赴森羅殿，怎不將天地也生埋怨？", "〔滾繡球〕有日月朝暮懸，有鬼神掌着生死權，天地也，只合把清濁分辨，可怎生錯看了盜跖顏淵？為善的受貧窮更命短，造惡的享富貴又壽延。天地也，做得個怕硬欺軟，却原來也這般順水推船。地也，你不分好歹何為地？天也，你錯勘賢愚枉做天！哎，只落得兩淚漣漣。", "（劊子云）快行動些，誤了時辰也。（正旦唱）"], "intro": "本課選自元雜劇《竇娥冤》第三折，是全劇高潮的所在，版本據人民文學出版社的《全元戲曲》。 雜劇是一種綜合性的表演藝術，由套曲、賓白（賓是對話，白是獨白）、角色和做作等組成。元代雜劇一般分四折，一折即一幕，另加楔子，是介紹劇情的引子。 《竇娥冤", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%AB%87%E5%A8%A5%E5%86%A4%E3%83%BB%E7%AC%AC%E4%B8%89%E6%8A%98"}, {"title": "石灰吟", "author": "于謙", "period": "明", "form": "詩", "theme": "山水登臨", "mood": "majestic_peaks", "lines": ["千錘萬鑿出深山，烈火焚燒若等閒；", "粉身碎骨全不怕，要留清白在人間。"], "quote": ["千錘萬鑿出深山，烈火焚燒若等閒；", "粉身碎骨全不怕，要留清白在人間。"], "intro": "《石灰吟》即「石灰詩」。吟，一種詩體的名稱。這首詩作於明永樂十二年（一四一四），當時于謙年僅十七歲。這是詩人藉物詠懷之作。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%9F%B3%E7%81%B0%E5%90%9F"}, {"title": "教條示龍場諸生", "author": "王守仁", "period": "明", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["諸生相從於此甚盛，恐無能為助也。以四事相規，聊以答諸生之意。一曰立志；二曰勤學；三曰改過；四曰責善。", "立志", "志不立，天下無可成之事，雖百工技藝，未有不本於志者。今學者曠廢隳惰，忨歲愒時，而百無所成，皆繇於志之未立耳！故立志而聖則聖矣，立志而賢則賢矣。志不立，如無舵之舟、無銜之馬；漂蕩奔逸，終亦何所底乎？", "昔人有言︰使為善，而父母怒之，兄弟怨之，宗族鄉黨賤惡之；如此，而不為善可也。為善，則父母愛之，兄弟悅之；宗族鄉黨敬信之，何苦而不為善、不為君子？使為惡，而父母愛之，兄弟悅之，宗族鄉黨敬信之；如此，而為惡可也。", "為惡，則父母怒之，兄弟怨之，宗族鄉黨賤惡之，何苦而必為惡、為小人？諸生念此，亦可以知所立志矣！", "勤學", "已立志為君子，自當從事於學。凡學之不勤，必其志之尚未篤也。從吾游者，不以聰慧警切為高，而以勤謹謙抑為上。諸生試觀儕輩之中，苟有虛而為盈，無而為有，諱己之不能，忌人之有善，自矜自是，大言欺人者；使其人資稟雖甚超邁，儕輩之中，有弗疾惡之者乎？", "有弗鄙賤之者乎？彼固將以欺人，人固遂為所欺，有弗竊笑之者乎？苟有謙默自持，無能自處，篤志力行，勤學好問，稱人之善，而咎己之失；從人之長，而明己之短；忠信樂易，表裏一致者；使其人資稟雖甚魯鈍，儕輩之中，有弗稱慕之者乎？", "彼固以無能自處，而不求上人，人果遂以彼為無能，有弗敬尚之者乎？諸生觀此，亦可以知所從事於學矣！", "改過", "夫過者，自大賢所不免；然不害其卒為大賢者，為其能改也。故不貴於無過，而貴於能改過。諸生自思，平日亦有缺於廉恥忠信之行者乎？亦有薄於孝友之道，陷於狡詐偷刻之習者乎？諸生殆不至於此。", "不幸或有之，皆其不知而誤蹈，素無師友之講習規飭也。諸生試內省，萬一有近於是者，固亦不可以不痛自悔咎；然亦不當以此自歉，遂餒於改過從善之心。但能一旦脫然洗滌舊染，雖昔為盜寇，今日不害為君子矣。"], "quote": ["諸生相從於此甚盛，恐無能為助也。以四事相規，聊以答諸生之意。一曰立志；二曰勤學；三曰改過；四曰責善。", "立志", "志不立，天下無可成之事，雖百工技藝，未有不本於志者。今學者曠廢隳惰，忨歲愒時，而百無所成，皆繇於志之未立耳！故立志而聖則聖矣，立志而賢則賢矣。志不立，如無舵之舟、無銜之馬；漂蕩奔逸，終亦何所底乎？", "昔人有言︰使為善，而父母怒之，兄弟怨之，宗族鄉黨賤惡之；如此，而不為善可也。為善，則父母愛之，兄弟悅之；宗族鄉黨敬信之，何苦而不為善、不為君子？使為惡，而父母愛之，兄弟悅之，宗族鄉黨敬信之；如此，而為惡可也。"], "intro": "王守仁三十四歲時抗章營救御史戴銑等冤獄，忤太監劉瑾，廷扙四十，謫充貴州龍場驛丞（今屬修文縣，在貴陽西北七十里）。龍場萬山叢薄，苗獠雜居，他因俗化道，當地落後民族全都敬愛他。本篇乃陽明謫居龍場講學時，提示學生進德修業的教條，猶如今日的校規；故", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%95%99%E6%A2%9D%E7%A4%BA%E9%BE%8D%E5%A0%B4%E8%AB%B8%E7%94%9F"}, {"title": "復多爾袞書", "author": "史可法", "period": "明", "form": "文", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["南中向接好音，法隨遣使問訊吳大將軍，未敢遽通左右。非委隆誼於草莽也︰誠以「大夫無私交」，春秋之義。今倥偬之際，忽捧琬琰之章，真不啻從天而降也。循讀再三，殷殷至意；", "若以逆賊尚稽天討，煩貴國憂，法且感且愧。懼左右不察，謂南國臣民，媮安江左，意忘君父之怨，敬為貴國一詳陳之。", "我大行皇帝敬天法祖，勤政愛民，真堯舜之主也。以庸臣誤國，致有三月十九日之事。法待罪南樞，救援無及；師次淮上，凶問遂來。地坼天崩，山枯海泣。嗟乎！人孰無君？雖肆法於巿朝；以為泄泄者之戒，亦奚足謝先皇帝於地下哉！", "爾時南中臣民，哀慟如喪考妣，無不拊膺切齒，欲悉東南之甲，立翦兇讎。而二三老臣，謂國破君亡，宗社為重，相與迎立今上，以繫中外之心。今上非他，神宗之孫，光宗猶子，而大行皇帝之兄也。名正言順，天與人歸。", "五月朔日，駕臨南都，萬姓夾道歡呼，聲聞數里。羣臣勸進，今上悲不自勝，讓再讓三，僅允監國。迨臣民伏闕屢請，始以十五日正位南都。從前鳳集河清，瑞應非一；即告廟之日，紫雲如蓋，祝文升霄，萬目共瞻，欣傳盛事。", "大江湧出枏梓數十萬章，助修宮殿。豈非天意也哉！", "越數日，遂命法視師江北，刻日西征。忽傳我大將軍吳三桂借兵貴國，破走逆賊，為我先皇帝后發喪成禮，掃清宮殿，撫輯羣黎，且罷薙髮之令，示不忘本朝；此等舉動，振古鑠今，凡為大明臣子，無不長跽北向，頂禮加額，豈但如明諭所云「感恩圖報」已乎！", "謹於八月薄治筐篚，遣使犒師，兼欲請命鴻裁，連兵西討；是以王師既發，復次江淮。", "及辱明詔，引春秋大義來相詰責，善哉乎推言之！然此乃為列國君薨，世子應立，有賊未討，不忍死其君者立說耳。若夫天下共主，身殉社稷，青宮皇子，慘變非常，而猶拘牽不即位之文，坐昧大一統之義，中原鼎沸，倉猝出師，將何以維繫人心，號召忠義？", "紫陽綱目，踵事春秋；其間特書，如莽移漢鼎，光武中興；丕廢山陽，昭烈踐祚；懷愍亡國，晉元嗣基；徽欽蒙塵，宋高纘統；是皆於國讎未翦之日，亟正位號，綱目未嘗斥為自立，率以正統與之。", "甚至如玄宗幸蜀，太子即位靈武，議者疵之；亦未嘗不許以行權，幸其光復舊物也。", "本朝傳世十六，正統相承；自治冠帶之族，繼絕存亡，仁恩遐被。貴國昔在先朝，夙膺封號，載在盟府，寧不聞乎？今痛心本朝之難，驅除亂逆，可謂大義復著於春秋矣。昔契丹和宋，止歲輸以金繒；回紇助唐，原不利其土地。"], "quote": ["南中向接好音，法隨遣使問訊吳大將軍，未敢遽通左右。非委隆誼於草莽也︰誠以「大夫無私交」，春秋之義。今倥偬之際，忽捧琬琰之章，真不啻從天而降也。循讀再三，殷殷至意；", "若以逆賊尚稽天討，煩貴國憂，法且感且愧。懼左右不察，謂南國臣民，媮安江左，意忘君父之怨，敬為貴國一詳陳之。", "我大行皇帝敬天法祖，勤政愛民，真堯舜之主也。以庸臣誤國，致有三月十九日之事。法待罪南樞，救援無及；師次淮上，凶問遂來。地坼天崩，山枯海泣。嗟乎！人孰無君？雖肆法於巿朝；以為泄泄者之戒，亦奚足謝先皇帝於地下哉！", "爾時南中臣民，哀慟如喪考妣，無不拊膺切齒，欲悉東南之甲，立翦兇讎。而二三老臣，謂國破君亡，宗社為重，相與迎立今上，以繫中外之心。今上非他，神宗之孫，光宗猶子，而大行皇帝之兄也。名正言順，天與人歸。"], "intro": "崇禎十七年，清兵統帥多爾袞親王藉吳三桂之助入關，趕走李自成，迎接清世祖建都北京，準備發兵消滅南明；當時史可法督師揚州，多爾袞在七八月左右給史可法一件最後通牒式的招降信；本文是史可法在九月左右給他的覆信。 多爾袞是清世祖（順治）的叔父，封和碩", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%BE%A9%E5%A4%9A%E7%88%BE%E8%A2%9E%E6%9B%B8"}, {"title": "朱子家訓（節錄）", "author": "朱柏廬", "period": "明", "form": "文", "theme": "田園幽居", "mood": "ethereal", "lines": ["黎明即起，灑掃庭除，要內外整潔。既昏便息，關鎖門戶，必親自檢點。一粥一飯，當思來處不易；半絲半縷，恒念物力維艱。宜未雨而綢繆，毋臨渴而掘井。自奉必須儉約，宴客切勿留連。器具質而潔，瓦缶勝金玉。飲食約而精，園蔬愈珍饈。"], "quote": ["黎明即起，灑掃庭除，要內外整潔。既昏便息，關鎖門戶，必親自檢點。一粥一飯，當思來處不易；半絲半縷，恒念物力維艱。宜未雨而綢繆，毋臨渴而掘井。自奉必須儉約，宴客切勿留連。器具質而潔，瓦缶勝金玉。飲食約而精，園蔬愈珍饈。"], "intro": "《朱子家訓》亦稱《朱柏廬治家格言》，全文五百餘字，以儒家的「修身」、「齊家」為宗旨，蘊含着做人處世、治家教子的人情道理，三百年來膾炙人口，對後代產生了很大的影響。這裏所節選的，是《朱子家訓》的開頭部分。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9C%B1%E5%AD%90%E5%AE%B6%E8%A8%93%EF%BC%88%E7%AF%80%E9%8C%84%EF%BC%89"}, {"title": "西遊記・孫悟空大鬧天宮", "author": "吳承恩", "period": "明", "form": "小說", "theme": "田園幽居", "mood": "snow_winter", "lines": ["話表齊天大聖到底是個妖猴，更不知官銜品從，也不較俸祿高低，但只註名便了。那齊天府下二司仙吏，早晚伏侍，只知日食三餐，夜眠一榻，無事牽縈，自由自在。閑時節會友遊宮，交朋結義。見三清，稱個「老」字；逢四帝，道個「陛下」。與那九曜星、五方將、二十八宿、四大天王、十二元辰、五方五老、普天星相、河漢群神，俱只以弟兄相待，彼此稱呼。今日東遊，明日西蕩，雲去雲來，行踪不定。", "一日，玉帝早朝，班部中閃出許旌陽真人，頫顖啟奏道︰「今有齊天大聖，無事閑遊，結交天上眾星宿，不論高低，俱稱朋友。恐後閑中生事，不若與他一件事管，庶免別生事端。」玉帝聞言，即時宣詔。那猴王欣欣然而至，道︰「陛下，詔老孫有何陞賞？」玉帝道︰「朕見您身閑無事，與你件執事。你且權管那蟠桃園，早晚好生在意。」大聖歡喜謝恩，朝上唱喏而退。", "他等不得窮忙，即入蟠桃園內查勘。本園中有個土地攔住，問道︰「大聖何往？」大聖道︰「吾奉玉帝點差，代管蟠桃園，今來查勘也。」那土地連忙施禮，即呼那一班鋤樹力士、運水力士、修桃力士、打掃力士都來見大聖磕頭，引他進去。但見那︰", "夭夭灼灼，顆顆株株。夭夭灼灼花盈樹，顆顆株株果壓枝。果壓枝頭垂錦彈，花盈樹上簇胭脂。時開時結千年熟，無夏無冬萬載遲。先熟的，酡顏醉臉；還生的，帶蒂青皮。凝煙肌帶綠，映日顯丹姿。樹下奇葩并異卉，四時不謝色齊齊。左右樓臺館舍，盈空常見罩雲霓。不是玄都凡俗種，瑤池王母自栽培。", "大聖看玩多時，問土地道︰「此樹有多少株數？」土地道︰「有三千六百株︰前面一千二百株，花微果小，三千年一熟，人喫了成仙了道，體健身輕。中間一千二百株，層花甘實，六千年一熟，人喫了霞舉飛昇，長生不老。後面一千二百株，紫紋緗核，九千年一熟，人喫了與天地齊壽，日月同庚。」大聖聞言，歡喜無任。當日查明了株樹，點看了亭閣，回府。自此後，三五日一次賞玩，也不交友，也不他遊。", "一日，見那老樹枝頭，桃熟大半，他心裏要喫個嘗新。奈何本園土地、力士並齊天府仙吏緊隨不便。忽設一計道︰「汝等且出門外伺候，讓我在這亭上少憩片時。」那眾仙果退。只見那猴王脫了冠服，爬上大樹，揀那熟透的大桃，摘了許多，就在樹枝上自在受用。喫了一飽，卻纔跳下樹來，簪冠着服，喚眾等儀從回府。遲三二日，又去設法偷桃，儘他享用。", "一朝，王母娘娘設宴，大開寶閣，瑤池中做「蟠桃勝會」，即着那紅衣仙女、青衣仙女、素衣仙女、皂衣仙女、紫衣仙女、黃衣仙女、綠衣仙女，各頂花籃，去蟠桃園摘桃建會。七衣仙女直至園門首，只見蟠桃園土地、力士同齊天府二司仙吏，都在那裏把門。仙女近前道︰「我等奉王母懿旨，到此摘桃設宴。」土地道︰「仙娥且住。今歲不比往年了，玉帝點差齊天大聖在此督理，須是報大聖得知，方敢開園。」仙女道︰「大聖何在？」土地道︰「大聖在園內，因困倦，自家在亭子上睡哩。」仙女道︰「既如此，尋他去來，不可遲誤。」土地即與同進。尋至花亭不見，只有衣冠在亭，不知何往。四下裏都沒尋處。原來大聖耍了一會，喫了幾個桃子，變做二寸長的個人兒，在那大樹梢頭濃葉之下睡着了。七衣仙女道︰「我等奉旨前來，尋不見大聖，怎敢空回？」旁有仙使道︰「仙娥既奉旨來，不必遲疑。我大聖閑遊慣了，想是出園會友去了。汝等且去摘桃。我們替你回話便是。」那仙女依言，入樹林之下摘桃。先在前樹摘了二籃，又在中樹摘了三籃；到後樹上摘取，只見那樹上花果稀疏，止有幾個毛蒂青皮的。原來熟的都是猴王喫了。七仙女張望東西，只見向南枝上止有一個半紅半白的桃子。青衣女用手扯下枝來，紅衣女摘了，卻將枝子望上一放。原來那大聖變化了，正睡在此枝，被他驚醒。大聖即現本相，耳朵內掣出金箍棒，幌一幌，碗來粗細，咄的一聲道︰「你是那方怪物，敢大膽偷摘我桃！」慌得那七仙女一齊跪下道︰「大聖息怒。我等不是妖怪，乃王母娘娘差來的七衣仙女，摘取仙桃，大開寶閣，做『蟠桃勝會』。適至此間，先見了本園土地等神，尋大聖不見。我等恐遲了王母懿旨，是以等不得大聖，故先在此摘桃，萬望恕罪。」大聖聞言，回嗔作喜道︰「仙娥請起。王母開閣設宴，請的是誰？」仙女道︰「上會自有舊規。請的是西天佛老、菩薩、聖僧、羅漢、南方南極觀音、東方崇恩聖帝、十洲三島仙翁、北方北極玄靈、中央黃極黃角大仙，這個是五方五老。還有五斗星君、上八洞三清，四帝、太乙天仙等眾、中八洞玉皇、九壘、海嶽神仙，下八洞幽冥教主、注世地仙。各宮各殿大小尊神，俱一齊赴蟠桃嘉會。」大聖笑道︰「可請我麼？」仙女道︰「不曾聽得說。」大聖道︰「我乃齊天大聖，就請我老孫做個席尊，有何不可？」仙女道︰「此是上會舊規，今會不知如何。」大聖道︰「此言也是，難怪汝等。你且立下，待老孫先去打聽個消息，看可請老孫不請。」", "好大聖，捻着訣，念聲咒語，對眾仙女道︰「住！住！住！」這原來是個定身法，把那七衣仙女，一個個睖睖睜睜，白着眼，都站在桃樹之下。大聖縱朵祥雲，跳出園內，竟奔瑤池路上而去。正行時，只見那壁廂︰", "一天瑞靄光搖曳，五色祥雲飛不絕。白鶴聲鳴振九皋，紫芝色秀分千葉。中間現出一尊仙，相貌天然丰采別。神舞虹霓幌漢霄，腰懸寶籙無生滅。名稱赤腳大羅仙，特赴蟠桃添壽節。", "那赤腳大仙覿面撞見大聖，大聖低頭定計，賺哄真仙。他要暗去赴會，卻問︰「老道何往？」大仙道︰「蒙王母見招，去赴蟠桃嘉會。」大聖道︰「老道不知。玉帝因老孫觔斗雲疾，着老孫五路邀請列位，先至通明殿下演禮後，方去赴宴。」大仙是個光明正大之人，就以他的誑語作真。道︰「常年就在瑤池演禮謝恩，如何先去通明殿演禮，方去瑤池赴會？」無奈，只得撥轉祥雲，徑往通明殿去了。", "大聖駕着雲，念聲咒語，搖身一變，就變做赤腳大仙模樣，前奔瑤池。不多時，直至寶閣，按住雲頭，輕輕移步，走入裏面。只見那裏︰", "瓊香繚繞，瑞靄繽紛。瑤臺鋪彩結，寶閣散氤氳。鳳翥鸞騰形縹緲，金花玉萼影浮沉。上排着九鳳丹霞扆，八寶紫霓墩。五綵描金桌，千花碧玉盆。桌上有龍肝和鳳髓，熊掌與猩唇。珍饈百味般般美，異果嘉餚色色新。"], "quote": ["話表齊天大聖到底是個妖猴，更不知官銜品從，也不較俸祿高低，但只註名便了。那齊天府下二司仙吏，早晚伏侍，只知日食三餐，夜眠一榻，無事牽縈，自由自在。閑時節會友遊宮，交朋結義。見三清，稱個「老」字；逢四帝，道個「陛下」。與那九曜星、五方將、二十八宿、四大天王、十二元辰、五方五老、普天星相、河漢群神，俱只以弟兄相待，彼此稱呼。今日東遊，明日西蕩，雲去雲來，行踪不定。", "一日，玉帝早朝，班部中閃出許旌陽真人，頫顖啟奏道︰「今有齊天大聖，無事閑遊，結交天上眾星宿，不論高低，俱稱朋友。恐後閑中生事，不若與他一件事管，庶免別生事端。」玉帝聞言，即時宣詔。那猴王欣欣然而至，道︰「陛下，詔老孫有何陞賞？」玉帝道︰「朕見您身閑無事，與你件執事。你且權管那蟠桃園，早晚好生在意。」大聖歡喜謝恩，朝上唱喏而退。", "他等不得窮忙，即入蟠桃園內查勘。本園中有個土地攔住，問道︰「大聖何往？」大聖道︰「吾奉玉帝點差，代管蟠桃園，今來查勘也。」那土地連忙施禮，即呼那一班鋤樹力士、運水力士、修桃力士、打掃力士都來見大聖磕頭，引他進去。但見那︰", "夭夭灼灼，顆顆株株。夭夭灼灼花盈樹，顆顆株株果壓枝。果壓枝頭垂錦彈，花盈樹上簇胭脂。時開時結千年熟，無夏無冬萬載遲。先熟的，酡顏醉臉；還生的，帶蒂青皮。凝煙肌帶綠，映日顯丹姿。樹下奇葩并異卉，四時不謝色齊齊。左右樓臺館舍，盈空常見罩雲霓。不是玄都凡俗種，瑤池王母自栽培。"], "intro": "本課節選自《西遊記》第五回「亂蟠桃大聖偷丹 反天宮諸神捉怪」，版本據中華書局排印本，現有標題為編者所加。《西遊記》是一部優秀的長篇神怪小說，內容主要寫孫悟空保護唐僧去西天取經的故事。孫悟空是《西遊記》的主人公，也是作者濃墨重彩、精心塑造的一", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A5%BF%E9%81%8A%E8%A8%98%E3%83%BB%E5%AD%AB%E6%82%9F%E7%A9%BA%E5%A4%A7%E9%AC%A7%E5%A4%A9%E5%AE%AE"}, {"title": "送東陽馬生序", "author": "宋濂", "period": "明", "form": "文", "theme": "送別行旅", "mood": "snow_winter", "lines": ["余幼時即嗜學。家貧，無從致書以觀，每假借於藏書之家，手自筆錄，計日以還。天大寒，硯冰堅，手指不可屈伸，弗之怠。錄畢，走送之，不敢稍逾約。", "以是人多以書假余，余因得遍觀群書。既加冠，益慕聖賢之道，又患無碩師、名人與游，嘗趨百里外，從鄉之先達執經叩問。先達德隆望尊，門人弟子填其室，未嘗稍降辭色。", "余立侍左右，援疑質理，俯身傾耳以請。或遇其叱咄，色愈恭，禮愈至，不敢出一言以復。俟其欣悅，則又請焉。故余雖愚，卒獲有所聞。", "當余之從師也，負篋曳屣行深山巨谷中，窮冬烈風，大雪深數尺，足膚皸裂而不知。至舍，四支僵勁不能動，媵人持湯沃灌，以衾擁覆，久而乃和。", "寓逆旅，主人日再食，無鮮肥滋味之享。同舍生皆被綺繡，戴朱纓寶飾之帽，腰白玉之環，左佩刀，右佩容臭，煜然若神人。余則縕袍敝衣處其間，略無慕豔意。以中有足樂者，不知口體之奉不若人也。蓋余之勤且艱若此。", "今雖耄老，未有所成，猶幸預君子之列，而承天子之寵光，綴公卿之後，日侍坐備顧問，四海亦謬稱其氏名，況才之過於餘者乎？", "今諸生學於太學，縣官日有廩稍之供，父母歲有裘葛之遺，無凍餒之患矣；坐大廈之下而誦詩書，無奔走之勞矣；有司業、博士為之師，未有問而不告，求而不得者也。", "凡所宜有之書，皆集於此，不必若余之手錄，假諸人而後見也。其業有不精，德有不成者，非天質之卑，則心不若余之專耳，豈他人之過哉！", "東陽馬生君則在太學已二年，流輩甚稱其賢。余朝京師，生以鄉人子謁余，譔長書以為贄，辭甚暢達，與之論辨，言和而色夷。", "自謂少時用心於學甚勞，是可謂善學者矣！其將歸見其親也，余故道為學之難以告之。謂余勉鄉人以學者，余之志也；詆我夸際遇之盛而驕鄉人者，豈知予者哉！"], "quote": ["余幼時即嗜學。家貧，無從致書以觀，每假借於藏書之家，手自筆錄，計日以還。天大寒，硯冰堅，手指不可屈伸，弗之怠。錄畢，走送之，不敢稍逾約。", "以是人多以書假余，余因得遍觀群書。既加冠，益慕聖賢之道，又患無碩師、名人與游，嘗趨百里外，從鄉之先達執經叩問。先達德隆望尊，門人弟子填其室，未嘗稍降辭色。", "余立侍左右，援疑質理，俯身傾耳以請。或遇其叱咄，色愈恭，禮愈至，不敢出一言以復。俟其欣悅，則又請焉。故余雖愚，卒獲有所聞。", "當余之從師也，負篋曳屣行深山巨谷中，窮冬烈風，大雪深數尺，足膚皸裂而不知。至舍，四支僵勁不能動，媵人持湯沃灌，以衾擁覆，久而乃和。"], "intro": "《送東陽馬生序》選自《宋文憲公全集》卷三十二。本篇是宋濂寫給太學生馬生的贈序。所謂贈序，是專門為了送別親友而寫的文章。 馬生，名君則，東陽（今浙江東陽）入，與宋濂同鄉。明太祖洪武十一年（一三七八），濂赴京朝見皇帝，馬生前往拜謁。臨別時，宋濂", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%80%81%E6%9D%B1%E9%99%BD%E9%A6%AC%E7%94%9F%E5%BA%8F"}, {"title": "勉諭兒輩", "author": "周怡", "period": "明", "form": "文", "theme": "邊塞豪放", "mood": "snow_winter", "lines": ["「由儉入奢易，由奢入儉難。」飲食衣服若思得之艱難，不敢輕易費用。酒肉一餐，可辦粗飯幾日；紗絹一匹，可辦粗衣幾件，不饞不寒足矣，何必圖好吃好着？常將有日思無日，莫等無時思有時，則子子孫孫常享溫飽矣。"], "quote": ["「由儉入奢易，由奢入儉難。」飲食衣服若思得之艱難，不敢輕易費用。酒肉一餐，可辦粗飯幾日；紗絹一匹，可辦粗衣幾件，不饞不寒足矣，何必圖好吃好着？常將有日思無日，莫等無時思有時，則子子孫孫常享溫飽矣。"], "intro": "勉諭兒輩是指勸勉教諭子侄一輩的人。中國人非常注重家庭教育，在長期的生活實踐中，古人積累了大量的治家經驗，希望子孫們世代遵守，以保長久的幸福安寧。周怡在這裏所談的是「奢」與「儉」的關係問題。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%8B%89%E8%AB%AD%E5%85%92%E8%BC%A9"}, {"title": "水滸傳・魯提轄拳打鎮關西", "author": "施耐庵", "period": "明", "form": "小說", "theme": "邊塞豪放", "mood": "snow_winter", "lines": ["風拂烟籠錦旆揚，太平時節日初長。能添壯士英雄膽，善解佳人愁悶腸。三尺曉垂楊柳外，一竿斜插杏花傍。男兒未遂平生志，且樂高歌入醉鄉。", "三人上到潘家酒樓上，揀個濟楚閣兒裏坐下。魯提轄坐了主位，李忠對席，史進下首坐了。酒保唱了喏，認得是魯提轄，便道︰「提轄官人，打多少酒？」魯提（轄）道︰「先打四角酒來。」一面鋪下菜蔬果品案酒。又問道︰「官人吃甚下飯？」魯達道︰「問甚麼！但有，只顧賣來，一發算錢還你。這廝只顧來聒噪。」酒保下去，隨即盪酒上來，但是下口肉食，只顧將來，擺一桌子。三個酒至數杯，正說些閑話，較量些鎗法。說得入港，只聽得隔壁閣子裏，有人哽哽咽咽啼哭。魯達焦躁，便把碟兒盞兒都丟在樓板上。酒保聽得，慌忙上來看時，見魯提轄氣憤憤地，酒保抄手道︰「官人要甚東西，分付賣來。」魯達道︰「洒家要甚麼，你也須認的洒家。卻恁地教甚麼人在間壁吱吱的哭，攪俺弟兄們吃酒。洒家須不曾少了你酒錢！」酒保道︰「官人息怒。小人怎敢教人啼哭，打攪官人吃酒？這箇哭的，是綽酒座兒唱的父子兩人。不知官人們在此吃酒，一時間自苦了啼哭。」魯提轄道︰「可是作怪！你與我喚的他來。」酒保去叫，不多時，只見兩個到來。前面一個十八九歲的婦人，背後一個五六十歲的老兒。手裏拿串拍板，都來到面前。看那婦人，雖無十分的容貌，也有些動人的顏色。但見︰", "鬅鬆雲髻，插一枝青玉簪兒；裊娜纖腰，繫六幅紅羅裙子。素白舊衫籠雪體，淡黃軟襪襯弓鞋。蛾眉緊蹙，汪汪淚眼落珍珠；粉面低垂，細細香肌消玉雪。若非雨病雲愁，定是懷憂積恨。大體還他肌骨好，不搽脂粉也風流。", "那婦人拭着淚眼，向前來，深深的道了三個萬福。那老兒也都相見了。魯達問道︰「你兩個是那裏人家？為甚啼哭？」那婦人便道︰「官人不知，容奴告稟︰奴家是東京人氏，因同父母來這渭州投奔親眷，不想搬移南京去了。母親在客店裏染病身故，子父二人流落在此生受。此間有個財主，叫做鎮關西鄭大官人，因見奴家，便使強媒硬保，要奴作妾。誰想寫了三千貫文書，虛錢實契，要了奴家身體。未及三箇月，他家大娘子好生利害，將奴趕打出來，不容完聚。着落店主人家追要原典身錢三千貫。父親懦弱，和他爭執不的，他又有錢有勢。當初不曾得他一文，如今那討錢來還他？沒計奈何，父親自小教得奴家些小曲兒，來這裏酒樓上趕座子。每日但得些錢來，將大半還他，留些少子父們盤纏。這兩日酒客稀少，違了他錢限，怕他來討時受他羞恥。子父們想起這苦楚來，無處告訴，因此啼哭。不想誤觸犯了官人，望乞恕罪，高抬貴手。」魯提轄又問道︰「你姓甚麼？在那個客店裏歇？那個鎮關西鄭大官人在那裏住？」老兒答道︰「老漢姓金，排行第二，孩兒小字翠蓮；鄭大官人便是此間狀元橋下賣肉的鄭屠，綽號鎮關西；老漢父子兩箇，只在前面東門裏魯家客店安下。」魯達聽了道︰「呸！俺只道那箇鄭大官人，卻原來是殺豬的鄭屠！這個腌臢潑才，投托着俺小种經略相公門下，做個肉舖戶，卻原來這等欺負人。」回頭看着李忠、史進道︰「你兩個且在這裏，等洒家去打死了那廝便來。」史進、李忠抱住勸道︰「哥哥息怒，明日卻理會。」兩個三回五次勸得他住。魯達又道︰「老兒你來，洒家與你些盤纏，明日便回東京去如何？」父子兩個告道︰「若是能勾得回鄉去時，便是重生父母，再長爺娘。只是店主人家如何肯放？鄭大官人須着落他要錢。」魯提轄道︰「這個不妨事！俺自有道理。」便去身邊摸出五兩來銀子，放在桌上，看着史進道︰「洒家今日不曾多帶得些出來，你有銀子，借些與俺，洒家明日便送還你。」史進道︰「直甚麼？要哥哥還。」去包裹裏取出一錠十兩銀子，放在桌上。魯達看着李忠道︰「你也借些出來與洒家。」李忠去身邊摸出二兩來銀子，魯提轄看了見少，便道︰「也是個不爽利的人。」魯達只把這十五兩銀子與了金老，分付道︰「你父子兩個將去做盤纏，一面收拾行李，俺明日清早來，發付你兩個起身，看那個店主人敢留你！」金老並女兒拜謝去了。魯達把這二兩銀子丟還了李忠。三人再吃了兩角酒，下樓來叫道︰「主人家，酒錢洒家明日送來還你。」主人家連聲應道︰「提轄只顧自去，但吃不妨，只怕提轄不來賒。」三個人出了潘家酒肆，到街上分手，史進、李忠各自投客店去了。只說魯提轄回到經略府前下處，到房裏，晚飯也不吃，氣憤憤的睡了。主人家又不敢問他。", "再說金老得了這一十五兩銀子，回到店中，安頓了女兒，先去城外遠處覓下一輛車兒，回來收拾了行李，還了房宿錢，算清了柴米錢，只等來日天明。當夜無事。次早五更起來，子父兩個先打火做飯，吃罷，收拾了，天色微明。只見魯提轄大踏步走入店裏來，高聲叫道︰「店小二，那裏是金老歇處？」小二哥道︰「金公，提轄在此尋你。」金老開了房門，便道︰「提轄官人，裏面請坐。」魯達道︰「坐甚麼！你去便去，等甚麼！」金老引了女兒，挑了擔兒，作謝提轄，便待出門。店小二攔住道︰「金公，那裏去？」魯達問道︰「他少你房錢？」小二道︰「小人房錢，昨夜都算還了。須欠鄭大官人典身錢，着落在小人身上看管他哩！」魯提轄道︰「鄭屠的錢，洒家自還他。你放這老兒還鄉去。」那店小二那裏肯放？魯達大怒，叉開五指，去那小二臉上只一掌，打的那店小二口中吐血；再復一拳，打下當門兩個牙齒。小二爬將起來，一道烟走了。店主人那裏敢出來攔他？金老父子兩個，忙忙離了店中，出城自去尋昨日覓下的車兒去了。且說魯達尋思，恐怕店小二趕去攔截他，且向店裏掇條凳子，坐了兩個時辰。約莫金公去的遠了，方纔起身，逕投狀元橋來。", "且說鄭屠開着兩間門面，兩副肉案，懸掛着三五片豬肉。鄭屠正在門前櫃身內坐定，看那十來個刀手賣肉。魯達走到門前，叫聲︰「鄭屠！」鄭屠看時，見是魯提轄，慌忙出櫃身來，唱喏道︰「提轄恕罪。」便叫副手掇條凳子來︰「提轄請坐。」魯達坐下道︰「奉着經略相公鈞旨，要十斤精肉，切做臊子，不要見半點肥的在上頭。」鄭屠道︰「使頭，你們快選好的，切十斤去。」魯提轄道︰「不要那等腌臢廝們動手，你自與我切。」鄭屠道︰「說得是，小人自切便了。」自去肉案上，揀了十斤精肉，細細切做臊子。那店小二把手帕包了頭，正來鄭屠家報說金老之事，卻見魯提轄坐在肉案門邊，不敢攏來，只得遠遠的立住在房簷下望。這鄭屠整整的自切了半個時辰，用荷葉包了道︰「提轄，教人送去。」魯達道︰「送甚麼！且住！再要十斤，都是肥的，不要見些精的在上面，也要切做臊子。」鄭屠道︰「卻纔精的，怕府裏要裹餛飩，肥的臊子何用？」魯達睜着眼道︰「相公鈞旨，分付洒家，誰敢問他？」鄭屠道︰「是合用的東西，小人切便了。」又選了十斤實膘的肥肉，也細細的切做臊子，把荷葉來包了，整弄了一早晨，卻得飯罷時候。那店小二那裏敢過來？連那正要買肉的主顧，也不敢攏來。鄭屠道︰「着人與提轄拿了，送將府裏去。」魯達道︰「再要十斤寸金軟骨，也要細細地剁做臊子，不要見些肉在上面。」鄭屠笑道︰「卻不是特地來消遣我！」魯達聽罷，跳起身來，拏着那兩包臊子在手裏，睜眼看着鄭屠說道︰「洒家特的要消遣你！」把兩包臊子劈面打將去，卻似下了一陣的肉雨。鄭屠大怒，兩條忿氣從腳底下直衝到頂門心頭。那一把無明業火焰騰騰的按納不住，從肉案上搶了一把剔骨尖刀，托地跳將下來。魯提轄早拔步在當街上。眾鄰舍并十來個火家，那個敢向前來勸？兩邊過路的人，都立住了脚，和那店小二也驚的呆了。", "鄭屠右手拿刀，左手便來要揪魯達。被這魯提轄就勢按住左手，趕將入去，望小腹上只一脚，騰地踢倒了在當街上。魯達再入一步，踏住胸脯，提起那醋鉢兒大小拳頭，看着這鄭屠道︰「洒家始投老种經略相公，做到關西五路廉訪使，也不枉了叫做鎮關西。你是箇賣肉的操刀屠戶，狗一般的人，也叫做鎮關西！你如何強騙了金翠蓮？」撲的只一拳，正打在鼻子上，打得鮮血迸流，鼻子歪在半邊，卻便似開了個油醬舖，鹹的、酸的、辣的，一發都滾出來。鄭屠掙不起來，那把尖刀也丟在一邊。口裏只叫︰「打得好！」魯達罵道︰「直娘賊，還敢應口！」提起拳頭來，就眼眶際眉梢只一拳，打得眼睖縫裂，烏珠迸出，也似開了箇彩帛舖的，紅的、黑的、絳的，都滾將出來。兩邊看的人，懼怕魯提轄，誰敢向前來勸？鄭屠當不過，討饒，魯達喝道︰「咄！你是個破落戶，若是和俺硬到底，洒家倒饒了你，你如何叫俺討饒，洒家卻不饒你。」又只一拳，太陽上正着，卻似做了一箇全堂水陸的道場，磬兒、鈸兒、鐃兒，一齊響。魯達看時，只見鄭屠挺在地下，口裏只有出的氣，沒了入的氣，動彈不得。魯提轄假意道︰「你這廝詐死，洒家再打！」只見面皮漸漸的變了。魯達尋思道︰「俺只指望痛打這廝一頓，不想三拳真箇打死了他。洒家須吃官司，又沒人送飯。不如及早撒開。」拔步便走，回頭指着鄭屠屍道︰「你詐死，洒家和你慢慢理會。」一頭罵，一頭大踏步去了。街坊鄰舍，並鄭屠的火家，誰敢向前來攔他？魯提轄回到下處，急急捲了些衣服、盤纏、細軟、銀兩，但是舊衣粗重，都棄了。提了一條齊眉短棒，奔出南門，一道烟走了。"], "quote": ["風拂烟籠錦旆揚，太平時節日初長。能添壯士英雄膽，善解佳人愁悶腸。三尺曉垂楊柳外，一竿斜插杏花傍。男兒未遂平生志，且樂高歌入醉鄉。", "三人上到潘家酒樓上，揀個濟楚閣兒裏坐下。魯提轄坐了主位，李忠對席，史進下首坐了。酒保唱了喏，認得是魯提轄，便道︰「提轄官人，打多少酒？」魯提（轄）道︰「先打四角酒來。」一面鋪下菜蔬果品案酒。又問道︰「官人吃甚下飯？」魯達道︰「問甚麼！但有，只顧賣來，一發算錢還你。這廝只顧來聒噪。」酒保下去，隨即盪酒上來，但是下口肉食，只顧將來，擺一桌子。三個酒至數杯，正說些閑話，較量些鎗法。說得入港，只聽得隔壁閣子裏，有人哽哽咽咽啼哭。魯達焦躁，便把碟兒盞兒都丟在樓板上。酒保聽得，慌忙上來看時，見魯提轄氣憤憤地，酒保抄手道︰「官人要甚東西，分付賣來。」魯達道︰「洒家要甚麼，你也須認的洒家。卻恁地教甚麼人在間壁吱吱的哭，攪俺弟兄們吃酒。洒家須不曾少了你酒錢！」酒保道︰「官人息怒。小人怎敢教人啼哭，打攪官人吃酒？這箇哭的，是綽酒座兒唱的父子兩人。不知官人們在此吃酒，一時間自苦了啼哭。」魯提轄道︰「可是作怪！你與我喚的他來。」酒保去叫，不多時，只見兩個到來。前面一個十八九歲的婦人，背後一個五六十歲的老兒。手裏拿串拍板，都來到面前。看那婦人，雖無十分的容貌，也有些動人的顏色。但見︰", "鬅鬆雲髻，插一枝青玉簪兒；裊娜纖腰，繫六幅紅羅裙子。素白舊衫籠雪體，淡黃軟襪襯弓鞋。蛾眉緊蹙，汪汪淚眼落珍珠；粉面低垂，細細香肌消玉雪。若非雨病雲愁，定是懷憂積恨。大體還他肌骨好，不搽脂粉也風流。", "那婦人拭着淚眼，向前來，深深的道了三個萬福。那老兒也都相見了。魯達問道︰「你兩個是那裏人家？為甚啼哭？」那婦人便道︰「官人不知，容奴告稟︰奴家是東京人氏，因同父母來這渭州投奔親眷，不想搬移南京去了。母親在客店裏染病身故，子父二人流落在此生受。此間有個財主，叫做鎮關西鄭大官人，因見奴家，便使強媒硬保，要奴作妾。誰想寫了三千貫文書，虛錢實契，要了奴家身體。未及三箇月，他家大娘子好生利害，將奴趕打出來，不容完聚。着落店主人家追要原典身錢三千貫。父親懦弱，和他爭執不的，他又有錢有勢。當初不曾得他一文，如今那討錢來還他？沒計奈何，父親自小教得奴家些小曲兒，來這裏酒樓上趕座子。每日但得些錢來，將大半還他，留些少子父們盤纏。這兩日酒客稀少，違了他錢限，怕他來討時受他羞恥。子父們想起這苦楚來，無處告訴，因此啼哭。不想誤觸犯了官人，望乞恕罪，高抬貴手。」魯提轄又問道︰「你姓甚麼？在那個客店裏歇？那個鎮關西鄭大官人在那裏住？」老兒答道︰「老漢姓金，排行第二，孩兒小字翠蓮；鄭大官人便是此間狀元橋下賣肉的鄭屠，綽號鎮關西；老漢父子兩箇，只在前面東門裏魯家客店安下。」魯達聽了道︰「呸！俺只道那箇鄭大官人，卻原來是殺豬的鄭屠！這個腌臢潑才，投托着俺小种經略相公門下，做個肉舖戶，卻原來這等欺負人。」回頭看着李忠、史進道︰「你兩個且在這裏，等洒家去打死了那廝便來。」史進、李忠抱住勸道︰「哥哥息怒，明日卻理會。」兩個三回五次勸得他住。魯達又道︰「老兒你來，洒家與你些盤纏，明日便回東京去如何？」父子兩個告道︰「若是能勾得回鄉去時，便是重生父母，再長爺娘。只是店主人家如何肯放？鄭大官人須着落他要錢。」魯提轄道︰「這個不妨事！俺自有道理。」便去身邊摸出五兩來銀子，放在桌上，看着史進道︰「洒家今日不曾多帶得些出來，你有銀子，借些與俺，洒家明日便送還你。」史進道︰「直甚麼？要哥哥還。」去包裹裏取出一錠十兩銀子，放在桌上。魯達看着李忠道︰「你也借些出來與洒家。」李忠去身邊摸出二兩來銀子，魯提轄看了見少，便道︰「也是個不爽利的人。」魯達只把這十五兩銀子與了金老，分付道︰「你父子兩個將去做盤纏，一面收拾行李，俺明日清早來，發付你兩個起身，看那個店主人敢留你！」金老並女兒拜謝去了。魯達把這二兩銀子丟還了李忠。三人再吃了兩角酒，下樓來叫道︰「主人家，酒錢洒家明日送來還你。」主人家連聲應道︰「提轄只顧自去，但吃不妨，只怕提轄不來賒。」三個人出了潘家酒肆，到街上分手，史進、李忠各自投客店去了。只說魯提轄回到經略府前下處，到房裏，晚飯也不吃，氣憤憤的睡了。主人家又不敢問他。"], "intro": "《水滸傳》是一部章回小說，即以章回分段敘事的長篇小說。每回常用兩句相對仗的句子標目，以揭示本回的主要內容。其源出宋元話本，後為古典長篇小說的主要形式。 本課節選自《水滸傳》第三回「史大郎夜走華陰縣 魯提轄拳打鎮關西」，版本據容與堂本《水滸傳", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%B0%B4%E6%BB%B8%E5%82%B3%E3%83%BB%E9%AD%AF%E6%8F%90%E8%BD%84%E6%8B%B3%E6%89%93%E9%8E%AE%E9%97%9C%E8%A5%BF"}, {"title": "畫雞", "author": "唐寅", "period": "明", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["頭上紅冠不用裁，", "滿身雪白走將來。", "平生不敢輕言語，", "一叫千門萬戶開。"], "quote": ["頭上紅冠不用裁，", "滿身雪白走將來。", "平生不敢輕言語，", "一叫千門萬戶開。"], "intro": "", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%95%AB%E9%9B%9E"}, {"title": "與茅鹿門書", "author": "唐順之", "period": "明", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["熟觀鹿門之文，及鹿門與人論文之書，門庭路徑，與鄙意殊有契合；雖中間小小異同，異日當自融釋，不待喋喋也。至如鹿門所疑於我，本是欲工文字之人，而不語人以求工文字者，此則有說。", "鹿門所見於我者，歿故吾也；而未嘗見夫槁形灰心之吾乎？吾豈欺鹿門者哉？其不語人以求工文字者，非謂一切抹摋，以文字絕不足為也；蓋謂學者先務，有源委本末之別耳。", "文莫猶人，躬行未得，此一段公案，姑不敢論，只就文章家論之︰雖其繩墨布置，奇正轉折，自有專門法師；至於中一段精神命脈骨髓，則非洗滌心源，獨立物表，具今古隻眼者，不足以與此。", "今有兩人︰其一人心地超然，所謂千古隻眼人也；即使未嘗操紙筆呻吟，學為文章，但直據胸臆，信手寫出，如寫家書，雖或疏鹵，然絕無煙火酸餡習氣，便是宇宙間一樣絕好文字。", "其一人猶然塵中人也；雖其專專學為文章，其於所謂繩墨布置，則盡是矣；然番來覆去，不過是這幾句婆子舌頭語，索其所謂真精神，與千古不可磨滅之見，絕無有也，則文雖工而不免為下格。此文章本色也。", "即如以詩為喻︰陶彭澤未嘗較聲律，雕句文；但信手寫出，便是宇宙間第一等好詩。何則？其本色高也。自有詩以來，其較聲律，雕句文，用心最苦而立說最嚴者，無如沈約；苦卻一生精力，使人讀其詩，祗見其綑縛齷齪，滿卷累牘，竟不能道出一兩句好話。何則？其本色卑也。本色卑，文不能工也；而況非其本色者哉！", "且夫兩漢而下，文之不如古者，豈有所為繩墨轉折之精之不盡如哉！秦、漢以前，儒家者有儒家本色，老、莊家有老、莊本色，縱橫家有縱橫本色，至如名家、墨家、陰陽家，皆有本色；雖其為術也駁，而莫不皆有一段千古不可磨滅之見。是以老家必不肯剿儒家之說，縱橫家必不肯借墨家之談，如自其本色而鳴之為言。其所言者，其本色也。", "是以精光注焉，而其言遂不泯於世。唐、宋而下，文人莫不語性命，談治道，滿紙炫然，一切自託於儒家。然非其涵養蓄聚之素，非真有一段千古不可磨滅之見。而影響剿說，蓋頭竊尾，如貧借富人之衣，莊農作大賈之飾，極力裝做，醜態盡露︰是以精光枵焉，而其言遂不久湮廢。", "然則秦、漢而上，雖其老、墨、名、法、雜家之說而猶傳；今諸子之書，是也。唐、宋而下，雖其一切語性命、談治道之說而亦不傳；歐陽永叔所見唐四庫書目，百不存一焉，是也。後之文人，欲以立言為不朽計者，可以知所用心矣。", "然則吾之不語人以求工文字者，乃其語人以求工文字者也；鹿門其可以信我矣！雖然，吾槁形而灰心焉久矣，而又敢於知文乎？今復縱言至此，吾過矣！吾過矣！此後鹿門更見我之文，其謂我之求工於文者耶？非求工於文者耶？鹿門當自知我矣。一笑。"], "quote": ["熟觀鹿門之文，及鹿門與人論文之書，門庭路徑，與鄙意殊有契合；雖中間小小異同，異日當自融釋，不待喋喋也。至如鹿門所疑於我，本是欲工文字之人，而不語人以求工文字者，此則有說。", "鹿門所見於我者，歿故吾也；而未嘗見夫槁形灰心之吾乎？吾豈欺鹿門者哉？其不語人以求工文字者，非謂一切抹摋，以文字絕不足為也；蓋謂學者先務，有源委本末之別耳。", "文莫猶人，躬行未得，此一段公案，姑不敢論，只就文章家論之︰雖其繩墨布置，奇正轉折，自有專門法師；至於中一段精神命脈骨髓，則非洗滌心源，獨立物表，具今古隻眼者，不足以與此。", "今有兩人︰其一人心地超然，所謂千古隻眼人也；即使未嘗操紙筆呻吟，學為文章，但直據胸臆，信手寫出，如寫家書，雖或疏鹵，然絕無煙火酸餡習氣，便是宇宙間一樣絕好文字。"], "intro": "茅鹿門（公元一五一二——一六○一），名坤，字順甫，鹿門是別號，明歸安（今浙江吳興）人。嘉靖進士，喜談兵，累官廣西兵備僉事，破猺寇立功，遷大名副使，為總督楊博賞識，薦之於朝，不幸遭忌落職。他也喜歡古文，最折服唐順之所作，曾照順之的愛好，編選《", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%88%87%E8%8C%85%E9%B9%BF%E9%96%80%E6%9B%B8"}, {"title": "遊雁宕山日記", "author": "徐宏祖", "period": "明", "form": "文", "theme": "山水登臨", "mood": "snow_winter", "lines": ["自初九日別台山，初十日抵黃巖，日已西；出南門三十里，宿於「八嶴」。", "十一日，二十里，登「盤山嶺」，望雁山諸峯，芙蓉插天，片片撲人眉宇。又二十里，飯「大荊驛」。南涉一溪，見西峯上綴圓石，奴輩指為兩頭陀，余疑即「老僧巖」，但不甚肖。", "五里，過「章家樓」，始見「老僧」真面目︰袈衣禿頂，宛然兀立，高可百尺。側又一小童，傴僂於後，向為「老僧」所掩耳。自「章樓」二里，山半得「石梁洞」，洞門東向；門口一梁自頂斜插於地，如飛虹下垂。", "由梁側隙中層級而上，高敞空豁。坐頃之，下山；由右麓逾「謝公嶺」，渡一澗；循澗西行，即「靈峯」道也。一轉山腋，兩壁峭立亙天，危峯亂疊，如削如攢，如駢笋，如挺芝，如筆之卓，如幞之攲。", "洞有口如捲幙者，潭有碧如澄靛者；「雙鸞」「五老」，接翼聯肩。如此里許，抵「靈峯寺」。循寺側登「靈峯洞」；峯中空，特立寺後。側有隙可入。", "由隙歷磴數十級，直至窩頂，則窅然平臺圓敞，中有羅漢諸像。坐玩至暝色，返寺。", "十二日，飯後，從「靈峯」右趾覓「碧霄洞」。返舊路，抵「謝公嶺」下；南過「響巖」，五里，至「淨名寺」路口。入覓「水簾谷」，乃兩崖相夾，水從崖頂飄下也。山谷五里，至「靈巖寺」。絕壁四合，摩天劈地，曲折而入，如另闢一寰界。", "寺居其中，南向，背為「屏霞嶂」。嶂頂齊而色紫，高數百丈，闊亦稱之。嶂之最南，左為「展旗峯」，右為「天柱峯」。嶂之右脅，介於「天柱」者，先為「龍鼻水」；「龍鼻」之穴，從石罅直上，似「靈峯洞」而小。", "穴內石色俱黃紫，獨罅口石紋一縷，青紺潤澤，頗有鱗爪之狀；自頂貫入洞底，垂下一端如鼻，鼻端孔可容指，水自內滴，下注石盆。此嶂右第一奇也。西南為「獨秀峯」，小於天柱，而高銳不相下。「獨秀」之下為「卓筆峯」，高半「獨秀」，銳亦如之。", "兩峯南坳，轟然下瀉者，「小龍湫」也。隔「龍湫」與「獨秀」相對者，「玉女峯」也。頂有春花，宛然插髻。自此過「雙鸞」，即極於「天柱」。「雙鸞」止兩峯並起，峯際有「僧拜石」，袈裟傴僂，肖矣。由嶂之左脅，介於「展旗」者，先為「安禪谷」，谷即「屏霞」之下巖。", "東南為「石屏風」，形如「屏霞」，高濶各得其半，正插「屏霞」盡處。「屏風」頂有蟾蜍石，與嶂側玉龜相向。「屏風」南去，「展旗」側褶中，有徑直上。磴級盡處，石閾限之；俯閾而窺，下臨無地，上嵌崆峒。", "外有二圓穴，側有一長穴，光自穴中射入，別有一境，是為「天聰洞」︰則嶂左第一奇也。銳峯疊嶂，左右環向，奇巧百出，真天下奇觀！而「小龍湫」下流經「天柱」「展旗」，橋跨其上，山門臨之。"], "quote": ["自初九日別台山，初十日抵黃巖，日已西；出南門三十里，宿於「八嶴」。", "十一日，二十里，登「盤山嶺」，望雁山諸峯，芙蓉插天，片片撲人眉宇。又二十里，飯「大荊驛」。南涉一溪，見西峯上綴圓石，奴輩指為兩頭陀，余疑即「老僧巖」，但不甚肖。", "五里，過「章家樓」，始見「老僧」真面目︰袈衣禿頂，宛然兀立，高可百尺。側又一小童，傴僂於後，向為「老僧」所掩耳。自「章樓」二里，山半得「石梁洞」，洞門東向；門口一梁自頂斜插於地，如飛虹下垂。", "由梁側隙中層級而上，高敞空豁。坐頃之，下山；由右麓逾「謝公嶺」，渡一澗；循澗西行，即「靈峯」道也。一轉山腋，兩壁峭立亙天，危峯亂疊，如削如攢，如駢笋，如挺芝，如筆之卓，如幞之攲。"], "intro": "本文選自《徐霞客遊記》，乃作者於明萬曆四十一年（公元一六一三）四月第一次遊雁宕山所寫的日記。雁宕山，一名雁蕩山，簡稱雁山，在浙江樂清、平陽二縣境，綿亙於東海岸，盤曲數百里，跨越甌江，構成雁蕩山脈；因有南雁蕩山、中雁蕩山、北雁蕩山之分，古稱「", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%81%8A%E9%9B%81%E5%AE%95%E5%B1%B1%E6%97%A5%E8%A8%98"}, {"title": "風鳶圖詩（其一）", "author": "徐渭", "period": "明", "form": "詩", "theme": "春水花鳥", "mood": "autumn_sunset", "lines": ["柳條搓線絮搓棉，搓夠千尋放紙鳶。", "消得春風多少力，帶將兒輩上青天。"], "quote": ["柳條搓線絮搓棉，搓夠千尋放紙鳶。", "消得春風多少力，帶將兒輩上青天。"], "intro": "相傳中國最早的風箏是由二千多年前春秋戰國時代的哲學家墨翟製造的。他在魯山（今山東省濰縣境內）因為看到老鷹在空中盤旋，因而有了製造風箏的念頭，但他製造風箏的過程並不順利。他研究試製了三年，終於用木頭製成了一隻木鳥，但只飛了一天就壞了。後來墨翟", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%A2%A8%E9%B3%B6%E5%9C%96%E8%A9%A9%EF%BC%88%E5%85%B6%E4%B8%80%EF%BC%89"}, {"title": "徐文長傳", "author": "袁宏道", "period": "明", "form": "文", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["徐渭，字文長，為山陰諸生；聲名籍甚。薛公蕙校越時，奇其才，有國士之目。然數奇，屢試輒蹶。中丞胡公宗憲聞之，客諸幕。文長每見則葛巾烏衣，縱談天下事，胡公大喜。", "是時公數督邊兵，威鎮東南，介胄之士，膝語蛇行，不敢舉頭；而文長以部下一諸生傲之。議者方之劉真長、杜少陵云。", "會得白鹿，屬文長作表。表上，永陵喜。公以是益奇之，一切疏計，皆出其手。文長自負才略，好奇計，談兵多中，視一世無可當意者，然竟不偶。", "文長既已不得志於有司，遂乃放浪麯糵，恣情山水，走齊魯燕趙之地，窮覽朔漠。其所見山奔海立，沙起雷行，雨鳴樹偃，幽谷大都，人物魚鳥，一切可驚可愕之狀，一一皆達之於詩。其胸中又有勃然不可磨滅之氣，英雄失路、托足無門之悲。", "故其為詩，如嗔如笑，如水鳴峽，如種出土，如寡婦之夜哭，羈人之寒起。雖其體格時有卑者；然匠心獨出，有王者氣；非彼巾幗而事人者，所敢望也。文有卓識，氣沈而法嚴，不以摸擬損才，不以議論傷格，韓曾之流亞也。", "文長既雅不與時調合，當時所謂騷壇主盟者，文長皆叱而奴之，故其名不出於越，悲夫！", "喜作書，筆意奔放如其詩，蒼勁中姿媚躍出；歐陽公所謂「妖韶女老，自有餘態」者也。閒以其餘旁溢為花鳥，皆超逸有致。", "卒以疑殺其繼室，下獄論死。張太史元抃力解，乃得出。", "晚年憤益深，佯狂益甚。顯者至門，或拒不納；時攜錢至酒肆，呼下隸與飲；或自持斧擊破其頭，血流被面，頭骨皆折，揉之有聲；或以利錐錐其兩耳，深入寸餘，竟不得死。", "周望言︰晚歲詩文益奇，無刻本，集藏於家。余同年有官越者，托以鈔錄，今未至。余所見者《徐文長集》闕編二種而已。然文長竟以不得志於時，抱憤而卒。", "石公曰︰先生數奇不已，遂為狂疾。狂疾不已，遂為囹圄。古今文人牢騷困苦，未有若先生者也！雖然，胡公閒世豪傑，永陵英主。", "幕中禮數異等，是胡公知有先生矣；表上人主悅，是人主知有先生矣；獨身未貴耳。先生詩文崛起，一掃近代蕪穢之習；百世而下，自有定論。胡為不遇哉？"], "quote": ["徐渭，字文長，為山陰諸生；聲名籍甚。薛公蕙校越時，奇其才，有國士之目。然數奇，屢試輒蹶。中丞胡公宗憲聞之，客諸幕。文長每見則葛巾烏衣，縱談天下事，胡公大喜。", "是時公數督邊兵，威鎮東南，介胄之士，膝語蛇行，不敢舉頭；而文長以部下一諸生傲之。議者方之劉真長、杜少陵云。", "會得白鹿，屬文長作表。表上，永陵喜。公以是益奇之，一切疏計，皆出其手。文長自負才略，好奇計，談兵多中，視一世無可當意者，然竟不偶。", "文長既已不得志於有司，遂乃放浪麯糵，恣情山水，走齊魯燕趙之地，窮覽朔漠。其所見山奔海立，沙起雷行，雨鳴樹偃，幽谷大都，人物魚鳥，一切可驚可愕之狀，一一皆達之於詩。其胸中又有勃然不可磨滅之氣，英雄失路、托足無門之悲。"], "intro": "徐文長（公元一五二一——一五九三），名「渭」，是一個比袁宏道年長四十七歲的文壇怪傑，他去世時七十二歲，袁宏道那時二十五歲。作者有感於徐文長的身世，所以為他作了這篇傳記。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%BE%90%E6%96%87%E9%95%B7%E5%82%B3"}, {"title": "滿井遊記", "author": "袁宏道", "period": "明", "form": "文", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["燕地寒，花朝節後，餘寒猶厲，凍風時作，作則飛沙走礫。局促一室之內，欲出不得；每冒風馳行，未百步輒返。", "廿二日天稍和，偕數友出東直。至滿井，高柳夾隄，土膏微潤，一望空闊，若脫籠之鵠。於時冰皮始解，波色乍明，鱗浪層層，清澈見底，晶晶然如鏡之新開而冷光之乍出於匣也。", "山巒為晴雪所洗，娟然如拭，鮮妍明媚，如倩女之靧面而髻鬟之始掠也。柳條將舒未舒，柔梢披風，麥田淺鬣寸許。遊人雖未盛，泉而茗者，罍而歌者，紅裝而蹇者，亦時時有。", "風力雖尚勁，然徒步則汗出浹背。凡曝沙之鳥，呷浪之鱗，悠然自得，毛、羽、鱗，鬣之間，皆有喜氣。始知郊田之外，未始無春，而城居者未之知也。", "夫能不以遊墮事，而瀟然於山石草木之間者，惟此官也。而此地適與余近，余之遊將自此始，惡能無紀？己亥之二月也。"], "quote": ["燕地寒，花朝節後，餘寒猶厲，凍風時作，作則飛沙走礫。局促一室之內，欲出不得；每冒風馳行，未百步輒返。", "廿二日天稍和，偕數友出東直。至滿井，高柳夾隄，土膏微潤，一望空闊，若脫籠之鵠。於時冰皮始解，波色乍明，鱗浪層層，清澈見底，晶晶然如鏡之新開而冷光之乍出於匣也。", "山巒為晴雪所洗，娟然如拭，鮮妍明媚，如倩女之靧面而髻鬟之始掠也。柳條將舒未舒，柔梢披風，麥田淺鬣寸許。遊人雖未盛，泉而茗者，罍而歌者，紅裝而蹇者，亦時時有。", "風力雖尚勁，然徒步則汗出浹背。凡曝沙之鳥，呷浪之鱗，悠然自得，毛、羽、鱗，鬣之間，皆有喜氣。始知郊田之外，未始無春，而城居者未之知也。"], "intro": "袁宏道在本文最後記載，此文作於「己亥之二月」，即萬曆二十七年（公元1599年）。袁宏道本在吳縣任知縣，在任兩年後辭去官職，在蘇杭一帶遊玩。萬曆二十六年（公元1598年），他收到在京城任職的哥哥袁宗道的信，讓他進京，後被授予順天府（治所在北京", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%BB%BF%E4%BA%95%E9%81%8A%E8%A8%98"}, {"title": "鐵杵磨針", "author": "陳仁錫", "period": "明", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["李白讀書未成，棄去。道逢老嫗磨杵，白問故，曰︰「欲作針。」白笑其拙，老婦曰︰「功到自然成耳。」白大為感動，遂還讀卒業。卒成名士。"], "quote": ["李白讀書未成，棄去。道逢老嫗磨杵，白問故，曰︰「欲作針。」白笑其拙，老婦曰︰「功到自然成耳。」白大為感動，遂還讀卒業。卒成名士。"], "intro": "本文選自陳仁錫的其中一本書《史品赤函》。這本書輯錄古今逸史，上起古初，下迄於《晉書》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%90%B5%E6%9D%B5%E7%A3%A8%E9%87%9D"}, {"title": "南宮生傳", "author": "高啟", "period": "明", "form": "文", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["南宮生，吳人，偉軀幹，博涉書傳，少任俠，喜擊劍、走馬；尤善彈，指飛鳥下之。家素厚藏，生用周養賓客，及與少年飲博遨戲，盡喪其貲。", "逮壯，見天下亂，思自樹功業，乃謝酒徒，去學兵，得風后《握奇》陳法。將北走中原，從豪傑計事，會道梗，周流無所合。遂泝大江，遊金陵，入金華、會稽諸山，蒐覽瓌怪，渡浙江，汎具區而歸。", "家居以氣節聞，衣冠慕之，爭往迎候，門止車日數十兩。生亦善交，無貴賤皆傾身與相接。有二軍將，恃武橫甚，數毆辱士類，號虎冠。其一嘗召生飲，或曰︰「彼酗不可近也。」生笑曰︰「使酒人惡能勇，吾將柔之矣。」即命駕往，坐上座，為語古賢將事，其人竦聽，居樽下拜起為壽，至罷會無失儀。", "其一嘗遇生客次，顧生不下己，目慴生而起。他日見生獨騎出，從健兒帶刀策馬踵生後，若將肆暴者；生故緩轡當中道進，不少避，知生非懦儒，遂引去，不敢突冒訶避。明旦，介客詣生謝，請結驩。生能以氣服人，類如此。", "性抗直多辯，好箴切友過；有忤己，則面數之，無留怨。與人論議，蘄必勝，然援事析理，眾終莫能折。時藩府數用師，生私策其雋蹶多中。有言生於府，欲致生幕下，不能得；將中生法，生以智免。", "家雖以貧，然喜事故在，或饋酒肉，立召客與飲啗相樂。四方游士至吳者，生察其賢，必與周旋欵曲，延譽上下。所知有喪疾，不能葬療者，以告生，輒令削牘疏所乏，為請諸公間營具之，終飲其德不言。故人皆多生，謂似樓君卿、原巨先，而賢過之。", "久之，稍厭事，闔門寡將迎。闢一室，庋歷代法書、周彝、漢硯、唐雷氏琴，日遊其間以自娛。素工草隸，逼鍾、王，患求者眾，遂自閟，希復執筆。歆慕靜退，時賦詩見志，怡然處約，若將終身。", "生姓宋，名克，家南宮里，故自號云。", "贊曰︰生之行凡三變，每變而益善。尚俠末矣；欲奮於兵固壯，然非士所先；晚乃刮磨豪習，隱然自將，履藏器之節，非有德能之乎？與夫不自知返，違遠道德者異矣。"], "quote": ["南宮生，吳人，偉軀幹，博涉書傳，少任俠，喜擊劍、走馬；尤善彈，指飛鳥下之。家素厚藏，生用周養賓客，及與少年飲博遨戲，盡喪其貲。", "逮壯，見天下亂，思自樹功業，乃謝酒徒，去學兵，得風后《握奇》陳法。將北走中原，從豪傑計事，會道梗，周流無所合。遂泝大江，遊金陵，入金華、會稽諸山，蒐覽瓌怪，渡浙江，汎具區而歸。", "家居以氣節聞，衣冠慕之，爭往迎候，門止車日數十兩。生亦善交，無貴賤皆傾身與相接。有二軍將，恃武橫甚，數毆辱士類，號虎冠。其一嘗召生飲，或曰︰「彼酗不可近也。」生笑曰︰「使酒人惡能勇，吾將柔之矣。」即命駕往，坐上座，為語古賢將事，其人竦聽，居樽下拜起為壽，至罷會無失儀。", "其一嘗遇生客次，顧生不下己，目慴生而起。他日見生獨騎出，從健兒帶刀策馬踵生後，若將肆暴者；生故緩轡當中道進，不少避，知生非懦儒，遂引去，不敢突冒訶避。明旦，介客詣生謝，請結驩。生能以氣服人，類如此。"], "intro": "南宮生，姓宋名克，字仲溫，蘇州人；因家住「南宮里」，故自號「南宮生」。他和作者是朋友，因給他寫了這篇傳記。選自《大全集》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%8D%97%E5%AE%AE%E7%94%9F%E5%82%B3"}, {"title": "五人墓碑記", "author": "張溥", "period": "明", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["五人者，蓋當蓼洲周公之被逮，急於義而死焉者也。至於今，郡之賢士大夫，請於當道，即除逆閹廢祠之址以葬之。且立石于其墓之門，以旌其所為。嗚呼，亦盛矣哉！", "夫五人之死，去今之墓而葬焉，其為時止十有一月爾。夫十有一月之中，凡富貴之子，慷慨得志之徒，其疾病而死，死而堙沒不足道者，亦已眾矣。況草野之無聞者與？獨五人之皦皦，何也？", "予猶記周公之被逮，在丁卯三月之望。吾社之行為士先者，為之聲義，斂貲財以送其行，哭聲震動天地。緹騎按劍而前，問誰為哀者？眾不能堪，抶而仆之。是時以大中丞撫吳者，為魏之私人，周公之逮所繇使也。", "吳之民方痛心焉，於是乘其厲聲以呵，則譟而相逐。中丞匿於溷藩以免。既而以吳民之亂請於朝，按誅五人，曰顏佩韋、楊念如、馬杰、沈揚、周文元，即今之傫然在墓者也。", "然五人之當刑也，意氣陽陽，呼中丞之名而詈之，談笑以死，斷頭置城上，顏色不少變。有賢士大夫發五十金，買五人之脰而函之，卒與屍合。故今之墓中，全乎為五人也。", "嗟乎！大閹之亂，縉紳而能不易其志者，四海之大，有幾人歟？而五人生於編伍之間，素不聞詩書之訓，激昂大義，蹈死不顧，亦曷故哉？", "且矯詔紛出，鉤黨之捕遍於天下，卒以吾郡之發憤一擊，不敢復有株治。大閹亦逡巡畏義，非常之謀，難於猝發。待聖人之出而投環道路，不可謂非五人之力也！", "繇是觀之，則今之高爵顯位，一旦抵罪，或脫身以逃，不能容於遠近，而又有翦發杜門，佯狂不知所之者，其辱人賤行，視五人之死，輕重固何如哉？是以蓼洲周公，忠義暴於朝廷，贈謚美顯，榮於身後。", "而五人亦得以加其土封，列其姓名於大堤之上，凡四方之士，無有不有過而拜且泣者，斯固百世之遇也！不然，令五人者保其首領，以老於戶牖之下，則盡其天年，人皆得以隸使之，安能屈豪傑之流，扼腕墓道，發其志士之悲哉？", "故余與同社諸君子，哀斯墓之徒有其石也，而為之記，亦以明死生之大，匹夫之有重於社稷也。", "賢士大夫者︰冏卿因之吳公、太史文起文公、孟長姚公也。"], "quote": ["五人者，蓋當蓼洲周公之被逮，急於義而死焉者也。至於今，郡之賢士大夫，請於當道，即除逆閹廢祠之址以葬之。且立石于其墓之門，以旌其所為。嗚呼，亦盛矣哉！", "夫五人之死，去今之墓而葬焉，其為時止十有一月爾。夫十有一月之中，凡富貴之子，慷慨得志之徒，其疾病而死，死而堙沒不足道者，亦已眾矣。況草野之無聞者與？獨五人之皦皦，何也？", "予猶記周公之被逮，在丁卯三月之望。吾社之行為士先者，為之聲義，斂貲財以送其行，哭聲震動天地。緹騎按劍而前，問誰為哀者？眾不能堪，抶而仆之。是時以大中丞撫吳者，為魏之私人，周公之逮所繇使也。", "吳之民方痛心焉，於是乘其厲聲以呵，則譟而相逐。中丞匿於溷藩以免。既而以吳民之亂請於朝，按誅五人，曰顏佩韋、楊念如、馬杰、沈揚、周文元，即今之傫然在墓者也。"], "intro": "《五人墓碑記》選自張溥《七錄齋集存稿》卷三。明熹宗天啟六年（一六二六）三月十五日，宦官魏忠賢派人至蘇州逮捕東林黨人周順昌，激起當地數萬市民義憤，奮起打死捕人官差。江蘇巡撫毛一鷺下令將倡亂民顏佩韋、馬杰、沈揚、楊念如、周文元五人處死。明思宗即", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%BA%94%E4%BA%BA%E5%A2%93%E7%A2%91%E8%A8%98"}, {"title": "牡丹亭・驚夢", "author": "湯顯祖", "period": "明", "form": "曲", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["〔遶地遊〕（旦上）夢回鶯囀，亂煞年光遍。人立小庭深院。（貼）炷盡沉煙，拋殘繡線，恁今春關情似去年？〔烏夜啼〕「（旦）曉來望斷梅關，宿妝殘。（貼）你側着宜春髻子恰憑闌。（旦）翦不斷，理還亂，悶無端。（貼）已分付催花鶯燕借春看。」（旦）春香，可曾叫人掃除花徑？（貼）分付了。（旦）取鏡臺衣服來。（貼取鏡臺衣服上）「雲髻罷梳還對鏡，羅衣欲換更添香。」鏡臺衣服在此。", "〔步步嬌〕（旦）裊晴絲吹來閒庭院，搖漾春如線。停半晌，整花鈿。沒揣菱花，偷人半面，迤逗的彩雲偏。（行介）步香閨怎便把全身現！（貼）今日穿插的好。", "〔醉扶歸〕（旦）你道翠生生出落的裙衫兒茜，豔晶晶花簪八寶填，可知我常一生兒愛好是天然。恰三春好處無人見。不隄防沉魚落雁鳥驚諠，則怕的羞花閉月花愁顫。（貼）早茶時了，請行。（行介）你看「畫廊金粉半零星，池館蒼苔一片青。踏草怕泥新繡襪，惜花疼煞小金鈴」。（旦）不到園林，怎知春色如許！", "〔皁羅袍〕原來姹紫嫣紅開遍，似這般都付與斷井頹垣。良辰美景奈何天，賞心樂事誰家院！恁般景致，我老爺和奶奶再不提起。（合）朝飛暮捲，雲霞翠軒；雨絲風片，煙波畫船——錦屏人忒看的這韶光賤！（貼）是花都放了，那牡丹還早。", "〔好姐姐〕（旦）遍青山紅啼了杜鵑，荼外煙絲醉軟。春香呵，牡丹雖好，他春歸怎占的先！（貼）成對兒鶯燕呵。（合）閒凝眄，生生燕語明如翦，嚦嚦鶯歌溜的圓。（旦）去罷。（貼）這園子委是觀之不足也。（旦）提他怎的！（行介）", "〔隔尾〕觀之不足由他繾，便賞遍了十二亭臺是枉然。到不如興盡回家閒過遣。（作到介）（貼）「開我西閣門，展我東閣牀。瓶插映山紫，爐添沉水香。」小姐，你歇息片時，俺瞧老夫人去也。（下）（旦歎介）「默地遊春轉，小試宜春面。」春呵，得和你兩留連，春去如何遣？咳，恁般天氣，好困人也。春香那裏？（作左右瞧介）（又低首沉吟介）天呵，春色惱人，信有之乎！常觀詩詞樂府，古之女子，因春感情，遇秋成恨，誠不謬矣。吾今年已二八，未逢折桂之夫。忽慕春情，怎得蟾宮之客？昔日韓夫人得遇于郎，張生偶逢崔氏，曾有《題紅記》、《崔徽傳》二書。此佳人才子，前以密約偷期，後皆得成秦晉。（長歎介）吾生於宦族，長在名門。年已及笄，不得早成佳配，誠為虛度青春。光陰如過隙耳。（淚介）可惜妾身顏色如花，豈料命如一葉乎！", "〔山坡羊〕（旦）沒亂裏春情難遣，驀地裏懷人幽怨。則為俺生小嬋娟，揀名門一例、一例裏神仙眷。甚良緣，把青春拋的遠！俺的睡情誰見？則索因循面覥。想幽夢誰邊，和春光暗流轉？遷延，這衷懷那處言！淹煎，潑殘生，除問天！身子困乏了，且自隱几而眠。（睡介）（夢生介）（生持柳枝上）「鶯逢日暖歌聲滑，人遇風情笑口開。一徑落花隨水入，今朝阮肇到天台。」小生順路兒跟着杜小姐回來，怎生不見？（回看介）呀，小姐，小姐！（旦作驚起介）（相見介）（生）小生那一處不尋訪小姐來，卻在這裏！（旦作斜視不語介）（生）恰好花園內，折取垂柳半枝。姐姐，你既淹通書史，可作詩以賞此柳枝乎？（旦作驚喜，欲言又止介）（背想）這生素昧平生，何因到此？（生笑介）小姐，咱愛殺你哩！", "〔山桃紅〕則為你如花美眷，似水流年，是答兒閒尋遍。在幽閨自憐。小姐，和你那答兒講話去。（旦作含笑不行）（生作牽衣介）（旦低問）那邊去？（生）轉過這芍藥欄前，緊靠着湖山石邊。（旦低問）秀才，去怎的？（生低答）和你把領扣鬆，衣帶寬。袖梢兒搵着牙兒苫也，則待你忍耐溫存一晌眠。（旦作羞）（生前抱）（旦推介）（合）是那處曾相見，相看儼然。早難道這好處相逢無一言。（生強抱旦下）（末扮花神束髮冠，紅衣插花上）「催花御史惜花天，檢點春工又一年。蘸客傷心紅雨下，勾人懸夢綵雲邊。」吾乃掌管南安府後花園花神是也。因杜知府小姐麗娘，與柳夢梅秀才，後日有姻緣之分。杜小姐游春感傷，致使柳秀才入夢。咱花神專掌惜玉憐香，竟來保護他，要他雲雨十分歡幸也。", "〔鮑老催〕（末）單則是混陽蒸變，看他似蟲兒般蠢動把風情搧。一般兒嬌凝翠綻魂兒顫。這是景上緣，想內成，因中見。呀，淫邪展污了花臺殿。咱待拈片落花兒驚醒他。（向鬼門丟花介）他夢酣春透了怎留連？拈花閃碎的紅如片。秀才，纔到的半夢兒。夢畢之時，好送杜小姐仍歸香閣。吾神去也。（下）", "〔山桃紅〕（生、旦攜手上）這一霎天留人便，草藉花眠。小姐可好？（旦低頭介）（生）則把雲鬟點，紅鬆翠偏。小姐休忘了呵，見了你緊相偎，慢廝連，恨不得肉兒般團成片也，逗的箇日下胭脂雨上鮮。（旦）秀才，你可去呵。（合）是那處曾相見，相看儼然，早難道這好處相逢無一言。（生）姐姐，你身子乏了，將息，將息。（送旦依前作睡介）（輕拍旦介）姐姐，俺去了。（作回顧介）姐姐，你可十分將息，我再來瞧你那。「行來春色三分雨，睡去巫山一片雲。」（下）（旦作驚醒，低叫介）秀才，秀才，你去了也。（又作癡睡介）（老旦上）「夫坐黃堂，嬌娃立繡窗。怪他裙衩上，花鳥繡雙雙。」孩兒，孩兒，你為甚瞌睡在此？（旦作醒，叫秀才介）咳也。（老旦）孩兒怎的來？（旦作驚起介）奶奶到此！（老旦）我兒，何不做些鍼指，或觀玩書史，舒展情懷？因何晝寢於此？（旦）孩兒適花園中閒玩，忽值春喧惱人，故此回房。無可消遣，不覺困倦少息。有失迎接，望母親恕兒之罪。（老旦）孩兒，這後花園中冷靜，少去閒行。（旦）領母親嚴命。（老旦）孩兒，書堂看書去。（旦）先生不在，且自消停。（老旦歎介）女孩兒長成，自有許多情態，且自由他。正是「宛轉隨兒女，辛勤做老娘」。（下）（旦長歎介）（看老旦下介）哎也，天那，今日杜麗娘有些僥倖也。偶到後花園中，百花開遍，覩景傷情。沒興而回，晝眠香閣。忽見一生，年可弱冠，丰姿俊妍。於園中折得柳絲一枝，笑對奴家說︰『姐姐既淹通書史，何不將柳枝題賞一篇？』那時待要應他一聲，心中自忖，素昧平生，不知名姓，何得輕與交言。正如此想間，只見那生向前說了幾句傷心話兒，將奴摟抱去牡丹亭畔，芍藥闌邊，共成雲雨之歡。兩情和合，真箇是千般愛惜，萬種溫存。歡畢之時，又送我睡眠，幾聲『將息』。正待自送那生出門，忽值母親來到，喚醒將來。我一身冷汗，乃是南柯一夢。忙身參禮母親，又被母親絮了許多閒話。奴家口雖無言答應，心內思想夢中之事，何曾放懷。行坐不甯，自覺如有所失。娘呵，你教我學堂看書去，知他看那一種書消悶也。（作掩淚介）", "〔綿搭絮〕（旦）雨香雲片，纔到夢兒邊。無奈高堂，喚醒紗窗睡不便。潑新鮮冷汗粘煎。閃的俺心悠步嚲，意輭鬟偏。不爭多費盡神情，坐起誰忺？則待去眠。（貼上）「晚妝銷粉印，春潤費香篝。」小姐，薰了被窩睡罷。", "〔尾聲〕（旦）困春心遊賞倦，也不索香薰繡被眠。天呵，有心情那夢兒還去不遠。"], "quote": ["〔遶地遊〕（旦上）夢回鶯囀，亂煞年光遍。人立小庭深院。（貼）炷盡沉煙，拋殘繡線，恁今春關情似去年？〔烏夜啼〕「（旦）曉來望斷梅關，宿妝殘。（貼）你側着宜春髻子恰憑闌。（旦）翦不斷，理還亂，悶無端。（貼）已分付催花鶯燕借春看。」（旦）春香，可曾叫人掃除花徑？（貼）分付了。（旦）取鏡臺衣服來。（貼取鏡臺衣服上）「雲髻罷梳還對鏡，羅衣欲換更添香。」鏡臺衣服在此。", "〔步步嬌〕（旦）裊晴絲吹來閒庭院，搖漾春如線。停半晌，整花鈿。沒揣菱花，偷人半面，迤逗的彩雲偏。（行介）步香閨怎便把全身現！（貼）今日穿插的好。", "〔醉扶歸〕（旦）你道翠生生出落的裙衫兒茜，豔晶晶花簪八寶填，可知我常一生兒愛好是天然。恰三春好處無人見。不隄防沉魚落雁鳥驚諠，則怕的羞花閉月花愁顫。（貼）早茶時了，請行。（行介）你看「畫廊金粉半零星，池館蒼苔一片青。踏草怕泥新繡襪，惜花疼煞小金鈴」。（旦）不到園林，怎知春色如許！", "〔皁羅袍〕原來姹紫嫣紅開遍，似這般都付與斷井頹垣。良辰美景奈何天，賞心樂事誰家院！恁般景致，我老爺和奶奶再不提起。（合）朝飛暮捲，雲霞翠軒；雨絲風片，煙波畫船——錦屏人忒看的這韶光賤！（貼）是花都放了，那牡丹還早。"], "intro": "本課選自明代傳奇《牡丹亭》第十齣《驚夢》，版本據中華書局排印本。傳奇是明人對南曲戲文的專稱，和唐、宋人專用以指短篇小說不同。明傳奇亦有別於元雜劇，除了南北樂器、樂譜、曲調及風格相異外，明傳奇無論在形式、宮調和劇本折數上，都較元雜劇更自由和更", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%89%A1%E4%B8%B9%E4%BA%AD%E3%83%BB%E9%A9%9A%E5%A4%A2"}, {"title": "臨江仙（滾滾長江東逝水）", "author": "楊慎", "period": "明", "form": "詞", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["滾滾長江東逝水，浪花淘盡英雄。是非成敗轉頭空。青山依舊在，幾度夕陽紅。", "白髮漁樵江渚上，慣看秋月春風。一壺濁酒喜相逢。古今多少事，都付笑談中。"], "quote": ["滾滾長江東逝水，浪花淘盡英雄。是非成敗轉頭空。青山依舊在，幾度夕陽紅。", "白髮漁樵江渚上，慣看秋月春風。一壺濁酒喜相逢。古今多少事，都付笑談中。"], "intro": "明代正德年間，明武宗寵用太監劉瑾，立內廠，疏於政事，耽於淫樂。世宗嘉靖年間，「大禮議」事件發生，君臣之爭不絕，廷杖大臣，朝政敗壞。楊慎兩次力諫不獲，兩次被廷杖，幾死復蘇，謫戍雲南永昌，終身不復錄用。楊慎自是謫居雲南長達三十八年，疏遠朝廷紛爭", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%87%A8%E6%B1%9F%E4%BB%99%EF%BC%88%E6%BB%BE%E6%BB%BE%E9%95%B7%E6%B1%9F%E6%9D%B1%E9%80%9D%E6%B0%B4%EF%BC%89"}, {"title": "五月十九日大雨", "author": "劉基", "period": "明", "form": "詩", "theme": "歲時雪月", "mood": "spring_breeze", "lines": ["風驅急雨灑高城，", "雲壓輕雷殷地聲，", "雨過不知龍去處，", "一池草色萬蛙鳴。"], "quote": ["風驅急雨灑高城，", "雲壓輕雷殷地聲，", "雨過不知龍去處，", "一池草色萬蛙鳴。"], "intro": "劉基為明初開國大臣，功勳昭著，而詩文創作，亦一代作手，成就不凡。朱元璋即位幾年後，朝廷人事紛爭，劉基於是辭官田居，心境漸復平靜。《五月十九日大雨》所寫情景，隱然可見平淡的心跡。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%BA%94%E6%9C%88%E5%8D%81%E4%B9%9D%E6%97%A5%E5%A4%A7%E9%9B%A8"}, {"title": "賣柑者言", "author": "劉基", "period": "明", "form": "文", "theme": "邊塞豪放", "mood": "snow_winter", "lines": ["杭有賣果者，善藏柑，涉寒暑不潰。出之燁然，玉質而金色。置於市，賈十倍，人爭鬻之。", "予貿得其一，剖之，如有煙撲口鼻，視其中，則乾若敗絮。予恠而問之曰︰「若所市於人者，將以實籩豆，奉祭祀，供賓客乎？將衒外以惑愚瞽也？甚矣哉，爲欺也！」", "賣者笑曰︰「吾業是有年矣，吾賴是以食吾軀。吾售之，人取之，未嘗有言，而獨不足子所乎？世之爲欺者不寡矣，而獨我也乎？吾子未之思也。今夫佩虎符坐皋比者，洸洸乎干城之具也，果能授孫吳之略耶？峨大冠拖長紳者，昂昂乎廟堂之器也，果能建伊皋之業耶？", "盜起而不知禦，民困而不知救，吏姦而不知禁，法斁而不知理，坐糜廩粟而不知恥;觀其坐高堂、騎大馬，醉醇醴而飫肥鮮者，孰不巍巍乎可畏，赫赫乎可象也？又何往而不金玉其外，敗絮其中也哉？今子是之不察，而以察吾柑。」", "予默然無以應。退而思其言，類東方生滑稽之流。豈其憤世疾邪者耶？而託於柑以諷耶？"], "quote": ["杭有賣果者，善藏柑，涉寒暑不潰。出之燁然，玉質而金色。置於市，賈十倍，人爭鬻之。", "予貿得其一，剖之，如有煙撲口鼻，視其中，則乾若敗絮。予恠而問之曰︰「若所市於人者，將以實籩豆，奉祭祀，供賓客乎？將衒外以惑愚瞽也？甚矣哉，爲欺也！」", "賣者笑曰︰「吾業是有年矣，吾賴是以食吾軀。吾售之，人取之，未嘗有言，而獨不足子所乎？世之爲欺者不寡矣，而獨我也乎？吾子未之思也。今夫佩虎符坐皋比者，洸洸乎干城之具也，果能授孫吳之略耶？峨大冠拖長紳者，昂昂乎廟堂之器也，果能建伊皋之業耶？", "盜起而不知禦，民困而不知救，吏姦而不知禁，法斁而不知理，坐糜廩粟而不知恥;觀其坐高堂、騎大馬，醉醇醴而飫肥鮮者，孰不巍巍乎可畏，赫赫乎可象也？又何往而不金玉其外，敗絮其中也哉？今子是之不察，而以察吾柑。」"], "intro": "《賣柑者言》選自《誠意伯文集》卷七。這是一篇諷刺性散文。作者藉賣柑者之口，揭露元朝末年社會的腐敗，嘲諷某些居高位的文臣武將，無不如杭柑之「金玉其外，敗絮其中」，都是虛有其表的庸才。文句簡煉，內容發人深省。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B3%A3%E6%9F%91%E8%80%85%E8%A8%80"}, {"title": "遊龍門記", "author": "薛瑄", "period": "明", "form": "文", "theme": "山水登臨", "mood": "snow_winter", "lines": ["出河津縣西郭門，西北三十里，抵龍門下；東西皆層巒危峯，橫出天漢。大河自西北山峽中來，至是，山斷河出，兩壁儼立相望。神禹疏鑿之勞，於此為大。繇東南麓，穴巖構木，浮虛駕水為棧道，盤曲而上。", "瀕河有寬平地，可二三畝，多石少土。中有禹廟，宮曰「明德」，制極宏麗；進謁庭下，悚肅思德者久之。庭多青松奇木，根負土石，突走連結，枝葉疏密交蔭，皮幹蒼勁偃蹇，形狀毅然若壯夫離立，相持不相下。", "宮門西南一石峯，危出半流。步石磴，登絕頂，頂有「臨思閣」，以風高不可木，甃甓為之。倚閣門俯視，大河奔湍，三面觸激，石峯疑若搖振；北顧巨峽，丹崖翠壁，生雲走霧，開闔晦明，倏忽萬變；", "西側連山宛宛而去；東視大山，巍然與天浮；南望洪濤漫流，石洲沙渚，高原缺岸，煙村霧樹，風帆浪舸，渺茫出沒，太華、潼關、雍、豫諸山，彷佛見之；蓋天下之奇觀也。", "下磴道石峯，東穿石崖，橫豎施木，憑空為樓；樓心穴板，上置井牀、轆轤，懸繘汲河。憑欄檻，涼風飄瀟，若列禦寇馭氣在空中立也。復自水樓北道，出宮後百餘步，至右谷；下視窈然。東距山，西臨河谷，南北涯相去尋尺，上橫老槎為橋，蹐步以渡。", "谷北二百舉武，有小祠扁曰「后土」；北山陡起，下與河際。遂窮祠東，有石龕窿然若大屋，懸石參差，若人形，若鳥翼，若獸吻，若肝肺，若疣贅，若懸鼎，若編磬，若璞未鑿，若礦未爐︰其狀莫窮。懸泉滴石上，鏘然有聲。", "龕下石縱橫羅列︰偃者，側者，立者；若牀，若几，若屏；可席，可憑，可倚。氣陰陰，雖甚暑，不知煩燠；但淒神寒肌，不可久處。復自槎橋道由「明德宮」左，歷石梯上。", "東南山腹有道院，地勢與「臨思閣」相高下，亦可以眺望河山之勝。遂自石梯下棧道，臨流觀渡，並東山而歸。", "時宣德元年丙午，夏五月某日。同游者楊景端也。"], "quote": ["出河津縣西郭門，西北三十里，抵龍門下；東西皆層巒危峯，橫出天漢。大河自西北山峽中來，至是，山斷河出，兩壁儼立相望。神禹疏鑿之勞，於此為大。繇東南麓，穴巖構木，浮虛駕水為棧道，盤曲而上。", "瀕河有寬平地，可二三畝，多石少土。中有禹廟，宮曰「明德」，制極宏麗；進謁庭下，悚肅思德者久之。庭多青松奇木，根負土石，突走連結，枝葉疏密交蔭，皮幹蒼勁偃蹇，形狀毅然若壯夫離立，相持不相下。", "宮門西南一石峯，危出半流。步石磴，登絕頂，頂有「臨思閣」，以風高不可木，甃甓為之。倚閣門俯視，大河奔湍，三面觸激，石峯疑若搖振；北顧巨峽，丹崖翠壁，生雲走霧，開闔晦明，倏忽萬變；", "西側連山宛宛而去；東視大山，巍然與天浮；南望洪濤漫流，石洲沙渚，高原缺岸，煙村霧樹，風帆浪舸，渺茫出沒，太華、潼關、雍、豫諸山，彷佛見之；蓋天下之奇觀也。"], "intro": "龍門，山名；介於今山西河津縣西北與陝西韓城縣東北之間，有東山及西山，分跨黃河的兩岸，形如門闕。相傳大禹治水時，把黃河疏導到這裏，為此山所阻，便鑿以通流。《書經‧禹貢》有「導河積石，至于龍門」之句，注云：「韓城縣北有安國嶺（按即龍門西山）。禹", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%81%8A%E9%BE%8D%E9%96%80%E8%A8%98"}, {"title": "明日歌", "author": "錢福", "period": "明", "form": "詩", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["明日復明日，明日何其多。我生待明日，萬事成蹉跎！世人苦被明日累，春去秋來老將至。朝看水東流，暮看日西墜。百年明日能幾何？請君聽我《明日歌》。"], "quote": ["明日復明日，明日何其多。我生待明日，萬事成蹉跎！世人苦被明日累，春去秋來老將至。朝看水東流，暮看日西墜。百年明日能幾何？請君聽我《明日歌》。"], "intro": "本詩收錄在《鶴灘稿》卷一。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%98%8E%E6%97%A5%E6%AD%8C"}, {"title": "核舟記", "author": "魏學洢", "period": "明", "form": "文", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["明有奇巧人曰王叔遠，能以徑寸之木，為宮室、器皿、人物，以至鳥、獸、木、石，罔不因勢象形，各具情態。嘗貽余核舟一，蓋「大蘇泛赤壁」云。", "舟首尾長約八分有奇，高可二黍許。中軒敞者為艙，篛篷覆之。旁開小窗，左右各四，共八扇。啟窗而觀，雕欄相望焉。閉之，則右刻「山高月小，水落石出」，左刻「清風徐來，水波不興」，石青糝之。", "船頭坐三人，中峨冠而多髯者為東坡，佛印居右，魯直居左。蘇黃共閱一手卷。東坡右手執卷端，左手撫魯直背；魯直左手執卷末，右手指卷如有所語。東坡現右足，魯直現左足，身各微側。", "其兩膝相比者，各隱卷底衣褶中。佛印絕類彌勒，袒胸露乳，矯首昂視，神情與蘇黃不屬。臥右膝，詘右臂支船，而豎其左膝。左臂掛念珠倚之，珠可歷歷數也。", "舟尾橫臥一檝，檝左右舟子各一人︰居右者椎髻仰面，左手倚一衡木，右手攀右趾若嘯呼狀；居左者右手執蒲葵扇，左手撫爐，爐上有壺，其人視端容寂，若聽茶聲然。", "其船背稍夷，則題名其上，文曰︰「天啟壬戌秋日，虞山王毅叔遠甫刻。」細若蚊足，鉤畫了了，其色墨。又用篆章一，文曰「初平山人」，其色丹。", "通計一舟︰為人五，為窗八、為篛篷、為檝、為爐、為壺、為手卷、為念珠各一；對聯、題名並篆文，為字共三十有四；而計其長，曾不盈寸，蓋簡桃核修狹者為之。", "魏子詳矚既畢，詫曰︰「嘻，技亦靈怪矣哉！莊、列所載稱驚猶鬼神者良多，然誰有游削於不寸之質而須麋瞭然者？", "假有人焉，舉我言以復於我，亦必疑其誑，乃今親睹之。繇斯以觀，棘刺之端，未必不可為母猴也。嘻，技亦靈怪矣哉！」"], "quote": ["明有奇巧人曰王叔遠，能以徑寸之木，為宮室、器皿、人物，以至鳥、獸、木、石，罔不因勢象形，各具情態。嘗貽余核舟一，蓋「大蘇泛赤壁」云。", "舟首尾長約八分有奇，高可二黍許。中軒敞者為艙，篛篷覆之。旁開小窗，左右各四，共八扇。啟窗而觀，雕欄相望焉。閉之，則右刻「山高月小，水落石出」，左刻「清風徐來，水波不興」，石青糝之。", "船頭坐三人，中峨冠而多髯者為東坡，佛印居右，魯直居左。蘇黃共閱一手卷。東坡右手執卷端，左手撫魯直背；魯直左手執卷末，右手指卷如有所語。東坡現右足，魯直現左足，身各微側。", "其兩膝相比者，各隱卷底衣褶中。佛印絕類彌勒，袒胸露乳，矯首昂視，神情與蘇黃不屬。臥右膝，詘右臂支船，而豎其左膝。左臂掛念珠倚之，珠可歷歷數也。"], "intro": "核舟，是用桃核雕刻成的一隻小船。作者的朋友王毅，是當時的雕刻藝術家，刻了一個核舟贈送給他，他就寫了這篇文章，來記述核舟的工巧。一般選本多有刪節，今照原文補正。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%A0%B8%E8%88%9F%E8%A8%98"}, {"title": "項脊軒志", "author": "歸有光", "period": "明", "form": "文", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["項脊軒，舊南閤子也。室僅方丈，可容一人居。百年老屋，塵泥滲漉，雨澤下注，每移案，顧視無可置者。又北向，不能得日，日過午已昏。", "余稍為修葺，使不上漏；前闢四窗，垣牆周庭，以當南日；日影反照，室始洞然。又雜植蘭桂竹木於庭，舊時欄楯，亦遂增勝。借書滿架，偃仰嘯歌，冥然兀坐，萬籟有聲。而庭堦寂寂，小鳥時來啄食，人至不去。", "三五之夜，明月半牆，桂影斑駁，風移影動，珊珊可愛。然予居於此，多可喜，亦多可悲。", "先是，庭中通南北為一，迨諸父異爨，內外多置小門牆，往往而是。東犬西吠，客踰庖而宴，雞棲於廳。庭中始為籬，已為牆，凡再變矣。", "家有老嫗，嘗居於此。嫗，先大母婢也，乳二世，先妣撫之甚厚。室西連於中閨，先妣嘗一至。嫗每謂予曰︰「某所，而母立於茲。」", "嫗又曰︰「汝姊在吾懷，呱呱而泣。娘以指扣門扉曰︰『兒寒乎？欲食乎？』吾從板外相為應答。」語未畢，余泣，嫗亦泣。", "余自束髮，讀書軒中。一日，大母過余曰︰「吾兒，久不見若影，何竟日默默在此，大類女郎也！」比去，以手闔門，自語曰︰「吾家讀書久不效，兒之成，則可待乎？」", "頃之，持一象笏至，曰︰「此吾祖太常公宣德間執此以朝，他日，汝當用之。」瞻顧遺跡，如在昨日，令人長號不自禁。", "軒東故嘗為廚，人往，從軒前過。余扃牖而居，久之，能以足音辨人。軒凡四遭火，得不焚，殆有神護者。", "項脊生曰︰「蜀清守丹穴，利甲天下。其後秦皇帝築女懷清臺。劉玄德與曹操爭天下，諸葛孔明起隴中。方二人之昧昧于一隅也，世何足以知之？」", "余區區處敗屋中，方揚眉瞬目，謂有奇景。人知之者，其謂與埳井之蛙何異！", "余既為此志，後五年，吾妻來歸。時至軒中，從余問古事，或憑几學書。吾妻歸寧，述諸小妹語曰︰「聞姊家有閤子，且何謂閤子也？」其後六年，吾妻死，室壞不修。"], "quote": ["項脊軒，舊南閤子也。室僅方丈，可容一人居。百年老屋，塵泥滲漉，雨澤下注，每移案，顧視無可置者。又北向，不能得日，日過午已昏。", "余稍為修葺，使不上漏；前闢四窗，垣牆周庭，以當南日；日影反照，室始洞然。又雜植蘭桂竹木於庭，舊時欄楯，亦遂增勝。借書滿架，偃仰嘯歌，冥然兀坐，萬籟有聲。而庭堦寂寂，小鳥時來啄食，人至不去。", "三五之夜，明月半牆，桂影斑駁，風移影動，珊珊可愛。然予居於此，多可喜，亦多可悲。", "先是，庭中通南北為一，迨諸父異爨，內外多置小門牆，往往而是。東犬西吠，客踰庖而宴，雞棲於廳。庭中始為籬，已為牆，凡再變矣。"], "intro": "本文選自《震川先生集》卷十七，是一篇出色的雜記。項脊軒，作者書齋的名字。作者遠祖歸道隆，曾居江蘇太倉的項脊涇。作者以此名軒，是為了紀念祖上。志，是古代文體的一種，內容以記人敍事為主。歸有光的散文包括學術、雜記、墓誌諸體，以雜記的成就最高。其", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%A0%85%E8%84%8A%E8%BB%92%E5%BF%97"}, {"title": "三國志演義・諸葛亮舌戰羣儒", "author": "羅貫中", "period": "明", "form": "小說", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["卻說魯肅、孔明辭了玄德、劉琦，登舟望柴桑郡來。二人在舟中共議。魯肅謂孔明曰︰「先生見孫將軍，切不可實言曹操兵多將廣。」孔明曰︰「不須子敬叮嚀，亮自有對答之語。」及船到岸，肅請孔明於館驛中暫歇，先自往見孫權。權正聚文武於堂上議事，聞魯肅回，急召入問曰︰「子敬往江夏，體探虛實若何？」肅曰︰「已知其略，尚容徐稟。」權將曹操檄文示肅曰︰「操昨遣使齎文至此，孤先發遣來使，現今會眾商議未定。」肅接檄文觀看。其略曰︰孤近承帝命，奉詞伐罪。旄麾南指，劉琮束手；荊襄之民，望風歸順。今統雄兵百萬，上將千員，欲與將軍會獵於江夏，共伐劉備，同分土地，永結盟好。幸勿觀望，速賜回音。", "魯肅看畢曰︰「主公尊意若何？」權曰︰「未有定論。」張昭曰︰「曹操擁百萬之眾，借天子之名，以征四方，拒之不順。且主公大勢可以拒操者，長江也。今操既得荊州，長江之險，已與我共之矣，勢不可敵。以愚之計，不如納降，為萬安之策。」眾謀士皆曰︰「子布之言，正合天意。」孫權沈吟不語。張昭又曰︰「主公不必多疑。如降操則東吳民安，江南六郡可保矣。」孫權低頭不語。須臾，權起更衣，魯肅隨於權後。權知肅意，乃執肅手而言曰︰「卿欲如何？」肅曰︰「恰纔眾人所言，深誤將軍。眾人皆可降曹操，惟將軍不可降曹操。」權曰︰「何以言之？」肅曰︰「如肅等降操，當以肅還鄉黨，累官故不失州郡也；將軍降操，欲安所歸乎？位不過封侯，車不過一乘，騎不過一匹，從不過數人，豈得南面稱孤哉！眾人之意，各自為己，不可聽也。將軍宜早定大計。」權歎曰︰「諸人議論，大失孤望。子敬開說大計，正與吾見相同。此天以子敬賜我也！但操新得袁紹之眾，近又得荊州之兵，恐勢大難以抵敵。」肅曰︰「肅至江夏，引諸葛瑾之弟諸葛亮在此，主公可問之，便知虛實。」權曰︰「臥龍先生在此乎？」肅曰︰「現在館驛中安歇。」權曰︰「今日天晚，且未相見。來日聚文武於帳下，先教見我江東英俊，然後升堂議事。」", "肅領命而去。次日至館驛中見孔明，又囑曰︰「今見我主，切不可言曹操兵多。」孔明笑曰︰「亮自見機而變，決不有誤。」肅乃引孔明至幕下。早見張昭、顧雍等一班文武二十餘人，峨冠博帶，整衣端坐。孔明逐一相見，各問姓名。施禮已畢，坐於客位。張昭等見孔明丰神飄洒，器宇軒昂，料道此人必來游說。張昭先以言挑之曰︰「昭乃江東微末之士，久聞先生高臥隆中，自比管、樂。此語果有之乎？」孔明曰︰「此亮平生小可之比也。」昭曰︰「近聞劉豫州三顧先生於草廬之中，幸得先生，以為如魚得水，思欲席捲荊襄。今一旦以屬曹操，未審是何主見？」孔明自思張昭乃孫權手下第一個謀士，若不先難倒他，如何說得孫權，遂答曰︰「吾觀取漢上之地，易如反掌。我主劉豫州躬行仁義，不忍奪同宗之基業，故力辭之。劉琮孺子，聽信佞言，暗自投降，致使曹操得以猖獗。今我主屯兵江夏，別有良圖，非等閒可知也。」昭曰︰「若此，是先生言行相違也。先生自比管、樂︰管仲相桓公，霸諸侯，一匡天下；樂毅扶持微弱之燕，下齊七十餘城；此二人者，真濟世之才也。先生在草廬之中，但笑傲風月，抱膝危坐；今既從事劉豫州，當為生靈興利除害，剿滅亂賊。且劉豫州未得先生之前，尚且縱橫寰宇，割據城池；今得先生，人皆仰望︰雖三尺童蒙，亦謂彪虎生翼，將見漢室復興，曹氏即滅矣；朝廷舊臣，山林隱士，無不拭目而待︰以為拂高天之雲翳，仰日月之光輝，拯民於水火之中，措天下於衽席之上，在此時也。何先生自歸豫州，曹兵一出，棄甲拋戈，望風而竄；上不能報劉表以安庶民，下不能輔孤子而據疆土；乃棄新野，走樊城，敗當陽，奔夏口，無容身之地︰是豫州既得先生之後，反不如其初也。管仲、樂毅，果如是乎？愚直之言，幸勿見怪！」孔明聽罷，啞然而笑曰︰「鵬飛萬里，其志豈羣鳥能識哉？譬如人染沈痾，當先用糜粥以飲之，和藥以服之；待其腑臟調和，形體漸安，然後用肉食以補之，猛藥以治之︰則病根盡去，人得全生也。若不待氣脈和緩，便投以猛藥厚味，欲求安保，誠為難矣。吾主劉豫州，向日軍敗於汝南，寄跡劉表，兵不滿千，將止關、張、趙雲而已，此正如病勢尪羸已極之時也。新野山僻小縣，人民稀少，糧食鮮薄，豫州不過暫借以容身，豈真將坐守於此耶？夫以甲兵不完，城郭不固，軍不經練，糧不繼日，然而博望燒屯，白河用水，使夏侯惇、曹仁輩心驚膽裂。竊謂管仲、樂毅之用兵，未必過此。至於劉琮降操，豫州實出不知；且又不忍乘亂奪同宗之基業，此真大仁大義也。當陽之敗，豫州見有數十萬赴義之民，扶老攜幼相隨，不忍棄之，日行十里，不思進取江陵，甘與同敗，此亦大仁大義也。寡不敵眾，勝負乃其常事。昔高皇數敗於項羽，而垓下一戰成功，此非韓信之良謀乎？夫信久事高皇，未嘗累勝。蓋國家大計，社稷安危，是有主謀。非比誇辯之徒，虛譽欺人，坐議立談，無人可及；臨機應變，百無一能︰誠為天下笑耳！」這一篇言語，說得張昭並無一言回答。", "座上忽一人抗聲問曰︰「今曹公兵屯百萬，將列千員，龍驤虎視，平吞江夏，公以為何如？」孔明視之，乃虞翻也。孔明曰︰「曹操收袁紹蟻聚之兵，劫劉表烏合之眾，雖數百萬不足懼也。」虞翻冷笑曰︰「軍敗於當陽，計窮於夏口，區區求救於人，而猶言不懼，此真大言欺人也！」孔明曰︰「劉豫州以數千仁義之師，安能敵百萬殘暴之眾，退守夏口，所以待時也。今江東兵精糧足，且有長江之險，猶欲使其主屈膝降賊，不顧天下恥笑；由此論之，劉豫州真不懼操賊者矣！」虞翻不能對。", "座間又一人問曰︰「孔明欲效儀、秦之舌，游說東吳耶？」孔明視之，乃步騭也。孔明曰︰「步子山以蘇秦、張儀為辯士，不知蘇秦、張儀亦豪傑也︰蘇秦佩六國相印，張儀兩次相秦，皆有匡扶人國之謀，非比畏強凌弱，懼刀避劍之人也。君等聞曹操虛發詐偽之詞，便畏懼請降，敢笑蘇秦、張儀乎？」步騭默然無語。", "忽一人問曰︰「孔明以曹操何如人也？」孔明視其人，乃薛綜也。孔明答曰︰「曹操乃漢賊也，又何必問？」綜曰︰「公言差矣。漢歷傳至今，天數將終。今曹公已有天下三分之二，人皆歸心。劉豫州不識天時，強欲與爭，正如以卵擊石，安得不敗乎？」孔明厲聲曰︰「薛敬文安得出此無父無君之言乎！夫人生天地間，以忠孝為立身之本。公既為漢臣，則見有不臣之人，當誓共戮之，臣之道也。今曹操祖宗叨食漢祿，不思報效，反懷篡逆之心，天下之所共憤；公乃以天數歸之，真無父無君之人也！不足與語！請勿復言！」薛綜滿面羞慚，不能對答。座上又一人應聲問曰︰「曹操雖挾天子以令諸侯，猶是相國曹參之後。劉豫州雖云中山靖王苗裔，卻無可稽考，眼見只是織蓆販屨之夫耳，何足與曹操抗衡哉！」孔明視之，乃陸績也。孔明笑曰︰「公非袁術座間懷橘之陸郎乎？請安坐，聽吾一言︰曹操既為曹相國之後，則世為漢臣矣；今乃專權肆橫，欺凌君父，是不惟無君，亦且蔑祖；不惟漢室之亂臣，亦曹氏之賊子也。劉豫州堂堂帝冑，當今皇帝，按譜賜爵，何云無可稽考？且高祖起身亭長，而終有天下；織蓆販屨，又何足為辱乎？公小兒之見，不足與高士共語！」陸績語塞。", "座上一人忽曰︰「孔明所言，皆強詞奪理，均非正論，不必再言。且請問孔明治何經典？」孔明視之，乃嚴畯也。孔明曰︰「尋章摘句，世之腐儒也，何能興邦立事？且古耕莘伊尹，釣渭子牙，張良、陳平之流，鄧禹、耿弇之輩，皆有匡扶宇宙之才，未審其生平治何經典。豈亦效書生區區於筆硯之間，數黑論黃，舞文弄墨而已乎？」嚴畯低頭喪氣而不能對。", "忽又一人大聲曰︰「公好為大言，未必真有實學，恐適為儒者所笑耳。」孔明視其人，乃汝南程德樞也。孔明答曰︰「儒有君子小人之別︰君子之儒，忠君愛國，守正惡邪，務使澤及當時，名留後世。若夫小人之儒，惟務彫蟲，專工翰墨，青春作賦，皓首窮經，筆下雖有千言，胸中實無一策；且如揚雄以文章名世，而屈身事莽，不免投閣而死，此所謂小人之儒也；雖日賦萬言，亦何取哉！」程德樞不能對。眾人見孔明對答如流，盡皆失色。", "時座上張溫、駱統二人，又欲問難。忽一人自外而入，厲聲言曰︰「孔明乃當世奇才，君等以脣舌相難，非敬客之禮也。曹操大軍臨境，不思退敵之策，乃徒鬥口耶！」眾視其人，乃零陵人，姓黃，名蓋，字公覆，現為東吳糧官。當時黃蓋謂孔明曰︰「愚聞多言獲利，不如默而無言。何不將金石之論為我主言之，乃與眾人辯論也？」孔明曰︰「諸君不知世務，互相問難，不容不答耳。」於是黃蓋與魯肅引孔明入。至中門，正遇諸葛瑾，孔明施禮。瑾曰︰「賢弟既到江東，如何不來見我？」孔明曰︰「弟既事劉豫州，理宜先公後私。公事未畢，不敢及私。望兄見諒。」瑾曰︰「賢弟見過吳侯，卻來敍話。」說罷自去。", "魯肅曰︰「適間所囑，不可有誤。」孔明點頭應諾。引至堂上，孫權降階而迎，優禮相待。施禮畢，賜孔明坐。眾文武分兩行而立。魯肅立於孔明之側，只看他講話。孔明致玄德之意畢。偷眼看孫權︰碧眼紫鬚，堂堂一表。孔明暗思︰「此人相貌非常，只可激，不可說。等他問時，用言激之便了。」獻茶已畢，孫權曰︰「多聞魯子敬談足下之才，今幸得相見，敢求教益。」孔明曰︰「不才無學，有辱明問。」權曰︰「足下近在新野，佐劉豫州與曹操決戰，必深知彼軍虛實。」孔明曰︰「劉豫州兵微將寡，更兼新野城小無糧，安能與曹操相持？」權曰︰「曹兵共有多少？」孔明曰︰「馬步水軍，約有一百餘萬。」權曰︰「莫非詐乎？」孔明曰︰「非詐也︰曹操就兗州已有青州軍二十萬，平了袁紹，又得五六十萬；中原新招之兵三四十萬；今又得荊州之軍二三十萬︰以此計之，不下一百五十萬。亮以百萬言之，恐驚江東之士也。」魯肅在旁，聞言失色，以目視孔明；孔明只做不見。權曰︰「曹操部下戰將，還有多少？」孔明曰︰「足智多謀之士，能征慣戰之將，何止一二千人！」權曰︰「今曹操平了荊、楚，復有遠圖乎？」孔明曰︰「即今沿江下寨，準備戰船，不欲圖江東，待取何地？」權曰︰「若彼有吞併之意，戰與不戰，請足下為我一決。」孔明曰︰「亮有一言，但恐將軍不肯聽從。」權曰︰「願聞高論。」孔明曰︰「向者宇內大亂，故將軍起江東，劉豫州收眾漢南，與曹操並爭天下。今操芟除大難，略已平矣；近又新破荊州，威震海內；縱有英雄，無用武之地︰故豫州遁逃至此。願將軍量力而處之。若能以吳、越之眾，與中國抗衡，不如早與之絕；若其不能，何不從眾謀士之論，按兵束甲，北面而事之？」權未及答。孔明又曰︰「將軍外託服從之名，內懷疑貳之見，事急而不斷，禍至無日矣。」權曰︰「誠如君言，劉豫州何不降操？」孔明曰︰「昔田橫齊之壯士耳，猶守義不辱；況劉豫州王室之冑，英才蓋世，眾士仰慕？事之不濟，此乃天也，又安能屈處人下乎？」", "孫權聽了孔明此言，不覺勃然變色，拂衣而起，退入後堂。眾皆哂笑而散。魯肅責孔明曰︰「先生何故出此言？幸是吾主寬洪大度，不即面責。先生之言，藐視吾主甚矣。」孔明仰面笑曰︰「何如此不能容物耶！我自有破曹之計，彼不問我，我故不言。」肅曰︰「果有良策，肅當請主公求教。」孔明曰︰「吾視曹操百萬之眾，如羣蟻耳！但我一舉手，則皆為虀粉矣！」肅聞言，便入後堂，見孫權。權怒氣未息，顧謂肅曰︰「孔明欺吾太甚！」肅曰︰「臣亦以此責孔明，孔明反笑主公不能容物，破曹之策，孔明不肯輕言。主公何不求之？」權回嗔作喜曰︰「原來孔明有良謀，故以言詞激我。我一時淺見，幾誤大事。」便同魯肅重復出堂，再請孔明敍話。權見孔明，謝曰︰「適來冒瀆威嚴，幸勿見罪。」孔明亦謝曰︰「亮言語冒犯，望乞恕罪。」權邀孔明入後堂，置酒相待。", "數巡之後，權曰︰「曹操平生所惡者︰呂布、劉表、袁紹、袁術、豫州與孤耳。今數雄已滅，獨豫州與孤尚存。孤不能以全吳之地，受制於人。吾計決矣。非劉豫州莫與當曹操者；然豫州新敗之後，安能抗此難乎？」孔明曰︰「豫州雖新敗，然關雲長猶率精兵萬人；劉琦領江夏戰士，亦不下萬人。曹操之眾，遠來疲憊；近追豫州，輕騎一日夜行三百里。此所謂『強弩之末，勢不能穿魯縞』者也。且北方之人，不習水戰。荊州士民附操者，迫於勢耳，非本心也。今將軍誠能與豫州協力同心，破曹軍必矣。操軍破，必北還，則荊、吳之勢強，而鼎足之形成矣。成敗之機，在於今日。惟將軍裁之。」權大悅曰︰「先生之言，頓開茅塞。吾意已決，更無他疑。即日商議起兵，共滅曹操。」遂令魯肅將此意傳諭文武官員，就送孔明於館驛安歇。"], "quote": ["卻說魯肅、孔明辭了玄德、劉琦，登舟望柴桑郡來。二人在舟中共議。魯肅謂孔明曰︰「先生見孫將軍，切不可實言曹操兵多將廣。」孔明曰︰「不須子敬叮嚀，亮自有對答之語。」及船到岸，肅請孔明於館驛中暫歇，先自往見孫權。權正聚文武於堂上議事，聞魯肅回，急召入問曰︰「子敬往江夏，體探虛實若何？」肅曰︰「已知其略，尚容徐稟。」權將曹操檄文示肅曰︰「操昨遣使齎文至此，孤先發遣來使，現今會眾商議未定。」肅接檄文觀看。其略曰︰孤近承帝命，奉詞伐罪。旄麾南指，劉琮束手；荊襄之民，望風歸順。今統雄兵百萬，上將千員，欲與將軍會獵於江夏，共伐劉備，同分土地，永結盟好。幸勿觀望，速賜回音。", "魯肅看畢曰︰「主公尊意若何？」權曰︰「未有定論。」張昭曰︰「曹操擁百萬之眾，借天子之名，以征四方，拒之不順。且主公大勢可以拒操者，長江也。今操既得荊州，長江之險，已與我共之矣，勢不可敵。以愚之計，不如納降，為萬安之策。」眾謀士皆曰︰「子布之言，正合天意。」孫權沈吟不語。張昭又曰︰「主公不必多疑。如降操則東吳民安，江南六郡可保矣。」孫權低頭不語。須臾，權起更衣，魯肅隨於權後。權知肅意，乃執肅手而言曰︰「卿欲如何？」肅曰︰「恰纔眾人所言，深誤將軍。眾人皆可降曹操，惟將軍不可降曹操。」權曰︰「何以言之？」肅曰︰「如肅等降操，當以肅還鄉黨，累官故不失州郡也；將軍降操，欲安所歸乎？位不過封侯，車不過一乘，騎不過一匹，從不過數人，豈得南面稱孤哉！眾人之意，各自為己，不可聽也。將軍宜早定大計。」權歎曰︰「諸人議論，大失孤望。子敬開說大計，正與吾見相同。此天以子敬賜我也！但操新得袁紹之眾，近又得荊州之兵，恐勢大難以抵敵。」肅曰︰「肅至江夏，引諸葛瑾之弟諸葛亮在此，主公可問之，便知虛實。」權曰︰「臥龍先生在此乎？」肅曰︰「現在館驛中安歇。」權曰︰「今日天晚，且未相見。來日聚文武於帳下，先教見我江東英俊，然後升堂議事。」", "肅領命而去。次日至館驛中見孔明，又囑曰︰「今見我主，切不可言曹操兵多。」孔明笑曰︰「亮自見機而變，決不有誤。」肅乃引孔明至幕下。早見張昭、顧雍等一班文武二十餘人，峨冠博帶，整衣端坐。孔明逐一相見，各問姓名。施禮已畢，坐於客位。張昭等見孔明丰神飄洒，器宇軒昂，料道此人必來游說。張昭先以言挑之曰︰「昭乃江東微末之士，久聞先生高臥隆中，自比管、樂。此語果有之乎？」孔明曰︰「此亮平生小可之比也。」昭曰︰「近聞劉豫州三顧先生於草廬之中，幸得先生，以為如魚得水，思欲席捲荊襄。今一旦以屬曹操，未審是何主見？」孔明自思張昭乃孫權手下第一個謀士，若不先難倒他，如何說得孫權，遂答曰︰「吾觀取漢上之地，易如反掌。我主劉豫州躬行仁義，不忍奪同宗之基業，故力辭之。劉琮孺子，聽信佞言，暗自投降，致使曹操得以猖獗。今我主屯兵江夏，別有良圖，非等閒可知也。」昭曰︰「若此，是先生言行相違也。先生自比管、樂︰管仲相桓公，霸諸侯，一匡天下；樂毅扶持微弱之燕，下齊七十餘城；此二人者，真濟世之才也。先生在草廬之中，但笑傲風月，抱膝危坐；今既從事劉豫州，當為生靈興利除害，剿滅亂賊。且劉豫州未得先生之前，尚且縱橫寰宇，割據城池；今得先生，人皆仰望︰雖三尺童蒙，亦謂彪虎生翼，將見漢室復興，曹氏即滅矣；朝廷舊臣，山林隱士，無不拭目而待︰以為拂高天之雲翳，仰日月之光輝，拯民於水火之中，措天下於衽席之上，在此時也。何先生自歸豫州，曹兵一出，棄甲拋戈，望風而竄；上不能報劉表以安庶民，下不能輔孤子而據疆土；乃棄新野，走樊城，敗當陽，奔夏口，無容身之地︰是豫州既得先生之後，反不如其初也。管仲、樂毅，果如是乎？愚直之言，幸勿見怪！」孔明聽罷，啞然而笑曰︰「鵬飛萬里，其志豈羣鳥能識哉？譬如人染沈痾，當先用糜粥以飲之，和藥以服之；待其腑臟調和，形體漸安，然後用肉食以補之，猛藥以治之︰則病根盡去，人得全生也。若不待氣脈和緩，便投以猛藥厚味，欲求安保，誠為難矣。吾主劉豫州，向日軍敗於汝南，寄跡劉表，兵不滿千，將止關、張、趙雲而已，此正如病勢尪羸已極之時也。新野山僻小縣，人民稀少，糧食鮮薄，豫州不過暫借以容身，豈真將坐守於此耶？夫以甲兵不完，城郭不固，軍不經練，糧不繼日，然而博望燒屯，白河用水，使夏侯惇、曹仁輩心驚膽裂。竊謂管仲、樂毅之用兵，未必過此。至於劉琮降操，豫州實出不知；且又不忍乘亂奪同宗之基業，此真大仁大義也。當陽之敗，豫州見有數十萬赴義之民，扶老攜幼相隨，不忍棄之，日行十里，不思進取江陵，甘與同敗，此亦大仁大義也。寡不敵眾，勝負乃其常事。昔高皇數敗於項羽，而垓下一戰成功，此非韓信之良謀乎？夫信久事高皇，未嘗累勝。蓋國家大計，社稷安危，是有主謀。非比誇辯之徒，虛譽欺人，坐議立談，無人可及；臨機應變，百無一能︰誠為天下笑耳！」這一篇言語，說得張昭並無一言回答。", "座上忽一人抗聲問曰︰「今曹公兵屯百萬，將列千員，龍驤虎視，平吞江夏，公以為何如？」孔明視之，乃虞翻也。孔明曰︰「曹操收袁紹蟻聚之兵，劫劉表烏合之眾，雖數百萬不足懼也。」虞翻冷笑曰︰「軍敗於當陽，計窮於夏口，區區求救於人，而猶言不懼，此真大言欺人也！」孔明曰︰「劉豫州以數千仁義之師，安能敵百萬殘暴之眾，退守夏口，所以待時也。今江東兵精糧足，且有長江之險，猶欲使其主屈膝降賊，不顧天下恥笑；由此論之，劉豫州真不懼操賊者矣！」虞翻不能對。"], "intro": "本篇節選自《三國演義》第四十三回「諸葛亮舌戰群儒 魯子敬力排眾議」，版本據人民文學出版社排印本。《三國演義》是一部文學價值很高的長篇演史小說，作者羅貫中依據陳壽《三國志》、裴松之《三國志注》及平話，從東漢靈帝中平元年（一八四）黃巾起義開始，", "url": "https://www.classicalchineseliterature.org/article.php?article=%E4%B8%89%E5%9C%8B%E5%BF%97%E6%BC%94%E7%BE%A9%E3%83%BB%E8%AB%B8%E8%91%9B%E4%BA%AE%E8%88%8C%E6%88%B0%E7%BE%A3%E5%84%92"}, {"title": "楊修之死", "author": "羅貫中", "period": "明", "form": "小說", "theme": "邊塞豪放", "mood": "spring_breeze", "lines": ["操屯兵日久，欲要進兵，又被馬超拒守；欲收兵回，又恐被蜀兵恥笑，心中猶豫不決。適庖官進雞湯，操見碗中有雞肋，因而有感於懷。正沈吟間，夏侯惇入帳，稟請夜間口號，操隨口曰︰「雞肋，雞肋。」惇傳令眾官，都稱「雞肋」。", "行軍主簿楊修見傳「雞肋」二字，便教隨行軍士，各收拾行裝，準備歸程。有人報知夏侯惇，惇大驚，遂請楊修至帳中，問曰︰「公何收拾行裝？」修曰︰「以今夜號令，便知魏王不日將退兵歸也。雞肋者，食之無肉，棄之有味。今進不能勝，退恐人笑，在此無益，不如早歸。來日魏王必班師矣，故先收拾行裝，免得臨時慌亂。」夏侯惇曰︰「公真知魏王肺腑也。」遂亦收拾行裝，於是寨中諸將，無不準備歸計。", "當夜曹操心亂，不能穩睡，遂手提鋼斧，遶寨私行。只見夏侯惇寨內軍士，各準備行裝。操大驚，急回帳召惇問其故。惇曰︰「主簿楊德祖，先知大王欲歸之意。」操喚楊修問之，修以雞肋之意對。操大怒曰︰「汝怎敢造言亂我軍心！」喝刀斧手推出斬之，將首級號令於轅門外。", "原來楊修為人，恃才放曠，數犯曹操之忌。操嘗造花園一所，造成，操往觀之，不置褒貶，只取筆於門上書一「活」字而去，人皆不曉其意。修曰︰「門內添『活』字，乃『闊』字也，丞相嫌園門闊耳。」於是再築牆圍，改造停當，又請操觀之。操大喜，問曰︰「誰知吾意？」左右曰︰「楊修也。」操雖稱美，心甚忌之。", "又一日，塞北送酥一盒至，操自寫「一合酥」三字於盒上，置之案頭。修入見之，竟取匙與眾分食訖。操問其故，修答曰︰「盒上明書『一人一口酥』，豈敢違丞相之命乎？」操雖喜而笑，心惡之。", "操恐人暗中謀害己身，常吩咐左右︰「吾夢中好殺人，凡吾睡著，汝等切勿近前。」一日，晝寢帳中，落被於地，一近侍慌取覆蓋，操躍起拔劍斬之，復上牀睡，半晌而起，佯驚問︰「何人殺吾近侍？」眾以實對，操痛哭，命厚葬之。人皆以為操果夢中殺人，惟修知其意，臨葬時指而歎曰︰「丞相非在夢中，君乃在夢中耳。」操聞而愈惡之。", "操第三子曹植，愛修之才，常邀修談論，終夜不息。操與眾商議，欲立植為世子，曹丕知之，密請朝歌長吳質入內府商議。因恐有人知覺，乃用大簏藏吳質於中，只說是絹疋在內，載入府中。修知其事，逕來告操，操令人於丕府門伺察之。丕慌告吳質，質曰︰「無憂也，明日用大簏裝絹，再入以惑之。」丕如其言，以大簏載絹入，使者搜看簏中，果絹也，回報曹操，操因疑修譖害曹丕，愈惡之。", "操欲試曹丕、曹植之才幹，一日令各出鄴城門，卻密使人吩咐門吏，令勿放出。曹丕先至，門吏阻之，丕只得退回。植聞之，問計於修，修曰︰「君奉王命而出，如有阻當者，竟斬之可也。」植然其言。及至門，門吏阻住。植叱曰︰「吾奉王命，誰敢阻當！」立斬之。於是曹操以植為能。後有人告操曰︰「此乃楊修之所教也。」操大怒，因此亦不喜植。", "修又嘗為曹植作答教十餘條，但操有問，植即依條答之。操每以軍國之事問植，植對答如流，操心中甚疑。後曹丕暗買植左右，偷答教來告操，操見了，大怒曰︰「匹夫安敢欺我耶！」此時已有殺修之心，今乃借惑亂軍心之罪殺之。"], "quote": ["操屯兵日久，欲要進兵，又被馬超拒守；欲收兵回，又恐被蜀兵恥笑，心中猶豫不決。適庖官進雞湯，操見碗中有雞肋，因而有感於懷。正沈吟間，夏侯惇入帳，稟請夜間口號，操隨口曰︰「雞肋，雞肋。」惇傳令眾官，都稱「雞肋」。", "行軍主簿楊修見傳「雞肋」二字，便教隨行軍士，各收拾行裝，準備歸程。有人報知夏侯惇，惇大驚，遂請楊修至帳中，問曰︰「公何收拾行裝？」修曰︰「以今夜號令，便知魏王不日將退兵歸也。雞肋者，食之無肉，棄之有味。今進不能勝，退恐人笑，在此無益，不如早歸。來日魏王必班師矣，故先收拾行裝，免得臨時慌亂。」夏侯惇曰︰「公真知魏王肺腑也。」遂亦收拾行裝，於是寨中諸將，無不準備歸計。", "當夜曹操心亂，不能穩睡，遂手提鋼斧，遶寨私行。只見夏侯惇寨內軍士，各準備行裝。操大驚，急回帳召惇問其故。惇曰︰「主簿楊德祖，先知大王欲歸之意。」操喚楊修問之，修以雞肋之意對。操大怒曰︰「汝怎敢造言亂我軍心！」喝刀斧手推出斬之，將首級號令於轅門外。", "原來楊修為人，恃才放曠，數犯曹操之忌。操嘗造花園一所，造成，操往觀之，不置褒貶，只取筆於門上書一「活」字而去，人皆不曉其意。修曰︰「門內添『活』字，乃『闊』字也，丞相嫌園門闊耳。」於是再築牆圍，改造停當，又請操觀之。操大喜，問曰︰「誰知吾意？」左右曰︰「楊修也。」操雖稱美，心甚忌之。"], "intro": "《三國演義》屬於明清流行的章回體小說。此類小說是由宋元時期市井藝人的講史話本演變而來。當時習慣將一大段歷史故事拆分為若干部分，分別講述，每一回講述均承上啓下。後來將說話轉換成文字，便成了章回體小說。如今我們仍能在一些章回體小說中看見「話說」", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%A5%8A%E4%BF%AE%E4%B9%8B%E6%AD%BB"}, {"title": "桃花扇・餘韻", "author": "孔尚任", "period": "清", "form": "曲", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["〔西江月〕（淨扮樵子挑擔上）放目蒼崖萬丈，拂頭紅樹千枝；雲深猛虎出無時，也避人間弓矢。建業城啼夜鬼，維揚井貯秋屍；樵夫剩得命如絲，滿肚南朝野史。在下蘇崑生，自從乙酉年同香君到山，一住三載，俺就不曾回家，往來牛首、棲霞，採樵度日。誰想柳敬亭與俺同志，買隻小船，也在此捕魚為業。且喜山深樹老，江闊人稀；每日相逢，便把斧頭敲着船頭，浩浩落落，儘俺歌唱，好不快活。今日柴擔早歇，專等他來促膝閒話，怎的還不見到。（歇擔盹睡介）（丑扮漁翁搖船上）年年垂釣鬢如銀，愛此江山勝富春；歌舞叢中征戰裏，漁翁都是過來人。俺柳敬亭送侯朝宗修道之後，就在這龍潭江畔，捕魚三載，把些興亡舊事，付之風月閒談。今值秋雨新晴，江光似練，正好尋蘇崑生飲酒談心。（指介）你看，他早已醉倒在地，待我上岸，喚他醒來。（作上岸介）（呼介）蘇崑生。（淨醒介）大哥果然來了。（丑拱介）賢弟偏杯呀！（淨）柴不曾賣，那得酒來。（丑）愚兄也沒賣魚，都是空囊，怎麼處？（淨）有了，有了！你輸水，我輸柴，大家煮茗清談罷。（副末扮老贊禮，提絃携壺上）江山江山，一忙一閒，誰贏誰輸，兩鬢皆斑。（見介）原來是柳、蘇兩位老哥。（淨、丑拱介）老相公怎得到此？（副末）老夫住在燕子磯邊，今乃戊子年九月十七日，是福德星君降生之辰；我同些山中社友，到福德神祠祭賽已畢，路過此間。（淨）為何挾着絃子，提着酒壺？（副末）見笑見笑！老夫編了幾句神絃歌，名曰《問蒼天》。今日彈唱樂神，社散之時，分得這瓶福酒。恰好遇着二位，就同飲三杯罷。（丑）怎好取擾。（副末）這叫做「有福同享」。（淨、丑）好，好！（同坐飲介）（淨）何不把神絃歌領略一回？（副末）使得！老夫的心事，正要請教二位哩。（彈絃唱巫腔）（淨、丑拍手襯介）", "〔問蒼天〕新曆數，順治朝，歲在戊子；九月秋，十七日，嘉會良時。擊神鼓，揚靈旗，鄉鄰賽社；老逸民，剃白髮，也到叢祠。椒作棟，桂為楣，唐修晉建；碧和金，丹間粉，畫壁精奇。貌赫赫，氣揚揚，福德名位；山之珍，海之寶，總掌無遺。超祖禰，邁君師，千人上壽；焚郁蘭，奠清醑，奪戶爭墀。草笠底，有一人，掀鬚長嘆︰貧者貧，富者富，造命奚為？我與爾，較生辰，同月同日；囊無錢，竃斷火，不啻乞兒。六十歲，花甲週，桑榆暮矣；亂離人，太平犬，未有亨期。稱玉斝，坐瓊筵，爾餐我看；誰為靈，誰為蠢，貴賤失宜。臣稽首，叫九閽，開聾啓瞶；宣命司，檢祿籍，何故差池。金闕遠，紫宸高，蒼天夢夢；迎神來，送神去，輿馬風馳。歌舞罷，雞豚收，須臾社散；倚枯槐，對斜日，獨自凝思。濁享富，清享名，或分兩例；內才多，外財少，應不同規。熱似火，福德君，庸人父母；冷如冰，文昌帝，秀士宗師。神有短，聖有虧，誰能足願；地難填，天難補，造化如斯。釋盡了，胸中愁，欣欣微笑；江自流，雲自卷，我又何疑。", "（唱完放絃介）出醜之極。（淨）妙絕！逼真《離騷》、《九歌》了。（丑）失敬，失敬！不知老相公竟是財神一轉哩。（副末讓介）請乾此酒。（淨咂舌介）這寡酒好難吃也。（丑）愚兄倒有些下酒之物。（淨）是什麼東西？（丑）請猜一猜。（淨）你的東西，不過是些魚鱉蝦蟹。（丑搖頭介）猜不着，猜不着。（淨）還有什麼異味？（丑指口介）是我的舌頭。（副末）你的舌頭，你自下酒，如何讓客。（丑笑介）你不曉得，古人以《漢書》下酒；這舌頭會說《漢書》，豈非下酒之物。（淨取酒斟介）我替老哥斟酒，老哥就把《漢書》說來。（副末）妙妙！只恐菜多酒少了。（丑）既然《漢書》太長，有我新編的一首彈詞，叫做《秣陵秋》，唱來下酒罷。（副末）就是俺南京的近事麼？（丑）便是！（淨）這都是俺們耳聞眼見的，你若說差了，我要罰的。（丑）包管你不差。（丑彈絃介）六代興亡，幾點清彈千古慨；半生湖海，一聲高唱萬山驚。（照盲女彈詞唱介）", "〔秣陵秋〕陳隋烟月恨茫茫，井帶胭脂土帶香；駘蕩柳綿沾客鬢，叮嚀鶯舌惱人腸。中興朝市繁華續，遺孽兒孫氣焰張；只勸樓臺追後主，不愁弓矢下殘唐。蛾眉越女才承選，燕子吳歈早擅場，力士簽名搜笛步，龜年協律奉椒房。西崑詞賦新溫李，烏巷冠裳舊謝王；院院宮妝金翠鏡，朝朝楚夢雨雲床。五侯閫外空狼燧，二水洲邊自雀舫；指馬誰攻秦相詐，入林都畏阮生狂。春燈已錯從頭認，社黨重鈎無縫藏；借手殺讎長樂老，脅肩媚貴半閒堂。龍鍾閣部啼梅嶺，跋扈將軍譟武昌；九曲河流晴喚渡，千尋江岸夜移防。瓊花劫到雕欄損，玉樹歌終畫殿涼；滄海迷家龍寂寞，風塵失伴鳳徬徨。青衣啣璧何年返，碧血濺沙此地亡；南內湯池仍蔓草，東陵輦路又斜陽。全開鎖鑰淮揚泗，難整乾坤左史黃。建帝飄零烈帝慘，英宗困頓武宗荒；那知還有福王一，臨去秋波淚數行。", "（淨）妙妙！果然一些不差。（副末）雖是幾句彈詞，竟似吳梅村一首長歌。（淨）老哥學問大進，該敬一杯。（斟酒介）（丑）倒叫我吃寡酒了。（淨）愚弟也有些須下酒之物。（丑）你的東西，一定是山殽野蔌了。（淨）不是，不是。昨日南京賣柴，特地帶來的。（丑）取來共享罷。（淨指口介）也是舌頭。（副末）怎的也是舌頭？（淨）不瞞二位說，我三年沒到南京，忽然高興，進城賣柴。路過孝陵，見那寶城享殿，成了芻牧之場。（丑）呵呀呀！那皇城如何？（淨）那皇城牆倒宮塌，滿地蒿萊了。（副末掩淚介）不料光景至此。（淨）俺又一直走到秦淮，立了半晌，竟沒一個人影兒。（丑）那長橋舊院，是咱們熟遊之地，你也該去瞧瞧。（淨）怎的沒瞧，長橋已無片板，舊院剩了一堆瓦礫。（丑搥胸介）咳！慟死俺也。（淨）那時疾忙回首，一路傷心；編成一套北曲，名為《哀江南》。待我唱來！（敲板唱弋陽腔介）俺樵夫呵！", "〔哀江南〕〔北新水令〕山松野草帶花挑，猛抬頭秣陵重到。殘軍留廢壘，瘦馬臥空壕；村郭蕭條，城對着夕陽道。", "〔駐馬聽〕野火頻燒，護墓長楸多半焦。山羊羣跑，守陵阿監幾時逃。鴿翎蝠糞滿堂拋，枯枝敗葉當階罩；誰祭掃，牧兒打碎龍碑帽。", "〔沉醉東風〕橫白玉八根柱倒，墮紅泥半堵牆高，碎琉璃瓦片多，爛翡翠窗櫺少，舞丹墀燕雀常朝，直入宮門一路蒿，住幾個乞兒餓殍。", "〔折桂令〕問秦淮舊日窗寮，破紙迎風，壞檻當潮，目斷魂消。當年粉黛，何處笙簫。罷燈船端陽不鬧，收酒旗重九無聊。白鳥飄飄，綠水滔滔，嫩黃花有些蝶飛，新紅葉無個人瞧。", "〔沽美酒〕你記得跨青谿半里橋，舊紅板沒一條。秋水長天人過少，冷清清的落照，剩一樹柳彎腰。", "〔太平令〕行到那舊院門，何用輕敲，也不怕小犬哰哰。無非是枯井頹巢，不過些磚苔砌草。手種的花條柳梢，儘意兒採樵；這黑灰是誰家廚？", "〔離亭宴帶歇指煞〕俺曾見金陵玉殿鶯啼曉，秦淮水榭花開早，誰知道容易冰消。眼看他起朱樓，眼看他宴賓客，眼看他樓塌了。這青苔碧瓦堆，俺曾睡風流覺，將五十年興亡看飽。那烏衣巷不姓王，莫愁湖鬼夜哭，鳳凰臺棲梟鳥。殘山夢最真，舊境丟難掉，不信這輿圖換稿。謅一套哀江南，放悲聲唱到老。"], "quote": ["〔西江月〕（淨扮樵子挑擔上）放目蒼崖萬丈，拂頭紅樹千枝；雲深猛虎出無時，也避人間弓矢。建業城啼夜鬼，維揚井貯秋屍；樵夫剩得命如絲，滿肚南朝野史。在下蘇崑生，自從乙酉年同香君到山，一住三載，俺就不曾回家，往來牛首、棲霞，採樵度日。誰想柳敬亭與俺同志，買隻小船，也在此捕魚為業。且喜山深樹老，江闊人稀；每日相逢，便把斧頭敲着船頭，浩浩落落，儘俺歌唱，好不快活。今日柴擔早歇，專等他來促膝閒話，怎的還不見到。（歇擔盹睡介）（丑扮漁翁搖船上）年年垂釣鬢如銀，愛此江山勝富春；歌舞叢中征戰裏，漁翁都是過來人。俺柳敬亭送侯朝宗修道之後，就在這龍潭江畔，捕魚三載，把些興亡舊事，付之風月閒談。今值秋雨新晴，江光似練，正好尋蘇崑生飲酒談心。（指介）你看，他早已醉倒在地，待我上岸，喚他醒來。（作上岸介）（呼介）蘇崑生。（淨醒介）大哥果然來了。（丑拱介）賢弟偏杯呀！（淨）柴不曾賣，那得酒來。（丑）愚兄也沒賣魚，都是空囊，怎麼處？（淨）有了，有了！你輸水，我輸柴，大家煮茗清談罷。（副末扮老贊禮，提絃携壺上）江山江山，一忙一閒，誰贏誰輸，兩鬢皆斑。（見介）原來是柳、蘇兩位老哥。（淨、丑拱介）老相公怎得到此？（副末）老夫住在燕子磯邊，今乃戊子年九月十七日，是福德星君降生之辰；我同些山中社友，到福德神祠祭賽已畢，路過此間。（淨）為何挾着絃子，提着酒壺？（副末）見笑見笑！老夫編了幾句神絃歌，名曰《問蒼天》。今日彈唱樂神，社散之時，分得這瓶福酒。恰好遇着二位，就同飲三杯罷。（丑）怎好取擾。（副末）這叫做「有福同享」。（淨、丑）好，好！（同坐飲介）（淨）何不把神絃歌領略一回？（副末）使得！老夫的心事，正要請教二位哩。（彈絃唱巫腔）（淨、丑拍手襯介）", "〔問蒼天〕新曆數，順治朝，歲在戊子；九月秋，十七日，嘉會良時。擊神鼓，揚靈旗，鄉鄰賽社；老逸民，剃白髮，也到叢祠。椒作棟，桂為楣，唐修晉建；碧和金，丹間粉，畫壁精奇。貌赫赫，氣揚揚，福德名位；山之珍，海之寶，總掌無遺。超祖禰，邁君師，千人上壽；焚郁蘭，奠清醑，奪戶爭墀。草笠底，有一人，掀鬚長嘆︰貧者貧，富者富，造命奚為？我與爾，較生辰，同月同日；囊無錢，竃斷火，不啻乞兒。六十歲，花甲週，桑榆暮矣；亂離人，太平犬，未有亨期。稱玉斝，坐瓊筵，爾餐我看；誰為靈，誰為蠢，貴賤失宜。臣稽首，叫九閽，開聾啓瞶；宣命司，檢祿籍，何故差池。金闕遠，紫宸高，蒼天夢夢；迎神來，送神去，輿馬風馳。歌舞罷，雞豚收，須臾社散；倚枯槐，對斜日，獨自凝思。濁享富，清享名，或分兩例；內才多，外財少，應不同規。熱似火，福德君，庸人父母；冷如冰，文昌帝，秀士宗師。神有短，聖有虧，誰能足願；地難填，天難補，造化如斯。釋盡了，胸中愁，欣欣微笑；江自流，雲自卷，我又何疑。", "（唱完放絃介）出醜之極。（淨）妙絕！逼真《離騷》、《九歌》了。（丑）失敬，失敬！不知老相公竟是財神一轉哩。（副末讓介）請乾此酒。（淨咂舌介）這寡酒好難吃也。（丑）愚兄倒有些下酒之物。（淨）是什麼東西？（丑）請猜一猜。（淨）你的東西，不過是些魚鱉蝦蟹。（丑搖頭介）猜不着，猜不着。（淨）還有什麼異味？（丑指口介）是我的舌頭。（副末）你的舌頭，你自下酒，如何讓客。（丑笑介）你不曉得，古人以《漢書》下酒；這舌頭會說《漢書》，豈非下酒之物。（淨取酒斟介）我替老哥斟酒，老哥就把《漢書》說來。（副末）妙妙！只恐菜多酒少了。（丑）既然《漢書》太長，有我新編的一首彈詞，叫做《秣陵秋》，唱來下酒罷。（副末）就是俺南京的近事麼？（丑）便是！（淨）這都是俺們耳聞眼見的，你若說差了，我要罰的。（丑）包管你不差。（丑彈絃介）六代興亡，幾點清彈千古慨；半生湖海，一聲高唱萬山驚。（照盲女彈詞唱介）", "〔秣陵秋〕陳隋烟月恨茫茫，井帶胭脂土帶香；駘蕩柳綿沾客鬢，叮嚀鶯舌惱人腸。中興朝市繁華續，遺孽兒孫氣焰張；只勸樓臺追後主，不愁弓矢下殘唐。蛾眉越女才承選，燕子吳歈早擅場，力士簽名搜笛步，龜年協律奉椒房。西崑詞賦新溫李，烏巷冠裳舊謝王；院院宮妝金翠鏡，朝朝楚夢雨雲床。五侯閫外空狼燧，二水洲邊自雀舫；指馬誰攻秦相詐，入林都畏阮生狂。春燈已錯從頭認，社黨重鈎無縫藏；借手殺讎長樂老，脅肩媚貴半閒堂。龍鍾閣部啼梅嶺，跋扈將軍譟武昌；九曲河流晴喚渡，千尋江岸夜移防。瓊花劫到雕欄損，玉樹歌終畫殿涼；滄海迷家龍寂寞，風塵失伴鳳徬徨。青衣啣璧何年返，碧血濺沙此地亡；南內湯池仍蔓草，東陵輦路又斜陽。全開鎖鑰淮揚泗，難整乾坤左史黃。建帝飄零烈帝慘，英宗困頓武宗荒；那知還有福王一，臨去秋波淚數行。"], "intro": "本課選自《桃花扇》續四十齣《餘韻》，是全劇的最後一齣，版本據人民文學出版社排印本。《桃花扇》是清代傳奇的佳作。全劇以明末名士侯方域和秦淮名妓李香君的愛情故事為骨幹，寫南明亡國的史實。「桃花扇」劇名的由來，出自李香君力拒田仰逼婚時，以頭撞向屋", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%A1%83%E8%8A%B1%E6%89%87%E3%83%BB%E9%A4%98%E9%9F%BB"}, {"title": "左忠毅公軼事", "author": "方苞", "period": "清", "form": "文", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["先君子嘗言︰鄉先輩左忠毅公視學京畿，一日，風雪嚴寒，從數騎出；微行入古寺廡下。一生伏案臥，文方成草；公閱畢，即解貂覆生，為掩戶。叩之寺僧，則史公可法也。", "及試，吏呼名至史公，公瞿然注視。呈卷，即面署第一；召入，使拜夫人，曰︰「吾諸兒碌碌，他日繼吾志事，惟此生耳。」", "及左公下廠獄，史朝夕獄門外。逆閹防伺甚嚴，雖家僕不得近。久之，聞左公被炮烙，旦夕且死；持五十金，涕泣謀於禁卒，卒感焉。", "一日，使史更敝衣草屨，背筐，手長鑱，為除不潔者；引入，微指左公處，則席地倚牆而坐，面額焦爛不可辨，左膝以下，筋骨盡脫矣。", "史前跪，抱公膝而嗚咽。公辨其聲，而目不可開，乃奮臂以指撥眥，目光如炬，怒曰︰「庸奴！此何地也，而汝來前！國家之事，糜爛至此。老夫已矣，汝復輕身而昧大義，天下事誰可支拄者？不速去，無俟姦人構陷，吾今即撲殺汝。」", "因摸地上刑械，作投擊勢。史噤不敢發聲，趨而出。後常流涕述其事以語人曰︰「吾師肺肝，皆鐵石所鑄造也。」", "崇禎末，流賊張獻忠出沒蘄、黃、潛、桐間，史公以鳳廬道奉檄守禦。每有警，輒數月不就寢，使將士更休，而自坐幄幕外；擇健卒十人，令二人蹲踞而背倚之，漏鼓移則番代。", "每寒夜起立，振衣裳，甲上冰霜迸落，鏗然有聲。或勸以少休，公曰︰「吾上恐負朝廷，下恐愧吾師也。」", "史公治兵，往來桐城，必躬造左公第，候太公、太母起居，拜夫人於堂上。", "余宗老塗山，左公甥也，與先君子善，謂獄中語乃親得之於史公云。"], "quote": ["先君子嘗言︰鄉先輩左忠毅公視學京畿，一日，風雪嚴寒，從數騎出；微行入古寺廡下。一生伏案臥，文方成草；公閱畢，即解貂覆生，為掩戶。叩之寺僧，則史公可法也。", "及試，吏呼名至史公，公瞿然注視。呈卷，即面署第一；召入，使拜夫人，曰︰「吾諸兒碌碌，他日繼吾志事，惟此生耳。」", "及左公下廠獄，史朝夕獄門外。逆閹防伺甚嚴，雖家僕不得近。久之，聞左公被炮烙，旦夕且死；持五十金，涕泣謀於禁卒，卒感焉。", "一日，使史更敝衣草屨，背筐，手長鑱，為除不潔者；引入，微指左公處，則席地倚牆而坐，面額焦爛不可辨，左膝以下，筋骨盡脫矣。"], "intro": "本篇選自《望溪文集》。左忠毅公，即左光斗（公元一五七五──一六二五），字遺直，號浮邱，明朝安徽桐城人。明神宗萬曆年間考取進士，做了「中書舍人」，後升任「御史」；敢言直諫，不畏權要。明光宗（朱常洛）死了以後，他和楊漣協力排除了弄權的宦官，扶保", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B7%A6%E5%BF%A0%E6%AF%85%E5%85%AC%E8%BB%BC%E4%BA%8B"}, {"title": "致史可法書", "author": "多爾袞", "period": "清", "form": "文", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["予向在瀋陽，即知燕京物望，咸推司馬。後入關破賊，得與都人士相接，識介弟於清班；曾託其手泐平安，拳致衷曲，未審以何時得達。", "比聞道路紛紛，多謂金陵有自立者。夫君父之讎，不共戴天。春秋之義︰有賊不討，則故君不得書葬，新君不得書即位；所以防亂臣賊子，法至嚴也。闖賊李自成，稱兵犯闕，荼毒君親；中國臣民，不聞加遺一矢。平西王吳三桂，界在東陲，獨效包胥之哭。", "朝廷感其忠義，念累世之夙好，棄近日之小嫌，爰整貔貅，驅除梟獍。入京之日，首崇懷宗帝后諡號，卜葬山陵，悉如典禮；親郡王將軍以下，一仍故封，不加改削；勳戚文武諸臣，咸在朝列，恩禮有加；耕市不驚，秋毫無擾。", "方擬秋高氣爽，遣將西征，傳檄江南，連兵河朔，陳師鞠旅，戮力同心，報乃君國之仇，彰我朝廷之德。豈意南州諸君子，苟安旦夕，弗審事機，聊慕虛名，頓妄實害。予甚惑之！", "國家之撫定燕京，乃得之於闖賊，非取之於明朝也。賊燬明朝之廟主，辱及先人；我國家不憚征繕之勞，悉索敝賦，代為雪恥。孝子仁人，當如何感恩圖報！茲乃乘逆寇稽誅，王師暫息，遂欲雄據江南，坐享漁人之利。揆諸情理，豈可謂平！將以為天塹不能飛渡，投鞭不足斷流耶？", "夫闖賊但為明朝祟耳，未嘗得罪於我國家也。徒以薄海同仇，特申大義。今若擁號稱尊，便是天有二日，儼為敵國。予將簡西行之銳卒，轉旆東征；且擬釋彼重誅，命為前導。夫以中華全力，受困潢池，而欲以江左一隅，兼支大國。勝負之數，無待蓍龜矣！", "予聞「君子之愛人也以德，細人則以姑息」。諸君子果識時知命，篤念故主，厚愛賢王，宜勸令削號歸藩，永綏福祿。朝廷當待以虞賓，統承禮物；帶礪山河，位在諸王侯上。庶不負朝廷伸義討賊，興滅繼絕之初心。至南州羣彥，翩然來儀，則爾公爾侯，列爵分土，有平西王之典例在。惟執事實利圖之！", "輓近士大夫，好高樹名義而不顧國家之急。每有大事，輒同築舍。昔宋人議論未定，兵已渡河，可為殷鑒。先生領袖名流，主持至計，必能深惟終始，寧忍隨俗浮沈？取舍從違，應早審定。兵行在即，可西可東。南國安危，在此一舉。願諸君子同以討賊為心，毋貪一身瞬息之榮，而重故國無窮之禍，為亂臣賊子所笑；余實有厚望焉！", "記有之︰「惟善人能受盡言。」敢布腹心，佇聞明教。江天在望，延跂為勞。書不宣意。"], "quote": ["予向在瀋陽，即知燕京物望，咸推司馬。後入關破賊，得與都人士相接，識介弟於清班；曾託其手泐平安，拳致衷曲，未審以何時得達。", "比聞道路紛紛，多謂金陵有自立者。夫君父之讎，不共戴天。春秋之義︰有賊不討，則故君不得書葬，新君不得書即位；所以防亂臣賊子，法至嚴也。闖賊李自成，稱兵犯闕，荼毒君親；中國臣民，不聞加遺一矢。平西王吳三桂，界在東陲，獨效包胥之哭。", "朝廷感其忠義，念累世之夙好，棄近日之小嫌，爰整貔貅，驅除梟獍。入京之日，首崇懷宗帝后諡號，卜葬山陵，悉如典禮；親郡王將軍以下，一仍故封，不加改削；勳戚文武諸臣，咸在朝列，恩禮有加；耕市不驚，秋毫無擾。", "方擬秋高氣爽，遣將西征，傳檄江南，連兵河朔，陳師鞠旅，戮力同心，報乃君國之仇，彰我朝廷之德。豈意南州諸君子，苟安旦夕，弗審事機，聊慕虛名，頓妄實害。予甚惑之！"], "intro": "明朝亡國前夕，政治腐敗，民變蠭起；崇禎十七年（公元一六四四）三月，流寇李自成攻陷北京，崇禎帝在煤山懸樹自縊。北京既陷，明朝就改在南京建都，六部衙門史可法（兵部尚書）、張慎言、呂大器等，打算迎立潞王常淓繼承皇統，太監魏忠賢的黨羽馬士英（鳳陽總", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%87%B4%E5%8F%B2%E5%8F%AF%E6%B3%95%E6%9B%B8"}, {"title": "桂殿秋（思往事）", "author": "朱彝尊", "period": "清", "form": "詞", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["思往事，渡江干，青蛾低映越山看。共眠一舸聽秋雨，小簟輕衾各自寒。"], "quote": ["思往事，渡江干，青蛾低映越山看。共眠一舸聽秋雨，小簟輕衾各自寒。"], "intro": "朱彝尊《桂殿秋》（思往事）選自《曝書亭集》卷二十四。《桂殿秋》是詞牌名。作者與其妻妹馮壽常有深情，這首詞記述作者與馮氏一次江上同舟卻無法親近的苦況。此詞雖是言情之作，卻寫得清秀脫俗。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%A1%82%E6%AE%BF%E7%A7%8B%EF%BC%88%E6%80%9D%E5%BE%80%E4%BA%8B%EF%BC%89"}, {"title": "解珮令（十年磨劍）", "author": "朱彝尊", "period": "清", "form": "詞", "theme": "邊塞豪放", "mood": "vast_river", "lines": ["十年磨劍，五陵結客，把平生、涕淚都飄盡。老去填詞，一半是、空中傳恨。幾曾圍、燕釵蟬鬢？", "不師秦七，不師黃九，倚新聲、玉田差近。落拓江湖，且分付、歌筵紅粉。料封侯、白頭無分！"], "quote": ["十年磨劍，五陵結客，把平生、涕淚都飄盡。老去填詞，一半是、空中傳恨。幾曾圍、燕釵蟬鬢？", "不師秦七，不師黃九，倚新聲、玉田差近。落拓江湖，且分付、歌筵紅粉。料封侯、白頭無分！"], "intro": "解珮令是詞牌。本篇副題作「自題詞集」，古人多在作品集有「題詞」，或邀人題詞，或自題，所指詞集是詞人自己的《江湖載酒集》。朱彝尊詞集尚有《靜志居琴趣》、《茶煙閣體物集》、《蕃錦集》等，合稱《曝書亭詞》。從康熙三年（公元1664）到十七年（公元", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A7%A3%E7%8F%AE%E4%BB%A4%EF%BC%88%E5%8D%81%E5%B9%B4%E7%A3%A8%E5%8A%8D%EF%BC%89"}, {"title": "圓圓曲", "author": "吳偉業", "period": "清", "form": "詩", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["鼎湖當日棄人間，破敵收京下玉關。慟哭六軍俱縞素，衝冠一怒為紅顏。紅顏流落非吾戀，逆賊天亡自荒讌。電掃黃巾定黑山，哭罷君親再相見。", "相見初經田竇家，侯門歌舞出如花。許將戚里空侯伎，等取將軍油壁車。家本姑蘇浣花里，圓圓小字嬌羅綺。夢向夫差苑裏遊，宮娥擁入君王起。前身合是采蓮人，門前一片橫塘水。", "橫塘雙槳去如飛，何處豪家強載歸？此際豈知非薄命，此時只有淚沾衣。薰天意氣連宮掖，明眸皓齒無人惜。奪歸永巷閉良家，教就新聲傾坐客。", "坐客飛觴紅日暮，一曲哀絃向誰訴？白晳通侯最少年，揀取花枝屢回顧。早攜嬌鳥出樊籠，待得銀河幾時渡？恨殺軍書底死催，苦留後約將人誤。", "相約恩深相見難，一朝蟻賊滿長安。可憐思婦樓頭柳，認作天邊粉絮看。徧索綠珠圍內第，強呼絳樹出雕闌。若非壯士全師勝，爭得蛾眉匹馬還？", "蛾眉馬上傳呼進，雲鬟不整驚魂定。蠟炬迎來在戰場，啼糚滿面殘紅印。專征簫鼓向秦川，金牛道上車千乘。斜谷雲深起畫樓，散關月落開糚鏡。", "傳來消息滿江鄉，烏桕紅經十度霜。教曲妓師憐尚在，浣紗女伴憶同行。舊巢共是銜泥燕，飛上枝頭變鳳皇。長向尊前悲老大，有人夫壻擅侯王。", "當時祇受聲名累，貴戚名豪競延致。一斛珠連萬斛愁，關山漂泊腰支細。錯怨狂風颺落花，無邊春色來天地。", "嘗聞傾國與傾城，翻使周郎受重名。妻子豈應關大計，英雄無奈是多情。全家白骨成灰土，一代紅糚照汗青。", "君不見館娃初起鴛鴦宿，越女如花看不足。香逕塵生鳥自啼，屧廊人去苔空綠。換羽移宮萬里愁，珠歌翠舞古梁州。為君別唱吳宮曲，漢水東南日夜流！"], "quote": ["鼎湖當日棄人間，破敵收京下玉關。慟哭六軍俱縞素，衝冠一怒為紅顏。紅顏流落非吾戀，逆賊天亡自荒讌。電掃黃巾定黑山，哭罷君親再相見。", "相見初經田竇家，侯門歌舞出如花。許將戚里空侯伎，等取將軍油壁車。家本姑蘇浣花里，圓圓小字嬌羅綺。夢向夫差苑裏遊，宮娥擁入君王起。前身合是采蓮人，門前一片橫塘水。", "橫塘雙槳去如飛，何處豪家強載歸？此際豈知非薄命，此時只有淚沾衣。薰天意氣連宮掖，明眸皓齒無人惜。奪歸永巷閉良家，教就新聲傾坐客。", "坐客飛觴紅日暮，一曲哀絃向誰訴？白晳通侯最少年，揀取花枝屢回顧。早攜嬌鳥出樊籠，待得銀河幾時渡？恨殺軍書底死催，苦留後約將人誤。"], "intro": "《圓圓曲》中的「圓圓」指陳圓圓，講述名妓陳圓圓的長篇敍事詩，故稱《圓圓曲》。曲，名稱源於古樂府歌謠，古詩中一種體裁。 本篇是以明朝末年，名妓陳圓圓與名將吳三桂悲歡離合故事作敍事主綫，寄寓國家興亡之嘆。「甲申之變」後，吳偉業退隱鄉里，時已自南", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%9C%93%E5%9C%93%E6%9B%B2"}, {"title": "懷古兼弔侯朝宗", "author": "吳偉業", "period": "清", "form": "詩", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["河洛風塵萬里昏，百年心事向夷門。", "氣傾市俠收奇用，策動宮娥報舊恩。", "多見攝衣稱上客，幾人刎頸送王孫？", "死生總負侯嬴諾，欲滴椒漿淚滿樽。"], "quote": ["河洛風塵萬里昏，百年心事向夷門。", "氣傾市俠收奇用，策動宮娥報舊恩。", "多見攝衣稱上客，幾人刎頸送王孫？", "死生總負侯嬴諾，欲滴椒漿淚滿樽。"], "intro": "吳偉業嘗以晚年失節為生平恨事，每流露於詩文之中；曾作書自敘事略道：「吾一生遭際，萬事憂危，無一刻不歷艱難，無一境不嘗辛苦，實為天下大苦人。吾死後，斂以僧裝，葬吾於鄧尉、靈巖相近，墓前立一圓石，題曰『詩人吳梅村之墓』足矣！」從這些話中，可以想", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%87%B7%E5%8F%A4%E5%85%BC%E5%BC%94%E4%BE%AF%E6%9C%9D%E5%AE%97"}, {"title": "儒林外史・范進中舉", "author": "吳敬梓", "period": "清", "form": "小說", "theme": "田園幽居", "mood": "snow_winter", "lines": ["這周學道雖也請了幾個看文章的相公，卻自心裏想道︰「我在這裏面吃苦久了，如今自己當權，須要把卷子都要細細看過，不可聽着幕客，屈了真才。」主意定了，到廣州上了任。次日，行香掛牌。先考了兩場生員。第三場是南海、番禺兩縣童生。周學道坐在堂上，見那些童生紛紛進來︰也有小的，也有老的，儀表端正的，獐頭鼠目的，衣冠齊楚的，襤褸破爛的……落後點進一個童生來，面黃飢瘦，花白鬍鬚，頭上戴一頂破氈帽。廣東雖是地氣溫暖，這時已是十二月上旬，那童生還穿着麻布直裰，凍得乞乞縮縮，接了卷子，下去歸號。周學道看在心裏，封門進去。出來放頭牌的時節，坐在上面，只見那穿麻布的童生上來交卷。那衣服因是朽爛了，在號裏又扯破了幾塊。周學道看看自己身上，緋袍金帶，何等輝煌。因翻一翻點名冊，問那童生道︰「你就是范進？」范進跪下道︰「童生就是。」學道道︰「你今年多少年紀了？」范進道︰「童生冊上寫的是三十歲，童生實年五十四歲。」學道道︰「你考過多少回數了？」范進道︰「童生二十歲應考，到今考過二十餘次。」學道道︰「如何總不進學？」范進道︰「總因童生文字荒謬，所以各位大老爺不曾賞取。」周學道道︰「這也未必盡然。你且出去，卷子待本道細細看。」范進磕頭下去了。", "那時天色尚早，並無童生交卷。周學道將范進卷子用心用意看了一遍，心裏不喜，道︰「這樣的文字，都說的是些甚麼話！怪不得不進學。」丟過一邊不看了。又坐了一會，還不見一個人來交卷，心裏又想道︰「何不把范進的卷子再看一遍，倘有一線之明，也可憐他苦志。」從頭至尾又看了一遍，覺得有些意思。正要再看看，却有一個童生來交卷。那童生跪下道︰「求大老爺面試。」學道和顏道︰「你的文字已在這裏了，又面試些甚麼？」那童生道︰「童生詩詞歌賦都會，求大老爺出題面試。」學道變了臉道︰「『當今天子重文章，足下何須講漢唐』！像你做童生的人，只該用心做文章，那些雜覽學他做甚麼！況且本道奉旨到此衡文，難道是來此同你談雜學的麼？看你這樣務名而不務實，那正務自然荒廢，都是些粗心浮氣的說話，看不得了。左右的趕了出去！」一聲吩咐過了，兩傍走過幾個如狼似虎的公人，把那童生叉着膊子，一路跟頭叉到大門外。周學道雖然趕他出去，却也把卷子取來看。看那童生叫做魏好古，文字也還清通。學道道︰「把他低低的進了學罷。」因取過筆來，在卷子尾上點了一點，做個記認。又取過范進卷子來看，看罷不覺嘆息道︰「這樣文字，連我看一兩遍也不能解，直到三遍之後，才曉得是天地間之至文，真乃一字一珠！可見世上糊塗試官不知屈煞了多少英才！」忙取筆細細圈點，卷面上加了三圈，即填了第一名。又把魏好古的卷子取過來，填了第二十名。將各卷匯齊，帶了進去。發出案來，范進是第一。謁見那日，着實贊揚了一回。點到二十名，魏好古上去，又勉勵了幾句「用心舉業，休學雜覽」的話，鼓吹送了出去。", "次日起馬，范進獨自送在三十里之外，轎前打恭。周學道又叫到跟前說道︰「龍頭屬老成。本道看你的文字火候到了，即在此科一定發達。我覆命之後在京專候。」范進又磕頭謝了。起來立着。學道轎子一擁而去。范進立着，直望見門槍影子抹過前山，看不見了，方才回到下處。謝了房主人。他家離城還有四十五里路，連夜回來，拜見母親。", "家裏住着一間草屋、一廈披子，門外是個茅草棚。正屋是母親住着，妻子住在披房裏。他妻子乃是集上胡屠戶的女兒。范進進學回家，母親、妻子俱各歡喜。正待燒鍋做飯，只見他丈人胡屠戶，手裏拿着一副大腸和一瓶酒，走了進來。范進向他作揖，坐下。胡屠戶道︰「我自倒運，把個女兒嫁與你這現世寶窮鬼，歷年以來不知累了我多少！如今不知因我積了甚麼德，帶挈你中了個相公，我所以帶個酒來賀你。」范進唯唯連聲，叫渾家把腸子煮了。燙起酒來，在茅草棚下坐着。母親自和媳婦在廚下造飯。胡屠戶又吩咐女婿道︰「你如今既中了相公，凡事要立起個體統來。比如我這行事裏，都是些正經有臉面的人，又是你的長親，你怎敢在我們跟前裝大，若是家門口這些做田的、扒糞的，不過是平頭百姓，你若同他拱手作揖，平起平坐，這就是壞了學校規矩，連我臉上都無光了。你是個爛忠厚沒用的人，所以這些話我不得不教導你，免得惹人笑話。」范進道︰「岳父見教的是。」胡屠戶又道︰「親家母也來這裏坐着吃飯。老人家每日小菜飯，想也難過，我女孩兒也吃些，自從進了你家門，這十幾年，不知豬油可曾吃過兩三回哩！可憐！可憐！」說罷，婆媳兩個都來坐着吃了飯。吃到日西時分，胡屠戶吃的醺醺的。這裏母子兩個，千恩萬謝。屠戶橫披了衣服，腆着肚子去了。", "次日，范進少不得拜拜鄉鄰。魏好古又約了一班同案的朋友，彼此來往。因是鄉試年，做了幾個文會。不覺到了六月盡間，這些同案的人約范進去鄉試。范進因沒有盤費，走去同丈人商議，被胡屠戶一口啐在臉上，罵了一個狗血噴頭，道︰「不要失了你的時了！你自己只覺得中了一個相公，就『癩蝦蟆想吃起天鵝肉』來！我聽見人說，就是中相公時，也不是你的文章，還是宗師看見你老，不過意，捨與你的。如今痴心就想中起老爺來！這些中老爺的都是天上的文曲星！你不看見城裏張府上那些老爺？都有萬貫家私，一個個方面大耳。像你這尖嘴猴腮，也該撒拋尿自己照照，不三不四就想天鵝屁吃！趁早收了這心，明年在我們行事裏替你尋一個館，每年尋幾兩銀子，養活你那老不死的老娘和你老婆是正經。你問我借盤纏，我一天殺一個豬還賺不得錢把銀子，都把與你去丟在水裏，叫我一家老小嗑西北風！」一頓夾七夾八，罵的范進摸門不着。辭了丈人回來，自心裏想︰「宗師說我火候已到，自古無場外的舉人，如不進去考他一考，如何甘心？」因向幾個同案商議，瞞着丈人，到城裏鄉試。出了場，即便回家。家裏已是餓了兩三天。被胡屠戶知道，又罵了一頓。", "到出榜那日，家裏沒有早飯米，母親吩咐范進道︰「我有一隻生蛋的母雞，你快拿集上去賣了，買幾升米來煮餐粥吃，我已是餓的兩眼都看不見了。」范進慌忙抱了雞，走出門去。才去不到兩個時候，只聽得一片聲的鑼響，三匹馬闖將來。那三個人下了馬，把馬拴在茅草棚上，一片聲叫道︰「快請范老爺出來，恭喜高中了！」母親不知是甚事，嚇得躲在屋裏，聽見中了，方敢伸出頭來說道︰「諸位請坐，小兒方才出去了。」那些報錄人道︰「原來是老太太。」大家簇擁着要喜錢。正在吵鬧，又是幾匹馬，二報、三報到了，擠了一屋的人，茅草棚地下都坐滿了。鄰居都來了，擠着看。老太太沒奈何，只得央及一個鄰居去尋他兒子。", "那鄰居飛奔到集上，一地裏尋不見，直尋到集東頭，見范進抱着雞，手里插個草標，一步一踱的東張西望，在那裏尋人買。鄰居道︰「范相公，快些回去！你恭喜中了舉人，報喜人擠了一屋裏。」范進道是哄他，只裝不聽見，低着頭往前走。鄰居見他不理，走上來就要奪他手裏的雞。范進道︰「你奪我的雞怎的？你又不買。」鄰居道︰「你中了舉了，叫你家去打發報子哩。」范進道︰「高鄰，你曉得我今日沒有米，要賣這雞去救命，為甚麼拿這話來混我。我又不同你頑，你自回去罷，莫誤了我賣雞。」鄰居見他不信，劈手把雞奪了，摜在地下，一把拉了回來。", "報錄人見了道︰「好了，新貴人回來了。」正要擁着他說話，范進三兩步走進屋裏來，見中間報帖已經升挂起來，上寫道︰「捷報貴府老爺范諱進高中廣東鄉試第七名亞元。京報連登黃甲。」范進不看便罷，看過一遍，又念一遍，自己把兩手拍了一下，笑了一聲道︰「噫，好了！我中了！」說着，往後一交跌倒，牙關咬緊，不省人事。老太太慌了，慌將幾口開水灌了過來。他爬將起來，又拍着手大笑道︰「噫，好！我中了！」笑着，不由分說就往門外飛跑，把報錄人和鄰居都唬了一跳。走出大門不多路，一脚踹在塘裏，掙起來，頭髮都跌散了，兩手黃泥，淋淋漓漓一身的水，眾人拉他不住，拍着，笑着，一直走到集上去了。", "眾人大眼望小眼，一齊道︰「原來新貴人歡喜瘋了。」老太太哭道︰「怎生這樣苦命的事，中了一個甚麼舉人，就得了這個拙病！這一瘋了，幾時才得好？」娘子胡氏道︰「早上好好出去，怎的就得了這樣的病！却是如何是好？」眾鄰居勸道︰「老太太不要心慌，我們而今且派兩個人跟定了范老爺。這裏眾人家裏拿些雞蛋酒米，且管待了報子上的老爹們，再為商酌。」當下眾鄰居有拿雞蛋來的，有拿白酒來的，也有背了斗米來的，也有捉兩隻雞來的。娘子哭哭啼啼，在廚下收拾齊了，拿在草棚下。鄰居又搬些桌櫈，請報錄的坐着吃酒，商議他這瘋了如何是好。報錄的內中有一個人道︰「在下倒有一個主意，不知可以行得行不得？」眾人問如何主意。那人道︰「范老爺平日可有最怕的人？他只因歡喜狠了，痰湧上來，迷了心竅。如今只消他怕的這個人來打他一個嘴巴，說︰『這報錄的話都是哄你，你並不曾中。』他吃這一唬，把痰吐了出來，就明白了。」眾鄰都拍手道︰「這個主意好得緊，妙得緊！范老爺怕的，莫過於肉案子上胡老爹。好了，快尋胡老爹來！他想是還不知道，在集上賣肉哩。」又一個人道︰「在集上賣肉他倒好知道了，他從五更鼓就往東頭集上迎豬，還不曾回來。快些迎着去尋他。」", "一個人飛奔去迎，走到半路，遇着胡屠戶來，後面跟着一個燒湯的二漢，提着七八觔肉，四五千錢，正來賀喜。進門見了老太太，老太太大哭着告訴了一番。胡屠戶詫異道︰「難道這等沒福？」外邊人一片聲請胡老爹說話。胡屠戶把肉和錢交與女兒，走了出來。眾人如此這般同他商議。胡屠戶作難道︰「雖然是我女婿，如今却做了老爺，就是天上的星宿。天上的星宿是打不得的！我聽得齋公們說，打了天上的星宿，閻王就要拿去打一百鐵棍，發在十八層地獄，永不得翻身。我却是不敢做這樣的事！」鄰居內一個尖酸人說道︰「罷麼！胡老爹，你每日殺豬的營生，白刀子進去，紅刀子出來，閻王也不知叫判官在簿子上記了你幾千條鐵棍，就是添上這一百棍，也打甚麼要緊？只恐把鐵棍子打完了，也算不到這筆賬上來。或者你救好了女婿的病，閻王敘功，從地獄裏把你提上第十七層來也不可知。」報錄的人道︰「不要只管講笑話。胡老爹，這個事須是這般，你沒奈何權變一權變。」屠戶被眾人局不過，只得連斟兩碗酒喝了，壯一壯膽，把方才這些小心收起，將平日的兇惡樣子拿出來，捲一捲那油晃晃的衣袖，走上集去。眾鄰居五六個都跟着走。老太太趕出來叫道︰「親家，你這可唬他一唬，却不要把他打傷了！」眾鄰居道︰「這自然，何消吩咐。」說着，一直去了。", "來到集上，見范進正在一個廟門口站着，散着頭髮，滿臉污泥，鞋都跑掉了一隻，兀自拍着掌，口裏叫道︰「中了！中了！」胡屠戶兇神走到跟前說道︰「該死的畜生！你中了甚麼？」一個嘴巴打將去。眾人和鄰居見這模樣，忍不住的笑。不想胡屠戶雖然大着膽子打了一下，心裏到底還是怕的，那手早顫起來，不敢打到第二下。范進因這一個嘴巴，却也打暈了，昏倒於地。眾鄰居一齊上前，替他抹胸口，捶背心，舞了半日，漸漸喘息過來，眼睛明亮，不瘋了。眾人扶起，借廟門口一個外科郎中「跳駝子」板櫈上坐着。胡屠戶站在一邊，不覺那隻手隱隱的疼將起來，自己看時，把個巴掌仰着再也彎不過來。自己心裏懊惱道︰「果然天上文曲星是打不得的！而今菩薩計較起來了。」想一想，更疼的狠了，連忙問郎中討了個膏藥貼着。范進看了眾人，說道︰「我怎麼坐在這裏？」又道︰「我這半日，昏昏沉沉，如在夢裏一般。」眾鄰居道︰「老爺恭喜高中了。適才歡喜的有些引動了痰，方才吐出幾口痰來好了。快請回家去打發報錄人。」范進說道︰「是了，我也記得是中的第七名。」范進一面自綰了頭髮，一面問郎中借了一盆水洗洗臉。一個鄰居早把那一隻鞋尋了來，替他穿上。見丈人在跟前，恐怕又要來罵。胡屠戶上前道︰「賢婿老爺，方才不是我敢大膽，是你老太太的主意，央我來勸你的。」鄰居內一個人道︰「胡老爹方才這個嘴巴打的親切，少頃范老爺洗臉還要洗下半盆豬油來！」又一個道︰「老爹，你這手明日殺不得豬了。」胡屠戶道︰「我那裏還殺豬，有我這賢婿，還怕後半世靠不着也怎的？我每常說，我的這個賢婿，才學又高，品貌又好，就是城裏頭那張府、周府這些老爺，也沒有我女婿這樣一個體面的相貌。你們不知道，得罪你們說，我小老這一雙眼睛卻是認得人的，想着先年我小女在家裏，長到三十多歲，多少有錢的富戶要和我結親，我自己覺得女兒像有些福氣的，畢竟要嫁與個老爺，今日果然不錯！」說罷哈哈大笑，眾人都笑起來。看着范進洗了臉，郎中又拿茶來吃了，一同回家。范舉人先走，屠戶和鄰居跟在後面，屠戶見女婿衣裳後襟滾皺了許多，一路低着頭替他扯了幾十回。到了家門，屠戶高聲叫道︰「老爺回府了！」老太太迎着出來，見兒子不瘋，喜從天降。眾人問報錄的，已是家裏把屠戶送來的幾千錢打發他們去了。范進拜了母親，也拜謝丈人。胡屠戶再三不安道︰「些須幾個錢，不夠你賞人。」范進又謝了鄰居。", "正待坐下，早看見一個體面的管家，手裏拿着一個大紅全帖，飛跑了進來︰「張老爺來拜新中的范老爺。」說畢，轎子已是到了門口。胡屠戶忙躲進女兒房裏不敢出來。鄰居各自散了。范進迎了出去，只見那張鄉紳下了轎進來，頭戴紗帽，身穿葵花色圓領，金帶、皂靴。他是舉人出身，做過一任知縣的，別號靜齋，同范進讓了進來，到堂屋內平磕了頭，分賓主坐下。張鄉紳先攀談道︰「世先生同在桑梓，一向有失親近。」范進道︰「晚生久仰老先生，只是無緣，不曾拜會。」張鄉紳道︰「適才看見題名錄，貴房師高要縣湯公，就是先祖的門生，我和你是親切的世弟兄。」范進道︰「晚生僥倖，實是有愧。卻幸得出老先生門下，可為欣喜。」張鄉紳四面將眼睛望了一望，說道︰「世先生果是清貧。」隨在跟的家人手裏拿過一封銀子來，說道︰「弟卻也無以為敬，謹具賀儀五十兩，世先生權且收着。這華居其實住不得，將來當事拜往俱不甚便。弟有空房一所，就在東門大街上，三進三間，雖不軒敞，也還乾凈，就送與世先生，搬到那裏去住，早晚也好請教些。」范進再三推辭，張鄉紳急了，道︰「你我年誼世好，就如至親骨肉一般，若要如此，就是見外了。」范進方才把銀子收下，作揖謝了。又說了一會，打躬作別。"], "quote": ["這周學道雖也請了幾個看文章的相公，卻自心裏想道︰「我在這裏面吃苦久了，如今自己當權，須要把卷子都要細細看過，不可聽着幕客，屈了真才。」主意定了，到廣州上了任。次日，行香掛牌。先考了兩場生員。第三場是南海、番禺兩縣童生。周學道坐在堂上，見那些童生紛紛進來︰也有小的，也有老的，儀表端正的，獐頭鼠目的，衣冠齊楚的，襤褸破爛的……落後點進一個童生來，面黃飢瘦，花白鬍鬚，頭上戴一頂破氈帽。廣東雖是地氣溫暖，這時已是十二月上旬，那童生還穿着麻布直裰，凍得乞乞縮縮，接了卷子，下去歸號。周學道看在心裏，封門進去。出來放頭牌的時節，坐在上面，只見那穿麻布的童生上來交卷。那衣服因是朽爛了，在號裏又扯破了幾塊。周學道看看自己身上，緋袍金帶，何等輝煌。因翻一翻點名冊，問那童生道︰「你就是范進？」范進跪下道︰「童生就是。」學道道︰「你今年多少年紀了？」范進道︰「童生冊上寫的是三十歲，童生實年五十四歲。」學道道︰「你考過多少回數了？」范進道︰「童生二十歲應考，到今考過二十餘次。」學道道︰「如何總不進學？」范進道︰「總因童生文字荒謬，所以各位大老爺不曾賞取。」周學道道︰「這也未必盡然。你且出去，卷子待本道細細看。」范進磕頭下去了。", "那時天色尚早，並無童生交卷。周學道將范進卷子用心用意看了一遍，心裏不喜，道︰「這樣的文字，都說的是些甚麼話！怪不得不進學。」丟過一邊不看了。又坐了一會，還不見一個人來交卷，心裏又想道︰「何不把范進的卷子再看一遍，倘有一線之明，也可憐他苦志。」從頭至尾又看了一遍，覺得有些意思。正要再看看，却有一個童生來交卷。那童生跪下道︰「求大老爺面試。」學道和顏道︰「你的文字已在這裏了，又面試些甚麼？」那童生道︰「童生詩詞歌賦都會，求大老爺出題面試。」學道變了臉道︰「『當今天子重文章，足下何須講漢唐』！像你做童生的人，只該用心做文章，那些雜覽學他做甚麼！況且本道奉旨到此衡文，難道是來此同你談雜學的麼？看你這樣務名而不務實，那正務自然荒廢，都是些粗心浮氣的說話，看不得了。左右的趕了出去！」一聲吩咐過了，兩傍走過幾個如狼似虎的公人，把那童生叉着膊子，一路跟頭叉到大門外。周學道雖然趕他出去，却也把卷子取來看。看那童生叫做魏好古，文字也還清通。學道道︰「把他低低的進了學罷。」因取過筆來，在卷子尾上點了一點，做個記認。又取過范進卷子來看，看罷不覺嘆息道︰「這樣文字，連我看一兩遍也不能解，直到三遍之後，才曉得是天地間之至文，真乃一字一珠！可見世上糊塗試官不知屈煞了多少英才！」忙取筆細細圈點，卷面上加了三圈，即填了第一名。又把魏好古的卷子取過來，填了第二十名。將各卷匯齊，帶了進去。發出案來，范進是第一。謁見那日，着實贊揚了一回。點到二十名，魏好古上去，又勉勵了幾句「用心舉業，休學雜覽」的話，鼓吹送了出去。", "次日起馬，范進獨自送在三十里之外，轎前打恭。周學道又叫到跟前說道︰「龍頭屬老成。本道看你的文字火候到了，即在此科一定發達。我覆命之後在京專候。」范進又磕頭謝了。起來立着。學道轎子一擁而去。范進立着，直望見門槍影子抹過前山，看不見了，方才回到下處。謝了房主人。他家離城還有四十五里路，連夜回來，拜見母親。", "家裏住着一間草屋、一廈披子，門外是個茅草棚。正屋是母親住着，妻子住在披房裏。他妻子乃是集上胡屠戶的女兒。范進進學回家，母親、妻子俱各歡喜。正待燒鍋做飯，只見他丈人胡屠戶，手裏拿着一副大腸和一瓶酒，走了進來。范進向他作揖，坐下。胡屠戶道︰「我自倒運，把個女兒嫁與你這現世寶窮鬼，歷年以來不知累了我多少！如今不知因我積了甚麼德，帶挈你中了個相公，我所以帶個酒來賀你。」范進唯唯連聲，叫渾家把腸子煮了。燙起酒來，在茅草棚下坐着。母親自和媳婦在廚下造飯。胡屠戶又吩咐女婿道︰「你如今既中了相公，凡事要立起個體統來。比如我這行事裏，都是些正經有臉面的人，又是你的長親，你怎敢在我們跟前裝大，若是家門口這些做田的、扒糞的，不過是平頭百姓，你若同他拱手作揖，平起平坐，這就是壞了學校規矩，連我臉上都無光了。你是個爛忠厚沒用的人，所以這些話我不得不教導你，免得惹人笑話。」范進道︰「岳父見教的是。」胡屠戶又道︰「親家母也來這裏坐着吃飯。老人家每日小菜飯，想也難過，我女孩兒也吃些，自從進了你家門，這十幾年，不知豬油可曾吃過兩三回哩！可憐！可憐！」說罷，婆媳兩個都來坐着吃了飯。吃到日西時分，胡屠戶吃的醺醺的。這裏母子兩個，千恩萬謝。屠戶橫披了衣服，腆着肚子去了。"], "intro": "《范進中舉》節錄自《儒林外史》第三回「周學道校士撥真才 胡屠戶行凶鬧捷報」，版本據嘉慶八年新鐫臥閑草堂藏板，現有標題為編者所加。故事以暮年登科的周學道與花白鬍鬚的老童生范進相遇為開端，帶出當時知識分子窮一生之力追求功名的現象。繼而寫范進高中", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%84%92%E6%9E%97%E5%A4%96%E5%8F%B2%E3%83%BB%E8%8C%83%E9%80%B2%E4%B8%AD%E8%88%89"}, {"title": "芙蕖", "author": "李漁", "period": "清", "form": "文", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["芙蕖與草本諸花似覺稍異；然有根無樹，一歲一生，其性同也。譜云︰「產於水者曰草芙蕖，產於陸者曰旱蓮。」則謂非草本不得矣。予夏季倚此為命者，非故效顰於茂叔而襲成說於前人也，以芙蕖之可人，其事不一而足，請備述之。", "群葩當令時，只在花開之數日，前此後此，均不足觀。芙蕖則不然。自荷錢出水之日，便已點綴綠波；及其莖葉既生，則又日高日上，日上日妍；有風既作飄颻之態，無風亦呈嬝娜之姿；是我於花之未開，先享無窮逸致矣。", "迨至菡萏成花，嬌姿欲滴，後先相繼，自夏徂秋；此則在花為分內之事，在人為玩賞之常者也。及花之既謝，似可告無罪於主人矣，乃復蒂下生蓬，蓬中結實，亭亭獨立，猶似未開之花，與翠葉並擎，不至白露為霜不止——此皆言其可目者也。", "可鼻則有荷葉之清香，荷花之異馥；可口則蓮實與藕，皆並列盤餐而互芬齒頰。只有霜中敗葉，零落難堪，似成棄物矣；乃摘而藏之，又備經年裹物之用。", "是則芙蕖也，無一時不適耳目之觀，無一物不備家常之用；有五穀之實而不有其名，兼百花之長而各去其短。種植之利，有大於此者乎？"], "quote": ["芙蕖與草本諸花似覺稍異；然有根無樹，一歲一生，其性同也。譜云︰「產於水者曰草芙蕖，產於陸者曰旱蓮。」則謂非草本不得矣。予夏季倚此為命者，非故效顰於茂叔而襲成說於前人也，以芙蕖之可人，其事不一而足，請備述之。", "群葩當令時，只在花開之數日，前此後此，均不足觀。芙蕖則不然。自荷錢出水之日，便已點綴綠波；及其莖葉既生，則又日高日上，日上日妍；有風既作飄颻之態，無風亦呈嬝娜之姿；是我於花之未開，先享無窮逸致矣。", "迨至菡萏成花，嬌姿欲滴，後先相繼，自夏徂秋；此則在花為分內之事，在人為玩賞之常者也。及花之既謝，似可告無罪於主人矣，乃復蒂下生蓬，蓬中結實，亭亭獨立，猶似未開之花，與翠葉並擎，不至白露為霜不止——此皆言其可目者也。", "可鼻則有荷葉之清香，荷花之異馥；可口則蓮實與藕，皆並列盤餐而互芬齒頰。只有霜中敗葉，零落難堪，似成棄物矣；乃摘而藏之，又備經年裹物之用。"], "intro": "芙蕖，蓮花的別名。本文是從《一家言》裏節選出來的。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%8A%99%E8%95%96"}, {"title": "閒情記趣", "author": "沈復", "period": "清", "form": "文", "theme": "田園幽居", "mood": "snow_winter", "lines": ["余憶童稚時，能張目對日，明察秋毫，見藐小之物，必細察其紋理，故時有物外之趣。", "夏蚊成雷，私擬作群鶴舞空，心之所向，則或千或百，果然鶴也；昂首觀之，項為之強。又留蚊子素帳中，徐噴以煙，使之沖煙而飛鳴，作青雲白鶴觀，果如鶴唳雲端，怡然稱快。", "於土牆凹凸處，花臺小草叢雜處，常蹲其身，使與臺齊，定神細視，以叢草為林，以蟲蟻為獸，以土礫凸者為丘，凹者為壑，神遊其中，恰然自得。", "一日，見二蟲鬥草間，觀之正濃，忽有龐然大物，拔山倒樹而來，蓋一癩蝦蟆也；舌一吐而二蟲盡為所吞。余年幼，方出神，不覺呀然驚恐。神定，捉蝦蟆，鞭數十，驅之別院。……", "及長，愛花成癖。……余閒居，案頭瓶花不絕。芸曰︰「子之插花能備風晴雨露，可謂精妙入神；而畫中有草蟲一法，盍仿而效之？」余曰︰「蟲躑躅不受制，焉能仿效？」芸曰︰「有一法，恐作俑罪過耳！」", "余曰︰「試言之。」曰︰「蟲死色不變，覓螳螂、蟬、蝶之屬，以針刺死，用細絲扣蟲項繫花草間；整其足，或抱梗，或踏葉，宛然如生，不亦善乎？」余喜，如其法行之，見者無不稱絕。求之閨中，今恐未必有此會心者矣！……", "蘇城有南園、北園二處，菜花黃時，苦無酒家小飲；攜盒而往，對花冷飲，殊無意味。或議就近覓飲者，或議看花歸飲者，終不如對花熱飲為快，眾議未定。芸笑子曰︰「明日但各出杖頭錢，我自擔爐火來。」聚笑曰︰「諾。」", "眾去，余問曰︰「卿果自往乎？」芸曰︰「非也，妾見市中賣餛飩者，其擔鍋竈無不備，盍雇之而往？妾先烹調端整，到彼處再一下鍋。茶酒兩便。」余曰︰「酒菜固便矣。茶乏烹具。」芸曰︰「攜一砂罐去，以鐵叉串罐柄，去其鍋，懸於行竈中，加柴火煎茶，不亦便乎？」余鼓掌稱善。", "街頭有鮑姓者，賣餛飩為業，以百錢雇其擔，約以明日午後。鮑欣然允諾。明日看花者至，余告以故，眾咸嘆服。飯後同往，并帶席墊，至南園，擇柳陰下團坐，先烹茗，飲畢，然後煖酒烹肴。是時風和日麗，徧地黃金，青衫紅袖，越阡度陌，蝶蜂亂飛，令人不飲自醉。", "既而酒肴俱熟，坐地大嚼。擔者頗不俗，拉與同飲。遊人見之莫不羡為奇想。杯盤狼藉，各已陶然，或坐或臥，或歌或嘯。紅日將頹，余思粥，擔者即為買米煮之，果腹而歸。芸問日︰「今日之遊樂乎？」眾曰︰「非夫人之力不及此。」大笑而散。", "貧士起居服食，以及器皿房舍，宜省儉而雅潔。省儉之法，曰「就事論事。」余愛小飲，不喜多菜。芸為置一梅花盒，用二寸白磁深碟六隻，中置一隻，外置五隻，用灰漆就，其形如梅花。底蓋均起凹楞，蓋之上有柄如花蒂，置之案頭，如一朶墨梅覆桌；啟蓋視之，如菜裝於花瓣中。", "一盒六色，二三知己可以隨意取食。食完再添。另做矮邊圓盤一隻，以便放盃箸酒壺之類，隨處可擺，移掇亦便。即食物省儉之一端也。余之小帽領襪皆芸自做。衣之破者移東補西，必整必潔，色取闇淡以免垢跡，既可出客，又可家常。此又服飾省儉之一端也。"], "quote": ["余憶童稚時，能張目對日，明察秋毫，見藐小之物，必細察其紋理，故時有物外之趣。", "夏蚊成雷，私擬作群鶴舞空，心之所向，則或千或百，果然鶴也；昂首觀之，項為之強。又留蚊子素帳中，徐噴以煙，使之沖煙而飛鳴，作青雲白鶴觀，果如鶴唳雲端，怡然稱快。", "於土牆凹凸處，花臺小草叢雜處，常蹲其身，使與臺齊，定神細視，以叢草為林，以蟲蟻為獸，以土礫凸者為丘，凹者為壑，神遊其中，恰然自得。", "一日，見二蟲鬥草間，觀之正濃，忽有龐然大物，拔山倒樹而來，蓋一癩蝦蟆也；舌一吐而二蟲盡為所吞。余年幼，方出神，不覺呀然驚恐。神定，捉蝦蟆，鞭數十，驅之別院。……"], "intro": "《浮生六記》一書，現存只有四記，本文是其中的一「記」，因原文太長，稍有刪節，均用省略號分別標明。閒情記趣，就是記悠閒中的樂趣。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%96%92%E6%83%85%E8%A8%98%E8%B6%A3"}, {"title": "赴戍登程口占示家人（二首選一）", "author": "林則徐", "period": "清", "form": "詩", "theme": "山水登臨", "mood": "majestic_peaks", "lines": ["力微任重久神疲，再竭衰庸定不支。", "苟利國家生死以，豈因禍福避趨之！", "謫居正是君恩厚，養拙剛於戍卒宜。", "戲與山妻談故事，試吟斷送老頭皮。"], "quote": ["力微任重久神疲，再竭衰庸定不支。", "苟利國家生死以，豈因禍福避趨之！", "謫居正是君恩厚，養拙剛於戍卒宜。", "戲與山妻談故事，試吟斷送老頭皮。"], "intro": "林則徐因查禁鴉片、積極禦敵而得罪朝廷中的主和派，遂於道光二十二年（一八四二）被遣戍新疆伊犁。八月十一日，他自西安告別家人，踏上遠謪之程。感念國家的命運、家人的離別與自己的處境，遂寫下這首名作。詩題的「赴戍」指被遣戍伊犁，「口占」即作詩不起草", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B5%B4%E6%88%8D%E7%99%BB%E7%A8%8B%E5%8F%A3%E5%8D%A0%E7%A4%BA%E5%AE%B6%E4%BA%BA%EF%BC%88%E4%BA%8C%E9%A6%96%E9%81%B8%E4%B8%80%EF%BC%89"}, {"title": "與妻書", "author": "林覺民", "period": "清", "form": "文", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["意映卿卿如晤︰", "吾今以此書與汝永別矣！吾作此書時，尚是世中一人；汝看此書時，吾已成為陰間一鬼。吾作此書，淚珠和筆墨齊下，不能竟書而欲擱筆。又恐汝不察吾衷，謂吾忍捨汝而死也，謂吾不知汝之不欲吾死也，故遂忍悲為汝言之。", "吾至愛汝，即此愛汝一念，使吾勇於就死也。吾自遇汝以來，常願天下有情人都成眷屬；然遍地腥雲，滿街狼犬，稱心快意，幾家能夠？司馬春衫，吾不能學太上之忘情也。", "語云︰仁者「老吾老以及人之老，幼吾幼以及人之幼」。吾充吾愛汝之心，助天下人愛其所愛，所以敢先汝而死，不顧汝也。汝體吾此心，於啼泣之餘，亦以天下人為念，當亦樂犧牲吾身與汝身之福利，為天下人謀永福也。汝其勿悲！", "汝憶否四五年前某夕，吾嘗語曰︰「與使吾先死也，無寧汝先吾而死。」汝初聞言而怒；後經吾婉解，雖不謂吾言為是，而亦無辭相答。吾之意，蓋謂以汝之弱，必不能禁失吾之悲。吾先死，留苦與汝，吾心不忍，故寧請汝先死，吾擔悲也。嗟夫！誰知吾卒先汝而死乎！", "吾真真不能忘汝也。回憶後街之屋，入門穿廊，過前後廳，又三四折，有小廳，廳旁一室為吾與汝雙棲之所。初婚三四個月，適冬之望日前後，窗外疏梅篩月影，依稀掩映，吾與汝並肩挽手，低低切切，何事不語？何情不訴？及今思之，空餘淚痕。", "又回憶六七年間，吾之逃家復歸也，汝泣告我︰「望今後有遠行，必以告妾，妾願隨君行。」吾亦既許汝矣。前十餘日回家，即欲乘便以此行之事語汝；及與汝相對，又不能啟口，且以汝之有身也，更恐不勝悲，故惟日日呼酒買醉。嗟夫！當時余心之悲，蓋不能以寸管形容之。", "吾誠願與汝相守以死，第以今日時勢觀之，天災可以死，盜賊可以死，瓜分之日可以死，奸官污吏虐民可以死，吾輩處今日之中國，國中無地無時不可以死。到那時使吾眼睜睜看汝死，或使汝眼睜睜看我死，吾能之乎？抑汝能之乎？", "即可不死，而離散不相見，徒使兩地眼成穿而骨化石，試問古來幾曾見破鏡能重圓？則較死為苦也，將奈之何！今日吾與汝幸雙健，天下人不當死而死，與不願離而離者，不可數計；鍾情如我輩者，能忍之乎？此吾所以敢率性就死，不顧汝也。", "吾今死無餘憾，國事成不成，自有同志者在。依新已五歲，轉眼成人，汝其善撫之，使之肖我。汝腹中之物，吾疑其女也，女必像汝，吾心甚慰；或又是男，則亦教其以父志為志，則我死後尚有二意洞在也。甚幸！甚幸！", "吾家日後當甚貧，貧無所苦，清靜過日而已。吾今與汝無言矣！吾居九泉之下，遙聞汝哭聲，當哭相和也。吾平日不信有鬼，今則又望其真有；今人又言心電感應有道，吾亦望其言是實；則吾之死，吾靈尚依依傍汝也，汝不必以無侶悲。", "吾平生未嘗以吾所志語汝，是吾不是處；然語之又恐汝日日為吾擔憂。吾犧牲百死而不辭，而使汝擔憂，的的非吾所忍。吾愛汝至，所以為汝謀者惟恐未盡。汝幸而偶我，又何不幸而生今日之中國；吾幸而得汝，又何不幸而生今日之中國！卒不忍獨善其身。"], "quote": ["意映卿卿如晤︰", "吾今以此書與汝永別矣！吾作此書時，尚是世中一人；汝看此書時，吾已成為陰間一鬼。吾作此書，淚珠和筆墨齊下，不能竟書而欲擱筆。又恐汝不察吾衷，謂吾忍捨汝而死也，謂吾不知汝之不欲吾死也，故遂忍悲為汝言之。", "吾至愛汝，即此愛汝一念，使吾勇於就死也。吾自遇汝以來，常願天下有情人都成眷屬；然遍地腥雲，滿街狼犬，稱心快意，幾家能夠？司馬春衫，吾不能學太上之忘情也。", "語云︰仁者「老吾老以及人之老，幼吾幼以及人之幼」。吾充吾愛汝之心，助天下人愛其所愛，所以敢先汝而死，不顧汝也。汝體吾此心，於啼泣之餘，亦以天下人為念，當亦樂犧牲吾身與汝身之福利，為天下人謀永福也。汝其勿悲！"], "intro": "本篇是林覺民於辛亥年（一九一一）三月廿六日，廣州起義前夕寫給妻子陳意映的遺書。 一九〇五年，林覺民東渡日本，就讀於慶應義塾大學。留學不久，他就參加了孫中山創辦的中國同盟會。一九一〇年廣州起義失敗後，同盟會又再密謀翌年在廣州起義，電令在日留學", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%88%87%E5%A6%BB%E6%9B%B8"}, {"title": "復魯絜非書", "author": "姚鼐", "period": "清", "form": "文", "theme": "詠史哲思", "mood": "autumn_sunset", "lines": ["桐城姚鼐頓首，絜非先生足下︰", "相知恨少，晚遇先生。接其人，知為君子矣；讀其文，非君子不能也。往與程魚門、周書昌嘗論古今才士，惟為古文者最少；苟為之，必傑士也；況為之專且善如先生者乎？", "辱書，引義謙而見推過當，非所敢任。鼐自幼迄衰，獲侍賢人長者為師友，剽取見聞，加臆度為說，非真知文，能為文也；奚辱命之哉？蓋虛懷樂取者，君子之心；而誦所得以正於君子，亦鄙陋之志也。", "鼐聞天地之道，陰陽剛柔而已。文者，天地之精英，而陰陽剛柔之發也。惟聖人之言，統二氣之會而弗偏。然而《易》《詩》《書》《論語》所載，亦間有可以剛柔分矣。值其時其人，告語之體，各有宜也。", "自諸子而降，其為文無弗有偏者。其得於陽與剛之美者，則其文如霆、如電、如長風之出谷、如崇山峻崖、如決大川、如奔騏驥；其光也，如杲日、如火、如金鏐鐵；其於人也，如憑高視遠、如君而朝萬眾、如鼓萬勇士而戰之。", "其得於陰與柔之美者，則其文如升初日、如清風、如雲、如霞、如煙、如幽林曲澗、如淪、如漾、如珠玉之輝、如鴻鵠之鳴而入寥廓；其於人也，漻乎其如歎，邈乎其如有思，㬉乎其如喜，愀乎其如悲。觀其文，諷其音，則為文者之性情形狀舉以殊焉。", "且夫陰陽剛柔，其本二端，造物者糅之，而氣有多寡進絀，則品次億萬，以至於不可窮，萬物生焉。故曰「一陰一陽之謂道」。夫文之多變，亦若是已。糅而偏勝，可也；偏勝之極，一有一絕無，與夫剛不足為剛，柔不足為柔者，皆不可以言文。", "今夫野人、孺子聞樂，以為笙歌弦管之會爾；苟善樂者聞之，則五音十二律，必有一當，接於耳而分矣。夫論文者豈異於是乎？", "宋朝歐陽、曾公之文，其才皆偏於柔之美者也︰歐公能取異己者之長而時濟之；曾公能避所短而不犯。觀先生之文，殆近於二公焉。", "抑人之學文，其功力所能至者，陳理義必明當，布置取舍，繁簡廉肉不失法，吐辭雅馴、不蕪而已。古今至此者，蓋不數數得，然尚非文之至。文之至者，通乎神明，人力不及施也。先生以為然乎？", "惠寄之文，刻本固當見與，鈔本謹封還。然鈔本不能勝刻者。諸體中，書疏贈序為上，記事之文次之，辨論又次之。鼐亦竊識數語於其間，未必當也。《梅崖集》果有逾人處，恨不識其人。郎君令甥皆美才，未易量，聽所好恣為之，勿拘其途可也。於所寄文輒妄評說，勿罪勿罪！", "秋暑，惟體中安否？千萬自愛！七月朔日。"], "quote": ["桐城姚鼐頓首，絜非先生足下︰", "相知恨少，晚遇先生。接其人，知為君子矣；讀其文，非君子不能也。往與程魚門、周書昌嘗論古今才士，惟為古文者最少；苟為之，必傑士也；況為之專且善如先生者乎？", "辱書，引義謙而見推過當，非所敢任。鼐自幼迄衰，獲侍賢人長者為師友，剽取見聞，加臆度為說，非真知文，能為文也；奚辱命之哉？蓋虛懷樂取者，君子之心；而誦所得以正於君子，亦鄙陋之志也。", "鼐聞天地之道，陰陽剛柔而已。文者，天地之精英，而陰陽剛柔之發也。惟聖人之言，統二氣之會而弗偏。然而《易》《詩》《書》《論語》所載，亦間有可以剛柔分矣。值其時其人，告語之體，各有宜也。"], "intro": "魯絜非，名仕驥，又名九皋，號山木，清江西新城人。乾隆進士。官山西夏縣知縣。嘗踰嶺至建寧謁朱梅崖（仕琇）受古文法；又嘗渡江至懷寧，聞業於作者。為文沖夷和易，有《山木居士集》。本文乃作者答復魯絜非論文的書信。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%BE%A9%E9%AD%AF%E7%B5%9C%E9%9D%9E%E6%9B%B8"}, {"title": "登泰山記", "author": "姚鼐", "period": "清", "form": "文", "theme": "山水登臨", "mood": "snow_winter", "lines": ["泰山之陽，汶水西流；其陰，濟水東流。陽谷皆入汶，陰谷皆入濟。當其南北分者，古長城也。最高日觀峯，在長城南十五里。余以乾隆三十九年十二月，自京師乘風雪，歷齊河、長清、穿泰山西北谷，越長城之限，至於泰安。", "是月丁未，與知府朱孝純子潁，由南麓登，四十五里，道皆砌石為磴，其級七千有餘。泰山正南面有三谷。中谷遶泰安城下，酈道元所謂環水也。余始循以入，道少半，越中嶺，復循西谷，遂至其巔。", "古時登山循東谷入，道有天門；東谷者，古謂之天門谿水，余所不至也。今所經中嶺，及山巔崖限當道者，世皆謂之天門云。道中迷霧，冰滑，磴幾不可登；及既上，蒼山負雪，明燭天南，望晚日照城郭，汶水徂徠如畫，而半山居霧若帶然。", "戊申晦，五鼓，與子潁坐日觀亭待日出，大風揚積雪擊面。亭東，自足下皆雲漫，稍見雲中白若樗蒱數十立者，山也。極天雲一線異色，須臾成五采，日上正赤如丹，下有紅光動搖承之。", "或曰︰此東海也。回視日觀以西峯，或得日，或否。絳皜駮色，而皆若僂。亭西有岱祠，又有碧霞元君祠。皇帝行宮在碧霞元君祠東。", "是日觀道中石刻，自唐顯慶以來，其遠古刻盡漫失；僻不當道者，皆不及往。山多石少，石蒼黑色，多平方，少圜。少雜樹，多松，生石罅，皆平頂。冰雪無瀑水，無鳥獸音迹。至日觀，數里內無樹，而雪與人膝齊。桐城姚鼐記。"], "quote": ["泰山之陽，汶水西流；其陰，濟水東流。陽谷皆入汶，陰谷皆入濟。當其南北分者，古長城也。最高日觀峯，在長城南十五里。余以乾隆三十九年十二月，自京師乘風雪，歷齊河、長清、穿泰山西北谷，越長城之限，至於泰安。", "是月丁未，與知府朱孝純子潁，由南麓登，四十五里，道皆砌石為磴，其級七千有餘。泰山正南面有三谷。中谷遶泰安城下，酈道元所謂環水也。余始循以入，道少半，越中嶺，復循西谷，遂至其巔。", "古時登山循東谷入，道有天門；東谷者，古謂之天門谿水，余所不至也。今所經中嶺，及山巔崖限當道者，世皆謂之天門云。道中迷霧，冰滑，磴幾不可登；及既上，蒼山負雪，明燭天南，望晚日照城郭，汶水徂徠如畫，而半山居霧若帶然。", "戊申晦，五鼓，與子潁坐日觀亭待日出，大風揚積雪擊面。亭東，自足下皆雲漫，稍見雲中白若樗蒱數十立者，山也。極天雲一線異色，須臾成五采，日上正赤如丹，下有紅光動搖承之。"], "intro": "本篇選自《惜抱軒集．文集》卷十四。乾隆三十九年（一七七五），作者辭官歸里，途經泰安，與友人登臨泰山，寫成這篇遊記。時值深冬，作者將所見的景物作細緻的描述，使人如見其景，如臨其地。本文風格簡潔嚴整，是桐城派古文的代表作之一。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%99%BB%E6%B3%B0%E5%B1%B1%E8%A8%98"}, {"title": "出關與畢侍郎牋", "author": "洪亮吉", "period": "清", "form": "文", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["自渡風陵，易車而騎。朝發蒲坂，夕宿鹽池。陰雲蔽虧，時雨凌厲。自河以東，與關內稍異︰土逼若衖，塗危入棧。原林黯慘，疑披谷口之霧；衢歌哀怨，恍聆山陽之笛。", "日在西隅，始展黃君仲則殯於運城西寺；見其遺棺七尺，枕書滿篋。撫其吟案，則阿㜷之遺牋尚存；披其繐帷，則城東之小史既去。蓋相如病肺，經月而難痊；昌谷嘔心，臨終而始悔者也。猶復丹鉛狼藉，几案紛披。", "聞其絕命前夕，吟哦未已，手不能書，畫之以指。此則杜鵑欲化，猶振哀音，鷙鳥將亡，冀留勁羽；遺棄一世之務，留連身後之名者焉。", "伏念明公生則為營薄宦，死則為䘏衰親；復發德音，欲梓遺集。一士之身，玉成終始，聞之者動容，受之者淪髓。冀其遊岱之魂，感恩而西顧；返洛之旐，銜酸而東指。又況龔生竟夭，尚有故人；元伯雖亡，不無死友。", "他日傳公風義，勉其遺孤，風茲來禩，亦盛事也。今謹上其詩及樂府共四大冊。此君平生，與亮吉雅故，惟持論不同。嘗戲謂亮吉曰︰「予不幸早死，集經君訂定，必乖余之指趣矣。」省其遺言，為之墮淚！", "今不敢輒加朱墨，皆封送閣下，暨與述菴廉使、東友侍讀共刪定之。即其所就，已有足傳；方乎古人，無愧作者。惟稿草皆其手寫，別無副本，梓後，望尚付其遺孤，以為手澤耳。", "亮吉十九日已抵潼關，馬上率啟，不宣。"], "quote": ["自渡風陵，易車而騎。朝發蒲坂，夕宿鹽池。陰雲蔽虧，時雨凌厲。自河以東，與關內稍異︰土逼若衖，塗危入棧。原林黯慘，疑披谷口之霧；衢歌哀怨，恍聆山陽之笛。", "日在西隅，始展黃君仲則殯於運城西寺；見其遺棺七尺，枕書滿篋。撫其吟案，則阿㜷之遺牋尚存；披其繐帷，則城東之小史既去。蓋相如病肺，經月而難痊；昌谷嘔心，臨終而始悔者也。猶復丹鉛狼藉，几案紛披。", "聞其絕命前夕，吟哦未已，手不能書，畫之以指。此則杜鵑欲化，猶振哀音，鷙鳥將亡，冀留勁羽；遺棄一世之務，留連身後之名者焉。", "伏念明公生則為營薄宦，死則為䘏衰親；復發德音，欲梓遺集。一士之身，玉成終始，聞之者動容，受之者淪髓。冀其遊岱之魂，感恩而西顧；返洛之旐，銜酸而東指。又況龔生竟夭，尚有故人；元伯雖亡，不無死友。"], "intro": "關指潼關，在黃河南岸，為陝西、河南、山西三省交界處。畢侍郎即畢沅。侍郎，官名，即清朝各部副大臣。畢沅，字湘蘅，號秋帆，又號靈巖山人，清鎮洋（今江蘇太倉縣）人。乾隆進士，歷任陝西、河南、山東等省巡撫，官至湖廣總督。幼聰穎，好讀書，對經史、小學", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%87%BA%E9%97%9C%E8%88%87%E7%95%A2%E4%BE%8D%E9%83%8E%E7%89%8B"}, {"title": "對酒", "author": "秋瑾", "period": "清", "form": "詩", "theme": "歲時雪月", "mood": "autumn_sunset", "lines": ["不惜千金買寶刀，", "貂裘換酒也堪豪。", "一腔熱血勤珍重，", "灑去猶能化碧濤。"], "quote": ["不惜千金買寶刀，", "貂裘換酒也堪豪。", "一腔熱血勤珍重，", "灑去猶能化碧濤。"], "intro": "晚清政局不穩，歷經鴉片戰爭、英法聯軍之役、太平天國之亂、甲午戰爭、八國聯軍入侵，國家積弱，民生困苦，民心思變。又隨着西方文明、民權思想的大量輸入，有志之士紛紛鼓吹改革，辦學興國，啟發民智，提高女性地位；又有革命志士提倡民族主義，積極從事反清", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B0%8D%E9%85%92%C2%A0"}, {"title": "長相思（山一程）", "author": "納蘭性德", "period": "清", "form": "詞", "theme": "山水登臨", "mood": "snow_winter", "lines": ["山一程，水一程。身向榆關那畔行，夜深千帳鐙。", "風一更，雪一更。聒碎鄉心夢不成，故園無此聲。"], "quote": ["山一程，水一程。身向榆關那畔行，夜深千帳鐙。", "風一更，雪一更。聒碎鄉心夢不成，故園無此聲。"], "intro": "納蘭性德《長相思》（山一程）選自《清名家詞・通志堂詞》。《長相思》是詞牌名。清康熙二十一年（一六八二），作者隨聖祖出巡，經山海關前往盛京（今遼寧瀋陽），盛京是清人入關前的京城。這首詞生動地描寫了帝王出巡關外的行程和夜宿軍營的情景，抒發了羈旅", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%95%B7%E7%9B%B8%E6%80%9D%EF%BC%88%E5%B1%B1%E4%B8%80%E7%A8%8B%EF%BC%89"}, {"title": "蝶戀花（辛苦最憐天上月）", "author": "納蘭性德", "period": "清", "form": "詞", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["辛苦最憐天上月。一昔如環，昔昔都成玦。若似月輪終皎潔，不辭冰雪為卿熱。", "無那塵緣容易絕。燕子依然，軟踏簾鈎說。唱罷秋墳愁未歇，春叢認取雙棲蝶。"], "quote": ["辛苦最憐天上月。一昔如環，昔昔都成玦。若似月輪終皎潔，不辭冰雪為卿熱。", "無那塵緣容易絕。燕子依然，軟踏簾鈎說。唱罷秋墳愁未歇，春叢認取雙棲蝶。"], "intro": "悼亡是古典詩歌中一大分類，此篇是納蘭性德悼念亡妻盧氏的詞作。納蘭原配妻子盧氏，是兩廣總督、兵部尚書、都察院右副都御史盧興祖之女，夫妻甚恩愛，可惜只相處三年，盧氏短壽，於納蘭二十三歲時病故，納蘭為作思念、悼亡詞作多情深動人。盧氏才貌雙全，在納", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%9D%B6%E6%88%80%E8%8A%B1%EF%BC%88%E8%BE%9B%E8%8B%A6%E6%9C%80%E6%86%90%E5%A4%A9%E4%B8%8A%E6%9C%88%EF%BC%89"}, {"title": "祭妹文", "author": "袁枚", "period": "清", "form": "文", "theme": "江河湖海", "mood": "snow_winter", "lines": ["乾隆丁亥冬，葬三妹素文於上元之羊山，而奠以文曰︰", "嗚呼！汝生於浙而葬於斯，離吾鄉七百里矣。當時雖觭夢幻想，寧知此為歸骨所耶？汝以一念之貞，遇人仳離，致孤危托落。雖命之所存，天實為之；然而累汝至此者，未嘗非予之過也。", "予幼從先生授經，汝差肩而坐，愛聽古人節義事，一旦長成，遽躬蹈之。嗚呼！使汝不識詩書，或未必艱貞若是。", "余捉蟋蟀，汝奮臂出其間，歲寒蟲僵，同臨其穴。今予殮汝、葬汝，而當日之情形，憬然赴目。予九歲，憩書齋，汝梳雙髻，披單縑來，温《緇衣》一章；適先生奓戶入，聞兩童子音琅琅然，不覺莞爾，連呼則則，此七月望日事也。", "汝在九原，當分明記之。予弱冠粵行，汝掎裳悲慟。逾三年，予披宮錦還家，汝從東廂扶案出，一家瞠視而笑；不記語從何起，大概說長安登科，函使報信遲早云爾。凡此瑣瑣，雖為陳迹，然我一日未死，則一日不能忘。", "舊事填膺，思之淒梗，如影歷歷，逼取便逝。悔當時不將嫛婗情狀，羅縷記存。然而汝已不在人間，則雖年光倒流，兒時可再，而亦無與為證印者矣！", "汝之義絕高氏而歸也，堂上阿嬭，仗汝扶持；家中文墨，䀢汝辦治。嘗謂女流中最少明經義、諳雅故者；汝嫂非不婉嫕，而於此微缺然。故自汝歸後，雖為汝悲，實為予喜。予又長汝四歲，或人間長者先亡，可將身後托汝，而不謂汝之先予以去也！", "前年予病，汝終宵刺探，減一分則喜，增一分則憂。後雖小差，猶尚殗殜，無所娛遣，汝來牀前，為說稗官野史可喜可愕之事，聊資一懽。嗚呼！今而後吾將再病，教從何處呼汝耶？", "汝之疾也，予信醫言無害，遠弔揚州。汝又慮戚吾心，阻人走報。及至綿惙已極，阿嬭問︰「望兄歸否？」強應曰︰「諾！」予已先一日夢汝來訣，心知不祥，飛舟渡江。果予以未時還家，而汝以辰時氣絕。四支猶溫，一目未瞑，蓋猶忍死待予也。", "嗚呼痛哉！早知訣汝，則予豈肯遠遊；即遊，亦尚有幾許心中言，要汝知聞，共汝籌畫也。而今已矣！除吾死外，當無見期。吾又不知何日死，可以見汝；而死後之有知無知，與得見不得見，又卒難明也。然則抱此無涯之憾，天乎，人乎！而竟已乎！", "汝之詩，吾已付梓；汝之女，吾已代嫁；汝之生平，吾已作傳；惟汝之窀穸未謀耳。先塋在杭，江廣河深，勢難歸葬，故請母命而寧汝於斯，便祭掃也。其旁葬汝女阿印，其下兩塚︰一為阿爺侍者朱氏，一為阿兄侍者陶氏。", "羊山曠渺，南望原隰，西望棲霞，風雨晨昏，羈魂有伴，當不孤寂。所憐者，吾自戊寅年讀汝哭姪詩後，至今無男；兩女牙牙，生汝死後，纔周睟耳。予雖親在未敢言老，而齒危髮禿，暗裏自知，知在人間，尚復幾日？"], "quote": ["乾隆丁亥冬，葬三妹素文於上元之羊山，而奠以文曰︰", "嗚呼！汝生於浙而葬於斯，離吾鄉七百里矣。當時雖觭夢幻想，寧知此為歸骨所耶？汝以一念之貞，遇人仳離，致孤危托落。雖命之所存，天實為之；然而累汝至此者，未嘗非予之過也。", "予幼從先生授經，汝差肩而坐，愛聽古人節義事，一旦長成，遽躬蹈之。嗚呼！使汝不識詩書，或未必艱貞若是。", "余捉蟋蟀，汝奮臂出其間，歲寒蟲僵，同臨其穴。今予殮汝、葬汝，而當日之情形，憬然赴目。予九歲，憩書齋，汝梳雙髻，披單縑來，温《緇衣》一章；適先生奓戶入，聞兩童子音琅琅然，不覺莞爾，連呼則則，此七月望日事也。"], "intro": "祭文是祭祀鬼神和死去的人時所誦讀的文章。本文為作者祭其三妹的文章。他的三妹名叫袁機，字素文，號青琳居士。幼時許配給江蘇如皋縣高姓，後來她的未婚夫染了惡疾，高姓願意解除婚約，但她堅執不可，竟嫁過去了。高姓子輕薄喜嫖賭，把她的粧奩揮霍光了，還想", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%A5%AD%E5%A6%B9%E6%96%87"}, {"title": "村居", "author": "高鼎", "period": "清", "form": "詩", "theme": "春水花鳥", "mood": "spring_breeze", "lines": ["草長鶯飛二月天，拂堤楊柳醉春煙。", "兒童散學歸來早，忙趁東風放紙鳶。"], "quote": ["草長鶯飛二月天，拂堤楊柳醉春煙。", "兒童散學歸來早，忙趁東風放紙鳶。"], "intro": "", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9D%91%E5%B1%85"}, {"title": "紅樓夢・接外孫賈母惜孤女", "author": "曹雪芹", "period": "清", "form": "小說", "theme": "春水花鳥", "mood": "snow_winter", "lines": ["且說黛玉自那日棄舟登岸時，便有榮府打發轎子並拉行李車輛伺候。這黛玉嘗聽得母親說，他外祖母家與別人家不同，他近日所見的這幾個三等的僕婦，吃穿用度，已是不凡，何況今至其家，都要步步留心，時時在意，不要多說一句話，不可多行一步路，恐被人恥笑了去。自上了轎，進了城，從紗窗中瞧了一瞧，其街市之繁華，人烟之阜盛，自非別處可比。又行了半日，忽見街北蹲着兩個大石獅子，三間獸頭大門，門前列坐着十來個華冠麗服之人。正門不開，只東西兩角門有人出入。正門之上有一匾，匾上大書「勅造寧國府」五個大字。黛玉想道︰「這是外祖的長房了。」又往西不遠，照樣也是三間大門，方是榮國府，卻不進正門，只由西角門而進。轎子抬着走了一箭之遠，將轉彎時，便歇了轎，後面的婆子也都下來了，另換了四個眉目秀潔的十七八歲的小廝上來抬着轎子，眾婆子步下跟隨，至一垂花門前落下，那小廝俱肅然退出，眾婆子上前打起轎簾，扶黛玉下了轎。黛玉扶着婆子的手，進了垂花門。兩邊是超手遊廊，正中是穿堂，當地放着一個紫檀架子大理石屏風。轉過屏風，小小三間廳房，廳後便是正房大院。正面五間上房，皆是雕梁畫棟。兩邊穿山遊廊廂房，掛着各色鸚鵡畫眉等雀鳥。台階上坐着幾個穿紅著綠的丫頭，一見他們來了，都笑迎上來，道︰「剛纔老太太還念誦呢！可巧就來了。」於是三四人爭着打簾子。一面聽得人說︰「林姑娘來了！」", "黛玉方進房，只見兩個人扶着一位鬢髮如銀的老母迎上來，黛玉知是外祖母了，正欲下拜，早被外祖母抱住，摟入懷中，「心肝兒肉」叫着大哭起來。當下侍立之人無不下淚，黛玉也哭個不休，眾人慢慢解勸。那黛玉方拜見了外祖母，賈母方一一指與黛玉道︰「這是你大舅母，這是二舅母，這是你先前珠大哥的媳婦珠大嫂子。」黛玉一一拜見。賈母又叫︰「請姑娘們來！今日遠客來了，可以不必上學去。」眾人答應了一聲，便去了兩個。不一時，只見三個奶媽並五六個丫鬟擁着三位姑娘來了︰第一個，肌膚微豐，身材合中，腮凝新荔，鼻膩鵝脂，溫柔沉默，觀之可親；第二個，削肩細腰，長挑身材，鴨蛋臉兒，俊眼修眉，顧盼神飛，文彩精華，見之忘俗；第三個，身量未足，形容尚小；其釵環裙襖，三人皆是一樣的粧束。黛玉忙起身迎上來見禮，互相廝認，歸了坐位，丫鬟送上茶來，不過敍些黛玉之母如何得病，如何請醫服藥，如何送死發喪。不免賈母又傷感起來，因說︰「我這些女孩兒，所疼的獨有你母親，今一旦先我而亡，不得見面，怎不傷心！」說着，攜了黛玉的手，又哭起來。眾人都忙相勸慰，方略略止住。", "眾人見黛玉年紀雖小，其舉止言談不俗，身體面貌雖弱不勝衣，卻有一段風流態度，便知他有不足之症，因問︰「常服何藥？為何不治好了？」黛玉道︰「我自來如此，從會吃飯時便吃藥到如今了。經過多少名醫，總未見效。那一年我纔三歲，記得來了一個癩頭和尚，說要化我去出家，我父母自是不從。他又說︰『既捨不得他，但只怕他的病一生也不能好的！若要好時，除非從此以後總不許見哭聲，除父母之外，凡有外親，一概不見，方可平安了此一生。』這和尚瘋瘋癲癲說了這些不經之談，也沒人理他。如今還是吃人參養榮丸。」賈母道︰「這正好，我這裏正配丸藥呢，叫他們多配一料就是了。」", "一語未完，只聽後院中有笑語聲，說︰「我來遲了，沒得迎接遠客！」黛玉思忖道︰「這些人個個皆斂聲屏氣如此，這來者是誰，這樣放誕無禮？」心下想時，只見一羣媳婦、丫鬟擁着一個麗人，從後房進來。這個人打扮與姑娘們不同︰彩繡輝煌，恍若神妃仙子，頭上戴着金絲八寶攢珠髻，綰着朝陽五鳳掛珠釵，項上戴着赤金盤螭纓絡圈，身上穿着縷金百蝶穿花大紅雲緞窄褃襖，外罩五彩刻絲石青銀鼠褂，下著翡翠撒花洋縐裙；一雙丹鳳三角眼，兩彎柳葉掉梢眉，身量苗條，體格風騷，粉面含春威不露，丹唇未啟笑先聞。黛玉連忙起身接見，賈母笑道︰「你不認得他，他是我們這裏有名的一個潑辣貨，南京所謂『辣子』，你只叫他鳳辣子就是了。」黛玉正不知以何稱呼，眾姊妹都忙告訴黛玉道︰「這是璉二嫂子。」黛玉雖不曾識面，聽見他母親說過︰大舅賈赦之子賈璉，娶的就是二舅母王氏的內姪女，自幼假充男兒教養，學名叫做王熙鳳。黛玉忙陪笑見禮，以「嫂」呼之。這熙鳳攜着黛玉的手，上下細細打量一回，便仍送至賈母身邊坐下，因笑道︰「天下真有這樣標致人兒！我今日纔算看見了！況且這通身的氣派竟不像老祖宗的外孫女兒，竟是個嫡親的孫女兒似的，怨不得老祖宗天天嘴裏心裏放不下。只可憐我這妹妹這麼命苦，怎麼姑媽偏就去世了呢！」說着便用手帕拭淚，賈母笑道︰「我纔好了，你又來招我。你妹妹遠路纔來，身子又弱，也纔勸住了，快別再提了。」熙鳳聽了，忙轉悲為喜道︰「正是呢。我一見了妹妹，一心都在他身上，又是歡喜，又是傷心，竟忘了老祖宗了。該打，該打！」又忙拉着黛玉的手問道︰「妹妹幾歲了？可也上過學？現吃甚麼藥？在這裏別想家，要甚麼吃的、甚麼玩的，只管告訴我；丫頭老婆們不好，也只管告訴我。」黛玉一一答應。一面熙鳳又問人︰「林姑娘的東西可搬進來了？帶了幾個人來？你們趕早打掃兩間屋子叫他們歇歇兒去。」說話時，已擺了茶菓上來，熙鳳親自佈讓。又見二舅母問他︰「月錢放完了沒有？」熙鳳道︰「放完了。剛纔帶了人到後樓上找緞子，找了半日，也沒見昨兒太太說的那個，想必太太記錯了。」王夫人道︰「有沒有，甚麼要緊！」因又說道︰「該隨手拿出兩個來給你這妹妹裁衣裳啊。等晚上想着再叫人去拿罷。」熙鳳道︰「我倒先料着了，知道妹妹這兩日必到，我已經預備下了，等太太回去過了目好送來。」王夫人一笑，點頭不語。", "當下茶菓已撤，賈母命兩個老嬤嬤帶黛玉去見兩個舅舅去。維時賈赦之妻邢氏忙起身笑回道︰「我帶了外甥女兒過去，到底便宜些。」賈母笑道︰「正是呢。你也去罷，不必過來了。」那邢夫人答應了，遂帶着黛玉和王夫人作辭，大家送至穿堂。垂花門前，早有眾小廝拉過一輛翠幄青油車來，邢夫人攜了黛玉坐上，眾老婆們放下車簾，方命小廝們抬起，拉至寬處，駕上馴騾，出了西角門往東，過榮府正門，入一黑油漆大門內，至儀門前，方下了車。邢夫人挽着黛玉的手進入院中，黛玉度其處必是榮府中之花園隔斷過來的。進入三層儀門，果見正房、廂房、遊廊，悉皆小巧別致，不似那邊的軒峻壯麗，且院中隨處之樹木山石皆好。及進入正室，早有許多豔妝麗服之姬妾丫鬟迎着。邢夫人讓黛玉坐了，一面令人到外書房中請賈赦。一時回來說︰「老爺說了︰『連日身上不好，見了姑娘彼此傷心，暫且不忍相見。勸姑娘不必傷懷想家，跟着老太太和舅母，是和家裏一樣的。姐妹們雖拙，大家一處作伴，也可以解些煩悶。或有委屈之處，只管說，別外道了纔是。』」黛玉忙站起身來，一一答應了。再坐一刻，便告辭，邢夫人苦留吃過飯去，黛玉笑回道︰「舅母愛惜賜飯，原不應辭，只是還要過去拜見二舅舅，恐去遲了不恭，異日再領，望舅母容諒。」邢夫人道︰「這也罷了。」遂命兩個嬤嬤用方纔坐來的車送過去。於是黛玉告辭，邢夫人送至儀門前，又囑咐了眾人幾句，眼看着車去了方回來。", "一時黛玉進入榮府，下了車，只見一條大甬路，直接出大門來。眾嬤嬤引着，便往東轉彎，走過一座東西穿堂，向南大廳之後，儀門內大院落，上面五間大正房，兩邊廂房，鹿頂耳門鑽山，四通八達，軒昂壯麗，比各處不同，黛玉便知這方是正內室。進入堂屋，抬頭迎面先見一個赤金九龍青地大匾，匾上寫着斗大三個字，是︰「榮禧堂」，後有一行小字︰「某年月日書賜榮國公賈源」，又有「萬幾宸翰」之寶。大紫檀雕螭案上設着三尺多高青綠古銅鼎，懸着待漏隨朝墨龍大畫，一邊是鏨金彝，一邊是玻璃盆，地下兩溜十六張楠木圈椅，又有一副對聯，乃是烏木聯牌鑲着鏨金字跡，道是︰「座上珠璣昭日月，堂前黼黻煥烟霞。」下面一行小字是︰「世教弟勳襲東安郡王穆蒔拜手書」。", "原來王夫人時常居坐宴息也不在這正室中，只在東邊的三間耳房內，於是嬤嬤們引黛玉進東房門來。臨窗大炕上鋪着猩紅洋毯，正面設着大紅金線蟒引枕，秋香色金線蟒大條褥，兩邊設一對梅花式洋漆小几︰左邊几上擺着文王鼎，鼎旁匙筯香盒；右邊几上擺着汝窯美人觚，裏面插着時鮮花草。地下面西一溜四張大椅，都搭着銀紅撒花椅搭，底下四副腳踏；兩邊又有一對高几，几上茗碗瓶花俱備。其餘陳設，不必細說。老嬤嬤讓黛玉上炕坐，炕沿上卻也有兩個錦褥對設，黛玉度其位次，便不上炕，只就東邊椅上坐了。本房的丫鬟忙捧上茶來，黛玉一面吃了，打量這些丫鬟們妝飾衣裙，舉止行動，果與別家不同。", "茶未吃了，只見一個穿紅綾襖青紬掐牙背心的一個丫鬟走來笑道︰「太太說，請林姑娘到那邊坐罷。」老嬤嬤聽了，於是又引黛玉出來，到了東廊三間小正房內。正面炕上橫設一張炕桌，上面堆着書籍茶具，靠東壁面西設着半舊的青緞靠背引枕，王夫人卻坐在西邊下首，亦是半舊青緞靠背坐褥，見黛玉來了，便往東讓。黛玉心中料定這是賈政之位，因見挨炕一溜三張椅子上也搭着半舊的彈花椅袱，黛玉便向椅上坐了。王夫人再三讓他上炕，他方挨王夫人坐下。王夫人因說︰「你舅舅今日齋戒去了，再見罷。只是有一句話囑咐你，你三個姐妹倒都極好，以後一處念書認字，學針線，或偶一玩笑，都有個儘讓的。我就只一件不放心，我有一個孽根禍胎，是家裏的『混世魔王』，今日因往廟裏還願去，尚未回來，晚上你看見就知道了。你以後總不用理會他，你這些姐姐妹妹都不敢沾惹他的。」黛玉素聞母親說過，有個內姪乃啣玉而生，頑劣異常，不喜讀書，最喜在內幃廝混，外祖母又溺愛，無人敢管。今見王夫人所說，便知是這位表兄，一面陪笑道︰「舅母所說，可是啣玉而生的？在家時記得母親常說，這位哥哥比我大一歲，小名就叫寶玉，性雖憨頑，說待姊妹們卻是極好的。況我來了，自然和姊妹們一處，弟兄們是另院別房，豈有沾惹之理？」王夫人笑道︰「你不知道原故，他和別人不同，自幼因老太太疼愛，原係和姐妹們一處嬌養慣了的。若姐妹們不理他，他倒還安靜些；若一日姐妹們和他多說了一句話，他心上一喜，便生出許多事來。所以囑咐你別理會他，他嘴裏一時甜言蜜語，一時有天沒日，瘋瘋儍儍，只休信他。」黛玉一一的都答應着，忽見一個丫鬟來說︰「老太太那裏傳晚飯了。」王夫人忙攜了黛玉出後房門，由後廊往西，出了角門，是一條南北甬路，南邊是倒座三間小小抱廈廳，北邊立着一個粉油大影壁，後有一個半大門，小小一所房屋，王夫人笑指向黛玉道︰「這是你鳳姐姐的屋子，回來你好往這裏找他去，少甚麼東西只管和他說就是了。」這院門上也有幾個纔總角的小廝，都垂手侍立。", "王夫人遂攜黛玉穿過一個東西穿堂，便是賈母的後院了，於是進入後房門，已有許多人在此伺候，見王夫人來，方安設桌椅。賈珠之妻李氏捧杯，熙鳳安筯，王夫人進羹，賈母正面榻上獨坐。兩旁四張空椅，熙鳳忙拉黛玉在左邊第一張椅子上坐下，黛玉十分推讓，賈母笑道︰「你舅母和嫂子們是不在這裏吃飯的，你是客，原該這麼坐。」黛玉方告了坐，就坐了。賈母命王夫人也坐了。迎春姊妹三個告了坐，方上來，迎春坐右手第一，探春左第二，惜春右第二。旁邊丫鬟執着拂塵漱盂巾帕。李紈鳳姐立於案旁佈讓，外間伺候的媳婦丫鬟雖多，卻連一聲咳嗽不聞。飯畢，各各有丫鬟用小茶盤捧上茶來。當日林家教女以惜福養身，每飯後必過片時方吃茶，不傷脾胃；今黛玉見了這裏許多規矩，不似家中，也只得隨和着些，接了茶。又有人捧過漱盂來，黛玉也漱了口，又盥手畢，然後又捧上茶來，這方是吃的茶。賈母便說︰「你們去罷，讓我們自在說說話兒。」王夫人遂起身，又說了兩句閒話兒，方引李鳳二人去了。賈母因問黛玉念何書，黛玉道︰「剛念了《四書》。」黛玉又問姊妹們讀何書，賈母道︰「讀甚麼書，不過認幾個字罷了。」", "一語未了，只聽外面一陣腳步響，丫鬟進來報道︰「寶玉來了。」黛玉心想︰「這個寶玉不知是怎樣個憊懶人呢。」及至進來一看，卻是位青年公子，頭上戴着束髮嵌寶紫金冠，齊眉勒着二龍戲珠金抹額，一件二色金百蝶穿花大紅箭袖，束着五彩絲攢花結長穗宮縧，外罩石青起花八團倭緞排穗褂，登着青緞粉底小朝靴；面若中秋之月，色如春曉之花，鬢若刀裁，眉如墨畫，鼻如懸膽，睛若秋波，雖怒時而似笑，即瞋視而有情；項上金螭纓絡，又有一根五色絲縧，繫着一塊美玉。黛玉一見便吃一大驚，心中想道︰「好生奇怪！倒像在那裏見過的？何等眼熟！」只見這寶玉向賈母請了安，賈母便命︰「去見你娘來！」即轉身去了。一回再來時，已換了冠帶，頭上周圍一轉的短髮，都結成小辮，紅絲結束，共攢至頂中胎髮，總編一根大辮，黑亮如漆，從頂至梢，一串四顆大珠，用金八寶墜腳；身上穿着銀紅撒花半舊大襖，仍舊帶着項圈、寶玉、寄名鎖、護身符等物；下面半露松綠撒花綾褲，錦邊彈墨襪，厚底大紅鞋；越顯得面如傅粉，唇若施脂，轉盼多情，語言若笑；天然一段風韻，全在眉梢；平生萬種情思，悉堆眼角。看其外貌，最是極好，卻難知其底細，後人有《西江月》二詞，批的極確，詞曰︰", "無故尋愁覓恨，有時似儍如狂；縱然生得好皮囊，腹內原來草莽。潦倒不通庶務，愚頑怕讀文章；行為偏僻性乖張，那管世人誹謗！", "又曰︰"], "quote": ["且說黛玉自那日棄舟登岸時，便有榮府打發轎子並拉行李車輛伺候。這黛玉嘗聽得母親說，他外祖母家與別人家不同，他近日所見的這幾個三等的僕婦，吃穿用度，已是不凡，何況今至其家，都要步步留心，時時在意，不要多說一句話，不可多行一步路，恐被人恥笑了去。自上了轎，進了城，從紗窗中瞧了一瞧，其街市之繁華，人烟之阜盛，自非別處可比。又行了半日，忽見街北蹲着兩個大石獅子，三間獸頭大門，門前列坐着十來個華冠麗服之人。正門不開，只東西兩角門有人出入。正門之上有一匾，匾上大書「勅造寧國府」五個大字。黛玉想道︰「這是外祖的長房了。」又往西不遠，照樣也是三間大門，方是榮國府，卻不進正門，只由西角門而進。轎子抬着走了一箭之遠，將轉彎時，便歇了轎，後面的婆子也都下來了，另換了四個眉目秀潔的十七八歲的小廝上來抬着轎子，眾婆子步下跟隨，至一垂花門前落下，那小廝俱肅然退出，眾婆子上前打起轎簾，扶黛玉下了轎。黛玉扶着婆子的手，進了垂花門。兩邊是超手遊廊，正中是穿堂，當地放着一個紫檀架子大理石屏風。轉過屏風，小小三間廳房，廳後便是正房大院。正面五間上房，皆是雕梁畫棟。兩邊穿山遊廊廂房，掛着各色鸚鵡畫眉等雀鳥。台階上坐着幾個穿紅著綠的丫頭，一見他們來了，都笑迎上來，道︰「剛纔老太太還念誦呢！可巧就來了。」於是三四人爭着打簾子。一面聽得人說︰「林姑娘來了！」", "黛玉方進房，只見兩個人扶着一位鬢髮如銀的老母迎上來，黛玉知是外祖母了，正欲下拜，早被外祖母抱住，摟入懷中，「心肝兒肉」叫着大哭起來。當下侍立之人無不下淚，黛玉也哭個不休，眾人慢慢解勸。那黛玉方拜見了外祖母，賈母方一一指與黛玉道︰「這是你大舅母，這是二舅母，這是你先前珠大哥的媳婦珠大嫂子。」黛玉一一拜見。賈母又叫︰「請姑娘們來！今日遠客來了，可以不必上學去。」眾人答應了一聲，便去了兩個。不一時，只見三個奶媽並五六個丫鬟擁着三位姑娘來了︰第一個，肌膚微豐，身材合中，腮凝新荔，鼻膩鵝脂，溫柔沉默，觀之可親；第二個，削肩細腰，長挑身材，鴨蛋臉兒，俊眼修眉，顧盼神飛，文彩精華，見之忘俗；第三個，身量未足，形容尚小；其釵環裙襖，三人皆是一樣的粧束。黛玉忙起身迎上來見禮，互相廝認，歸了坐位，丫鬟送上茶來，不過敍些黛玉之母如何得病，如何請醫服藥，如何送死發喪。不免賈母又傷感起來，因說︰「我這些女孩兒，所疼的獨有你母親，今一旦先我而亡，不得見面，怎不傷心！」說着，攜了黛玉的手，又哭起來。眾人都忙相勸慰，方略略止住。", "眾人見黛玉年紀雖小，其舉止言談不俗，身體面貌雖弱不勝衣，卻有一段風流態度，便知他有不足之症，因問︰「常服何藥？為何不治好了？」黛玉道︰「我自來如此，從會吃飯時便吃藥到如今了。經過多少名醫，總未見效。那一年我纔三歲，記得來了一個癩頭和尚，說要化我去出家，我父母自是不從。他又說︰『既捨不得他，但只怕他的病一生也不能好的！若要好時，除非從此以後總不許見哭聲，除父母之外，凡有外親，一概不見，方可平安了此一生。』這和尚瘋瘋癲癲說了這些不經之談，也沒人理他。如今還是吃人參養榮丸。」賈母道︰「這正好，我這裏正配丸藥呢，叫他們多配一料就是了。」", "一語未完，只聽後院中有笑語聲，說︰「我來遲了，沒得迎接遠客！」黛玉思忖道︰「這些人個個皆斂聲屏氣如此，這來者是誰，這樣放誕無禮？」心下想時，只見一羣媳婦、丫鬟擁着一個麗人，從後房進來。這個人打扮與姑娘們不同︰彩繡輝煌，恍若神妃仙子，頭上戴着金絲八寶攢珠髻，綰着朝陽五鳳掛珠釵，項上戴着赤金盤螭纓絡圈，身上穿着縷金百蝶穿花大紅雲緞窄褃襖，外罩五彩刻絲石青銀鼠褂，下著翡翠撒花洋縐裙；一雙丹鳳三角眼，兩彎柳葉掉梢眉，身量苗條，體格風騷，粉面含春威不露，丹唇未啟笑先聞。黛玉連忙起身接見，賈母笑道︰「你不認得他，他是我們這裏有名的一個潑辣貨，南京所謂『辣子』，你只叫他鳳辣子就是了。」黛玉正不知以何稱呼，眾姊妹都忙告訴黛玉道︰「這是璉二嫂子。」黛玉雖不曾識面，聽見他母親說過︰大舅賈赦之子賈璉，娶的就是二舅母王氏的內姪女，自幼假充男兒教養，學名叫做王熙鳳。黛玉忙陪笑見禮，以「嫂」呼之。這熙鳳攜着黛玉的手，上下細細打量一回，便仍送至賈母身邊坐下，因笑道︰「天下真有這樣標致人兒！我今日纔算看見了！況且這通身的氣派竟不像老祖宗的外孫女兒，竟是個嫡親的孫女兒似的，怨不得老祖宗天天嘴裏心裏放不下。只可憐我這妹妹這麼命苦，怎麼姑媽偏就去世了呢！」說着便用手帕拭淚，賈母笑道︰「我纔好了，你又來招我。你妹妹遠路纔來，身子又弱，也纔勸住了，快別再提了。」熙鳳聽了，忙轉悲為喜道︰「正是呢。我一見了妹妹，一心都在他身上，又是歡喜，又是傷心，竟忘了老祖宗了。該打，該打！」又忙拉着黛玉的手問道︰「妹妹幾歲了？可也上過學？現吃甚麼藥？在這裏別想家，要甚麼吃的、甚麼玩的，只管告訴我；丫頭老婆們不好，也只管告訴我。」黛玉一一答應。一面熙鳳又問人︰「林姑娘的東西可搬進來了？帶了幾個人來？你們趕早打掃兩間屋子叫他們歇歇兒去。」說話時，已擺了茶菓上來，熙鳳親自佈讓。又見二舅母問他︰「月錢放完了沒有？」熙鳳道︰「放完了。剛纔帶了人到後樓上找緞子，找了半日，也沒見昨兒太太說的那個，想必太太記錯了。」王夫人道︰「有沒有，甚麼要緊！」因又說道︰「該隨手拿出兩個來給你這妹妹裁衣裳啊。等晚上想着再叫人去拿罷。」熙鳳道︰「我倒先料着了，知道妹妹這兩日必到，我已經預備下了，等太太回去過了目好送來。」王夫人一笑，點頭不語。"], "intro": "《接外孫賈母惜孤女》節選自《紅樓夢》第三回，篇名是第三回「託內兄如海薦西賓 接外孫賈母惜孤女」的下半回目。《紅樓夢》描寫的賈府是金陵世家大族，分為兩房，世襲「寧國公」和「榮國公」兩個官位。書中主要寫「榮國府」，該府由兩兄弟賈赦和賈政主持，而", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%B4%85%E6%A8%93%E5%A4%A2%E3%83%BB%E6%8E%A5%E5%A4%96%E5%AD%AB%E8%B3%88%E6%AF%8D%E6%83%9C%E5%AD%A4%E5%A5%B3"}, {"title": "為學一首示子姪", "author": "彭端淑", "period": "清", "form": "文", "theme": "詠史哲思", "mood": "vast_river", "lines": ["天下事有難易乎？為之，則難者亦易矣；不為，則易者亦難矣。人之為學有難易乎？學之，則難者亦易矣；不學，則易者亦難矣。", "吾資之昏，不逮人也；吾材之庸，不逮人也。旦旦而學之，久而不怠焉；迄乎成，而亦不知其昏與庸也。吾資之聰，倍人也；吾材之敏，倍人也。", "屏棄而不用，其昏與庸，無以異也。聖人之道，卒於魯也傳之。然則昏、庸、聰、敏之用，豈有常哉？", "蜀之鄙，有二僧︰其一貧，其一富。貧者語於富者曰︰「吾欲之南海，何如？」富者曰︰「子何恃而往？」曰︰「吾一瓶一缽足矣。」富者曰︰「吾數年來欲買舟而下，猶未能也。子何恃而往！」", "越明年，貧者自南海還，以告富者，富者有慚色。西蜀之去南海，不知幾千里也，僧富者不能至，而貧者至焉。人之立志，顧不如蜀鄙之僧哉？", "是故聰與敏，可恃而不可恃也；自恃其聰與敏而不學者，自敗者也。昏與庸，可限而不可限也；不自限其昏與庸，而力學不倦者，自力者也。"], "quote": ["天下事有難易乎？為之，則難者亦易矣；不為，則易者亦難矣。人之為學有難易乎？學之，則難者亦易矣；不學，則易者亦難矣。", "吾資之昏，不逮人也；吾材之庸，不逮人也。旦旦而學之，久而不怠焉；迄乎成，而亦不知其昏與庸也。吾資之聰，倍人也；吾材之敏，倍人也。", "屏棄而不用，其昏與庸，無以異也。聖人之道，卒於魯也傳之。然則昏、庸、聰、敏之用，豈有常哉？", "蜀之鄙，有二僧︰其一貧，其一富。貧者語於富者曰︰「吾欲之南海，何如？」富者曰︰「子何恃而往？」曰︰「吾一瓶一缽足矣。」富者曰︰「吾數年來欲買舟而下，猶未能也。子何恃而往！」"], "intro": "本文是作者教訓他的子姪們的一封家書。文中講的是研究學問的問題，所以稱做「為學」。一首，是一篇的意思。示子姪，是給子姪們看。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%82%BA%E5%AD%B8%E4%B8%80%E9%A6%96%E7%A4%BA%E5%AD%90%E5%A7%AA"}, {"title": "復彭麗生書", "author": "曾國藩", "period": "清", "form": "文", "theme": "山水登臨", "mood": "autumn_sunset", "lines": ["前承惠書，存唁不孝；頃又蒙手書，所以期勖故人，甚篤且勤。國藩積愆叢慝，無實行而盜虛聲，為神明所不容；乃不隕滅我躬，而禍延於吾母。椎心悔憾，蓋不得自比於人類，其又何經濟之足言？", "顧如足下所稱︰「今日不可救藥之端，惟在人心陷溺，絕無廉恥」云云，則國藩之私見，實與賢者相脗合。", "竊嘗以為無兵不足深憂，無餉不足痛哭。獨舉目斯世，求一攘利不先，赴義恐後，忠憤耿耿者，不可亟得；或僅得之，而又屈居卑下，往往抑鬱不伸，以挫，以去，以死。", "而貪饕、退縮者，果驤首而上騰，而富貴，而名譽，而老健不死。此其可為浩歎者也！足下與某公書，言之至為深痛。積年痒疥，為君一搔，憂患餘生，得少快慰。", "國藩來此，蓋以鄂中失守，恐其回竄，不得不出，以自別於畏死者之徒。至於求有補濟，則骯髒之性，將以方枘周旋於圓鑿之中，亦知其鉏鋙而鮮當矣。", "刻下所志，惟在練兵、除暴二事︰練兵、則猶七年之病，求三年之艾；除暴，則借一方之良，鋤一方之莠。故急訪公正紳耆，佐我不逮先與以一書，然後剴切示諭之。", "年來飽更世故，又經憂患，齒髮稍侵，精神頹敗。幸故人一來顧我，相對敍論，收召散亡之魂魄，祓濯如山之塵垢，庶生新機而還舊識；即拯時艱於萬一，亦未可知。", "郭筠仙、劉霞仙、羅羅山，及平日交舊，都來此間︰尚望足下惠然命駕，無任佇企！"], "quote": ["前承惠書，存唁不孝；頃又蒙手書，所以期勖故人，甚篤且勤。國藩積愆叢慝，無實行而盜虛聲，為神明所不容；乃不隕滅我躬，而禍延於吾母。椎心悔憾，蓋不得自比於人類，其又何經濟之足言？", "顧如足下所稱︰「今日不可救藥之端，惟在人心陷溺，絕無廉恥」云云，則國藩之私見，實與賢者相脗合。", "竊嘗以為無兵不足深憂，無餉不足痛哭。獨舉目斯世，求一攘利不先，赴義恐後，忠憤耿耿者，不可亟得；或僅得之，而又屈居卑下，往往抑鬱不伸，以挫，以去，以死。", "而貪饕、退縮者，果驤首而上騰，而富貴，而名譽，而老健不死。此其可為浩歎者也！足下與某公書，言之至為深痛。積年痒疥，為君一搔，憂患餘生，得少快慰。"], "intro": "這是作者回覆他的朋友彭麗生的一封書信。那時作者適丁母憂，太平軍起，奉命在籍督辦團練。彭麗生寫給作者的信中，曾談到當時國家的病根所在，並對作者備致期許之意。作者這封覆信，就是針對來書所提出的問題，表示了自己對於國事的關切， 以及不得不出任艱鉅", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%BE%A9%E5%BD%AD%E9%BA%97%E7%94%9F%E6%9B%B8"}, {"title": "諭子紀鴻", "author": "曾國藩", "period": "清", "form": "文", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["字諭紀鴻兒︰家中之來營者，多稱爾舉止大方，余為少慰。凡人多望子孫為大官，余不望為大官，但願為讀書明理之君子。勤儉自持，習勞習苦，可以處樂，可以處約，此君子也。", "余服官二十年，不敢稍染官宦氣習，飲食、起居，尚守寒素家風。極儉也可，略豐也可，太豐則我不敢也。凡仕宦之家，由儉入奢易，由奢返儉難。爾年尚幼，切不可貪愛奢華，不可慣習懶惰。", "無論大家小家，士農工商，勤苦儉約，未有不興；驕奢倦怠，未有不敗。", "爾讀書寫字，不可間斷。早晨要早起，莫墜高曾祖考以來相傳之家風。吾父吾叔皆黎明即起，爾之所知也。", "凡富貴功名，皆有命定，半由人力，半由天事；惟學作聖賢，全由自己作主，不與天命相干涉。吾有志學為聖賢，少時欠居敬工夫，至今猶不免偶有戲言、戲動。爾宜舉止端莊，言不妄發，則入德之基也。"], "quote": ["字諭紀鴻兒︰家中之來營者，多稱爾舉止大方，余為少慰。凡人多望子孫為大官，余不望為大官，但願為讀書明理之君子。勤儉自持，習勞習苦，可以處樂，可以處約，此君子也。", "余服官二十年，不敢稍染官宦氣習，飲食、起居，尚守寒素家風。極儉也可，略豐也可，太豐則我不敢也。凡仕宦之家，由儉入奢易，由奢返儉難。爾年尚幼，切不可貪愛奢華，不可慣習懶惰。", "無論大家小家，士農工商，勤苦儉約，未有不興；驕奢倦怠，未有不敗。", "爾讀書寫字，不可間斷。早晨要早起，莫墜高曾祖考以來相傳之家風。吾父吾叔皆黎明即起，爾之所知也。"], "intro": "這是作者寫給他的次子紀鴻的一封家書。曾紀鴻，字栗誠，年少好學，最精代數。作者於同治年間去世後，紀鴻得賞給舉人，後於光緒初年早卒。他曾用「格列高里級數」（Gregory’s Series）求圓周率的值到百位，著有《對數詳解》《圓率考真圖解》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%AB%AD%E5%AD%90%E7%B4%80%E9%B4%BB"}, {"title": "都門秋思（其二）", "author": "黃仲則", "period": "清", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["五劇車聲隱若雷，北邙惟見塚千堆。", "夕陽勸客登樓去，山色將秋遶郭來。", "寒甚更無修竹倚，愁多思買白楊栽。", "全家都在風聲裏，九月衣裳未剪裁。"], "quote": ["五劇車聲隱若雷，北邙惟見塚千堆。", "夕陽勸客登樓去，山色將秋遶郭來。", "寒甚更無修竹倚，愁多思買白楊栽。", "全家都在風聲裏，九月衣裳未剪裁。"], "intro": "這首詩是乾隆四十二年秋，作者二十九歲在北京任四庫館校錄時所作。當時由於微薄薪資不足以維持一家人生計，不得不常靠朋友的賙濟。生活的窘迫，仕途的蹭蹬，致詩人寫出了四首讀來迴腸盪氣，悽惻感人的作品。這首是第二首。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%83%BD%E9%96%80%E7%A7%8B%E6%80%9D%EF%BC%88%E5%85%B6%E4%BA%8C%EF%BC%89"}, {"title": "雜感", "author": "黃仲則", "period": "清", "form": "詩", "theme": "春水花鳥", "mood": "autumn_sunset", "lines": ["仙佛茫茫兩未成，祇知獨夜不平鳴。", "風蓬飄盡悲歌氣，泥絮沾來薄倖名。", "十有九人堪白眼，百無一用是書生。", "莫因詩卷愁成讖，春鳥秋蟲自作聲。"], "quote": ["仙佛茫茫兩未成，祇知獨夜不平鳴。", "風蓬飄盡悲歌氣，泥絮沾來薄倖名。", "十有九人堪白眼，百無一用是書生。", "莫因詩卷愁成讖，春鳥秋蟲自作聲。"], "intro": "清代乾隆年間，四海昇平，民豐物阜。科舉盛行，士子重視八股文（時文）考試，自童試、鄉試、會試、殿試，層層考核，花費考生畢生精力，仍無法中舉。黃仲則就是一位典型落榜的書生，屢試屢敗，無法進士及第，沈淪下僚，鬱鬱以終。《雜感》是黃仲則詩歌中一首抒", "url": "https://www.classicalchineseliterature.org/article.php?article=%E9%9B%9C%E6%84%9F%C2%A0"}, {"title": "柳敬亭傳", "author": "黃宗羲", "period": "清", "form": "文", "theme": "春水花鳥", "mood": "autumn_sunset", "lines": ["余讀《東京夢華錄》、《武林舊事記》，當時演史小說者數十人。自此以來，其姓名不可得聞，乃近年共稱柳敬亭之說書。", "柳敬亭者，揚之泰州人，本姓曹。年十五，獷悍無賴，犯法當死；變姓柳，之盱眙市中，為人說書，已能傾動其市人。久之過江，雲間有儒生莫後光見之，曰︰「此子機變，可使以其技鳴。」於是謂之曰︰「說書雖小技，然必拘性情，習方俗，如優孟搖頭而歌，而後可以得志。」", "敬亭退而凝神定氣，簡練揣摩，期月而詣莫生。生曰︰「子之說，能使人咍驩、嗢噱矣。」又期月，生曰︰「子之說，能使人慷慨、涕泣矣。」又期月，生喟然曰︰「子言末發，而哀樂具乎其前，使人之性情不能自主，蓋進乎技矣！」", "由是之揚，之杭，之金陵，名達於搢紳間。華堂旅會，閒亭獨坐，爭延之，使奏其技，無不當於心，稱善也。", "寧南南下，皖帥欲結歡寧南，致敬亭於幕府。寧南以為相見之晚，使參機密；軍中亦不敢以說書目敬亭。寧南不知書，所有文檄，幕下儒生，設意修飾，援古證今，極力為之，寧南皆不悅；而敬亭耳剽口熟，從委巷話套中來者，無不與寧南意合。", "嘗奉命至金陵，是時朝中皆畏寧南，聞其使人來，莫不傾動加禮，宰執以下，俱使之南面上坐，稱柳將軍；敬亭亦無所不安也。其市井小人，昔與敬亭爾汝者，從道旁私語︰「此故吾儕同說書者也，今富貴若此！」", "亡何，國變，寧南死，敬亭喪失其資略盡，貧困如故時，始復於街頭理其舊業。敬亭既在軍中久，其豪猾大俠，殺人亡命，流離遇合，破家失國之事，無不身親見之；且五方土音，鄉俗好尚，習見習聞。", "每發一聲，使人聞之，或如刀劍鐵騎，颯然浮空；或如風號雨泣，鳥悲獸駭；亡國之恨頓生，檀板之聲無色，有非莫生之言可盡者矣！"], "quote": ["余讀《東京夢華錄》、《武林舊事記》，當時演史小說者數十人。自此以來，其姓名不可得聞，乃近年共稱柳敬亭之說書。", "柳敬亭者，揚之泰州人，本姓曹。年十五，獷悍無賴，犯法當死；變姓柳，之盱眙市中，為人說書，已能傾動其市人。久之過江，雲間有儒生莫後光見之，曰︰「此子機變，可使以其技鳴。」於是謂之曰︰「說書雖小技，然必拘性情，習方俗，如優孟搖頭而歌，而後可以得志。」", "敬亭退而凝神定氣，簡練揣摩，期月而詣莫生。生曰︰「子之說，能使人咍驩、嗢噱矣。」又期月，生曰︰「子之說，能使人慷慨、涕泣矣。」又期月，生喟然曰︰「子言末發，而哀樂具乎其前，使人之性情不能自主，蓋進乎技矣！」", "由是之揚，之杭，之金陵，名達於搢紳間。華堂旅會，閒亭獨坐，爭延之，使奏其技，無不當於心，稱善也。"], "intro": "柳敬亭，是明末的一個說書人，滿面㿬瘤，貌奇醜，號「柳麻子」；但善弄權譎，頗能顛倒當時王公大人，一時極負盛名。明末文人如吳偉業、張岱等也寫有他的傳記。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E6%9F%B3%E6%95%AC%E4%BA%AD%E5%82%B3"}, {"title": "聊齋志異・種梨", "author": "蒲松齡", "period": "清", "form": "小說", "theme": "詠史哲思", "mood": "spring_breeze", "lines": ["有鄉人貨梨於市，頗甘芳，價騰貴。有道士破巾絮衣，丐於車前。鄉人咄之而不去；鄉人怒，加以叱罵。道士曰︰「一車數百顆，老衲止丐其一，於居士亦無大損，何怒為？」觀者勸置劣者一枚令去，鄉人執不肯。", "肆中傭保者，見喋聒不堪，遂出錢市一枚，付道士。道士拜謝，謂眾曰︰「出家人不解吝惜。我有佳梨，請出供客。」或曰︰「既有之，何不自食？」曰︰「吾特需此核作種。」於是掬梨大啗。", "且盡，把核於手，解肩上鑱，坎地上深數寸，納之而覆以土。向市人索湯沃灌。好事者於臨路店索得沸瀋，道士接浸坎處。萬目攢視，見有勾萌出，漸大；俄成樹，枝葉扶疎；倏而花，倏而實，碩大芳馥，纍纍滿樹。", "道士乃即樹頭摘賜觀者，頃刻向盡。已，乃以鑱伐樹，丁丁良久，方斷。帶葉荷肩頭，從容徐步而去。", "初，道士作法時，鄉人亦雜眾中，引領注目，竟忘其業。道士既去，始顧車中，則梨已空矣，方悟適所俵散，皆己物也。又細視車上一靶亡，是新鑿斷者。心大憤恨。急跡之，轉過牆隅，則斷靶棄垣下，始知所伐梨本，即是物也。道士不知所在。一市粲然。", "異史氏曰︰「鄉人憒憒，憨狀可掬，其見笑於市人，有以哉。每見鄉中稱素封者，良朋乞米則怫然，且計曰︰『是數日之資也。』或勸濟一危難，飯一煢獨，則又忿然計曰︰『此十人、五人之食也。』甚而父子兄弟，較盡錙銖。", "及至淫博迷心，則傾囊不吝；刀鋸臨頸，則贖命不遑。諸如此類，正不勝道，蠢爾鄉人，又何足怪。」"], "quote": ["有鄉人貨梨於市，頗甘芳，價騰貴。有道士破巾絮衣，丐於車前。鄉人咄之而不去；鄉人怒，加以叱罵。道士曰︰「一車數百顆，老衲止丐其一，於居士亦無大損，何怒為？」觀者勸置劣者一枚令去，鄉人執不肯。", "肆中傭保者，見喋聒不堪，遂出錢市一枚，付道士。道士拜謝，謂眾曰︰「出家人不解吝惜。我有佳梨，請出供客。」或曰︰「既有之，何不自食？」曰︰「吾特需此核作種。」於是掬梨大啗。", "且盡，把核於手，解肩上鑱，坎地上深數寸，納之而覆以土。向市人索湯沃灌。好事者於臨路店索得沸瀋，道士接浸坎處。萬目攢視，見有勾萌出，漸大；俄成樹，枝葉扶疎；倏而花，倏而實，碩大芳馥，纍纍滿樹。", "道士乃即樹頭摘賜觀者，頃刻向盡。已，乃以鑱伐樹，丁丁良久，方斷。帶葉荷肩頭，從容徐步而去。"], "intro": "《種梨》是一篇文言短篇小說，選自蒲松齡《聊齋志異》卷一。故事寫道士在市集施展幻術，在頃刻間種出結滿甜美果實的梨樹，懲戒吝惜而態度惡劣的賣梨小販。 《聊齋志異》中的故事並不全部是由蒲松齡自行編造，有一些來自古書或民間故事。蒲松齡自稱「雅愛搜神", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%81%8A%E9%BD%8B%E5%BF%97%E7%95%B0%E3%83%BB%E7%A8%AE%E6%A2%A8"}, {"title": "竹石", "author": "鄭燮", "period": "清", "form": "詩", "theme": "田園幽居", "mood": "majestic_peaks", "lines": ["咬定青山不放鬆，立根原在破巖中。", "千磨萬擊還堅勁，任爾東西南北風。"], "quote": ["咬定青山不放鬆，立根原在破巖中。", "千磨萬擊還堅勁，任爾東西南北風。"], "intro": "《竹石》選自《鄭板橋集‧題畫》。作者雖涉足仕途，卻鬱鬱不得志。他在書法和繪畫所獲得的成功，使其本來就「落拓不羈」的性情顯得更狂傲，不肯與世俗同流。這首七言絕句約作於乾隆十六年（一七五一）濰縣知縣任上，當時板橋已經在任十年，對官場的黑暗深為不", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%AB%B9%E7%9F%B3"}, {"title": "詠雪", "author": "鄭燮", "period": "清", "form": "詩", "theme": "歲時雪月", "mood": "snow_winter", "lines": ["一片兩片三四片，", "五六七八九十片。", "千片萬片無數片，", "飛入梅花都不見。"], "quote": ["一片兩片三四片，", "五六七八九十片。", "千片萬片無數片，", "飛入梅花都不見。"], "intro": "據說鄭板橋初到揚州時非常窮困，有一天大雪紛飛，他冒雪外出，路上遇上一群讀書人在吟詩。他們見鄭板橋穿着粗衣布履，以為他不懂作詩，便故意刁難。結果鄭板橋吟出這首詩，令這群讀書人甘拜下風。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A9%A0%E9%9B%AA"}, {"title": "問說", "author": "劉開", "period": "清", "form": "文", "theme": "詠史哲思", "mood": "heroic", "lines": ["君子之學必好問。問與學，相輔而行者也︰非學，無以致疑，非問，無以廣識。好學而不勤問，非真能好學者也。理明矣，而或不達於事；識其大矣，而或不知其細；舍問，其奚決焉？", "賢於己者，問焉以破其疑，所謂「就有道而正」也。不如己者，問焉以求一得，所謂「以能問於不能，以多問於寡」也。等於己者，問焉以資切磋，所謂交相問難，「審問而明辨之」也。", "《書》不云乎？「好問則裕。」孟子論求放心，而並稱之曰學問之道，學即繼以問也；子思言尊德性而歸於道問學，問且先於學也。", "古之人，虛衷樂善，不擇事而問焉，不擇人而問焉，取其有益於身而已。是故狂夫之言，聖人擇之；芻蕘之微，先民詢之。舜以天子而詢於匹夫，以大知而察及邇言，非苟為謙，誠取善之宏也。", "三代而下，有學無問，朋友之交，至於勤善規過，足矣；其以義理相咨訪，孜孜焉惟進修是急，未之多見也。況流俗乎？", "是己而非人，俗之同病，學猶未達，強以為知；理有未安，妄以臆度，如是，則終身幾無可問之事。賢於己者，忌之而不願問焉；不如己者，輕之而不屑問焉；等於己者，狎之而不甘問焉，如是，則天下幾無可問之人。", "人不足服矣，事無可疑矣，此惟師心自用耳。夫自用，其小者也；自知其陋而謹護其失，寧使學終不進，不欲虛以下人，此為害於心術者大，而蹈之者常十之八九。", "不然，則所問非所學焉︰詢天下之異文鄙事以快言論；甚且心之所已明者，問之人以試其能；事之至難解者，問之人以窮其短。而非是者，雖有切於身心性命之事，可以收取善益，求一屈己焉而不可得也。", "嗟乎！學之所以不能幾於古者，非此之由乎？", "且夫不好問者，由心不能虛，心之不虛，由好學之不誠也，非謂不潛心專力之故；其學非古人之學，而好非古人之好也；不能問，宜也。", "智者千慮，必有一失。聖人所不知，未必不為愚人之所知也；愚人之所能，未必非聖人之所不能也。理無專在，而學無止境也。", "《周禮》外朝以詢萬民，國之政事，而問庶人；是故貴可以問賤，賢可以問不肖，而老可以問幼，惟道之所成而已矣。"], "quote": ["君子之學必好問。問與學，相輔而行者也︰非學，無以致疑，非問，無以廣識。好學而不勤問，非真能好學者也。理明矣，而或不達於事；識其大矣，而或不知其細；舍問，其奚決焉？", "賢於己者，問焉以破其疑，所謂「就有道而正」也。不如己者，問焉以求一得，所謂「以能問於不能，以多問於寡」也。等於己者，問焉以資切磋，所謂交相問難，「審問而明辨之」也。", "《書》不云乎？「好問則裕。」孟子論求放心，而並稱之曰學問之道，學即繼以問也；子思言尊德性而歸於道問學，問且先於學也。", "古之人，虛衷樂善，不擇事而問焉，不擇人而問焉，取其有益於身而已。是故狂夫之言，聖人擇之；芻蕘之微，先民詢之。舜以天子而詢於匹夫，以大知而察及邇言，非苟為謙，誠取善之宏也。"], "intro": "學問一詞，一般作為求學所得到的知識來解釋；本文把這一名詞分為「學」與「問」兩事，專指求學問的方法而言，並單就問字立論發揮，所以題為「問說」。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%95%8F%E8%AA%AA"}, {"title": "習慣說", "author": "劉蓉", "period": "清", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["蓉少時，讀書養晦堂之西偏一室。俛而讀，仰而思；思有弗得，輒起，繞室以旋。室有窪徑尺，浸淫日廣。每履之，足苦躓焉；既久而遂安之。", "一日父來室中，顧而笑曰︰「一室之不治，何以天下家國為？」命童子取土平之。", "後蓉履其地，蹴然以驚，如土忽隆起者；俯視地，坦然則既平矣。已而復然，又久而後安之。", "噫！習之中人甚矣哉！足履平地，不與窪適也；及其久，而漥者若平。至使久而即乎其故，則反窒焉而不寧。故君子之學，貴慎始。"], "quote": ["蓉少時，讀書養晦堂之西偏一室。俛而讀，仰而思；思有弗得，輒起，繞室以旋。室有窪徑尺，浸淫日廣。每履之，足苦躓焉；既久而遂安之。", "一日父來室中，顧而笑曰︰「一室之不治，何以天下家國為？」命童子取土平之。", "後蓉履其地，蹴然以驚，如土忽隆起者；俯視地，坦然則既平矣。已而復然，又久而後安之。", "噫！習之中人甚矣哉！足履平地，不與窪適也；及其久，而漥者若平。至使久而即乎其故，則反窒焉而不寧。故君子之學，貴慎始。"], "intro": "習和慣這兩個字是一個意思，對於某一種事情熟練了以後，不知不覺地就自然成了一個常例，便叫做「習」或「慣」。兩字連輟到一塊，就構成一個同義聯合複名詞，意義並沒有變。普通我們說某人的習慣，也可以說是某人積久養成的一種性質。《書經》說：「習與性成」", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%BF%92%E6%85%A3%E8%AA%AA"}, {"title": "老殘遊記・大明湖", "author": "劉鶚", "period": "清", "form": "小說", "theme": "江河湖海", "mood": "snow_winter", "lines": ["老殘動身上車，一路秋山紅葉，老圃黃花，頗不寂寞。到了濟南府，進得城來，家家泉水，戶戶垂楊，比那江南風景，覺得更為有趣。", "到了小布政司街，覓了一家客店，名叫高陞店，將行李卸下，開發了車價酒錢，胡亂吃點晚飯，也就睡了。", "次日清晨起來，喫點兒點心，便搖着串鈴，滿街踅了一趟，午後步行至鵲華橋邊，雇了一隻小船，盪起雙槳，朝北不遠，便到歷下亭前。下船進去，入了大門，便是一個亭子，油漆已大半剝蝕。亭子上懸了一幅對聯，寫的是︰", "「歷下此亭古，", "濟南名士多。」", "上寫着「杜工部句」，下寫着「道州何紹基書」。亭子旁邊，雖有幾間房屋，也沒有甚麼意思。", "復行上船，向西盪去，不甚遠，又到了鐵公祠畔，——你道鐵公是誰？就是明初與燕王為難的那個鐵鉉。後人敬他的忠義，所以至今春秋時節，士人尚不斷的來此進香。——到了鐵公祠前，朝南一望，只見對面千佛山上的梵宇僧樓，與那蒼松翠柏，高下相間；紅的火紅，白的雪白，青的靛青，綠的碧綠，更有那一株半株的丹楓，夾在裏面，彷彿宋人趙千里的一幅大畫，做了一架數十里長的屏風。", "正在嘆賞不斷，忽聽一聲漁唱；低頭看去，誰知那大明湖業已澄淨的同鏡子一般。那千佛山的倒影映在湖裏，顯得明明白白。那樓臺樹木，格外光彩；覺得比上頭的千佛山還要好看，還要清楚。", "這湖的南岸上去，便是街市，卻有一層蘆葦，密密遮住。現在正是開花的時候，一片白花映着帶水氣的斜陽︰好似一條粉紅絨毯，做了上下兩個山的墊子，實在奇絕。", "老殘心裏想道︰「如此佳景，為何沒有甚麼遊人？」看了一會兒，回轉身來，看那祠裏面，楹柱上有副對聯，寫的是︰", "「四面荷花三面柳，", "一城山色半城湖。」"], "quote": ["老殘動身上車，一路秋山紅葉，老圃黃花，頗不寂寞。到了濟南府，進得城來，家家泉水，戶戶垂楊，比那江南風景，覺得更為有趣。", "到了小布政司街，覓了一家客店，名叫高陞店，將行李卸下，開發了車價酒錢，胡亂吃點晚飯，也就睡了。", "次日清晨起來，喫點兒點心，便搖着串鈴，滿街踅了一趟，午後步行至鵲華橋邊，雇了一隻小船，盪起雙槳，朝北不遠，便到歷下亭前。下船進去，入了大門，便是一個亭子，油漆已大半剝蝕。亭子上懸了一幅對聯，寫的是︰", "「歷下此亭古，"], "intro": "《老殘遊記》是劉鶚寫的一部章回體遊記小說。書中主人翁姓鐵名英，號老殘，藉行醫各地，由其所見所聞，反映當時政治社會的實況。但這位老殘，實是作者自己的託名，所寫風景經歷，也都帶着自傳的性質。初編二十回，曾於光緒年間，先後發表於《繡像小說半月刊》", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%80%81%E6%AE%98%E9%81%8A%E8%A8%98%E3%83%BB%E5%A4%A7%E6%98%8E%E6%B9%96"}, {"title": "貓捕雀", "author": "薛福成", "period": "清", "form": "文", "theme": "田園幽居", "mood": "ethereal", "lines": ["窗外有棗林，雛雀習飛其下。貓蔽身林間，突噬雀母。其雛四五，噪而逐貓，每進益怒。貓奮攫之，不勝，反奔入室。雀母死，其雛繞室啁啾，飛入室者三。越數日，猶望室而噪也。", "哀哉！貓一搏而奪四五雛之母，人雖不及救之，未有不惻慨於中者。而貓且眈眈然，唯恐不盡其類焉。烏虖，何其性之獨忍於人哉？", "物與物相殘，人且惡之，乃有憑權位，張爪牙，殘民以自肥者，何也？"], "quote": ["窗外有棗林，雛雀習飛其下。貓蔽身林間，突噬雀母。其雛四五，噪而逐貓，每進益怒。貓奮攫之，不勝，反奔入室。雀母死，其雛繞室啁啾，飛入室者三。越數日，猶望室而噪也。", "哀哉！貓一搏而奪四五雛之母，人雖不及救之，未有不惻慨於中者。而貓且眈眈然，唯恐不盡其類焉。烏虖，何其性之獨忍於人哉？", "物與物相殘，人且惡之，乃有憑權位，張爪牙，殘民以自肥者，何也？"], "intro": "本文是作者《雜記》四則中的一則，本無標題，後人單選這一篇出來，因即冠以今題。《貓捕雀》這一標題，照字面很容易解釋，不過這是一篇寓言的故事，作者是藉此來譏刺壓迫人民的特權階級。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%B2%93%E6%8D%95%E9%9B%80"}, {"title": "觀巴黎油畫院記", "author": "薛福成", "period": "清", "form": "文", "theme": "春水花鳥", "mood": "autumn_sunset", "lines": ["光緒十六年春閏二月甲子，余遊巴黎蠟人館，見所製蠟人，悉仿生人︰形體、態度、髮膚、顏色、長短、豐瘠，無不畢肖。自王公卿相，以至工藝雜流，凡有名者，往往留像於館。或立、或臥、或坐、或俯、或哭、或笑、或飲、或博，驟視之，無不驚為生人者。余亟歎其技術之奇妙。", "通譯者稱︰「西人尤善油畫，允為絕技，盍馳往油畫院一觀普法交戰圖乎？」余曰︰「諾。」", "其院為一大圜室，以巨幅懸之四壁，由屋頂放光入室。人在室中，極目四望，則見城堡、岡巒、溪澗、樹木，森然布列。兩軍人馬雜遝︰馳者、伏者、奔者、追者、開槍者、然礮者、搴大旗者、挽礮車者，絡繹相屬。", "每一巨彈墮地，則火光迸裂，烟焰迷漫。其被轟擊者，則斷壁危樓，或黔其廬，或赭其垣；而軍士之斷臂、折足、血流殷地、偃仰僵仆者，令人目不忍覩。仰視天，則明月斜挂，雲霞掩映；俯視地，則綠草如茵，川原無際。幾疑身外即戰場，而忘其在一室中者。迨以手捫之，始知其為壁也，畫也，皆幻也。", "余問︰「法人好勝，何以自繪敗狀，令人喪氣若此？」通譯者曰︰「所以昭炯戒，激眾憤，圖報復也。」則其用意深矣！夫普法之戰，於今雖為陳跡，而其事信而有徵。然則此畫果真邪？幻邪？幻者而同於真邪？真者而託於幻邪？斯二者，蓋皆有之。"], "quote": ["光緒十六年春閏二月甲子，余遊巴黎蠟人館，見所製蠟人，悉仿生人︰形體、態度、髮膚、顏色、長短、豐瘠，無不畢肖。自王公卿相，以至工藝雜流，凡有名者，往往留像於館。或立、或臥、或坐、或俯、或哭、或笑、或飲、或博，驟視之，無不驚為生人者。余亟歎其技術之奇妙。", "通譯者稱︰「西人尤善油畫，允為絕技，盍馳往油畫院一觀普法交戰圖乎？」余曰︰「諾。」", "其院為一大圜室，以巨幅懸之四壁，由屋頂放光入室。人在室中，極目四望，則見城堡、岡巒、溪澗、樹木，森然布列。兩軍人馬雜遝︰馳者、伏者、奔者、追者、開槍者、然礮者、搴大旗者、挽礮車者，絡繹相屬。", "每一巨彈墮地，則火光迸裂，烟焰迷漫。其被轟擊者，則斷壁危樓，或黔其廬，或赭其垣；而軍士之斷臂、折足、血流殷地、偃仰僵仆者，令人目不忍覩。仰視天，則明月斜挂，雲霞掩映；俯視地，則綠草如茵，川原無際。幾疑身外即戰場，而忘其在一室中者。迨以手捫之，始知其為壁也，畫也，皆幻也。"], "intro": "巴黎（Paris），是法國的首都，在那裏有全世界最大的博物院，名叫魯佛爾博物院（Musée du Louvre），也譯為羅浮博物館，其中有一油畫院，為展覽油畫的地方。油畫，是用油和顏料融化，繪在畫布或木板上的，為西洋畫的一種。本文乃作者出使", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A7%80%E5%B7%B4%E9%BB%8E%E6%B2%B9%E7%95%AB%E9%99%A2%E8%A8%98"}, {"title": "弈喻", "author": "錢大昕", "period": "清", "form": "文", "theme": "詠史哲思", "mood": "ethereal", "lines": ["予觀弈於友人所，一客數敗，嗤其失算，輒欲易置之，以為不逮己也。頃之，客請與予對局，予頗易之。甫下數子，客已得先手；局將半，予思益苦，而客之智尚有餘。竟局數之，客勝予十三子。予赧甚，不能出一言。後有招予觀弈者，終日默坐而已。", "今之學者，讀古人書，多訾古人之失；與今人居，亦樂稱人失。人固不能無失，然試易地以處，平心而度之，吾果無一失乎？吾能知人之失，而不能見吾之失，吾能指人之小失，而不能見吾之大失，吾求吾失且不暇，何暇論人哉？", "弈之優劣，有定也，一着之失，人皆見之，雖護前者，不能諱也、理之所在，各是其所是，各非其所非。世無孔子，誰能定是非之真？然則人之失者，未必非得也；吾之無失者，未必非大失也。而彼此相嗤，無有已時，曾觀弈者之不若已！"], "quote": ["予觀弈於友人所，一客數敗，嗤其失算，輒欲易置之，以為不逮己也。頃之，客請與予對局，予頗易之。甫下數子，客已得先手；局將半，予思益苦，而客之智尚有餘。竟局數之，客勝予十三子。予赧甚，不能出一言。後有招予觀弈者，終日默坐而已。", "今之學者，讀古人書，多訾古人之失；與今人居，亦樂稱人失。人固不能無失，然試易地以處，平心而度之，吾果無一失乎？吾能知人之失，而不能見吾之失，吾能指人之小失，而不能見吾之大失，吾求吾失且不暇，何暇論人哉？", "弈之優劣，有定也，一着之失，人皆見之，雖護前者，不能諱也、理之所在，各是其所是，各非其所非。世無孔子，誰能定是非之真？然則人之失者，未必非得也；吾之無失者，未必非大失也。而彼此相嗤，無有已時，曾觀弈者之不若已！"], "intro": "弈（粤：[逆jik９]；普：[yì]），就是圍棋。據《博物志》說，圍棋是帝堯發明的，他的兒子丹朱下圍棋下得很好。至於為甚麼叫做圍棋呢，因為這種棋是完全用棋子包圍着對方的棋子，如果被四面包圍住了，那就是死子。結局時數數棋子，誰的子兒多誰贏。圍", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%BC%88%E5%96%BB"}, {"title": "要做則做", "author": "錢泳", "period": "清", "form": "文", "theme": "田園幽居", "mood": "autumn_sunset", "lines": ["後生家每臨事，輒曰︰「吾不會做。」此大謬也。凡事做則會，不做安能會耶？又，做一事，輒曰︰「且待明日。」此亦大謬也。凡事要做則做，若一味因循，大誤終身。", "家鶴灘先生有《明日歌》最妙，附記於此︰「明日復明日，明日何其多。我生待明日，萬事成蹉跎。世人苦被明日累，春去秋來老將至。朝看水東流，暮看日西墜。百年明日能幾何？請君聽我《明日歌》。」"], "quote": ["後生家每臨事，輒曰︰「吾不會做。」此大謬也。凡事做則會，不做安能會耶？又，做一事，輒曰︰「且待明日。」此亦大謬也。凡事要做則做，若一味因循，大誤終身。", "家鶴灘先生有《明日歌》最妙，附記於此︰「明日復明日，明日何其多。我生待明日，萬事成蹉跎。世人苦被明日累，春去秋來老將至。朝看水東流，暮看日西墜。百年明日能幾何？請君聽我《明日歌》。」"], "intro": "本文選自《履園叢話》。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E8%A6%81%E5%81%9A%E5%89%87%E5%81%9A"}, {"title": "大鐵椎傳", "author": "魏禧", "period": "清", "form": "文", "theme": "邊塞豪放", "mood": "vast_river", "lines": ["大鐵椎，不知何許人；北平陳子燦省兄河南，與遇宋將軍家。宋，懷慶清華鎮人，工技擊，七省好事者皆來學；人以其雄健，呼宋將軍云。宋弟子高信之，亦懷慶人，多力，善射；長子燦七歲，少同學，故嘗與過宋將軍。", "時座上有健啖客，貌甚寢。右脅夾大鐵椎，重四五十斤，飲食、拱揖不暫去；柄鐵摺疊環複，如鎖上練，引之長丈許。與人罕言語；語類楚聲。問其鄉及姓字，皆不答。", "既同寢；夜半，客曰︰「吾去矣！」言訖，不見。子燦見窗戶皆閉，驚問信之。信之曰︰「客初至時，不冠，不襪，以藍布巾裹頭，足纏白布。大鐵椎外，一物無所持，而腰多白金。吾與將軍，俱不敢問也。」子燦寐而醒，客則鼾睡炕上矣。", "一日，辭宋將軍曰︰「吾始聞汝名，以為豪，然皆不足用；吾去矣！」將軍強留之，乃曰︰「吾嘗奪取諸響馬物，不順者，輒擊殺之；眾魁請長其羣，吾又不許；是以讎我。久居此，禍必及汝。今夜半，方期我決鬬某所。」", "宋將軍欣然曰︰「吾騎馬挾矢以助戰。」客曰︰「止！賊能且眾，吾欲護汝，則不快吾意。」宋將軍故自負，且欲觀客所為，力請客。客不得已，與偕行。", "將至鬬處，送將軍登空堡上；曰︰「但觀之，慎勿聲，令賊知汝也！」時雞鳴月落，星光照曠野，百步見人。客馳下，吹觱篥數聲。頃之，二十餘騎四面集，步行負弓矢從者百餘人。一賊提刀縱馬奔客，曰︰「奈何殺吾兄！」", "言未畢，客呼曰:「椎！」賊應聲落馬，馬首盡裂。眾賊環而進；客從容揮椎，人馬四面仆地下，殺三十餘人。宋將軍屏息觀之，股栗欲墮。忽聞客大呼曰︰「吾去矣！」地塵且起，黑煙滾滾東向馳，去。後遂不復至。", "魏禧論曰︰子房得力士，椎秦皇帝博浪沙中，大鐵椎其人歟！天生異人，必有所用之。予讀陳同甫《中興遺傳》，豪俊、俠烈、魁奇之士，泯泯然不見功名於世者，又何多也！", "豈天之生才，不必為人用歟？抑用之自有時歟？子燦遇大鐵椎，為壬寅歲，當年三十；然則大鐵椎今四十耳！子燦又嘗見其寫市物帖子，甚工楷書也。"], "quote": ["大鐵椎，不知何許人；北平陳子燦省兄河南，與遇宋將軍家。宋，懷慶清華鎮人，工技擊，七省好事者皆來學；人以其雄健，呼宋將軍云。宋弟子高信之，亦懷慶人，多力，善射；長子燦七歲，少同學，故嘗與過宋將軍。", "時座上有健啖客，貌甚寢。右脅夾大鐵椎，重四五十斤，飲食、拱揖不暫去；柄鐵摺疊環複，如鎖上練，引之長丈許。與人罕言語；語類楚聲。問其鄉及姓字，皆不答。", "既同寢；夜半，客曰︰「吾去矣！」言訖，不見。子燦見窗戶皆閉，驚問信之。信之曰︰「客初至時，不冠，不襪，以藍布巾裹頭，足纏白布。大鐵椎外，一物無所持，而腰多白金。吾與將軍，俱不敢問也。」子燦寐而醒，客則鼾睡炕上矣。", "一日，辭宋將軍曰︰「吾始聞汝名，以為豪，然皆不足用；吾去矣！」將軍強留之，乃曰︰「吾嘗奪取諸響馬物，不順者，輒擊殺之；眾魁請長其羣，吾又不許；是以讎我。久居此，禍必及汝。今夜半，方期我決鬬某所。」"], "intro": "大鐵椎，舊時一種武器的名字。本文中的主人公不肯說出自己名字，因善用大鐵椎，故以代其名。 本文屬人物傳記，為敍述體裁。", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%A4%A7%E9%90%B5%E6%A4%8E%E5%82%B3"}, {"title": "廉恥", "author": "顧炎武", "period": "清", "form": "文", "theme": "詠史哲思", "mood": "snow_winter", "lines": ["《五代史‧馮道傳》論曰︰「禮義廉恥，國之四維；四維不張，國乃滅亡。善乎管生之能言也。禮義，治人之大法，廉恥，立人之大節。蓋不廉則無所不取，不恥則無所不為，人而如此，則禍敗亂亡亦無所不至。況為大臣，而無所不取，無所不為，則天下其有不亂，國家其有不亡者乎！」", "然而四者之中，恥尤為要。故夫子之論士曰︰「行己有恥。」孟子曰︰「人不可以無恥，無恥之恥，無恥矣！」又曰︰「恥之於人大矣！為機變之巧者，無所用恥焉！」所以然者，人之不廉，而至於悖禮犯義，其原皆生於無恥也。故士大夫之無恥，是謂國恥。", "吾觀三代以下，世衰道微，棄禮義，捐廉恥，非一朝一夕之故。然而松柏後彫於歲寒，雞鳴不已於風雨，彼昏之日，固未嘗無獨醒之人也。", "頃讀《顏氏家訓》，有云︰「齊朝一士夫，嘗謂吾曰︰『我有一兒，年已十七，頗曉書疏，教其鮮卑語及彈琵琶，稍欲通解，以此伏事公卿，無不寵愛。』吾時俯而不答。異哉此人之教子也！若由此業自致卿相，亦不願汝曹為之！」", "嗟乎！之推不得已而仕於亂世，猶為此言，尚有《小宛》詩人之意，彼閹然媚於世者，能無媿哉！"], "quote": ["《五代史‧馮道傳》論曰︰「禮義廉恥，國之四維；四維不張，國乃滅亡。善乎管生之能言也。禮義，治人之大法，廉恥，立人之大節。蓋不廉則無所不取，不恥則無所不為，人而如此，則禍敗亂亡亦無所不至。況為大臣，而無所不取，無所不為，則天下其有不亂，國家其有不亡者乎！」", "然而四者之中，恥尤為要。故夫子之論士曰︰「行己有恥。」孟子曰︰「人不可以無恥，無恥之恥，無恥矣！」又曰︰「恥之於人大矣！為機變之巧者，無所用恥焉！」所以然者，人之不廉，而至於悖禮犯義，其原皆生於無恥也。故士大夫之無恥，是謂國恥。", "吾觀三代以下，世衰道微，棄禮義，捐廉恥，非一朝一夕之故。然而松柏後彫於歲寒，雞鳴不已於風雨，彼昏之日，固未嘗無獨醒之人也。", "頃讀《顏氏家訓》，有云︰「齊朝一士夫，嘗謂吾曰︰『我有一兒，年已十七，頗曉書疏，教其鮮卑語及彈琵琶，稍欲通解，以此伏事公卿，無不寵愛。』吾時俯而不答。異哉此人之教子也！若由此業自致卿相，亦不願汝曹為之！」"], "intro": "本文選自《日知錄》卷十七《廉恥》條中的一段。此書是顧炎武的一部筆記體著作，共三十二卷，對政治、經濟、經學、文學、風俗、文字、歷史、天文、地理等具體問題有精要的論述和考辨。他對此書十分重視，認為︰「平生之志與業皆在其中。」本文主張人須有廉恥之", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%BB%89%E6%81%A5"}, {"title": "己亥雜詩（其一百二十五）", "author": "龔自珍", "period": "清", "form": "詩", "theme": "江河湖海", "mood": "autumn_sunset", "lines": ["九州生氣恃風雷，萬馬齊喑究可哀。", "我勸天公重抖擻，不拘一格降人才。", "（過鎮江，見賽玉皇及風神雷神者，禱祠萬數，道士乞撰青詞。）"], "quote": ["九州生氣恃風雷，萬馬齊喑究可哀。", "我勸天公重抖擻，不拘一格降人才。", "（過鎮江，見賽玉皇及風神雷神者，禱祠萬數，道士乞撰青詞。）"], "intro": "己亥，指清宣宗道光十九年（一八三九）。這年夏天，龔自珍辭官南歸，秋天又北上迎取眷屬。在南北「往返九千里」的旅途上，陸續寫成七言絕句三百一十五首，總題《己亥雜詩》。這一組大型自敘詩，內容或直抒胸臆，或回憶往事、或敘述見聞、或友朋贈答，其中很多", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B7%B1%E4%BA%A5%E9%9B%9C%E8%A9%A9%EF%BC%88%E5%85%B6%E4%B8%80%E7%99%BE%E4%BA%8C%E5%8D%81%E4%BA%94%EF%BC%89"}, {"title": "己亥雜詩（其五）", "author": "龔自珍", "period": "清", "form": "詩", "theme": "春水花鳥", "mood": "autumn_sunset", "lines": ["浩蕩離愁白日斜，吟鞭東指即天涯。", "落紅不是無情物，化作春泥更護花。"], "quote": ["浩蕩離愁白日斜，吟鞭東指即天涯。", "落紅不是無情物，化作春泥更護花。"], "intro": "己亥，指清宣宗道光十九年（一八三九）。這年夏天，龔自珍辭官南歸，秋天又北上迎取眷屬。在南北「往返九千里」的旅途上，陸續寫成七言絕句三百一十五首，總題《己亥雜詩》。這一組大型自敘詩，內容或直抒胸臆，或回憶往事、或敘述見聞、或友朋贈答，其中很多", "url": "https://www.classicalchineseliterature.org/article.php?article=%E5%B7%B1%E4%BA%A5%E9%9B%9C%E8%A9%A9%EF%BC%88%E5%85%B6%E4%BA%94%EF%BC%89"}, {"title": "病梅館記", "author": "龔自珍", "period": "清", "form": "文", "theme": "田園幽居", "mood": "vast_river", "lines": ["江寧之龍蟠，蘇州之鄧尉，杭州之西谿，皆產梅。或曰︰梅以曲為美，直則無姿；以欹為美，正則無景；梅以疏為美，密則無態。固也。此文人畫士，心知其意，未可明詔大號，以繩天下之梅也；又不可以使天下之民，斫直、刪密、鋤正、以殀梅、病梅為業以求錢也。梅之欹、之疏、之曲，又非蠢蠢求錢之民，能以其智力為也。有以文人畫士孤癖之隱，明告鬻梅者，斫其正，養其旁條，刪其密，夭其稚枝，鋤其直，遏其生氣，以求重價，而江浙之梅皆病。文人畫士之禍之烈至此哉！", "予購三百盆，皆病者，無一完者。既泣之三日，乃誓療之、縱之、順之，毀其盆，悉埋於地，解其棕縛，以五年為期，必復之、全之。予本非文人畫士，甘受詬厲，闢病梅之館以貯之。嗚呼！安得使予多暇日，又多閒田，以廣貯江寧、杭州、蘇州之病梅，窮予生之光陰以療梅也哉！"], "quote": ["江寧之龍蟠，蘇州之鄧尉，杭州之西谿，皆產梅。或曰︰梅以曲為美，直則無姿；以欹為美，正則無景；梅以疏為美，密則無態。固也。此文人畫士，心知其意，未可明詔大號，以繩天下之梅也；又不可以使天下之民，斫直、刪密、鋤正、以殀梅、病梅為業以求錢也。梅之欹、之疏、之曲，又非蠢蠢求錢之民，能以其智力為也。有以文人畫士孤癖之隱，明告鬻梅者，斫其正，養其旁條，刪其密，夭其稚枝，鋤其直，遏其生氣，以求重價，而江浙之梅皆病。文人畫士之禍之烈至此哉！", "予購三百盆，皆病者，無一完者。既泣之三日，乃誓療之、縱之、順之，毀其盆，悉埋於地，解其棕縛，以五年為期，必復之、全之。予本非文人畫士，甘受詬厲，闢病梅之館以貯之。嗚呼！安得使予多暇日，又多閒田，以廣貯江寧、杭州、蘇州之病梅，窮予生之光陰以療梅也哉！"], "intro": "龔自珍生於乾隆末年，經歷了乾隆、嘉慶、道光三朝，正是中國由盛轉衰的時期。他飽讀詩書，但直到三十八歲才得中進士，在朝廷做一些閒散官職。他看不慣官場種種腐敗現象，又受到保守勢力的排擠，終於在任官十年後辭官回鄉，在書院任教。《病梅館記》就是他寫於", "url": "https://www.classicalchineseliterature.org/article.php?article=%E7%97%85%E6%A2%85%E9%A4%A8%E8%A8%98"}];
